  HEADER_LENGTH as INTERFACE_COMPOSITE_HEADER_LENGTH,
  INTERFACE_COMPOSITE_V0,
  InterfaceCompositeError,
  MAX_LIST_LENGTH,
  MAX_VALUE_DEPTH,
  compositeEnvelopeOf,
  compositePayloadOf,
  envelopeFingerprint,
  packCompositeValue,
  unpackCompositeValue,
