import {resolveDeclaredType} from './type-grammar.js';
import {
  assertFieldMappingCovers,
  assertProjectedIndexedFieldType,
  normalizeProjectionFields,
  projectObjectSlots,
} from './image-projection-binding.js';

// A sibling of image-projection-binding/v1 that also returns the object's optimistic-concurrency
// token, closing the read/modify/write loop. Ordinary projection stays frozen and
// version-free: only interfaces that actually need a token pay for one.
//
//   read-versioned-item(id) -> {version-token, value}
//
// The token comes from the same object read that produced the value. Fetching the value and
// then separately fetching a version could return a pair that never described one actual object
// state, which would make the token worse than useless — it would be confidently wrong.
const IMAGE_VERSIONED_PROJECTION_BINDING_V1 = 'image-versioned-projection-binding/v1';
const VERSION_TOKEN_FIELD = 'version-token';
const VALUE_FIELD = 'value';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function parseVersionedProjectionBindingArtifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact'
    || artifact.representation !== IMAGE_VERSIONED_PROJECTION_BINDING_V1) {
    throw new TypeError(`artifact must be ${IMAGE_VERSIONED_PROJECTION_BINDING_V1}`);
  }
  if (artifact.content?.kind !== 'text') {
    throw new TypeError('versioned projection binding content must be a text Value');
  }
  assertBindingDependencies(artifact, [CALLABLE_INTERFACE_DEPENDENCY_ROLE], IMAGE_VERSIONED_PROJECTION_BINDING_V1);
  let decoded;
  try {
    decoded = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError('versioned projection binding content must be valid JSON', {cause: error});
  }
  const expected = ['abi', 'fields'];
  const actual = Object.keys(decoded).sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`${IMAGE_VERSIONED_PROJECTION_BINDING_V1} descriptor must contain exactly ${expected.join(', ')}`);
  }
  if (decoded.abi !== IMAGE_VERSIONED_PROJECTION_BINDING_V1) {
    throw new TypeError(`unsupported versioned projection binding ABI: ${decoded.abi}`);
  }
  return Object.freeze({
    fields: normalizeProjectionFields(decoded.fields, IMAGE_VERSIONED_PROJECTION_BINDING_V1),
  });
}

// read-versioned-item(id: string) -> record { version-token: string, value: <leaf record> }
function assertVersionedProjectionInterface(descriptor, fields = []) {
  const {parameters, result, types = {}} = descriptor;
  if (parameters.length !== 1 || parameters[0] !== 'string') {
    throw new TypeError(
      `${IMAGE_VERSIONED_PROJECTION_BINDING_V1} requires exactly one string parameter naming the object id`,
    );
  }
  const outer = typeof result === 'string' ? resolveDeclaredType(result, types) : null;
  if (!outer || outer.kind !== 'record') {
    throw new TypeError(`${IMAGE_VERSIONED_PROJECTION_BINDING_V1} result must be a declared record type`);
  }
  const names = outer.fields.map(({name}) => name);
  if (names.length !== 2 || names[0] !== VERSION_TOKEN_FIELD || names[1] !== VALUE_FIELD) {
    throw new TypeError(
      `${IMAGE_VERSIONED_PROJECTION_BINDING_V1} result must declare exactly ${VERSION_TOKEN_FIELD} then ${VALUE_FIELD}`,
    );
  }
  const [tokenField, valueField] = outer.fields;
  if (tokenField.type !== 'string') {
    throw new TypeError(`${IMAGE_VERSIONED_PROJECTION_BINDING_V1} ${VERSION_TOKEN_FIELD} must be string; a token is opaque text`);
  }
  const inner = typeof valueField.type === 'string' ? resolveDeclaredType(valueField.type, types) : null;
  if (!inner || inner.kind !== 'record') {
    throw new TypeError(`${IMAGE_VERSIONED_PROJECTION_BINDING_V1} ${VALUE_FIELD} must be a declared record type`);
  }
  const indexedFieldNames = new Set(fields.filter((f) => f.indexed === true).map((f) => f.name));
  for (const field of inner.fields) {
    if (indexedFieldNames.has(field.name)) {
      assertProjectedIndexedFieldType(
        field,
        types,
        `${IMAGE_VERSIONED_PROJECTION_BINDING_V1} indexed field ${field.name}`,
      );
      continue;
    }
    if (!CALLABLE_TYPES.includes(field.type)) {
      throw new TypeError(
        `${IMAGE_VERSIONED_PROJECTION_BINDING_V1} field ${field.name} must be a leaf type; v1 does not project nested values`,
      );
    }
  }
  return {outer, inner};
}

async function installImageVersionedProjectionBinding({
  images,
  callableInterface,
  fields,
  imageId = null,
  bindingId = randomUUID(),
  blockId = randomUUID(),
  bindingMetadata = {},
  blockMetadata = {},
} = {}) {
  const imageService = assertImages(images);
  const interfaceRef = normalizeObjectRef(callableInterface, 'versioned projection binding interface');
  const interfaceArtifact = await imageService.getCodeArtifact(interfaceRef.imageId, interfaceRef.objectId);
  if (!interfaceArtifact) {
    throw new TypeError(`callable interface not found: ${interfaceRef.imageId}/${interfaceRef.objectId}`);
  }
  const targetImageId = imageId ?? interfaceRef.imageId;
  const normalizedFields = normalizeProjectionFields(fields, IMAGE_VERSIONED_PROJECTION_BINDING_V1);

  const {descriptor} = await resolveCallableInterface(
    imageService,
    {dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}]},
    IMAGE_VERSIONED_PROJECTION_BINDING_V1,
  );
  const {inner} = assertVersionedProjectionInterface(descriptor, normalizedFields);
  assertFieldMappingCovers(inner, normalizedFields, IMAGE_VERSIONED_PROJECTION_BINDING_V1);

  const bindingArtifact = await imageService.putCodeArtifact(targetImageId, {
    id: bindingId,
    representation: IMAGE_VERSIONED_PROJECTION_BINDING_V1,
    content: textValue(JSON.stringify({
      abi: IMAGE_VERSIONED_PROJECTION_BINDING_V1,
      fields: normalizedFields.map((entry) => (
        entry.indexed === true ? {name: entry.name, indexed: true} : {name: entry.name, slot: entry.slot}
      )),
    })),
    dependencies: [{role: CALLABLE_INTERFACE_DEPENDENCY_ROLE, artifact: interfaceRef}],
    metadata: bindingMetadata,
  });
  const block = await imageService.putBlock(targetImageId, {
    id: blockId,
    code: objectRef(targetImageId, bindingArtifact.id),
    environment: null,
    metadata: blockMetadata,
  });
  return Object.freeze({bindingArtifact, block, interfaceRef});
}

function createImageVersionedProjectionBindingV1Executor() {
  return Object.freeze({
    async execute({activation, code}, {images, require}) {
      if (!code || code.representation !== IMAGE_VERSIONED_PROJECTION_BINDING_V1) {
        throw new TypeError(`versioned projection executor requires ${IMAGE_VERSIONED_PROJECTION_BINDING_V1}`);
      }
      assertBlockApplicationReceiver(activation, IMAGE_VERSIONED_PROJECTION_BINDING_V1);
      if (activation.environment !== null) {
        throw new TypeError(`${IMAGE_VERSIONED_PROJECTION_BINDING_V1} does not accept a lexical environment`);
      }
      const binding = parseVersionedProjectionBindingArtifact(code);
      const {descriptor} = await resolveCallableInterface(images, code, IMAGE_VERSIONED_PROJECTION_BINDING_V1);
      const {inner} = assertVersionedProjectionInterface(descriptor, binding.fields);
      const mapped = assertFieldMappingCovers(inner, binding.fields, IMAGE_VERSIONED_PROJECTION_BINDING_V1);

      const args = assertCallableInterfaceArguments(descriptor, activation.arguments, descriptor.function);
      const objectId = requiredText(args[0].value, 'projected object id');
      // The image comes from the binding, never the caller.
      const imageId = code.imageId;

      require({operation: OBJECT_READ_OPERATION, resource: objectResource(imageId, objectId)});

      // Read once. Both halves of the returned pair come from this single record, so the token
      // always describes the state the value was taken from.
      const object = await images.getObject(imageId, objectId);
      if (!object) throw new TypeError(`projected object not found: ${imageId}/${objectId}`);

      const value = projectObjectSlots({
        object,
        record: inner,
        mapped,
        types: descriptor.types ?? {},
        imageId,
        objectId,
      });
      // The same object-scoped codec the mutation lane accepts: no second encoding, and no
      // projection-specific token identity.
      const token = objectVersionToken(imageId, objectId, object._version);

      return packCompositeValue(
        {[VERSION_TOKEN_FIELD]: token, [VALUE_FIELD]: value},
        descriptor.result,
        descriptor.types ?? {},
        `${descriptor.function} result`,
      );
    },
  });
}

export {
  IMAGE_VERSIONED_PROJECTION_BINDING_V1,
  assertVersionedProjectionInterface,
  createImageVersionedProjectionBindingV1Executor,
  installImageVersionedProjectionBinding,
  parseVersionedProjectionBindingArtifact,
};

import {base64Decode} from '../support/portable-bytes.js';
import {uuid as randomUUID} from '../support/default-crypto.js';
import {VALUE_KIND, booleanValue, bytesValue, canonicalizeValue, float64ToNumber, float64Value, integerValue, textValue} from '../value/index.js';

// A callable interface describes a callable shape and nothing else. It deliberately
// carries no reference to a WASM module, a foreign runtime, a provider or a capability:
// those belong to an implementation binding, which depends on this artifact. One
// interface artifact is meant to be shared by every lane that implements it.
const CALLABLE_INTERFACE_V1 = 'callable-interface/v1';

// The type language is WIT's, spelled the way WIT spells it, so the descriptor can be
// projected to a real WIT interface without a translation table. It is kept tiny on
// purpose: no lists (beyond list<u8> for bytes), records, tuples, options, results,
// refs or multiple results. Those need a separate decision about how structured
// interface values relate to the canonical Value model.
const CALLABLE_TYPES = Object.freeze(['bool', 's32', 's64', 'f32', 'f64', 'string', 'list<u8>']);

const S32_MIN = -(2n ** 31n);
const S32_MAX = 2n ** 31n - 1n;
const S64_MIN = -(2n ** 63n);
const S64_MAX = 2n ** 63n - 1n;

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function exactKeys(value, keys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`${label} must contain exactly ${expected.join(', ')}`);
  }
  return value;
}

function normalizeCallableType(value, label) {
  const type = requiredText(value, label);
  if (!CALLABLE_TYPES.includes(type)) throw new TypeError(`${label} must be one of ${CALLABLE_TYPES.join(', ')}`);
  return type;
}

function normalizeCallableInterfaceDescriptor(input) {
  exactKeys(input, ['abi', 'function', 'parameters', 'result'], 'callable interface descriptor');
  if (input.abi !== CALLABLE_INTERFACE_V1) {
    throw new TypeError(`unsupported callable interface ABI: ${input.abi}`);
  }
  if (!Array.isArray(input.parameters)) throw new TypeError('callable interface parameters must be an array');
  return Object.freeze({
    abi: CALLABLE_INTERFACE_V1,
    function: requiredText(input.function, 'callable interface function'),
    parameters: Object.freeze(input.parameters.map((type, index) => normalizeCallableType(type, `callable interface parameter ${index}`))),
    result: normalizeCallableType(input.result, 'callable interface result'),
  });
}

function createCallableInterfaceContent({functionName, parameters = [], result} = {}) {
  return textValue(JSON.stringify(normalizeCallableInterfaceDescriptor({
    abi: CALLABLE_INTERFACE_V1,
    function: functionName,
    parameters,
    result,
  })));
}

function parseCallableInterfaceArtifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== CALLABLE_INTERFACE_V1) {
    throw new TypeError(`artifact must be ${CALLABLE_INTERFACE_V1}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError('callable interface content must be a text Value');
  // An interface that depended on anything would no longer be implementation-independent.
  if ((artifact.dependencies ?? []).length !== 0) {
    throw new TypeError('callable interface must not declare dependencies; implementations bind to it, not the reverse');
  }
  let decoded;
  try {
    decoded = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError('callable interface content must be valid JSON', {cause: error});
  }
  return normalizeCallableInterfaceDescriptor(decoded);
}

// Type checking against the shared interface, used by every lane. Lowering a Value into
// a lane's own representation is the binding's job; agreeing on what is legal is not.
function assertCallableValueType(value, type, label) {
  const normalized = canonicalizeValue(value);
  switch (type) {
    case 'bool':
      if (normalized.kind !== VALUE_KIND.BOOLEAN) throw new TypeError(`${label} must be a boolean Value for bool`);
      return normalized;
    case 's32':
    case 's64': {
      if (normalized.kind !== VALUE_KIND.INTEGER) throw new TypeError(`${label} must be an integer Value for ${type}`);
      const n = BigInt(normalized.value);
      const [min, max] = type === 's32' ? [S32_MIN, S32_MAX] : [S64_MIN, S64_MAX];
      if (n < min || n > max) throw new RangeError(`${label} is outside ${type} range`);
      return normalized;
    }
    case 'f64':
      if (normalized.kind !== VALUE_KIND.FLOAT64) throw new TypeError(`${label} must be a float64 Value for f64`);
      return normalized;
    case 'f32': {
      if (normalized.kind !== VALUE_KIND.FLOAT64) throw new TypeError(`${label} must be a float64 Value for f32`);
      // f32 at this boundary means "a float64 restricted to f32 precision". Rounding here,
      // in the shared interface, is what makes the lanes agree by construction instead of
      // by each lane happening to round the same way. A lane that rounds again is a no-op.
      return float64Value(Math.fround(float64ToNumber(normalized)));
    }
    case 'string':
      if (normalized.kind !== VALUE_KIND.TEXT) throw new TypeError(`${label} must be a text Value for string`);
      return normalized;
    case 'list<u8>':
      if (normalized.kind !== VALUE_KIND.BYTES) throw new TypeError(`${label} must be a bytes Value for list<u8>`);
      return normalized;
    default:
      throw new TypeError(`unsupported callable type: ${type}`);
  }
}

// Canonical Value -> the host representation the composite codec and lane adapters expect.
// Shared so every lane converts leaves identically; a second copy is a place for them to drift.
function canonicalToHostLeaf(value, type, label) {
  const normalized = assertCallableValueType(value, type, label);
  switch (type) {
    case 'bool': return normalized.value;
    case 's32': return Number(BigInt(normalized.value));
    case 's64': return BigInt(normalized.value);
    case 'f32': return Math.fround(float64ToNumber(normalized));
    case 'f64': return float64ToNumber(normalized);
    case 'string': return normalized.value;
    case 'list<u8>': return base64Decode(normalized.base64);
    default: throw new TypeError(`${label} has unsupported leaf type ${type}`);
  }
}

// The inverse of canonicalToHostLeaf, kept beside it so the two cannot drift.
function hostLeafToCanonical(value, type, label) {
  switch (type) {
    case 'bool':
      if (typeof value !== 'boolean') throw new TypeError(`${label} must be a boolean`);
      return booleanValue(value);
    case 's32':
    case 's64': {
      if (typeof value !== 'bigint' && !(typeof value === 'number' && Number.isInteger(value))) {
        throw new TypeError(`${label} must be an integer`);
      }
      return assertCallableValueType(integerValue(typeof value === 'bigint' ? value : BigInt(value)), type, label);
    }
    case 'f32':
    case 'f64':
      if (typeof value !== 'number') throw new TypeError(`${label} must be a number`);
      return assertCallableValueType(float64Value(value), type, label);
    case 'string':
      if (typeof value !== 'string') throw new TypeError(`${label} must be a string`);
      return textValue(value);
    case 'list<u8>':
      if (!(value instanceof Uint8Array) && !Array.isArray(value)) throw new TypeError(`${label} must be a byte sequence`);
      return bytesValue(value instanceof Uint8Array ? value : new Uint8Array(value));
    default:
      throw new TypeError(`${label} has unsupported leaf type ${type}`);
  }
}

function assertCallableArguments(descriptor, args, label = 'callable') {
  if (!Array.isArray(args)) throw new TypeError(`${label} arguments must be an array`);
  if (args.length !== descriptor.parameters.length) {
    throw new TypeError(`${label} expected ${descriptor.parameters.length} arguments, got ${args.length}`);
  }
  return descriptor.parameters.map((type, index) => assertCallableValueType(args[index], type, `${label} argument ${index}`));
}

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['getCodeArtifact', 'putCodeArtifact', 'putBlock']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

async function installCallableInterface({
  images,
  imageId,
  functionName,
  parameters = [],
  result,
  interfaceId = randomUUID(),
  metadata = {},
} = {}) {
  const imageService = assertImages(images);
  requiredText(imageId, 'callable interface imageId');
  return await imageService.putCodeArtifact(imageId, {
    id: interfaceId,
    representation: CALLABLE_INTERFACE_V1,
    content: createCallableInterfaceContent({functionName, parameters, result}),
    dependencies: [],
    metadata,
  });
}

export {
  CALLABLE_INTERFACE_V1,
  CALLABLE_TYPES,
  assertCallableArguments,
  assertCallableValueType,
  canonicalToHostLeaf,
  hostLeafToCanonical,
  assertImages,
  createCallableInterfaceContent,
  installCallableInterface,
  normalizeCallableInterfaceDescriptor,
  parseCallableInterfaceArtifact,
};

