import {ensureCodeArtifact, ensureCodeArtifacts} from '../graph/ensure-records.js';
import {uuid as randomUUID} from '../support/default-crypto.js';
import {TupleMap} from '../support/tuple-map.js';
import {normalizeArtifactDependencies} from '../execution/model.js';
import {canonicalizeValue, isObjectRef, objectRef} from '../value/index.js';
import {normalizeMetadata} from '../object/model.js';
import {createDerivationDescriptor} from './derivation-cache.js';
import {CodeCompilerRegistry, normalizeRepresentation} from './compiler-registry.js';
import {COMPILATION_GROUP_KIND} from './group.js';
import {CompilationGroupCompilerRegistry, normalizePolicyId} from './group-compiler-registry.js';

function normalizeObjectRef(value, label) {
  const normalized = canonicalizeValue(value);
  if (!isObjectRef(normalized)) throw new TypeError(`${label} must be an unpinned object ref`);
  return normalized;
}

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['getCodeArtifact', 'putCodeArtifact']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

function requiredKey(value, label) {
  if (typeof value !== 'string' || value.length === 0 || value.includes(':')) {
    throw new TypeError(`${label} must be non-empty text without ':'`);
  }
  return value;
}

// A compiler result is either ONE artifact description {content, dependencies, metadata} — the
// common case — or a RESULT GRAPH {primary, artifacts: [{key, representation, content,
// dependencies, metadata}]} when a compilation's durable form is several records that must become
// visible together (a compiled module = its raw bytes + its semantic descriptor + the edge between
// them). A graph dependency's `artifact` may name a sibling by key; the service resolves it to that
// sibling's ref at persistence time. This is the generic repair of the old one-result-one-artifact
// assumption: no target-specific branch lives here, and the compiler never manufactures artifacts.
function normalizeCompilerResult(result, fallbackLanguageId = null) {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    throw new TypeError('compiler must return an artifact description object');
  }
  const languageId = result.languageId === undefined ? fallbackLanguageId : result.languageId;
  if (result.artifacts === undefined) {
    return Object.freeze({
      languageId,
      content: canonicalizeValue(result.content),
      dependencies: normalizeArtifactDependencies(result.dependencies ?? []),
      metadata: normalizeMetadata(result.metadata ?? {}, 'compiler result metadata'),
    });
  }
  if (!Array.isArray(result.artifacts) || result.artifacts.length === 0) {
    throw new TypeError('compiler result graph must list at least one artifact');
  }
  const keys = new Set();
  const artifacts = result.artifacts.map((entry, index) => {
    const label = `compiler result artifact ${index}`;
    const key = requiredKey(entry?.key, `${label} key`);
    if (keys.has(key)) throw new TypeError(`compiler result graph repeats key ${key}`);
    keys.add(key);
    return Object.freeze({
      key,
      representation: normalizeRepresentation(entry.representation, `${label} representation`),
      content: canonicalizeValue(entry.content),
      dependencies: Object.freeze((entry.dependencies ?? []).map((dependency) => Object.freeze({
        role: dependency?.role,
        artifact: typeof dependency?.artifact === 'string' ? dependency.artifact : canonicalizeValue(dependency?.artifact),
      }))),
      metadata: normalizeMetadata(entry.metadata ?? {}, `${label} metadata`),
    });
  });
  const primary = requiredKey(result.primary, 'compiler result primary key');
  if (!keys.has(primary)) throw new TypeError(`compiler result primary ${primary} is not among its artifacts`);
  for (const artifact of artifacts) {
    for (const dependency of artifact.dependencies) {
      if (typeof dependency.artifact === 'string' && !keys.has(dependency.artifact)) {
        throw new TypeError(`compiler result artifact ${artifact.key} depends on unknown sibling ${dependency.artifact}`);
      }
    }
  }
  return Object.freeze({languageId, primary, artifacts: Object.freeze(artifacts)});
}

// Persist one normalized compiler result at `id` and return the artifact a caller compiles FOR
// (the single artifact, or the graph's primary). Sibling ids derive from the primary id, so the
// whole graph is ensure-exact-or-create at deterministic ids exactly like a single artifact; a
// graph goes through ONE createRecords batch, so its descriptor can never be durably visible
// without its implementation. Caller and cache metadata land on the primary only.
async function persistCompilerResult(images, imageId, {id, target, result, derivedFrom, callerMetadata, cacheMetadata}) {
  if (result.artifacts === undefined) {
    return await ensureCodeArtifact(images, imageId, {
      id,
      languageId: result.languageId,
      representation: target,
      content: result.content,
      dependencies: result.dependencies,
      derivedFrom,
      metadata: {...result.metadata, ...callerMetadata, ...cacheMetadata},
    });
  }
  const idOf = (key) => (key === result.primary ? id : `${id}:${key}`);
  const records = result.artifacts.map((artifact) => {
    const isPrimary = artifact.key === result.primary;
    if (isPrimary && artifact.representation !== target) {
      throw new TypeError(`compiler result primary must be ${target}, got ${artifact.representation}`);
    }
    return {
      id: idOf(artifact.key),
      languageId: result.languageId,
      representation: artifact.representation,
      content: artifact.content,
      dependencies: normalizeArtifactDependencies(artifact.dependencies.map(({role, artifact: target}) => ({
        role,
        artifact: typeof target === 'string' ? objectRef(imageId, idOf(target)) : target,
      }))),
      derivedFrom,
      metadata: isPrimary ? {...artifact.metadata, ...callerMetadata, ...cacheMetadata} : artifact.metadata,
    };
  });
  const stored = await ensureCodeArtifacts(images, imageId, records);
  return stored[result.artifacts.findIndex((artifact) => artifact.key === result.primary)];
}

function commonLanguageId(artifacts) {
  if (artifacts.length === 0) return null;
  const first = artifacts[0].languageId;
  return artifacts.every((artifact) => artifact.languageId === first) ? first : null;
}

class CompilationService {
  #reusableByImage = new Map();

  constructor({
    images,
    compilers = new CodeCompilerRegistry(),
    groupCompilers = new CompilationGroupCompilerRegistry(),
  } = {}) {
    this.images = assertImages(images);
    if (!compilers || typeof compilers.get !== 'function') {
      throw new TypeError('compilers must be a CodeCompilerRegistry-compatible object');
    }
    if (!groupCompilers || typeof groupCompilers.get !== 'function') {
      throw new TypeError('groupCompilers must be a CompilationGroupCompilerRegistry-compatible object');
    }
    this.compilers = compilers;
    this.groupCompilers = groupCompilers;
  }

  #indexReusableArtifact(imageId, artifact) {
    const byKey = this.#reusableByImage.get(imageId);
    if (!byKey) return;
    const compilerIdentity = artifact?.metadata?.compilerIdentity;
    const derivationKey = artifact?.metadata?.derivationKey;
    if (typeof artifact?.representation !== 'string'
      || typeof compilerIdentity !== 'string'
      || typeof derivationKey !== 'string') {
      return;
    }
    const key = [artifact.representation, compilerIdentity, derivationKey];
    if (!byKey.has(key)) byKey.set(key, artifact);
  }

  async findReusableArtifact(imageId, targetRepresentation, descriptor) {
    if (!descriptor) return null;
    if (typeof this.images.listCodeArtifacts !== 'function') {
      throw new TypeError('reusable compilation requires images.listCodeArtifacts');
    }
    let byKey = this.#reusableByImage.get(imageId);
    if (!byKey) {
      byKey = new TupleMap(3);
      this.#reusableByImage.set(imageId, byKey);
      for (const artifact of await this.images.listCodeArtifacts(imageId)) {
        this.#indexReusableArtifact(imageId, artifact);
      }
    }
    return byKey.get([targetRepresentation, descriptor.compilerIdentity, descriptor.derivationKey]) ?? null;
  }

  async compileArtifact(sourceRef, {
    targetRepresentation,
    id = randomUUID(),
    metadata = {},
    options = {},
    reuse = true,
  } = {}) {
    if (typeof reuse !== 'boolean') throw new TypeError('reuse must be a boolean');
    const ref = normalizeObjectRef(sourceRef, 'source code artifact');
    const target = normalizeRepresentation(targetRepresentation, 'target representation');
    const source = await this.images.getCodeArtifact(ref.imageId, ref.objectId);
    if (!source) throw new TypeError(`source code artifact not found: ${ref.imageId}/${ref.objectId}`);

    const compiler = this.compilers.get(source.representation, target);
    const request = Object.freeze({source, targetRepresentation: target, options});
    const context = Object.freeze({images: this.images});
    const callerMetadata = normalizeMetadata(metadata, 'compiled artifact metadata');
    const descriptor = await createDerivationDescriptor(compiler, request, context, callerMetadata);

    if (reuse && descriptor) {
      const existing = await this.findReusableArtifact(ref.imageId, target, descriptor);
      if (existing) return existing;
    }

    const result = normalizeCompilerResult(await compiler.compile(request, context), source.languageId);
    const cacheMetadata = descriptor
      ? {compilerIdentity: descriptor.compilerIdentity, derivationKey: descriptor.derivationKey}
      : {};

    const persisted = await persistCompilerResult(this.images, ref.imageId, {
      id, target, result, callerMetadata, cacheMetadata,
      derivedFrom: [objectRef(ref.imageId, ref.objectId)],
    });
    this.#indexReusableArtifact(ref.imageId, persisted);
    return persisted;
  }

  async compileGroup(group, {
    id = randomUUID(),
    metadata = {},
    reuse = true,
  } = {}) {
    if (typeof reuse !== 'boolean') throw new TypeError('reuse must be a boolean');
    if (!group || typeof group !== 'object' || Array.isArray(group) || group.kind !== COMPILATION_GROUP_KIND) {
      throw new TypeError(`group must be a ${COMPILATION_GROUP_KIND}`);
    }
    const policyId = normalizePolicyId(group.policyId);
    const target = normalizeRepresentation(group.targetRepresentation, 'compilation group target representation');
    if (!Array.isArray(group.members) || group.members.length === 0) {
      throw new TypeError('compilation group members must be a non-empty array');
    }

    const refs = group.members.map((member, index) => normalizeObjectRef(member, `compilation group member ${index}`));
    const imageId = refs[0].imageId;
    if (refs.some((ref) => ref.imageId !== imageId)) {
      throw new TypeError('grouped compilation currently requires all members to belong to one image');
    }
    const members = [];
    for (const ref of refs) {
      const artifact = await this.images.getCodeArtifact(ref.imageId, ref.objectId);
      if (!artifact) throw new TypeError(`compilation group member not found: ${ref.imageId}/${ref.objectId}`);
      members.push(artifact);
    }

    const compiler = this.groupCompilers.get(policyId, target);
    const request = Object.freeze({
      group,
      members: Object.freeze(members),
      targetRepresentation: target,
      options: group.options,
    });
    const context = Object.freeze({images: this.images});
    const callerMetadata = normalizeMetadata(metadata, 'compiled group artifact metadata');
    const descriptor = await createDerivationDescriptor(compiler, request, context, callerMetadata);

    if (reuse && descriptor) {
      const existing = await this.findReusableArtifact(imageId, target, descriptor);
      if (existing) return existing;
    }

    const result = normalizeCompilerResult(await compiler.compile(request, context), commonLanguageId(members));
    const cacheMetadata = descriptor
      ? {compilerIdentity: descriptor.compilerIdentity, derivationKey: descriptor.derivationKey}
      : {};

    const persisted = await persistCompilerResult(this.images, imageId, {
      id, target, result, callerMetadata, cacheMetadata,
      derivedFrom: refs.map((ref) => objectRef(ref.imageId, ref.objectId)),
    });
    this.#indexReusableArtifact(imageId, persisted);
    return persisted;
  }
}

export {CompilationService};

import {TupleMap} from '../support/tuple-map.js';

// Ordered by part, so ordering never depends on a separator either.
function compareTuples(left, right) {
  for (let index = 0; index < left.length; index += 1) {
    const order = left[index].localeCompare(right[index]);
    if (order !== 0) return order;
  }
  return 0;
}

class CodeCompilerRegistrationError extends Error {
  constructor(sourceRepresentation, targetRepresentation) {
    super(`compiler already registered: ${sourceRepresentation} -> ${targetRepresentation}`);
    this.name = 'CodeCompilerRegistrationError';
    this.sourceRepresentation = sourceRepresentation;
    this.targetRepresentation = targetRepresentation;
  }
}

class CodeCompilerNotFoundError extends Error {
  constructor(sourceRepresentation, targetRepresentation) {
    super(`compiler not registered: ${sourceRepresentation} -> ${targetRepresentation}`);
    this.name = 'CodeCompilerNotFoundError';
    this.sourceRepresentation = sourceRepresentation;
    this.targetRepresentation = targetRepresentation;
  }
}

function normalizeRepresentation(value, label = 'representation') {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function assertCompiler(compiler) {
  if (!compiler || typeof compiler !== 'object' || typeof compiler.compile !== 'function') {
    throw new TypeError('compiler must implement compile(request, context)');
  }
  return compiler;
}

class CodeCompilerRegistry {
  constructor(entries = []) {
    // Keyed by the (source, target) tuple rather than by a joined string. Representations are
    // arbitrary non-empty text, so no separator is safe to join on: see src/support/tuple-map.js.
    this.compilers = new TupleMap(2);
    for (const [source, target, compiler] of entries) this.register(source, target, compiler);
  }

  register(sourceRepresentation, targetRepresentation, compiler) {
    const source = normalizeRepresentation(sourceRepresentation, 'source representation');
    const target = normalizeRepresentation(targetRepresentation, 'target representation');
    assertCompiler(compiler);
    if (this.compilers.has([source, target])) throw new CodeCompilerRegistrationError(source, target);
    this.compilers.set([source, target], compiler);
    return compiler;
  }

  get(sourceRepresentation, targetRepresentation) {
    const source = normalizeRepresentation(sourceRepresentation, 'source representation');
    const target = normalizeRepresentation(targetRepresentation, 'target representation');
    const compiler = this.compilers.get([source, target]);
    if (!compiler) throw new CodeCompilerNotFoundError(source, target);
    return compiler;
  }

  has(sourceRepresentation, targetRepresentation) {
    const source = normalizeRepresentation(sourceRepresentation, 'source representation');
    const target = normalizeRepresentation(targetRepresentation, 'target representation');
    return this.compilers.has([source, target]);
  }

  list() {
    return [...this.compilers.keys()].sort(compareTuples);
  }
}

export {
  CodeCompilerNotFoundError,
  compareTuples,
  CodeCompilerRegistrationError,
  CodeCompilerRegistry,
  assertCompiler,
  normalizeRepresentation,
};

import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {bytesToHex, utf8Encode} from '../support/portable-bytes.js';

const DERIVATION_KEY_VERSION = 'lagrange-derivation-key/v0';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function normalizeKeyMaterial(value, path = 'cache key material') {
  if (value === null) return ['null'];
  switch (typeof value) {
    case 'boolean': return ['boolean', value];
    case 'string': return ['string', value];
    case 'number':
      if (!Number.isFinite(value)) throw new TypeError(`${path} numbers must be finite`);
      return ['number', Object.is(value, -0) ? '-0' : String(value)];
    case 'bigint': return ['bigint', value.toString(10)];
    case 'object': {
      if (Array.isArray(value)) {
        return ['array', value.map((entry, index) => normalizeKeyMaterial(entry, `${path}[${index}]`))];
      }
      const prototype = Object.getPrototypeOf(value);
      if (prototype !== Object.prototype && prototype !== null) {
        throw new TypeError(`${path} objects must be plain records`);
      }
      const entries = Object.keys(value).sort().map((key) => [key, normalizeKeyMaterial(value[key], `${path}.${key}`)]);
      return ['object', entries];
    }
    default:
      throw new TypeError(`${path} contains unsupported ${typeof value}`);
  }
}

function compilerCacheContract(compiler) {
  const identity = compiler?.identity;
  const cacheKey = compiler?.cacheKey;
  if (identity === undefined && cacheKey === undefined) return null;
  requiredText(identity, 'compiler identity');
  if (typeof cacheKey !== 'function') throw new TypeError('cacheable compiler must implement cacheKey(request, context)');
  return Object.freeze({identity, cacheKey});
}

async function createDerivationDescriptor(compiler, request, context = {}, artifactMetadata = {}) {
  const contract = compilerCacheContract(compiler);
  if (!contract) return null;
  const material = await contract.cacheKey(request, context);
  const normalized = normalizeKeyMaterial(material);
  const normalizedMetadata = normalizeKeyMaterial(artifactMetadata, 'compiled artifact metadata');
  const payload = JSON.stringify([
    DERIVATION_KEY_VERSION,
    contract.identity,
    request.targetRepresentation,
    normalized,
    normalizedMetadata,
  ]);
  const key = bytesToHex(getDefaultCryptoProvider().sha256(utf8Encode(payload)));
  return Object.freeze({compilerIdentity: contract.identity, derivationKey: key});
}

export {
  DERIVATION_KEY_VERSION,
  compilerCacheContract,
  createDerivationDescriptor,
  normalizeKeyMaterial as normalizeDerivationKeyMaterial,
};

import {TupleMap} from '../support/tuple-map.js';
import {compareTuples} from './compiler-registry.js';

class CompilationGroupCompilerRegistrationError extends Error {
  constructor(policyId, targetRepresentation) {
    super(`group compiler already registered: ${policyId} -> ${targetRepresentation}`);
    this.name = 'CompilationGroupCompilerRegistrationError';
    this.policyId = policyId;
    this.targetRepresentation = targetRepresentation;
  }
}

class CompilationGroupCompilerNotFoundError extends Error {
  constructor(policyId, targetRepresentation) {
    super(`group compiler not registered: ${policyId} -> ${targetRepresentation}`);
    this.name = 'CompilationGroupCompilerNotFoundError';
    this.policyId = policyId;
    this.targetRepresentation = targetRepresentation;
  }
}

function normalizePolicyId(value, label = 'compilation group policyId') {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function assertGroupCompiler(compiler) {
  if (!compiler || typeof compiler !== 'object' || typeof compiler.compile !== 'function') {
    throw new TypeError('group compiler must implement compile(request, context)');
  }
  return compiler;
}

class CompilationGroupCompilerRegistry {
  constructor(entries = []) {
    // Keyed by the (policyId, target) tuple: policy ids and representations are arbitrary
    // non-empty text, so a joined key is not injective.
    this.compilers = new TupleMap(2);
    for (const [policyId, targetRepresentation, compiler] of entries) {
      this.register(policyId, targetRepresentation, compiler);
    }
  }

  register(policyId, targetRepresentation, compiler) {
    const policy = normalizePolicyId(policyId);
    if (typeof targetRepresentation !== 'string' || targetRepresentation.length === 0) {
      throw new TypeError('target representation must be a non-empty string');
    }
    assertGroupCompiler(compiler);
    if (this.compilers.has([policy, targetRepresentation])) {
      throw new CompilationGroupCompilerRegistrationError(policy, targetRepresentation);
    }
    this.compilers.set([policy, targetRepresentation], compiler);
    return compiler;
  }

  get(policyId, targetRepresentation) {
    const policy = normalizePolicyId(policyId);
    if (typeof targetRepresentation !== 'string' || targetRepresentation.length === 0) {
      throw new TypeError('target representation must be a non-empty string');
    }
    const compiler = this.compilers.get([policy, targetRepresentation]);
    if (!compiler) throw new CompilationGroupCompilerNotFoundError(policy, targetRepresentation);
    return compiler;
  }

  has(policyId, targetRepresentation) {
    const policy = normalizePolicyId(policyId);
    if (typeof targetRepresentation !== 'string' || targetRepresentation.length === 0) {
      throw new TypeError('target representation must be a non-empty string');
    }
    return this.compilers.has([policy, targetRepresentation]);
  }

  list() {
    return [...this.compilers.keys()].sort(compareTuples);
  }
}

export {
  CompilationGroupCompilerNotFoundError,
  CompilationGroupCompilerRegistrationError,
  CompilationGroupCompilerRegistry,
  assertGroupCompiler,
  normalizePolicyId,
};

import {TupleSet} from '../support/tuple-map.js';
import {canonicalizeValue, isObjectRef} from '../value/index.js';
import {normalizeDerivationKeyMaterial} from './derivation-cache.js';
import {normalizeRepresentation} from './compiler-registry.js';

const COMPILATION_GROUP_KIND = 'compilation-group';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function normalizeMember(value, index) {
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) throw new TypeError(`compilation group member ${index} must be an unpinned object ref`);
  return ref;
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const entry of Object.values(value)) deepFreeze(entry);
  return Object.freeze(value);
}

function normalizeOptions(options) {
  normalizeDerivationKeyMaterial(options, 'compilation group options');
  return deepFreeze(structuredClone(options));
}

function createCompilationGroup({policyId, targetRepresentation, members, options = {}} = {}) {
  const policy = requiredText(policyId, 'compilation group policyId');
  const target = normalizeRepresentation(targetRepresentation, 'compilation group target representation');
  if (!Array.isArray(members) || members.length === 0) throw new TypeError('compilation group members must be a non-empty array');
  const normalizedMembers = Object.freeze(members.map(normalizeMember));
  const seen = new TupleSet(2);
  for (const member of normalizedMembers) {
    const key = [member.imageId, member.objectId];
    if (seen.has(key)) throw new TypeError(`duplicate compilation group member: ${member.imageId}/${member.objectId}`);
    seen.add(key);
  }
  return Object.freeze({
    kind: COMPILATION_GROUP_KIND,
    policyId: policy,
    targetRepresentation: target,
    members: normalizedMembers,
    options: normalizeOptions(options),
  });
}

