  constructor({
    images,
    executors = new CodeExecutorRegistry(),
    invocations = null,
    authority = null,
    temporaryInitializer = null,
  } = {}) {
    if (temporaryInitializer !== null && typeof temporaryInitializer !== 'function') {
      throw new TypeError('temporaryInitializer must be a function or null');
    }
    this.temporaryInitializer = temporaryInitializer;
    this.images = assertImages(images);
    // The authority *service*, not a context. Per ADR 0037 it is never handed to an executor.
    this.authority = authority;
    if (!executors || typeof executors.get !== 'function') {
      throw new TypeError('executors must be a CodeExecutorRegistry-compatible object');
    }
    this.executors = executors;
    this.invocations = assertInvocations(invocations);
  }

  // The durable record rather than its value, because the three capture dispositions of ADR 0043
  // mean different things and only one of them carries a value at all.
  async lookupBindingRecord(environmentRef, bindingId, images = this.images) {
    if (typeof bindingId !== 'string' || bindingId.length === 0) {
      throw new TypeError('binding id must be a non-empty string');
    }
    let currentRef = environmentRef;
    // Nested by imageId then objectId. Flattening a two-part identity into one string needs a
    // separator that cannot occur inside either part, and object ids are arbitrary non-empty text,
    // so no such separator exists — the same non-injectivity that makes object resources encode
    // each part rather than concatenate them.
    const visited = new Map();
    while (currentRef) {
      const ref = normalizeObjectRef(currentRef, 'lexical environment');
      let visitedObjects = visited.get(ref.imageId);
      if (!visitedObjects) {
        visitedObjects = new Set();
        visited.set(ref.imageId, visitedObjects);
      }
      if (visitedObjects.has(ref.objectId)) throw new TypeError('lexical environment parent cycle detected');
      visitedObjects.add(ref.objectId);

      const environment = await images.getLexicalEnvironment(ref.imageId, ref.objectId);
      if (!environment) {
        throw new TypeError(`lexical environment not found: ${ref.imageId}/${ref.objectId}`);
      }
      if (Object.hasOwn(environment.bindings, bindingId)) return environment.bindings[bindingId];
      currentRef = environment.parent;
    }
    return null;
  }

  async lookupBinding(environmentRef, bindingId, images = this.images) {
    const record = await this.lookupBindingRecord(environmentRef, bindingId, images);
    if (!record) throw new TypeError(`lexical binding not found: ${bindingId}`);
    if (record.cell === true) throw new EscapingMutableClosureError(bindingId, record.name);
    if (record.unbound === true) throw new UnboundBindingError(record.name, bindingId);
    return canonicalizeValue(record.value);
  }

  async createClosure({prototype, captures}, cells = null, arena = null, frame = null) {
    const prototypeRef = normalizeObjectRef(prototype, 'closure prototype');
    if (!Array.isArray(captures)) throw new TypeError('closure captures must be an array');
    const resolver = arena ? arenaImagesView(this.images, arena) : this.images;
    const prototypeBlock = await resolver.getBlock(prototypeRef.imageId, prototypeRef.objectId);
    if (!prototypeBlock) {
      throw new TypeError(`closure prototype Block not found: ${prototypeRef.imageId}/${prototypeRef.objectId}`);
    }

    const bindings = {};
    const capturedCells = new Map();
    for (const capture of captures) {
      if (!capture || typeof capture !== 'object' || Array.isArray(capture)) throw new TypeError('closure capture must be an object');
      if (typeof capture.id !== 'string' || capture.id.length === 0) throw new TypeError('closure capture id must be non-empty text');
      if (typeof capture.name !== 'string' || capture.name.length === 0) throw new TypeError('closure capture name must be non-empty text');
      if (Object.hasOwn(bindings, capture.id)) throw new TypeError(`duplicate closure capture id: ${capture.id}`);
      if (capture.mode === 'cell') {
        // The cell of the frame that *declared* the binding, which is what `cells.resolve` walks
        // to — not whichever frame happens to be running. The durable record says only that a
        // cell is required: writing the current contents would hand a later invocation an old
        // value to restart from, which ADR 0043 decision 5 rules out.
        const cell = cells?.resolve(capture.id) ?? null;
        if (!cell) throw new EscapingMutableClosureError(capture.id, capture.name);
        capturedCells.set(capture.id, cell);
        bindings[capture.id] = {name: capture.name, cell: true};
        continue;
      }
      bindings[capture.id] = {name: capture.name, value: canonicalizeValue(capture.value)};
    }

    // ADR 0052 decision 5: a closure instance is execution-local. No environment record, no Block
    // record, no history event — the instance lives in the arena and becomes durable only if it
    // escapes, which is what makes evaluating a Block literal in a loop cost nothing.
    //
    // The instance's image is the prototype's, so dispatch-image behaviour is unchanged.
    const hasBindings = Object.keys(bindings).length > 0;
    let blockRef;
    if (arena) {
      const environment = hasBindings
        ? arena.mintClosureEnvironment(prototypeRef.imageId, {bindings})
        : null;
      blockRef = arena.mintClosureBlock(prototypeRef.imageId, {
        code: prototypeBlock.code,
        environment,
        metadata: {prototypeBlockId: prototypeRef.objectId},
      });
    } else {
      // No arena means no execution to be local to — a closure created outside one has nowhere
      // transient to live, so it is durable immediately.
      const environment = hasBindings
        ? await this.images.putLexicalEnvironment(prototypeRef.imageId, {bindings})
        : null;
      const block = await this.images.putBlock(prototypeRef.imageId, {
        code: prototypeBlock.code,
        environment: environment ? objectRef(environment.imageId, environment.id) : null,
        metadata: {prototypeBlockId: prototypeRef.objectId},
      });
      blockRef = objectRef(block.imageId, block.id);
    }
    // Execution-scoped, never durable: this is the only thing that lets a closure created in this
    // execution reach a live cell, and it dies with the arena.
    cells?.associate(blockRef, capturedCells);
    // Lexical frame state, alongside the lexical cells that already work this way. Execution-scoped
    // by construction: it dies with the arena, which is what makes an escaped closure fail closed
    // rather than carry a forgeable claim into a later execution (ADR 0050 decision 10a).
    if (frame) arena?.associateFrame?.(blockRef, frame);
    return blockRef;
  }

  // `authorityContext` is execution context in exactly the way `depth` already is: real,
  // load-bearing, and absent from the durable model. Nothing is added to the activation.
  // `invocationFrame` is ADR 0050 decision 5b's transient envelope, and `inheritedFrame` is the
  // caller's frame offered to a callee the language marked as its own host operation. Both are
  // execution context in exactly the way `depth` and `authority` are: they reach no activation
  // record, no Value and no durable state.
  async execute(activation, {
    depth = 0,
    authority = null,
    cellArena = null,
    dispatchImage = null,
    invocationFrame = null,
    inheritedFrame = null,
    conditionRuntime = null,
    signal = null,
  } = {}) {
    if (!Number.isInteger(depth) || depth < 0) throw new TypeError('activation depth must be a non-negative integer');
    if (depth > MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
    if (signal !== null && signal !== undefined && typeof signal?.aborted !== 'boolean') {
      throw new TypeError('signal must be an AbortSignal or null');
    }
    assertActivationRequest(activation);

    // The root execution owns the arena; nested sends share it. That is a lifetime relationship and
    // nothing more: cells are still reached by frame, so sharing an arena never means sharing a
    // variable. It is what makes a returned closure keep working for the rest of this execution
    // while still expiring when the execution does.
    //
    // Created here, before the verification reads below, because ADR 0052 lets the activation's
    // Block be a closure instance that lives only in the arena — so the resolver has to exist
    // before anything tries to resolve.
    // ADR 0052 decision 6: returning from a *root* execution is an escape, because the answer
    // reaches a caller with no arena. A nested send is not — it hands its answer back inside the
    // same arena, where a transient closure stays perfectly usable. The existing call structure
    // already draws that line exactly: the root is the execution that was given no arena.
    const ownsArena = !cellArena;
    const arena = cellArena ?? new LexicalCellArena();
    // ADR 0054: one execution-wide condition runtime, owned beside the arena and living exactly as
    // long. Nested sends share it, so a handler established anywhere in the execution is found from
    // anywhere else in it — including across a WASM boundary, which contributes no machinery of its
    // own.
    const conditions = conditionRuntime ?? arena.conditionRuntime();
    // ADR 0052 decision 5a: one resolution rule for this execution, shared by the executors, the
    // dispatcher and this class's own reads. Identical to `this.images` when there is no arena.
    const view = arenaImagesView(this.images, arena);
    // ADR 0060: a write to an already-promoted object may introduce a *new* transient value (a
    // backing store allocated after its owner escaped). The view's write-through promotes such a
    // value through the same central operation the boundary uses, so the durable copy never holds
    // an unpromoted ref. The memo is the arena's, so a value promoted here and at the boundary is
    // one object.
    if (arena) arena.postPromotionPromoter = async (value) => await promoteClosure(this.images, arena, value);

    const block = await view.getBlock(activation.block.imageId, activation.block.objectId);
    if (!block) throw new TypeError(`activation block not found: ${activation.block.imageId}/${activation.block.objectId}`);
    if (!sameRef(block.code, activation.code)) throw new TypeError('activation code does not match Block code');
    if (!sameRef(block.environment, activation.environment)) {
      throw new TypeError('activation environment does not match Block environment');
    }

    const code = await view.getCodeArtifact(activation.code.imageId, activation.code.objectId);
    if (!code) throw new TypeError(`activation code artifact not found: ${activation.code.imageId}/${activation.code.objectId}`);

    const executor = this.executors.get(code.representation);

    const cells = arena.activationCells(activation.block);

    // ADR 0050 decision 5a, in priority order:
    //
    //   a dispatch that supplied a frame        REPLACES  — the callee runs as its own self
    //   a callee the language marked inheriting INHERITS  — its host operation acts for the caller
    //   a closure created inside a framed frame  RESTORES  — lexical self, per decision 10
    //   anything else                            NONE      — and the slot primitives are unusable
    //
    // The restore case is also what makes decision 10a fail closed for free: the association lives
    // in the arena, the arena dies with the execution, so a closure invoked in a *later* execution
    // finds nothing rather than believing a durable claim.
    const activeFrame = invocationFrame
      ?? this.invocations?.frameFor?.(activation)
      ?? inheritedFrame
      ?? arena.frameFor?.(activation.block)
      ?? null;

    // ADR 0055 decision 3a. Computed *alongside* the expression above rather than by refactoring it,
    // so ADR 0050's priority semantics are reused rather than re-derived.
    //
    // Only a dispatch-supplied frame is owned. A kernel primitive inherits one and a closure restores
    // one — both are borrowers holding the very same object — so ownership, not frame equality, is
    // what decides where a non-local return stops. Otherwise the return primitive, which is running
    // with the home frame at the moment it raises, would catch its own transfer.
    const ownsFrame = activeFrame !== null
      && (invocationFrame !== null || this.invocations?.frameFor?.(activation) != null);
    // Marked live inside the protected region below, not here: a failure between this point and the
    // `try` — temporary initialization, for instance — would otherwise leave a frame permanently
    // live, and a later `^` naming it would be told its home is still running.
    const homeSelector = ownsFrame ? (activation.dispatch?.message?.value ?? null) : null;

    // ADR 0044 decision 5a. A root activation dispatches in its own Block's image; a nested one
    // inherits what its sender computed. Context, never a field on the activation.
    const activeDispatchImage = dispatchImage ?? activation.block.imageId;

    // Resolved once per activation, before any executor runs, so both lanes see one answer.
    let initialTemporaryContents = UNBOUND;
    if (this.temporaryInitializer) {
      const cachedInitial = arena.temporaryContents?.(activeDispatchImage, code.languageId ?? null);
      if (cachedInitial !== undefined) {
        initialTemporaryContents = cachedInitial;
      } else {
        // The artifact's language identity travels with the request, because initialization policy
        // belongs to a language rather than to an image. The execution layer still knows nothing
        // about any particular language — only that an artifact has one.
        const initial = await this.temporaryInitializer({
          images: view,
          dispatchImage: activeDispatchImage,
          languageId: code.languageId ?? null,
        });
        if (initial !== null && initial !== undefined) {
          initialTemporaryContents = canonicalizeValue(initial);
          arena.cacheTemporaryContents?.(activeDispatchImage, code.languageId ?? null, initialTemporaryContents);
        }
      }
    }

    // A mutable record rather than mere stack scoping, so that "active" can later mean "the
    // logical activation is still alive" once async activations exist, instead of "a
    // JavaScript frame happens to be on the stack".
    const lifetime = {active: true};
    const whileActive = (operation, implementation) => (...args) => {
      if (!lifetime.active) throw new ExpiredExecutionContextError(operation);
      return implementation(...args);
    };

    const activationFrameId = conditions.enterActivationFrame?.({
      depth,
      block: activation.block,
      code: activation.code,
      languageId: code.languageId ?? null,
      representation: code.representation,
      receiver: activation.receiver,
      selector: activation.dispatch?.message?.value ?? null,
      definingBehavior: activeFrame?.definingBehavior ?? null,
      ownsFrame,
      argumentCount: activation.arguments.length,
      metadata: activeFrame?.metadata ?? block.metadata ?? {},
    }) ?? null;

    const checkCancelled = () => {
      if (signal && signal.aborted) {
        const frames = conditions.snapshotActivationFrames?.() ?? Object.freeze([]);
        conditions.recordSignalSnapshot?.({
          condition: null,
          description: 'activation cancelled',
          handled: false,
          handlerScopeId: null,
          frames,
          scopes: conditions.snapshotScopes?.() ?? Object.freeze([]),
          restarts: conditions.snapshotRestarts?.() ?? Object.freeze([]),
        });
        throw new ActivationCancelledError(signal.reason ?? null, {frames});
      }
    };

    try {
      if (ownsFrame) this.#markHomeActivation(activeFrame, 'live', homeSelector);
      checkCancelled();
      const result = await executor.execute(
      {activation, code},
      {
        images: view,
        signal: signal ?? null,
        checkCancelled: whileActive('checkCancelled', checkCancelled),
        recordWasmState: whileActive('recordWasmState', (patch) => {
          if (activationFrameId !== null) {
            conditions.updateActivationFrameWasmState?.(activationFrameId, patch);
          }
        }),
        // ADR 0054. Primitives reach the condition runtime through this facade and never through
        // an authority context: `establish` hands back a scope id, and the *invoker* it stores
        // closes over the authority in force here. A handler therefore runs with its establisher's
        // rights without any capability crossing the primitive boundary (ADR 0037).
        conditions: Object.freeze({
          runtime: conditions,
          // Captures the authority in force *here*, and nothing else. An opaque handle rather than
          // the context itself, so a primitive can carry it to a handler entry without ever holding
          // a capability (ADR 0037).
          captureAuthority: whileActive('captureAuthority', () => {
            const token = Object.freeze({});
            CAPTURED_AUTHORITY.set(token, authority);
            return token;
          }),
          // Invoked from whichever frame is *running* the Block, not from the frame that captured
          // the token. Depth is therefore the depth at the signal point — a handler on a deep
          // signalling stack must not be measured from where `on:do:` was written — and the
          // dispatch image is the Block's own, which is the ordinary rule for any Block and is what
          // keeps a cross-image handler using its own kernel rather than the establisher's.
          //
          // Invoking a Block rather than dispatching a selector keeps this language-neutral, and
          // lets ADR 0050 restore the Block's creation frame, which is what gives a handler its
          // establisher's `self` for free.
          // ADR 0055. The primitive asks whether the frame it was handed still has a running
          // owner; it never sees the registry, and a frame is only ever a key in it.
          homeActivationState: whileActive('homeActivationState', (frame) => this.homeActivationState(frame)),
          homeActivationSelector: whileActive('homeActivationSelector', (frame) => this.homeActivationSelector(frame)),
          invoke: whileActive('invoke', async (token, blockRef, args = [], {uninterruptible = false} = {}) => {
            if (!CAPTURED_AUTHORITY.has(token)) throw new TypeError('unknown captured authority token');
            if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
            const activation = await this.invocations.prepareActivation({
              block: blockRef, arguments: args, images: view,
            });
            return await this.execute(activation, {
              depth: depth + 1,
              authority: CAPTURED_AUTHORITY.get(token),
              cellArena: arena,
              conditionRuntime: conditions,
              dispatchImage: normalizeObjectRef(blockRef, 'condition block').imageId,
              signal: uninterruptible ? null : signal,
            });
          }),
        }),
        // ADR 0052 decision 7a. The boundary that creates durable reachability calls this before
        // its write; the graph guard stays a tripwire proving a boundary was not forgotten, rather
        // than becoming the mechanism. A value with nothing transient in it comes straight back.
        promote: whileActive('promote', async (value) => await promoteClosure(this.images, arena, value)),
        // ADR 0060 decision 3. An object allocated inside this execution begins in the arena, not
        // the durable store — `basicNew` and condition allocation mint here, and the object becomes
        // durable only if a reference crosses a durability boundary via `promote`. The arena owns
        // the identity (a transient ref in the reserved namespace); the caller supplies only the
        // layout, so there is no identity collision to retry.
        mintObject: whileActive('mintObject', ({imageId, shape, behavior, slots = {}, indexed = null, metadata = {}}) => (
          arena.mintObject(imageId, {shape, behavior, slots, indexed, metadata})
        )),
        // Check-only, and the only authority operation that crosses this seam. There is no
        // grant to return, no context to read, and no principal to branch on. Absent
        // authority fails closed rather than permitting.
        require: whileActive('require', (demand) => {
          if (!this.authority) throw new TypeError('no authority service is configured; this execution has no capabilities');
          if (authority === null) throw new TypeError('no authority context was supplied; this execution has no capabilities');
          return this.authority.require(authority, demand);
        }),
        lookupBinding: whileActive('lookupBinding', async (bindingId) => {
          if (!activation.environment) throw new TypeError(`lexical binding not found: ${bindingId}`);
          return await this.lookupBinding(activation.environment, bindingId, view);
        }),
        // Declared, not initialized: a temporary has no value until it is assigned, and there is
        // no nil to give it. Reading one before assignment raises rather than defaulting.
        declareTemporaries: whileActive('declareTemporaries', (temporaries) => {
          if (!Array.isArray(temporaries)) throw new TypeError('temporaries must be an array');
          cells.declare(temporaries, initialTemporaryContents);
        }),
        // Cell-only and synchronous, which `readBinding` cannot be: it falls through to an awaited
        // durable-environment lookup. A WASM import must return a value, not a promise, so the
        // WASM lane uses these and never the general ones. Absence raises rather than falling
        // back, so there is no path by which a durable snapshot could answer a cell read.
        readCell: whileActive('readCell', (bindingId) => {
          const cell = cells.resolve(bindingId);
          if (!cell) throw new MissingLexicalCellError(bindingId);
          return cell.read();
        }),
        writeCell: whileActive('writeCell', (bindingId, value) => {
          const cell = cells.resolve(bindingId);
          if (!cell) throw new MissingLexicalCellError(bindingId);
          return cell.write(value);
        }),
        readBinding: whileActive('readBinding', async (bindingId) => {
          const cell = cells.resolve(bindingId);
          if (cell) return cell.read();
          if (!activation.environment) throw new TypeError(`lexical binding not found: ${bindingId}`);
          return await this.lookupBinding(activation.environment, bindingId, view);
        }),
        writeBinding: whileActive('writeBinding', async (bindingId, value) => {
          const cell = cells.resolve(bindingId);
          if (cell) return cell.write(value);
          // Assignment reaches cells only. A durable binding is layout plus a snapshot, and ADR
          // 0043 decision 2 keeps assignment out of the graph entirely.
          const record = activation.environment
            ? await this.lookupBindingRecord(activation.environment, bindingId, view)
            : null;
          if (record?.cell === true) throw new EscapingMutableClosureError(bindingId, record.name);
          if (record) throw new TypeError(`lexical binding ${bindingId} is not an assignable cell`);
          throw new TypeError(`lexical binding not found: ${bindingId}`);
        }),
        // Read-only, and only meaningful to a language-owned executor: it is the identity of the
        // method activation this operation is acting for, never a capability.
        invocationFrame: activeFrame,
        createClosure: whileActive('createClosure', async (request) => await this.createClosure(request, cells, arena, activeFrame)),
        // ADR 0098. Language-neutral direct callable Block application. Unlike `sendMessage`,
        // `invokeBlock` resolves no selector through a language dispatcher, sets `receiver: null`
        // and `dispatch: null` via `prepareActivation` (so `assertBlockApplicationReceiver`
        // accepts all callable bindings while `assertLoopBlock` still refuses un-dispatched loop
        // primitives), and passes neither `invocationFrame` nor `inheritedFrame` (so a method
        // cannot lend its `self`/`definingBehavior` to a Block it applies, while a lexical closure
        // still restores its own creation frame from `arena.frameFor(activation.block)`).
        invokeBlock: whileActive('invokeBlock', async (blockRef, args = [], {attenuate = null} = {}) => {
          if (!this.invocations) throw new TypeError('activation executor has no message runtime');
          if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
          let nestedAuthority = authority;
          if (attenuate !== null) {
            if (!this.authority) throw new TypeError('cannot attenuate without an authority service');
            if (authority === null) throw new TypeError('cannot attenuate without an authority context');
            nestedAuthority = this.authority.attenuate(authority, {grants: attenuate});
          }
          const nestedActivation = await this.invocations.prepareActivation({
            block: blockRef,
            arguments: args,
            images: view,
          });
          return await this.execute(nestedActivation, {
            depth: depth + 1,
            authority: nestedAuthority,
            cellArena: arena,
            conditionRuntime: conditions,
            dispatchImage: nestedActivation.block.imageId,
            signal,
          });
        }),
        // ADR 0089. The activation half of a language-resolved send, and the only reason a
        // Symmetric Smalltalk super send needs no execution path of its own.
        //
        // Lookup happened at the language's own lookup owner, because a super send starts above the
        // running method's DEFINING Behavior rather than at the receiver's — a starting point
        // ordinary dispatch cannot express. Everything after lookup is identical to an ordinary
        // nested send and stays here: the depth guard, the shared arena and condition runtime, the
        // inherited authority, and the dispatch image. The frame is neither built nor attached here;
        // it travels through `prepareResolvedDispatch`'s existing normalization and envelope, so the
        // callee discovers it by the same priority walk as any dispatched method and OWNS it.
        invokeResolvedMethod: whileActive('invokeResolvedMethod', async ({
          languageId, block, receiver, message, arguments: args = [], frame,
        }) => {
          if (!this.invocations) throw new TypeError('activation executor has no message runtime');
          if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
          const nextDispatchImage = isObjectRef(receiver) ? receiver.imageId : activeDispatchImage;
          const resolved = await this.invocations.prepareResolvedDispatch({
            languageId, block, receiver, message, arguments: args, frame, images: view,
          });
          return await this.execute(resolved.activation, {
            depth: depth + 1,
            authority,
            cellArena: arena,
            conditionRuntime: conditions,
            dispatchImage: nextDispatchImage,
            signal,
          });
        }),
        // A nested send inherits the current authority. An executor may ask for a narrower
        // child, but never receives one: the attenuation happens here, so no executor ever
        // holds a context. Since attenuation only narrows, a nested send can lose rights and
        // can never gain them.
        sendMessage: whileActive('sendMessage', async (request, {attenuate = null} = {}) => {
          if (!this.invocations) throw new TypeError('activation executor has no message runtime');
          if (depth >= MAX_ACTIVATION_DEPTH) throw new TypeError('activation depth limit exceeded');
          let nestedAuthority = authority;
          if (attenuate !== null) {
            if (!this.authority) throw new TypeError('cannot attenuate without an authority service');
            if (authority === null) throw new TypeError('cannot attenuate without an authority context');
            nestedAuthority = this.authority.attenuate(authority, {grants: attenuate});
          }
          // An object receiver dispatches in its own image; an immediate one has none, so the
          // sender's dispatch image carries through unchanged.
          const nextDispatchImage = isObjectRef(request.receiver)
            ? request.receiver.imageId
            : activeDispatchImage;
          const dispatched = await this.invocations.prepareDispatch(request, {
            dispatchImage: nextDispatchImage, images: view,
          });
          return await this.execute(dispatched.activation, {
            depth: depth + 1,
            authority: nestedAuthority,
            cellArena: arena,
            conditionRuntime: conditions,
            dispatchImage: nextDispatchImage,
            invocationFrame: dispatched.frame,
            // Offered only where the language said this callee is its own host operation. An
            // ordinary Block send inherits nothing, so a method cannot lend its identity to a Block
            // it merely invoked.
            inheritedFrame: dispatched.inheritsFrame ? activeFrame : null,
            signal,
          });
        }),
      },
      );
      const answer = canonicalizeValue(result);
      // Before leaving, while the arena still exists. Deliberately the returned Value only: a
      // durable object cannot secretly hold a transient closure, because creating that edge would
      // already have been refused at the graph write seam. Walking a returned object graph would be
      // I/O spent re-proving what the write boundary guarantees.
      return ownsArena ? await promoteClosure(this.images, arena, answer) : answer;
    } catch (error) {
      // Only the owner stops a return naming its own frame; a borrower lets it travel on.
      if (ownsFrame && error instanceof NonLocalReturnTransfer && error.frame === activeFrame) {
        const answer = canonicalizeValue(error.value);
        // The same escape boundary an ordinary return crosses (ADR 0052 decision 6): a root
        // execution's answer is promoted before leaving, while the arena still exists. Returning
        // this value unpromoted would let `^ [ ... ]` hand a transient closure to a caller that has
        // no arena to resolve it in.
        return ownsArena ? await promoteClosure(this.images, arena, answer) : answer;
      }
      throw error;
    } finally {
      // Also on the exceptional path: a trapping guest must not leave a live context behind.
      lifetime.active = false;
      if (activationFrameId !== null) conditions.leaveActivationFrame?.(activationFrameId);
      // Dead from here on. Retained rather than deleted: while the frame is still reachable, a
      // `^` naming it must be told the method returned rather than that it has no home.
      // Marked dead rather than deleted: while the frame is still reachable, a `^` naming it must
      // be told the method returned rather than that it has no home.
      if (ownsFrame) this.#markHomeActivation(activeFrame, 'dead', homeSelector);
    }
  }
}

export {
  ActivationCancelledError,
  ActivationExecutor,
  ExpiredExecutionContextError,
  MAX_ACTIVATION_DEPTH,
  assertActivationRequest,
};

import {canonicalizeValue, isObjectRef} from '../value/index.js';

function sameObjectRef(left, right) {
  return left.imageId === right.imageId && left.objectId === right.objectId;
}

function assertBlockApplicationReceiver(activation, label = 'callable Block') {
  if (!activation || typeof activation !== 'object' || Array.isArray(activation)) {
    throw new TypeError(`${label} activation must be an object`);
  }
  if (activation.receiver === null) return activation;

  const block = canonicalizeValue(activation.block);
  const receiver = canonicalizeValue(activation.receiver);
  if (!isObjectRef(block) || !isObjectRef(receiver) || !sameObjectRef(block, receiver)) {
    throw new TypeError(`${label} accepts only direct Block invocation or the Block itself as receiver`);
  }
  return activation;
}

export {assertBlockApplicationReceiver};

import {ensureBlock, ensureLexicalEnvironment, ensureObject} from '../graph/ensure-records.js';
import {objectRef} from '../value/index.js';
import {TRANSIENT_ID_PREFIX, isTransientRef} from '../value/transient-ref.js';
import {ExpiredClosureInstanceError} from './lexical-cells.js';

// ADR 0052 decision 7a: promotion is ONE operation, not a habit.
//
// Every escape boundary — root return, slot and indexed writes, Dictionary writes, the foreign
// boundary — calls this and nothing else. Four implementations of a rule this subtle would disagree,
// and the disagreement would surface as a closure that is sometimes shared and sometimes duplicated.
//
// The ordering below is the whole design, so it is worth reading as a sequence:
//
//   discover a transient instance
//     -> compute its durable id
//     -> memoize transient -> durable *immediately*, before recursing
//     -> recursively promote snapshot-captured transient refs
//     -> write the environment (exact-or-create)
//     -> write the Block (exact-or-create)
//
// The early memo is what makes sharing and cycles terminate: a closure reached twice is answered
// from the memo the second time, and a cycle meets its own entry rather than recursing forever. The
// preassigned durable ref is what lets another environment name this closure before its Block record
// exists — which is legal because `putLexicalEnvironment` validates the parent edge only and does
// not require binding refs to resolve, so no atomic write of a cycle is needed.
//
// But "identity reserved" and "records published" are different facts, and conflating them turns the
// very mechanism that breaks cycles into a way of reporting a failed promotion as a success: a retry
// would meet the leftover entry and answer a durable ref whose Block was never written. The memo
// therefore has three effective states:
//
//   absent        begin promotion
//   in-progress   answer the preassigned ref, so recursion and cycles terminate
//   complete      answer the promoted ref; the records exist
//
// A failure clears the in-progress entry, so a later call re-runs publication rather than trusting
// a reservation nobody honoured. Exact-or-create is what makes that safe after a commit-then-lost-
// ack: the retry rediscovers its own committed records and converges on them.

// Deterministic, and derived from the transient id — which already carries a per-arena nonce, so two
// executions cannot collide and a retry within one execution recomputes the same id. That is what
// makes a lost acknowledgement converge instead of promoting one closure under two identities.
//
// The transient id embeds the arena's mint kind as its first segment (`block`, `environment`,
// `object`). Closures keep the historical `closure/` prefix so a pre-ADR-0060 promoted closure's
// derived id is unchanged; objects derive under `object/`. The kind segment is consumed, not
// carried into the durable id.
function durableIdFor(transientObjectId) {
  const suffix = transientObjectId.slice(TRANSIENT_ID_PREFIX.length);
  if (suffix.startsWith('object/')) return `object/${suffix.slice('object/'.length)}`;
  return `closure/${suffix}`;
}

// Snapshot bindings only. A `{cell: true}` binding carries no value by construction, so there is
// nothing here to read — and that is deliberate rather than incidental: ADR 0043 keeps cell contents
// out of the durable record, and letting promotion see them would make transient state decide what
// persists. What is traversed is what is written.
function promotedBinding(binding) {
  if (binding?.cell === true) return {name: binding.name, cell: true};
  return {name: binding.name, unbound: true};
}

class ClosurePromoter {
  #images;
  #arena;
  #memo;

  constructor(images, arena) {
    this.#images = images;
    this.#arena = arena;
    // Per arena, so promotion is idempotent for the whole execution: a closure written into two
    // slots is one closure, in the second slot as much as the first.
    this.#memo = arena.promotionMemo();
  }

  // Rewrites a Value that may itself be, or contain, a transient reference. Returns a plain Value
  // when there is nothing transient about it, which is the overwhelmingly common case.
  async promoteValue(value) {
    if (!isTransientRef(value)) return value;
    return await this.promote(value);
  }

  async promote(ref) {
    const key = [ref.imageId, ref.objectId];
    // Both `in-progress` and `complete` answer the same ref: the first is what closes a cycle, the
    // second is what makes promotion idempotent. Only `absent` starts work.
    const existing = this.#memo.get(key);
    if (existing) return existing.ref;

    const record = this.#arena.transientRecord(ref.imageId, ref.objectId);
    if (!record) throw new ExpiredClosureInstanceError(ref.imageId, ref.objectId);

    const durable = objectRef(ref.imageId, durableIdFor(ref.objectId));
    // Reserved before any recursion. Everything below may reach this same instance again.
    this.#memo.set(key, {ref: durable, status: 'in-progress'});
    try {
      if (record.kind === 'block') {
        const environment = await this.#promoteEnvironment(ref.imageId, record.environment);
        await ensureBlock(this.#images, ref.imageId, {
          id: durable.objectId,
          code: record.code,
          environment,
          metadata: {...record.metadata},
        });
      } else if (record.kind === 'object') {
        await this.#promoteObjectRecord(ref, durable.objectId);
      } else {
        throw new TypeError(`only a closure instance or an object can be promoted: ${ref.imageId}/${ref.objectId}`);
      }
      this.#memo.set(key, {ref: durable, status: 'complete'});
      return durable;
    } catch (error) {
      // A reservation nobody honoured must not survive as an answer. Dropping it costs only the
      // work of re-running an exact-or-create publication, which converges whether the failed
      // attempt wrote nothing or wrote everything and lost the acknowledgement.
      this.#memo.delete(key);
      throw error;
    }
  }

  // ADR 0060 decision 5. The durable projection is the object's slots and indexed part, recursively
  // through transient refs only: what is traversed is what is written. A durable ref reachable from
  // the object is an edge to an existing durable record and is written as an edge, not re-published.
  // The preassigned durable ref (reserved in `promote` before this runs) is what lets a cycle name
  // this object before its record exists, so the traversal terminates on shared structure and on
  // cycles through the memo.
  //
  // The record is re-read from the arena *at write time*, not carried from the caller. Promotion of
  // a cyclic graph suspends inside a nested `promoteValue`, and Smalltalk code runs while a cycle is
  // still in-progress (`initialize`, slot writes) — so the object can be mutated between reservation
  // and publication. Writing the stale snapshot would silently drop the mutation that closed the
  // cycle (a link written *after* its target was reserved). The arena holds the live state; the
  // write publishes it as it stands when the holder's own promotion completes.
  async #promoteObjectRecord(ref, durableObjectId) {
    const record = this.#arena.transientRecord(ref.imageId, ref.objectId);
    if (!record) throw new ExpiredClosureInstanceError(ref.imageId, ref.objectId);
    const slots = {};
    for (const [slotId, value] of Object.entries(record.slots)) {
      slots[slotId] = await this.promoteValue(value);
    }
    let indexed;
    if (Object.hasOwn(record, 'indexed')) {
      indexed = [];
      for (const value of record.indexed) {
        indexed.push(await this.promoteValue(value));
      }
    }
    const desired = {
      id: durableObjectId,
      shape: record.shape,
      behavior: record.behavior,
      slots,
      ...(indexed !== undefined ? {indexed} : {}),
      metadata: {...record.metadata},
    };
    this.#arena.imagesViewFor?.(this.#images)?.invalidateObject?.(ref.imageId, durableObjectId);
    await ensureObject(this.#images, ref.imageId, desired);
  }

  async #promoteEnvironment(imageId, environmentRef) {
    if (!environmentRef) return null;
    // An instance may close over an environment that is already durable — a prototype's, say — in
    // which case there is nothing to promote and the edge stands as it is.
    if (!isTransientRef(environmentRef)) return environmentRef;

    const record = this.#arena.transientRecord(environmentRef.imageId, environmentRef.objectId);
    if (!record) throw new ExpiredClosureInstanceError(environmentRef.imageId, environmentRef.objectId);

    const bindings = {};
    for (const [bindingId, binding] of Object.entries(record.bindings)) {
      bindings[bindingId] = binding?.cell === true || binding?.unbound === true
        ? promotedBinding(binding)
        : {name: binding.name, value: await this.promoteValue(binding.value)};
    }

    const parent = await this.#promoteEnvironment(imageId, record.parent);
    const id = durableIdFor(environmentRef.objectId);
    await ensureLexicalEnvironment(this.#images, environmentRef.imageId, {
      id,
      ...(parent ? {parent} : {}),
      bindings,
    });
    return objectRef(environmentRef.imageId, id);
  }
}

// The single entry point every boundary uses.
async function promoteClosure(images, arena, value) {
  if (!arena || !isTransientRef(value)) return value;
  return await new ClosurePromoter(images, arena).promoteValue(value);
}

export {ClosurePromoter, durableIdFor, promoteClosure};

import {canonicalizeValue} from '../value/index.js';

// ADR 0054: the condition runtime.
//
// One execution-wide stack of scopes, owned beside the arena and living exactly as long. The three
// classless-Block operations (`on:do:`, `ensure:`, `ifCurtailed:`) only enter and leave scopes on it,
// and signalling only searches it — so the neutral and WASM lanes share one handler search and one
// transfer mechanism, and WASM contributes nothing but the suspend/resume/retire behaviour it
// already had. There is deliberately no "WASM exception system".
//
// Nothing here is durable. A scope reaches no record, no Value and no activation field: it is
// execution context in the way `dispatchImage`, the authority context and ADR 0050's frame are.

// The unwind mechanism. Thrown to move control to a scope that is still on the stack, and carried by
// the host's own stack unwinding — which is what makes `ensure:` fire for host failures too, since
// they travel the same way.
class ConditionTransfer extends Error {
  constructor(kind, scopeId, value, occurrenceId = null) {
    super(`condition transfer (${kind})`);
    this.name = 'ConditionTransfer';
    this.kind = kind;
    this.scopeId = scopeId;
    this.value = value;
    this.occurrenceId = occurrenceId;
  }
}

// ADR 0055. A transfer that names a *home method activation* rather than a handler scope, which is
// why `on:do:` cannot intercept one: it is a different class and carries a frame, not a scope id.
class NonLocalReturnTransfer extends Error {
  constructor(frame, value) {
    super('non-local return');
    this.name = 'NonLocalReturnTransfer';
    this.frame = frame;
    this.value = value;
  }
}

class NonLocalReturnHomeError extends TypeError {
  constructor(detail) {
    super(`non-local return has no live home method activation: ${detail}`);
    this.name = 'NonLocalReturnHomeError';
  }
}

class UnhandledConditionError extends TypeError {
  constructor(description, message = `unhandled condition: ${description}`) {
    super(message);
    this.name = 'UnhandledConditionError';
    this.description = description;
  }
}

class NoActiveOccurrenceError extends TypeError {
  constructor(operation) {
    super(`${operation} requires a condition that is currently being handled`);
    this.name = 'NoActiveOccurrenceError';
    this.operation = operation;
  }
}

class ActivationCancelledError extends Error {
  constructor(reason = null, {frames = null, message = null} = {}) {
    const detail = typeof reason === 'string' && reason.length > 0
      ? `: ${reason}`
      : (reason instanceof Error && reason.message ? `: ${reason.message}` : '');
    super(message ?? `activation cancelled${detail}`);
    this.name = 'ActivationCancelledError';
    this.reason = reason;
    this.frames = frames ? Object.freeze([...frames]) : Object.freeze([]);
  }
}

function defaultExecutionLane(representation) {
  if (typeof representation === 'string' && representation.startsWith('wasm-function/')) {
    return 'wasm';
  }
  return 'neutral';
}

class ConditionRuntime {
  #scopes = [];
  #occurrences = [];
  #activationFrames = [];
  #restarts = [];
  #wasmResumptions = [];
  #lastSignalSnapshot = null;
  #nextId = 0;

  // `authorityToken` is an opaque handle to the authority in force at establishment. The runtime
  // carries it and never reads it; only the executor can resolve it (ADR 0037). Deliberately *not*
  // a bound invoker: binding one would freeze the establishment frame's depth and dispatch image
  // too, and a handler must run at the signal point's depth and in its own Block's image.
  enterHandler({conditionClass, block, authorityToken}) {
    const scopeId = (this.#nextId += 1);
    this.#scopes.push({scopeId, kind: 'handler', conditionClass, block, authorityToken, active: true});
    return scopeId;
  }

  enterProtection({kind, block, authorityToken}) {
    const scopeId = (this.#nextId += 1);
    this.#scopes.push({scopeId, kind, block, authorityToken, active: true});
    return scopeId;
  }

  enterRestart({name, block, description = null, authorityToken = null}) {
    const restartId = (this.#nextId += 1);
    this.#restarts.push({
      restartId,
      name: String(name),
      block,
      description: description === null ? null : String(description),
      authorityToken,
      active: true,
    });
    return restartId;
  }

  leaveRestart(restartId) {
    const index = this.#restarts.findIndex((entry) => entry.restartId === restartId);
    if (index >= 0) this.#restarts.length = index;
  }

  enterActivationFrame(descriptor = {}) {
    const frameId = (this.#nextId += 1);
    const representation = descriptor.representation ?? null;
    const entry = Object.freeze({
      frameId,
      depth: Number.isInteger(descriptor.depth) ? descriptor.depth : this.#activationFrames.length,
      block: descriptor.block ?? null,
      code: descriptor.code ?? null,
      languageId: descriptor.languageId ?? null,
      representation,
      executionLane: descriptor.executionLane ?? defaultExecutionLane(representation),
      receiver: descriptor.receiver ?? null,
      selector: descriptor.selector ?? null,
      definingBehavior: descriptor.definingBehavior ?? null,
      ownsFrame: Boolean(descriptor.ownsFrame),
      argumentCount: Number.isInteger(descriptor.argumentCount) ? descriptor.argumentCount : 0,
      metadata: Object.freeze({...(descriptor.metadata ?? {})}),
      wasmState: descriptor.wasmState ?? null,
      suspensionCount: Number.isInteger(descriptor.suspensionCount) ? descriptor.suspensionCount : 0,
      resumedCount: Number.isInteger(descriptor.resumedCount) ? descriptor.resumedCount : 0,
      lastSuspension: descriptor.lastSuspension ? Object.freeze({...descriptor.lastSuspension}) : null,
    });
    this.#activationFrames.push(entry);
    return frameId;
  }

  updateActivationFrameWasmState(frameId, patch = {}) {
    const index = this.#activationFrames.findIndex((entry) => entry.frameId === frameId);
    if (index < 0) return null;
    const current = this.#activationFrames[index];
    const nextLastSuspension = Object.hasOwn(patch, 'lastSuspension')
      ? (patch.lastSuspension ? Object.freeze({...patch.lastSuspension}) : null)
      : current.lastSuspension;
    const updated = Object.freeze({
      ...current,
      wasmState: patch.wasmState ?? current.wasmState,
      suspensionCount: Number.isInteger(patch.suspensionCount) ? patch.suspensionCount : current.suspensionCount,
      resumedCount: Number.isInteger(patch.resumedCount) ? patch.resumedCount : current.resumedCount,
      lastSuspension: nextLastSuspension,
    });
    this.#activationFrames[index] = updated;
    if (patch.event === 'suspend' || patch.event === 'resume' || patch.event === 'retire') {
      this.#wasmResumptions.push(Object.freeze({
        frameId,
        depth: updated.depth,
        block: updated.block,
        code: updated.code,
        selector: updated.selector,
        event: patch.event,
        wasmState: updated.wasmState,
        suspensionCount: updated.suspensionCount,
        resumedCount: updated.resumedCount,
        suspension: nextLastSuspension,
      }));
    }
    return updated;
  }

  snapshotWasmResumptions() {
    return Object.freeze([...this.#wasmResumptions]);
  }

  leaveActivationFrame(frameId) {
    const index = this.#activationFrames.findIndex((entry) => entry.frameId === frameId);
    if (index >= 0) this.#activationFrames.length = index;
  }

  snapshotActivationFrames() {
    return Object.freeze([...this.#activationFrames]);
  }

  snapshotScopes() {
    return Object.freeze(this.#scopes.map((scope) => Object.freeze({
      scopeId: scope.scopeId,
      kind: scope.kind,
      conditionClass: scope.conditionClass ?? null,
      block: scope.block ?? null,
      active: Boolean(scope.active),
    })));
  }

  snapshotOccurrences() {
    return Object.freeze(this.#occurrences.map((entry) => Object.freeze({
      occurrenceId: entry.occurrenceId,
      condition: entry.condition,
      handlerScopeId: entry.handlerScopeId,
      active: Boolean(entry.active),
    })));
  }

  snapshotRestarts() {
    return Object.freeze(
      this.#restarts
        .filter((entry) => entry.active)
        .map((entry) => Object.freeze({
          restartId: entry.restartId,
          name: entry.name,
          block: entry.block,
          description: entry.description,
          active: true,
        })),
    );
  }

  recordSignalSnapshot(snapshot) {
    this.#lastSignalSnapshot = Object.freeze({...snapshot});
    return this.#lastSignalSnapshot;
  }

  lastSignalSnapshot() {
    return this.#lastSignalSnapshot;
  }

  // Truncates rather than pops: an unwind may have skipped scopes established inside this one, and
  // leaving them on the stack would let a later signal find a handler whose `on:do:` has returned.
  leave(scopeId) {
    const index = this.#scopes.findIndex((scope) => scope.scopeId === scopeId);
    if (index >= 0) this.#scopes.length = index;
  }

  // Innermost first, and only scopes that are active — a handler is disabled while it runs, so a
  // re-signal from inside it delegates outward instead of recursing into itself.
  //
  // Asynchronous because matching walks the candidate's superclass chain through the image, which is
  // I/O. Sequential rather than parallel on purpose: innermost-first is the semantics, not an
  // optimisation, so the first match must be the innermost one.
  async findHandler(matches) {
    for (let index = this.#scopes.length - 1; index >= 0; index -= 1) {
      const scope = this.#scopes[index];
      if (scope.kind !== 'handler' || !scope.active) continue;
      if (await matches(scope.conditionClass)) return scope;
    }
    return null;
  }

  // The handling scope is recorded on the occurrence, so `return:` knows where to unwind to without
  // the condition object carrying any control-flow state.
  beginOccurrence(condition, handlerScopeId) {
    const occurrenceId = (this.#nextId += 1);
    this.#occurrences.push({occurrenceId, condition, handlerScopeId, active: true});
    return occurrenceId;
  }

  endOccurrence(occurrenceId) {
    const index = this.#occurrences.findIndex((entry) => entry.occurrenceId === occurrenceId);
    if (index >= 0) this.#occurrences.splice(index, 1);
  }

  // The receiver's *currently active* occurrence. One condition object signalled twice has two, and
  // neither may see the other's — so this is resolved per handling and never read off the object.
  activeOccurrenceFor(sameCondition) {
    for (let index = this.#occurrences.length - 1; index >= 0; index -= 1) {
      const entry = this.#occurrences[index];
      if (entry.active && sameCondition(entry.condition)) return entry;
    }
    return null;
  }

  withDisabled(scope, body) {
    scope.active = false;
    return Promise.resolve()
      .then(body)
      .finally(() => { scope.active = true; });
  }
}

function performNonLocalReturn({
  context,
  value,
  requireConditionRuntimeMessage = 'non-local return requires a condition runtime',
  formatDeadHome = null,
}) {
  const frame = context?.invocationFrame ?? null;
  if (!frame) {
    throw new NonLocalReturnHomeError(
      'the Block has no home frame; it outlived the execution that created it',
    );
  }
  if (typeof context.conditions?.homeActivationState !== 'function') {
    throw new TypeError(requireConditionRuntimeMessage);
  }
  const state = context.conditions.homeActivationState(frame);
  if (state === 'dead') {
    const selector = context.conditions.homeActivationSelector?.(frame) ?? null;
    const summary = typeof formatDeadHome === 'function'
      ? formatDeadHome({frame, selector})
      : `${frame.definingBehavior?.objectId ?? 'unknown'}${selector ? ` >> ${selector}` : ''}`;
    throw new NonLocalReturnHomeError(
      `the home method activation has already returned: ${summary}`,
    );
  }
  if (state !== 'live') {
    throw new NonLocalReturnHomeError('the frame in force is not a home method activation');
  }
  throw new NonLocalReturnTransfer(frame, canonicalizeValue(value));
}

async function runConditionHandler({facade, conditionClass, handlerBlock, protectedBlock}) {
  const authorityToken = facade.captureAuthority();
  const scopeId = facade.runtime.enterHandler({
    conditionClass: canonicalizeValue(conditionClass),
    block: handlerBlock,
    authorityToken,
  });
  try {
    return await facade.invoke(authorityToken, protectedBlock, []);
  } catch (error) {
    if (error instanceof ConditionTransfer && error.kind === 'return' && error.scopeId === scopeId) {
      return canonicalizeValue(error.value);
    }
    throw error;
  } finally {
    facade.runtime.leave(scopeId);
  }
}

async function runUnwindProtection({
  facade,
  kind,
  protectedBlock,
  cleanupBlock,
  onlyWhenCurtailed = false,
}) {
  const authorityToken = facade.captureAuthority();
  const scopeId = facade.runtime.enterProtection({kind, block: cleanupBlock, authorityToken});

  let result = null;
  let primary = null;
  try {
    result = await facade.invoke(authorityToken, protectedBlock, []);
  } catch (error) {
    primary = error;
  } finally {
    facade.runtime.leave(scopeId);
  }

  if (primary !== null || !onlyWhenCurtailed) {
    try {
      await facade.invoke(authorityToken, cleanupBlock, [], {uninterruptible: true});
    } catch (secondary) {
      if (primary !== null && secondary && typeof secondary === 'object' && !secondary.duringUnwind) {
        secondary.duringUnwind = primary;
      }
      throw secondary;
    }
  }
  if (primary !== null) throw primary;
  return result;
}

async function signalConditionOccurrence({
  facade,
  condition,
  matches,
  createUnhandledError = (description) => new UnhandledConditionError(description),
  describeCondition = () => 'condition',
}) {
  const normalizedCondition = canonicalizeValue(condition);
  const scope = await facade.runtime.findHandler(matches);
  const descriptionText = describeCondition();
  const signalFrames = facade.runtime.snapshotActivationFrames?.() ?? Object.freeze([]);
  const signalScopes = facade.runtime.snapshotScopes?.() ?? Object.freeze([]);
  const signalRestarts = facade.runtime.snapshotRestarts?.() ?? Object.freeze([]);
  if (!scope) {
    const unhandledSnapshot = facade.runtime.recordSignalSnapshot?.({
      condition: normalizedCondition,
      description: descriptionText,
      handled: false,
      handlerScopeId: null,
      frames: signalFrames,
      scopes: signalScopes,
      restarts: signalRestarts,
    }) ?? null;
    const unhandledError = createUnhandledError(descriptionText);
    if (unhandledError && typeof unhandledError === 'object' && unhandledSnapshot) {
      unhandledError.conditionSnapshot = unhandledSnapshot;
    }
    throw unhandledError;
  }

  const occurrence = facade.runtime.beginOccurrence(normalizedCondition, scope.scopeId);
  facade.runtime.recordSignalSnapshot?.({
    condition: normalizedCondition,
    description: descriptionText,
    handled: true,
    handlerScopeId: scope.scopeId,
    occurrenceId: occurrence,
    frames: signalFrames,
    scopes: signalScopes,
    restarts: signalRestarts,
  });
  try {
    const answer = await facade.runtime.withDisabled(
      scope,
      async () => await facade.invoke(scope.authorityToken, scope.block, [normalizedCondition]),
    );
    throw new ConditionTransfer('return', scope.scopeId, canonicalizeValue(answer));
  } catch (error) {
    if (error instanceof ConditionTransfer && error.kind === 'resume' && error.occurrenceId === occurrence) {
      return canonicalizeValue(error.value);
    }
    throw error;
  } finally {
    facade.runtime.endOccurrence(occurrence);
  }
}

function transferConditionOccurrence({
  facade,
  sameCondition,
  value,
  kind,
  operation,
  createNoActiveOccurrenceError = (op) => new NoActiveOccurrenceError(op),
}) {
  const occurrence = facade.runtime.activeOccurrenceFor(sameCondition);
  if (!occurrence) throw createNoActiveOccurrenceError(operation);
  const normalizedValue = canonicalizeValue(value);
  if (kind === 'resume') {
    throw new ConditionTransfer('resume', null, normalizedValue, occurrence.occurrenceId);
  }
  throw new ConditionTransfer('return', occurrence.handlerScopeId, normalizedValue);
}

export {
  ActivationCancelledError,
  ConditionRuntime,
  ConditionTransfer,
  NoActiveOccurrenceError,
  NonLocalReturnHomeError,
  NonLocalReturnTransfer,
  UnhandledConditionError,
  performNonLocalReturn,
  runConditionHandler,
  runUnwindProtection,
  signalConditionOccurrence,
  transferConditionOccurrence,
};

import {OBJECT_READ_OPERATION, objectResource} from '../authority/object-resource.js';
import {canonicalizeValue, isObjectRef} from '../value/index.js';
import {assertActivationRequest} from './activation-executor.js';
import {ActivationCancelledError, ConditionRuntime, UnhandledConditionError} from './conditions.js';

const ACTIVATION_STACK_REPORT_V1 = 'lagrange-activation-stack-report/v1';
const CONDITION_INSPECTION_REPORT_V1 = 'lagrange-condition-inspection-report/v1';

function resolveConditionRuntime(source) {
  if (!source) return null;
  if (source instanceof ConditionRuntime) return source;
  if (source.conditions?.runtime instanceof ConditionRuntime) return source.conditions.runtime;
  if (source.runtime instanceof ConditionRuntime) return source.runtime;
  if (typeof source.snapshotActivationFrames === 'function') return source;
  return null;
}

function normalizeFrameEntry(entry, index) {
  const representation = entry?.representation ?? null;
  const executionLane = entry?.executionLane
    ?? (typeof representation === 'string' && representation.startsWith('wasm-function/') ? 'wasm' : 'neutral');
  return Object.freeze({
    frameId: Number.isInteger(entry?.frameId) ? entry.frameId : index + 1,
    depth: Number.isInteger(entry?.depth) ? entry.depth : index,
    block: entry?.block ?? null,
    code: entry?.code ?? null,
    languageId: entry?.languageId ?? null,
    representation,
    executionLane,
    receiver: entry?.receiver ?? null,
    selector: entry?.selector ?? null,
    definingBehavior: entry?.definingBehavior ?? null,
    ownsFrame: Boolean(entry?.ownsFrame),
    argumentCount: Number.isInteger(entry?.argumentCount) ? entry.argumentCount : 0,
    metadata: Object.freeze({...(entry?.metadata ?? {})}),
    wasmState: entry?.wasmState ?? null,
    suspensionCount: Number.isInteger(entry?.suspensionCount) ? entry.suspensionCount : 0,
    resumedCount: Number.isInteger(entry?.resumedCount) ? entry.resumedCount : 0,
    lastSuspension: entry?.lastSuspension ? Object.freeze({...entry.lastSuspension}) : null,
  });
}

function captureActivationStackReport(source = null) {
  let rawFrames = [];
  let runtime = null;
  if (Array.isArray(source)) {
    rawFrames = source;
  } else {
    runtime = resolveConditionRuntime(source);
    if (runtime) {
      const current = runtime.snapshotActivationFrames?.() ?? [];
      rawFrames = current.length > 0
        ? current
        : (runtime.lastSignalSnapshot?.()?.frames ?? []);
    } else if (source?.conditionSnapshot?.frames) {
      rawFrames = source.conditionSnapshot.frames;
    } else if (Array.isArray(source?.frames)) {
      rawFrames = source.frames;
    }
  }

  const frames = Object.freeze(rawFrames.map((entry, idx) => normalizeFrameEntry(entry, idx)));
  const languages = Object.freeze(
    [...new Set(frames.map((frame) => frame.languageId).filter((lang) => typeof lang === 'string' && lang.length > 0))]
      .sort(),
  );
  const suspendedFrameCount = frames.filter((frame) => frame.wasmState === 'suspended').length;
  const totalSuspensions = frames.reduce((sum, frame) => sum + frame.suspensionCount, 0);
  const wasmResumptions = Object.freeze(runtime?.snapshotWasmResumptions?.() ?? []);

  return Object.freeze({
    schema: ACTIVATION_STACK_REPORT_V1,
    depth: frames.length,
    frames,
    languages,
    suspendedFrameCount,
    totalSuspensions,
    wasmResumptions,
  });
}

async function resolveRestartNameFromValue(images, value) {
  if (!value || typeof value !== 'object') return String(value ?? '');
  if (value.kind === 'text') return value.value;
  if (isObjectRef(value) && images && typeof images.getObject === 'function') {
    const obj = await images.getObject(value.imageId, value.objectId);
    const spelling = obj?.slots?.['symbol-spelling'] ?? obj?.slots?.['slot-name'] ?? null;
    if (spelling?.kind === 'text') return spelling.value;
    return value.objectId;
  }
  return String(value.value ?? '');
}

async function extractRestartsFromImagePairChain(images, headValue) {
  if (!images || typeof images.getObject !== 'function' || !isObjectRef(headValue)) {
    return [];
  }
  const collected = [];
  const visited = new Set();
  let cursor = headValue;

  while (isObjectRef(cursor)) {
    const key = `${cursor.imageId}/${cursor.objectId}`;
    if (visited.has(key)) break;
    visited.add(key);

    const cell = await images.getObject(cursor.imageId, cursor.objectId);
    if (!cell || !Array.isArray(cell.indexed) || cell.indexed.length < 2) {
      break;
    }
    const pairRef = cell.indexed[0];
    const nextRef = cell.indexed[1];
    if (isObjectRef(pairRef)) {
      const pairObj = await images.getObject(pairRef.imageId, pairRef.objectId);
      if (pairObj && Array.isArray(pairObj.indexed) && pairObj.indexed.length >= 2) {
        const rawName = pairObj.indexed[0];
        const handlerTarget = pairObj.indexed[1];
        const name = await resolveRestartNameFromValue(images, rawName);
        let blockRef = isObjectRef(handlerTarget) ? handlerTarget : null;
        if (blockRef && typeof images.getBlock === 'function') {
          const maybeBlock = await images.getBlock(blockRef.imageId, blockRef.objectId);
          if (!maybeBlock) {
            const wrapperObj = await images.getObject(blockRef.imageId, blockRef.objectId);
            const innerBlock = wrapperObj?.slots?.['slot-block'] ?? wrapperObj?.slots?.block ?? null;
            if (isObjectRef(innerBlock)) blockRef = innerBlock;
          }
        }
        if (name && blockRef) {
          collected.push(Object.freeze({
            restartId: null,
            name,
            block: blockRef,
            description: null,
            source: 'image-alist',
            active: true,
          }));
        }
      }
    }
    cursor = nextRef;
  }
  return collected;
}

async function listAvailableRestarts({
  images = null,
  conditionRuntime = null,
  restartList = null,
  restartBindingRef = null,
} = {}) {
  const results = [];
  const runtime = resolveConditionRuntime(conditionRuntime);
  if (runtime) {
    const liveRestarts = runtime.snapshotRestarts?.() ?? [];
    const signalRestarts = runtime.lastSignalSnapshot?.()?.restarts ?? [];
    const sourceRestarts = liveRestarts.length > 0 ? liveRestarts : signalRestarts;
    for (const entry of sourceRestarts) {
      results.push(Object.freeze({
        restartId: entry.restartId ?? null,
        name: String(entry.name),
        block: entry.block,
        description: entry.description ?? null,
        source: 'condition-runtime',
        active: true,
      }));
    }
  }

  if (Array.isArray(restartList)) {
    for (const entry of restartList) {
      if (!entry || typeof entry !== 'object') continue;
      const name = String(entry.name ?? '');
      const block = entry.block ?? null;
      if (name && isObjectRef(block)) {
        results.push(Object.freeze({
          restartId: entry.restartId ?? null,
          name,
          block: canonicalizeValue(block),
          description: entry.description ?? null,
          source: 'explicit-list',
          active: true,
        }));
      }
    }
  } else if (isObjectRef(restartList)) {
    const chainEntries = await extractRestartsFromImagePairChain(images, restartList);
    results.push(...chainEntries);
  }

  if (isObjectRef(restartBindingRef) && images && typeof images.getObject === 'function') {
    const bindingObj = await images.getObject(restartBindingRef.imageId, restartBindingRef.objectId);
    const bindingValue = bindingObj?.slots?.['global-binding-value']
      ?? bindingObj?.slots?.['slot-value']
      ?? bindingObj?.slots?.value
      ?? null;
    if (isObjectRef(bindingValue)) {
      const chainEntries = await extractRestartsFromImagePairChain(images, bindingValue);
      results.push(...chainEntries);
    }
  }

  return Object.freeze(results);
}

async function captureConditionAndStackReport({
  conditionRuntime = null,
  condition = null,
  error = null,
  images = null,
  restartList = null,
  restartBindingRef = null,
} = {}) {
  const runtime = resolveConditionRuntime(conditionRuntime);
  const snapshot = error?.conditionSnapshot ?? runtime?.lastSignalSnapshot?.() ?? null;

  const resolvedCondition = condition ?? snapshot?.condition ?? null;
  const description = snapshot?.description
    ?? error?.description
    ?? (typeof error?.message === 'string' ? error.message : 'condition');
  const handled = snapshot ? Boolean(snapshot.handled) : false;
  const handlerScopeId = snapshot?.handlerScopeId ?? null;

  const stackReport = snapshot?.frames
    ? captureActivationStackReport(snapshot.frames)
    : captureActivationStackReport(runtime);

  const scopes = Object.freeze(
    snapshot?.scopes ?? runtime?.snapshotScopes?.() ?? [],
  );
  const occurrences = Object.freeze(
    runtime?.snapshotOccurrences?.() ?? [],
  );
  const restarts = await listAvailableRestarts({
    images,
    conditionRuntime: runtime,
    restartList,
    restartBindingRef,
  });

  return Object.freeze({
    schema: CONDITION_INSPECTION_REPORT_V1,
    handled,
    condition: resolvedCondition ? canonicalizeValue(resolvedCondition) : null,
    description,
    errorName: error?.name ?? null,
    handlerScopeId,
    stackReport,
    scopes,
    occurrences,
    restarts,
  });
}

async function invokeCapturedRestart({
  executor,
  invocations,
  images = null,
  conditionRuntime = null,
  restart,
  restarts = [],
  arguments: args = [],
  authority = null,
} = {}) {
  if (!executor || typeof executor.execute !== 'function') {
    throw new TypeError('invokeCapturedRestart requires an ActivationExecutor');
  }
  if (!invocations || typeof invocations.prepareActivation !== 'function') {
    throw new TypeError('invokeCapturedRestart requires an InvocationService');
  }

  let targetRestart = null;
  if (typeof restart === 'string') {
    const available = restarts.length > 0
      ? restarts
      : await listAvailableRestarts({images, conditionRuntime});
    targetRestart = available.find((entry) => entry.name === restart) ?? null;
    if (!targetRestart) {
      throw new TypeError(`restart not found: ${restart}`);
    }
  } else if (restart && typeof restart === 'object' && isObjectRef(restart.block)) {
    targetRestart = restart;
  } else if (isObjectRef(restart)) {
    targetRestart = {name: 'anonymous', block: restart};
  } else {
    throw new TypeError('invokeCapturedRestart requires a restart name, descriptor, or Block ref');
  }

  const normalizedArgs = Array.isArray(args) ? args.map((arg) => canonicalizeValue(arg)) : [];
  const prepareOpts = {
    block: canonicalizeValue(targetRestart.block),
    arguments: normalizedArgs,
  };
  if (images) prepareOpts.images = images;
  const activation = await invocations.prepareActivation(prepareOpts);
  const runtime = resolveConditionRuntime(conditionRuntime);

  return await executor.execute(activation, {
    authority,
    ...(runtime ? {conditionRuntime: runtime} : {}),
  });
}

function compareCanonicalResources(left, right) {
  if (left.imageId !== right.imageId) return left.imageId.localeCompare(right.imageId);
  return left.objectId.localeCompare(right.objectId);
}

async function authorizedInspectExecutionCondition({
  images = null,
  executor,
  invocations = null,
  activation,
  authority = null,
  restartBindingRef = null,
  signal = null,
  require,
} = {}) {
  if (typeof require !== 'function') {
    throw new TypeError('authorizedInspectExecutionCondition requires a require(demand) function');
  }
  if (!executor || typeof executor.execute !== 'function') {
    throw new TypeError('authorizedInspectExecutionCondition requires an ActivationExecutor');
  }
  assertActivationRequest(activation);

  const demandedTargets = [
    {imageId: activation.block.imageId, objectId: activation.block.objectId},
  ];
  if (restartBindingRef !== null) {
    if (!isObjectRef(restartBindingRef)) {
      throw new TypeError('restartBindingRef must be an unpinned ObjectRef or null');
    }
    demandedTargets.push({imageId: restartBindingRef.imageId, objectId: restartBindingRef.objectId});
  }
  demandedTargets.sort(compareCanonicalResources);
  const seenResources = new Set();
  for (const target of demandedTargets) {
    const resource = objectResource(target.imageId, target.objectId);
    if (seenResources.has(resource)) continue;
    seenResources.add(resource);
    require({
      operation: OBJECT_READ_OPERATION,
      resource,
    });
  }

  const conditionRuntime = new ConditionRuntime();
  try {
    const value = await executor.execute(activation, {
      authority,
      conditionRuntime,
      signal,
    });
    const lastSnapshot = conditionRuntime.lastSignalSnapshot();
    const conditionReport = lastSnapshot
      ? await captureConditionAndStackReport({
        conditionRuntime,
        images: images ?? executor.images,
        restartBindingRef,
      })
      : null;
    return Object.freeze({
      status: 'completed',
      value,
      errorName: null,
      description: null,
      stackReport: captureActivationStackReport(conditionRuntime),
      conditionReport,
      invocations,
    });
  } catch (error) {
    if (error instanceof ActivationCancelledError) {
      return Object.freeze({
        status: 'cancelled',
        value: null,
        errorName: 'ActivationCancelledError',
        description: error.message,
        stackReport: captureActivationStackReport(error.frames?.length ? error.frames : conditionRuntime),
        conditionReport: null,
        invocations,
      });
    }
    if (error instanceof UnhandledConditionError || error?.conditionSnapshot) {
      const conditionReport = await captureConditionAndStackReport({
        conditionRuntime,
        error,
        images: images ?? executor.images,
        restartBindingRef,
      });
      return Object.freeze({
        status: 'unhandled-condition',
        value: null,
        errorName: error.name ?? 'UnhandledConditionError',
        description: conditionReport.description,
        stackReport: conditionReport.stackReport,
        conditionReport,
        invocations,
      });
    }
    throw error;
  }
}

export {
  ACTIVATION_STACK_REPORT_V1,
  CONDITION_INSPECTION_REPORT_V1,
  authorizedInspectExecutionCondition,
  captureActivationStackReport,
  captureConditionAndStackReport,
  invokeCapturedRestart,
  listAvailableRestarts,
};

class ExecutorRegistrationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ExecutorRegistrationError';
  }
}

class ExecutorNotFoundError extends Error {
  constructor(representation) {
    super(`no executor registered for representation: ${representation}`);
    this.name = 'ExecutorNotFoundError';
    this.representation = representation;
  }
}

function normalizeRepresentation(value) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError('code representation must be a non-empty string');
  }
  return value;
}

function assertExecutor(executor) {
  if (!executor || typeof executor !== 'object' || typeof executor.execute !== 'function') {
    throw new TypeError('code executor must implement execute(input, context)');
  }
  return executor;
}

class CodeExecutorRegistry {
  constructor() {
    this.executors = new Map();
  }

  register(representation, executor) {
    const key = normalizeRepresentation(representation);
    if (this.executors.has(key)) {
      throw new ExecutorRegistrationError(`executor already registered: ${key}`);
    }
    this.executors.set(key, assertExecutor(executor));
    return executor;
  }

  get(representation) {
    const key = normalizeRepresentation(representation);
    const executor = this.executors.get(key);
    if (!executor) throw new ExecutorNotFoundError(key);
    return executor;
  }

  has(representation) {
    return this.executors.has(normalizeRepresentation(representation));
  }

  list() {
    return [...this.executors.keys()].sort();
  }
}

export {
  CodeExecutorRegistry,
  ExecutorNotFoundError,
  ExecutorRegistrationError,
  normalizeRepresentation,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {TupleMap} from '../support/tuple-map.js';
import {canonicalizeValue, objectRef} from '../value/index.js';
import {isTransientObjectId, transientObjectId} from '../value/transient-ref.js';
import {ConditionRuntime} from './conditions.js';

// A closure instance whose arena is gone. Distinct from "block not found" on purpose: ADR 0052
// decision 5c makes this rigorous, because a reserved id can never name a durable record, so its
// absence from the arena means expiry rather than a missing or corrupt record.
class ExpiredClosureInstanceError extends TypeError {
  constructor(imageId, objectId) {
    super(`closure instance ${imageId}/${objectId} has expired; its execution has ended`);
    this.name = 'ExpiredClosureInstanceError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

// The lane-neutral lexical frame and cell substrate, per ADR 0043.
//
// This deliberately lives in the common execution layer rather than inside an executor. Two
// implementations of mutable lexical state — one for the neutral lane, one for WASM — is the
// architecture to avoid: the semantics would become lane-dependent, which ADR 0043 decision 10
// forbids. Both lanes consume these operations instead.
//
// A cell is identified by (lexical frame, static binding ID), never by binding ID alone. Binding
// IDs are static slot identity: the compiler derives them from a path defaulting to 'root', so
// `root:temporary:0` names a slot in the code, and two activations of that code — including two
// recursive activations — deliberately share it while needing distinct variables.
//
// Frame *identity* and frame *lifetime* are separate, and conflating them is the easy mistake:
//
//   different lexical invocation   ->  different frame
//   a frame stays reachable after its own call returns, if a closure still holds one of its cells
//   nothing captured it            ->  it goes away when its call returns
//   the root execution ends        ->  the arena dies with it
//
// So a factory that returns a counter closure keeps working for the rest of that execution:
//
//   make := [ | n | n := 0. [ n := n + 1 ] ].
//   counter := make value.  counter value.  counter value.   "2"
//
// The closure has escaped its declaring frame but not the execution that owns the arena. Only a
// later, independent execution meeting a durable {cell: true} capture raises.

// A host sentinel, never a canonical Value and never observable as one. When the object system
// arrives, a temporary's initial contents become the `nil` object ref and nothing here changes.
const UNBOUND = Symbol('lagrange.lexical.unbound');

class UnboundBindingError extends TypeError {
  constructor(name, id) {
    super(`lexical binding ${name ?? id} is unbound; it has no value until it is assigned`);
    this.name = 'UnboundBindingError';
    this.bindingId = id;
  }
}

// Raised when a closure that depends on a live cell is invoked without the execution that owns
// that cell. ADR 0043 decision 5: this case is unsupported, not silently reset to whatever the
// durable snapshot happened to hold.
class EscapingMutableClosureError extends TypeError {
  constructor(id, name) {
    super(
      `closure depends on the live lexical cell ${name ?? id}, which belonged to a finished execution; `
      + 'persistent mutable captured state needs an explicit survival contract',
    );
    this.name = 'EscapingMutableClosureError';
    this.bindingId = id;
  }
}

// Raised when a synchronous cell operation names a binding that is not a cell of this activation.
// The cell-only accessors deliberately do not fall back to the durable environment: that lookup is
// asynchronous, so a fallback would be unusable from a WASM import anyway, and offering one would
// reopen the snapshot channel that ADR 0043 decision 5 closes.
class MissingLexicalCellError extends TypeError {
  constructor(id) {
    super(`lexical binding ${id} is not a cell of this activation`);
    this.name = 'MissingLexicalCellError';
    this.bindingId = id;
  }
}

class LexicalCell {
  #id;
  #name;
  #contents = UNBOUND;

  // `initialContents` is how ADR 0044 decision 8 arrives: in a bootstrapped image a declared
  // temporary starts holding that image's `nil` ref, and elsewhere it starts UNBOUND exactly as
  // before. A cell holding nil is an ordinary bound cell — nothing downstream distinguishes it,
  // which is why this needs no new WASM ABI.
  constructor(id, name, initialContents = UNBOUND) {
    this.#id = id;
    this.#name = name ?? null;
    this.#contents = initialContents === UNBOUND ? UNBOUND : canonicalizeValue(initialContents);
  }

  get id() { return this.#id; }
  get name() { return this.#name; }
  get bound() { return this.#contents !== UNBOUND; }

  read() {
    if (this.#contents === UNBOUND) throw new UnboundBindingError(this.#name, this.#id);
    return this.#contents;
  }

  // Assignment is an expression, so the written value is returned.
  write(value) {
    this.#contents = canonicalizeValue(value);
    return this.#contents;
  }

  // Deliberately no snapshot() method. Persisting a mutable capture always writes
  // {name, cell: true} regardless of what the cell currently holds, so that no value is
  // reachable in the durable record for a later invocation to silently restart from. A snapshot
  // accessor would exist only to defeat that, so it does not exist.
}

// One lexical activation's cells. Opaque: nothing outside resolves a cell except through here.
class LexicalFrame {
  #cells = new Map();

  declare(id, name, initialContents = UNBOUND) {
    if (!this.#cells.has(id)) this.#cells.set(id, new LexicalCell(id, name, initialContents));
    return this.#cells.get(id);
  }

  own(id) {
    return this.#cells.get(id) ?? null;
  }
}

// Execution-scoped. What the arena actually owns is the closure-to-cell associations: those must
// outlive the activation that created the closure, and must not outlive the execution — which is
// what makes cells activation state under ADR 0041 rather than something that survives by accident.
//
// It deliberately does *not* keep a list of frames. A frame is reachable while its activation runs,
// and afterwards only through cells some closure captured, so an unwatched frame becomes collectable
// as soon as its call returns. Holding every frame for the execution's duration would retain one
// Map per send in a long loop while changing no semantics.
class LexicalCellArena {
  #closureCells = new Map();

  allocateFrame() {
    return new LexicalFrame();
  }

  // The transient association between a closure Block created in this execution and the cells it
  // captured. The durable environment cannot express cell identity, so this is what lets a
  // same-execution closure resolve the *declaring* frame's cell rather than a snapshot.
  //
  // Nested by imageId then objectId, because a Block ref is a two-part identity and flattening it
  // into one string is not injective: object ids are arbitrary non-empty text, so any separator can
  // itself appear inside a part. `a<sep>b` + `c` and `a` + `b<sep>c` would then collide and one
  // closure would resolve another closure's cells. A tuple lookup cannot be got wrong this way.
  associate(blockRef, cells) {
    if (cells.size === 0) return;
    let byObject = this.#closureCells.get(blockRef.imageId);
    if (!byObject) {
      byObject = new Map();
      this.#closureCells.set(blockRef.imageId, byObject);
    }
    byObject.set(blockRef.objectId, new Map(cells));
  }

  capturedCells(blockRef) {
    return this.#closureCells.get(blockRef.imageId)?.get(blockRef.objectId) ?? null;
  }

  // One lexical activation's view: its own fresh frame, plus the cells the Block being activated
  // captured when some earlier activation in this same execution created it.
  activationCells(blockRef) {
    return new ActivationCells(this, this.allocateFrame(), this.capturedCells(blockRef));
  }

  // ADR 0050 decision 10a. The frame in force where a closure was created, so activating it later in
  // the *same* execution restores lexical `self`. Deliberately here rather than in a durable record:
  // a persisted defining Behavior would be forgeable data, which is the vector self-only exists to
  // close. Dying with the arena is the feature.
  associateFrame(blockRef, frame) {
    this.frames ??= new TupleMap(2);
    this.frames.set([blockRef.imageId, blockRef.objectId], frame);
  }

  frameFor(blockRef) {
    return this.frames?.get([blockRef.imageId, blockRef.objectId]) ?? null;
  }

  // ADR 0052 decision 5a. Closure instances that have not escaped live here rather than in the
  // graph, keyed by the same instance ref the cells and frame above are keyed by — one keying
  // scheme, so an instance's cells, frame and definition are all reached the same way.
  //
  // The stored shapes deliberately mirror the durable Block and LexicalEnvironment records field for
  // field. Promotion is then a copy rather than a translation, which is what keeps a promoted
  // closure the same representation as one written eagerly.
  #instances = new TupleMap(2);

  #mint(imageId, kind, record) {
    const objectId = transientObjectId(`${kind}/${this.#nextInstance += 1}/${this.#nonce}`);
    this.#instances.set([imageId, objectId], record);
    return objectRef(imageId, objectId);
  }

  #nextInstance = 0;

  // Per-arena, so a transient id minted by one execution can never be mistaken for one minted by
  // another — including after an arena is gone, where the id must read as expired rather than as
  // some other execution's live instance.
  #nonce = randomUUID();

  // The instance's image is its prototype's, so dispatch-image behaviour needs no special case for
  // a transient receiver (ADR 0044 decision 5a, ADR 0051 decision 3).
  mintClosureBlock(imageId, {code, environment = null, metadata = {}}) {
    return this.#mint(imageId, 'block', Object.freeze({
      kind: 'block', code, environment, metadata: Object.freeze({...metadata}),
    }));
  }

  mintClosureEnvironment(imageId, {bindings, parent = null}) {
    return this.#mint(imageId, 'environment', Object.freeze({
      kind: 'lexical-environment', bindings: Object.freeze({...bindings}), parent,
    }));
  }

  // ADR 0060 decision 3. An object allocated inside this execution begins here rather than in the
  // durable store: `basicNew` and condition allocation mint into the arena, and the object becomes
  // durable only if a reference crosses a durability boundary. The record mirrors the durable
  // object record field for field — shape, behavior, slots, indexed, metadata — so promotion is a
  // copy rather than a translation, exactly as ADR 0052 made it for closures.
  mintObject(imageId, {shape, behavior, slots = {}, indexed = null, metadata = {}}) {
    return this.#mint(imageId, 'object', Object.freeze({
      kind: 'object',
      shape,
      behavior,
      slots: Object.freeze({...slots}),
      // A non-indexed Shape omits the property entirely, preserving the durable record form.
      ...(indexed === null ? {} : {indexed: Object.freeze([...indexed])}),
      metadata: Object.freeze({...metadata}),
    }));
  }

  transientRecord(imageId, objectId) {
    return this.#instances.get([imageId, objectId]) ?? null;
  }

  // ADR 0060: a slot or indexed write to an object that has not escaped stays in the arena. The
  // record is replaced whole (slots and indexed are immutable snapshots), mirroring the durable
  // whole-record rewrite, so a later read in the same execution sees the new state and a promotion
  // that follows publishes the latest. There is no version to CAS on — the record is
  // execution-local, so the only writer is this execution itself.
  mutateTransientObject(imageId, objectId, {slots = null, indexed = null} = {}) {
    const key = [imageId, objectId];
    const record = this.#instances.get(key);
    if (!record) throw new ExpiredClosureInstanceError(imageId, objectId);
    if (record.kind !== 'object') {
      throw new TypeError(`only a transient object can be mutated: ${imageId}/${objectId}`);
    }
    this.#instances.set(key, Object.freeze({
      ...record,
      slots: slots === null ? record.slots : Object.freeze({...slots}),
      ...(indexed === null
        ? (Object.hasOwn(record, 'indexed') ? {indexed: record.indexed} : {})
        : {indexed: Object.freeze([...indexed])}),
    }));
  }

  transientEntries() {
    return this.#instances.entries();
  }

  // ADR 0052 decision 7a. Lives on the arena so promotion is idempotent for the whole execution
  // rather than per boundary: a closure written into two slots must be one closure both times.
  #promotionMemo = new TupleMap(2);

  promotionMemo() {
    return this.#promotionMemo;
  }

  // ADR 0054. Kept on the arena because its lifetime is the arena's: a handler established in this
  // execution must not be findable from a later one, for the same reason a defining frame is not.
  #conditions = null;

  conditionRuntime() {
    this.#conditions ??= new ConditionRuntime();
    return this.#conditions;
  }

  #imagesViews = new WeakMap();

  imagesViewFor(images) {
    return this.#imagesViews.get(images) ?? null;
  }

  cacheImagesView(images, view) {
    this.#imagesViews.set(images, view);
    return view;
  }

  #temporaryInitializers = new TupleMap(2);

  temporaryContents(dispatchImage, languageId) {
    return this.#temporaryInitializers.get([String(dispatchImage ?? ''), String(languageId ?? '')]);
  }

  cacheTemporaryContents(dispatchImage, languageId, value) {
    this.#temporaryInitializers.set([String(dispatchImage ?? ''), String(languageId ?? '')], value);
    return value;
  }
}

// What an executor is given. Deliberately narrow: declare a slot, resolve one, associate a new
// closure. No frame, no arena and no cell contents leak through it, so both execution lanes share
// one lexical-state model instead of each growing its own.
class ActivationCells {
  #arena;
  #frame;
  #captured;

  constructor(arena, frame, captured) {
    this.#arena = arena;
    this.#frame = frame;
    this.#captured = captured;
  }

  // One place, before the neutral and WASM lanes diverge. Four executors independently learning
  // about `nil` is the lane-dependent-semantics mistake ADR 0043 decision 10 forbids.
  declare(temporaries, initialContents = UNBOUND) {
    for (const {id, name} of temporaries) this.#frame.declare(id, name, initialContents);
  }

  // This activation's own slot first, then a captured cell — never the other way round, so a
  // recursive activation shadows the identically-named static slot it captured.
  resolve(id) {
    return this.#frame.own(id) ?? this.#captured?.get(id) ?? null;
  }

  associate(blockRef, cells) {
    this.#arena.associate(blockRef, cells);
  }
}



// ADR 0052 decision 5a: Block resolution is arena-first, then durable.
//
// Delivered as a view over the images service rather than as a new parameter on every reader,
// because the readers that must see a transient instance — `prepareActivation`, the language
// dispatcher's Block recognition, binding lookup — all already take an images service. A view keeps
// one resolution rule in one place instead of three call sites remembering to check the arena.
//
// The view is execution context in exactly the way `dispatchImage` is: it is built per execution,
// it reaches no durable record, and it dies with the arena.
function arenaImagesView(images, arena) {
  if (!arena) return images;
  const cachedView = arena.imagesViewFor?.(images);
  if (cachedView) return cachedView;
  const view = Object.create(images);
  const immutableDurable = new TupleMap(3);
  const durableObjects = new TupleMap(2);
  const protocols = new TupleMap(2);
  const readImmutableDurable = async (kind, imageId, objectId, durable) => {
    const key = [kind, imageId, objectId];
    const hit = immutableDurable.get(key);
    if (hit) return hit;
    const loaded = await durable.call(images, imageId, objectId);
    if (loaded) immutableDurable.set(key, loaded);
    return loaded;
  };
  view.cachedProtocol = (protocol, imageId) => protocols.get([protocol, imageId]) ?? null;
  view.cacheProtocol = (protocol, imageId, value) => {
    protocols.set([protocol, imageId], value);
    return value;
  };
  view.invalidateObject = (imageId, objectId) => {
    durableObjects.delete([imageId, objectId]);
  };
  // Durable fallback is never reached for a reserved id, because decision 5b forbids a durable
  // record from taking one. A reserved id absent from this arena is therefore an *expired*
  // instance, which is a lifetime error rather than a missing record — and saying so is the
  // difference between "your closure outlived its execution" and "your image is corrupt".
  //
  // One nuance ADR 0060 forces: the dispatcher asks *every* object receiver "are you a Block?"
  // first (ADR 0044's Block-personality check), so a transient *object* is looked up as a Block on
  // every send to it. That is a negative answer, not an expiry — the id is live in the arena as a
  // different kind, and only a reserved id present *nowhere* in the arena has outlived its
  // execution. So "not this kind" answers null and lets the durable-negative fall through, while
  // "not in the arena at all" is the lifetime error.
  const resolve = async (imageId, objectId, kind, durable, {immutable = false} = {}) => {
    const record = arena.transientRecord(imageId, objectId);
    if (record) return record.kind === kind ? record : null;
    if (isTransientObjectId(objectId)) {
      throw new ExpiredClosureInstanceError(imageId, objectId);
    }
    if (immutable) return await readImmutableDurable(kind, imageId, objectId, durable);
    return await durable.call(images, imageId, objectId);
  };
  view.getBlock = (imageId, objectId) =>
    resolve(imageId, objectId, 'block', images.getBlock, {immutable: true});
  view.getLexicalEnvironment = (imageId, objectId) =>
    resolve(imageId, objectId, 'lexical-environment', images.getLexicalEnvironment, {immutable: true});
  if (typeof images.putLexicalEnvironment === 'function') {
    view.putLexicalEnvironment = async (imageId, input, options) => {
      if (typeof input?.id === 'string') immutableDurable.delete(['lexical-environment', imageId, input.id]);
      const saved = await images.putLexicalEnvironment(imageId, input, options);
      if (saved?.id) immutableDurable.set(['lexical-environment', imageId, saved.id], saved);
      return saved;
    };
  }
  if (typeof images.getCodeArtifact === 'function') {
    view.getCodeArtifact = (imageId, objectId) =>
      readImmutableDurable('code-artifact', imageId, objectId, images.getCodeArtifact);
  }
  if (typeof images.getShape === 'function') {
    view.getShape = (imageId, objectId) =>
      readImmutableDurable('shape', imageId, objectId, images.getShape);
  }
  // ADR 0060: object reads resolve arena-first, exactly as Block reads already do — so a primitive
  // holding a transient receiver (a `basicNew` result, an unhandled condition still in its
  // execution) sees its state without the object ever becoming durable. The durable fallback is
  // never reached for a reserved id, for the same reason as above.
  // A transient record's id is its arena key rather than a stored field, but every reader and
  // writer below the view addresses a record by `record.id` — the whole-record rewrites in the
  // slot, indexed and Dictionary primitives all rebuild from it. Surface the id on the record the
  // view answers so those paths work unchanged against a transient object; the durable record
  // already carries its own id.
  view.getObject = async (imageId, objectId) => {
    const record = arena.transientRecord(imageId, objectId);
    if (record) {
      if (record.kind !== 'object') return null;
      return Object.freeze({...record, id: objectId});
    }
    if (isTransientObjectId(objectId)) throw new ExpiredClosureInstanceError(imageId, objectId);
    const key = [imageId, objectId];
    const cached = durableObjects.get(key);
    if (cached) return cached;
    const loaded = await images.getObject(imageId, objectId);
    if (loaded) durableObjects.set(key, loaded);
    return loaded;
  };
  // A write naming a reserved id is a write to an object in this arena. `basicNew`'s whole point is
  // that the id is minted transient and the record lives here — so the write updates the arena.
  // But ADR 0060 decision 4 makes the object *one object across promotion*: if this transient id is
  // already registered as promoted (the arena's memo, keyed exactly as the promoter keys it), the
  // mutation must also reach the durable record, or the durable copy goes stale the moment Smalltalk
  // code mutates an escaped object — which a cyclic structure does while its own promotion is still
  // resolving. The durable id is derived, so the write converges on the same identity; the arena is
  // updated too, so the rest of this execution keeps reading the new state. A durable id that is
  // not transient falls through to the durable store unchanged.
  view.putObject = async (imageId, record, options = {}) => {
    if (isTransientObjectId(record?.id)) {
      const existing = arena.transientRecord(imageId, record.id);
      if (!existing) throw new ExpiredClosureInstanceError(imageId, record.id);
      arena.mutateTransientObject(imageId, record.id, {
        slots: record.slots,
        indexed: Object.hasOwn(record, 'indexed') ? record.indexed : null,
      });
      const promoted = arena.promotionMemo().get([imageId, record.id]);
      if (promoted) {
        // The durable id is derived from the transient one by the promoter's rule. The durable
        // record already exists (promotion wrote it), so this is a mutation of it. A value written
        // now may itself be transient — a backing Array allocated *after* its OrderedCollection
        // escaped — and writing that ref unpromoted would dangle, so the new state is promoted
        // through the same central operation first. Within one execution the only writer is this
        // execution, so the read-then-write CAS cannot race here.
        const durableId = promoted.ref.objectId;
        durableObjects.delete([imageId, durableId]);
        const current = await images.getObject(imageId, durableId);
        if (current) {
          const promoteValue = arena.postPromotionPromoter
            ?? ((v) => v);
          const slots = {};
          for (const [slotId, value] of Object.entries(record.slots)) {
            slots[slotId] = await promoteValue(value);
          }
          const saved = await images.putObject(imageId, {
            id: durableId,
            shape: record.shape,
            behavior: record.behavior,
            slots,
            ...(Object.hasOwn(record, 'indexed')
              ? {indexed: await Promise.all(record.indexed.map(promoteValue))}
              : {}),
            metadata: record.metadata,
          }, {expectedVersion: current._version});
          if (saved?.id) durableObjects.set([imageId, saved.id], saved);
        }
      }
      return record;
    }
    if (typeof record?.id === 'string') {
      protocols.delete([record.id, imageId]);
      durableObjects.delete([imageId, record.id]);
    }
    const saved = await images.putObject(imageId, record, options);
    if (saved?.id) durableObjects.set([imageId, saved.id], saved);
    return saved;
  };
  return arena.cacheImagesView ? arena.cacheImagesView(images, view) : view;
}

export {
  ActivationCells,
  EscapingMutableClosureError,
  ExpiredClosureInstanceError,
  MissingLexicalCellError,
  LexicalCell,
  LexicalCellArena,
  LexicalFrame,
  UNBOUND,
  UnboundBindingError,
  arenaImagesView,
};

import {TupleSet} from '../support/tuple-map.js';
import {
  canonicalizeValue,
  isObjectRef,
  isReference,
} from '../value/index.js';
import {normalizeMetadata} from '../object/model.js';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeObjectRef(value, label) {
  const normalized = canonicalizeValue(value);
  if (!isObjectRef(normalized)) {
    throw new TypeError(`${label} must be an unpinned object ref`);
  }
  return normalized;
}

function normalizeReferenceList(values, label) {
  if (!Array.isArray(values)) throw new TypeError(`${label} must be an array`);
  return Object.freeze(values.map((value, index) => {
    const normalized = canonicalizeValue(value);
    if (!isReference(normalized)) throw new TypeError(`${label}[${index}] must be a reference`);
    return normalized;
  }));
}

// The materialization-relative path at which an artifact's bytes are laid down when a
// consumer materializes it (a Cargo source's `src/main.rs`, a Cuis image's `Mixed.image`).
// This is SEMANTIC CONTENT, not provenance: two artifacts with identical bytes at different
// logical paths are different build/runtime inputs, so the CodeArtifact owner keeps it as a
// canonical field that enters contentIdentity — never in `metadata`, which ADR 0074 defines as
// stripped, non-identity provenance. Consumers (the Cargo and Cuis providers) read it here and
// apply their own stricter rules (a Cuis name is a single-segment path with a required
// extension; a Cargo path may nest). Absent is `null`.
function normalizeLogicalPath(value, label = 'code artifact logicalPath') {
  if (value === null || value === undefined) return null;
  const path = requiredText(value, label);
  if (path.includes('\\') || path.includes('\0')) {
    throw new TypeError(`${label} must be a portable path without backslashes or NUL`);
  }
  if (path.startsWith('/')) throw new TypeError(`${label} must be relative, not absolute`);
  const segments = path.split('/');
  if (segments.some((segment) => segment.length === 0 || segment === '.' || segment === '..')) {
    throw new TypeError(`${label} must not contain empty, . or .. segments`);
  }
  return path;
}

function normalizeArtifactDependencies(values, {imageId = null, artifactId = null} = {}) {
  if (!Array.isArray(values)) throw new TypeError('code artifact dependencies must be an array');
  const seen = new TupleSet(3);
  return Object.freeze(values.map((dependency, index) => {
    exactKeys(dependency, ['artifact', 'role'], `code artifact dependency ${index}`);
    const role = requiredText(dependency.role, `code artifact dependency ${index} role`);
    const artifact = normalizeObjectRef(dependency.artifact, `code artifact dependency ${index} artifact`);
    if (imageId !== null && artifactId !== null && artifact.imageId === imageId && artifact.objectId === artifactId) {
      throw new TypeError('code artifact cannot depend on itself');
    }
    const key = [role, artifact.imageId, artifact.objectId];
    if (seen.has(key)) throw new TypeError(`duplicate code artifact dependency: ${role} ${artifact.imageId}/${artifact.objectId}`);
    seen.add(key);
    return Object.freeze({role, artifact});
  }));
}

function createCodeArtifactRecord({
  id,
  imageId,
  languageId = null,
  representation,
  content,
  logicalPath = null,
  dependencies = [],
  derivedFrom = [],
  metadata = {},
  updatedAt = null,
}) {
  const recordId = requiredText(id, 'code artifact id');
  const recordImageId = requiredText(imageId, 'code artifact imageId');
  return Object.freeze({
    kind: 'code-artifact',
    id: recordId,
    imageId: recordImageId,
    languageId: languageId === null ? null : requiredText(languageId, 'code artifact languageId'),
    representation: requiredText(representation, 'code artifact representation'),
    content: canonicalizeValue(content),
    logicalPath: normalizeLogicalPath(logicalPath),
    dependencies: normalizeArtifactDependencies(dependencies, {imageId: recordImageId, artifactId: recordId}),
    derivedFrom: normalizeReferenceList(derivedFrom, 'code artifact derivedFrom'),
    metadata: normalizeMetadata(metadata, 'code artifact metadata'),
    updatedAt,
  });
}

function assertCodeArtifactRecord(record) {
  if (!record || record.kind !== 'code-artifact') throw new TypeError('record is not a code artifact');
  createCodeArtifactRecord(record);
  return record;
}

function normalizeBindings(bindings) {
  if (!bindings || typeof bindings !== 'object' || Array.isArray(bindings)) {
    throw new TypeError('lexical environment bindings must be keyed by stable binding id');
  }
  const normalized = {};
  for (const [bindingId, binding] of Object.entries(bindings)) {
    requiredText(bindingId, 'binding id');
    if (!binding || typeof binding !== 'object' || Array.isArray(binding)) {
      throw new TypeError(`binding ${bindingId} must be an object`);
    }
    if (binding.name !== null && typeof binding.name !== 'string') {
      throw new TypeError(`binding ${bindingId} name must be text or null`);
    }
    // Three capture dispositions, per ADR 0043. `bound` and `unbound` describe a durable
    // snapshot; `cell` says no durable snapshot is semantically usable and this binding requires
    // its live execution cell. That is what makes a later invocation fail correctly: there is no
    // old value available to helpfully reset from.
    const keys = Object.keys(binding).sort();
    if (keys.length === 2 && keys[0] === 'name' && keys[1] === 'value') {
      normalized[bindingId] = Object.freeze({
        name: binding.name,
        value: canonicalizeValue(binding.value),
      });
    } else if (keys.length === 2 && keys[0] === 'name' && keys[1] === 'unbound') {
      if (binding.unbound !== true) throw new TypeError(`binding ${bindingId} unbound must be true`);
      normalized[bindingId] = Object.freeze({name: binding.name, unbound: true});
    } else if (keys.length === 2 && keys[0] === 'cell' && keys[1] === 'name') {
      if (binding.cell !== true) throw new TypeError(`binding ${bindingId} cell must be true`);
      normalized[bindingId] = Object.freeze({name: binding.name, cell: true});
    } else {
      throw new TypeError(
        `binding ${bindingId} must contain exactly name and one of value, unbound, cell`,
      );
    }
  }
  return Object.freeze(normalized);
}

function createLexicalEnvironmentRecord({
  id,
  imageId,
  parent = null,
  bindings = {},
  metadata = {},
  updatedAt = null,
}) {
  const recordId = requiredText(id, 'lexical environment id');
  const recordImageId = requiredText(imageId, 'lexical environment imageId');
  const normalizedParent = parent === null ? null : normalizeObjectRef(parent, 'lexical environment parent');
  if (normalizedParent && normalizedParent.imageId === recordImageId && normalizedParent.objectId === recordId) {
    throw new TypeError('lexical environment cannot be its own parent');
  }
  return Object.freeze({
    kind: 'lexical-environment',
    id: recordId,
    imageId: recordImageId,
    parent: normalizedParent,
    bindings: normalizeBindings(bindings),
    metadata: normalizeMetadata(metadata, 'lexical environment metadata'),
    updatedAt,
  });
}

function assertLexicalEnvironmentRecord(record) {
  if (!record || record.kind !== 'lexical-environment') throw new TypeError('record is not a lexical environment');
  createLexicalEnvironmentRecord(record);
  return record;
}

function sameRef(left, right) {
  if (left === null || right === null) return left === right;
  return left.kind === right.kind && left.imageId === right.imageId && left.objectId === right.objectId;
}

function assertLexicalEnvironmentLayoutCompatible(current, next) {
  assertLexicalEnvironmentRecord(current);
  assertLexicalEnvironmentRecord(next);
  if (!sameRef(current.parent, next.parent)) {
    throw new TypeError('lexical environment parent is part of its stable layout');
  }
  const currentIds = Object.keys(current.bindings).sort();
  const nextIds = Object.keys(next.bindings).sort();
  if (currentIds.length !== nextIds.length || currentIds.some((id, index) => id !== nextIds[index])) {
    throw new TypeError('lexical environment binding ids are part of its stable layout');
  }
  return next;
}

function createBlockRecord({
  id,
  imageId,
  code,
  environment = null,
  metadata = {},
  updatedAt = null,
}) {
  return Object.freeze({
    kind: 'block',
    id: requiredText(id, 'block id'),
    imageId: requiredText(imageId, 'block imageId'),
    code: normalizeObjectRef(code, 'block code'),
    environment: environment === null ? null : normalizeObjectRef(environment, 'block environment'),
    metadata: normalizeMetadata(metadata, 'block metadata'),
    updatedAt,
  });
}

function assertBlockRecord(record) {
  if (!record || record.kind !== 'block') throw new TypeError('record is not a block');
  createBlockRecord(record);
  return record;
}

export {
  assertBlockRecord,
  assertCodeArtifactRecord,
  assertLexicalEnvironmentLayoutCompatible,
  assertLexicalEnvironmentRecord,
  createBlockRecord,
  createCodeArtifactRecord,
  normalizeLogicalPath,
  createLexicalEnvironmentRecord,
  normalizeArtifactDependencies,
};

import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  integerValue,
} from '../value/index.js';

const NEUTRAL_EXPRESSION_V0 = 'neutral-expression/v0';
const MAX_EXPRESSION_DEPTH = 256;

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function nonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function parseProgram(code) {
  if (code.content?.kind !== VALUE_KIND.TEXT) {
    throw new TypeError(`${NEUTRAL_EXPRESSION_V0} code content must be a text Value`);
  }
  let program;
  try {
    program = JSON.parse(code.content.value);
  } catch (error) {
    throw new TypeError(`${NEUTRAL_EXPRESSION_V0} code content must contain valid JSON`, {cause: error});
  }
  exactKeys(program, ['parameters', 'body'], 'neutral expression program');
  nonNegativeInteger(program.parameters, 'neutral expression parameter count');
  return program;
}

function sameValue(left, right) {
  return JSON.stringify(canonicalizeValue(left)) === JSON.stringify(canonicalizeValue(right));
}

async function evaluate(expression, frame, context, depth = 0) {
  if (depth > MAX_EXPRESSION_DEPTH) throw new TypeError('neutral expression depth limit exceeded');
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) {
    throw new TypeError('neutral expression must be an object');
  }

  switch (expression.op) {
    case 'literal': {
      exactKeys(expression, ['op', 'value'], 'literal expression');
      return canonicalizeValue(expression.value);
    }
    case 'argument': {
      exactKeys(expression, ['op', 'index'], 'argument expression');
      const index = nonNegativeInteger(expression.index, 'argument index');
      if (index >= frame.arguments.length) throw new TypeError(`argument index out of range: ${index}`);
      return frame.arguments[index];
    }
    case 'receiver': {
      exactKeys(expression, ['op'], 'receiver expression');
      if (frame.receiver === null) throw new TypeError('activation has no receiver');
      return frame.receiver;
    }
    case 'binding': {
      exactKeys(expression, ['op', 'id'], 'binding expression');
      if (typeof expression.id !== 'string' || expression.id.length === 0) {
        throw new TypeError('binding expression id must be a non-empty string');
      }
      return await context.lookupBinding(expression.id);
    }
    case 'integer-add': {
      exactKeys(expression, ['op', 'left', 'right'], 'integer-add expression');
      const left = await evaluate(expression.left, frame, context, depth + 1);
      const right = await evaluate(expression.right, frame, context, depth + 1);
      if (left.kind !== VALUE_KIND.INTEGER || right.kind !== VALUE_KIND.INTEGER) {
        throw new TypeError('integer-add operands must be integer Values');
      }
      return integerValue(BigInt(left.value) + BigInt(right.value));
    }
    case 'equals': {
      exactKeys(expression, ['op', 'left', 'right'], 'equals expression');
      const left = await evaluate(expression.left, frame, context, depth + 1);
      const right = await evaluate(expression.right, frame, context, depth + 1);
      return booleanValue(sameValue(left, right));
    }
    case 'if': {
      exactKeys(expression, ['op', 'condition', 'then', 'else'], 'if expression');
      const condition = await evaluate(expression.condition, frame, context, depth + 1);
      if (condition.kind !== VALUE_KIND.BOOLEAN) throw new TypeError('if condition must be a boolean Value');
      return await evaluate(condition.value ? expression.then : expression.else, frame, context, depth + 1);
    }
    case 'send': {
      exactKeys(expression, ['op', 'languageId', 'receiver', 'message', 'arguments'], 'send expression');
      const languageId = requiredText(expression.languageId, 'send languageId');
      const message = canonicalizeValue(expression.message);
      if (!Array.isArray(expression.arguments)) throw new TypeError('send arguments must be an array');
      if (typeof context.sendMessage !== 'function') throw new TypeError('neutral expression send requires a message runtime');
      const receiver = await evaluate(expression.receiver, frame, context, depth + 1);
      const args = [];
      for (const argument of expression.arguments) {
        args.push(await evaluate(argument, frame, context, depth + 1));
      }
      return await context.sendMessage({languageId, receiver, message, arguments: args});
    }
    case 'make-block': {
      exactKeys(expression, ['op', 'prototype', 'captures'], 'make-block expression');
      if (!Array.isArray(expression.captures)) throw new TypeError('make-block captures must be an array');
      if (typeof context.createClosure !== 'function') throw new TypeError('make-block requires a closure runtime');
      const captures = [];
      for (let index = 0; index < expression.captures.length; index += 1) {
        const capture = expression.captures[index];
        exactKeys(capture, ['id', 'name', 'value'], `make-block capture ${index}`);
        captures.push(Object.freeze({
          id: requiredText(capture.id, `make-block capture ${index} id`),
          name: requiredText(capture.name, `make-block capture ${index} name`),
          value: await evaluate(capture.value, frame, context, depth + 1),
        }));
      }
      return await context.createClosure({prototype: canonicalizeValue(expression.prototype), captures});
    }
    default:
      throw new TypeError(`unknown neutral expression op: ${expression.op}`);
  }
}

const neutralExpressionV0Executor = Object.freeze({
  async execute({activation, code}, context) {
    const program = parseProgram(code);
    if (activation.arguments.length !== program.parameters) {
      throw new TypeError(
        `activation expected ${program.parameters} arguments, received ${activation.arguments.length}`,
      );
    }
    const frame = Object.freeze({
      receiver: activation.receiver,
      arguments: activation.arguments,
    });
    return await evaluate(program.body, frame, context);
  },
});

export {
  MAX_EXPRESSION_DEPTH,
  NEUTRAL_EXPRESSION_V0,
  neutralExpressionV0Executor,
  parseProgram,
};

import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  integerValue,
} from '../value/index.js';

// neutral-expression/v1 adds the executable form of ADR 0043's mutable lexical semantics:
// temporaries, statement sequences, assignment, and captures that carry a disposition.
//
// v0 is frozen, and its grammar is closed in the same way lagrange-code/v0 is, so extending it in
// place would change the meaning of a representation string already present in artifacts.
//
// The representation describes *what the program does*. It contains no frame machinery: which
// runtime cell a static binding id resolves to is ActivationExecutor's business, reached through
// the narrow context operations below. That is what keeps a single lexical-state model shared with
// the WASM lane instead of two lane-private ones.
const NEUTRAL_EXPRESSION_V1 = 'neutral-expression/v1';
const NEUTRAL_EXPRESSION_V2 = 'neutral-expression/v2';
const MAX_EXPRESSION_DEPTH = 256;

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function nonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function parseProgramForRepresentation(code, representation, label) {
  if (code.content?.kind !== VALUE_KIND.TEXT) {
    throw new TypeError(`${representation} code content must be a text Value`);
  }
  let program;
  try {
    program = JSON.parse(code.content.value);
  } catch (error) {
    throw new TypeError(`${representation} code content must contain valid JSON`, {cause: error});
  }
  exactKeys(program, ['parameters', 'temporaries', 'body'], label);
  nonNegativeInteger(program.parameters, 'neutral expression parameter count');
  if (!Array.isArray(program.temporaries)) throw new TypeError('neutral expression temporaries must be an array');
  for (const [index, temporary] of program.temporaries.entries()) {
    exactKeys(temporary, ['id', 'name'], `temporary ${index}`);
    requiredText(temporary.id, `temporary ${index} id`);
    requiredText(temporary.name, `temporary ${index} name`);
  }
  return program;
}

function parseProgram(code) {
  return parseProgramForRepresentation(code, NEUTRAL_EXPRESSION_V1, 'neutral expression v1 program');
}

function parseNeutralExpressionV2Program(code) {
  return parseProgramForRepresentation(code, NEUTRAL_EXPRESSION_V2, 'neutral expression v2 program');
}

function sameValue(left, right) {
  return JSON.stringify(canonicalizeValue(left)) === JSON.stringify(canonicalizeValue(right));
}

function requireOperation(context, name, label) {
  if (typeof context[name] !== 'function') {
    throw new TypeError(`${label} requires the ${name} execution operation`);
  }
  return context[name];
}

async function evaluate(expression, frame, context, depth = 0, {
  representation = NEUTRAL_EXPRESSION_V1,
  allowApply = false,
} = {}) {
  const options = {representation, allowApply};
  if (depth > MAX_EXPRESSION_DEPTH) throw new TypeError('neutral expression depth limit exceeded');
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) {
    throw new TypeError('neutral expression must be an object');
  }
  context?.checkCancelled?.();

  switch (expression.op) {
    case 'literal':
      exactKeys(expression, ['op', 'value'], 'literal expression');
      return canonicalizeValue(expression.value);
    case 'argument': {
      exactKeys(expression, ['op', 'index'], 'argument expression');
      const index = nonNegativeInteger(expression.index, 'argument index');
      if (index >= frame.arguments.length) throw new TypeError(`argument index out of range: ${index}`);
      return frame.arguments[index];
    }
    case 'receiver':
      exactKeys(expression, ['op'], 'receiver expression');
      if (frame.receiver === null) throw new TypeError('activation has no receiver');
      return frame.receiver;
    // A read of this activation's own cell, a captured cell, or a durable snapshot — resolved by
    // the executor, in that order.
    case 'binding':
      exactKeys(expression, ['op', 'id'], 'binding expression');
      return await requireOperation(context, 'readBinding', 'binding')(
        requiredText(expression.id, 'binding expression id'),
      );
    // Assignment, whose value is the written value.
    case 'binding-write': {
      exactKeys(expression, ['op', 'id', 'value'], 'binding-write expression');
      const id = requiredText(expression.id, 'binding-write id');
      const value = await evaluate(expression.value, frame, context, depth + 1, options);
      return await requireOperation(context, 'writeBinding', 'binding-write')(id, value);
    }
    case 'sequence': {
      exactKeys(expression, ['op', 'statements'], 'sequence expression');
      if (!Array.isArray(expression.statements) || expression.statements.length === 0) {
        throw new TypeError('sequence statements must be a non-empty array');
      }
      let result = null;
      for (const statement of expression.statements) {
        result = await evaluate(statement, frame, context, depth + 1, options);
      }
      return result;
    }
    case 'integer-add': {
      exactKeys(expression, ['op', 'left', 'right'], 'integer-add expression');
      const left = await evaluate(expression.left, frame, context, depth + 1, options);
      const right = await evaluate(expression.right, frame, context, depth + 1, options);
      if (left.kind !== VALUE_KIND.INTEGER || right.kind !== VALUE_KIND.INTEGER) {
        throw new TypeError('integer-add operands must be integer Values');
      }
      return integerValue(BigInt(left.value) + BigInt(right.value));
    }
    case 'equals': {
      exactKeys(expression, ['op', 'left', 'right'], 'equals expression');
      const left = await evaluate(expression.left, frame, context, depth + 1, options);
      const right = await evaluate(expression.right, frame, context, depth + 1, options);
      return booleanValue(sameValue(left, right));
    }
    case 'if': {
      exactKeys(expression, ['op', 'condition', 'then', 'else'], 'if expression');
      const condition = await evaluate(expression.condition, frame, context, depth + 1, options);
      if (condition.kind !== VALUE_KIND.BOOLEAN) throw new TypeError('if condition must be a boolean Value');
      return await evaluate(condition.value ? expression.then : expression.else, frame, context, depth + 1, options);
    }
    case 'send': {
      exactKeys(expression, ['op', 'languageId', 'receiver', 'message', 'arguments'], 'send expression');
      const languageId = requiredText(expression.languageId, 'send languageId');
      const message = canonicalizeValue(expression.message);
      if (!Array.isArray(expression.arguments)) throw new TypeError('send arguments must be an array');
      const sendMessage = requireOperation(context, 'sendMessage', 'send');
      const receiver = await evaluate(expression.receiver, frame, context, depth + 1, options);
      const args = [];
      for (const argument of expression.arguments) {
        args.push(await evaluate(argument, frame, context, depth + 1, options));
      }
      return await sendMessage({languageId, receiver, message, arguments: args});
    }
    case 'apply': {
      if (!allowApply) throw new TypeError(`unknown ${representation} expression op: ${expression.op}`);
      exactKeys(expression, ['op', 'callee', 'arguments'], 'apply expression');
      if (!Array.isArray(expression.arguments)) throw new TypeError('apply arguments must be an array');
      const invokeBlock = requireOperation(context, 'invokeBlock', 'apply');
      const callee = await evaluate(expression.callee, frame, context, depth + 1, options);
      const args = [];
      for (const argument of expression.arguments) {
        args.push(await evaluate(argument, frame, context, depth + 1, options));
      }
      return await invokeBlock(callee, args);
    }
    case 'make-block': {
      exactKeys(expression, ['op', 'prototype', 'captures'], 'make-block expression');
      if (!Array.isArray(expression.captures)) throw new TypeError('make-block captures must be an array');
      const createClosure = requireOperation(context, 'createClosure', 'make-block');
      const captures = [];
      for (const [index, capture] of expression.captures.entries()) {
        const label = `make-block capture ${index}`;
        const mode = requiredText(capture?.mode, `${label} mode`);
        if (mode === 'cell') {
          // No value is evaluated: the executor binds the declaring frame's live cell. Evaluating
          // one here is exactly how a snapshot would sneak back in.
          exactKeys(capture, ['id', 'mode', 'name'], label);
          captures.push(Object.freeze({
            id: requiredText(capture.id, `${label} id`),
            name: requiredText(capture.name, `${label} name`),
            mode: 'cell',
          }));
          continue;
        }
        if (mode !== 'snapshot') throw new TypeError(`${label} mode must be snapshot or cell`);
        exactKeys(capture, ['id', 'mode', 'name', 'value'], label);
        captures.push(Object.freeze({
          id: requiredText(capture.id, `${label} id`),
          name: requiredText(capture.name, `${label} name`),
          mode: 'snapshot',
          value: await evaluate(capture.value, frame, context, depth + 1, options),
        }));
      }
      return await createClosure({prototype: canonicalizeValue(expression.prototype), captures});
    }
    default:
      throw new TypeError(`unknown ${representation} expression op: ${expression.op}`);
  }
}

const neutralExpressionV1Executor = Object.freeze({
  async execute({activation, code}, context) {
    const program = parseProgram(code);
    if (activation.arguments.length !== program.parameters) {
      throw new TypeError(
        `activation expected ${program.parameters} arguments, received ${activation.arguments.length}`,
      );
    }
    // One frame per lexical activation, so two activations of this code — recursion included —
    // get distinct cells despite sharing static binding ids.
    if (program.temporaries.length > 0) {
      requireOperation(context, 'declareTemporaries', 'temporaries')(program.temporaries);
    }
    const frame = Object.freeze({
      receiver: activation.receiver,
      arguments: activation.arguments,
    });
    return await evaluate(program.body, frame, context);
  },
});

const neutralExpressionV2Executor = Object.freeze({
  async execute({activation, code}, context) {
    const program = parseNeutralExpressionV2Program(code);
    if (activation.arguments.length !== program.parameters) {
      throw new TypeError(
        `activation expected ${program.parameters} arguments, received ${activation.arguments.length}`,
      );
    }
    if (program.temporaries.length > 0) {
      requireOperation(context, 'declareTemporaries', 'temporaries')(program.temporaries);
    }
    const frame = Object.freeze({
      receiver: activation.receiver,
      arguments: activation.arguments,
    });
    return await evaluate(program.body, frame, context, 0, {
      representation: NEUTRAL_EXPRESSION_V2,
      allowApply: true,
    });
  },
});

export {
  NEUTRAL_EXPRESSION_V1,
  NEUTRAL_EXPRESSION_V2,
  neutralExpressionV1Executor,
  neutralExpressionV2Executor,
  parseProgram as parseNeutralExpressionV1Program,
  parseNeutralExpressionV2Program,
};

import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';
import {integerValue, isObjectRef, objectRef, textValue} from '../value/index.js';
import {
  objectVersionToken,
  parseObjectVersionToken,
  putObjectAtExpectedVersion,
} from '../object/version-token.js';
import {ensureShape} from './ensure-records.js';
import {diffImageRecords, reconstructImageRecordsAtFrontier} from './diff.js';
import {applyImageMerge, mergeImageRecords, rehomeRecordToImage} from './merge.js';

const IMAGE_BRANCH_DESCRIPTOR_V1 = 'lagrange-image-branch/v1';
const BRANCH_HEAD_SHAPE_ID = 'lagrange-branch/head-shape/v1';
const BRANCH_OBJECT_PREFIX = 'lagrange-branch/head/';

const BRANCH_SLOT = Object.freeze({
  name: 'branch-name',
  imageId: 'branch-image-id',
  revision: 'branch-revision',
  parentRevision: 'branch-parent-revision',
  description: 'branch-description',
});

class BranchConflictError extends Error {
  constructor(message, {branchName = null, currentRevision = null, targetRevision = null} = {}) {
    super(message);
    this.name = 'BranchConflictError';
    this.branchName = branchName;
    this.currentRevision = currentRevision;
    this.targetRevision = targetRevision;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function normalizeRevisionNumber(frontierOrRevision, label = 'frontier revision') {
  const raw =
    typeof frontierOrRevision === 'number' || typeof frontierOrRevision === 'bigint'
      ? Number(frontierOrRevision)
      : frontierOrRevision && typeof frontierOrRevision === 'object'
        ? Object.hasOwn(frontierOrRevision, 'revision')
          ? Number(frontierOrRevision.revision)
          : Object.hasOwn(frontierOrRevision, 'frontier')
            ? Number(frontierOrRevision.frontier)
            : Number.NaN
        : Number.NaN;
  if (!Number.isInteger(raw) || raw < 0) {
    throw new TypeError(`${label} must be a non-negative integer`);
  }
  return raw;
}

function branchObjectId(name) {
  const validName = requiredText(name, 'branch name');
  return `${BRANCH_OBJECT_PREFIX}${base64urlEncode(utf8Encode(validName))}`;
}

function isBranchHeadRecord(record) {
  return (
    record?.kind === 'object'
    && ((typeof record.id === 'string' && record.id.startsWith(BRANCH_OBJECT_PREFIX))
      || (isObjectRef(record.shape) && record.shape.objectId === BRANCH_HEAD_SHAPE_ID))
  );
}

async function ensureBranchHeadShape(images, imageId) {
  const shape = await ensureShape(images, imageId, {
    id: BRANCH_HEAD_SHAPE_ID,
    slots: [
      {id: BRANCH_SLOT.name, name: 'name'},
      {id: BRANCH_SLOT.imageId, name: 'imageId'},
      {id: BRANCH_SLOT.revision, name: 'revision'},
      {id: BRANCH_SLOT.parentRevision, name: 'parentRevision'},
      {id: BRANCH_SLOT.description, name: 'description'},
    ],
  });
  return objectRef(imageId, shape.id);
}

function branchDescriptorFromRecord(record, expectedImageId, expectedName = null) {
  if (
    !record
    || record.kind !== 'object'
    || !isObjectRef(record.shape)
    || record.shape.objectId !== BRANCH_HEAD_SHAPE_ID
  ) {
    throw new TypeError(`malformed branch record: ${record?.id ?? 'unknown'}`);
  }
  const nameVal = record.slots?.[BRANCH_SLOT.name];
  const imgVal = record.slots?.[BRANCH_SLOT.imageId];
  const revVal = record.slots?.[BRANCH_SLOT.revision];
  const parentRevVal = record.slots?.[BRANCH_SLOT.parentRevision];
  const descVal = record.slots?.[BRANCH_SLOT.description];

  if (
    nameVal?.kind !== 'text'
    || imgVal?.kind !== 'text'
    || revVal?.kind !== 'integer'
    || parentRevVal?.kind !== 'integer'
    || descVal?.kind !== 'text'
  ) {
    throw new TypeError(`malformed branch slot values on ${record.id}`);
  }
  if (expectedName !== null && nameVal.value !== expectedName) {
    throw new TypeError(`branch record ${record.id} name mismatch: expected ${expectedName}, got ${nameVal.value}`);
  }
  const revision = Number(revVal.value);
  const parentRaw = Number(parentRevVal.value);
  return Object.freeze({
    format: IMAGE_BRANCH_DESCRIPTOR_V1,
    imageId: expectedImageId ?? record.imageId,
    name: nameVal.value,
    objectId: record.id,
    frontier: Object.freeze({
      imageId: imgVal.value,
      revision,
    }),
    parentRevision: parentRaw >= 0 ? parentRaw : null,
    description: descVal.value,
  });
}

function buildBranchRecordPayload({
  imageId,
  shapeRef,
  name,
  revision,
  parentRevision = null,
  description = '',
}) {
  return {
    id: branchObjectId(name),
    shape: shapeRef ?? objectRef(imageId, BRANCH_HEAD_SHAPE_ID),
    behavior: null,
    slots: {
      [BRANCH_SLOT.name]: textValue(name),
      [BRANCH_SLOT.imageId]: textValue(imageId),
      [BRANCH_SLOT.revision]: integerValue(BigInt(revision)),
      [BRANCH_SLOT.parentRevision]: integerValue(
        parentRevision !== null && parentRevision !== undefined && parentRevision >= 0
          ? BigInt(parentRevision)
          : -1n,
      ),
      [BRANCH_SLOT.description]: textValue(description ?? ''),
    },
    metadata: {branch: 'head', name},
  };
}

async function createBranch({
  images,
  imageId,
  name,
  frontier = null,
  parentRevision = null,
  description = '',
  overwrite = false,
} = {}) {
  if (!images || typeof images.frontier !== 'function' || typeof images.putObject !== 'function') {
    throw new TypeError('createBranch requires an ImageService');
  }
  requiredText(imageId, 'imageId');
  requiredText(name, 'branch name');
  if (typeof description !== 'string') {
    throw new TypeError('branch description must be a string');
  }

  const headFrontier = normalizeRevisionNumber(await images.frontier(imageId), 'image head frontier');
  const targetRevision =
    frontier === null || frontier === undefined
      ? headFrontier
      : normalizeRevisionNumber(frontier, 'branch frontier');
  if (targetRevision > headFrontier) {
    throw new RangeError(
      `branch ${name} frontier revision ${targetRevision} exceeds image ${imageId} head revision ${headFrontier}`,
    );
  }

  const shapeRef = await ensureBranchHeadShape(images, imageId);
  const id = branchObjectId(name);
  const existing = await images.getObject(imageId, id);
  if (existing) {
    const existingDesc = branchDescriptorFromRecord(existing, imageId, name);
    if (!overwrite) {
      if (existingDesc.frontier.revision === targetRevision) {
        return Object.freeze({
          descriptor: existingDesc,
          versionToken: objectVersionToken(imageId, existing.id, existing._version),
        });
      }
      throw new BranchConflictError(
        `branch ${name} already exists in image ${imageId} at revision ${existingDesc.frontier.revision}`,
        {
          branchName: name,
          currentRevision: existingDesc.frontier.revision,
          targetRevision,
        },
      );
    }
  }

  const payload = buildBranchRecordPayload({
    imageId,
    shapeRef,
    name,
    revision: targetRevision,
    parentRevision,
    description,
  });
  const saved = existing
    ? await images.putObject(imageId, payload, {expectedVersion: existing._version})
    : await images.putObject(imageId, payload, {expectedVersion: 0});

  return Object.freeze({
    descriptor: branchDescriptorFromRecord(saved, imageId, name),
    versionToken: objectVersionToken(imageId, saved.id, saved._version),
  });
}

async function getBranch({images, imageId, name} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('getBranch requires an ImageService');
  }
  requiredText(imageId, 'imageId');
  requiredText(name, 'branch name');
  const record = await images.getObject(imageId, branchObjectId(name));
  if (!record) return null;
  return Object.freeze({
    descriptor: branchDescriptorFromRecord(record, imageId, name),
    versionToken: objectVersionToken(imageId, record.id, record._version),
  });
}

async function listBranches({images, imageId} = {}) {
  if (!images || typeof images.listObjects !== 'function') {
    throw new TypeError('listBranches requires an ImageService');
  }
  requiredText(imageId, 'imageId');
  const objects = await images.listObjects(imageId);
  const descriptors = [];
  for (const obj of objects) {
    if (isObjectRef(obj.shape) && obj.shape.objectId === BRANCH_HEAD_SHAPE_ID) {
      descriptors.push(branchDescriptorFromRecord(obj, imageId));
    }
  }
  descriptors.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  return Object.freeze(descriptors);
}

async function advanceBranch({
  images,
  imageId,
  name,
  toFrontier = null,
  expectedVersionToken = null,
  expectedRevision = null,
  description = null,
  allowNonFastForward = false,
} = {}) {
  if (!images || typeof images.getObject !== 'function' || typeof images.putObject !== 'function') {
    throw new TypeError('advanceBranch requires an ImageService');
  }
  requiredText(imageId, 'imageId');
  requiredText(name, 'branch name');

  const id = branchObjectId(name);
  let expectedVersionFromToken = null;
  if (expectedVersionToken !== null && expectedVersionToken !== undefined) {
    expectedVersionFromToken = parseObjectVersionToken(expectedVersionToken, imageId, id);
  }
  const currentRecord = await images.getObject(imageId, id);
  if (!currentRecord) {
    throw new TypeError(`branch not found: ${imageId}/${name}`);
  }
  const currentDesc = branchDescriptorFromRecord(currentRecord, imageId, name);

  if (expectedRevision !== null && expectedRevision !== undefined) {
    const expRev = normalizeRevisionNumber(expectedRevision, 'expectedRevision');
    if (currentDesc.frontier.revision !== expRev) {
      throw new BranchConflictError(
        `branch ${name} expected revision ${expRev}, but current revision is ${currentDesc.frontier.revision}`,
        {
          branchName: name,
          currentRevision: currentDesc.frontier.revision,
          targetRevision: expRev,
        },
      );
    }
  }

  const headFrontier = normalizeRevisionNumber(await images.frontier(imageId), 'image head frontier');
  const targetRevision =
    toFrontier === null || toFrontier === undefined
      ? headFrontier
      : normalizeRevisionNumber(toFrontier, 'toFrontier');
  if (targetRevision > headFrontier) {
    throw new RangeError(
      `branch ${name} target revision ${targetRevision} exceeds image ${imageId} head revision ${headFrontier}`,
    );
  }

  if (targetRevision < currentDesc.frontier.revision && !allowNonFastForward) {
    throw new BranchConflictError(
      `cannot non-fast-forward branch ${name} from revision ${currentDesc.frontier.revision} to ${targetRevision} without allowNonFastForward`,
      {
        branchName: name,
        currentRevision: currentDesc.frontier.revision,
        targetRevision,
      },
    );
  }

  const payload = buildBranchRecordPayload({
    imageId,
    shapeRef: currentRecord.shape,
    name,
    revision: targetRevision,
    parentRevision: currentDesc.frontier.revision,
    description: description !== null && description !== undefined ? description : currentDesc.description,
  });

  const saved =
    expectedVersionFromToken !== null
      ? await putObjectAtExpectedVersion(images, imageId, payload, expectedVersionFromToken)
      : await images.putObject(imageId, payload, {expectedVersion: currentRecord._version});

  return Object.freeze({
    descriptor: branchDescriptorFromRecord(saved, imageId, name),
    versionToken: objectVersionToken(imageId, saved.id, saved._version),
    fastForward: targetRevision >= currentDesc.frontier.revision,
  });
}

async function deleteBranch({images, imageId, name} = {}) {
  if (!images || typeof images.sweepRecords !== 'function') {
    throw new TypeError('deleteBranch requires an ImageService with sweepRecords');
  }
  requiredText(imageId, 'imageId');
  requiredText(name, 'branch name');
  const id = branchObjectId(name);
  const existing = await images.getObject(imageId, id);
  if (!existing) {
    return Object.freeze({deleted: false, imageId, name});
  }
  await images.sweepRecords(imageId, [id]);
  return Object.freeze({deleted: true, imageId, name});
}

function candidateRecordForCreate(rehomedRecord) {
  switch (rehomedRecord.kind) {
    case 'shape':
      return {
        kind: 'shape',
        id: rehomedRecord.id,
        slots: rehomedRecord.slots,
        ...(Object.hasOwn(rehomedRecord, 'indexed') ? {indexed: rehomedRecord.indexed} : {}),
        metadata: rehomedRecord.metadata ?? {},
      };
    case 'code-artifact':
      return {
        kind: 'code-artifact',
        id: rehomedRecord.id,
        languageId: rehomedRecord.languageId ?? null,
        representation: rehomedRecord.representation,
        content: rehomedRecord.content,
        logicalPath: rehomedRecord.logicalPath ?? null,
        dependencies: rehomedRecord.dependencies ?? [],
        derivedFrom: rehomedRecord.derivedFrom ?? [],
        metadata: rehomedRecord.metadata ?? {},
      };
    case 'lexical-environment':
      return {
        kind: 'lexical-environment',
        id: rehomedRecord.id,
        parent: rehomedRecord.parent ?? null,
        bindings: rehomedRecord.bindings ?? {},
        metadata: rehomedRecord.metadata ?? {},
      };
    case 'block':
      return {
        kind: 'block',
        id: rehomedRecord.id,
        code: rehomedRecord.code,
        environment: rehomedRecord.environment ?? null,
        metadata: rehomedRecord.metadata ?? {},
      };
    case 'object':
      return {
        kind: 'object',
        id: rehomedRecord.id,
        shape: rehomedRecord.shape,
        behavior: rehomedRecord.behavior ?? null,
        slots: rehomedRecord.slots ?? {},
        ...(Object.hasOwn(rehomedRecord, 'indexed') ? {indexed: rehomedRecord.indexed} : {}),
        metadata: rehomedRecord.metadata ?? {},
      };
    default:
      throw new TypeError(`unsupported record kind in forkImageFromFrontier: ${rehomedRecord.kind}`);
  }
}

async function forkImageFromFrontier({
  images,
  sourceImageId,
  frontier = null,
  targetImageId,
  targetImageName = null,
  createBranchName = null,
  includeBranches = false,
} = {}) {
  if (!images || typeof images.createImage !== 'function' || typeof images.createRecords !== 'function') {
    throw new TypeError('forkImageFromFrontier requires an ImageService with createImage and createRecords');
  }
  requiredText(sourceImageId, 'sourceImageId');
  requiredText(targetImageId, 'targetImageId');
  if (sourceImageId === targetImageId) {
    throw new TypeError('forkImageFromFrontier targetImageId must differ from sourceImageId');
  }

  const headRevision = normalizeRevisionNumber(
    await images.frontier(sourceImageId),
    'sourceImageId head frontier',
  );
  const sourceRevision =
    frontier === null || frontier === undefined
      ? headRevision
      : normalizeRevisionNumber(frontier, 'frontier');

  const records = await reconstructImageRecordsAtFrontier({
    images,
    imageId: sourceImageId,
    frontier: sourceRevision,
  });

  await images.createImage({
    id: targetImageId,
    name: targetImageName ?? `Fork of ${sourceImageId}@${sourceRevision}`,
  });

  const filteredRecords = records.filter((record) => {
    if (includeBranches) return true;
    if (isBranchHeadRecord(record)) return false;
    if (record.kind === 'shape' && record.id === BRANCH_HEAD_SHAPE_ID) return false;
    return true;
  });

  const candidates = filteredRecords.map((rec) =>
    candidateRecordForCreate(rehomeRecordToImage(rec, sourceImageId, targetImageId)),
  );
  if (candidates.length > 0) {
    await images.createRecords(targetImageId, candidates);
  }

  const targetRev = normalizeRevisionNumber(
    await images.frontier(targetImageId),
    'targetImageId head frontier',
  );
  let branch = null;
  if (createBranchName !== null && createBranchName !== undefined) {
    branch = await createBranch({
      images,
      imageId: targetImageId,
      name: createBranchName,
      frontier: targetRev,
      description: `Forked from ${sourceImageId}@${sourceRevision}`,
    });
  }

  return Object.freeze({
    sourceImageId,
    sourceFrontier: Object.freeze({
      imageId: sourceImageId,
      revision: sourceRevision,
    }),
    targetImageId,
    targetFrontier: Object.freeze({
      imageId: targetImageId,
      revision: targetRev,
    }),
    recordCount: candidates.length,
    branch: branch ? branch.descriptor : null,
  });
}

async function forkImageFromBranch({
  images,
  imageId,
  branchName,
  targetImageId,
  targetImageName = null,
  createBranchName = branchName,
  includeBranches = false,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(branchName, 'branchName');
  const branchEntry = await getBranch({images, imageId, name: branchName});
  if (!branchEntry) {
    throw new TypeError(`branch not found: ${imageId}/${branchName}`);
  }
  return await forkImageFromFrontier({
    images,
    sourceImageId: imageId,
    frontier: branchEntry.descriptor.frontier,
    targetImageId,
    targetImageName,
    createBranchName,
    includeBranches,
  });
}

async function diffBranches({
  images,
  imageId,
  baseBranch,
  targetBranch,
  targetImageId = imageId,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(baseBranch, 'baseBranch');
  requiredText(targetBranch, 'targetBranch');
  requiredText(targetImageId, 'targetImageId');

  const baseEntry = await getBranch({images, imageId, name: baseBranch});
  if (!baseEntry) {
    throw new TypeError(`base branch not found: ${imageId}/${baseBranch}`);
  }
  const targetEntry = await getBranch({images, imageId: targetImageId, name: targetBranch});
  if (!targetEntry) {
    throw new TypeError(`target branch not found: ${targetImageId}/${targetBranch}`);
  }

  const baseRev = baseEntry.descriptor.frontier.revision;
  const targetRev = targetEntry.descriptor.frontier.revision;

  const [rawFromRecords, rawToRecords] = await Promise.all([
    reconstructImageRecordsAtFrontier({images, imageId, frontier: baseRev}),
    reconstructImageRecordsAtFrontier({images, imageId: targetImageId, frontier: targetRev}),
  ]);

  const filterNonBranch = (record) =>
    !isBranchHeadRecord(record) && !(record.kind === 'shape' && record.id === BRANCH_HEAD_SHAPE_ID);

  const fromRecords = rawFromRecords.filter(filterNonBranch);
  const toRecords = rawToRecords
    .filter(filterNonBranch)
    .map((rec) => (targetImageId !== imageId ? rehomeRecordToImage(rec, targetImageId, imageId) : rec));

  const diff = diffImageRecords({
    fromRecords,
    toRecords,
    fromImageId: imageId,
    toImageId: targetImageId,
    fromFrontier: baseRev,
    toFrontier: targetRev,
  });

  return Object.freeze({
    ...diff,
    baseBranch: baseEntry.descriptor,
    targetBranch: targetEntry.descriptor,
  });
}

async function mergeBranches({
  images,
  imageId,
  baseFrontier = null,
  baseBranch = null,
  sourceBranch,
  sourceImageId = imageId,
  targetBranch,
  resolutions = {},
  allowConflicts = false,
  apply = true,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(sourceBranch, 'sourceBranch');
  requiredText(sourceImageId, 'sourceImageId');
  requiredText(targetBranch, 'targetBranch');

  const targetEntry = await getBranch({images, imageId, name: targetBranch});
  if (!targetEntry) {
    throw new TypeError(`target branch not found: ${imageId}/${targetBranch}`);
  }
  const sourceEntry = await getBranch({images, imageId: sourceImageId, name: sourceBranch});
  if (!sourceEntry) {
    throw new TypeError(`source branch not found: ${sourceImageId}/${sourceBranch}`);
  }

  let resolvedBaseFrontier = baseFrontier;
  if (resolvedBaseFrontier === null && baseBranch !== null) {
    const baseBranchEntry = await getBranch({images, imageId, name: baseBranch});
    if (!baseBranchEntry) {
      throw new TypeError(`base branch not found: ${imageId}/${baseBranch}`);
    }
    resolvedBaseFrontier = baseBranchEntry.descriptor.frontier;
  }
  if (resolvedBaseFrontier === null) {
    if (sourceEntry.descriptor.parentRevision !== null) {
      resolvedBaseFrontier = {imageId, revision: sourceEntry.descriptor.parentRevision};
    } else {
      resolvedBaseFrontier = targetEntry.descriptor.frontier;
    }
  }

  const baseRev = normalizeRevisionNumber(resolvedBaseFrontier, 'baseFrontier');
  const targetRev = targetEntry.descriptor.frontier.revision;
  const sourceRev = sourceEntry.descriptor.frontier.revision;

  const filterNonBranch = (record) =>
    !isBranchHeadRecord(record) && !(record.kind === 'shape' && record.id === BRANCH_HEAD_SHAPE_ID);

  const [rawBaseRecords, rawLeftRecords, rawRightRecords] = await Promise.all([
    reconstructImageRecordsAtFrontier({images, imageId, frontier: baseRev}),
    reconstructImageRecordsAtFrontier({images, imageId, frontier: targetRev}),
    reconstructImageRecordsAtFrontier({images, imageId: sourceImageId, frontier: sourceRev}),
  ]);

  const mergePlan = mergeImageRecords({
    baseRecords: rawBaseRecords.filter(filterNonBranch),
    leftRecords: rawLeftRecords.filter(filterNonBranch),
    rightRecords: rawRightRecords.filter(filterNonBranch),
    baseImageId: imageId,
    leftImageId: imageId,
    rightImageId: sourceImageId,
    targetImageId: imageId,
    baseFrontier: baseRev,
    leftFrontier: targetRev,
    rightFrontier: sourceRev,
    resolutions,
  });

  if (!mergePlan.clean && !allowConflicts) {
    return Object.freeze({
      clean: false,
      fastForward: false,
      applied: false,
      sourceBranch: sourceEntry.descriptor,
      targetBranch: targetEntry.descriptor,
      mergePlan,
      conflicts: mergePlan.conflicts,
    });
  }

  if (!apply) {
    return Object.freeze({
      clean: mergePlan.clean,
      fastForward: sourceImageId === imageId && baseRev === targetRev && sourceRev >= targetRev,
      applied: false,
      sourceBranch: sourceEntry.descriptor,
      targetBranch: targetEntry.descriptor,
      mergePlan,
      conflicts: mergePlan.conflicts,
    });
  }

  const headBeforeApply = normalizeRevisionNumber(
    await images.frontier(imageId),
    'image head frontier',
  );
  const isPureFastForward =
    sourceImageId === imageId
    && baseRev === targetRev
    && sourceRev >= targetRev
    && headBeforeApply === sourceRev;

  if (isPureFastForward) {
    const advanced = await advanceBranch({
      images,
      imageId,
      name: targetBranch,
      toFrontier: {imageId, revision: sourceRev},
    });
    return Object.freeze({
      clean: true,
      fastForward: true,
      applied: true,
      sourceBranch: sourceEntry.descriptor,
      targetBranch: advanced.descriptor,
      mergePlan,
      conflicts: mergePlan.conflicts,
    });
  }

  await applyImageMerge({
    images,
    targetImageId: imageId,
    mergePlan,
    allowConflicts,
  });

  if (mergePlan.removedIds.length > 0 && typeof images.sweepRecords === 'function') {
    await images.sweepRecords(imageId, [...mergePlan.removedIds]);
  }

  const postMergeFrontier = normalizeRevisionNumber(
    await images.frontier(imageId),
    'post-merge frontier',
  );
  const advanced = await advanceBranch({
    images,
    imageId,
    name: targetBranch,
    toFrontier: postMergeFrontier,
    allowNonFastForward: true,
  });

  return Object.freeze({
    clean: mergePlan.clean,
    fastForward: false,
    applied: true,
    sourceBranch: sourceEntry.descriptor,
    targetBranch: advanced.descriptor,
    mergePlan,
    conflicts: mergePlan.conflicts,
  });
}

export {
  BRANCH_HEAD_SHAPE_ID,
  BranchConflictError,
  IMAGE_BRANCH_DESCRIPTOR_V1,
  advanceBranch,
  branchObjectId,
  createBranch,
  deleteBranch,
  diffBranches,
  forkImageFromBranch,
  forkImageFromFrontier,
  getBranch,
  isBranchHeadRecord,
  listBranches,
  mergeBranches,
};

import {referencesOfRecord} from './references.js';
import {canonicalizeValue, isObjectRef, isPinnedRef, isReference, objectRef, VALUE_KIND} from '../value/index.js';
import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {bytesToHex, utf8Encode} from '../support/portable-bytes.js';
import {TupleMap} from '../support/tuple-map.js';

// ADR 0074: durable graph roots <-> portable graph bundle + deterministic
// contentIdentity. EXPORT (first slice) + IMPORT (second slice).
//
// OWNERSHIP. This module is the single owner of portable graph bundle semantics
// (closure, bundle-local identity, external-ref rule, canonical form, content
// identity, bundle validation, the external-resolution contract, and bundle-local
// -> target-local identity translation). It CONSUMES `referencesOfRecord` — the
// single owner of which graph edges a durable record has — and never re-implements
// per-kind traversal. It reads records through `GraphImageService` and never
// duplicates graph storage semantics. The IMPORT direction publishes exclusively
// through `GraphImageService.createRecords` — the owner of record-model validation,
// relational validation, batch-local fresh-record visibility and the atomic
// N-records + N-history-events transaction; the importer never calls the backend,
// never appends history and never calls the per-kind single-record puts. Project
// release semantics, authority lanes, reconciliation/dedup, GC/retention,
// historical reads and deployment are all separate owners and out of scope here.
//
// BUNDLE-LOCAL IDENTITY. Source ObjectRefs are used internally ONLY for fetching
// and visited/dedup bookkeeping; they never become portable internal identity.
// Local ids (r0, r1, ...) are assigned by deterministic traversal: roots in
// canonical code-unit key order, outgoing edges in canonical semantic edge order
// (the order `referencesOfRecord` yields). Source objectIds never break traversal
// ties and never appear inside roots/records internal identity data. On import,
// bundle localIds likewise never become target identity: every target id is a
// freshly minted uuid, and the localId -> target-ref map is transient import state.
//
// PORTABILITY. This module imports no Node host API; it resolves the active crypto
// provider (SHA-256, uuid) and the portable-bytes owner, so it runs inside the
// portable runtime closure once a host provider is installed.

const GRAPH_BUNDLE_V1 = 'lagrange-graph-bundle/v1';

class GraphBundleExportError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'GraphBundleExportError';
    Object.assign(this, details);
  }
}

function fail(message, details) {
  throw new GraphBundleExportError(message, details);
}

function requiredRef(value, label) {
  const normalized = canonicalizeValue(value);
  if (!isObjectRef(normalized)) fail(`${label} must be an unpinned ObjectRef`);
  return normalized;
}

// A source ObjectRef is an internal/bookkeeping key only. Pinned refs are never
// internal closure targets (ADR 0074 §C: always external by construction).
//
// Bookkeeping keys are TUPLES, never joined strings: image ids, object ids and
// revision text are arbitrary strings, so any separator is ambiguous — ('ab','c')
// and ('a','bc') join to the same key, silently collapsing two distinct records to
// one localId (or two distinct external requirements to one externalKey) and
// corrupting aliasing/cycles. The repository's tuple-key owner (TupleMap) makes
// that mistake unavailable rather than discouraged.

// The default per-ref policy (ADR 0074 §C). `rootImageIds` is the set of Image ids
// the closure is allowed to internalize: by default exactly the Images named by the
// roots, so a cross-Image ObjectRef is external UNLESS the caller opts it in. The
// caller's `referencePolicy` may override either direction for an UNPINNED ref; a
// pinned ref is ALWAYS external and no policy may internalize it.
function defaultReferencePolicy({rootImageIds}) {
  return {
    // Return 'internal' to bundle the ref's target, 'external' to record it as an
    // unresolved requirement. Only ever called for unpinned refs.
    classify(ref) {
      return rootImageIds.has(ref.imageId) ? 'internal' : 'external';
    },
  };
}

// Canonical JSON: map keys in code-unit order, arrays in semantic order, values in
// their existing canonical form. This is the host-independent encoding the content
// identity is hashed from. No new binary codec — UTF-8 via portable-bytes, SHA-256
// via the crypto provider.
function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value ?? null);
}

// contentIdentity: SHA-256 over the canonical bundle form, via the active crypto
// provider and portable-bytes. Source refs/provenance/frontiers/metadata are
// already excluded by the projection. The bundle does not contain its own
// contentIdentity, so the hash is well-founded. ONE owner: exporter and importer
// compute identity through this same function, so the two directions can never
// drift on what a bundle's hash means.
function contentIdentityForBundle(bundle, {crypto} = {}) {
  const activeCrypto = crypto ?? getDefaultCryptoProvider();
  return `sha256:${bytesToHex(activeCrypto.sha256(utf8Encode(canonicalJson(bundle))))}`;
}

class GraphBundleImportError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'GraphBundleImportError';
    Object.assign(this, details);
  }
}

function importFail(message, details) {
  throw new GraphBundleImportError(message, details);
}

// --- Bundle v1 validation: ONE owner of what a valid bundle is -------------------
// Used by the importer (pre-publication gate) and by the exporter (post-assembly
// self-check). Structural checks PLUS closure completeness: a bundle is a closed
// graph, not an arbitrary bag of records. Throws TypeError with a precise message;
// the importer converts these into GraphBundleImportError.

const LOCAL_ID_PATTERN = /^r\d+$/;
const EXTERNAL_KEY_PATTERN = /^e\d+$/;
// Source/runtime fields the exporter strips (ADR 0074 §4); they must never
// reappear at a portable record's top level.
const FORBIDDEN_RECORD_FIELDS = new Set(['id', 'imageId', '_version', 'updatedAt', 'metadata']);

function isPlainMap(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// The canonical v1 key domain: exactly r0..r(N-1) (or e0..e(M-1)), contiguous and
// complete — no gaps, no aliases, no foreign keys.
function assertCanonicalKeyDomain(keys, pattern, prefix, label) {
  const indices = new Set();
  for (const key of keys) {
    if (typeof key !== 'string' || !pattern.test(key)) {
      throw new TypeError(`${label} key is not in the canonical ${prefix}<n> domain: ${JSON.stringify(key)}`);
    }
    indices.add(Number(key.slice(1)));
  }
  for (let index = 0; index < keys.length; index += 1) {
    if (!indices.has(index)) {
      throw new TypeError(`${label} keys are not the contiguous canonical domain ${prefix}0..${prefix}${keys.length - 1}`);
    }
  }
}

// Strict generic walk over portable material. Every local-ref/external-ref token
// is validated and handed to `visit`; a raw durable ObjectRef/pinned-ref Value
// (kind 'ref'/'pinned-ref') is a source-identity smuggling attempt and rejected.
// No record-kind switch — one structural transform.
function forEachPortableToken(value, visit, path) {
  if (Array.isArray(value)) {
    value.forEach((entry, index) => forEachPortableToken(entry, visit, `${path}[${index}]`));
    return;
  }
  if (value && typeof value === 'object') {
    if (value.kind === 'local-ref') {
      const keys = Object.keys(value);
      if (keys.length !== 2 || typeof value.localId !== 'string' || !LOCAL_ID_PATTERN.test(value.localId)) {
        throw new TypeError(`malformed local-ref token at ${path}`);
      }
      visit(value);
      return;
    }
    if (value.kind === 'external-ref') {
      const keys = Object.keys(value);
      if (keys.length !== 2 || typeof value.externalKey !== 'string' || !EXTERNAL_KEY_PATTERN.test(value.externalKey)) {
        throw new TypeError(`malformed external-ref token at ${path}`);
      }
      visit(value);
      return;
    }
    if (value.kind === VALUE_KIND.REF || value.kind === VALUE_KIND.PINNED_REF) {
      throw new TypeError(`raw source ${value.kind} smuggled into portable material at ${path}`);
    }
    for (const key of Object.keys(value)) forEachPortableToken(value[key], visit, `${path}.${key}`);
  }
}

// Validate the ENTIRE bundle: exact format, plain maps, canonical key domains,
// root/local-ref/external-ref referential integrity, descriptor shapes, no
// smuggled source refs, no source/runtime fields, and closure completeness (every
// record reachable from a root; every external descriptor actually referenced).
function assertGraphBundleV1(bundle) {
  if (!isPlainMap(bundle)) throw new TypeError('graph bundle must be a plain object');
  if (bundle.format !== GRAPH_BUNDLE_V1) {
    throw new TypeError(`unsupported graph bundle format: ${JSON.stringify(bundle.format)}`);
  }
  const {roots, records, externals} = bundle;
  if (!isPlainMap(roots)) throw new TypeError('graph bundle roots must be a plain map');
  if (!isPlainMap(records)) throw new TypeError('graph bundle records must be a plain map');
  if (!isPlainMap(externals)) throw new TypeError('graph bundle externals must be a plain map');
  const rootKeys = Object.keys(roots);
  if (rootKeys.length === 0) throw new TypeError('graph bundle must name at least one root');

  assertCanonicalKeyDomain(Object.keys(records), LOCAL_ID_PATTERN, 'r', 'records');
  assertCanonicalKeyDomain(Object.keys(externals), EXTERNAL_KEY_PATTERN, 'e', 'externals');

  for (const rootKey of rootKeys) {
    const localId = roots[rootKey];
    if (typeof localId !== 'string' || !Object.hasOwn(records, localId)) {
      throw new TypeError(`root ${JSON.stringify(rootKey)} names an unknown localId: ${JSON.stringify(localId)}`);
    }
  }

  for (const [externalKey, descriptor] of Object.entries(externals)) {
    if (!isPlainMap(descriptor)) throw new TypeError(`external descriptor ${externalKey} must be a plain object`);
    const keys = Object.keys(descriptor).sort();
    if (descriptor.pinned === true) {
      if (keys.join(',') !== 'imageId,objectId,pinned,revision'
        || typeof descriptor.imageId !== 'string' || typeof descriptor.objectId !== 'string'
        || typeof descriptor.revision !== 'string') {
        throw new TypeError(`pinned external descriptor ${externalKey} must be exactly {pinned:true, imageId, objectId, revision}`);
      }
    } else if (descriptor.pinned === false) {
      if (keys.join(',') !== 'imageId,objectId,pinned'
        || typeof descriptor.imageId !== 'string' || typeof descriptor.objectId !== 'string') {
        throw new TypeError(`unpinned external descriptor ${externalKey} must be exactly {pinned:false, imageId, objectId} (no revision)`);
      }
    } else {
      throw new TypeError(`external descriptor ${externalKey} must declare pinned: true|false`);
    }
  }

  for (const [localId, record] of Object.entries(records)) {
    if (!isPlainMap(record)) throw new TypeError(`record ${localId} must be a plain object`);
    if (typeof record.kind !== 'string' || record.kind.length === 0) {
      throw new TypeError(`record ${localId} must declare a non-empty kind`);
    }
    for (const field of Object.keys(record)) {
      if (FORBIDDEN_RECORD_FIELDS.has(field)) {
        throw new TypeError(`record ${localId} carries forbidden source/runtime field: ${field}`);
      }
    }
    // Referential integrity + no smuggled source refs, generically over tokens.
    forEachPortableToken(record, (token) => {
      if (token.kind === 'local-ref' && !Object.hasOwn(records, token.localId)) {
        throw new TypeError(`record ${localId} references unknown localId: ${token.localId}`);
      }
      if (token.kind === 'external-ref' && !Object.hasOwn(externals, token.externalKey)) {
        throw new TypeError(`record ${localId} references unknown externalKey: ${token.externalKey}`);
      }
    }, localId);
  }

  // Closure completeness: walk portable tokens from the root localIds. Every
  // records entry must be reachable and every external descriptor used, so hidden
  // extra material cannot hitchhike through import inside one "graph bundle".
  const reachable = new Set();
  const usedExternals = new Set();
  const queue = rootKeys.map((rootKey) => roots[rootKey]);
  while (queue.length > 0) {
    const localId = queue.shift();
    if (reachable.has(localId)) continue;
    reachable.add(localId);
    forEachPortableToken(records[localId], (token) => {
      if (token.kind === 'local-ref') queue.push(token.localId);
      else usedExternals.add(token.externalKey);
    }, localId);
  }
  for (const localId of Object.keys(records)) {
    if (!reachable.has(localId)) throw new TypeError(`unreachable record in bundle closure: ${localId}`);
  }
  for (const externalKey of Object.keys(externals)) {
    if (!usedExternals.has(externalKey)) throw new TypeError(`unused external descriptor in bundle: ${externalKey}`);
  }
  return bundle;
}

// Canonical localId order: r0, r1, ... by numeric index (the key domain is already
// validated contiguous by assertGraphBundleV1).
function orderedLocalIds(bundle) {
  return Object.keys(bundle.records).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)));
}

async function exportGraphBundleInternal({images, roots, referencePolicy, crypto, includeSourceMap = false} = {}) {
  if (!images || typeof images.getRecord !== 'function') fail('images must be a GraphImageService');
  if (!roots || typeof roots !== 'object' || Array.isArray(roots)) fail('roots must be a map of root key -> ObjectRef');
  const rootEntries = Object.entries(roots);
  if (rootEntries.length === 0) fail('roots must name at least one root');

  // Roots processed in canonical code-unit key order. Source refs validated and
  // used ONLY for fetching/dedup — never as portable identity.
  const sortedRoots = rootEntries
    .map(([key, ref]) => [key, requiredRef(ref, `root ${JSON.stringify(key)}`)])
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));

  const policy = referencePolicy ?? defaultReferencePolicy({
    rootImageIds: new Set(sortedRoots.map(([, ref]) => ref.imageId)),
  });
  if (typeof policy.classify !== 'function') fail('referencePolicy must supply classify(ref)');

  const sourceToLocal = new TupleMap(2);        // [imageId, objectId] -> localId (visited/dedup only)
  const localToSourceRef = {};                  // localId -> source ObjectRef (when includeSourceMap is true)
  const unpinnedExternalToKey = new TupleMap(2); // [imageId, objectId] -> externalKey (dedup only)
  const pinnedExternalToKey = new TupleMap(3);   // [imageId, objectId, revision] -> externalKey (dedup only)
  const records = {};                  // localId -> canonical portable record
  const externals = {};                // externalKey -> external descriptor
  const rootLocalIds = {};             // rootKey -> localId
  let nextLocal = 0;
  let nextExternal = 0;
  const queue = [];                    // BFS frontier of {localId, ref}

  // Classify one enumerated ref and return its portable edge token.
  function edgeToken(ref, ownerLocalId) {
    if (isPinnedRef(ref)) {
      const identity = [ref.imageId, ref.objectId, ref.revision];
      let externalKey = pinnedExternalToKey.get(identity);
      if (externalKey === undefined) {
        externalKey = `e${nextExternal}`;
        nextExternal += 1;
        pinnedExternalToKey.set(identity, externalKey);
        externals[externalKey] = {
          pinned: true,
          imageId: ref.imageId,
          objectId: ref.objectId,
          revision: ref.revision,
        };
      }
      return {kind: 'external-ref', externalKey};
    }
    const decision = policy.classify(ref);
    if (decision === 'internal') {
      return {kind: 'local-ref', localId: assignLocalId(ref)};
    }
    if (decision === 'external') {
      const identity = [ref.imageId, ref.objectId];
      let externalKey = unpinnedExternalToKey.get(identity);
      if (externalKey === undefined) {
        externalKey = `e${nextExternal}`;
        nextExternal += 1;
        unpinnedExternalToKey.set(identity, externalKey);
        externals[externalKey] = {
          pinned: false,
          imageId: ref.imageId,
          objectId: ref.objectId,
        };
      }
      return {kind: 'external-ref', externalKey};
    }
    fail(`referencePolicy.classify must return 'internal' or 'external', got ${JSON.stringify(decision)}`, {ownerLocalId});
    return undefined;
  }

  function projectValue(value, ctx) {
    if (isReference(value)) {
      ctx.rewritten += 1;
      return edgeToken(value, ctx.ownerLocalId);
    }
    if (Array.isArray(value)) return value.map((entry) => projectValue(entry, ctx));
    if (value && typeof value === 'object') {
      const out = {};
      for (const key of Object.keys(value).sort()) out[key] = projectValue(value[key], ctx);
      return out;
    }
    return value ?? null;
  }

  function projectRecord(record, ownerLocalId) {
    const ctx = {ownerLocalId, rewritten: 0};
    const out = {kind: record.kind};
    for (const field of Object.keys(record).sort()) {
      if (field === 'kind') continue;
      if (field === 'id' || field === 'imageId' || field === '_version'
        || field === 'updatedAt' || field === 'metadata') continue;
      out[field] = projectValue(record[field], ctx);
    }
    return {projected: out, rewritten: ctx.rewritten};
  }

  function assignLocalId(ref) {
    const identity = [ref.imageId, ref.objectId];
    let localId = sourceToLocal.get(identity);
    if (localId === undefined) {
      localId = `r${nextLocal}`;
      nextLocal += 1;
      sourceToLocal.set(identity, localId);
      if (includeSourceMap) {
        localToSourceRef[localId] = objectRef(ref.imageId, ref.objectId);
      }
    }
    return localId;
  }

  for (const [rootKey, ref] of sortedRoots) {
    const localId = assignLocalId(ref);
    rootLocalIds[rootKey] = localId;
    queue.push({localId, ref});
  }

  const projected = new Set();
  while (queue.length > 0) {
    const {localId, ref} = queue.shift();
    if (projected.has(localId)) continue;
    // eslint-disable-next-line no-await-in-loop
    const record = await images.getRecord(ref.imageId, ref.objectId);
    if (!record) {
      fail(`graph bundle export failed: required internal record is missing: ${ref.imageId}/${ref.objectId}`, {localId});
    }
    const ownedRefs = referencesOfRecord(record);
    const internalInEdgeOrder = [];
    for (const edgeRef of ownedRefs) {
      if (isPinnedRef(edgeRef)) continue;
      if (policy.classify(edgeRef) === 'internal') {
        const targetLocalId = assignLocalId(edgeRef);
        internalInEdgeOrder.push({localId: targetLocalId, ref: edgeRef});
      }
    }
    const result = projectRecord(record, localId);
    if (ownedRefs.length !== result.rewritten) {
      fail(
        `reference enumeration/projection mismatch for ${record.kind}: referencesOfRecord reports ${ownedRefs.length} refs but the projection rewrote ${result.rewritten}`,
        {localId, kind: record.kind},
      );
    }
    records[localId] = result.projected;
    projected.add(localId);
    for (const target of internalInEdgeOrder) queue.push(target);
  }

  const bundle = {
    format: GRAPH_BUNDLE_V1,
    roots: rootLocalIds,
    records,
    externals,
  };

  assertGraphBundleV1(bundle);
  const contentIdentity = contentIdentityForBundle(bundle, {crypto});
  if (includeSourceMap) {
    return {bundle, contentIdentity, localToSourceRef: Object.freeze(localToSourceRef)};
  }
  return {bundle, contentIdentity};
}

async function exportGraphBundle(options = {}) {
  return await exportGraphBundleInternal({...options, includeSourceMap: false});
}

async function exportGraphBundleWithSourceMap(options = {}) {
  return await exportGraphBundleInternal({...options, includeSourceMap: true});
}

async function extractSubBundleFromBundle({bundle, rootLocalId, rootKey = 'root', crypto} = {}) {
  assertGraphBundleV1(bundle);
  if (typeof rootLocalId !== 'string' || !Object.hasOwn(bundle.records, rootLocalId)) {
    throw new TypeError(`rootLocalId ${JSON.stringify(rootLocalId)} is not present in bundle.records`);
  }
  const VIRTUAL_IMAGE = 'bundle-virtual';
  const virtualTargetRefs = {};
  for (const localId of Object.keys(bundle.records)) {
    virtualTargetRefs[localId] = objectRef(VIRTUAL_IMAGE, localId);
  }
  const virtualExternalRefs = {};
  for (const [extKey, desc] of Object.entries(bundle.externals)) {
    virtualExternalRefs[extKey] = objectRef(desc.imageId, desc.objectId);
  }
  const virtualImages = {
    async getRecord(_img, localId) {
      const entry = bundle.records[localId];
      if (!entry) return null;
      const {kind, ...portableFields} = entry;
      const rewritten = rewritePortableValue(portableFields, virtualTargetRefs, virtualExternalRefs);
      return {
        kind,
        id: localId,
        imageId: VIRTUAL_IMAGE,
        updatedAt: '1970-01-01T00:00:00.000Z',
        metadata: {},
        ...(kind === 'object' ? {behavior: rewritten.behavior ?? null, slots: rewritten.slots ?? {}} : {}),
        ...(kind === 'shape' ? {slots: rewritten.slots ?? []} : {}),
        ...(kind === 'code-artifact'
          ? {
              languageId: rewritten.languageId ?? null,
              logicalPath: rewritten.logicalPath ?? null,
              dependencies: rewritten.dependencies ?? [],
              derivedFrom: rewritten.derivedFrom ?? [],
            }
          : {}),
        ...(kind === 'lexical-environment' ? {parent: rewritten.parent ?? null, bindings: rewritten.bindings ?? {}} : {}),
        ...(kind === 'block' ? {environment: rewritten.environment ?? null} : {}),
        ...rewritten,
      };
    },
  };
  const exported = await exportGraphBundleWithSourceMap({
    images: virtualImages,
    roots: {[rootKey]: objectRef(VIRTUAL_IMAGE, rootLocalId)},
    referencePolicy: {classify: (ref) => (ref.imageId === VIRTUAL_IMAGE ? 'internal' : 'external')},
    crypto,
  });
  const subLocalToBundleLocal = {};
  for (const [subLocalId, srcRef] of Object.entries(exported.localToSourceRef)) {
    subLocalToBundleLocal[subLocalId] = srcRef.objectId;
  }
  return Object.freeze({
    bundle: exported.bundle,
    contentIdentity: exported.contentIdentity,
    subLocalToBundleLocal: Object.freeze(subLocalToBundleLocal),
  });
}

// --- IMPORT: portable graph bundle -> fresh target-Image graph (ADR 0074 §H) -----
//
// The ownership chain: this module owns bundle validation, the external-resolution
// contract, bundle-local -> target-local identity translation and portable ref
// rewriting. `GraphImageService.createRecords` owns record-model validation,
// relational validation, batch-local fresh-record visibility and the atomic
// N-records + N-history-events transaction. The importer NEVER calls the backend,
// appends history, reproduces per-kind validation, or sequences the single-record
// puts. Its ONLY durable effect is one createRecords call.

// Generic recursive portable rewrite: local-ref -> freshly minted target ref,
// external-ref -> the explicitly bound target ref. Everything else is structurally
// preserved. This transform does not know that Block has code, Object has shape,
// etc. — createRecords owns those schemas and relationships.
function rewritePortableValue(value, targetRefs, resolvedBindings) {
  if (Array.isArray(value)) return value.map((entry) => rewritePortableValue(entry, targetRefs, resolvedBindings));
  if (value && typeof value === 'object') {
    if (value.kind === 'local-ref') return targetRefs[value.localId];
    if (value.kind === 'external-ref') return resolvedBindings[value.externalKey];
    const out = {};
    for (const key of Object.keys(value)) out[key] = rewritePortableValue(value[key], targetRefs, resolvedBindings);
    return out;
  }
  return value ?? null;
}

// Freeze the fresh preparation result recursively. The plan contains only arrays,
// plain records and canonical Values constructed by this owner; it never freezes
// caller-owned bundle or binding objects.
function deepFreeze(value) {
  if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) deepFreeze(entry);
    Object.freeze(value);
  }
  return value;
}

// Prepare the complete target-side graph without publishing it (ADR 0076
// Decision 4). This is the sole owner of bundle validation, content-identity
// verification, external resolution, target-id minting and portable ref
// rewriting for BOTH standalone and managed installation. The returned record
// inputs may be appended to another owner-created batch, but never reinterpreted,
// filtered, reordered or rewritten.
async function prepareGraphBundleImport({
  images,
  targetImageId,
  bundle,
  externalBindings = {},
  expectedContentIdentity,
  preboundLocalRefs = {},
  crypto,
} = {}) {
  if (!images || typeof images.getRecord !== 'function') importFail('images must be a GraphImageService');
  if (typeof targetImageId !== 'string' || targetImageId.length === 0) importFail('targetImageId must be non-empty text');

  // (2) Validate the ENTIRE bundle — structure AND closure completeness — BEFORE
  // any durable effect. Malformed input is never silently normalized.
  try {
    assertGraphBundleV1(bundle);
  } catch (error) {
    importFail(`invalid graph bundle: ${error.message}`, {cause: error});
  }

  // (4) Verify content identity BEFORE any identity minting or publication. This
  // is the seam a Project installation later uses: the release says identity X,
  // the supplied bundle is verified to BE X before it is materialized. A mismatch
  // means ZERO createRecords calls and ZERO durable state/history.
  const actualContentIdentity = contentIdentityForBundle(bundle, {crypto});
  if (expectedContentIdentity !== undefined && expectedContentIdentity !== actualContentIdentity) {
    importFail(`graph bundle content identity mismatch: expected ${expectedContentIdentity}, actual ${actualContentIdentity}`);
  }

  // (5) External resolution. A source external descriptor is a REQUIREMENT; the
  // binding says which target-environment reference satisfies it. Source
  // descriptors are NEVER automatically reinterpreted as target refs. Exactly one
  // binding per external, no unknown/extra keys; pinnedness must match. No
  // authority is inferred from a binding, and a bound ref is not followed.
  const externalKeys = Object.keys(bundle.externals);
  const bindingKeys = Object.keys(externalBindings ?? {});
  for (const externalKey of externalKeys) {
    if (!Object.hasOwn(externalBindings, externalKey)) {
      importFail(`missing external binding for ${externalKey}`, {descriptor: bundle.externals[externalKey]});
    }
  }
  for (const bindingKey of bindingKeys) {
    if (!Object.hasOwn(bundle.externals, bindingKey)) {
      importFail(`unknown external binding key: ${JSON.stringify(bindingKey)}`);
    }
  }
  const resolvedBindings = {};
  for (const externalKey of externalKeys) {
    const descriptor = bundle.externals[externalKey];
    const binding = canonicalizeValue(externalBindings[externalKey]);
    if (descriptor.pinned) {
      if (!isPinnedRef(binding)) {
        importFail(`pinned external ${externalKey} must bind to a PinnedRef`);
      }
    } else {
      if (!isObjectRef(binding)) {
        importFail(`unpinned external ${externalKey} must bind to an unpinned ObjectRef`);
      }
      let target;
      try {
        // eslint-disable-next-line no-await-in-loop
        target = await images.getRecord(binding.imageId, binding.objectId);
      } catch (error) {
        importFail(`external binding ${externalKey} target cannot be read: ${binding.imageId}/${binding.objectId}`, {cause: error});
      }
      if (!target) {
        importFail(`external binding ${externalKey} target does not exist: ${binding.imageId}/${binding.objectId}`);
      }
    }
    resolvedBindings[externalKey] = binding;
  }

  const preboundKeys = Object.keys(preboundLocalRefs ?? {});
  const resolvedPrebound = {};
  for (const localId of preboundKeys) {
    if (!Object.hasOwn(bundle.records, localId)) {
      importFail(`unknown prebound localId: ${JSON.stringify(localId)}`);
    }
    const ref = canonicalizeValue(preboundLocalRefs[localId]);
    if (!isObjectRef(ref) || ref.imageId !== targetImageId) {
      importFail(`prebound localId ${localId} must bind to an unpinned ObjectRef in targetImageId ${targetImageId}`);
    }
    // eslint-disable-next-line no-await-in-loop
    const existing = await images.getRecord(ref.imageId, ref.objectId);
    if (!existing) {
      importFail(`prebound localId ${localId} target does not exist: ${ref.imageId}/${ref.objectId}`);
    }
    resolvedPrebound[localId] = ref;
  }

  // (6) Mint ALL target identities FIRST, in canonical localId order (or reuse
  // prebound content-addressed target refs).
  const activeCrypto = crypto ?? getDefaultCryptoProvider();
  const localIds = orderedLocalIds(bundle);
  const targetRefs = {};
  for (const localId of localIds) {
    targetRefs[localId] = Object.hasOwn(resolvedPrebound, localId)
      ? resolvedPrebound[localId]
      : objectRef(targetImageId, activeCrypto.uuid());
  }

  // (7) Rewrite every non-prebound record generically, in canonical localId order.
  const recordInputs = localIds
    .filter((localId) => !Object.hasOwn(resolvedPrebound, localId))
    .map((localId) => {
      const {kind, ...portableFields} = bundle.records[localId];
      return {
        kind,
        id: targetRefs[localId].objectId,
        ...rewritePortableValue(portableFields, targetRefs, resolvedBindings),
      };
    });

  // Expose only semantic roots. The complete localId -> target ref table is
  // transient implementation state and is not persisted or returned.
  const roots = {};
  for (const [rootKey, localId] of Object.entries(bundle.roots)) {
    roots[rootKey] = targetRefs[localId];
  }

  return deepFreeze({roots, recordInputs, contentIdentity: actualContentIdentity});
}

async function importGraphBundle({images, targetImageId, bundle, externalBindings = {}, expectedContentIdentity, crypto} = {}) {
  if (!images || typeof images.createRecords !== 'function') importFail('images must be a GraphImageService');

  const plan = await prepareGraphBundleImport({
    images,
    targetImageId,
    bundle,
    externalBindings,
    expectedContentIdentity,
    crypto,
  });

  // (8) Publish ONCE. If createRecords refuses (wrong-kind relationship,
  // collision, malformed reconstructed record, backend failure), its proven
  // all-or-none atomicity is the whole failure story — the importer performs no
  // prior put, no cleanup transaction, no rollback and no selective id
  // regeneration inside a partly-rewritten graph.
  try {
    await images.createRecords(targetImageId, plan.recordInputs);
  } catch (error) {
    importFail(`graph bundle import publication failed: ${error.message}`, {cause: error});
  }

  return {roots: plan.roots, contentIdentity: plan.contentIdentity};
}

export {
  GRAPH_BUNDLE_V1,
  GraphBundleExportError,
  GraphBundleImportError,
  assertGraphBundleV1,
  contentIdentityForBundle,
  defaultReferencePolicy,
  exportGraphBundle,
  exportGraphBundleWithSourceMap,
  extractSubBundleFromBundle,
  importGraphBundle,
  prepareGraphBundleImport,
};

import {assertGraphBundleV1, contentIdentityForBundle} from './bundle.js';
import {RELOCATED_RECORD_KIND, SWEPT_RECORD_KIND} from './locator.js';

const IMAGE_RECORD_DIFF_V1 = 'lagrange-image-record-diff/v1';
const GRAPH_BUNDLE_DIFF_V1 = 'lagrange-graph-bundle-diff/v1';

const TRANSIENT_RECORD_KEYS = new Set(['_version', 'createdAt', 'updatedAt']);

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function canonicalClone(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    return Object.freeze(value.map((item) => canonicalClone(item)));
  }
  const result = {};
  for (const key of Object.keys(value).sort(compareText)) {
    if (value[key] !== undefined) {
      result[key] = canonicalClone(value[key]);
    }
  }
  return Object.freeze(result);
}

function normalizeRecordForDiff(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) {
    throw new TypeError('diff record must be a plain record');
  }
  if (typeof record.id !== 'string' || record.id.length === 0) {
    throw new TypeError('diff record.id must be a non-empty string');
  }
  if (typeof record.kind !== 'string' || record.kind.length === 0) {
    throw new TypeError(`diff record ${record.id} must declare a non-empty kind`);
  }
  const stripped = {};
  for (const key of Object.keys(record).sort(compareText)) {
    if (TRANSIENT_RECORD_KEYS.has(key) || record[key] === undefined) continue;
    stripped[key] = canonicalClone(record[key]);
  }
  return Object.freeze(stripped);
}

function canonicalJson(value) {
  return JSON.stringify(canonicalClone(value));
}

function computeSlotChanges(beforeSlots = {}, afterSlots = {}) {
  const beforeKeys = Object.keys(beforeSlots).sort(compareText);
  const afterKeys = Object.keys(afterSlots).sort(compareText);
  const beforeSet = new Set(beforeKeys);
  const afterSet = new Set(afterKeys);

  const added = [];
  const removed = [];
  const modified = [];

  for (const slotId of afterKeys) {
    if (!beforeSet.has(slotId)) {
      added.push(Object.freeze({slotId, value: canonicalClone(afterSlots[slotId])}));
    }
  }
  for (const slotId of beforeKeys) {
    if (!afterSet.has(slotId)) {
      removed.push(Object.freeze({slotId, value: canonicalClone(beforeSlots[slotId])}));
    } else if (canonicalJson(beforeSlots[slotId]) !== canonicalJson(afterSlots[slotId])) {
      modified.push(
        Object.freeze({
          slotId,
          before: canonicalClone(beforeSlots[slotId]),
          after: canonicalClone(afterSlots[slotId]),
        }),
      );
    }
  }
  return Object.freeze({
    added: Object.freeze(added),
    removed: Object.freeze(removed),
    modified: Object.freeze(modified),
  });
}

function diffImageRecords({
  fromRecords,
  toRecords,
  fromImageId = null,
  toImageId = null,
  fromFrontier = null,
  toFrontier = null,
} = {}) {
  if (!Array.isArray(fromRecords)) throw new TypeError('fromRecords must be an array');
  if (!Array.isArray(toRecords)) throw new TypeError('toRecords must be an array');

  const fromMap = new Map();
  for (const raw of fromRecords) {
    if (raw?.kind === RELOCATED_RECORD_KIND || raw?.kind === SWEPT_RECORD_KIND) continue;
    const normalized = normalizeRecordForDiff(raw);
    if (fromMap.has(normalized.id)) {
      throw new TypeError(`duplicate record id in fromRecords: ${normalized.id}`);
    }
    fromMap.set(normalized.id, normalized);
  }

  const toMap = new Map();
  for (const raw of toRecords) {
    if (raw?.kind === RELOCATED_RECORD_KIND || raw?.kind === SWEPT_RECORD_KIND) continue;
    const normalized = normalizeRecordForDiff(raw);
    if (toMap.has(normalized.id)) {
      throw new TypeError(`duplicate record id in toRecords: ${normalized.id}`);
    }
    toMap.set(normalized.id, normalized);
  }

  const allIds = [...new Set([...fromMap.keys(), ...toMap.keys()])].sort(compareText);
  const added = [];
  const removed = [];
  const modified = [];
  let unchangedCount = 0;

  for (const id of allIds) {
    const before = fromMap.get(id) ?? null;
    const after = toMap.get(id) ?? null;
    if (!before) {
      added.push(Object.freeze({id, kind: after.kind, record: after}));
      continue;
    }
    if (!after) {
      removed.push(Object.freeze({id, kind: before.kind, record: before}));
      continue;
    }
    // Strip imageId difference when comparing records across two distinct images.
    const beforeComparable = fromImageId && toImageId && fromImageId !== toImageId
      ? {...before, imageId: undefined}
      : before;
    const afterComparable = fromImageId && toImageId && fromImageId !== toImageId
      ? {...after, imageId: undefined}
      : after;
    if (canonicalJson(beforeComparable) === canonicalJson(afterComparable)) {
      unchangedCount += 1;
      continue;
    }
    const fieldKeys = [...new Set([...Object.keys(beforeComparable), ...Object.keys(afterComparable)])]
      .filter((key) => key !== 'id' && key !== 'imageId')
      .sort(compareText);
    const changedFields = fieldKeys.filter(
      (key) => canonicalJson(beforeComparable[key]) !== canonicalJson(afterComparable[key]),
    );
    const slotChanges = before.kind === 'object' && after.kind === 'object'
      ? computeSlotChanges(before.slots, after.slots)
      : null;
    modified.push(
      Object.freeze({
        id,
        kind: after.kind,
        before,
        after,
        changedFields: Object.freeze(changedFields),
        slotChanges,
      }),
    );
  }

  return Object.freeze({
    format: IMAGE_RECORD_DIFF_V1,
    fromImageId,
    toImageId,
    fromFrontier,
    toFrontier,
    identical: added.length === 0 && removed.length === 0 && modified.length === 0,
    unchangedCount,
    added: Object.freeze(added),
    removed: Object.freeze(removed),
    modified: Object.freeze(modified),
  });
}

function assertFrontierNumber(value, currentFrontier, label) {
  const num = typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : value;
  if (!Number.isSafeInteger(num) || num < 0) {
    throw new TypeError(`${label} must be a non-negative safe integer`);
  }
  if (num > currentFrontier) {
    throw new RangeError(`${label} (${num}) exceeds current committed frontier (${currentFrontier})`);
  }
  return num;
}

function replayHistoryEventsToFrontier(events, frontier) {
  const byId = new Map();
  for (const event of events) {
    const rev = event?.revision ?? event?._revision ?? 0;
    if (rev > frontier) break;
    switch (event?.type) {
      case 'shape.put':
        if (event.shape?.id) byId.set(event.shape.id, structuredClone(event.shape));
        break;
      case 'object.put':
        if (event.object?.id) byId.set(event.object.id, structuredClone(event.object));
        break;
      case 'code-artifact.put':
        if (event.artifact?.id) byId.set(event.artifact.id, structuredClone(event.artifact));
        break;
      case 'lexical-environment.put':
        if (event.environment?.id) byId.set(event.environment.id, structuredClone(event.environment));
        break;
      case 'block.put':
        if (event.block?.id) byId.set(event.block.id, structuredClone(event.block));
        break;
      case 'object.relocated':
      case 'record.relocated':
        if (event.objectId) byId.delete(event.objectId);
        if (event.recordId) byId.delete(event.recordId);
        break;
      case 'record.swept':
        if (event.recordId) byId.delete(event.recordId);
        break;
      default:
        break;
    }
  }
  return Object.freeze(
    [...byId.entries()]
      .sort(([left], [right]) => compareText(left, right))
      .map(([, record]) => Object.freeze(record)),
  );
}

async function reconstructImageRecordsAtFrontier({images, imageId, frontier} = {}) {
  if (!images || typeof images.frontier !== 'function' || typeof images.history !== 'function') {
    throw new TypeError('reconstructImageRecordsAtFrontier requires an ImageService with frontier() and history()');
  }
  if (typeof imageId !== 'string' || imageId.length === 0) {
    throw new TypeError('imageId must be a non-empty string');
  }
  const currentFrontier = await images.frontier(imageId);
  const targetFrontier = assertFrontierNumber(frontier, currentFrontier, 'frontier');
  const events = await images.history(imageId);
  return replayHistoryEventsToFrontier(events, targetFrontier);
}

async function diffImageFrontiers({images, imageId, fromFrontier, toFrontier} = {}) {
  if (!images || typeof images.frontier !== 'function' || typeof images.history !== 'function') {
    throw new TypeError('diffImageFrontiers requires an ImageService with frontier() and history()');
  }
  if (typeof imageId !== 'string' || imageId.length === 0) {
    throw new TypeError('imageId must be a non-empty string');
  }
  const currentFrontier = await images.frontier(imageId);
  const resolvedFrom = assertFrontierNumber(fromFrontier, currentFrontier, 'fromFrontier');
  const resolvedTo = assertFrontierNumber(toFrontier, currentFrontier, 'toFrontier');
  const events = await images.history(imageId);
  const fromRecords = replayHistoryEventsToFrontier(events, resolvedFrom);
  const toRecords = replayHistoryEventsToFrontier(events, resolvedTo);
  return diffImageRecords({
    fromRecords,
    toRecords,
    fromImageId: imageId,
    toImageId: imageId,
    fromFrontier: resolvedFrom,
    toFrontier: resolvedTo,
  });
}

function diffGraphBundles(fromBundleInput, toBundleInput) {
  const fromBundle = fromBundleInput?.bundle ?? fromBundleInput;
  const toBundle = toBundleInput?.bundle ?? toBundleInput;
  assertGraphBundleV1(fromBundle);
  assertGraphBundleV1(toBundle);
  const fromContentIdentity = contentIdentityForBundle(fromBundle);
  const toContentIdentity = contentIdentityForBundle(toBundle);

  const fromByLocalId = new Map(
    Object.entries(fromBundle.records).map(([localId, entry]) => [localId, canonicalClone(entry)]),
  );
  const toByLocalId = new Map(
    Object.entries(toBundle.records).map(([localId, entry]) => [localId, canonicalClone(entry)]),
  );
  const allLocalIds = [...new Set([...fromByLocalId.keys(), ...toByLocalId.keys()])].sort(compareText);

  const addedRecords = [];
  const removedRecords = [];
  const modifiedRecords = [];
  for (const localId of allLocalIds) {
    const before = fromByLocalId.get(localId) ?? null;
    const after = toByLocalId.get(localId) ?? null;
    if (!before) {
      addedRecords.push(Object.freeze({localId, kind: after.kind, record: after}));
    } else if (!after) {
      removedRecords.push(Object.freeze({localId, kind: before.kind, record: before}));
    } else if (canonicalJson(before) !== canonicalJson(after)) {
      modifiedRecords.push(Object.freeze({localId, kind: after.kind, before, after}));
    }
  }

  const rootsChanged = canonicalJson(fromBundle.roots) !== canonicalJson(toBundle.roots);
  return Object.freeze({
    format: GRAPH_BUNDLE_DIFF_V1,
    fromContentIdentity,
    toContentIdentity,
    identical: fromContentIdentity === toContentIdentity,
    rootsChanged,
    addedRecords: Object.freeze(addedRecords),
    removedRecords: Object.freeze(removedRecords),
    modifiedRecords: Object.freeze(modifiedRecords),
  });
}

export {
  GRAPH_BUNDLE_DIFF_V1,
  IMAGE_RECORD_DIFF_V1,
  diffGraphBundles,
  diffImageFrontiers,
  diffImageRecords,
  normalizeRecordForDiff,
  reconstructImageRecordsAtFrontier,
};

// Ensure-exact-or-create for durable records at deterministic ids.
//
// The rule this substrate applies everywhere a record's id is derived rather than minted:
//
//   absent                  -> create
//   present and identical   -> reuse, write nothing
//   present and different   -> fail, overwrite nothing
//
// It lives here, language-neutral, because both the Symmetric Smalltalk builders and the WASM tree
// installers write deterministic ids and both owe the same convergence guarantee. Two copies would
// be two chances to disagree about what "identical" means.
import {SHAPE_INDEXED} from '../object/model.js';

class RecordConflictError extends TypeError {
  constructor(kind, imageId, objectId) {
    super(`${kind} ${imageId}/${objectId} already exists and differs; refusing to overwrite it`);
    this.name = 'RecordConflictError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

// Key order is not part of a record's meaning, so compare a canonical projection rather than
// whatever order the caller or the backend happened to produce.
function canonicalRecordJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalRecordJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalRecordJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value ?? null);
}

// "Exact" for a code artifact includes `dependencies` and `derivedFrom`: those are durable semantic
// and provenance edges, so an artifact differing there is a different artifact. Matching provenance
// is not matching output.
function codeArtifactProjection(record) {
  return canonicalRecordJson({
    representation: record.representation ?? null,
    languageId: record.languageId ?? null,
    content: record.content ?? null,
    dependencies: record.dependencies ?? [],
    derivedFrom: record.derivedFrom ?? [],
    metadata: record.metadata ?? {},
  });
}

function blockProjection(record) {
  return canonicalRecordJson({
    code: record.code ?? null,
    environment: record.environment ?? null,
    metadata: record.metadata ?? {},
  });
}

function lexicalEnvironmentProjection(record) {
  return canonicalRecordJson({
    parent: record.parent ?? null,
    bindings: record.bindings ?? {},
    metadata: record.metadata ?? {},
  });
}

// ADR 0060. The durable object record carries `indexed` only for an indexed Shape, so the
// projection includes it only when present — matching how putObject stores it.
function objectProjection(record) {
  return canonicalRecordJson({
    shape: record.shape ?? null,
    behavior: record.behavior ?? null,
    slots: record.slots ?? {},
    ...(Object.hasOwn(record, 'indexed') ? {indexed: record.indexed} : {}),
    metadata: record.metadata ?? {},
  });
}

// A Shape's meaning is its LAYOUT: named slots and the indexed declaration (ADR 0047: absence of
// `indexed` is the old `none` meaning, and a values Shape must never compare equal to a no-indexed
// Shape by accident). Metadata is provenance and does not decide whether two Shapes are the same.
function shapeProjection(record) {
  return canonicalRecordJson({
    slots: record.slots ?? [],
    indexed: Object.hasOwn(record, 'indexed') ? record.indexed : SHAPE_INDEXED.NONE,
  });
}

const defaultConflict = (kind, imageId, id) => new RecordConflictError(kind, imageId, id);

// THE ensure-exact-or-create core, including its concurrency rule (bead lagrange-images-ea8):
//
//   read absent -> INSERT-ONLY create (the image service's expectedVersion:0 CAS in one backend
//                  transaction, so a record is never overwritten or half-written)
//   the insert loses the CAS -> another caller created the record between our read and our
//                  insert; re-read and treat the WINNER as the authority: identical -> converge on
//                  it, different -> conflict. Which contender wins scheduling never changes the
//                  outcome, and a retry after the winner commits is idempotent.
//   read present -> identical reuses, different conflicts, nothing is written.
//
// Every per-kind ensure below is this rule over its kind's read/insert/projection; none of them
// decides the rule again.
//
// Two modes, one rule. EXACT (default): the record is immutable by construction, so a present or
// winning record must be IDENTICAL to be adopted. SEED (`seed: true`): the desired record is only
// the initial value of a record that is mutated afterwards through its own CAS (a registry that
// is appended to, a companion whose values change), so a present or winning record is adopted AS
// IT IS — the caller applies its own domain check to what it gets back — and only creation is
// decided here. Neither mode ever overwrites.
async function ensureRecord({kind, imageId, desired, read, insert, projection, conflict, seed = false}) {
  const adopt = (record) => {
    if (!seed && projection(desired) !== projection(record)) throw conflict(kind, imageId, desired.id);
    return record;
  };
  const existing = await read();
  if (existing) return adopt(existing);
  try {
    return await insert();
  } catch (error) {
    if (error?.name !== 'VersionConflictError') throw error;
    const winner = await read();
    // No readable winner of this kind means the id is occupied by something that is not this
    // kind of record: a conflicting occupant, never normalized into success.
    if (!winner) throw conflict(kind, imageId, desired.id);
    return adopt(winner);
  }
}

// The ONE Shape admission owner. Reads through getRecord so a non-Shape occupant of the id is a
// conflict rather than "absent"; inserts through the insert-only putShape.
async function ensureShape(images, imageId, desired, {conflict = defaultConflict} = {}) {
  const read = async () => {
    const record = typeof images.getRecord === 'function'
      ? await images.getRecord(imageId, desired.id)
      : await images.getShape(imageId, desired.id);
    if (!record) return null;
    if (record.kind !== 'shape') throw conflict('shape', imageId, desired.id);
    return record;
  };
  return await ensureRecord({
    kind: 'shape', imageId, desired, read, conflict, projection: shapeProjection,
    insert: () => images.putShape(imageId, desired),
  });
}

async function ensureCodeArtifact(images, imageId, desired, {conflict = defaultConflict} = {}) {
  return await ensureRecord({
    kind: 'code artifact', imageId, desired, conflict, projection: codeArtifactProjection,
    read: () => images.getCodeArtifact(imageId, desired.id),
    insert: () => images.putCodeArtifact(imageId, desired),
  });
}

// Ensure-exact-or-create for a SMALL GRAPH of code artifacts that must become durable together
// (ADR 0080-adjacent; ygi): all absent -> ONE insert-only createRecords batch (so no member is ever
// visible without the others); all present and identical -> reuse, write nothing; anything else
// (a partial graph, or a differing member) -> fail, overwrite nothing. The atomicity envelope is
// ImageService.createRecords' — this owner adds only the convergence rule.
async function ensureCodeArtifacts(images, imageId, desiredList, {conflict = defaultConflict} = {}) {
  if (!Array.isArray(desiredList) || desiredList.length === 0) throw new TypeError('ensureCodeArtifacts requires a non-empty list');
  const readAll = async () => {
    const records = [];
    for (const desired of desiredList) records.push(await images.getCodeArtifact(imageId, desired.id));
    return records;
  };
  const adoptAll = (records) => {
    for (const [index, desired] of desiredList.entries()) {
      if (!records[index] || codeArtifactProjection(desired) !== codeArtifactProjection(records[index])) {
        throw conflict('code artifact', imageId, desired.id);
      }
    }
    return records;
  };
  const existing = await readAll();
  if (!existing.every((record) => !record)) return adoptAll(existing);
  if (typeof images.createRecords !== 'function') throw new TypeError('ensureCodeArtifacts requires images.createRecords');
  try {
    return await images.createRecords(imageId, desiredList.map((desired) => ({kind: 'code-artifact', ...desired})));
  } catch (error) {
    if (error?.name !== 'VersionConflictError') throw error;
    // The whole batch lost to a concurrent creator (all-or-none): the winner's graph is the
    // authority — identical converges, anything else conflicts. Same rule as ensureRecord.
    return adoptAll(await readAll());
  }
}

async function ensureBlock(images, imageId, desired, {conflict = defaultConflict} = {}) {
  return await ensureRecord({
    kind: 'block', imageId, desired, conflict, projection: blockProjection,
    read: () => images.getBlock(imageId, desired.id),
    insert: () => images.putBlock(imageId, desired),
  });
}

// ADR 0052 decision 7a. Promotion writes at deterministic ids, so a retry after a lost
// acknowledgement must converge rather than mint a second identity for one closure.
async function ensureLexicalEnvironment(images, imageId, desired, {conflict = defaultConflict} = {}) {
  return await ensureRecord({
    kind: 'lexical environment', imageId, desired, conflict, projection: lexicalEnvironmentProjection,
    read: () => images.getLexicalEnvironment(imageId, desired.id),
    // Insert-only: an ensure never overwrites, even when two callers raced past the read.
    insert: () => images.putLexicalEnvironment(imageId, desired, {expectedVersion: 0}),
  });
}

// ADR 0060. Object promotion writes at a derived id, so a retry after a lost acknowledgement
// converges on the same durable object rather than minting a second identity for one transient one.
async function ensureObject(images, imageId, desired, {conflict = defaultConflict, seed = false} = {}) {
  return await ensureRecord({
    kind: 'object', imageId, desired, conflict, seed, projection: objectProjection,
    read: () => images.getObject(imageId, desired.id),
    // Insert-only: an ensure never overwrites, even when two callers raced past the read.
    insert: () => images.putObject(imageId, desired, {expectedVersion: 0}),
  });
}

// Exact objects may have been admitted individually by an older installer. Preserve those
// records and atomically create only the missing subset through the existing graph owner.
// A concurrent creator is progress only when its identical winners strictly reduce that subset;
// unrelated CAS failures and all other errors remain the caller's failure, never an open retry.
async function ensureObjects(images, imageId, desiredList, {conflict = defaultConflict} = {}) {
  if (!Array.isArray(desiredList) || desiredList.length === 0) {
    throw new TypeError('ensureObjects requires a non-empty list');
  }
  for (const method of ['getRecord', 'createRecords']) {
    if (typeof images?.[method] !== 'function') throw new TypeError(`ensureObjects requires images.${method}`);
  }
  const ids = new Set();
  for (const desired of desiredList) {
    if (!desired || typeof desired !== 'object' || Array.isArray(desired)
      || typeof desired.id !== 'string' || !desired.id || ids.has(desired.id)) {
      throw new TypeError('ensureObjects requires unique non-empty object ids');
    }
    ids.add(desired.id);
  }
  const readAll = async () => {
    const existing = new Map();
    const missing = [];
    for (const desired of desiredList) {
      const record = await images.getRecord(imageId, desired.id);
      if (!record) missing.push(desired);
      else {
        if (record.kind !== 'object' || objectProjection(desired) !== objectProjection(record)) {
          throw conflict('object', imageId, desired.id);
        }
        existing.set(desired.id, record);
      }
    }
    return {existing, missing};
  };
  let state = await readAll();
  while (state.missing.length) {
    try {
      const created = await images.createRecords(imageId, state.missing.map((desired) => ({...desired, kind: 'object'})));
      for (const record of created) state.existing.set(record.id, record);
      return desiredList.map(({id}) => state.existing.get(id));
    } catch (error) {
      if (error?.name !== 'VersionConflictError') throw error;
      const previous = new Set(state.missing.map(({id}) => id));
      const next = await readAll();
      if (next.missing.length >= previous.size || next.missing.some(({id}) => !previous.has(id))) throw error;
      state = next;
    }
  }
  return desiredList.map(({id}) => state.existing.get(id));
}

export {
  RecordConflictError,
  blockProjection,
  canonicalRecordJson,
  codeArtifactProjection,
  ensureBlock,
  ensureCodeArtifact,
  ensureCodeArtifacts,
  ensureLexicalEnvironment,
  ensureObject,
  ensureObjects,
  ensureShape,
  lexicalEnvironmentProjection,
  objectProjection,
  shapeProjection,
};

import {assertBackend} from '../backend/backend-contract.js';
import {IMAGE_COLLECTION, records} from '../image/storage-layout.js';
import {isObjectRef} from '../value/scalars.js';

const WHOLE_IMAGE_RESIDENCY = 'whole-image/v1';
const PER_OBJECT_RESIDENCY = 'per-object/v1';
const RELOCATED_RECORD_KIND = 'relocated';
const SWEPT_RECORD_KIND = 'swept';
const backendByResidency = new WeakMap();
const remoteByResidency = new WeakMap();

class ObjectResidency {
  constructor({backend, imageId, kind = WHOLE_IMAGE_RESIDENCY, objectId = undefined, remote = false}) {
    this.kind = kind;
    this.imageId = imageId;
    if (kind === PER_OBJECT_RESIDENCY) {
      this.objectId = objectId;
    }
    backendByResidency.set(this, backend);
    remoteByResidency.set(this, Boolean(remote));
    Object.freeze(this);
  }
}

function backendForResidency(residency) {
  const backend = backendByResidency.get(residency);
  if (!backend) throw new TypeError('object residency did not come from the object locator');
  return backend;
}

function isRemoteResidency(residency) {
  return Boolean(remoteByResidency.get(residency));
}

class ObjectLocator {
  #residencies = new Map();
  #objectResidencies = new Map();
  #peers = new Map();

  constructor({backend, peers = {}} = {}) {
    this.backend = assertBackend(backend);
    if (peers && typeof peers === 'object') {
      const entries = peers instanceof Map || Array.isArray(peers)
        ? peers
        : Object.entries(peers);
      for (const [nodeId, peerBackend] of entries) {
        this.registerPeer(nodeId, peerBackend);
      }
    }
  }

  registerPeer(nodeId, peerBackend) {
    if (typeof nodeId !== 'string' || nodeId.length === 0) {
      throw new TypeError('peer nodeId must be a non-empty string');
    }
    const validated = assertBackend(peerBackend);
    this.#peers.set(nodeId, validated);
    this.#residencies.clear();
    this.#objectResidencies.clear();
    return this;
  }

  unregisterPeer(nodeId) {
    this.#peers.delete(nodeId);
    this.#residencies.clear();
    this.#objectResidencies.clear();
    return this;
  }

  hasPeers() {
    return this.#peers.size > 0;
  }

  peerBackend(nodeId) {
    return this.#peers.get(nodeId) ?? null;
  }

  invalidate(ref = null) {
    if (!ref) {
      this.#residencies.clear();
      this.#objectResidencies.clear();
      return;
    }
    if (!isObjectRef(ref)) throw new TypeError('object locator invalidate requires an ObjectRef');
    this.#objectResidencies.delete(`${ref.imageId}\0${ref.objectId}`);
    this.#residencies.delete(ref.imageId);
  }

  async locateImage(imageId) {
    if (typeof imageId !== 'string' || imageId.length === 0) {
      throw new TypeError('object locator requires a non-empty imageId');
    }
    const cached = this.#residencies.get(imageId);
    if (cached) return cached;
    const localImage = await this.backend.get(IMAGE_COLLECTION, imageId);
    if (localImage) {
      const residency = new ObjectResidency({backend: this.backend, imageId, kind: WHOLE_IMAGE_RESIDENCY});
      this.#residencies.set(imageId, residency);
      return residency;
    }
    for (const [, peerBackend] of this.#peers.entries()) {
      const peerImage = await peerBackend.get(IMAGE_COLLECTION, imageId);
      if (peerImage) {
        const residency = new ObjectResidency({
          backend: peerBackend,
          imageId,
          kind: WHOLE_IMAGE_RESIDENCY,
          remote: peerBackend !== this.backend,
        });
        this.#residencies.set(imageId, residency);
        return residency;
      }
    }
    return null;
  }

  async locate(ref) {
    if (!isObjectRef(ref)) throw new TypeError('object locator requires an ObjectRef');
    if (this.#peers.size === 0) {
      return await this.locateImage(ref.imageId);
    }

    const key = `${ref.imageId}\0${ref.objectId}`;
    const cachedObject = this.#objectResidencies.get(key);
    if (cachedObject) return cachedObject;

    const localRecord = await this.backend.get(records(ref.imageId), ref.objectId);
    if (localRecord && localRecord.kind !== SWEPT_RECORD_KIND) {
      if (localRecord.kind === RELOCATED_RECORD_KIND) {
        let hopRecord = localRecord;
        let hops = 0;
        while (hopRecord?.kind === RELOCATED_RECORD_KIND && hops <= this.#peers.size) {
          hops += 1;
          const peerBackend = this.#peers.get(hopRecord.node);
          if (!peerBackend) break;
          const peerRecord = await peerBackend.get(records(ref.imageId), ref.objectId);
          if (!peerRecord || peerRecord.kind === SWEPT_RECORD_KIND) break;
          if (peerRecord.kind !== RELOCATED_RECORD_KIND) {
            const residency = new ObjectResidency({
              backend: peerBackend,
              imageId: ref.imageId,
              kind: PER_OBJECT_RESIDENCY,
              objectId: ref.objectId,
              remote: peerBackend !== this.backend,
            });
            this.#objectResidencies.set(key, residency);
            return residency;
          }
          hopRecord = peerRecord;
        }
      } else {
        const localImage = await this.backend.get(IMAGE_COLLECTION, ref.imageId);
        if (localImage) {
          return await this.locateImage(ref.imageId);
        }
        const residency = new ObjectResidency({
          backend: this.backend,
          imageId: ref.imageId,
          kind: PER_OBJECT_RESIDENCY,
          objectId: ref.objectId,
          remote: false,
        });
        this.#objectResidencies.set(key, residency);
        return residency;
      }
    }

    for (const [, peerBackend] of this.#peers.entries()) {
      const peerRecord = await peerBackend.get(records(ref.imageId), ref.objectId);
      if (peerRecord && peerRecord.kind !== RELOCATED_RECORD_KIND && peerRecord.kind !== SWEPT_RECORD_KIND) {
        const peerImage = await peerBackend.get(IMAGE_COLLECTION, ref.imageId);
        if (peerImage) {
          return await this.locateImage(ref.imageId);
        }
        const residency = new ObjectResidency({
          backend: peerBackend,
          imageId: ref.imageId,
          kind: PER_OBJECT_RESIDENCY,
          objectId: ref.objectId,
          remote: peerBackend !== this.backend,
        });
        this.#objectResidencies.set(key, residency);
        return residency;
      }
    }

    return await this.locateImage(ref.imageId);
  }
}

export {
  ObjectLocator,
  PER_OBJECT_RESIDENCY,
  RELOCATED_RECORD_KIND,
  SWEPT_RECORD_KIND,
  WHOLE_IMAGE_RESIDENCY,
  backendForResidency,
  isRemoteResidency,
};

import {RELOCATED_RECORD_KIND, SWEPT_RECORD_KIND} from './locator.js';
import {normalizeRecordForDiff, reconstructImageRecordsAtFrontier} from './diff.js';
import {isObjectRef, objectRef} from '../value/index.js';

const IMAGE_RECORD_MERGE_V1 = 'lagrange-image-record-merge/v1';

const MERGE_CONFLICT_KINDS = Object.freeze({
  ADD_ADD: 'add-add',
  DELETE_MODIFY: 'delete-modify',
  KIND_CONFLICT: 'kind-conflict',
  OBJECT_CONFLICT: 'object-conflict',
  LEXICAL_ENVIRONMENT_CONFLICT: 'lexical-environment-conflict',
  RECORD_CONFLICT: 'record-conflict',
});

class MergeConflictError extends Error {
  constructor(message, {conflicts = []} = {}) {
    super(message);
    this.name = 'MergeConflictError';
    this.conflicts = Object.freeze([...conflicts]);
  }
}

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function canonicalClone(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    return Object.freeze(value.map((item) => canonicalClone(item)));
  }
  const result = {};
  for (const key of Object.keys(value).sort(compareText)) {
    if (value[key] !== undefined) {
      result[key] = canonicalClone(value[key]);
    }
  }
  return Object.freeze(result);
}

function canonicalJson(value) {
  return JSON.stringify(canonicalClone(value));
}

function rehomeValueToImage(value, fromImageId, targetImageId) {
  if (!fromImageId || !targetImageId || fromImageId === targetImageId) {
    return canonicalClone(value);
  }
  if (isObjectRef(value)) {
    return value.imageId === fromImageId
      ? objectRef(targetImageId, value.objectId)
      : canonicalClone(value);
  }
  if (Array.isArray(value)) {
    return Object.freeze(value.map((item) => rehomeValueToImage(item, fromImageId, targetImageId)));
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value).sort(compareText)) {
      if (value[key] !== undefined) {
        out[key] = rehomeValueToImage(value[key], fromImageId, targetImageId);
      }
    }
    return Object.freeze(out);
  }
  return value;
}

function rehomeRecordToImage(record, fromImageId, targetImageId) {
  const normalized = normalizeRecordForDiff(record);
  if (!fromImageId || !targetImageId || fromImageId === targetImageId) {
    return normalized;
  }
  const rehomed = rehomeValueToImage(normalized, fromImageId, targetImageId);
  if (typeof rehomed.imageId === 'string') {
    return canonicalClone({...rehomed, imageId: targetImageId});
  }
  return rehomed;
}

function indexRecordsById(records, label, fromImageId, targetImageId) {
  if (!Array.isArray(records)) {
    throw new TypeError(`${label} must be an array`);
  }
  const map = new Map();
  for (const raw of records) {
    if (raw?.kind === RELOCATED_RECORD_KIND || raw?.kind === SWEPT_RECORD_KIND) continue;
    const normalized = rehomeRecordToImage(raw, fromImageId, targetImageId);
    if (map.has(normalized.id)) {
      throw new TypeError(`duplicate record id in ${label}: ${normalized.id}`);
    }
    map.set(normalized.id, normalized);
  }
  return map;
}

function mergeKeyValueMapThreeWay(baseMap = {}, leftMap = {}, rightMap = {}) {
  const allKeys = [
    ...new Set([...Object.keys(baseMap), ...Object.keys(leftMap), ...Object.keys(rightMap)]),
  ].sort(compareText);
  const merged = {};
  const conflicts = [];

  for (const key of allKeys) {
    const hasBase = Object.hasOwn(baseMap, key);
    const hasLeft = Object.hasOwn(leftMap, key);
    const hasRight = Object.hasOwn(rightMap, key);
    const baseVal = hasBase ? baseMap[key] : undefined;
    const leftVal = hasLeft ? leftMap[key] : undefined;
    const rightVal = hasRight ? rightMap[key] : undefined;

    const leftSameAsBase = hasLeft === hasBase && canonicalJson(leftVal) === canonicalJson(baseVal);
    const rightSameAsBase = hasRight === hasBase && canonicalJson(rightVal) === canonicalJson(baseVal);
    const leftSameAsRight = hasLeft === hasRight && canonicalJson(leftVal) === canonicalJson(rightVal);

    if (leftSameAsBase) {
      if (hasRight) merged[key] = canonicalClone(rightVal);
      continue;
    }
    if (rightSameAsBase) {
      if (hasLeft) merged[key] = canonicalClone(leftVal);
      continue;
    }
    if (leftSameAsRight) {
      if (hasLeft) merged[key] = canonicalClone(leftVal);
      continue;
    }
    conflicts.push(
      Object.freeze({
        key,
        base: hasBase ? canonicalClone(baseVal) : null,
        left: hasLeft ? canonicalClone(leftVal) : null,
        right: hasRight ? canonicalClone(rightVal) : null,
      }),
    );
    if (hasBase) {
      merged[key] = canonicalClone(baseVal);
    }
  }

  return {
    merged: Object.freeze(merged),
    conflicts: Object.freeze(conflicts),
  };
}

function mergeObjectRefSetThreeWay(baseIndexed = [], leftIndexed = [], rightIndexed = []) {
  const toMap = (arr) => new Map(arr.map((ref) => [ref.objectId, ref]));
  const baseMap = toMap(baseIndexed);
  const leftMap = toMap(leftIndexed);
  const rightMap = toMap(rightIndexed);
  const allIds = [
    ...new Set([...baseMap.keys(), ...leftMap.keys(), ...rightMap.keys()]),
  ].sort(compareText);
  const merged = [];
  for (const objectId of allIds) {
    const inBase = baseMap.has(objectId);
    const inLeft = leftMap.has(objectId);
    const inRight = rightMap.has(objectId);
    if (!inBase) {
      if (inLeft || inRight) {
        merged.push(canonicalClone(leftMap.get(objectId) ?? rightMap.get(objectId)));
      }
    } else if (inLeft && inRight) {
      merged.push(canonicalClone(leftMap.get(objectId)));
    }
  }
  return {merged: Object.freeze(merged), conflict: null};
}

function mergeIndexedArrayThreeWay(baseIndexed, leftIndexed, rightIndexed, {asObjectRefSet = false} = {}) {
  const leftSameAsBase = canonicalJson(leftIndexed) === canonicalJson(baseIndexed);
  const rightSameAsBase = canonicalJson(rightIndexed) === canonicalJson(baseIndexed);
  const leftSameAsRight = canonicalJson(leftIndexed) === canonicalJson(rightIndexed);

  if (leftSameAsBase) {
    return {merged: rightIndexed ? canonicalClone(rightIndexed) : undefined, conflict: null};
  }
  if (rightSameAsBase || leftSameAsRight) {
    return {merged: leftIndexed ? canonicalClone(leftIndexed) : undefined, conflict: null};
  }

  if (
    asObjectRefSet
    && Array.isArray(baseIndexed)
    && Array.isArray(leftIndexed)
    && Array.isArray(rightIndexed)
    && baseIndexed.every(isObjectRef)
    && leftIndexed.every(isObjectRef)
    && rightIndexed.every(isObjectRef)
  ) {
    return mergeObjectRefSetThreeWay(baseIndexed, leftIndexed, rightIndexed);
  }

  if (
    Array.isArray(baseIndexed) &&
    Array.isArray(leftIndexed) &&
    Array.isArray(rightIndexed) &&
    baseIndexed.length === leftIndexed.length &&
    baseIndexed.length === rightIndexed.length
  ) {
    const mergedElements = [];
    const elementConflicts = [];
    for (let index = 0; index < baseIndexed.length; index += 1) {
      const bElem = baseIndexed[index];
      const lElem = leftIndexed[index];
      const rElem = rightIndexed[index];
      const lUnchanged = canonicalJson(lElem) === canonicalJson(bElem);
      const rUnchanged = canonicalJson(rElem) === canonicalJson(bElem);
      const lrSame = canonicalJson(lElem) === canonicalJson(rElem);
      if (lUnchanged) {
        mergedElements.push(canonicalClone(rElem));
      } else if (rUnchanged || lrSame) {
        mergedElements.push(canonicalClone(lElem));
      } else {
        elementConflicts.push(
          Object.freeze({
            index,
            base: canonicalClone(bElem),
            left: canonicalClone(lElem),
            right: canonicalClone(rElem),
          }),
        );
        mergedElements.push(canonicalClone(bElem));
      }
    }
    if (elementConflicts.length === 0) {
      return {merged: Object.freeze(mergedElements), conflict: null};
    }
    return {
      merged: Object.freeze(mergedElements),
      conflict: Object.freeze({
        base: canonicalClone(baseIndexed),
        left: canonicalClone(leftIndexed),
        right: canonicalClone(rightIndexed),
        elementConflicts: Object.freeze(elementConflicts),
      }),
    };
  }

  return {
    merged: baseIndexed ? canonicalClone(baseIndexed) : undefined,
    conflict: Object.freeze({
      base: baseIndexed ? canonicalClone(baseIndexed) : null,
      left: leftIndexed ? canonicalClone(leftIndexed) : null,
      right: rightIndexed ? canonicalClone(rightIndexed) : null,
      elementConflicts: Object.freeze([]),
    }),
  };
}

function mergeScalarFieldThreeWay(baseVal, leftVal, rightVal) {
  const leftSameAsBase = canonicalJson(leftVal) === canonicalJson(baseVal);
  const rightSameAsBase = canonicalJson(rightVal) === canonicalJson(baseVal);
  const leftSameAsRight = canonicalJson(leftVal) === canonicalJson(rightVal);

  if (leftSameAsBase) {
    return {merged: canonicalClone(rightVal), conflict: null};
  }
  if (rightSameAsBase || leftSameAsRight) {
    return {merged: canonicalClone(leftVal), conflict: null};
  }
  return {
    merged: canonicalClone(baseVal),
    conflict: Object.freeze({
      base: canonicalClone(baseVal ?? null),
      left: canonicalClone(leftVal ?? null),
      right: canonicalClone(rightVal ?? null),
    }),
  };
}

function mergeObjectRecordThreeWay(base, left, right) {
  const shapeResult = mergeScalarFieldThreeWay(base.shape, left.shape, right.shape);
  const behaviorResult = mergeScalarFieldThreeWay(
    base.behavior ?? null,
    left.behavior ?? null,
    right.behavior ?? null,
  );
  const slotsResult = mergeKeyValueMapThreeWay(base.slots ?? {}, left.slots ?? {}, right.slots ?? {});
  const isProjectLinkageSet =
    isObjectRef(base.shape) && base.shape.objectId === 'lagrange-project/project/v1';
  const indexedResult = mergeIndexedArrayThreeWay(base.indexed, left.indexed, right.indexed, {
    asObjectRefSet: isProjectLinkageSet,
  });
  const metadataResult = mergeKeyValueMapThreeWay(
    base.metadata ?? {},
    left.metadata ?? {},
    right.metadata ?? {},
  );

  const slotConflicts = slotsResult.conflicts.map(({key, base: b, left: l, right: r}) =>
    Object.freeze({slotId: key, base: b, left: l, right: r}),
  );
  const metadataConflicts = metadataResult.conflicts;

  const hasConflict =
    shapeResult.conflict !== null ||
    behaviorResult.conflict !== null ||
    slotConflicts.length > 0 ||
    indexedResult.conflict !== null ||
    metadataConflicts.length > 0;

  const mergedRecord = canonicalClone({
    ...base,
    shape: shapeResult.merged,
    behavior: behaviorResult.merged,
    slots: slotsResult.merged,
    ...(indexedResult.merged !== undefined ? {indexed: indexedResult.merged} : {}),
    metadata: metadataResult.merged,
  });

  if (!hasConflict) {
    return {mergedRecord, conflict: null};
  }

  return {
    mergedRecord,
    conflict: Object.freeze({
      id: base.id,
      kind: 'object',
      conflictKind: MERGE_CONFLICT_KINDS.OBJECT_CONFLICT,
      base,
      left,
      right,
      shapeConflict: shapeResult.conflict,
      behaviorConflict: behaviorResult.conflict,
      slotConflicts: Object.freeze(slotConflicts),
      indexedConflict: indexedResult.conflict,
      metadataConflicts: Object.freeze(metadataConflicts),
    }),
  };
}

function mergeLexicalEnvironmentRecordThreeWay(base, left, right) {
  const parentResult = mergeScalarFieldThreeWay(
    base.parent ?? null,
    left.parent ?? null,
    right.parent ?? null,
  );
  const bindingsResult = mergeKeyValueMapThreeWay(
    base.bindings ?? {},
    left.bindings ?? {},
    right.bindings ?? {},
  );
  const metadataResult = mergeKeyValueMapThreeWay(
    base.metadata ?? {},
    left.metadata ?? {},
    right.metadata ?? {},
  );

  const bindingConflicts = bindingsResult.conflicts.map(({key, base: b, left: l, right: r}) =>
    Object.freeze({bindingId: key, base: b, left: l, right: r}),
  );
  const metadataConflicts = metadataResult.conflicts;

  const hasConflict =
    parentResult.conflict !== null ||
    bindingConflicts.length > 0 ||
    metadataConflicts.length > 0;

  const mergedRecord = canonicalClone({
    ...base,
    parent: parentResult.merged,
    bindings: bindingsResult.merged,
    metadata: metadataResult.merged,
  });

  if (!hasConflict) {
    return {mergedRecord, conflict: null};
  }

  return {
    mergedRecord,
    conflict: Object.freeze({
      id: base.id,
      kind: 'lexical-environment',
      conflictKind: MERGE_CONFLICT_KINDS.LEXICAL_ENVIRONMENT_CONFLICT,
      base,
      left,
      right,
      parentConflict: parentResult.conflict,
      bindingConflicts: Object.freeze(bindingConflicts),
      metadataConflicts: Object.freeze(metadataConflicts),
    }),
  };
}

function applyConflictResolution(conflict, resolution, targetImageId) {
  if (resolution === 'left') {
    return conflict.left ? canonicalClone(conflict.left) : null;
  }
  if (resolution === 'right') {
    return conflict.right ? canonicalClone(conflict.right) : null;
  }
  if (resolution === 'base') {
    return conflict.base ? canonicalClone(conflict.base) : null;
  }
  if (resolution && typeof resolution === 'object') {
    return rehomeRecordToImage(resolution, resolution.imageId ?? null, targetImageId);
  }
  throw new TypeError(
    `invalid merge conflict resolution for ${conflict.id}: expected 'left', 'right', 'base', or a record object`,
  );
}

function mergeImageRecords({
  baseRecords,
  leftRecords,
  rightRecords,
  baseImageId = null,
  leftImageId = baseImageId,
  rightImageId = baseImageId,
  targetImageId = baseImageId ?? leftImageId ?? rightImageId ?? null,
  baseFrontier = null,
  leftFrontier = null,
  rightFrontier = null,
  resolutions = {},
} = {}) {
  if (resolutions !== null && typeof resolutions !== 'object') {
    throw new TypeError('resolutions must be an object map');
  }
  const resolutionMap = resolutions ?? {};

  const baseMap = indexRecordsById(baseRecords, 'baseRecords', baseImageId, targetImageId);
  const leftMap = indexRecordsById(leftRecords, 'leftRecords', leftImageId, targetImageId);
  const rightMap = indexRecordsById(rightRecords, 'rightRecords', rightImageId, targetImageId);

  const allIds = [
    ...new Set([...baseMap.keys(), ...leftMap.keys(), ...rightMap.keys()]),
  ].sort(compareText);

  const mergedRecords = [];
  const appliedChanges = [];
  const removedIds = [];
  const conflicts = [];
  let unchangedCount = 0;

  for (const id of allIds) {
    const base = baseMap.get(id) ?? null;
    const left = leftMap.get(id) ?? null;
    const right = rightMap.get(id) ?? null;

    // Case 1: Absent in base (addition on left, right, or both)
    if (!base) {
      if (left && !right) {
        mergedRecords.push(left);
        appliedChanges.push(Object.freeze({id, kind: left.kind, action: 'added-left', record: left}));
        continue;
      }
      if (!left && right) {
        mergedRecords.push(right);
        appliedChanges.push(Object.freeze({id, kind: right.kind, action: 'added-right', record: right}));
        continue;
      }
      if (left && right) {
        if (canonicalJson(left) === canonicalJson(right)) {
          mergedRecords.push(left);
          appliedChanges.push(Object.freeze({id, kind: left.kind, action: 'added-both', record: left}));
          continue;
        }
        const conflict = Object.freeze({
          id,
          kind: left.kind === right.kind ? left.kind : `${left.kind}|${right.kind}`,
          conflictKind: MERGE_CONFLICT_KINDS.ADD_ADD,
          base: null,
          left,
          right,
        });
        if (Object.hasOwn(resolutionMap, id)) {
          const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
          if (resolved) {
            mergedRecords.push(resolved);
            appliedChanges.push(
              Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
            );
          } else {
            removedIds.push(id);
          }
        } else {
          conflicts.push(conflict);
        }
      }
      continue;
    }

    // Case 2: Present in base, deleted on both sides
    if (!left && !right) {
      removedIds.push(id);
      appliedChanges.push(Object.freeze({id, kind: base.kind, action: 'removed-both', record: null}));
      continue;
    }

    // Case 3: Present in base, deleted on left only
    if (!left && right) {
      if (canonicalJson(right) === canonicalJson(base)) {
        removedIds.push(id);
        appliedChanges.push(Object.freeze({id, kind: base.kind, action: 'removed-left', record: null}));
        continue;
      }
      const conflict = Object.freeze({
        id,
        kind: base.kind,
        conflictKind: MERGE_CONFLICT_KINDS.DELETE_MODIFY,
        deletedSide: 'left',
        modifiedSide: 'right',
        base,
        left: null,
        right,
      });
      if (Object.hasOwn(resolutionMap, id)) {
        const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
        if (resolved) {
          mergedRecords.push(resolved);
          appliedChanges.push(
            Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
          );
        } else {
          removedIds.push(id);
          appliedChanges.push(
            Object.freeze({id, kind: base.kind, action: 'resolved-conflict', record: null}),
          );
        }
      } else {
        conflicts.push(conflict);
        mergedRecords.push(base);
      }
      continue;
    }

    // Case 4: Present in base, deleted on right only
    if (left && !right) {
      if (canonicalJson(left) === canonicalJson(base)) {
        removedIds.push(id);
        appliedChanges.push(Object.freeze({id, kind: base.kind, action: 'removed-right', record: null}));
        continue;
      }
      const conflict = Object.freeze({
        id,
        kind: base.kind,
        conflictKind: MERGE_CONFLICT_KINDS.DELETE_MODIFY,
        deletedSide: 'right',
        modifiedSide: 'left',
        base,
        left,
        right: null,
      });
      if (Object.hasOwn(resolutionMap, id)) {
        const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
        if (resolved) {
          mergedRecords.push(resolved);
          appliedChanges.push(
            Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
          );
        } else {
          removedIds.push(id);
          appliedChanges.push(
            Object.freeze({id, kind: base.kind, action: 'resolved-conflict', record: null}),
          );
        }
      } else {
        conflicts.push(conflict);
        mergedRecords.push(base);
      }
      continue;
    }

    // Case 5: Present in base, left, and right
    const leftUnchanged = canonicalJson(left) === canonicalJson(base);
    const rightUnchanged = canonicalJson(right) === canonicalJson(base);
    const leftEqualsRight = canonicalJson(left) === canonicalJson(right);

    if (leftUnchanged && rightUnchanged) {
      unchangedCount += 1;
      mergedRecords.push(base);
      continue;
    }
    if (leftUnchanged && !rightUnchanged) {
      mergedRecords.push(right);
      appliedChanges.push(Object.freeze({id, kind: right.kind, action: 'modified-right', record: right}));
      continue;
    }
    if (!leftUnchanged && rightUnchanged) {
      mergedRecords.push(left);
      appliedChanges.push(Object.freeze({id, kind: left.kind, action: 'modified-left', record: left}));
      continue;
    }
    if (leftEqualsRight) {
      mergedRecords.push(left);
      appliedChanges.push(
        Object.freeze({id, kind: left.kind, action: 'modified-both-identical', record: left}),
      );
      continue;
    }

    // Both left and right modified the record differently
    if (left.kind !== right.kind || left.kind !== base.kind) {
      const conflict = Object.freeze({
        id,
        kind: `${left.kind}|${right.kind}`,
        conflictKind: MERGE_CONFLICT_KINDS.KIND_CONFLICT,
        base,
        left,
        right,
      });
      if (Object.hasOwn(resolutionMap, id)) {
        const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
        if (resolved) {
          mergedRecords.push(resolved);
          appliedChanges.push(
            Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
          );
        }
      } else {
        conflicts.push(conflict);
        mergedRecords.push(base);
      }
      continue;
    }

    if (base.kind === 'object') {
      const {mergedRecord, conflict} = mergeObjectRecordThreeWay(base, left, right);
      if (!conflict) {
        mergedRecords.push(mergedRecord);
        appliedChanges.push(
          Object.freeze({id, kind: 'object', action: 'merged-object', record: mergedRecord}),
        );
      } else if (Object.hasOwn(resolutionMap, id)) {
        const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
        if (resolved) {
          mergedRecords.push(resolved);
          appliedChanges.push(
            Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
          );
        }
      } else {
        conflicts.push(conflict);
        mergedRecords.push(mergedRecord);
      }
      continue;
    }

    if (base.kind === 'lexical-environment') {
      const {mergedRecord, conflict} = mergeLexicalEnvironmentRecordThreeWay(base, left, right);
      if (!conflict) {
        mergedRecords.push(mergedRecord);
        appliedChanges.push(
          Object.freeze({
            id,
            kind: 'lexical-environment',
            action: 'merged-lexical-environment',
            record: mergedRecord,
          }),
        );
      } else if (Object.hasOwn(resolutionMap, id)) {
        const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
        if (resolved) {
          mergedRecords.push(resolved);
          appliedChanges.push(
            Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
          );
        }
      } else {
        conflicts.push(conflict);
        mergedRecords.push(mergedRecord);
      }
      continue;
    }

    // Atomic/immutable records (shape, code-artifact, block) modified divergently
    const fieldKeys = [
      ...new Set([...Object.keys(base), ...Object.keys(left), ...Object.keys(right)]),
    ]
      .filter((key) => key !== 'id' && key !== 'imageId' && key !== 'kind')
      .sort(compareText);
    const conflictingFields = fieldKeys.filter(
      (key) => canonicalJson(left[key]) !== canonicalJson(right[key]),
    );
    const conflict = Object.freeze({
      id,
      kind: base.kind,
      conflictKind: MERGE_CONFLICT_KINDS.RECORD_CONFLICT,
      base,
      left,
      right,
      conflictingFields: Object.freeze(conflictingFields),
    });
    if (Object.hasOwn(resolutionMap, id)) {
      const resolved = applyConflictResolution(conflict, resolutionMap[id], targetImageId);
      if (resolved) {
        mergedRecords.push(resolved);
        appliedChanges.push(
          Object.freeze({id, kind: resolved.kind, action: 'resolved-conflict', record: resolved}),
        );
      }
    } else {
      conflicts.push(conflict);
      mergedRecords.push(base);
    }
  }

  return Object.freeze({
    format: IMAGE_RECORD_MERGE_V1,
    baseImageId,
    leftImageId,
    rightImageId,
    targetImageId,
    baseFrontier,
    leftFrontier,
    rightFrontier,
    clean: conflicts.length === 0,
    unchangedCount,
    mergedRecords: Object.freeze(mergedRecords),
    appliedChanges: Object.freeze(appliedChanges),
    removedIds: Object.freeze(removedIds),
    conflicts: Object.freeze(conflicts),
  });
}

async function mergeImageFrontiers({
  images,
  imageId,
  baseFrontier,
  leftFrontier,
  rightFrontier,
  resolutions = {},
} = {}) {
  if (!images || typeof images.frontier !== 'function' || typeof images.history !== 'function') {
    throw new TypeError('mergeImageFrontiers requires an ImageService with frontier() and history()');
  }
  if (typeof imageId !== 'string' || imageId.length === 0) {
    throw new TypeError('imageId must be a non-empty string');
  }
  const [baseRecords, leftRecords, rightRecords] = await Promise.all([
    reconstructImageRecordsAtFrontier({images, imageId, frontier: baseFrontier}),
    reconstructImageRecordsAtFrontier({images, imageId, frontier: leftFrontier}),
    reconstructImageRecordsAtFrontier({images, imageId, frontier: rightFrontier}),
  ]);
  return mergeImageRecords({
    baseRecords,
    leftRecords,
    rightRecords,
    baseImageId: imageId,
    leftImageId: imageId,
    rightImageId: imageId,
    targetImageId: imageId,
    baseFrontier: Number(baseFrontier),
    leftFrontier: Number(leftFrontier),
    rightFrontier: Number(rightFrontier),
    resolutions,
  });
}

const KIND_APPLY_ORDER = Object.freeze({
  shape: 1,
  'code-artifact': 2,
  'lexical-environment': 3,
  block: 4,
  object: 5,
});

async function applySingleMergedRecord(images, targetImageId, record) {
  const rehomed = rehomeRecordToImage(record, record.imageId ?? null, targetImageId);
  switch (rehomed.kind) {
    case 'shape': {
      const existing = await images.getShape(targetImageId, rehomed.id);
      if (existing && canonicalJson(normalizeRecordForDiff(existing)) === canonicalJson(rehomed)) {
        return existing;
      }
      return await images.putShape(targetImageId, {
        id: rehomed.id,
        slots: rehomed.slots,
        ...(Object.hasOwn(rehomed, 'indexed') ? {indexed: rehomed.indexed} : {}),
        metadata: rehomed.metadata ?? {},
      });
    }
    case 'code-artifact': {
      const existing = await images.getCodeArtifact(targetImageId, rehomed.id);
      if (existing && canonicalJson(normalizeRecordForDiff(existing)) === canonicalJson(rehomed)) {
        return existing;
      }
      return await images.putCodeArtifact(targetImageId, {
        id: rehomed.id,
        languageId: rehomed.languageId ?? null,
        representation: rehomed.representation,
        content: rehomed.content,
        logicalPath: rehomed.logicalPath ?? null,
        dependencies: rehomed.dependencies ?? [],
        derivedFrom: rehomed.derivedFrom ?? [],
        metadata: rehomed.metadata ?? {},
      });
    }
    case 'lexical-environment': {
      const existing = await images.getLexicalEnvironment(targetImageId, rehomed.id);
      if (existing && canonicalJson(normalizeRecordForDiff(existing)) === canonicalJson(rehomed)) {
        return existing;
      }
      return await images.putLexicalEnvironment(targetImageId, {
        id: rehomed.id,
        parent: rehomed.parent ?? null,
        bindings: rehomed.bindings ?? {},
        metadata: rehomed.metadata ?? {},
      });
    }
    case 'block': {
      const existing = await images.getBlock(targetImageId, rehomed.id);
      if (existing && canonicalJson(normalizeRecordForDiff(existing)) === canonicalJson(rehomed)) {
        return existing;
      }
      return await images.putBlock(targetImageId, {
        id: rehomed.id,
        code: rehomed.code,
        environment: rehomed.environment ?? null,
        metadata: rehomed.metadata ?? {},
      });
    }
    case 'object': {
      const existing = await images.getObject(targetImageId, rehomed.id);
      if (existing && canonicalJson(normalizeRecordForDiff(existing)) === canonicalJson(rehomed)) {
        return existing;
      }
      return await images.putObject(targetImageId, {
        id: rehomed.id,
        shape: rehomed.shape,
        behavior: rehomed.behavior ?? null,
        slots: rehomed.slots ?? {},
        ...(Object.hasOwn(rehomed, 'indexed') ? {indexed: rehomed.indexed} : {}),
        metadata: rehomed.metadata ?? {},
      });
    }
    default:
      throw new TypeError(`unsupported record kind in applyImageMerge: ${rehomed.kind}`);
  }
}

async function applyImageMerge({
  images,
  targetImageId,
  mergePlan,
  allowConflicts = false,
} = {}) {
  if (!images || typeof images.putObject !== 'function') {
    throw new TypeError('applyImageMerge requires an ImageService');
  }
  if (typeof targetImageId !== 'string' || targetImageId.length === 0) {
    throw new TypeError('targetImageId must be a non-empty string');
  }
  if (!mergePlan || mergePlan.format !== IMAGE_RECORD_MERGE_V1) {
    throw new TypeError(`mergePlan must be a ${IMAGE_RECORD_MERGE_V1} descriptor`);
  }
  if (!mergePlan.clean && !allowConflicts) {
    throw new MergeConflictError(
      `cannot apply image merge with ${mergePlan.conflicts.length} unresolved conflict(s)`,
      {conflicts: mergePlan.conflicts},
    );
  }

  const recordsToWrite = mergePlan.appliedChanges
    .filter((change) => change.record !== null)
    .map((change) => change.record)
    .sort((a, b) => {
      const orderDiff = (KIND_APPLY_ORDER[a.kind] ?? 99) - (KIND_APPLY_ORDER[b.kind] ?? 99);
      return orderDiff !== 0 ? orderDiff : compareText(a.id, b.id);
    });

  const written = [];
  for (const record of recordsToWrite) {
    const saved = await applySingleMergedRecord(images, targetImageId, record);
    written.push(saved);
  }

  return Object.freeze({
    targetImageId,
    appliedCount: written.length,
    writtenIds: Object.freeze(written.map((r) => r.id)),
  });
}

export {
  IMAGE_RECORD_MERGE_V1,
  MERGE_CONFLICT_KINDS,
  MergeConflictError,
  applyImageMerge,
  mergeImageFrontiers,
  mergeImageRecords,
  rehomeRecordToImage,
};

import {RELOCATED_RECORD_KIND, SWEPT_RECORD_KIND} from './locator.js';
import {reconstructImageRecordsAtFrontier} from './diff.js';
import {referencesOfRecord} from './references.js';
import {isObjectRef} from '../value/scalars.js';

const IMAGE_GRAPH_INDEX_V1 = 'lagrange-image-graph-index/v1';
const IMAGE_REACHABILITY_CLOSURE_V1 = 'lagrange-image-reachability-closure/v1';
const IMAGE_GC_PLAN_V1 = 'lagrange-image-gc-plan/v1';
const IMAGE_GC_RECEIPT_V1 = 'lagrange-image-gc-receipt/v1';

const DURABLE_RECORD_KINDS = Object.freeze([
  'shape',
  'object',
  'code-artifact',
  'lexical-environment',
  'block',
]);

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function compareObjectRef(left, right) {
  const imageOrder = compareText(left.imageId, right.imageId);
  if (imageOrder !== 0) return imageOrder;
  return compareText(left.objectId, right.objectId);
}

function dedupeSortedStrings(values) {
  return Object.freeze([...new Set(values)].sort(compareText));
}

function dedupeSortedObjectRefs(refs) {
  const byKey = new Map();
  for (const ref of refs) {
    if (!isObjectRef(ref)) continue;
    const key = `${ref.imageId}\0${ref.objectId}`;
    if (!byKey.has(key)) {
      byKey.set(key, Object.freeze({kind: 'ref', imageId: ref.imageId, objectId: ref.objectId}));
    }
  }
  return Object.freeze([...byKey.values()].sort(compareObjectRef));
}

function isIntrinsicRootRecord(record, {imageRootObjectId = null, preserveSystemShapes = true} = {}) {
  if (!record || typeof record !== 'object') return false;
  const id = record.id;
  if (typeof id !== 'string' || id.length === 0) return false;
  if (imageRootObjectId && id === imageRootObjectId) return true;

  // Intrinsic versioned system/protocol shapes (e.g. `<domain>/<name>/v1`).
  if (
    preserveSystemShapes &&
    record.kind === 'shape' &&
    (id.startsWith('smalltalk/') ||
      id.startsWith('lagrange-project/') ||
      id.startsWith('lagrange-project-installation/') ||
      (id.includes('/') && /\/v\d+$/.test(id)))
  ) {
    return true;
  }

  // Kernel, global namespace, interned symbols/characters, and behaviors.
  if (
    id === 'smalltalk-kernel/v1' ||
    id === 'smalltalk/kernel' ||
    id === 'smalltalk-global-namespace/v1' ||
    id === 'smalltalk/globals' ||
    id === 'smalltalk-block-protocol/v1' ||
    id === 'smalltalk/block-protocol' ||
    id === 'smalltalk-block-unwind/v1' ||
    id === 'smalltalk/block-unwind' ||
    id === 'smalltalk/symbol-table' ||
    id === 'smalltalk/subclasses' ||
    id.startsWith('smalltalk/symbol/') ||
    id.startsWith('smalltalk/char/') ||
    id.endsWith('/namespace/v1')
  ) {
    return true;
  }
  const stMeta = record.metadata?.smalltalk;
  if (
    stMeta === 'behavior' ||
    stMeta === 'singleton' ||
    stMeta === 'class-state' ||
    stMeta === 'subclass-registry' ||
    stMeta === 'kernel-primitive'
  ) {
    return true;
  }
  const protocolMeta = record.metadata?.protocol;
  if (
    protocolMeta === 'smalltalk-kernel/v1' ||
    protocolMeta === 'smalltalk-kernel-protocol/v1' ||
    protocolMeta === 'smalltalk-global-namespace/v1' ||
    protocolMeta === 'smalltalk-block-protocol/v1' ||
    protocolMeta === 'smalltalk-block-unwind/v1' ||
    protocolMeta === 'smalltalk-block-unwind-protocol/v1'
  ) {
    return true;
  }

  // Generic namespace objects, sentinels, and system descriptors.
  if (
    record.kind === 'object' &&
    (record.shape?.objectId === 'smalltalk/global-namespace-shape/v2' ||
      record.shape?.objectId === 'smalltalk/global-namespace-shape/v1')
  ) {
    return true;
  }
  if (
    record.metadata &&
    typeof record.metadata === 'object' &&
    Object.values(record.metadata).some((val) => val === 'sentinel' || val === 'defsystem')
  ) {
    return true;
  }

  // Project working-state roots, sentinel, installation heads, and named branch heads.
  if (
    id === 'lagrange-project/none/v1' ||
    id.startsWith('lagrange-branch/head/') ||
    (id.startsWith('lagrange-project-installation/') && id.endsWith('/head'))
  ) {
    return true;
  }
  if (
    record.kind === 'object' &&
    (record.shape?.objectId === 'lagrange-project/project/v1' ||
      record.shape?.objectId === 'lagrange-project-installation/head-shape/v1' ||
      record.shape?.objectId === 'lagrange-branch/head-shape/v1' ||
      record.metadata?.project === 'working-state' ||
      record.metadata?.branch === 'head')
  ) {
    return true;
  }

  return false;
}

function buildImageGraphIndex(records, {imageId = null} = {}) {
  if (!Array.isArray(records)) {
    throw new TypeError('buildImageGraphIndex requires an array of records');
  }

  const liveRecords = [];
  for (const record of records) {
    if (!record || typeof record !== 'object') continue;
    if (record.kind === RELOCATED_RECORD_KIND || record.kind === SWEPT_RECORD_KIND) continue;
    liveRecords.push(record);
  }

  const resolvedImageId =
    imageId ?? liveRecords.find((record) => typeof record.imageId === 'string')?.imageId ?? null;

  const recordsByIdMap = new Map();
  const byKindBuckets = new Map(DURABLE_RECORD_KINDS.map((kind) => [kind, []]));

  for (const record of liveRecords) {
    if (typeof record.id !== 'string' || record.id.length === 0) {
      throw new TypeError('record must have a non-empty string id');
    }
    if (recordsByIdMap.has(record.id)) {
      throw new TypeError(`duplicate record id in image graph index: ${record.id}`);
    }
    if (!byKindBuckets.has(record.kind)) {
      throw new TypeError(`unknown record kind in image graph index: ${record.kind}`);
    }
    recordsByIdMap.set(record.id, record);
    byKindBuckets.get(record.kind).push(record.id);
  }

  const sortedIds = [...recordsByIdMap.keys()].sort(compareText);
  const recordsById = {};
  for (const id of sortedIds) {
    recordsById[id] = recordsByIdMap.get(id);
  }

  const recordIdsByKind = {};
  for (const kind of DURABLE_RECORD_KINDS) {
    recordIdsByKind[kind] = dedupeSortedStrings(byKindBuckets.get(kind));
  }

  const outgoingRefsById = {};
  const outgoingLocalIdsById = {};
  const outgoingExternalRefsById = {};
  const incomingLocalSets = new Map(sortedIds.map((id) => [id, new Set()]));

  const derivedFromByArtifactId = {};
  const dependentsOfSourceSets = new Map();
  const dependenciesByArtifactId = {};
  const reverseDependencyLists = new Map();
  const logicalPathSets = new Map();
  const representationSets = new Map();
  const blocksByCodeArtifactSets = new Map();

  for (const id of sortedIds) {
    const record = recordsById[id];
    const refs = dedupeSortedObjectRefs(referencesOfRecord(record));
    outgoingRefsById[id] = refs;

    const localTargets = [];
    const externalTargets = [];
    for (const ref of refs) {
      const sameImage = resolvedImageId === null || ref.imageId === resolvedImageId || ref.imageId === record.imageId;
      if (sameImage && recordsByIdMap.has(ref.objectId)) {
        localTargets.push(ref.objectId);
        incomingLocalSets.get(ref.objectId).add(id);
      } else {
        externalTargets.push(ref);
      }
    }
    outgoingLocalIdsById[id] = dedupeSortedStrings(localTargets);
    outgoingExternalRefsById[id] = Object.freeze(externalTargets);

    if (record.kind === 'code-artifact') {
      const derivedSources = [];
      for (const sourceRef of record.derivedFrom ?? []) {
        if (!isObjectRef(sourceRef)) continue;
        derivedSources.push(sourceRef.objectId);
        if (!dependentsOfSourceSets.has(sourceRef.objectId)) {
          dependentsOfSourceSets.set(sourceRef.objectId, new Set());
        }
        dependentsOfSourceSets.get(sourceRef.objectId).add(id);
      }
      derivedFromByArtifactId[id] = dedupeSortedStrings(derivedSources);

      const depEntries = [];
      for (const dep of record.dependencies ?? []) {
        if (!dep || !isObjectRef(dep.artifact)) continue;
        depEntries.push(
          Object.freeze({
            role: dep.role,
            imageId: dep.artifact.imageId,
            artifactId: dep.artifact.objectId,
          }),
        );
        if (!reverseDependencyLists.has(dep.artifact.objectId)) {
          reverseDependencyLists.set(dep.artifact.objectId, []);
        }
        reverseDependencyLists.get(dep.artifact.objectId).push(
          Object.freeze({
            role: dep.role,
            dependentArtifactId: id,
          }),
        );
      }
      depEntries.sort((left, right) => {
        const roleOrder = compareText(left.role, right.role);
        if (roleOrder !== 0) return roleOrder;
        return compareText(left.artifactId, right.artifactId);
      });
      dependenciesByArtifactId[id] = Object.freeze(depEntries);

      if (typeof record.logicalPath === 'string' && record.logicalPath.length > 0) {
        if (!logicalPathSets.has(record.logicalPath)) {
          logicalPathSets.set(record.logicalPath, new Set());
        }
        logicalPathSets.get(record.logicalPath).add(id);
      }

      if (typeof record.representation === 'string' && record.representation.length > 0) {
        if (!representationSets.has(record.representation)) {
          representationSets.set(record.representation, new Set());
        }
        representationSets.get(record.representation).add(id);
      }
    }

    if (record.kind === 'block' && isObjectRef(record.code)) {
      const codeId = record.code.objectId;
      if (!blocksByCodeArtifactSets.has(codeId)) {
        blocksByCodeArtifactSets.set(codeId, new Set());
      }
      blocksByCodeArtifactSets.get(codeId).add(id);
    }
  }

  const incomingLocalIdsById = {};
  for (const id of sortedIds) {
    incomingLocalIdsById[id] = dedupeSortedStrings(incomingLocalSets.get(id));
  }

  const dependentsOfSourceByArtifactId = {};
  for (const [sourceId, set] of [...dependentsOfSourceSets.entries()].sort(([a], [b]) => compareText(a, b))) {
    dependentsOfSourceByArtifactId[sourceId] = dedupeSortedStrings(set);
  }

  const reverseDependenciesByArtifactId = {};
  for (const [targetId, list] of [...reverseDependencyLists.entries()].sort(([a], [b]) => compareText(a, b))) {
    const sorted = [...list].sort((left, right) => {
      const roleOrder = compareText(left.role, right.role);
      if (roleOrder !== 0) return roleOrder;
      return compareText(left.dependentArtifactId, right.dependentArtifactId);
    });
    reverseDependenciesByArtifactId[targetId] = Object.freeze(sorted);
  }

  const artifactsByLogicalPath = {};
  for (const [logicalPath, set] of [...logicalPathSets.entries()].sort(([a], [b]) => compareText(a, b))) {
    artifactsByLogicalPath[logicalPath] = dedupeSortedStrings(set);
  }

  const artifactsByRepresentation = {};
  for (const [rep, set] of [...representationSets.entries()].sort(([a], [b]) => compareText(a, b))) {
    artifactsByRepresentation[rep] = dedupeSortedStrings(set);
  }

  const blocksByCodeArtifactId = {};
  for (const [codeId, set] of [...blocksByCodeArtifactSets.entries()].sort(([a], [b]) => compareText(a, b))) {
    blocksByCodeArtifactId[codeId] = dedupeSortedStrings(set);
  }

  return Object.freeze({
    format: IMAGE_GRAPH_INDEX_V1,
    imageId: resolvedImageId,
    recordCount: sortedIds.length,
    recordIds: Object.freeze(sortedIds),
    recordsById: Object.freeze(recordsById),
    recordIdsByKind: Object.freeze(recordIdsByKind),
    outgoingRefsById: Object.freeze(outgoingRefsById),
    outgoingLocalIdsById: Object.freeze(outgoingLocalIdsById),
    outgoingExternalRefsById: Object.freeze(outgoingExternalRefsById),
    incomingLocalIdsById: Object.freeze(incomingLocalIdsById),
    derivedFromByArtifactId: Object.freeze(derivedFromByArtifactId),
    dependentsOfSourceByArtifactId: Object.freeze(dependentsOfSourceByArtifactId),
    dependenciesByArtifactId: Object.freeze(dependenciesByArtifactId),
    reverseDependenciesByArtifactId: Object.freeze(reverseDependenciesByArtifactId),
    artifactsByLogicalPath: Object.freeze(artifactsByLogicalPath),
    artifactsByRepresentation: Object.freeze(artifactsByRepresentation),
    blocksByCodeArtifactId: Object.freeze(blocksByCodeArtifactId),
  });
}

function ensureGraphIndex(indexOrRecords, options = {}) {
  if (indexOrRecords && indexOrRecords.format === IMAGE_GRAPH_INDEX_V1) {
    return indexOrRecords;
  }
  return buildImageGraphIndex(indexOrRecords, options);
}

function traverseAdjacency(startIds, getNeighbors) {
  const visited = new Set();
  const queue = [...startIds];
  while (queue.length > 0) {
    const current = queue.shift();
    for (const next of getNeighbors(current) ?? []) {
      if (!visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }
  return dedupeSortedStrings(visited);
}

function findOutgoingReferences(indexOrRecords, sourceId, {transitive = false} = {}) {
  if (typeof sourceId !== 'string' || sourceId.length === 0) {
    throw new TypeError('findOutgoingReferences requires a non-empty string sourceId');
  }
  const index = ensureGraphIndex(indexOrRecords);
  if (!transitive) {
    return index.outgoingLocalIdsById[sourceId] ?? Object.freeze([]);
  }
  return traverseAdjacency([sourceId], (id) => index.outgoingLocalIdsById[id]);
}

function findIncomingReferences(indexOrRecords, targetId, {transitive = false} = {}) {
  if (typeof targetId !== 'string' || targetId.length === 0) {
    throw new TypeError('findIncomingReferences requires a non-empty string targetId');
  }
  const index = ensureGraphIndex(indexOrRecords);
  if (!transitive) {
    return index.incomingLocalIdsById[targetId] ?? Object.freeze([]);
  }
  return traverseAdjacency([targetId], (id) => index.incomingLocalIdsById[id]);
}

function findDerivedArtifacts(indexOrRecords, sourceArtifactId, {transitive = true} = {}) {
  if (typeof sourceArtifactId !== 'string' || sourceArtifactId.length === 0) {
    throw new TypeError('findDerivedArtifacts requires a non-empty string sourceArtifactId');
  }
  const index = ensureGraphIndex(indexOrRecords);
  const artifactIds = transitive
    ? traverseAdjacency([sourceArtifactId], (id) => index.dependentsOfSourceByArtifactId[id])
    : index.dependentsOfSourceByArtifactId[sourceArtifactId] ?? Object.freeze([]);
  const artifacts = Object.freeze(
    artifactIds.map((id) => index.recordsById[id]).filter(Boolean),
  );
  const blockIds = [];
  for (const id of artifactIds) {
    for (const blockId of index.blocksByCodeArtifactId[id] ?? []) {
      blockIds.push(blockId);
    }
  }
  return Object.freeze({
    sourceArtifactId,
    artifactIds,
    artifacts,
    blocksReferencingDerived: dedupeSortedStrings(blockIds),
  });
}

function findArtifactSources(indexOrRecords, artifactId, {transitive = true} = {}) {
  if (typeof artifactId !== 'string' || artifactId.length === 0) {
    throw new TypeError('findArtifactSources requires a non-empty string artifactId');
  }
  const index = ensureGraphIndex(indexOrRecords);
  const sourceArtifactIds = transitive
    ? traverseAdjacency([artifactId], (id) => index.derivedFromByArtifactId[id])
    : index.derivedFromByArtifactId[artifactId] ?? Object.freeze([]);
  const sourceArtifacts = Object.freeze(
    sourceArtifactIds.map((id) => index.recordsById[id]).filter(Boolean),
  );
  return Object.freeze({
    artifactId,
    sourceArtifactIds,
    sourceArtifacts,
  });
}

function findArtifactDependents(indexOrRecords, targetArtifactId, {transitive = true} = {}) {
  if (typeof targetArtifactId !== 'string' || targetArtifactId.length === 0) {
    throw new TypeError('findArtifactDependents requires a non-empty string targetArtifactId');
  }
  const index = ensureGraphIndex(indexOrRecords);
  const directNeighbors = (id) =>
    (index.reverseDependenciesByArtifactId[id] ?? []).map((entry) => entry.dependentArtifactId);
  const dependentArtifactIds = transitive
    ? traverseAdjacency([targetArtifactId], directNeighbors)
    : dedupeSortedStrings(directNeighbors(targetArtifactId));
  const dependentArtifacts = Object.freeze(
    dependentArtifactIds.map((id) => index.recordsById[id]).filter(Boolean),
  );
  return Object.freeze({
    targetArtifactId,
    dependentArtifactIds,
    dependentArtifacts,
  });
}

function findArtifactsByLogicalPath(indexOrRecords, logicalPath) {
  if (typeof logicalPath !== 'string' || logicalPath.length === 0) {
    throw new TypeError('findArtifactsByLogicalPath requires a non-empty string logicalPath');
  }
  const index = ensureGraphIndex(indexOrRecords);
  const artifactIds = index.artifactsByLogicalPath[logicalPath] ?? Object.freeze([]);
  const artifacts = Object.freeze(
    artifactIds.map((id) => index.recordsById[id]).filter(Boolean),
  );
  return Object.freeze({
    logicalPath,
    artifactIds,
    artifacts,
  });
}

function discoverDefaultImageRoots(
  indexOrRecords,
  {imageId = null, imageRootObjectId = null, preserveSystemShapes = true} = {},
) {
  const index = ensureGraphIndex(indexOrRecords, {imageId});
  const roots = [];
  for (const id of index.recordIds) {
    const record = index.recordsById[id];
    if (isIntrinsicRootRecord(record, {imageRootObjectId, preserveSystemShapes})) {
      roots.push(id);
    }
  }
  return dedupeSortedStrings(roots);
}

function normalizeRootId(entry, imageId) {
  if (typeof entry === 'string' && entry.length > 0) {
    return entry;
  }
  if (isObjectRef(entry)) {
    if (imageId && entry.imageId !== imageId) {
      return null;
    }
    return entry.objectId;
  }
  if (entry && typeof entry === 'object' && typeof entry.id === 'string' && entry.id.length > 0) {
    return entry.id;
  }
  throw new TypeError('root entry must be a record id string, ObjectRef, or record object');
}

function groupIdsByKind(ids, recordsById) {
  const buckets = new Map(DURABLE_RECORD_KINDS.map((kind) => [kind, []]));
  for (const id of ids) {
    const record = recordsById[id];
    if (record && buckets.has(record.kind)) {
      buckets.get(record.kind).push(id);
    }
  }
  const grouped = {};
  for (const kind of DURABLE_RECORD_KINDS) {
    grouped[kind] = dedupeSortedStrings(buckets.get(kind));
  }
  return Object.freeze(grouped);
}

function computeReachableImageClosure({
  records = null,
  index: providedIndex = null,
  imageId = null,
  imageRootObjectId = null,
  roots = [],
  includeDefaultRoots = true,
  preserveSystemShapes = true,
  includeDerivedArtifacts = false,
  pinnedRecordIds = [],
} = {}) {
  const index = providedIndex ?? ensureGraphIndex(records, {imageId});
  const resolvedImageId = imageId ?? index.imageId;

  if (!Array.isArray(roots)) {
    throw new TypeError('computeReachableImageClosure roots must be an array');
  }
  if (!Array.isArray(pinnedRecordIds)) {
    throw new TypeError('computeReachableImageClosure pinnedRecordIds must be an array');
  }

  const explicitRootIds = [];
  for (const entry of roots) {
    const normalized = normalizeRootId(entry, resolvedImageId);
    if (normalized && Object.hasOwn(index.recordsById, normalized)) {
      explicitRootIds.push(normalized);
    }
  }

  const normalizedPinnedIds = [];
  for (const entry of pinnedRecordIds) {
    const normalized = normalizeRootId(entry, resolvedImageId);
    if (normalized && Object.hasOwn(index.recordsById, normalized)) {
      normalizedPinnedIds.push(normalized);
    }
  }

  const defaultRootIds = includeDefaultRoots
    ? discoverDefaultImageRoots(index, {
        imageId: resolvedImageId,
        imageRootObjectId,
        preserveSystemShapes,
      })
    : Object.freeze([]);

  const rootIds = dedupeSortedStrings([
    ...defaultRootIds,
    ...explicitRootIds,
    ...normalizedPinnedIds,
  ]);

  const reachableSet = new Set(rootIds);
  const queue = [...rootIds];

  while (queue.length > 0) {
    const currentId = queue.shift();
    for (const targetId of index.outgoingLocalIdsById[currentId] ?? []) {
      if (!reachableSet.has(targetId)) {
        reachableSet.add(targetId);
        queue.push(targetId);
      }
    }
    if (includeDerivedArtifacts) {
      for (const derivedId of index.dependentsOfSourceByArtifactId[currentId] ?? []) {
        if (Object.hasOwn(index.recordsById, derivedId) && !reachableSet.has(derivedId)) {
          reachableSet.add(derivedId);
          queue.push(derivedId);
        }
      }
    }
  }

  const reachableIds = dedupeSortedStrings(reachableSet);
  const unreachableIds = dedupeSortedStrings(
    index.recordIds.filter((id) => !reachableSet.has(id)),
  );

  const externalRefs = [];
  for (const id of reachableIds) {
    for (const ref of index.outgoingExternalRefsById[id] ?? []) {
      externalRefs.push(ref);
    }
  }

  return Object.freeze({
    format: IMAGE_REACHABILITY_CLOSURE_V1,
    imageId: resolvedImageId,
    rootIds,
    defaultRootIds,
    explicitRootIds: dedupeSortedStrings(explicitRootIds),
    pinnedRecordIds: dedupeSortedStrings(normalizedPinnedIds),
    reachableIds,
    unreachableIds,
    reachableByKind: groupIdsByKind(reachableIds, index.recordsById),
    unreachableByKind: groupIdsByKind(unreachableIds, index.recordsById),
    reachableRecords: Object.freeze(reachableIds.map((id) => index.recordsById[id])),
    unreachableRecords: Object.freeze(unreachableIds.map((id) => index.recordsById[id])),
    externalRefs: dedupeSortedObjectRefs(externalRefs),
    index,
  });
}

async function planImageGarbageCollection({
  images,
  imageId,
  roots = [],
  pinnedFrontiers = [],
  includeDefaultRoots = true,
  preserveSystemShapes = true,
  preserveNamedBranches = true,
  includeDerivedArtifacts = false,
} = {}) {
  if (
    !images ||
    typeof images.getImage !== 'function' ||
    typeof images.listRecords !== 'function' ||
    typeof images.frontier !== 'function' ||
    typeof images.history !== 'function'
  ) {
    throw new TypeError(
      'planImageGarbageCollection requires an ImageService with getImage(), listRecords(), frontier(), and history()',
    );
  }
  if (typeof imageId !== 'string' || imageId.length === 0) {
    throw new TypeError('planImageGarbageCollection requires a non-empty string imageId');
  }
  if (!Array.isArray(pinnedFrontiers)) {
    throw new TypeError('planImageGarbageCollection pinnedFrontiers must be an array');
  }

  const image = await images.getImage(imageId);
  const currentFrontier = await images.frontier(imageId);
  const currentRecords = await images.listRecords(imageId);
  const currentIndex = buildImageGraphIndex(currentRecords, {imageId});

  const rawFronts = pinnedFrontiers.map((f) =>
    f && typeof f === 'object' && Object.hasOwn(f, 'revision') ? Number(f.revision) : Number(f),
  );
  if (preserveNamedBranches) {
    for (const rec of currentRecords) {
      if (rec?.kind === 'object' && rec.shape?.objectId === 'lagrange-branch/head-shape/v1') {
        const revSlot = rec.slots?.['branch-revision'];
        if (revSlot?.kind === 'integer') {
          rawFronts.push(Number(revSlot.value));
        }
      }
    }
  }

  const sortedPinnedFrontiers = [...new Set(rawFronts)].sort((a, b) => a - b);
  const pinnedFrontierIdSet = new Set();

  for (const frontier of sortedPinnedFrontiers) {
    const historicalSnapshot = await reconstructImageRecordsAtFrontier({
      images,
      imageId,
      frontier,
    });
    const historicalClosure = computeReachableImageClosure({
      records: Array.isArray(historicalSnapshot) ? historicalSnapshot : historicalSnapshot.records,
      imageId,
      imageRootObjectId: image.rootObjectId ?? null,
      roots,
      includeDefaultRoots,
      preserveSystemShapes,
      includeDerivedArtifacts,
    });
    for (const id of historicalClosure.reachableIds) {
      if (Object.hasOwn(currentIndex.recordsById, id)) {
        pinnedFrontierIdSet.add(id);
      }
    }
  }

  const pinnedByFrontierIds = dedupeSortedStrings(pinnedFrontierIdSet);
  const closure = computeReachableImageClosure({
    index: currentIndex,
    imageId,
    imageRootObjectId: image.rootObjectId ?? null,
    roots,
    includeDefaultRoots,
    preserveSystemShapes,
    includeDerivedArtifacts,
    pinnedRecordIds: pinnedByFrontierIds,
  });

  return Object.freeze({
    format: IMAGE_GC_PLAN_V1,
    imageId,
    frontier: currentFrontier,
    pinnedFrontiers: Object.freeze(sortedPinnedFrontiers),
    rootIds: closure.rootIds,
    defaultRootIds: closure.defaultRootIds,
    explicitRootIds: closure.explicitRootIds,
    pinnedByFrontierIds,
    retainedIds: closure.reachableIds,
    sweptIds: closure.unreachableIds,
    retainedByKind: closure.reachableByKind,
    sweptByKind: closure.unreachableByKind,
    externalRefs: closure.externalRefs,
  });
}

async function collectUnreachableImageRecords({
  images,
  imageId,
  roots = [],
  pinnedFrontiers = [],
  includeDefaultRoots = true,
  preserveSystemShapes = true,
  includeDerivedArtifacts = false,
  reason = 'unreachable',
  dryRun = false,
} = {}) {
  const plan = await planImageGarbageCollection({
    images,
    imageId,
    roots,
    pinnedFrontiers,
    includeDefaultRoots,
    preserveSystemShapes,
    includeDerivedArtifacts,
  });

  let receipts = Object.freeze([]);
  if (!dryRun && plan.sweptIds.length > 0) {
    if (typeof images.sweepRecords !== 'function') {
      throw new TypeError('collectUnreachableImageRecords requires images.sweepRecords()');
    }
    receipts = await images.sweepRecords(imageId, plan.sweptIds, {reason});
  }

  const afterFrontier = await images.frontier(imageId);
  return Object.freeze({
    format: IMAGE_GC_RECEIPT_V1,
    imageId,
    dryRun: Boolean(dryRun),
    reason,
    beforeFrontier: plan.frontier,
    afterFrontier,
    sweptCount: plan.sweptIds.length,
    sweptIds: plan.sweptIds,
    retainedCount: plan.retainedIds.length,
    retainedIds: plan.retainedIds,
    pinnedFrontiers: plan.pinnedFrontiers,
    pinnedByFrontierIds: plan.pinnedByFrontierIds,
    plan,
    receipts,
  });
}

