import {referencesOfValue} from '../value/index.js';
import {assertObjectRecord, assertShapeRecord} from '../object/model.js';
import {assertBlockRecord, assertCodeArtifactRecord, assertLexicalEnvironmentRecord} from '../execution/model.js';

function referencesOfRecord(record) {
  if (record?.kind === 'shape') {
    assertShapeRecord(record);
    return [];
  }
  if (record?.kind === 'object') {
    assertObjectRecord(record);
    const refs = [record.shape];
    if (record.behavior) refs.push(record.behavior);
    // Canonical edge order: slot edges are enumerated by stable slot id (code-unit order), never
    // by insertion order, so two semantically identical records built with opposite insertion
    // order yield the same edge sequence. Fixed structural edges (shape, behavior) keep their
    // semantic order first; the indexed part (an ordinary ordered array) retains its own order.
    for (const slotId of Object.keys(record.slots).sort()) refs.push(...referencesOfValue(record.slots[slotId]));
    // ADR 0047: an indexed Value is just as much graph as a named-slot Value. Omitting this walk
    // would make a ref durable and readable while invisible to every graph operation built here.
    for (const value of record.indexed ?? []) refs.push(...referencesOfValue(value));
    return refs;
  }
  if (record?.kind === 'code-artifact') {
    assertCodeArtifactRecord(record);
    return [
      ...referencesOfValue(record.content),
      ...(record.dependencies ?? []).map(({artifact}) => artifact),
      ...record.derivedFrom,
    ];
  }
  if (record?.kind === 'lexical-environment') {
    assertLexicalEnvironmentRecord(record);
    const refs = record.parent ? [record.parent] : [];
    // Canonical edge order: binding edges are enumerated by stable binding id (code-unit order),
    // never by insertion order. `parent` (a fixed structural edge) keeps its semantic position
    // first. Note a binding may be {value} | {unbound} | {cell}; only `value` carries a ref.
    for (const bindingId of Object.keys(record.bindings).sort()) {
      refs.push(...referencesOfValue(record.bindings[bindingId].value));
    }
    return refs;
  }
  if (record?.kind === 'block') {
    assertBlockRecord(record);
    return record.environment ? [record.code, record.environment] : [record.code];
  }
  throw new TypeError(`unknown record kind: ${record?.kind ?? 'missing'}`);
}

export {referencesOfRecord};

import {assertBackendTransaction} from '../backend/backend-contract.js';
import {IMAGE_COLLECTION, records} from '../image/storage-layout.js';
import {isObjectRef} from '../value/scalars.js';
import {
  PER_OBJECT_RESIDENCY,
  RELOCATED_RECORD_KIND,
  SWEPT_RECORD_KIND,
  backendForResidency,
  isRemoteResidency,
} from './locator.js';

class RemoteRecordResolver {
  #recordReads = 0;
  #crossNodeRecordReads = 0;
  #localRecordReads = 0;
  #perObjectRecordReads = 0;
  #imageResidencyRecordReads = 0;
  #imageReads = 0;
  #recordWrites = 0;
  #crossNodeRecordWrites = 0;
  #localRecordWrites = 0;
  #perObjectRecordWrites = 0;

  stats() {
    return Object.freeze({
      recordReads: this.#recordReads,
      crossNodeRecordReads: this.#crossNodeRecordReads,
      localRecordReads: this.#localRecordReads,
      perObjectRecordReads: this.#perObjectRecordReads,
      imageResidencyRecordReads: this.#imageResidencyRecordReads,
      imageReads: this.#imageReads,
      recordWrites: this.#recordWrites,
      crossNodeRecordWrites: this.#crossNodeRecordWrites,
      localRecordWrites: this.#localRecordWrites,
      perObjectRecordWrites: this.#perObjectRecordWrites,
    });
  }

  resetStats() {
    this.#recordReads = 0;
    this.#crossNodeRecordReads = 0;
    this.#localRecordReads = 0;
    this.#perObjectRecordReads = 0;
    this.#imageResidencyRecordReads = 0;
    this.#imageReads = 0;
    this.#recordWrites = 0;
    this.#crossNodeRecordWrites = 0;
    this.#localRecordWrites = 0;
    this.#perObjectRecordWrites = 0;
  }

  async resolveAt(ref, residency) {
    if (!isObjectRef(ref)) throw new TypeError('remote resolution requires an ObjectRef');
    if (!residency || residency.imageId !== ref.imageId) {
      throw new TypeError('remote resolution residency does not match the ObjectRef image');
    }
    if (residency.kind === PER_OBJECT_RESIDENCY && residency.objectId !== ref.objectId) {
      throw new TypeError('remote resolution residency does not match the ObjectRef object');
    }
    const backend = backendForResidency(residency);
    const remote = isRemoteResidency(residency);
    this.#recordReads += 1;
    if (remote) {
      this.#crossNodeRecordReads += 1;
      if (residency.kind === PER_OBJECT_RESIDENCY) {
        this.#perObjectRecordReads += 1;
      } else {
        this.#imageResidencyRecordReads += 1;
      }
    } else {
      this.#localRecordReads += 1;
    }
    const record = await backend.get(records(ref.imageId), ref.objectId);
    if (record?.kind === RELOCATED_RECORD_KIND || record?.kind === SWEPT_RECORD_KIND) return null;
    return record;
  }

  async resolveImageAt(imageId, residency) {
    if (typeof imageId !== 'string' || imageId.length === 0) {
      throw new TypeError('remote image resolution requires a non-empty imageId');
    }
    if (!residency || residency.imageId !== imageId) {
      throw new TypeError('remote resolution residency does not match the imageId');
    }
    const backend = backendForResidency(residency);
    this.#imageReads += 1;
    return await backend.get(IMAGE_COLLECTION, imageId);
  }

  async writeRecordAt(ref, residency, {value, expectedVersion, stream, event}) {
    if (!isObjectRef(ref)) throw new TypeError('remote resolution requires an ObjectRef');
    if (!residency || residency.imageId !== ref.imageId) {
      throw new TypeError('remote resolution residency does not match the ObjectRef image');
    }
    if (residency.kind === PER_OBJECT_RESIDENCY && residency.objectId !== ref.objectId) {
      throw new TypeError('remote resolution residency does not match the ObjectRef object');
    }
    const backend = backendForResidency(residency);
    const remote = isRemoteResidency(residency);
    this.#recordWrites += 1;
    if (remote) {
      this.#crossNodeRecordWrites += 1;
      if (residency.kind === PER_OBJECT_RESIDENCY) {
        this.#perObjectRecordWrites += 1;
      }
    } else {
      this.#localRecordWrites += 1;
    }
    return await backend.transaction(async (candidate) => {
      const transaction = assertBackendTransaction(candidate);
      const stored = await transaction.put(records(ref.imageId), ref.objectId, value, {expectedVersion});
      await transaction.append(stream, event(stored));
      return stored;
    });
  }
}

export {RemoteRecordResolver};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {assertBackend, assertBackendTransaction} from '../backend/backend-contract.js';
import {ObjectLocator, RELOCATED_RECORD_KIND, SWEPT_RECORD_KIND} from '../graph/locator.js';
import {RemoteRecordResolver} from '../graph/remote-resolution.js';
import {assertObjectMatchesShape, createObjectRecord, createShapeRecord, normalizeMetadata} from '../object/index.js';
import {
  assertLexicalEnvironmentLayoutCompatible,
  createBlockRecord,
  createCodeArtifactRecord,
  createLexicalEnvironmentRecord,
} from '../execution/model.js';
import {objectRef} from '../value/scalars.js';
import {findTransientRefs, isTransientObjectId} from '../value/transient-ref.js';
import {IMAGE_COLLECTION, history, records, snapshots} from './storage-layout.js';

function assertAllowedFields(input, allowed, label) {
  const extra = Object.keys(input).filter((key) => !allowed.has(key));
  if (extra.length) throw new TypeError(`unknown ${label} fields: ${extra.join(', ')}`);
}

// ADR 0052 decision 5b. Every durable write in this service funnels through here, which is why the
// guard lives here rather than in each `put*`: one seam, so a record kind added later is covered
// without anyone remembering to cover it.
//
// Two refusals, and they are different failures with different scopes.
//
// A reserved *id* would create a durable record that arena-first resolution could later shadow,
// which decision 5c forbids outright. That check applies only where the key *is* an object id — the
// per-image record collection. ADR 0052 reserves the namespace for REF `objectId` specifically, not
// for every storage key, so an image may legitimately be named anything at all; an image id is not
// an object id and never appears as one in a REF.
//
// A reserved *ref* would persist a pointer to something that dies with the arena — a dangling
// reference the moment the execution ends. That applies to every durable value, image records
// included, because a transient ref is just as dangling wherever it is stored.
//
// Neither should ever fire in correct operation: the central promotion operation runs first and
// rewrites transient refs. This is the proof that it did, not the mechanism that does it.
function assertNoTransientIdentity(collection, key, value, {keyIsObjectId}) {
  if (keyIsObjectId && isTransientObjectId(key)) {
    throw new TypeError(
      `cannot write a durable record at the runtime-reserved transient id ${key} in ${collection}`,
    );
  }
  const embedded = findTransientRefs(value);
  if (embedded.length > 0) {
    const {imageId, objectId} = embedded[0];
    throw new TypeError(
      `cannot write a durable record embedding the unpromoted transient reference `
      + `${imageId}/${objectId}; it must be promoted first`,
    );
  }
}

async function putWithHistory(backend, {
  collection,
  key,
  value,
  expectedVersion,
  stream,
  event,
  // True where `key` is a graph object id, which is the only place ADR 0052's reserved namespace
  // applies. Default false so a new caller has to say so deliberately rather than inherit a
  // restriction on whatever its keys happen to mean.
  keyIsObjectId = false,
}) {
  assertNoTransientIdentity(collection, key, value, {keyIsObjectId});
  return await backend.transaction(async (candidate) => {
    const transaction = assertBackendTransaction(candidate);
    const stored = await transaction.put(collection, key, value, {expectedVersion});
    await transaction.append(stream, event(stored));
    return stored;
  });
}

async function writeRecordWithResidency(service, imageId, record, {expectedVersion, at}) {
  if (
    typeof service.locator?.hasPeers === 'function' &&
    service.locator.hasPeers() &&
    typeof service.remoteResolution?.writeRecordAt === 'function'
  ) {
    assertNoTransientIdentity(records(imageId), record.id, record, {keyIsObjectId: true});
    const ref = objectRef(imageId, record.id);
    const residency = await service.locator.locate(ref);
    if (!residency) throw new TypeError(`image not found: ${imageId}`);
    return await service.remoteResolution.writeRecordAt(ref, residency, {
      value: record,
      expectedVersion,
      stream: history(imageId),
      event: (saved) => putEventForRecord(saved, at),
    });
  }
  return await putWithHistory(service.backend, {
    collection: records(imageId),
    keyIsObjectId: true,
    key: record.id,
    value: record,
    expectedVersion,
    stream: history(imageId),
    event: (saved) => putEventForRecord(saved, at),
  });
}
//
// ONE owner for "N durable records + N history events -> one backend transaction".
// Both the existing single-record put paths and the heterogeneous batch route
// through the SAME per-kind prepare/validate/event owners below, so the batch can
// never drift from the single-record semantics. The backend stays unaware of
// record kinds/image semantics.
//
// The per-kind history event. Single owner for the exact event payload each record
// kind emits; the single-record put methods and the batch share it, so no generic
// `record.put` event can ever be invented and ADR 0071 replay stays truthful.
function putEventForRecord(saved, at) {
  switch (saved.kind) {
    case 'shape':
      return {type: 'shape.put', at, shapeId: saved.id, shapeVersion: saved._version, shape: structuredClone(saved)};
    case 'object':
      return {type: 'object.put', at, objectId: saved.id, objectVersion: saved._version, object: structuredClone(saved)};
    case 'code-artifact':
      return {type: 'code-artifact.put', at, artifactId: saved.id, artifactVersion: saved._version, artifact: structuredClone(saved)};
    case 'lexical-environment':
      return {type: 'lexical-environment.put', at, environmentId: saved.id, environmentVersion: saved._version, environment: structuredClone(saved)};
    case 'block':
      return {type: 'block.put', at, blockId: saved.id, blockVersion: saved._version, block: structuredClone(saved)};
    default:
      throw new TypeError(`unknown record kind for history event: ${saved?.kind ?? 'missing'}`);
  }
}

// The ONE owner of "N prepared candidate records + N history events -> one backend
// transaction". Both `putObjects` (generic-object batch) and `createRecords`
// (heterogeneous batch) delegate the actual atomic commit here, so there is exactly
// one place that pairs a per-record put with its per-kind history append inside a
// single transaction. A module-level function (not a private method) because the
// service is consumed through lane wrappers that cannot reach private receivers.
// expectedVersion is insert-only 0 unless a caller deliberately overrides (the ADR
// 0067 batch's CAS-retry contract).
async function commitCandidateRecords(backend, imageId, candidates, {at, expectedVersion = 0} = {}) {
  return await backend.transaction(async (candidate) => {
    const transaction = assertBackendTransaction(candidate);
    const results = [];
    for (const record of candidates) {
      assertNoTransientIdentity(records(imageId), record.id, record, {keyIsObjectId: true});
      const stored = await transaction.put(records(imageId), record.id, record, {expectedVersion});
      await transaction.append(history(imageId), putEventForRecord(stored, at));
      results.push(stored);
    }
    return results;
  });
}

// The field whitelist each kind's write seam enforces (identical to the single-record
// put methods). One definition so the batch cannot drift.
const RECORD_INPUT_FIELDS = Object.freeze({
  'shape': new Set(['id', 'slots', 'indexed', 'metadata']),
  'object': new Set(['id', 'shape', 'behavior', 'slots', 'indexed', 'metadata']),
  'code-artifact': new Set(['id', 'languageId', 'representation', 'content', 'logicalPath', 'dependencies', 'derivedFrom', 'metadata']),
  'lexical-environment': new Set(['id', 'parent', 'bindings', 'metadata']),
  'block': new Set(['id', 'code', 'environment', 'metadata']),
});

// The human-readable label each kind's field-whitelist error uses, matching the
// established single-record put contracts exactly (so error messages do not change).
const RECORD_INPUT_LABEL = Object.freeze({
  'shape': 'shape',
  'object': 'generic object',
  'code-artifact': 'code artifact',
  'lexical-environment': 'lexical environment',
  'block': 'block',
});

// Phase 1: build the canonical candidate record from the existing record-model
// owner, with the kind's field whitelist enforced. No relational validation and no
// durable effect here. `at` is the one operation timestamp for the whole batch.
function prepareCandidateRecord(kind, imageId, input, {at, mintId}) {
  // The `kind` discriminant selects the schema; it is not itself a record field, so
  // it is excluded from the field whitelist (the single-record put methods never
  // see it). Everything else is validated exactly as the single-record path does.
  const {kind: _kind, ...fields} = input;
  assertAllowedFields(fields, RECORD_INPUT_FIELDS[kind], RECORD_INPUT_LABEL[kind]);
  const id = input.id ?? mintId();
  switch (kind) {
    case 'shape':
      return createShapeRecord({
        id, imageId, slots: input.slots ?? [], metadata: input.metadata ?? {}, updatedAt: at,
        ...(Object.hasOwn(input, 'indexed') ? {indexed: input.indexed} : {}),
      });
    case 'object':
      return createObjectRecord({
        id, imageId, shape: input.shape, behavior: input.behavior ?? null, slots: input.slots ?? {},
        metadata: input.metadata ?? {}, updatedAt: at,
        ...(Object.hasOwn(input, 'indexed') ? {indexed: input.indexed} : {}),
      });
    case 'code-artifact':
      return createCodeArtifactRecord({
        id, imageId, languageId: input.languageId ?? null, representation: input.representation,
        content: input.content, logicalPath: input.logicalPath ?? null,
        dependencies: input.dependencies ?? [], derivedFrom: input.derivedFrom ?? [],
        metadata: input.metadata ?? {}, updatedAt: at,
      });
    case 'lexical-environment':
      return createLexicalEnvironmentRecord({
        id, imageId, parent: input.parent ?? null, bindings: input.bindings ?? {},
        metadata: input.metadata ?? {}, updatedAt: at,
      });
    case 'block':
      return createBlockRecord({
        id, imageId, code: input.code, environment: input.environment ?? null,
        metadata: input.metadata ?? {}, updatedAt: at,
      });
    default:
      throw new TypeError(`unknown record kind: ${kind}`);
  }
}

// Phase 3: relational validation against a resolver. EXACTLY the rules the
// single-record put methods enforce — no broadened or narrowed semantics. The
// resolver is batch-local for the heterogeneous path (a fresh record created in the
// same batch resolves), and the plain GraphImageService record read for a single
// put. `resolve(ref)` must return the candidate/existing record or null, and
// `resolveKind(ref)` its kind (or null). `existing` is the pre-existing durable
// record at the candidate's own id (for the lexical-environment layout rule), if any.
async function validateCandidateRecord(candidate, {resolve, resolveKind, existing}) {
  switch (candidate.kind) {
    case 'shape':
      return; // Shape's own model validation already ran in prepare; no graph edges.
    case 'object': {
      if ((await resolveKind(candidate.shape)) !== 'shape') {
        throw new TypeError(`shape not found: ${candidate.shape.imageId}/${candidate.shape.objectId}`);
      }
      assertObjectMatchesShape(candidate, await resolve(candidate.shape));
      return;
    }
    case 'code-artifact':
      for (const dependency of candidate.dependencies) {
        if ((await resolveKind(dependency.artifact)) !== 'code-artifact') {
          throw new TypeError(`code artifact dependency ${dependency.role} must reference a code-artifact: ${dependency.artifact.imageId}/${dependency.artifact.objectId}`);
        }
      }
      return;
    case 'lexical-environment':
      if (candidate.parent && (await resolveKind(candidate.parent)) !== 'lexical-environment') {
        throw new TypeError(`lexical environment parent must reference a lexical-environment: ${candidate.parent.imageId}/${candidate.parent.objectId}`);
      }
      if (existing) {
        if (existing.kind !== 'lexical-environment') {
          throw new TypeError(`record already exists with another kind: ${candidate.imageId}/${candidate.id}`);
        }
        assertLexicalEnvironmentLayoutCompatible(existing, candidate);
      }
      return;
    case 'block':
      if ((await resolveKind(candidate.code)) !== 'code-artifact') {
        throw new TypeError(`block code must reference a code-artifact: ${candidate.code.imageId}/${candidate.code.objectId}`);
      }
      if (candidate.environment && (await resolveKind(candidate.environment)) !== 'lexical-environment') {
        throw new TypeError(`block environment must reference a lexical-environment: ${candidate.environment.imageId}/${candidate.environment.objectId}`);
      }
      return;
    default:
      throw new TypeError(`unknown record kind: ${candidate.kind}`);
  }
}

class ImageService {
  constructor({backend, clock = () => new Date(), locator = null, remoteResolution = null, peers = undefined} = {}) {
    this.backend = assertBackend(backend);
    this.clock = clock;
    this.locator = locator ?? new ObjectLocator({backend: this.backend, peers});
    this.remoteResolution = remoteResolution ?? new RemoteRecordResolver();
    if (typeof this.locator?.locate !== 'function') {
      throw new TypeError('locator must provide locate(ref)');
    }
    if (typeof this.remoteResolution?.resolveAt !== 'function') {
      throw new TypeError('remoteResolution must provide resolveAt(ref, residency)');
    }
  }

  now() { return this.clock().toISOString(); }

  async createImage({id = randomUUID(), name = id, language = 'symmetric-smalltalk', metadata = {}} = {}) {
    const at = this.now();
    if (await this.backend.get(IMAGE_COLLECTION, id)) throw new TypeError(`image already exists: ${id}`);
    const image = await putWithHistory(this.backend, {
      collection: IMAGE_COLLECTION,
      key: id,
      value: {
        id, name, language, rootObjectId: null,
        metadata: normalizeMetadata(metadata, 'image metadata'),
        createdAt: at, updatedAt: at,
      },
      expectedVersion: 0,
      stream: history(id),
      event: (stored) => ({type: 'image.created', at, image: structuredClone(stored)}),
    });
    return image;
  }

  async getImage(imageId) {
    const image = await this.backend.get(IMAGE_COLLECTION, imageId);
    if (image) return image;
    if (
      typeof this.locator.locateImage === 'function' &&
      typeof this.remoteResolution.resolveImageAt === 'function'
    ) {
      const residency = await this.locator.locateImage(imageId);
      if (residency) {
        const remote = await this.remoteResolution.resolveImageAt(imageId, residency);
        if (remote) return remote;
      }
    }
    throw new TypeError(`image not found: ${imageId}`);
  }

  async listImages() {
    return (await this.backend.scan(IMAGE_COLLECTION)).map(({value}) => value);
  }

  async putShape(imageId, input) {
    await this.getImage(imageId);
    const at = this.now();
    // One owner: prepare/validate/event all route through the shared per-kind owners,
    // so the single-record path and the heterogeneous batch can never drift apart.
    const shape = prepareCandidateRecord('shape', imageId, input, {at, mintId: randomUUID});
    await validateCandidateRecord(shape, {resolve: () => null, resolveKind: () => null, existing: null});
    return await writeRecordWithResidency(this, imageId, shape, {expectedVersion: 0, at});
  }

  async getRecord(imageId, recordId) {
    const ref = objectRef(imageId, recordId);
    const residency = await this.locator.locate(ref);
    if (!residency) throw new TypeError(`image not found: ${imageId}`);
    return await this.remoteResolution.resolveAt(ref, residency);
  }

  async requireRecordKind(ref, kind, label) {
    const record = await this.getRecord(ref.imageId, ref.objectId);
    if (!record || record.kind !== kind) {
      throw new TypeError(`${label} must reference a ${kind}: ${ref.imageId}/${ref.objectId}`);
    }
    return record;
  }

  async getShape(imageId, shapeId) {
    const record = await this.getRecord(imageId, shapeId);
    return record?.kind === 'shape' ? record : null;
  }

  async listRecords(imageId) {
    await this.getImage(imageId);
    const entries = await this.backend.scan(records(imageId));
    const results = [];
    for (const {value} of entries) {
      if (value?.kind === SWEPT_RECORD_KIND) {
        continue;
      }
      if (value?.kind === RELOCATED_RECORD_KIND) {
        const resolved = await this.getRecord(imageId, value.id);
        if (resolved) results.push(resolved);
      } else {
        results.push(value);
      }
    }
    return results;
  }

  async sweepRecords(imageId, recordIds, {reason = 'unreachable'} = {}) {
    const image = await this.getImage(imageId);
    if (!Array.isArray(recordIds)) {
      throw new TypeError('sweepRecords recordIds must be an array');
    }
    if (typeof reason !== 'string' || reason.length === 0) {
      throw new TypeError('sweepRecords reason must be a non-empty string');
    }
    const uniqueIds = [...new Set(recordIds)];
    for (const id of uniqueIds) {
      if (typeof id !== 'string' || id.length === 0) {
        throw new TypeError('sweepRecords recordIds must contain non-empty strings');
      }
      if (image.rootObjectId && id === image.rootObjectId) {
        throw new TypeError(`cannot sweep image rootObjectId: ${imageId}/${id}`);
      }
    }
    uniqueIds.sort((left, right) => (left < right ? -1 : left > right ? 1 : 0));
    if (uniqueIds.length === 0) return Object.freeze([]);

    const at = this.now();
    const swept = await this.backend.transaction(async (candidate) => {
      const transaction = assertBackendTransaction(candidate);
      const receipts = [];
      for (const id of uniqueIds) {
        const current = await transaction.get(records(imageId), id);
        if (!current || current.kind === RELOCATED_RECORD_KIND || current.kind === SWEPT_RECORD_KIND) {
          throw new TypeError(`record not found for sweep: ${imageId}/${id}`);
        }
        const tombstone = {
          kind: SWEPT_RECORD_KIND,
          id,
          imageId,
          previousKind: current.kind,
          previousVersion: current._version,
          reason,
          sweptAt: at,
        };
        const saved = await transaction.put(records(imageId), id, tombstone, {
          expectedVersion: current._version,
        });
        await transaction.append(history(imageId), {
          type: 'record.swept',
          at,
          recordId: id,
          recordKind: current.kind,
          previousVersion: current._version,
          sweepVersion: saved._version,
          reason,
        });
        receipts.push(Object.freeze(saved));
      }
      return receipts;
    });

    for (const id of uniqueIds) {
      this.locator.invalidate?.(objectRef(imageId, id));
    }
    return Object.freeze(swept);
  }

  async listShapes(imageId) {
    return (await this.listRecords(imageId)).filter(({kind}) => kind === 'shape');
  }

  async putObject(imageId, input, {expectedVersion} = {}) {
    await this.getImage(imageId);
    const at = this.now();
    const object = prepareCandidateRecord('object', imageId, input, {at, mintId: randomUUID});
    await validateCandidateRecord(object, {
      resolve: (ref) => this.getRecord(ref.imageId, ref.objectId),
      resolveKind: async (ref) => (await this.getRecord(ref.imageId, ref.objectId))?.kind ?? null,
      existing: null,
    });
    return await writeRecordWithResidency(this, imageId, object, {expectedVersion, at});
  }

  // ADR 0067. N create specs, one transaction, all-or-none. Each element goes through the same
  // field/record/shape checks as putObject, but every put+append pair is committed inside a single
  // backend.transaction. The caller is expected to have already authorized every member (this is a
  // graph write, not an authority surface); the atomicity envelope is what this method adds.
  async putObjects(imageId, inputs, {expectedVersion = 0} = {}) {
    if (!Array.isArray(inputs) || inputs.length === 0) {
      throw new TypeError('putObjects inputs must be a non-empty array');
    }
    await this.getImage(imageId);
    const at = this.now();
    // Phase 1 + 3: build and validate each generic Object candidate through the SAME
    // owners the heterogeneous batch uses. putObjects is objects-only and resolves
    // Shapes from EXISTING storage (its ADR 0067 contract predates the batch-local
    // overlay), so its resolver is the plain record read — no fresh-in-batch shapes.
    const prepared = [];
    for (const [index, input] of inputs.entries()) {
      const object = prepareCandidateRecord('object', imageId, input, {at, mintId: randomUUID});
      await validateCandidateRecord(object, {
        resolve: (ref) => this.getRecord(ref.imageId, ref.objectId),
        resolveKind: async (ref) => (await this.getRecord(ref.imageId, ref.objectId))?.kind ?? null,
        existing: null,
      });
      prepared.push(object);
    }
    // Phase 4: the SAME atomic commit owner as the heterogeneous batch.
    return await commitCandidateRecords(this.backend, imageId, prepared, {at, expectedVersion});
  }

  // The ONE owner of "N prepared candidate records + N history events -> one
  // backend transaction". Both `putObjects` (generic-object batch) and
  // `createRecords` (heterogeneous batch) delegate the actual atomic commit here,
  // so there is exactly one place that pairs a per-record put with its history
  // ADR 0074 §H follow-up (bead lagrange-images-595): ONE atomic heterogeneous
  // insert-only creation operation for the existing durable record kinds. Every
  // prepared record + its correct per-kind history event commits, or none do. This
  // is a trusted GraphImageService substrate seam — NOT arbitrary heterogeneous
  // mutation, a general multi-record transaction API, deletion, a cross-Image
  // transaction, an authority surface, or graph-bundle import.
  //
  // Inputs are discriminated by the EXISTING durable record kind:
  //   {kind:'shape'| 'object'| 'code-artifact'| 'lexical-environment'| 'block', ...}
  //
  // The batch-local overlay (Phase 2) lets a record reference another record created
  // in the SAME batch — a fresh Object -> fresh Shape, Block -> fresh CodeArtifact +
  // LexicalEnvironment, CodeArtifact -> fresh CodeArtifact dependency — without
  // pretending the referenced record pre-existed. Validation reuses EXACTLY the
  // single-record semantic owners; no broadened or narrowed graph semantics.
  async createRecords(imageId, inputs) {
    if (!Array.isArray(inputs) || inputs.length === 0) {
      throw new TypeError('createRecords inputs must be a non-empty array');
    }
    await this.getImage(imageId);
    const at = this.now();

    // Phase 1 — structural preparation, no durable effect. Build every canonical
    // candidate via the existing record-model owner; enforce non-empty, known kinds,
    // unique candidate ids, target-image membership, no _version, no transient, and
    // insert-only semantics.
    const candidates = [];
    const byId = new Map();
    for (const [index, input] of inputs.entries()) {
      if (!input || typeof input !== 'object' || Array.isArray(input)) {
        throw new TypeError(`createRecords input ${index} must be a record spec object`);
      }
      const kind = input.kind;
      if (!Object.hasOwn(RECORD_INPUT_FIELDS, kind)) {
        throw new TypeError(`createRecords input ${index} has unknown record kind: ${kind}`);
      }
      if (Object.hasOwn(input, '_version')) {
        throw new TypeError(`createRecords input ${index} must not supply _version (insert-only)`);
      }
      const record = prepareCandidateRecord(kind, imageId, input, {at, mintId: randomUUID});
      if (byId.has(record.id)) {
        throw new TypeError(`createRecords duplicate candidate id: ${imageId}/${record.id}`);
      }
      if (record.imageId !== imageId) {
        throw new TypeError(`createRecords candidate ${record.id} belongs to image ${record.imageId}, not ${imageId}`);
      }
      byId.set(record.id, record);
      candidates.push(record);
    }

    // Phase 2 — batch-local overlay resolver. Exactly one purpose: resolve(ref) is
    // the prepared batch candidate if ref names one, otherwise the existing durable
    // record via GraphImageService. Transaction/preparation-local only — not a new
    // graph namespace or durable identity system.
    const resolveOverlay = async (ref) => {
      if (ref.imageId === imageId && byId.has(ref.objectId)) return byId.get(ref.objectId);
      return await this.getRecord(ref.imageId, ref.objectId);
    };
    const resolveKind = async (ref) => (await resolveOverlay(ref))?.kind ?? null;

    // Phase 3 — relational validation via the overlay, reusing EXACTLY the
    // single-record semantic owners. Any failure -> ZERO records, ZERO history.
    for (const candidate of candidates) {
      const existing = await this.getRecord(imageId, candidate.id);
      await validateCandidateRecord(candidate, {resolve: resolveOverlay, resolveKind, existing});
    }

    // Phase 4 — ONE backend transaction. Each candidate put insert-only
    // (expectedVersion: 0) + the EXACT per-kind history event the single-record path
    // would emit. Any put/append/backend failure aborts the whole transaction.
    return await commitCandidateRecords(this.backend, imageId, candidates, {at, expectedVersion: 0});
  }

  async getObject(imageId, objectId) {
    const record = await this.getRecord(imageId, objectId);
    return record?.kind === 'object' ? record : null;
  }

  async listObjects(imageId) {
    return (await this.listRecords(imageId)).filter(({kind}) => kind === 'object');
  }

  async putCodeArtifact(imageId, input) {
    await this.getImage(imageId);
    const at = this.now();
    const artifact = prepareCandidateRecord('code-artifact', imageId, input, {at, mintId: randomUUID});
    await validateCandidateRecord(artifact, {
      resolve: (ref) => this.getRecord(ref.imageId, ref.objectId),
      resolveKind: async (ref) => (await this.getRecord(ref.imageId, ref.objectId))?.kind ?? null,
      existing: null,
    });
    return await writeRecordWithResidency(this, imageId, artifact, {expectedVersion: 0, at});
  }

  async getCodeArtifact(imageId, artifactId) {
    const record = await this.getRecord(imageId, artifactId);
    return record?.kind === 'code-artifact' ? record : null;
  }

  async listCodeArtifacts(imageId) {
    return (await this.listRecords(imageId)).filter(({kind}) => kind === 'code-artifact');
  }

  async putLexicalEnvironment(imageId, input, {expectedVersion} = {}) {
    await this.getImage(imageId);
    const at = this.now();
    const environment = prepareCandidateRecord('lexical-environment', imageId, input, {at, mintId: randomUUID});
    const current = await this.getRecord(imageId, environment.id);
    await validateCandidateRecord(environment, {
      resolve: (ref) => this.getRecord(ref.imageId, ref.objectId),
      resolveKind: async (ref) => (await this.getRecord(ref.imageId, ref.objectId))?.kind ?? null,
      existing: current,
    });
    return await writeRecordWithResidency(this, imageId, environment, {
      expectedVersion: expectedVersion ?? current?._version ?? 0,
      at,
    });
  }

  async getLexicalEnvironment(imageId, environmentId) {
    const record = await this.getRecord(imageId, environmentId);
    return record?.kind === 'lexical-environment' ? record : null;
  }

  async listLexicalEnvironments(imageId) {
    return (await this.listRecords(imageId)).filter(({kind}) => kind === 'lexical-environment');
  }

  async putBlock(imageId, input) {
    await this.getImage(imageId);
    const at = this.now();
    const block = prepareCandidateRecord('block', imageId, input, {at, mintId: randomUUID});
    await validateCandidateRecord(block, {
      resolve: (ref) => this.getRecord(ref.imageId, ref.objectId),
      resolveKind: async (ref) => (await this.getRecord(ref.imageId, ref.objectId))?.kind ?? null,
      existing: null,
    });
    return await writeRecordWithResidency(this, imageId, block, {expectedVersion: 0, at});
  }

  async getBlock(imageId, blockId) {
    const record = await this.getRecord(imageId, blockId);
    return record?.kind === 'block' ? record : null;
  }

  async listBlocks(imageId) {
    return (await this.listRecords(imageId)).filter(({kind}) => kind === 'block');
  }

  async setRoot(imageId, rootObjectId, {expectedVersion} = {}) {
    const image = await this.getImage(imageId);
    if (!await this.getObject(imageId, rootObjectId)) throw new TypeError(`root object not found: ${rootObjectId}`);
    const at = this.now();
    const stored = await putWithHistory(this.backend, {
      collection: IMAGE_COLLECTION,
      key: imageId,
      value: {...image, rootObjectId, updatedAt: at, _version: undefined},
      expectedVersion: expectedVersion ?? image._version,
      stream: history(imageId),
      event: (saved) => ({type: 'image.root-set', at, rootObjectId, imageVersion: saved._version}),
    });
    return stored;
  }

  async history(imageId, options = {}) {
    await this.getImage(imageId);
    return await this.backend.readStream(history(imageId), options);
  }

  // ADR 0071 Q1: the current committed Image frontier — the per-image
  // history-stream high-water revision. This is a stable-current-position fence,
  // not an as-of read, atomic snapshot, retention promise, multi-Image
  // transaction, or Project frontier capture. Reading it advances nothing.
  //
  // Ownership: this method is about the current committed IMAGE FRONTIER. The
  // private history-stream name stays inside the Images layer; the backend's
  // `streamHead` stays about stream heads and never learns what an Image
  // frontier is. Frontier is the HISTORY revision, categorically distinct from a
  // record's per-record `_version` (ADR 0069/0071).
  async frontier(imageId) {
    await this.getImage(imageId);
    return await this.backend.streamHead(history(imageId));
  }

  async snapshot(imageId, {id = randomUUID(), label = null} = {}) {
    const image = await this.getImage(imageId);
    const data = {id, imageId, label, createdAt: this.now(), image, records: await this.listRecords(imageId)};
    return await this.backend.put(snapshots(imageId), id, data, {expectedVersion: 0});
  }
}

export {ImageService};

const IMAGE_COLLECTION = 'images';

const records = (imageId) => `image:${imageId}:objects`;
const snapshots = (imageId) => `image:${imageId}:snapshots`;
const history = (imageId) => `image:${imageId}:history`;

export {
  IMAGE_COLLECTION,
  history,
  records,
  snapshots,
};

import {
  OBJECT_READ_OPERATION,
  OBJECT_WRITE_OPERATION,
  objectResource,
} from '../authority/object-resource.js';
import {VALUE_KIND, isObjectRef, objectRef} from '../value/index.js';
import {
  COMMON_LISP_NAMESPACE_ID,
  COMMON_LISP_SYSTEM_V0,
  installCommonLispProgram,
  installCommonLispSystem,
  installCommonLispSystemFromArtifact,
  listCommonLispNamespaceBindings,
  parseCommonLispDefsystem,
  readCommonLispClassDefinition,
  readCommonLispFunctionDefinition,
  readCommonLispGenericDefinition,
  readCommonLispMacroDefinition,
  readCommonLispSource,
  readCommonLispStructDefinition,
  readCommonLispSystemDefinition,
  readCommonLispVariableDefinition,
} from './common-lisp.js';
import {
  COMMON_LISP_DEFINITION_KIND,
  COMMON_LISP_DEFINITION_READ_OPERATION,
  COMMON_LISP_DEFINITION_WRITE_OPERATION,
  assertCommonLispDefinitionKind,
  commonLispDefinitionResource,
} from './common-lisp-definition-resource.js';

// The AUTHORIZED in-image Common Lisp browsing seam (ADR 0087, ADR 0099, bead lagrange-images-gn41).
//
// This is an IMAGES semantic API. It answers ordinary in-image Common Lisp facts about namespaces,
// functions, macros, structs, and special variables — useful to the Object Environment and any
// headless client — without exposing storage layouts.
//
// COMPOSITION, NOT DECODING. Every fact here comes from the owner that already decides it:
//
//   namespace definition index                               listCommonLispNamespaceBindings (common-lisp.js)
//   function Block, arity/lambda-list signature, source      readCommonLispFunctionDefinition (common-lisp.js)
//   macro lambda-list and source                             readCommonLispMacroDefinition    (common-lisp.js)
//   defstruct layout, accessors, and backing Class ref       readCommonLispStructDefinition   (common-lisp.js)
//   special variable current Value                           readCommonLispVariableDefinition (common-lisp.js)
//   object authority operation + resource naming             object-resource.js               (authority)
//   logical definition-position authority vocabulary         common-lisp-definition-resource.js (language)
//
// WHAT DELIBERATELY DOES NOT ESCAPE. GlobalBinding object ids or `global-binding-value` slot ids;
// `%MACRO:`, `%STRUCT:`, `%SIG:`, `%MAKE-STRUCT-*`, or `%SET-*` internal namespace keys; backend
// `_version`; semantic/syntax/WASM CodeArtifact ids; or Smalltalk camelCase slot ids underneath a
// `defstruct`.
//
// AUTHORITY. Two operations, two checks, no transitive authority (ADR 0037, ADR 0039 §2):
//
//   namespace browsing   ONE `object/read` on the namespace OBJECT (`common-lisp/namespace/v1`).
//   definition browsing  that SAME namespace check, AND an independent `common-lisp-definition/read`
//                        on the exact logical {imageId, namespaceId, kind, name} position.
//
// AUTHORIZATION BEFORE EXISTENCE. Every entry point validates its caller-supplied inputs (which
// discloses nothing), then requires, then reads. A denied caller cannot tell an existing namespace
// or definition from a missing one: both fail with AuthorityError.

const COMMON_LISP_NAMESPACE_DESCRIPTION_V1 = 'common-lisp-namespace-description/v1';
const COMMON_LISP_DEFINITION_DESCRIPTION_V1 = 'common-lisp-definition-description/v1';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function assertRequire(require, label) {
  if (typeof require !== 'function') {
    throw new TypeError(`${label} requires a require(demand) authority-check function`);
  }
  return require;
}

const readDemand = (imageId, objectId) => ({
  operation: OBJECT_READ_OPERATION,
  resource: objectResource(imageId, objectId),
});

const writeDemand = (imageId, objectId) => ({
  operation: OBJECT_WRITE_OPERATION,
  resource: objectResource(imageId, objectId),
});

async function authorizedDescribeCommonLispNamespace({
  images,
  imageId,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  assertRequire(require, 'authorizedDescribeCommonLispNamespace');

  require(readDemand(imageId, namespaceId));

  const bindings = await listCommonLispNamespaceBindings({images, imageId, namespaceId});
  return Object.freeze({
    format: COMMON_LISP_NAMESPACE_DESCRIPTION_V1,
    namespace: objectRef(imageId, namespaceId),
    functions: bindings.functions,
    macros: bindings.macros,
    structs: bindings.structs,
    variables: bindings.variables,
  });
}

async function authorizedDescribeCommonLispDefinition({
  images,
  imageId,
  kind,
  name,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  const validKind = assertCommonLispDefinitionKind(
    kind,
    'authorizedDescribeCommonLispDefinition kind',
  );
  const canonicalName = requiredText(
    name,
    'authorizedDescribeCommonLispDefinition name',
  ).toUpperCase();
  assertRequire(require, 'authorizedDescribeCommonLispDefinition');

  require(readDemand(imageId, namespaceId));
  require({
    operation: COMMON_LISP_DEFINITION_READ_OPERATION,
    resource: commonLispDefinitionResource(imageId, validKind, canonicalName, {namespaceId}),
  });

  const namespaceRef = objectRef(imageId, namespaceId);

  switch (validKind) {
    case COMMON_LISP_DEFINITION_KIND.FUNCTION: {
      const def = await readCommonLispFunctionDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define function ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.FUNCTION,
        name: def.name,
        function: def.blockRef,
        signature: def.signature,
        source: def.source,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.MACRO: {
      const def = await readCommonLispMacroDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define macro ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.MACRO,
        name: def.name,
        lambdaList: def.lambdaList,
        source: def.source,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.STRUCT: {
      const def = await readCommonLispStructDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define struct ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.STRUCT,
        name: def.name,
        class: def.classRef,
        className: def.className,
        include: def.include,
        concName: def.concName,
        constructor: def.constructor,
        predicate: def.predicate,
        copier: def.copier,
        slots: def.slots,
        localSlots: def.localSlots,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.CLASS: {
      const def = await readCommonLispClassDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define class ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.CLASS,
        name: def.name,
        class: def.classRef,
        className: def.className,
        superclasses: def.superclasses,
        cpl: def.cpl,
        slots: def.slots,
        localSlots: def.localSlots,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.GENERIC: {
      const def = await readCommonLispGenericDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define generic ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.GENERIC,
        name: def.name,
        parameters: def.parameters,
        methods: def.methods,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.VARIABLE: {
      const def = await readCommonLispVariableDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define variable ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.VARIABLE,
        name: def.name,
        value: def.value,
      });
    }
    case COMMON_LISP_DEFINITION_KIND.SYSTEM: {
      const def = await readCommonLispSystemDefinition({
        images,
        imageId,
        name: canonicalName,
        namespaceId,
      });
      if (!def) {
        throw new TypeError(
          `Common Lisp namespace ${imageId}/${namespaceId} does not define system ${canonicalName}`,
        );
      }
      return Object.freeze({
        format: COMMON_LISP_DEFINITION_DESCRIPTION_V1,
        namespace: namespaceRef,
        kind: COMMON_LISP_DEFINITION_KIND.SYSTEM,
        name: def.name,
        description: def.description,
        version: def.version,
        serial: def.serial,
        dependsOn: def.dependsOn,
        loadOrder: def.loadOrder,
      });
    }
    default:
      throw new TypeError(`unsupported Common Lisp definition kind: ${validKind}`);
  }
}

function validateReplacementForm(forms, validKind, canonicalName) {
  if (!Array.isArray(forms) || forms.length !== 1 || forms[0]?.kind !== 'list' || forms[0].elements.length < 2) {
    throw new SyntaxError(
      `authorizedReplaceCommonLispDefinition requires a single top-level ${validKind} definition form for ${canonicalName}`,
    );
  }
  const form = forms[0];
  const headSym = form.elements[0];
  if (headSym?.kind !== 'symbol') {
    throw new SyntaxError(`invalid Common Lisp definition form head for ${canonicalName}`);
  }
  const head = headSym.name;
  let targetSym = form.elements[1];
  if (validKind === COMMON_LISP_DEFINITION_KIND.STRUCT && targetSym?.kind === 'list') {
    targetSym = targetSym.elements[0];
  }
  const expectedHeads = {
    [COMMON_LISP_DEFINITION_KIND.FUNCTION]: ['DEFUN'],
    [COMMON_LISP_DEFINITION_KIND.MACRO]: ['DEFMACRO'],
    [COMMON_LISP_DEFINITION_KIND.STRUCT]: ['DEFSTRUCT'],
    [COMMON_LISP_DEFINITION_KIND.CLASS]: ['DEFCLASS'],
    [COMMON_LISP_DEFINITION_KIND.GENERIC]: ['DEFGENERIC', 'DEFMETHOD'],
    [COMMON_LISP_DEFINITION_KIND.VARIABLE]: ['DEFPARAMETER', 'DEFVAR'],
  }[validKind];
  if (!expectedHeads || !expectedHeads.includes(head)) {
    throw new SyntaxError(
      `Common Lisp ${validKind} replacement for ${canonicalName} must use ${expectedHeads?.join(' or ') ?? validKind}, got ${head}`,
    );
  }
  if (targetSym?.kind !== 'symbol') {
    throw new SyntaxError(`Common Lisp ${validKind} replacement target must be a symbol`);
  }
  const formName = targetSym.name.toUpperCase();
  const bareFormName = formName.includes('::') ? formName.split('::')[1] : formName;
  const bareTarget = canonicalName.includes('::') ? canonicalName.split('::')[1] : canonicalName;
  if (formName !== canonicalName && bareFormName !== bareTarget) {
    throw new SyntaxError(
      `Common Lisp ${validKind} replacement form defines ${formName}, expected ${canonicalName}`,
    );
  }
}

async function readExistingDefinitionByKind({images, imageId, namespaceId, kind, name}) {
  switch (kind) {
    case COMMON_LISP_DEFINITION_KIND.FUNCTION:
      return await readCommonLispFunctionDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.MACRO:
      return await readCommonLispMacroDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.STRUCT:
      return await readCommonLispStructDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.CLASS:
      return await readCommonLispClassDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.GENERIC:
      return await readCommonLispGenericDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.VARIABLE:
      return await readCommonLispVariableDefinition({images, imageId, name, namespaceId});
    case COMMON_LISP_DEFINITION_KIND.SYSTEM:
      return await readCommonLispSystemDefinition({images, imageId, name, namespaceId});
    default:
      return null;
  }
}

async function authorizedInstallCommonLispProgram({
  images,
  compilation = null,
  runtime = null,
  imageId,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  source,
  lane = 'neutral',
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  assertRequire(require, 'authorizedInstallCommonLispProgram');
  const parsedForms = typeof source === 'string'
    ? readCommonLispSource(requiredText(source, 'authorizedInstallCommonLispProgram source'))
    : Array.isArray(source) && source.length > 0
      ? source
      : null;
  if (!parsedForms || parsedForms.length === 0) {
    throw new TypeError('authorizedInstallCommonLispProgram source must contain at least one Common Lisp form');
  }

  require(writeDemand(imageId, namespaceId));

  const result = await installCommonLispProgram({
    images: images ?? runtime?.images,
    compilation: compilation ?? runtime?.compilation ?? null,
    runtime,
    imageId,
    source: parsedForms,
    lane,
  });

  return Object.freeze({
    installed: true,
    namespace: objectRef(imageId, namespaceId),
    functions: Object.freeze(Object.keys(result.functions).sort((a, b) => a.localeCompare(b))),
    variables: Object.freeze(Object.keys(result.variables).sort((a, b) => a.localeCompare(b))),
    macros: Object.freeze(Object.keys(result.macros).sort((a, b) => a.localeCompare(b))),
    structs: Object.freeze(Object.keys(result.structs).sort((a, b) => a.localeCompare(b))),
    classes: Object.freeze(Object.keys(result.classes).sort((a, b) => a.localeCompare(b))),
    generics: Object.freeze(Object.keys(result.generics).sort((a, b) => a.localeCompare(b))),
    packages: Object.freeze(Object.keys(result.packages).sort((a, b) => a.localeCompare(b))),
  });
}

async function authorizedInstallCommonLispSystem({
  images,
  compilation = null,
  runtime = null,
  imageId,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  asdSource,
  files = {},
  systems = {},
  systemName = null,
  lane = 'neutral',
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  requiredText(asdSource, 'authorizedInstallCommonLispSystem asdSource');
  assertRequire(require, 'authorizedInstallCommonLispSystem');

  const sysDef = parseCommonLispDefsystem(asdSource, {systemName});

  require(writeDemand(imageId, namespaceId));
  require({
    operation: COMMON_LISP_DEFINITION_WRITE_OPERATION,
    resource: commonLispDefinitionResource(imageId, COMMON_LISP_DEFINITION_KIND.SYSTEM, sysDef.name, {namespaceId}),
  });

  const installed = await installCommonLispSystem({
    images: images ?? runtime?.images,
    compilation: compilation ?? runtime?.compilation ?? null,
    runtime,
    imageId,
    asdSource,
    files,
    systems,
    systemName: sysDef.name,
    lane,
  });

  return Object.freeze({
    installed: true,
    namespace: objectRef(imageId, namespaceId),
    system: installed.system.name,
    version: installed.system.version,
    dependsOn: installed.system.dependsOn,
    loadOrder: installed.loadOrder,
  });
}

async function authorizeSystemArtifactGraph({
  images,
  imageId,
  namespaceId,
  artifactId,
  require,
  visited = new Set(),
}) {
  if (visited.has(artifactId)) return;
  visited.add(artifactId);

  require(readDemand(imageId, artifactId));

  const artifact = await images.getCodeArtifact(imageId, artifactId);
  if (!artifact || artifact.representation !== COMMON_LISP_SYSTEM_V0 || artifact.content?.kind !== VALUE_KIND.TEXT) {
    throw new TypeError(`CodeArtifact ${imageId}/${artifactId} is not a ${COMMON_LISP_SYSTEM_V0} artifact`);
  }
  const rawSysDef = JSON.parse(artifact.content.value);
  const sysName = requiredText(rawSysDef?.name, 'Common Lisp system name').toUpperCase();
  require({
    operation: COMMON_LISP_DEFINITION_WRITE_OPERATION,
    resource: commonLispDefinitionResource(imageId, COMMON_LISP_DEFINITION_KIND.SYSTEM, sysName, {namespaceId}),
  });

  for (const dep of artifact.dependencies ?? []) {
    const role = typeof dep?.role === 'string' ? dep.role : '';
    const depRef = dep?.artifact;
    if (!isObjectRef(depRef) || depRef.imageId !== imageId) continue;
    if (role.startsWith('system:')) {
      await authorizeSystemArtifactGraph({
        images,
        imageId,
        namespaceId,
        artifactId: depRef.objectId,
        require,
        visited,
      });
    } else if (role.startsWith('component:')) {
      require(readDemand(imageId, depRef.objectId));
    }
  }
}

async function authorizedInstallCommonLispSystemFromArtifact({
  images,
  compilation = null,
  runtime = null,
  imageId,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  systemArtifact,
  lane = 'neutral',
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  const artifactId = typeof systemArtifact === 'string'
    ? systemArtifact
    : isObjectRef(systemArtifact)
      ? systemArtifact.objectId
      : '';
  requiredText(artifactId, 'authorizedInstallCommonLispSystemFromArtifact systemArtifact');
  if (isObjectRef(systemArtifact) && systemArtifact.imageId !== imageId) {
    throw new TypeError(
      `Common Lisp system artifact ${systemArtifact.imageId}/${artifactId} does not belong to image ${imageId}`,
    );
  }
  assertRequire(require, 'authorizedInstallCommonLispSystemFromArtifact');

  require(writeDemand(imageId, namespaceId));

  const effectiveImages = images ?? runtime?.images;
  await authorizeSystemArtifactGraph({
    images: effectiveImages,
    imageId,
    namespaceId,
    artifactId,
    require,
  });

  const installed = await installCommonLispSystemFromArtifact({
    images: effectiveImages,
    compilation: compilation ?? runtime?.compilation ?? null,
    runtime,
    imageId,
    systemArtifact: objectRef(imageId, artifactId),
    lane,
  });

  return Object.freeze({
    installed: true,
    namespace: objectRef(imageId, namespaceId),
    system: installed.system.name,
    version: installed.system.version,
    dependsOn: installed.system.dependsOn,
    loadOrder: installed.loadOrder,
  });
}

async function authorizedReplaceCommonLispDefinition({
  images,
  compilation = null,
  runtime = null,
  imageId,
  namespaceId = COMMON_LISP_NAMESPACE_ID,
  kind,
  name,
  source,
  lane = 'neutral',
  require,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(namespaceId, 'namespaceId');
  const validKind = assertCommonLispDefinitionKind(
    kind,
    'authorizedReplaceCommonLispDefinition kind',
  );
  const canonicalName = requiredText(
    name,
    'authorizedReplaceCommonLispDefinition name',
  ).toUpperCase();
  const sourceText = requiredText(source, 'authorizedReplaceCommonLispDefinition source');
  assertRequire(require, 'authorizedReplaceCommonLispDefinition');

  const forms = readCommonLispSource(sourceText);
  validateReplacementForm(forms, validKind, canonicalName);

  require(writeDemand(imageId, namespaceId));
  require({
    operation: COMMON_LISP_DEFINITION_WRITE_OPERATION,
    resource: commonLispDefinitionResource(imageId, validKind, canonicalName, {namespaceId}),
  });

  const effectiveImages = images ?? runtime?.images;
  const existing = await readExistingDefinitionByKind({
    images: effectiveImages,
    imageId,
    namespaceId,
    kind: validKind,
    name: canonicalName,
  });
  if (!existing) {
    throw new TypeError(
      `Common Lisp namespace ${imageId}/${namespaceId} does not define ${validKind} ${canonicalName}`,
    );
  }

  await installCommonLispProgram({
    images: effectiveImages,
    compilation: compilation ?? runtime?.compilation ?? null,
    runtime,
    imageId,
    source: forms,
    lane,
  });

  return Object.freeze({
    replaced: true,
    namespace: objectRef(imageId, namespaceId),
    kind: validKind,
    name: canonicalName,
  });
}

export {
  COMMON_LISP_DEFINITION_DESCRIPTION_V1,
  COMMON_LISP_NAMESPACE_DESCRIPTION_V1,
  authorizedDescribeCommonLispDefinition,
  authorizedDescribeCommonLispNamespace,
  authorizedInstallCommonLispProgram,
  authorizedInstallCommonLispSystem,
  authorizedInstallCommonLispSystemFromArtifact,
  authorizedReplaceCommonLispDefinition,
};

import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';

// Public authority vocabulary for reading the CURRENT in-image Common Lisp definition at one
// logical namespace position. The position is stable while immutable Block/CodeArtifact revisions
// or variable bindings change, and is nameable from the public semantic locator alone: imageId,
// namespaceId, definition kind ('function' | 'macro' | 'struct' | 'variable'), and symbol name.
// Naming it reads no graph state and discloses no definition existence.
//
// Every input part is encoded independently with base64url (which excludes `.`), so the four-part
// resource string is injective by construction and cannot alias across images, namespaces, kinds,
// or symbol names (including Lisp-2 function vs variable bindings of the same symbol).
const COMMON_LISP_DEFINITION_RESOURCE_V0 = 'common-lisp-definition-resource/v0';
const COMMON_LISP_DEFINITION_READ_OPERATION = 'common-lisp-definition/read';
const COMMON_LISP_DEFINITION_WRITE_OPERATION = 'common-lisp-definition/write';
const COMMON_LISP_NAMESPACE_ID = 'common-lisp/namespace/v1';
const PART_SEPARATOR = '.';

const COMMON_LISP_DEFINITION_KIND = Object.freeze({
  FUNCTION: 'function',
  MACRO: 'macro',
  STRUCT: 'struct',
  CLASS: 'class',
  GENERIC: 'generic',
  VARIABLE: 'variable',
  SYSTEM: 'system',
});

const VALID_DEFINITION_KINDS = new Set(Object.values(COMMON_LISP_DEFINITION_KIND));

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function assertCommonLispDefinitionKind(kind, label = 'Common Lisp definition kind') {
  if (!VALID_DEFINITION_KINDS.has(kind)) {
    throw new TypeError(
      `${label} must be one of function, macro, struct, class, generic, variable, system; got ${String(kind)}`,
    );
  }
  return kind;
}

function encodePart(value) {
  return base64urlEncode(utf8Encode(value));
}

function commonLispDefinitionResource(
  imageId,
  kind,
  name,
  {namespaceId = COMMON_LISP_NAMESPACE_ID} = {},
) {
  const localImageId = requiredText(imageId, 'Common Lisp definition resource imageId');
  const localNamespaceId = requiredText(namespaceId, 'Common Lisp definition resource namespaceId');
  const validKind = assertCommonLispDefinitionKind(kind, 'Common Lisp definition resource kind');
  const canonicalName = requiredText(name, 'Common Lisp definition resource name').toUpperCase();
  return [
    encodePart(localImageId),
    encodePart(localNamespaceId),
    encodePart(validKind),
    encodePart(canonicalName),
  ].join(PART_SEPARATOR);
}

export {
  COMMON_LISP_DEFINITION_KIND,
  COMMON_LISP_DEFINITION_READ_OPERATION,
  COMMON_LISP_DEFINITION_RESOURCE_V0,
  COMMON_LISP_DEFINITION_WRITE_OPERATION,
  assertCommonLispDefinitionKind,
  commonLispDefinitionResource,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {objectRef} from '../value/index.js';
import {defineClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';

// Cuis semantic export — Stage 2 materialization (Bead lagrange-images-i3f; ADR 0072 §6 + ADR 0067).
//
// This module turns ONE canonical smalltalk/cuis-semantic-export-v1 manifest (produced by the
// OpenSmalltalk/Cuis toolchain provider, which owns ONLY the extraction seam) into ordinary Lagrange
// image objects through the SHIPPED authorized atomic creation batch (image-creation-batch-binding/v1,
// ADR 0067). No new lane, no new authority, no Cuis-specific privileged insertion path.
//
// REPRESENTATION MODEL (Peter-confirmed, narrowing the design): three language-owned representation
// Behavior classes — CuisExportPackage / CuisExportClass / CuisExportMethod — are the ADR 0067
// creation/schema boundary. An INSTANCE of CuisExportClass REPRESENTS a Cuis class; it is NOT the
// executable Lagrange Class for that Cuis class, and we never create one Behavior per exported Cuis
// class. These classes are behaviorally boring (no methods; defineClass installs empty method
// dictionaries). They live here, in the Cuis/Smalltalk compatibility personality — NOT in the generic
// image layer, which keeps knowing only Shape/Object/Value/ref/history.
//
// IDENTITY: the cuis-package/... / cuis-class/... / cuis-method/... strings are durable SEMANTIC
// identity carried as ordinary string DATA in slots. ObjectRefs are server-minted by the batch and are
// never derived from a semantic identity. Cuis-Base is never materialized as a package or class: a
// base superclass/target keeps the reserved cuis-class/Cuis-Base/<name> identity STRING in a slot and
// leaves the relationship edge EMPTY (we do not manufacture an ObjectRef for a base class).
//
// OWNERSHIP (docs/ownership.md): the image-creation-batch binding executor owns manifest->objects;
// this module is the Cuis-adapter's pure translator + the representation-class schema installer that
// feed that lane. The toolchain does not create image objects.

// The three representation Behavior class names (deliberately explicit, so nobody mistakes an instance
// for the Cuis entity it describes). defineClass gives each the deterministic id smalltalk/class/<name>.
const CUIS_EXPORT_PACKAGE_CLASS_NAME = 'CuisExportPackage';
const CUIS_EXPORT_CLASS_CLASS_NAME = 'CuisExportClass';
const CUIS_EXPORT_METHOD_CLASS_NAME = 'CuisExportMethod';

const CUIS_SEMANTIC_EXPORT_V1 = 'smalltalk/cuis-semantic-export-v1';
// The reserved package name for base-image classes. It is never materialized as a package object.
const CUIS_BASE_PACKAGE_NAME = 'Cuis-Base';
// The empty superclass identity for a class with no superclass (e.g. ProtoObject). ADR 0072 keeps this
// null; we store it as the empty string in the text slot (a text slot has no null distinct from '').
const CUIS_BASE_SUPERCLASS_NULL = '';

// The deterministic Shape ids for the three representation layouts. Shapes are immutable; these ids are
// stable so re-installation is ensure-exact-or-create (idempotent), not a fresh shape each run.
const CUIS_EXPORT_PACKAGE_SHAPE_ID = 'cuis-export/package-shape/v1';
const CUIS_EXPORT_CLASS_SHAPE_ID = 'cuis-export/class-shape/v1';
const CUIS_EXPORT_METHOD_SHAPE_ID = 'cuis-export/method-shape/v1';

// The member-record union type field names. RESERVED (consumed by the batch, never stored): `class`
// (the member's class id) and `name` (the batch-local local name). Every OTHER field maps to a slot or
// an indexed edge. Shared STRING slots are mapped by ALL THREE classes (so a member whose class does
// not use a given string simply leaves it as '' — and because every class maps it, the batch lane's
// fail-closed "unmapped field" check never rejects a string). The relationship/list fields are
// class-specific INDEXED list<string> fields, whose codec zero ([]) is the one the fail-closed check
// tolerates for a class that does not map them (the shipped presentations pattern).
//
// The ADR 0067 lane allows AT MOST ONE indexed field per class (image-creation-binding.js:98). So the
// ALWAYS-present relationship (the owning package, which is always materialized) is a SCALAR SLOT EDGE
// (edge:true on a slot, holding a local:<pkgIdentity> string resolved to the minted ObjectRef — the
// lane resolves slot-edge local: refs exactly like indexed ones, image-creation-batch-binding.js:342-388),
// and the OPTIONAL base/exported relationship (superclass / target class) is the single INDEXED edge
// (0 or 1 elements: empty for a base class, [local:<identity>] for an exported one). Every edge field
// is union-typed 'string' (a ref target can only arrive as text; the lane canonicalizes it host-side).
const MEMBER_UNION_FIELDS = Object.freeze([
  {name: 'class', type: 'string'},
  {name: 'name', type: 'string'},
  // Shared string slots (mapped by all three representation classes).
  {name: 'semanticidentity', type: 'string'},
  {name: 'entityname', type: 'string'},
  {name: 'superclassidentity', type: 'string'},
  {name: 'targetclassidentity', type: 'string'},
  {name: 'side', type: 'string'},
  {name: 'selector', type: 'string'},
  {name: 'source', type: 'string'},
  // The always-present owning-package relationship: a scalar slot edge (string holding local:<pkg>).
  {name: 'packageref', type: 'string'},
  // Class-specific indexed list<string> fields ([] for classes that do not map them).
  {name: 'requirements', type: {kind: 'list', element: 'string'}},
  {name: 'superclassref', type: {kind: 'list', element: 'string'}},
  {name: 'targetclassref', type: {kind: 'list', element: 'string'}},
]);

// The shared plain (non-edge) string-slot field mappings, identical for all three classes. Slot ids
// are stable. `packageref` is NOT shared: its `edge` flag differs per class (below), and the edge flag
// lives on the per-class mapping entry, never in the union type — so this per-class split is legal.
const SHARED_STRING_FIELDS = Object.freeze([
  {name: 'semanticidentity', slot: 'slot-semanticidentity'},
  {name: 'entityname', slot: 'slot-entityname'},
  {name: 'superclassidentity', slot: 'slot-superclassidentity'},
  {name: 'targetclassidentity', slot: 'slot-targetclassidentity'},
  {name: 'side', slot: 'slot-side'},
  {name: 'selector', slot: 'slot-selector'},
  {name: 'source', slot: 'slot-source'},
]);

// Per-class field maps for the ADR 0067 binding (AT MOST ONE indexed field per class).
// - Package: `packageref` is a NON-edge plain string slot (a Package has no owning package, so the slot
//   holds a harmless '' text Value — the edge:false branch never parses it as a ref). Its single
//   indexed field is `requirements` (a NON-edge list of cuis-package/<name> identity strings).
// - Class: `packageref` is a scalar slot EDGE (always the exported owning package, local: -> minted
//   ref) + single indexed edge `superclassref` (0 or 1: empty for a base superclass, [local:] for an
//   exported one).
// - Method: `packageref` is a scalar slot EDGE (always the exported owning package, local:) + single
//   indexed edge `targetclassref` (0 or 1: empty for a base target — e.g. ByteArray>>unzipped
//   targeting cuis-class/Cuis-Base/ByteArray — [local:] for an exported target).
// (Keys are the representation classes' deterministic object ids — the batch member `class` field and
// the binding fields map are both keyed by objectId, not the bare class name.)
const CUIS_EXPORT_FIELDS = Object.freeze({
  [representationClassObjectId(CUIS_EXPORT_PACKAGE_CLASS_NAME)]: Object.freeze([
    ...SHARED_STRING_FIELDS,
    {name: 'packageref', slot: 'slot-packageref'},
    {name: 'requirements', indexed: true},
  ]),
  [representationClassObjectId(CUIS_EXPORT_CLASS_CLASS_NAME)]: Object.freeze([
    ...SHARED_STRING_FIELDS,
    {name: 'packageref', slot: 'slot-packageref', edge: true},
    {name: 'superclassref', indexed: true, edge: true},
  ]),
  [representationClassObjectId(CUIS_EXPORT_METHOD_CLASS_NAME)]: Object.freeze([
    ...SHARED_STRING_FIELDS,
    {name: 'packageref', slot: 'slot-packageref', edge: true},
    {name: 'targetclassref', indexed: true, edge: true},
  ]),
});

// The Shape slot declarations shared by all three representation layouts. `slot-packageref` holds the
// owning-package ref Value for Class/Method; for Package it holds a harmless '' text Value (a Package
// has no owning package).
const SHARED_SHAPE_SLOTS = Object.freeze([
  {id: 'slot-semanticidentity', name: 'semanticIdentity'},
  {id: 'slot-entityname', name: 'entityName'},
  {id: 'slot-superclassidentity', name: 'superclassIdentity'},
  {id: 'slot-targetclassidentity', name: 'targetClassIdentity'},
  {id: 'slot-side', name: 'side'},
  {id: 'slot-selector', name: 'selector'},
  {id: 'slot-source', name: 'source'},
  {id: 'slot-packageref', name: 'packageRef'},
]);

// Install (ensure-exact-or-create) the three representation Behavior classes and their instance
// Shapes. This is a SEPARATE prerequisite schema step: the classes are infrastructure, installed once
// and idempotently (defineClass and ensureSmalltalkShape are both ensure-exact-or-create: an exact
// existing record is reused, a differing one is a conflict, an absent one is created); the
// all-or-none atomicity that matters is the manifest instance graph, not this schema. Returns the
// class refs + shape refs the caller needs to authorize object/create and to build the binding.
async function ensureCuisExportSchema({images, imageId} = {}) {
  // ensureSmalltalkShape is get-then-put with a layout-projection conflict check: re-running the
  // schema install (a retry after a lost acknowledgement, or a second materialization into a reused
  // image) reuses the existing Shapes instead of failing putShape's expectedVersion:0.
  const desired = (id) => ({id, slots: [...SHARED_SHAPE_SLOTS], indexed: SHAPE_INDEXED.VALUES});
  const packageShapeRef = await ensureSmalltalkShape(images, imageId, desired(CUIS_EXPORT_PACKAGE_SHAPE_ID));
  const classShapeRef = await ensureSmalltalkShape(images, imageId, desired(CUIS_EXPORT_CLASS_SHAPE_ID));
  const methodShapeRef = await ensureSmalltalkShape(images, imageId, desired(CUIS_EXPORT_METHOD_SHAPE_ID));
  const {classRef: packageClassRef} = await defineClass({
    images, imageId, name: CUIS_EXPORT_PACKAGE_CLASS_NAME, instanceShapeRef: packageShapeRef,
  });
  const {classRef: classClassRef} = await defineClass({
    images, imageId, name: CUIS_EXPORT_CLASS_CLASS_NAME, instanceShapeRef: classShapeRef,
  });
  const {classRef: methodClassRef} = await defineClass({
    images, imageId, name: CUIS_EXPORT_METHOD_CLASS_NAME, instanceShapeRef: methodShapeRef,
  });
  return Object.freeze({
    packageClassRef,
    classClassRef,
    methodClassRef,
    packageShape: {id: packageShapeRef.objectId},
    classShape: {id: classShapeRef.objectId},
    methodShape: {id: methodShapeRef.objectId},
  });
}

// --- the pure, deterministic translator ---------------------------------------------------------------

function assertManifest(manifest) {
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    throw new TypeError(`manifest must be a ${CUIS_SEMANTIC_EXPORT_V1} object`);
  }
  if (manifest.format !== CUIS_SEMANTIC_EXPORT_V1) {
    throw new TypeError(`manifest format must be ${CUIS_SEMANTIC_EXPORT_V1}, got ${manifest.format ?? 'missing'}`);
  }
  for (const key of ['packages', 'classes', 'methods']) {
    if (!Array.isArray(manifest[key])) {
      throw new TypeError(`manifest ${key} must be an array`);
    }
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function packageIdentity(packageName) {
  return `cuis-package/${packageName}`;
}

// The deterministic object id defineClass gives each representation Behavior class. The batch member's
// `class` field and the binding's fields map are both keyed by this objectId (not the bare class name).
function representationClassObjectId(className) {
  return `smalltalk/class/${className}`;
}

function isBaseClassIdentity(classIdentity) {
  return typeof classIdentity === 'string' && classIdentity.startsWith(`cuis-class/${CUIS_BASE_PACKAGE_NAME}/`);
}

// The set of class identities that THIS manifest materializes (i.e. exported, non-base classes). A
// superclass/target that is NOT in this set is a base/foreign class: keep its reserved identity string
// and leave the relationship edge empty (no recursive export, no manufactured base object).
function materializedClassIdentities(manifest) {
  const set = new Set();
  for (const cls of manifest.classes) {
    const identity = requiredText(cls.identity, 'class identity');
    if (!isBaseClassIdentity(identity)) set.add(identity);
  }
  return set;
}

// Translate one canonical manifest into the ADR 0067 member list. PURE and DETERMINISTIC: it consumes
// the manifest AS GIVEN (already canonical — the toolchain canonicalizes + sorts it) and emits members
// in a fixed order (packages, then classes, then methods), preserving the manifest's own order within
// each kind. It re-sorts nothing (a locale-dependent comparator would diverge from the byte-identical
// manifest guarantee). Local names are the FULL semantic identity strings (batch-local syntax; they
// never leak); method local names use the full target-class identity, never the manifest's simple
// className, so cross-package same-simple-name extension methods cannot collide.
//
// Returns {members, unionFields, fieldsByClass} — the member list to pack + the binding metadata the
// caller installs once. `members` is deeply frozen: the translator is a pure function and a later
// mutation must not leak between calls.
function manifestToBatchMembers(manifest) {
  assertManifest(manifest);
  const exportedClassIds = materializedClassIdentities(manifest);

  // A relationship edge: [local:<identity>] when the target is materialized in this batch, else [].
  // (We always use local: refs for intra-batch edges; the batch mints the durable ObjectRef.)
  const edgeTo = (identity, isMaterialized) => (isMaterialized ? [`local:${identity}`] : []);

  const members = [];

  // Packages. Cuis-Base is never materialized as a package.
  for (const pkg of manifest.packages) {
    const name = requiredText(pkg.name, 'package name');
    if (name === CUIS_BASE_PACKAGE_NAME) continue;
    if (!Array.isArray(pkg.requires)) throw new TypeError(`package ${name} requires must be an array`);
    members.push({
      class: representationClassObjectId(CUIS_EXPORT_PACKAGE_CLASS_NAME),
      name: packageIdentity(name),
      semanticidentity: packageIdentity(name),
      entityname: name,
      superclassidentity: CUIS_BASE_SUPERCLASS_NULL,
      targetclassidentity: '',
      side: '',
      selector: '',
      source: '',
      requirements: pkg.requires.map((r) => packageIdentity(requiredText(r, `package ${name} requirement`))),
      packageref: '',
      superclassref: [],
      targetclassref: [],
    });
  }

  // Classes (exported, non-base). The package relationship is a local ref to the exported package.
  for (const cls of manifest.classes) {
    const identity = requiredText(cls.identity, 'class identity');
    if (isBaseClassIdentity(identity)) continue;
    const packageName = requiredText(cls.package, `class ${identity} package`);
    const name = requiredText(cls.name, `class ${identity} name`);
    // superclass: null (ProtoObject) -> empty identity + empty edge; a base superclass -> reserved
    // identity string + empty edge; an exported superclass -> its identity + a local edge ref.
    const superclassIdentity = cls.superclass === null || cls.superclass === undefined
      ? CUIS_BASE_SUPERCLASS_NULL
      : requiredText(cls.superclass, `class ${identity} superclass`);
    const superclassIsExported = superclassIdentity !== CUIS_BASE_SUPERCLASS_NULL && exportedClassIds.has(superclassIdentity);
    members.push({
      class: representationClassObjectId(CUIS_EXPORT_CLASS_CLASS_NAME),
      name: identity,
      semanticidentity: identity,
      entityname: name,
      superclassidentity: superclassIdentity,
      targetclassidentity: '',
      side: '',
      selector: '',
      source: '',
      requirements: [],
      packageref: `local:${packageIdentity(packageName)}`,
      superclassref: edgeTo(superclassIdentity, superclassIsExported),
      targetclassref: [],
    });
  }

  // Methods. Owning package is always a local ref to the exported package. Target class: an exported
  // target -> local edge ref; a base target -> reserved identity string + empty edge (the
  // ByteArray>>unzipped case: owned by Compression, targeting cuis-class/Cuis-Base/ByteArray).
  for (const method of manifest.methods) {
    const identity = requiredText(method.identity, 'method identity');
    const packageName = requiredText(method.package, `method ${identity} package`);
    const targetClassIdentity = requiredText(method.class, `method ${identity} class`);
    const targetIsExported = exportedClassIds.has(targetClassIdentity);
    members.push({
      class: representationClassObjectId(CUIS_EXPORT_METHOD_CLASS_NAME),
      // Local name from the FULL target-class identity (not the manifest's simple className), so two
      // extension methods on same-named classes in different packages cannot collide.
      name: `cuis-method/${packageName}/${targetClassIdentity.slice('cuis-class/'.length)}/${requiredText(method.side, `method ${identity} side`)}/${requiredText(method.selector, `method ${identity} selector`)}`,
      semanticidentity: identity,
      entityname: '',
      superclassidentity: '',
      targetclassidentity: targetClassIdentity,
      side: requiredText(method.side, `method ${identity} side`),
      selector: requiredText(method.selector, `method ${identity} selector`),
      source: typeof method.source === 'string' ? method.source : '',
      requirements: [],
      packageref: `local:${packageIdentity(packageName)}`,
      superclassref: [],
      targetclassref: edgeTo(targetClassIdentity, targetIsExported),
    });
  }

  // Reject duplicate local names here too (the lane also checks, but a clear translator error beats a
  // lane error for a malformed manifest).
  const seen = new Set();
  for (const member of members) {
    if (seen.has(member.name)) {
      throw new TypeError(`duplicate local name derived from manifest: ${member.name}`);
    }
    seen.add(member.name);
  }

  return deepFreeze({
    members,
    unionFields: MEMBER_UNION_FIELDS,
    fieldsByClass: CUIS_EXPORT_FIELDS,
  });
}

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    for (const key of Object.keys(value)) deepFreeze(value[key]);
    Object.freeze(value);
  }
  return value;
}

export {
  CUIS_BASE_PACKAGE_NAME,
  CUIS_BASE_SUPERCLASS_NULL,
  CUIS_EXPORT_CLASS_CLASS_NAME,
  CUIS_EXPORT_CLASS_SHAPE_ID,
  CUIS_EXPORT_FIELDS,
  CUIS_EXPORT_METHOD_CLASS_NAME,
  CUIS_EXPORT_METHOD_SHAPE_ID,
  CUIS_EXPORT_PACKAGE_CLASS_NAME,
  CUIS_EXPORT_PACKAGE_SHAPE_ID,
  MEMBER_UNION_FIELDS,
  ensureCuisExportSchema,
  manifestToBatchMembers,
};

import {textValue} from '../value/index.js';
import {ensureClassFromDeclaration} from './smalltalk-class-builder.js';
import {ensureClassVariableBindings} from './smalltalk-class-variables.js';
import {
  GLOBAL_BINDING_VALUE_SLOT,
  NAMESPACE_OBJECT_ID,
  findSmalltalkGlobalNamespace,
  publishSmalltalkClassGlobals,
  reexportGlobals,
  resolveGlobal,
} from './smalltalk-globals.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {reconcileMethodsFromSource} from './smalltalk-instance-variables.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';
import {
  formatSymmetricSmalltalkMethodBlock,
  parseSymmetricSmalltalkDialect,
} from './symmetric-smalltalk-parser.js';
import {tokenizeSymmetricSmalltalk} from './symmetric-smalltalk-tokenizer.js';

// ADR 0085 M1/M2: this adapter owns translation only. The canonical representation remains owned
// by the OpenSmalltalk/Cuis toolchain provider; native builders/compilers remain the sole owners of
// Class, Metaclass, Shape, slot and method identity and behavior.
const CUIS_SEMANTIC_EXPORT_V2 = 'smalltalk/cuis-semantic-export-v2';

// The ONE seam where a Cuis semantic class identity corresponds to an already-proven native class.
// Keyed by the export owner's COMPLETE semantic identity and never by class name: a Cuis class
// merely spelled `Integer` in some other package is not this image's Integer, exactly as the M1
// root rule already said about `Object`. Nothing outside this table resolves to a native class, so
// there is no name fallback and no caller-supplied alias.
//
// Each entry also declares the POSITIONS it is proved for, because "this identity denotes that
// native class" is not one claim but two, and the two are independently justified:
//
//   cuis-class/Cuis-Base/Object   `superclass` only. The structural root for native class
//                                 construction/allocation (ADR 0085 M1) — a declared superclass
//                                 position. It is deliberately NOT a method target: installing a
//                                 package's extension selector on the root of the whole native
//                                 image is a far larger claim than M1 made, and no consumer has
//                                 demanded it.
//   cuis-class/Cuis-Base/Integer  `method-target` only. The class an ordinary native integer's
//                                 Behavior resolves to, so a Cuis package's extension method
//                                 installed here is reached by real native integer receivers.
//                                 Required by the pinned upstream JSON package:
//                                 `Integer>>jsonWriteOn:` is an extension on a class that package
//                                 does not define. This is NOT a claim that native Integer
//                                 implements every Cuis Integer protocol — that method's own
//                                 `printOn:base:` receiver requirement is a separate, unproven
//                                 native-library semantic, and a missing one stays a visible
//                                 failure rather than something this table papers over. Nor is it
//                                 a claim that Integer is a sound SUPERCLASS: native integers are
//                                 Values whose dispatch class is fixed by their kind, so a Cuis
//                                 class declaring Integer as its parent would get an inert class
//                                 no integer ever dispatches to. Refused until something proves
//                                 otherwise.
//
//   cuis-class/Cuis-Base/Array2D  `superclass` only. Required by the frozen M5.2 measurement
//                                 (bead lagrange-images-nfv1.1: `LifeArray < Array2D`; the
//                                 witness refused exactly this identity before the entry
//                                 existed). The native Array2D owner is the measured Cuis
//                                 grid protocol the unchanged Life code reaches. Resolved
//                                 through the image's native global namespace (the standard
//                                 image publishes the class as `Array2D`), not a kernel slot:
//                                 it is an ordinary library class, not an immediate-value
//                                 dispatch owner. NOT a method target: the package defines no
//                                 extension selector on Array2D, and no consumer declared one.
//   cuis-class/Cuis-Base/TextModel `superclass` only. Same frozen measurement
//                                 (`LifeModel < TextModel`; `TextModel < ActiveModel` in Cuis
//                                 is flattened into the native base, whose measured surface —
//                                 silent `triggerEvent:` with zero subscribers — is what the
//                                 unchanged `nextState` exercises). Also namespace-resolved
//                                 (`TextModel`), also refused as a method target.
//
// A Map, not an object literal, so a hostile identity such as `__proto__` cannot resolve.
const CUIS_NATIVE_MAPPING_POSITION = Object.freeze({SUPERCLASS: 'superclass', METHOD_TARGET: 'method-target'});
const CUIS_NATIVE_ROOT_OBJECT_IDENTITY = 'cuis-class/Cuis-Base/Object';
const CUIS_NATIVE_INTEGER_IDENTITY = 'cuis-class/Cuis-Base/Integer';
const CUIS_NATIVE_ARRAY2D_IDENTITY = 'cuis-class/Cuis-Base/Array2D';
const CUIS_NATIVE_TEXTMODEL_IDENTITY = 'cuis-class/Cuis-Base/TextModel';
const CUIS_NATIVE_CLASS_MAPPINGS = new Map([
  [CUIS_NATIVE_ROOT_OBJECT_IDENTITY, Object.freeze({
    slot: 'objectClass', className: 'Object', positions: Object.freeze([CUIS_NATIVE_MAPPING_POSITION.SUPERCLASS]),
  })],
  [CUIS_NATIVE_INTEGER_IDENTITY, Object.freeze({
    slot: 'integerClass', className: 'Integer', positions: Object.freeze([CUIS_NATIVE_MAPPING_POSITION.METHOD_TARGET]),
  })],
  // Ordinary library classes resolve through the image's own global namespace — the namespace
  // owner's replay/rebind semantics, never a second lookup implementation and never a name
  // guess: the NAME is part of this sealed entry, matched against the namespace as-is, and a
  // missing native class fails the import explicitly.
  [CUIS_NATIVE_ARRAY2D_IDENTITY, Object.freeze({
    globalName: 'Array2D', className: 'Array2D', positions: Object.freeze([CUIS_NATIVE_MAPPING_POSITION.SUPERCLASS]),
  })],
  [CUIS_NATIVE_TEXTMODEL_IDENTITY, Object.freeze({
    globalName: 'TextModel', className: 'TextModel', positions: Object.freeze([CUIS_NATIVE_MAPPING_POSITION.SUPERCLASS]),
  })],
]);

// The native class NAME a sealed entry denotes, answered purely (no graph read). The authorized
// import seam names its authority demands from it BEFORE any read, through the class builder's
// deterministic `smalltalk/class/<name>` identity; resolution of the actual class ref stays lazy and
// graph-backed below.
function mappedCuisClassName(identity) {
  return CUIS_NATIVE_CLASS_MAPPINGS.get(identity)?.className ?? null;
}

function isMappedCuisClass(identity) {
  return CUIS_NATIVE_CLASS_MAPPINGS.has(identity);
}

function mappedCuisIdentities(position) {
  return [...CUIS_NATIVE_CLASS_MAPPINGS]
    .filter(([, entry]) => entry.positions.includes(position))
    .map(([identity]) => identity);
}

function isMappedCuisClassAt(identity, position) {
  const entry = CUIS_NATIVE_CLASS_MAPPINGS.get(identity);
  return entry !== undefined && entry.positions.includes(position);
}

// Resolution needs the kernel, so it happens in the import phase; the plan phase asks only whether
// an identity is mapped at the position it appears in. Kernel-slot entries answer the kernel's own
// class ref; namespace entries resolve through the durable global namespace (the same owner the
// import publishes application classes through). The kernel/namespace own the ref — this never
// creates, rewrites or names a class.
async function resolveMappedCuisClass(identity, kernel, {images, imageId}) {
  const entry = CUIS_NATIVE_CLASS_MAPPINGS.get(identity);
  if (entry === undefined) return null;
  if (entry.slot) return kernel[entry.slot];
  return await namespaceMappedClass(images, imageId, entry.globalName);
}

// One namespace read per required mapping, through the namespace owner. The binding's value is
// the native Class object; a missing name refuses the import exactly like a missing kernel slot.
async function namespaceMappedClass(images, imageId, name) {
  const binding = await resolveGlobal({images, imageId, name});
  if (!binding) return null;
  const record = await images.getObject(imageId, binding.objectId);
  return record?.slots?.[GLOBAL_BINDING_VALUE_SLOT] ?? null;
}

class CuisNativeImportError extends TypeError {
  constructor(message, semanticIdentity = null) {
    super(`Cuis native import refused: ${message}`);
    this.name = 'CuisNativeImportError';
    if (semanticIdentity !== null) this.semanticIdentity = semanticIdentity;
  }
}

function fail(message, semanticIdentity = null) {
  throw new CuisNativeImportError(message, semanticIdentity);
}

function record(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) fail(`${label} must be an object`);
  return value;
}

function exactKeys(value, expected, label) {
  const keys = Object.keys(record(value, label)).sort();
  const wanted = [...expected].sort();
  if (JSON.stringify(keys) !== JSON.stringify(wanted)) {
    fail(`${label} must have exactly fields ${wanted.join(', ')}`);
  }
  return value;
}

function text(value, label) {
  if (typeof value !== 'string' || value.length === 0) fail(`${label} must be non-empty text`);
  return value;
}

function textArray(value, label) {
  if (!Array.isArray(value)) fail(`${label} must be an array`);
  const seen = new Set();
  return value.map((item) => {
    const normalized = text(item, `${label} entry`);
    if (seen.has(normalized)) fail(`${label} must not contain duplicates`);
    seen.add(normalized);
    return normalized;
  });
}

function canonicalClassIdentity(packageName, className) {
  return `cuis-class/${packageName}/${className}`;
}

function classNameFromIdentity(identity) {
  return identity.slice(identity.lastIndexOf('/') + 1);
}

function canonicalMethodIdentity(packageName, classIdentity, side, selector) {
  return `cuis-method/${packageName}/${classNameFromIdentity(classIdentity)}/${side}/${selector}`;
}

// Cuis sourceCodeAt: answers a complete method definition. The native class-scoped compiler takes
// the same method's body as a Block because selector/arity arrive separately. Standard/Cuis
// methods implicitly answer their receiver when control reaches the end, whereas a native Block
// answers its last expression, so make the method return rule explicit at this dialect boundary.
// Parsing/lowering the body and binding native state remain the existing Symmetric Smalltalk
// compiler's responsibility.
// Narrow Cuis dialect/base-image idioms, translated at the boundary that already owns dialect
// translation (the method header and the implicit-receiver return rule are translated here too).
// These are NOT class mappings and make no claim that `String` or `UnicodeString` is `Text`.
//
// The first idiom is the unary send `String new`, and the claim is only about the role that
// expression plays. Measured against the pinned Cuis VM and image and recorded on bead
// lagrange-images-nv1.5:
//
//   seedSize=0, seedPrint=''                  `String new` is an EMPTY textual seed
//   seedSizeAfterWrite=0, seedAfterWrite=''   writing through the stream does NOT mutate it: the
//                                             seed is empty, so the first write grows the stream
//                                             onto a NEW collection and the original is discarded
//   contentsIdenticalToSeed=false             the answer is not the seed either
//   thatCanBeModifiedIdentical=true           the only message `on:` sends it answers with itself,
//                                             so no identity is established and nothing is copied
//   unicodeSeedContentsClass=UnicodeString    swapping the seed for an empty UnicodeString changes
//   unicodeSeedContents='3'                   the result's SPECIES and not its textual VALUE
//
// So in this idiom the seed contributes no content, no behavior and no observable identity — only
// the species of the eventual result. The smallest truthful native counterpart is therefore an
// empty native Text value, and the substitution is exact for the covered expression, because the
// milestone's own acceptance oracle already treats a Cuis String result as a native Text value.
//
// DELIBERATELY NARROW, and each of these is a separate unproven question that stays refused:
//   `String new: 16`   a SIZED buffer. A different expression (keyword `new:`), not covered by the
//                      oracle above, and left to fail as an unbound name.
//   `String` anywhere else — as a receiver of any other message, as an argument, as a superclass,
//                      as a method target — is untouched and remains `unbound Symmetric Smalltalk
//                      name: String`. Nothing publishes a `String` global.
//   every other String use is untouched. The closed table has no name fallback.
//
// The match is on the TOKEN stream, not on text, so `'String new'` inside a string literal and
// `"String new"` inside a comment are not rewritten. An idiom is also about a GLOBAL name that the
// package does NOT define, so it does not fire when the name is bound or declared: a parameter, a
// temporary or a block parameter named `String`, or a class named `String` declared by the
// manifest itself, all mean their own thing and need no translation. A cascade is excluded too,
// because its later messages go to the receiver rather than to what `new` answered.
//
// HONEST ASYMMETRY with the class-mapping table above, which is keyed by COMPLETE semantic
// identity precisely so that a class merely SPELLED `Integer` elsewhere is not this image's
// Integer. This table cannot be keyed that way: a name inside a method body carries no package
// attribution — the export records the source text, not a resolved binding for each name in it —
// so the key is unavoidably the source token. What replaces identity keying is the narrowness of
// the claim (one expression, not a class), the exclusions above (the package's own bindings and
// declarations win), and the requirement that each entry be justified by a recorded measurement
// that the expression's object contributes nothing observable to the covered path.
//
// The second idiom is `UnicodeString writeStream`, forced by the real pinned YAXO
// `XMLTokenizer>>initialize` and measured by that vertical's real-Cuis oracle (bead
// lagrange-images-xxm.9):
//
//   UnicodeString superclass/species             CharacterSequence / UnicodeString
//   UnicodeString writeStream class              Utf8EncodedWriteStream (a WriteStream subclass)
//   empty/written/reset contents class            UnicodeString
//   empty/written contents are fresh              true
//   nextPutAll: answers the stream                 true
//   U+03BB survives in contents                   code point 955
//
// YAXO uses the two buffers only through stream protocol (`reset`, `nextPut:`, `contents`) and
// never observes their physical class. This native image has one textual representation, `Text`,
// and already has one ordinary native text-backed stream construction. The exact native semantic
// counterpart for CONSTRUCTING that buffer is therefore `(WriteStream on: '')`. Parentheses are
// part of the translation so a following unary send remains on the resulting stream rather than
// becoming part of the keyword argument. This does not claim that the two concrete Cuis stream
// classes are identical, and it does not pre-implement the later
// `reset`/`nextPut:` protocol: the executable vertical must force that breadth in its own order.
//
// DELIBERATELY NARROW in the same way as `String new`: `UnicodeString` as a value, any other send,
// a cascade, a locally bound name or a manifest-declared class remains untouched. No
// `UnicodeString` global is published, and direct native source still refuses the name.
//
// HOW THE REST OF THE PATH REALISES THESE, since the substitutions' justification depends on it:
// the seed's contribution is the result's REPRESENTATION, and the native stream owner is what
// supplies it. `WriteStream >> contents` builds its answer preserving the backing's class, so a
// text seed yields a text result. It does NOT go through `species` — measurement showed upstream's
// own `contents` is a class-preserving copy that never sends it, and that a native text Value is
// not allocatable — so nothing here depends on a Text ever answering `species`.
//
// The third idiom is the distinct `UnicodeString streamContents: [ ... ]`, forced by unchanged
// pinned YAXO `XMLTokenizer>>nextWhitespace` and measured independently (bead
// lagrange-images-xxm.11). In the pinned image UnicodeString class itself creates a
// Utf8EncodedWriteStream, evaluates the block once, ignores its answer, and returns stream
// contents. Empty, ASCII, U+03BB and supplementary U+1F600 writes all answer UnicodeString;
// multiple writes preserve order; an Error escapes unchanged; and the result is equal and has the
// same class as the corresponding `UnicodeString writeStream ... contents` result.
//
// The native image's honest counterpart is ordinary `Text class >> streamContents:` protocol,
// installed by the native Text/WriteStream owner and answering the one canonical native Text
// representation. The adapter therefore changes ONLY the foreign receiver name and selector to
// `Text streamContents:`. It does not expand the call, evaluate the block, construct the stream or
// take contents. Those semantics stay native and direct native source can call them with no Cuis
// material present. This remains no claim that UnicodeString is generally Text and publishes no
// UnicodeString global.
const CUIS_DIALECT_IDIOMS = Object.freeze([
  Object.freeze({
    receiverName: 'String',
    selector: 'new',
    arity: 0,
    lower() {
      return Object.freeze({kind: 'string', value: ''});
    },
  }),
  Object.freeze({
    receiverName: 'UnicodeString',
    selector: 'writeStream',
    arity: 0,
    lower() {
      return Object.freeze({
        kind: 'send',
        receiver: Object.freeze({kind: 'name', name: 'WriteStream'}),
        selector: 'on:',
        arguments: Object.freeze([Object.freeze({kind: 'string', value: ''})]),
      });
    },
  }),
  Object.freeze({
    receiverName: 'UnicodeString',
    selector: 'streamContents:',
    arity: 1,
    exactBlockArgument: true,
    lower([blockArg]) {
      return Object.freeze({
        kind: 'send',
        receiver: Object.freeze({kind: 'name', name: 'Text'}),
        selector: 'streamContents:',
        arguments: Object.freeze([blockArg]),
      });
    },
  }),
]);

// A dialect idiom is about a GLOBAL name. If the method binds that name itself — as a parameter,
// a temporary, a block parameter or an assignment target — then the source means something else
// entirely and needs no translation at all, so the idiom must not fire. Walking the parsed AST
// directly (ADR 0097) collects every declared temporary, block parameter and assignment target
// structurally without token-level bar heuristics.
function collectAstBoundNames(ast, parameters) {
  const bound = new Set(parameters);
  const visit = (node) => {
    if (!node || typeof node !== 'object') return;
    switch (node.kind) {
      case 'sequence':
        for (const temp of node.temporaries) bound.add(temp);
        for (const statement of node.statements) visit(statement);
        break;
      case 'block':
        for (const param of node.parameters) bound.add(param);
        visit(node.body);
        break;
      case 'assign':
        bound.add(node.name);
        visit(node.value);
        break;
      case 'return':
        visit(node.value);
        break;
      case 'send':
        visit(node.receiver);
        for (const arg of node.arguments) visit(arg);
        break;
      case 'cascade':
        visit(node.receiver);
        for (const msg of node.messages) {
          for (const arg of msg.arguments) visit(arg);
        }
        break;
      default:
        break;
    }
  };
  visit(ast);
  return bound;
}

// Structured AST-to-AST lowering of the closed three-entry `CUIS_DIALECT_IDIOMS` table (ADR 0097).
// Because matching operates on parsed `send` nodes:
//   * a cascade (`String new; yourself`) is a `cascade` node, never a `send`, so it is untouched;
//   * a unary chain (`self UnicodeString writeStream`) has a `send` receiver rather than `{kind: 'name'}`;
//   * `UnicodeString streamContents: [ ... ] yourself` parses `yourself` onto the block argument,
//     making `node.arguments[0]` a `send` node rather than `{kind: 'block'}`.
function lowerCuisDialectAst(node, context) {
  if (!node || typeof node !== 'object') return node;
  switch (node.kind) {
    case 'sequence':
      return Object.freeze({
        kind: 'sequence',
        temporaries: node.temporaries,
        statements: Object.freeze(node.statements.map((stmt) => lowerCuisDialectAst(stmt, context))),
      });
    case 'block':
      return Object.freeze({
        ...node,
        body: lowerCuisDialectAst(node.body, context),
      });
    case 'assign':
      return Object.freeze({
        kind: 'assign',
        name: node.name,
        value: lowerCuisDialectAst(node.value, context),
      });
    case 'return':
      return Object.freeze({
        ...node,
        value: lowerCuisDialectAst(node.value, context),
      });
    case 'cascade':
      return Object.freeze({
        kind: 'cascade',
        receiver: lowerCuisDialectAst(node.receiver, context),
        messages: Object.freeze(node.messages.map((msg) => Object.freeze({
          selector: msg.selector,
          arguments: Object.freeze(msg.arguments.map((arg) => lowerCuisDialectAst(arg, context))),
        }))),
      });
    case 'send': {
      const loweredArgs = Object.freeze(node.arguments.map((arg) => lowerCuisDialectAst(arg, context)));
      if (node.receiver.kind === 'name') {
        const receiverName = node.receiver.name;
        if (!context.bound.has(receiverName) && !context.declaredNames.has(receiverName)) {
          for (const idiom of CUIS_DIALECT_IDIOMS) {
            if (idiom.receiverName !== receiverName) continue;
            if (idiom.selector !== node.selector) continue;
            if (idiom.arity !== node.arguments.length) continue;
            if (idiom.exactBlockArgument && node.arguments[0]?.kind !== 'block') continue;
            return idiom.lower(loweredArgs);
          }
        }
      }
      return Object.freeze({
        kind: 'send',
        receiver: lowerCuisDialectAst(node.receiver, context),
        selector: node.selector,
        arguments: loweredArgs,
      });
    }
    default:
      return node;
  }
}

function parseCuisMethodHeader({identity, selector, source}) {
  let tokens;
  try {
    tokens = tokenizeSymmetricSmalltalk(source);
  } catch (error) {
    fail(`method ${identity} source is not in the supported native Smalltalk subset: ${error.message}`, identity);
  }
  const parameters = [];
  let parsedSelector = '';
  let index = 0;
  if (tokens[index].type === 'identifier') {
    parsedSelector = tokens[index].value;
    index += 1;
  } else if (tokens[index].type === 'binary') {
    parsedSelector = tokens[index].value;
    index += 1;
    if (tokens[index].type !== 'identifier') {
      fail(`method ${identity} binary header must declare one parameter`, identity);
    }
    parameters.push(tokens[index].value);
    index += 1;
  } else if (tokens[index].type === 'keyword') {
    while (tokens[index].type === 'keyword') {
      parsedSelector += tokens[index].value;
      index += 1;
      if (tokens[index].type !== 'identifier') {
        fail(`method ${identity} keyword part must declare a parameter`, identity);
      }
      parameters.push(tokens[index].value);
      index += 1;
    }
  } else {
    fail(`method ${identity} has an unsupported method header`, identity);
  }
  if (parsedSelector !== selector) {
    fail(`method ${identity} source header declares ${parsedSelector}, not ${selector}`, identity);
  }
  const bodyStart = tokens[index - 1].end;
  return Object.freeze({
    parameters: Object.freeze(parameters),
    bodySource: source.slice(bodyStart),
  });
}

function lowerCuisMethodToNativeSource({parameters, bodySource, declaredNames}) {
  const dialectAst = parseSymmetricSmalltalkDialect(bodySource, {allowEmpty: true});
  const bound = collectAstBoundNames(dialectAst, parameters);
  const loweredAst = lowerCuisDialectAst(dialectAst, {bound, declaredNames});
  return formatSymmetricSmalltalkMethodBlock(parameters, loweredAst);
}

// M3 (bead lagrange-images-nv1.2): a real package is imported progressively, so the caller names
// which canonical declarations this import covers. The canonical manifest is never edited — the
// scope selects from the unmodified artifact, so the export owner remains the only authority on
// what the package contains. Everything the adapter guarantees for a whole manifest holds
// unchanged for the selected subset, and an unsupported semantic INSIDE the scope is still an
// explicit refusal: nothing is silently skipped as though it had succeeded. Omitting the scope
// imports the whole manifest, which is what M1/M2 proved.
function normalizeScope(scope) {
  if (scope === undefined || scope === null) return null;
  exactKeys(scope, ['classes', 'methods'], 'import scope');
  const classes = textArray(scope.classes, 'import scope classes');
  const methods = textArray(scope.methods, 'import scope methods');
  // A scope is a positive statement about what this import covers, and the covering unit is a
  // class. Note that this is now a deliberate constraint rather than a consequence: since a
  // mapped method target needs no class-scope entry, a methods-only scope WOULD describe a real
  // import (an extension on an existing native class). No consumer has asked for one, so it stays
  // refused rather than silently proven by the classes-plus-methods path.
  if (classes.length === 0) fail('import scope must name at least one class');
  return Object.freeze({classes: new Set(classes), methods: new Set(methods)});
}

const CLASS_DEFINITION_KEYWORD = new Set([
  'subclass:',
  'variableSubclass:',
  'variableByteSubclass:',
  'variableWordSubclass:',
]);

function splitCuisChunks(pckSource) {
  const chunks = [];
  let index = 0;
  let inMethodSection = false;
  let skipNextChunk = false;

  while (index < pckSource.length) {
    while (index < pckSource.length && /\s/.test(pckSource[index])) {
      index += 1;
    }
    if (index >= pckSource.length) break;

    let isDirective = false;
    if (!inMethodSection && pckSource[index] === '!') {
      isDirective = true;
      index += 1;
    } else if (inMethodSection && pckSource[index] === '!') {
      inMethodSection = false;
      index += 1;
      continue;
    }

    let current = '';
    let inString = false;
    while (index < pckSource.length) {
      const ch = pckSource[index];
      if (ch === '\'') {
        if (inString && pckSource[index + 1] === '\'') {
          current += '\'\'';
          index += 2;
          continue;
        }
        inString = !inString;
        current += ch;
        index += 1;
        continue;
      }
      if (!inString && ch === '!') {
        if (pckSource[index + 1] === '!') {
          current += '!';
          index += 2;
          continue;
        }
        index += 1;
        break;
      }
      current += ch;
      index += 1;
    }

    const trimmed = current.trim();
    if (skipNextChunk) {
      skipNextChunk = false;
      continue;
    }
    if (isDirective) {
      if (/^[A-Za-z_][A-Za-z0-9_]*(\s+class)?\s+methodsFor:/m.test(trimmed)) {
        inMethodSection = true;
      } else if (/^commentStamp:/m.test(trimmed)) {
        skipNextChunk = true;
      }
      continue;
    }
    if (!inMethodSection && trimmed.length > 0) {
      chunks.push(trimmed);
    }
  }
  return chunks;
}

function canonicalInitializerIdentity(packageName, className, selector = 'initialize') {
  return `cuis-initializer/${packageName}/${className}/${selector}`;
}

// Parse top-level chunks of a Cuis .pck.st source string and extract explicit post-load
// `<ClassName> initialize!` chunks into canonical initializer descriptors, while refusing
// arbitrary top-level DoIt expressions (ADR 0096).
function extractCuisPackagePostLoadInitializers(packageName, pckSource) {
  const pkg = text(packageName, 'packageName');
  const source = text(pckSource, 'pckSource');
  const initializers = [];
  const seen = new Set();
  for (const trimmed of splitCuisChunks(source)) {
    let tokens;
    try {
      tokens = tokenizeSymmetricSmalltalk(trimmed);
    } catch (error) {
      fail(`Cuis package ${pkg} contains unparseable top-level chunk: ${error.message}`);
    }
    const bodyTokens = tokens.filter((token) => token.type !== 'eof');
    if (bodyTokens.length === 0) continue;
    if (bodyTokens.length === 1 && bodyTokens[0].type === 'string') continue;
    if (bodyTokens[0].type === 'identifier' && bodyTokens[1]?.type === 'keyword' && CLASS_DEFINITION_KEYWORD.has(bodyTokens[1].value)) {
      continue;
    }
    if (
      bodyTokens.length === 2
      && bodyTokens[0].type === 'identifier'
      && bodyTokens[1].type === 'identifier'
      && bodyTokens[1].value === 'initialize'
    ) {
      const className = bodyTokens[0].value;
      const classIdentity = canonicalClassIdentity(pkg, className);
      if (!seen.has(classIdentity)) {
        seen.add(classIdentity);
        initializers.push(Object.freeze({
          identity: canonicalInitializerIdentity(pkg, className, 'initialize'),
          package: pkg,
          class: classIdentity,
          selector: 'initialize',
        }));
      }
      continue;
    }
    fail(`unsupported Cuis post-load DoIt chunk in ${pkg}: ${trimmed}`);
  }
  return Object.freeze(initializers);
}

function normalizePostLoadInitializerEntry(entry, byIdentity, byClassName) {
  if (typeof entry === 'string') {
    const trimmed = text(entry, 'postLoadInitializers entry').trim();
    if (trimmed.startsWith('cuis-class/')) {
      const declaration = byIdentity.get(trimmed);
      if (!declaration) {
        fail(`postLoadInitializers names class ${trimmed}, which this manifest does not declare`, trimmed);
      }
      return Object.freeze({
        identity: canonicalInitializerIdentity(declaration.package, declaration.name, 'initialize'),
        package: declaration.package,
        class: declaration.identity,
        selector: 'initialize',
      });
    }
    let tokens;
    try {
      tokens = tokenizeSymmetricSmalltalk(trimmed);
    } catch (error) {
      fail(`postLoadInitializers entry ${trimmed} is not a valid class initializer: ${error.message}`);
    }
    const bodyTokens = tokens.filter((token) => token.type !== 'eof');
    if (
      bodyTokens.length !== 2
      || bodyTokens[0].type !== 'identifier'
      || bodyTokens[1].type !== 'identifier'
      || bodyTokens[1].value !== 'initialize'
    ) {
      fail(`postLoadInitializers only supports <ClassName> initialize, got: ${trimmed}`);
    }
    const declaration = byClassName.get(bodyTokens[0].value);
    if (!declaration) {
      fail(`postLoadInitializers names undeclared class ${bodyTokens[0].value}`);
    }
    return Object.freeze({
      identity: canonicalInitializerIdentity(declaration.package, declaration.name, 'initialize'),
      package: declaration.package,
      class: declaration.identity,
      selector: 'initialize',
    });
  }
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
    fail('postLoadInitializers entry must be an object or string');
  }
  const keys = Object.keys(entry).sort().join(',');
  if (keys !== 'class,selector' && keys !== 'class,identity,package,selector') {
    fail('postLoadInitializers entry must have fields {class, selector} or {identity, package, class, selector}');
  }
  const classIdentity = text(entry.class, 'postLoadInitializers entry class');
  const selector = text(entry.selector, 'postLoadInitializers entry selector');
  if (selector !== 'initialize') {
    fail(`postLoadInitializers selector must be initialize, got ${selector}`, classIdentity);
  }
  const declaration = byIdentity.get(classIdentity);
  if (!declaration) {
    fail(`postLoadInitializers names class ${classIdentity}, which this manifest does not declare`, classIdentity);
  }
  const expectedIdentity = canonicalInitializerIdentity(declaration.package, declaration.name, 'initialize');
  if (entry.package !== undefined && text(entry.package, 'postLoadInitializers entry package') !== declaration.package) {
    fail(`postLoadInitializers entry package ${entry.package} does not match ${declaration.package}`, classIdentity);
  }
  if (entry.identity !== undefined && text(entry.identity, 'postLoadInitializers entry identity') !== expectedIdentity) {
    fail(`postLoadInitializers entry identity ${entry.identity} does not match ${expectedIdentity}`, classIdentity);
  }
  return Object.freeze({
    identity: expectedIdentity,
    package: declaration.package,
    class: declaration.identity,
    selector: 'initialize',
  });
}

function orderPackagesByRequires(packages) {
  const byName = new Map(packages.map((pkg) => [pkg.name, pkg]));
  const rank = new Map();
  const visiting = new Set();
  const visited = new Set();
  const visit = (name) => {
    if (visited.has(name)) return;
    if (visiting.has(name)) fail(`package dependency cycle reaches ${name}`);
    const pkg = byName.get(name);
    if (!pkg) return;
    visiting.add(name);
    for (const req of pkg.requires) {
      if (byName.has(req)) visit(req);
    }
    visiting.delete(name);
    visited.add(name);
    rank.set(name, rank.size);
  };
  for (const pkg of packages) visit(pkg.name);
  return rank;
}

// Validate every adapter-owned schema, identity and dependency-graph rule before the first native
// owner call. Native declaration semantics (for example inherited-name legality) stay exclusively
// in the class builder; this adapter does not duplicate them to promise a batch transaction it does
// not own. An owner rejection may therefore leave already-valid immutable ancestors, and an exact
// retry converges through their ordinary admission rules.
function importPlan(manifest, scope, {postLoadInitializers: optionInitializers = null} = {}) {
  const requested = normalizeScope(scope);
  const manifestRecord = record(manifest, 'manifest');
  const expectedManifestKeys = Object.hasOwn(manifestRecord, 'postLoadInitializers')
    ? ['format', 'packages', 'classes', 'methods', 'postLoadInitializers']
    : ['format', 'packages', 'classes', 'methods'];
  exactKeys(manifestRecord, expectedManifestKeys, 'manifest');
  if (optionInitializers !== null && optionInitializers !== undefined && Object.hasOwn(manifestRecord, 'postLoadInitializers')) {
    fail('postLoadInitializers may be supplied on manifest or options, not both');
  }
  if (manifest.format !== CUIS_SEMANTIC_EXPORT_V2) {
    fail(`manifest format must be ${CUIS_SEMANTIC_EXPORT_V2}, got ${manifest.format ?? 'missing'}`);
  }
  if (!Array.isArray(manifest.packages)) fail('manifest packages must be an array');
  if (!Array.isArray(manifest.classes)) fail('manifest classes must be an array');
  if (!Array.isArray(manifest.methods)) fail('manifest methods must be an array');

  const packageNames = new Set();
  const normalizedPackages = [];
  for (const item of manifest.packages) {
    exactKeys(item, ['name', 'requires'], 'package declaration');
    const name = text(item.name, 'package name');
    if (packageNames.has(name)) fail(`package ${name} appears more than once`);
    packageNames.add(name);
    const requires = textArray(item.requires, `package ${name} requirements`);
    normalizedPackages.push(Object.freeze({name, requires}));
  }
  const packageRank = orderPackagesByRequires(normalizedPackages);

  const classes = [];
  const byIdentity = new Map();
  const byClassName = new Map();
  const nativeNames = new Set();
  for (const item of manifest.classes) {
    const classKeys = item?.category !== undefined
      ? ['identity', 'package', 'name', 'superclassName', 'superclass', 'instanceVariables', 'classVariables', 'category']
      : ['identity', 'package', 'name', 'superclassName', 'superclass', 'instanceVariables', 'classVariables'];
    exactKeys(
      item,
      classKeys,
      'class declaration',
    );
    const packageName = text(item.package, 'class package');
    const name = text(item.name, 'class name');
    const identity = text(item.identity, 'class semantic identity');
    if (identity !== canonicalClassIdentity(packageName, name)) {
      fail(`class semantic identity ${identity} does not match its canonical package/name`, identity);
    }
    if (byIdentity.has(identity)) fail(`class semantic identity ${identity} appears more than once`, identity);
    // A mapped identity ALREADY denotes an existing native class. If a manifest also declared it,
    // the same semantic identity would mean the mapped kernel class in one position and a freshly
    // constructed class in another, and the table would no longer be the single answer to "what
    // native class is this identity". One authority per identity: refused, not silently preferred.
    if (isMappedCuisClass(identity)) {
      fail(
        `class ${identity} is already mapped to an existing native class; `
        + 'a manifest may not also declare it',
        identity,
      );
    }
    if (nativeNames.has(name)) fail(`native class name ${name} appears more than once`, identity);
    nativeNames.add(name);
    const superclassName = text(item.superclassName, `class ${identity} superclassName`);
    const superclass = text(item.superclass, `class ${identity} superclass semantic identity`);
    if (superclass.slice(superclass.lastIndexOf('/') + 1) !== superclassName) {
      fail(`class ${identity} superclass name does not match ${superclass}`, identity);
    }
    const instanceVariables = textArray(item.instanceVariables, `class ${identity} instanceVariables`);
    // Declared class-variable NAMES are definition facts the canonical export now carries; their
    // values do not cross the boundary and are never normalized here.
    const classVariables = textArray(item.classVariables, `class ${identity} classVariables`);
    if (new Set(classVariables).size !== classVariables.length) {
      fail(`class ${identity} declares duplicate class variable names`, identity);
    }
    const category = item.category !== undefined ? text(item.category, `class ${identity} category`) : null;
    const normalized = Object.freeze({
      identity,
      package: packageName,
      name,
      superclass,
      instanceVariables,
      classVariables,
      category,
    });
    classes.push(normalized);
    byIdentity.set(identity, normalized);
    byClassName.set(name, normalized);
  }
  // Package attribution is a property of the manifest as a whole, so it is checked for every
  // declaration whether or not this import covers it.
  for (const declaration of classes) {
    if (!packageNames.has(declaration.package)) {
      fail(`class ${declaration.identity} names undeclared package ${declaration.package}`, declaration.identity);
    }
  }
  if (requested) {
    for (const identity of requested.classes) {
      if (!byIdentity.has(identity)) {
        fail(`import scope names class ${identity}, which this manifest does not declare`, identity);
      }
    }
  }
  const scopedClasses = requested === null
    ? classes
    : classes.filter((declaration) => requested.classes.has(declaration.identity));
  for (const declaration of scopedClasses) {
    if (isMappedCuisClassAt(declaration.superclass, CUIS_NATIVE_MAPPING_POSITION.SUPERCLASS)) continue;
    const parent = byIdentity.get(declaration.superclass);
    if (!parent) {
      fail(
        `unsupported superclass semantic identity ${declaration.superclass}; `
        + `outside the imported graph only these map to a native superclass: `
        + `${mappedCuisIdentities(CUIS_NATIVE_MAPPING_POSITION.SUPERCLASS).join(', ')}`,
        declaration.identity,
      );
    }
    // A superclass the scope omits is refused rather than pulled in: the caller decides what this
    // import covers, and the adapter never widens it silently.
    if (requested && !requested.classes.has(parent.identity)) {
      fail(
        `class ${declaration.identity} requires superclass ${declaration.superclass}, `
        + 'which the requested import scope omits',
        declaration.identity,
      );
    }
  }

  const ordered = [];
  const visiting = new Set();
  const visited = new Set();
  const visit = (declaration) => {
    if (visited.has(declaration.identity)) return;
    if (visiting.has(declaration.identity)) fail(`class dependency cycle reaches ${declaration.identity}`, declaration.identity);
    visiting.add(declaration.identity);
    const parent = byIdentity.get(declaration.superclass);
    if (parent) visit(parent);
    visiting.delete(declaration.identity);
    visited.add(declaration.identity);
    ordered.push(declaration);
  };
  for (const declaration of scopedClasses) visit(declaration);

  // Schema, canonical identity and uniqueness are properties of the manifest as a whole and are
  // checked for every method declaration. Native target legality and source translation are
  // properties of THIS import, so they apply to the covered methods: a Cuis package's source can
  // reach semantics this image does not support yet, and an import that does not cover such a
  // method must not be blocked by it.
  const methods = [];
  const methodIdentities = new Set();
  const nativeBindings = new Set();
  for (const item of manifest.methods) {
    const methodKeys = item?.category !== undefined
      ? ['identity', 'package', 'class', 'side', 'selector', 'source', 'category']
      : ['identity', 'package', 'class', 'side', 'selector', 'source'];
    exactKeys(item, methodKeys, 'method declaration');
    const packageName = text(item.package, 'method package');
    if (!packageNames.has(packageName)) fail(`method names undeclared package ${packageName}`);
    const classIdentity = text(item.class, 'method target class semantic identity');
    if (item.side !== 'instance' && item.side !== 'class') {
      fail(`method side must be instance or class, got ${item.side ?? 'missing'}`, item.identity ?? null);
    }
    const selector = text(item.selector, 'method selector');
    const identity = text(item.identity, 'method semantic identity');
    const expectedIdentity = canonicalMethodIdentity(packageName, classIdentity, item.side, selector);
    if (identity !== expectedIdentity) {
      fail(`method semantic identity ${identity} does not match its canonical declaration`, identity);
    }
    if (methodIdentities.has(identity)) fail(`method semantic identity ${identity} appears more than once`, identity);
    methodIdentities.add(identity);
    const binding = `${classIdentity}\u0000${item.side}\u0000${selector}`;
    if (nativeBindings.has(binding)) {
      fail(`native ${item.side} method ${classIdentity}>>${selector} appears more than once`, identity);
    }
    nativeBindings.add(binding);
    const source = text(item.source, `method ${identity} source`);
    const category = item.category !== undefined ? text(item.category, `method ${identity} category`) : null;
    if (requested && !requested.methods.has(identity)) continue;
    if (isMappedCuisClassAt(classIdentity, CUIS_NATIVE_MAPPING_POSITION.METHOD_TARGET)) {
      // An extension method on a class the package does not define is ordinary Smalltalk. The
      // target is an existing native class, so it needs no manifest declaration and no scope
      // entry: the covered METHOD is what this import requested. The native MethodDictionary
      // owner installs it exactly as it does for an imported class.
      if (item.side === 'class') {
        fail(
          `class-side method ${identity} targets mapped native class ${classIdentity}; `
          + 'only instance-side extension of a mapped native class is proven',
          identity,
        );
      }
    } else if (!byIdentity.has(classIdentity)) {
      fail(`method target ${classIdentity} is outside the imported native class graph`, identity);
    } else if (requested && !requested.classes.has(classIdentity)) {
      fail(`method target ${classIdentity} is outside the requested import scope`, identity);
    }
    const header = parseCuisMethodHeader({identity, selector, source});
    methods.push(Object.freeze({
      identity,
      package: packageName,
      category,
      classIdentity,
      side: item.side,
      selector,
      parameters: header.parameters,
      bodySource: header.bodySource,
      declaredNames: nativeNames,
    }));
  }
  if (requested) {
    for (const identity of requested.methods) {
      if (!methodIdentities.has(identity)) {
        fail(`import scope names method ${identity}, which this manifest does not declare`, identity);
      }
    }
  }

  const rawInitializers = optionInitializers ?? manifestRecord.postLoadInitializers ?? null;
  const postLoadInitializers = [];
  if (rawInitializers !== null && rawInitializers !== undefined) {
    if (!Array.isArray(rawInitializers)) fail('postLoadInitializers must be an array');
    const scopedSet = new Set(scopedClasses.map((declaration) => declaration.identity));
    const coveredClassInitSet = new Set(
      methods
        .filter((method) => method.side === 'class' && method.selector === 'initialize')
        .map((method) => method.classIdentity),
    );
    const seenInitializers = new Set();
    for (const entry of rawInitializers) {
      const normalized = normalizePostLoadInitializerEntry(entry, byIdentity, byClassName);
      const classIdentity = normalized.class;
      if (seenInitializers.has(classIdentity)) {
        fail(`postLoadInitializers must not contain duplicate class ${classIdentity}`, classIdentity);
      }
      seenInitializers.add(classIdentity);
      if (!scopedSet.has(classIdentity)) {
        fail(`postLoadInitializers target ${classIdentity} is outside the requested import scope`, classIdentity);
      }
      if (!coveredClassInitSet.has(classIdentity)) {
        fail(
          `postLoadInitializers target ${classIdentity} does not declare a covered class-side initialize method`,
          classIdentity,
        );
      }
      postLoadInitializers.push(normalized);
    }
    const orderedIndex = new Map(ordered.map((declaration, index) => [declaration.identity, index]));
    const isAncestor = (candidateAncestor, candidateDescendant) => {
      let current = byIdentity.get(candidateDescendant);
      while (current) {
        if (current.superclass === candidateAncestor) return true;
        current = byIdentity.get(current.superclass);
      }
      return false;
    };
    postLoadInitializers.sort((left, right) => {
      if (isAncestor(left.class, right.class)) return -1;
      if (isAncestor(right.class, left.class)) return 1;
      const pkgDiff = (packageRank.get(left.package) ?? 0) - (packageRank.get(right.package) ?? 0);
      if (pkgDiff !== 0) return pkgDiff;
      return (orderedIndex.get(left.class) ?? 0) - (orderedIndex.get(right.class) ?? 0);
    });
  }

  return {classes: scopedClasses, ordered, methods, postLoadInitializers: Object.freeze(postLoadInitializers)};
}

// Cancellation between declarations. The adapter checks the caller's `signal` before each class
// declaration, before namespace publication and before each class's method group — never inside
// an owner's write, so what has been admitted is complete and a retry converges through the owners'
// own admission rules (exact replay is write-free). `admitted` lists the canonical identities that
// landed before the check; nothing else about the import is retained.
class CuisNativeImportAbortedError extends Error {
  constructor({admitted, reason = null}) {
    super(`Cuis native import aborted after ${admitted.classes.length} class(es) and ${admitted.methods.length} method(s)`);
    this.name = 'CuisNativeImportAbortedError';
    this.admitted = Object.freeze({classes: Object.freeze([...admitted.classes]), methods: Object.freeze([...admitted.methods])});
    this.reason = reason;
  }
}

function assertProgressOptions(signal, onProgress) {
  if (signal !== null && (typeof signal !== 'object' || typeof signal.aborted !== 'boolean')) {
    fail('signal must be null or an AbortSignal-like object with a boolean aborted');
  }
  if (onProgress !== null && typeof onProgress !== 'function') fail('onProgress must be null or a function');
}

async function importCuisNativePackage({
  images,
  compilation,
  invocations = null,
  executor = null,
  imageId,
  manifest,
  scope = null,
  postLoadInitializers = null,
  targetNamespaceId = null,
  retainSource = false,
  retainProvenance = false,
  signal = null,
  onProgress = null,
} = {}) {
  text(imageId, 'image id');
  if (!images || typeof images !== 'object') fail('images must be an image service');
  if (typeof retainSource !== 'boolean') fail('retainSource must be a boolean');
  if (typeof retainProvenance !== 'boolean') fail('retainProvenance must be a boolean');
  if (targetNamespaceId !== null) text(targetNamespaceId, 'targetNamespaceId');
  assertProgressOptions(signal, onProgress);
  const plan = importPlan(manifest, scope, {postLoadInitializers});
  const admitted = {classes: [], methods: []};
  const checkpoint = (reason) => {
    if (signal?.aborted) throw new CuisNativeImportAbortedError({admitted, reason: signal.reason ?? reason ?? null});
  };
  const progress = (event) => { if (onProgress) onProgress(Object.freeze(event)); };
  const totals = Object.freeze({classes: plan.ordered.length, methods: plan.methods.length});
  if (plan.methods.length > 0 && (!compilation || typeof compilation.compileArtifact !== 'function')) {
    fail('compilation must be a compilation service when methods are present');
  }
  if (plan.postLoadInitializers.length > 0) {
    if (!invocations || typeof invocations.sendMessage !== 'function') {
      fail('invocations must be an invocation service when postLoadInitializers are present');
    }
    if (!executor || typeof executor.execute !== 'function') {
      fail('executor must be an execution service when postLoadInitializers are present');
    }
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) fail(`image ${imageId} has no Smalltalk kernel`);

  // The compatibility facts, resolved through the one seam. Each answers an EXISTING native class
  // ref owned by the kernel or the native global namespace; none is created, rewritten or renamed
  // here. Resolution is LAZY by necessity, not preference: the M1 seam deliberately supports
  // kernel-only images where namespace-backed entries (Array2D, TextModel) could not resolve at
  // all, and those imports never reference those superclasses — so only the mapped identities
  // THIS plan references are resolved, and each must resolve for the import to proceed.
  const resolved = new Map();
  const requiredMappedIdentities = new Set();
  for (const declaration of plan.ordered) {
    if (isMappedCuisClass(declaration.superclass)) requiredMappedIdentities.add(declaration.superclass);
  }
  for (const method of plan.methods) {
    if (isMappedCuisClass(method.classIdentity)) requiredMappedIdentities.add(method.classIdentity);
  }
  for (const identity of requiredMappedIdentities) {
    const classRef = await resolveMappedCuisClass(identity, kernel, {images, imageId});
    if (!classRef) fail(`image ${imageId} has no native class for ${identity}`, identity);
    resolved.set(identity, Object.freeze({classRef}));
  }
  for (const declaration of plan.ordered) {
    checkpoint(`before class ${declaration.identity}`);
    progress({event: 'begin', phase: 'class', identity: declaration.identity, totals});
    const superclass = resolved.get(declaration.superclass);
    if (!superclass) fail(`superclass ${declaration.superclass} was not resolved`, declaration.identity);
    resolved.set(declaration.identity, await ensureClassFromDeclaration({
      images,
      imageId,
      name: declaration.name,
      superclassRef: superclass.classRef,
      instanceVariables: declaration.instanceVariables,
      classVariables: declaration.classVariables,
      ...(retainProvenance
        ? {
          provenance: {
            package: declaration.package,
            ...(declaration.category !== null ? {category: declaration.category} : {}),
          },
        }
        : {}),
    }));
    // The declared NAMES became definition metadata at creation; the executable shared state is
    // the ClassVariableBinding object each name denotes, created here at its deterministic id so
    // the package's own class-side methods can write them. Values stay the image's nil until the
    // imported package code itself initializes them.
    if (declaration.classVariables.length > 0) {
      await ensureClassVariableBindings({images, imageId, className: declaration.name, variables: declaration.classVariables});
    }
    admitted.classes.push(declaration.identity);
    progress({event: 'admitted', phase: 'class', identity: declaration.identity, totals});
  }

  // Cuis class names live in its image-wide SystemDictionary. When the native image has installed
  // the corresponding namespace protocol, publish every scoped declaration through that existing
  // owner before compiling any method: source order must not decide whether one package class can
  // name another. A kernel-only image can still admit unnameable class structures (the M1 seam),
  // just as it could before this step; without a namespace it has no native name-resolution
  // contract for the adapter to target. Collision identity, replay and rebind preservation remain
  // wholly owned by publishSmalltalkClassGlobals/publishGlobal (ADR 0057), never duplicated here.
  checkpoint('before namespace publication');
  const globalNamespace = await findSmalltalkGlobalNamespace({images, imageId});
  if (globalNamespace && plan.classes.length > 0) {
    progress({event: 'begin', phase: 'globals', identity: null, totals});
    const classNames = plan.classes.map(({name}) => name);
    await publishSmalltalkClassGlobals({
      images,
      imageId,
      names: classNames,
    });
    if (targetNamespaceId !== null && targetNamespaceId !== NAMESPACE_OBJECT_ID) {
      await reexportGlobals({
        images,
        imageId,
        names: classNames,
        fromNamespaceId: NAMESPACE_OBJECT_ID,
        toNamespaceId: targetNamespaceId,
      });
    }
    progress({event: 'admitted', phase: 'globals', identity: null, totals});
  }

  const methodGroups = new Map();
  for (const method of plan.methods) {
    const target = resolved.get(method.classIdentity);
    const classRef = method.side === 'class' ? target.metaclassRef : target.classRef;
    const key = `${classRef.imageId}\u0000${classRef.objectId}`;
    const group = methodGroups.get(key) ?? {classRef, classIdentity: method.classIdentity, methods: [], identities: []};
    group.methods.push(method);
    group.identities.push(method.identity);
    methodGroups.set(key, group);
  }
  for (const {classRef, classIdentity, methods, identities} of methodGroups.values()) {
    // One class's methods are one reconciliation (one MethodDictionary publication), so the unit of
    // progress and of cancellation is the group: a group is admitted whole or not at all.
    checkpoint(`before the methods of ${classIdentity}`);
    progress({event: 'begin', phase: 'methods', identity: classIdentity, methods: Object.freeze([...identities]), totals});
    const loweredMethods = methods.map((method) => ({
      selector: method.selector,
      source: lowerCuisMethodToNativeSource(method),
      ...(retainProvenance
        ? {
          provenance: {
            package: method.package,
            ...(method.category !== null ? {category: method.category} : {}),
          },
        }
        : {}),
    }));
    await reconcileMethodsFromSource({
      images,
      compilation,
      imageId,
      classRef,
      methods: loweredMethods,
      retainSource,
      ...(targetNamespaceId !== null ? {namespaceId: targetNamespaceId} : {}),
      lane: 'wasm',
    });
    admitted.methods.push(...identities);
    progress({event: 'admitted', phase: 'methods', identity: classIdentity, methods: Object.freeze([...identities]), totals});
  }

  for (const initializer of plan.postLoadInitializers) {
    checkpoint(`before post-load initializer ${initializer.identity}`);
    progress({event: 'begin', phase: 'initializer', identity: initializer.identity, totals});
    const target = resolved.get(initializer.class);
    const activation = await invocations.sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: target.classRef,
      message: textValue(initializer.selector),
      arguments: [],
    }, {dispatchImage: imageId});
    await executor.execute(activation);
    progress({event: 'admitted', phase: 'initializer', identity: initializer.identity, totals});
  }

  // Semantic identity is useful to the caller, but this is deliberately transient output: the
  // adapter creates no durable side table or alternate native representation.
  return Object.freeze({
    classes: Object.freeze(plan.classes.map((declaration) => Object.freeze({
      identity: declaration.identity,
      ...resolved.get(declaration.identity),
    }))),
    ...(plan.postLoadInitializers.length === 0
      ? {}
      : {initializers: plan.postLoadInitializers}),
  });
}

