class LanguageAlreadyRegisteredError extends Error {
  constructor(id) {
    super(`language already registered: ${id}`);
    this.name = 'LanguageAlreadyRegisteredError';
  }
}

class LanguagePlatform {
  constructor() {
    this.languages = new Map();
  }

  register(descriptor) {
    if (!descriptor?.id) throw new Error('language descriptor must have an id');
    if (this.languages.has(descriptor.id)) {
      throw new LanguageAlreadyRegisteredError(descriptor.id);
    }

    const frozen = Object.freeze(structuredClone(descriptor));
    this.languages.set(frozen.id, frozen);
    return frozen;
  }

  get(id) {
    return this.languages.get(id) ?? null;
  }

  list() {
    return [...this.languages.values()];
  }
}

export {LanguageAlreadyRegisteredError, LanguagePlatform};

// Native event-model base, required by the frozen M5.2 measurement (bead lagrange-images-nfv1.1):
// `LifeModel extends TextModel`, and the imported, unchanged `LifeModel>>nextState` sends
// `self triggerEvent: #stateChanged.` and `self triggerEvent: #period` after replacing its cell
// state. The Cuis import adapter's correspondence seam maps `cuis-class/Cuis-Base/TextModel` to
// THIS class; nothing else creates or guesses the correspondence.
//
// RECORDED REAL-CUIS ORACLE (bead lagrange-images-nfv1.1, running the real pinned Cuis 7.9 image
// headlessly through the LIFE model itself): `LifeModel>>nextState` completes — twice, through
// event fires with ZERO subscribers — and the measured behavior is a SILENT SKIP, not an error
// and not a nil dispatch. `TextModel < ActiveModel` in Cuis, but ActiveModel is imported here
// as one flattened base because the M5 acceptance path (LifeModel `new`, plus `triggerEvent:`
// with no subscribers) exercises exactly that measured surface. ActiveModel's real action-map
// protocol (`when:send:to:`, `updateableActionMap`, `removeAllActions`) remains ABSENT: the
// acceptance scope imports no views, so no subscriber protocol is yet load-bearing. Execution
// pressure adds protocol one proven consumer at a time.
import {ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

const ACTIVE_MODEL_SHAPE_ID = 'smalltalk/active-model-instance-shape/v1';

// Measured: a `triggerEvent:` with no registered actions is silent and completes. Returning the
// receiver is the safe identity answer for the unchanged callers that chain off it.
const ACTIVE_MODEL_METHODS = Object.freeze([
  {selector: 'triggerEvent:', source: '[ :aSymbol | ^ self ]'},
]);

async function installSmalltalkActiveModelProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  const instanceShapeRef = await ensureSmalltalkShape(images, imageId, {
    id: ACTIVE_MODEL_SHAPE_ID, slots: [],
  });
  const {classRef, metaclassRef} = await ensureNamedClass({
    images, imageId, name: 'TextModel', superclassRef: objectRef(imageId, 'smalltalk/class/Object'), instanceShapeRef,
  });
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef, methods: ACTIVE_MODEL_METHODS});
  return Object.freeze({classRef, metaclassRef});
}

export {ACTIVE_MODEL_SHAPE_ID, ACTIVE_MODEL_METHODS, installSmalltalkActiveModelProtocol};

import {objectRef, textValue} from '../value/index.js';
import {assertMethodLane, defineMethods, ensureBlock, ensureCodeArtifact, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0046 decision 12: the allocation and class-introspection protocol, installed explicitly after
// kernel identity exists — never by `installSmalltalkKernel`, which stays identity-only.
//
// Two layers land here. The primitive Blocks are lane-independent host implementations; the methods
// that reach them are ordinary semantic `lagrange-code/v0` programs derived per lane, so `basicNew`,
// `new`, `class` and `initialize` are found by the same Behavior walk as `+` and `ifTrue:`. Neither
// the compiler nor the dispatcher learns any of these selectors.
//
// Note what installation does *not* do: registering the executor for
// `smalltalk-kernel-primitive/v1` is runtime composition (decision 2a), so an image may hold this
// protocol in a process that never registered it. That fails as an unregistered representation,
// which is the ordinary outcome rather than a special case.
const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.CLASS_OF]: 'smalltalk/primitive/class-of',
  [SMALLTALK_PRIMITIVE.BASIC_NEW]: 'smalltalk/primitive/basic-new',
});

// The capture names are what the method bodies read as, so they are part of the installed program
// and are kept beside the ids they bind.
const CLASS_OF_CAPTURE = Object.freeze({
  id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.CLASS_OF],
  name: 'primitiveClassOf',
});
const BASIC_NEW_CAPTURE = Object.freeze({
  id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.BASIC_NEW],
  name: 'primitiveBasicNew',
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// `aPrimitive value: self` — an ordinary Block send, which ADR 0044 decision 11 answers without a
// class, so the host effect rides the existing send/resumption machinery in both lanes.
const sendPrimitive = (capture) => ({
  op: 'send',
  languageId: SYMMETRIC_SMALLTALK_ID,
  receiver: {op: 'binding', id: capture.id},
  message: textValue('value:'),
  arguments: [{op: 'receiver'}],
});

// The installed protocol, as it reads in Smalltalk:
//
//   Object >> class        primitiveClassOf value: self
//   Object >> initialize   ^self
//   Class  >> basicNew     primitiveBasicNew value: self
//   Class  >> new          ^self basicNew initialize
//
// `new` is deliberately not a second allocation primitive: it is composition, and in the WASM lane
// the `basicNew` result feeding `initialize` is a non-tail send that the resumable ABI carries.
function protocolFor(kernel) {
  return [
    {
      classRef: kernel.objectClass,
      methods: [
        {
          selector: 'class',
          program: {parameters: [], captures: [{...CLASS_OF_CAPTURE}], body: sendPrimitive(CLASS_OF_CAPTURE)},
          captures: [{...CLASS_OF_CAPTURE, value: objectRef(kernel.ref.imageId, CLASS_OF_CAPTURE.id)}],
        },
        {
          selector: 'initialize',
          program: {parameters: [], captures: [], body: {op: 'receiver'}},
        },
      ],
    },
    {
      classRef: kernel.classClass,
      methods: [
        {
          selector: 'basicNew',
          program: {parameters: [], captures: [{...BASIC_NEW_CAPTURE}], body: sendPrimitive(BASIC_NEW_CAPTURE)},
          captures: [{...BASIC_NEW_CAPTURE, value: objectRef(kernel.ref.imageId, BASIC_NEW_CAPTURE.id)}],
        },
        {
          selector: 'new',
          program: {
            parameters: [],
            captures: [],
            body: {
              op: 'send',
              languageId: SYMMETRIC_SMALLTALK_ID,
              receiver: {
                op: 'send',
                languageId: SYMMETRIC_SMALLTALK_ID,
                receiver: {op: 'receiver'},
                message: textValue('basicNew'),
                arguments: [],
              },
              message: textValue('initialize'),
              arguments: [],
            },
          },
        },
      ],
    },
  ];
}

// Both writes are ensure-exact-or-create, like every other deterministic-id record in this
// substrate: an identical artifact left by a partial run is reused, and a differing one is refused
// rather than overwritten.
async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkAllocationProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  // Validated here rather than only inside `defineMethods`, which runs after both primitive Blocks
  // and their code artifacts are already committed. Validate everything before publishing anything.
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Primitives first: the methods capture their refs, and a method's environment may not point at a
  // Block that does not yet exist.
  const primitives = {};
  for (const primitive of [SMALLTALK_PRIMITIVE.CLASS_OF, SMALLTALK_PRIMITIVE.BASIC_NEW]) {
    primitives[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }

  for (const {classRef, methods} of protocolFor(kernel)) {
    await defineMethods({images, compilation, imageId, classRef, methods, lane});
  }

  // Workstream 3 (MessagePack pressure). Ordinary-source root-class protocol, installed here because
  // this installer already owns the base `Object` protocol (`class`/`initialize` above). These are
  // pure Smalltalk — no primitive, no compiler knowledge — reached for by real upstream source:
  // `MpEncoder class>>on:` ends in `yourself`, and `MpEncoder>>writeStream` guards with `isNil`.
  //
  // `isNil` needs both halves: `nil` is the kernel `UndefinedObject` singleton, so `nil isNil` must
  // find `^true` on `UndefinedObject` while every other receiver inherits `^false` from `Object`.
  // Installing only the `Object` half would leave `nil isNil` answering `false` by inheritance.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      {selector: 'yourself', source: '[ ^self ]'},
      {selector: 'isNil', source: '[ ^false ]'},
    ],
  });
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: objectRef(imageId, 'smalltalk/class/UndefinedObject'),
    methods: [
      {selector: 'isNil', source: '[ ^true ]'},
    ],
  });

  return Object.freeze({
    classOfPrimitive: primitives[SMALLTALK_PRIMITIVE.CLASS_OF],
    basicNewPrimitive: primitives[SMALLTALK_PRIMITIVE.BASIC_NEW],
    objectClass: kernel.objectClass,
    classClass: kernel.classClass,
  });
}

// Pinned Object/CharacterSequence type query. Native Text and Symbol are separate classes, so
// both receive the true override. Ordinary lookup owns inheritance and application overrides.
// Keep this after Symbol installation rather than adding a dependency to base allocation.
async function installSmalltalkStringTestingProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') throw new TypeError('images service is required');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const symbolClass = objectRef(imageId, 'smalltalk/class/Symbol');
  if (!await methodBlockRef({images, imageId, classRef: symbolClass, selector: 'asString'})) {
    throw new TypeError(`image ${imageId} has no Symbol asString method`);
  }
  for (const [classRef, source] of [
    [kernel.objectClass, '[ ^ false ]'],
    [kernel.textClass, '[ ^ true ]'],
    [symbolClass, '[ ^ true ]'],
  ]) {
    await defineMethodsFromSource({images, compilation, imageId, lane, classRef, methods: [{selector: 'isString', source}]});
  }
}

export {
  BASIC_NEW_CAPTURE as SMALLTALK_BASIC_NEW_CAPTURE,
  CLASS_OF_CAPTURE as SMALLTALK_CLASS_OF_CAPTURE,
  PRIMITIVE_BLOCK_ID as SMALLTALK_PRIMITIVE_BLOCK_ID,
  installSmalltalkAllocationProtocol,
  installSmalltalkStringTestingProtocol,
};

// Native `Array2D`, required by the frozen M5.2 measurement (bead lagrange-images-nfv1.1/
// nfv1.3): `LifeArray extends Array2D`, and the imported, unchanged Life code builds grids with
// `LifeArray height: width:`, fills them with `fillWithArrayOfArrays:`, iterates with
// `i:j:` / `i:j:put:` / `at:` / `at:put:`, and copies with `copy` (`LifeModel>>nextState`).
// The Cuis import adapter's correspondence seam maps `cuis-class/Cuis-Base/Array2D` to THIS
// class; nothing else creates or guesses the correspondence.
//
// This is an ordinary native Smalltalk class published as an ordinary global — NOT a Cuis
// compatibility class. The Cuis import adapter knows nothing about the name beyond the sealed
// correspondence entry.
//
// RECORDED REAL-CUIS ORACLE (pinned Cuis7.8.sources, read out of the pinned image — the whole
// protocol below is upstream's own wording, minimized to the protocol the measured acceptance
// path sends):
//
//   ivar order            width, height, elements
//   height:width: (class) ^self basicNew initHeight: h width: w
//                         (this image has no `basicNew` class-protocol divergence to
//                          preserve: `new` = basicNew + initialize, and Array2D carries no
//                          other initializer state, so `new initHeight:width:` is equivalent)
//   initHeight:width:     height := h. width := w. self initializeElements
//   initializeElements    elements := Array new: height * width
//   elementsIndexForI:j:  (j between: 1 and: width) ifFalse: [self errorSubscriptBounds...].
//                         ^ i-1*width+j     (this image has no measured `errorSubscriptBounds:`
//                          protocol; the measured BOUNDS behavior is preserved by signalling
//                          the existing Error condition — an out-of-bounds column is refused,
//                          never a silent wrap)
//   i:j: / i:j:put:       elements at: (self elementsIndexForI: i j: j) [put: anObject]
//   elements / elements:  the one flattened backing
//   at: / at:put:         the Point form, decomposing through `isPoint`
//   fillWithArrayOfArrays rows 1..height, columns 1..width
//   copy / postCopy       Object copy = shallowCopy postCopy; postCopy COPIES the elements
//                         array, so a copy is independent of its original. This image has no
//                         measured `shallowCopy` primitive protocol, so the measured COPY
//                         SEMANTIC (independent elements, same layout) is the method's contract.
//
// The rest of upstream's matrix protocol (`wrapI:j:`, `with:otherImageDo:`, `replaceValues:`,
// printing, `=`, `hash`) remains absent. Execution pressure adds protocol one proven consumer
// at a time.
import {ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

const ARRAY_2D_SHAPE_ID = 'smalltalk/point-agnostic-array2d-instance-shape/v1';

const ARRAY_2D_CLASS_METHODS = Object.freeze([
  {selector: 'height:width:', source: '[ :h :w | | a | a := self new. a initHeight: h width: w. ^ a ]'},
]);

// Bodies in measured upstream order. The bounds check keeps the measured REFUSAL behavior: an
// out-of-bounds column refuses, it never silently wraps to another cell.
const ARRAY_2D_METHODS = Object.freeze([
  {selector: 'initHeight:width:', source: '[ :h :w | width := w. height := h. self initializeElements ]'},
  {selector: 'initializeElements', source: '[ elements := Array new: height * width ]'},
  {selector: 'width', source: '[ ^width ]'},
  {selector: 'height', source: '[ ^height ]'},
  {selector: 'elements', source: '[ ^elements ]'},
  {selector: 'elements:', source: '[ :anArray | elements := anArray ]'},
  {selector: 'elementsIndexForI:j:', source: '[ :i :j | (j between: 1 and: width) ifTrue: [ ^ i-1*width+j ]. Error signal ]'},
  {selector: 'i:j:', source: '[ :i :j | ^ elements at: (self elementsIndexForI: i j: j) ]'},
  {selector: 'i:j:put:', source: '[ :i :j :anObject | elements at: (self elementsIndexForI: i j: j) put: anObject ]'},
  {selector: 'at:', source: '[ :aPoint | aPoint isPoint ifTrue: [ ^ self i: aPoint x j: aPoint y ]. width = 1 ifTrue: [ ^ self i: aPoint j: 1 ]. height = 1 ifTrue: [ ^ self i: 1 j: aPoint ] ]'},
  {selector: 'at:put:', source: '[ :aPoint :anObject | aPoint isPoint ifTrue: [ self i: aPoint x j: aPoint y put: anObject ] ifFalse: [ width = 1 ifTrue: [ self i: aPoint j: 1 put: anObject ] ifFalse: [ self i: 1 j: aPoint put: anObject ] ] ]'},
  {selector: 'fillWithArrayOfArrays:', source: '[ :anArray | 1 to: height do: [ :i | 1 to: width do: [ :j | self i: i j: j put: ((anArray at: i) at: j) ] ] ]'},
]);

// The measured COPY SEMANTIC (a copy has its OWN elements array, identical contents), as its
// own composition stage because the body names the published `Array2D` and `Array` globals.
const ARRAY_2D_COPY_METHOD = Object.freeze({
  selector: 'copy',
  source: `[ | c newElements |
    c := Array2D height: height width: width.
    newElements := Array new: elements size.
    1 to: elements size do: [ :idx | newElements at: idx put: (elements at: idx) ].
    c elements: newElements.
    ^ c ]`,
