import {OBJECT_WRITE_OPERATION, objectResource} from '../authority/object-resource.js';
import {OBJECT_CREATE_OPERATION} from '../callable/image-creation-binding.js';
import {
  importCuisNativePackage,
  isMappedCuisClass,
  mappedCuisClassName,
  planCuisNativeImport,
} from './cuis-native-import.js';
import {smalltalkClassObjectId} from './smalltalk-class-builder.js';
import {NAMESPACE_OBJECT_ID} from './smalltalk-globals.js';

// The AUTHORIZED Cuis native import seam (ADR 0094; Object Environment E4, bead eij.4).
//
// It brings ONE canonical Cuis package manifest (or a caller-declared scope of it) into an image
// through the existing Cuis native-import adapter, under ordinary authority, with progress,
// cancellation and a truthful partial-result contract. It owns no import semantics: the adapter
// owns translation, scope, preflight, ordering and the partial-publication rule; the class builder,
// namespace and method owners own admission. This module owns exactly five things:
//
//   1. caller-owned input validation, including the pure import plan (the adapter's own preflight
//      of the caller's manifest, run BEFORE authority because it reads nothing);
//   2. the authority demand SET, computed purely from that plan, and its ORDER before any read;
//   3. the progress and cancellation plumbing between the caller and the adapter;
//   4. the partial-result contract: what was admitted when an import stops, and why;
//   5. the public result and error taxonomy.
//
// AUTHORITY. An import mutates three kinds of state, and the demands name each through resources
// the caller can compute from its own manifest, never from anything read out of the image:
//
//   * every class the manifest declares becomes a native Class object at the class builder's
//     deterministic identity `smalltalk/class/<name>`: `object/create` on that object. Its
//     Metaclass, Shapes, MethodDictionary, class-state companion, class-variable bindings and
//     subclass registry are that Class's storage representation (the ADR 0087/0088 rule), so one
//     demand covers them;
//   * defining a class appends it to its SUPERCLASS's subclass registry, which is the superclass's
//     storage representation: `object/write` on every mapped superclass (`Object`, `Array2D`,
//     `TextModel`) a declaration names. An in-manifest superclass is covered by its own create;
//   * an extension method on a mapped existing class (`Integer`) advances that class's
//     selector-binding state: `object/write` on that Class, exactly as ADR 0088 demands for a
//     replacement;
//   * publishing the declared names into the root namespace rebinds the namespace object:
//     `object/write` on `smalltalk-global-namespace/v1` whenever the plan declares a class.
//
// The set is deduplicated and demanded in canonical order BEFORE the adapter reads the kernel, so a
// denied caller learns nothing the manifest did not already say: whether the image has a kernel, a
// namespace or any of the named classes stays undisclosed (`AuthorityError` either way).
//
// PARTIAL RESULTS are the adapter's rule, restated once here and never widened: an adapter refusal
// (`CuisNativeImportError`) happens before the first native write and admits nothing; a
// cancellation (`CuisNativeImportAbortedError`) happens between declarations and reports exactly
// what landed; a native owner's refusal of a covered declaration after earlier ones were admitted is
// `SmalltalkImportRefusedError`, which names the declaration that was being admitted, what had
// already landed, and carries the owner's own refusal as `cause` — a compiler diagnostic or an
// admission conflict is exactly what the caller needs to correct the package, and the identities
// it names are the caller's own. In every case the image is not corrupt and a corrected retry
// converges through the owners' admission rules (exact replay is write-free). Nothing here rolls
// back, retries or skips.

class SmalltalkImportInputError extends TypeError {
  constructor(message) {
    super(message);
    this.name = 'SmalltalkImportInputError';
  }
}

class SmalltalkImportRefusedError extends Error {
  constructor({identity, phase, admitted, cause}) {
    super(`Cuis native import refused at ${phase ?? 'an unknown phase'} ${identity ?? ''}`.trim()
      + `: ${cause?.message ?? cause}`, {cause});
    this.name = 'SmalltalkImportRefusedError';
    this.identity = identity;
    this.phase = phase;
    this.admitted = Object.freeze({classes: Object.freeze([...admitted.classes]), methods: Object.freeze([...admitted.methods])});
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new SmalltalkImportInputError(`${label} must be non-empty text`);
  return value;
}

function assertServices(images, compilation, require) {
  if (!images || typeof images !== 'object' || typeof images.getObject !== 'function') {
    throw new SmalltalkImportInputError('authorizedImportCuisPackage requires an image service');
  }
  if (!compilation || typeof compilation.compileArtifact !== 'function') {
    throw new SmalltalkImportInputError('authorizedImportCuisPackage requires a compilation service');
  }
  if (typeof require !== 'function') {
    throw new SmalltalkImportInputError('authorizedImportCuisPackage requires a require(demand) authority-check function');
  }
}

function assertProgressOptions(signal, onProgress) {
  if (signal !== null && (typeof signal !== 'object' || typeof signal.aborted !== 'boolean')) {
    throw new SmalltalkImportInputError('signal must be null or an AbortSignal-like object with a boolean aborted');
  }
  if (onProgress !== null && typeof onProgress !== 'function') {
    throw new SmalltalkImportInputError('onProgress must be null or a function');
  }
}

// The authority demand set of a plan: pure, deterministic, computed from the caller's manifest.
// Exported so the contract can be pinned as data.
function importDemandsFor({imageId, plan}) {
  const demands = new Map();
  const add = (operation, objectId) => {
    const resource = objectResource(imageId, objectId);
    demands.set(`${operation}\u0000${resource}`, Object.freeze({operation, resource}));
  };
  const declared = new Set(plan.classes.map(({name}) => name));
  for (const {name} of plan.classes) add(OBJECT_CREATE_OPERATION, smalltalkClassObjectId(name));
  for (const declaration of plan.ordered) {
    if (isMappedCuisClass(declaration.superclass)) {
      add(OBJECT_WRITE_OPERATION, smalltalkClassObjectId(mappedCuisClassName(declaration.superclass)));
    }
  }
  for (const method of plan.methods) {
    if (isMappedCuisClass(method.classIdentity)) {
      add(OBJECT_WRITE_OPERATION, smalltalkClassObjectId(mappedCuisClassName(method.classIdentity)));
    }
  }
  if (declared.size > 0) add(OBJECT_WRITE_OPERATION, NAMESPACE_OBJECT_ID);
  return Object.freeze([...demands.values()].sort((left, right) =>
    (left.operation < right.operation ? -1 : left.operation > right.operation ? 1 : left.resource < right.resource ? -1 : left.resource > right.resource ? 1 : 0)));
}

async function authorizedImportCuisPackage({
  images,
  compilation,
  imageId,
  manifest,
  scope = null,
  retainSource = false,
  retainProvenance = false,
  require,
  signal = null,
  onProgress = null,
} = {}) {
  // 1. Caller-owned input, then the pure plan (the adapter's own preflight; no graph read).
  assertServices(images, compilation, require);
  requiredText(imageId, 'imageId');
  if (typeof retainSource !== 'boolean') throw new SmalltalkImportInputError('retainSource must be a boolean');
  if (typeof retainProvenance !== 'boolean') throw new SmalltalkImportInputError('retainProvenance must be a boolean');
  assertProgressOptions(signal, onProgress);
  if (!manifest || typeof manifest !== 'object') throw new SmalltalkImportInputError('manifest must be a canonical Cuis semantic export manifest');
  const plan = planCuisNativeImport(manifest, scope);

  // 2. Authority: every demand, in canonical order, before anything is read.
  for (const demand of importDemandsFor({imageId, plan})) require(demand);

  // 3. Progress plumbing: remember what is being admitted so a refusal can name it.
  const admitted = {classes: [], methods: []};
  let current = null;
  const tracker = (event) => {
    if (event.event === 'begin') current = event;
    if (event.event === 'admitted') {
      if (event.phase === 'class') admitted.classes.push(event.identity);
      if (event.phase === 'methods') admitted.methods.push(...event.methods);
      current = null;
    }
    if (onProgress) onProgress(event);
  };

  // 4. The import itself, at its owner; 5. the public outcome.
  let imported;
  try {
    imported = await importCuisNativePackage({
      images,
      compilation,
      imageId,
      manifest,
      scope,
      retainSource,
      retainProvenance,
      signal,
      onProgress: tracker,
    });
  } catch (error) {
    if (error?.name === 'CuisNativeImportError' || error?.name === 'CuisNativeImportAbortedError') throw error;
    throw new SmalltalkImportRefusedError({
      identity: current?.identity ?? null, phase: current?.phase ?? null, admitted, cause: error,
    });
  }
  return Object.freeze({
    imported,
    admitted: Object.freeze({classes: Object.freeze([...admitted.classes]), methods: Object.freeze([...admitted.methods])}),
  });
}

export {
  SmalltalkImportInputError,
  SmalltalkImportRefusedError,
  authorizedImportCuisPackage,
  importDemandsFor,
};

import {OBJECT_WRITE_OPERATION, objectResource} from '../authority/object-resource.js';
import {isObjectRef, objectRef} from '../value/index.js';
import {
  SmalltalkMethodDictionaryContentionError,
  SmalltalkSealedMethodDictionaryError,
  SmalltalkStaleMethodPositionError,
  methodBlockRef,
} from './smalltalk-class-builder.js';
import {reconcileMethodsFromSource} from './smalltalk-instance-variables.js';
import {parseSmalltalkMethodPositionToken} from './smalltalk-method-position-token.js';
import {sameRef} from './smalltalk-lookup.js';

// The AUTHORIZED native Symmetric Smalltalk method REPLACEMENT seam (bead lagrange-images-qax slice
// C2, Object Environment E3, GitHub #218).
//
// It replaces ONE EXISTING method at the logical position ADR 0086 already defines — `{Class or
// Metaclass, selector}` — from explicitly supplied new source, only if the binding the caller
// OBSERVED is still the current one. It adds no method, removes none, edits no class, persists no
// source, carries no protocol/category and no Cuis provenance, and publishes no compiler and no
// generic reconciliation API.
//
// THIS MODULE OWNS EXACTLY SIX THINGS, and deliberately nothing else:
//
//   1. caller-owned input validation;
//   2. the token's syntax and scope for THIS {image, class, selector};
//   3. the authority demand and its ORDER relative to every graph read;
//   4. the current-position resolution that bridges a token to an expected binding;
//   5. the pre-compilation admission of that expectation;
//   6. the public result and error contract.
//
// EVERYTHING ELSE IS SOMEONE ELSE'S. What "still current" means once a write is in flight, how a
// lost whole-dictionary CAS is rebased, how an unrelated selector's winner is preserved, how bounded
// contention is reported, how immutable revision material is published and how source is lowered to
// a native program all live at the class builder and the from-source compiler owner (slice C1). This
// module resolves the current binding through the ONE current-binding reader (`methodBlockRef`) and
// then hands the caller's ORIGINAL observation to `reconcileMethodsFromSource` as `expectedCurrent`.
// It decodes no MethodDictionary bucket, no Shape, no backend `_version`, and it never writes.
//
// WHY THERE IS AN ADMISSION CHECK HERE AT ALL, given that C1 re-asserts the same expectation. C1's
// earliest check is at plan time — which is AFTER `reconcileMethodsFromSource` has compiled the
// source. A public seam that only relied on it would answer a compiler diagnostic to a caller whose
// real problem is that its observation was overtaken, and would compile source it can already know
// is inadmissible. So this check moves the stale verdict in FRONT of compilation. It is not a second
// authority on staleness: the very same observation is then passed to C1, which re-asserts it at plan
// time and at EVERY rebase boundary, and C1's verdict is final. Removing this check would change
// which error a stale caller sees and how much work a doomed call does; it could never let a stale
// replacement land.
//
// THE EXPECTATION IS NEVER REFRESHED. The binding read in step 4 is used to ADMIT the caller's token,
// never to replace it: what reaches C1 is the token's observed revision, so a position that moved
// between the caller's read and this call is stale even though this seam has just seen the winner.
// A hidden fresh read substituted for the caller's assumption would make a stale conflict
// unobservable, which is precisely what #218 asks this operation to prove it cannot do.
//
// AUTHORITY. Replacement mutates the DECLARING Class/Metaclass's selector-binding state, so it
// demands ONE `object/write` on the Class (or Metaclass) object, before any existence is disclosed.
//
//   * NOT a write on the currently bound Block. That Block is immutable revision material (ADR 0086
//     decision 1); a replacement does not modify it, it stops pointing at it. Demanding write there
//     would authorize a mutation nobody performs and would refuse a caller who legitimately owns the
//     class but not the method's previous revision.
//   * NOT inferred from anything. Not from a class `object/read`, not from a Block `object/read`,
//     not from possession of refs, not from Project membership (ADR 0039 §2), and NOT from the
//     token: a version token is an assumption about state, and holding one confers zero authority.
//   * Authorization strictly precedes existence disclosure, exactly as ADR 0087's reads do, so a
//     denied caller cannot tell an implemented selector from an unimplemented one from a missing
//     class. All three are `AuthorityError`.
//
// NO EXECUTION LANE IS PUBLISHED, AND NONE IS CHOSEN HERE. A `lane` parameter would publish a
// compiler/execution knob on a seam whose whole point is that E3 exposes no compiler, and
// discovering the current method's lane HERE would mean reading the bound Block's code artifact —
// making this a second CodeArtifact decoder, exactly the path ADR 0087 rejected for the read seam.
//
// So this module does not know, and must not learn, how the method it replaces executes. What
// happens to the execution lane is the native method evolution owner's decision (bead
// lagrange-images-it3): a replacement guarded by an observed revision is compiled in THAT
// REVISION'S lane, which that owner reads back from the `metadata.lane` it published itself when it
// installed the Block — its own record, not a decoded executable representation. Replacing what a
// position MEANS is therefore never also a migration of how it RUNS, and there is no fallback: a
// replacement the observed lane cannot compile fails, and the observed revision stays current.
//
// Nothing about that reaches this contract. The token already names the observed immutable binding,
// which is all the owner needs; the Environment never has to know what a lane is, and a future
// explicit lane migration would be a separate operation with its own policy.
//
// SOURCE IS NOT PERSISTED. `source` is the explicitly supplied NEW source and this seam is not a
// source editor: it compiles through the existing owner and retains no text, so ADR 0087's
// `source: null` stays truthful after a successful replacement. #218 scopes E3 this way on purpose.
//
// THE RESULT IS DELIBERATELY MINIMAL. `{replaced: true}`, frozen, and nothing else — no new Block
// ref, no descriptor, no replacement token, no source. The consumer has already committed to a fresh
// authorized reread as displayed truth (#218 point 4); handing back anything richer would tempt it
// to skip that reread and patch its local state from a receipt instead.
//
// It says "the position now denotes the source you supplied", NOT "a record was written". Supplying
// source that means exactly what is already bound is ADR 0086 exact replay against the very state
// the caller observed: a write-free success, the same receipt, and the binding does not move. That
// is the honest reading — the receipt is about the caller's request, and the number of records the
// image gained is the revision owner's business, not a public fact.
//
// ERROR TAXONOMY. Every outcome is an Images-native semantic one, distinguished by `error.name` —
// which is the only discriminator that works for a consumer reaching this seam through
// `src/portable-runtime.js`, where these classes are deliberately not published:
//
//   SmalltalkMethodReplacementInputError    malformed caller-owned input
//   SmalltalkMethodPositionTokenError       malformed token, or one issued for another position
//   AuthorityError                          the caller's own `require` denied `object/write`
//   SmalltalkMethodTargetError              after authorization: no such native method position
//   SmalltalkStaleMethodPositionError       the observed binding is no longer current (C1's class)
//   SmalltalkMethodReplacementContentionError  transient: the position did not move and was not advanced
//   SmalltalkMethodLaneError                the observed revision records no usable execution lane,
//                                           so its lane cannot be preserved (the lane owner's class)
//   anything else                           the native compiler/source owner rejected the source
//
// `SmalltalkMethodLaneError` passes through unrestated, unlike the two dictionary-scoped outcomes
// above it: it already names only the `{class, selector}` the caller supplied, carries no storage
// identity and no `cause`, and a caller cannot provoke it with a well-formed observation of a
// method this substrate installed. Restating it would only hide which of two very different things
// went wrong.
//
// Malformed caller input has its OWN class rather than a bare `TypeError` for one concrete reason:
// the native semantic compiler also rejects bad source with `TypeError`, so a bare `TypeError` here
// would make "your call is malformed" and "your source is malformed" indistinguishable — and those
// demand opposite responses from a consumer.
//
// WHAT NEVER ESCAPES: a backend `VersionConflictError` raw or as a `cause`; a MethodDictionary ref,
// representation, bucket, tally, seal or version; a backend version; the winning Block ref in a
// stale refusal; a replacement token. Current truth comes only from a fresh authorized read.

const REPLACED = Object.freeze({replaced: true});

// Caller-owned input only. Every check below is pure — it reads no record — so a refusal here can
// never be an existence oracle, and it happens before the token is even looked at.
class SmalltalkMethodReplacementInputError extends TypeError {
  constructor(message) {
    super(message);
    this.name = 'SmalltalkMethodReplacementInputError';
  }
}

// After authorization: there is no such native method position to replace — the named Behavior is
// absent or is not a well-formed Class/Metaclass, or its method storage cannot be read as one.
//
// It names ONLY the position the caller already supplied. There is deliberately no `cause` and no
// underlying message: the resolution failures underneath name the class's MethodDictionary record,
// and this seam does not disclose storage identity. A caller that needs to diagnose a corrupt class
// browses it through the ADR 0087 read seam, which is where that diagnosis belongs.
class SmalltalkMethodTargetError extends TypeError {
  constructor(classRef, selector) {
    super(
      `${classRef.imageId}/${classRef.objectId} is not a native class whose ${selector} method `
      + 'position can be resolved',
    );
    this.name = 'SmalltalkMethodTargetError';
    this.selector = selector;
  }
}

// Transient, and NOT staleness: the observed position is exactly what the caller observed and was
// not advanced. Two owner outcomes reach it, and they are merged because the caller's response to
// both is the same and neither is a statement about the request: the whole-dictionary CAS moved
// under the write more often than the owner could rebase onto it, or the class's method storage is
// SEALED for migration and refuses writes until the Behavior points at its hashed dictionary.
//
// It is a public restatement of the owner's outcome rather than the owner's own error, because that
// one names the class's MethodDictionary record — storage identity this seam does not publish. Like
// every refusal here it carries no `cause`, so no backend conflict can travel out inside one.
//
// It deliberately does NOT claim that nothing was written: ADR 0086 publishes immutable revision
// material before the final CAS, so by now the replacement's Block may exist, addressable and not
// current. The invariant that holds is the narrow one — the current binding did not move.
class SmalltalkMethodReplacementContentionError extends TypeError {
  constructor(classRef, selector) {
    super(
      `${classRef.imageId}/${classRef.objectId} ${selector} could not be advanced right now; the `
      + 'observed method position is unchanged, retry from a fresh authorized read',
    );
    this.name = 'SmalltalkMethodReplacementContentionError';
    this.selector = selector;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new SmalltalkMethodReplacementInputError(`${label} must be a non-empty string`);
  }
  return value;
}

// The same rule the browse seam applies to a class ref, for the same reason: `classRef.imageId` is
// part of the position's identity, so a ref into another image must be refused rather than compared
// by object id alone.
function assertLocalClassRef(classRef, imageId) {
  if (!isObjectRef(classRef) || classRef.imageId !== imageId) {
    throw new SmalltalkMethodReplacementInputError(
      `authorizedReplaceSmalltalkMethod classRef must be an unpinned object ref in ${imageId}`,
    );
  }
  return classRef;
}

function assertServices(images, compilation) {
  if (!images || typeof images.getObject !== 'function') {
    throw new SmalltalkMethodReplacementInputError('authorizedReplaceSmalltalkMethod requires an image service');
  }
  if (!compilation || typeof compilation.compileArtifact !== 'function') {
    throw new SmalltalkMethodReplacementInputError('authorizedReplaceSmalltalkMethod requires a compilation service');
  }
}

function assertRequire(require) {
  if (typeof require !== 'function') {
    throw new SmalltalkMethodReplacementInputError(
      'authorizedReplaceSmalltalkMethod requires a require(demand) authority-check function',
    );
  }
  return require;
}

// The current binding at this position, through the ONE representation-neutral current-binding
// reader the browse seam and the write planner already share (bead lagrange-images-jtz.2). This
// module never opens a method dictionary itself, so "which Block does this selector bind" has one
// answer for the reader, this admission check and the write planner alike.
async function currentBinding({images, imageId, classRef, selector}) {
  try {
    return await methodBlockRef({images, imageId, classRef, selector});
  } catch (error) {
    // Only the reader's own semantic refusals become a target verdict. Anything else — a host or
    // transport failure from the image service, say — is not a statement about this position and is
    // not this seam's to reinterpret, so it propagates as it was raised.
    if (!(error instanceof TypeError)) throw error;
    throw new SmalltalkMethodTargetError(classRef, selector);
  }
}

// Only PUBLIC SEMANTIC outcomes cross this boundary. The owner's own dictionary-scoped errors name
// the class's MethodDictionary record, so they are restated in terms of the caller's position; every
// other outcome — the stale verdict, a compile/source rejection, a code-artifact conflict — is
// already an Images-native semantic error from its own owner and is passed through unchanged, with
// its identity intact.
function publicOutcome(error, classRef, selector) {
  if (error instanceof SmalltalkMethodDictionaryContentionError
    || error instanceof SmalltalkSealedMethodDictionaryError) {
    return new SmalltalkMethodReplacementContentionError(classRef, selector);
  }
  return error;
}

// AUTHORIZED replacement of ONE existing native method.
//
// Order, and the order is the contract:
//
//   1. validate caller-owned shape                     (pure; discloses nothing)
//   2. validate the token's syntax and scope           (pure; discloses nothing)
//   3. require `object/write` on the Class/Metaclass   (before ANY read)
//   4. resolve the current binding                     (the one current-binding reader)
//   5. admit the token's observed binding against it
//   6. stale -> refuse, BEFORE any compilation
//   7. reconcile from source WITH the caller's ORIGINAL observation
//   8. map only public semantic outcomes
//
// Steps 1 and 2 come before step 3 so that a malformed call is diagnosed as a malformed call rather
// than as an authority failure, and step 3 comes before step 4 so that existence is never disclosed
// to a caller who may not write the class.
async function authorizedReplaceSmalltalkMethod({
  images, compilation, imageId, classRef, selector, source, expectedVersionToken, require,
} = {}) {
  assertServices(images, compilation);
  requiredText(imageId, 'imageId');
  assertLocalClassRef(classRef, imageId);
  requiredText(selector, 'selector');
  requiredText(source, 'source');
  assertRequire(require);

  // Scope-checked against the position the CALLER named, never against anything read from the
  // image: a token minted for another image, class or selector is refused here, before authority is
  // even demanded, and the refusal discloses nothing about that other position.
  //
  // The parser answers the observed binding as `{imageId, objectId}` — a token is deliberately not
  // a ref and does not carry one — so the ref the binding owner compares against is BUILT HERE,
  // through the value owner's own constructor. This is the whole of the token -> expected-binding
  // bridge, and it is the only place in the operation where a ref is constructed rather than read.
  const parsed = parseSmalltalkMethodPositionToken(expectedVersionToken, {imageId, classRef, selector});
  const observed = objectRef(parsed.imageId, parsed.objectId);

  require({
    operation: OBJECT_WRITE_OPERATION,
    resource: objectResource(imageId, classRef.objectId),
  });

  const current = await currentBinding({images, imageId, classRef, selector});
  // An ABSENT selector is stale, not a fresh definition — the same rule C1 applies, for the same
  // reason: the caller said it was replacing something it had observed, and E3 adds no method.
  if (!sameRef(current, observed)) throw new SmalltalkStaleMethodPositionError(classRef, selector);

  try {
    await reconcileMethodsFromSource({
      images,
      compilation,
      imageId,
      classRef,
      // `observed` and not `current`: the caller's assumption is what C1 must keep re-asserting.
      methods: [{selector, source, expectedCurrent: observed}],
    });
  } catch (error) {
    throw publicOutcome(error, classRef, selector);
  }
  return REPLACED;
}

export {
  SmalltalkMethodReplacementContentionError,
  SmalltalkMethodReplacementInputError,
  SmalltalkMethodTargetError,
  authorizedReplaceSmalltalkMethod,
};

import {objectRef, textValue} from '../value/index.js';
import {ensureBlock, ensureCodeArtifact} from './smalltalk-class-builder.js';
import {ensureObject, ensureShape, findSmalltalkKernel, isLocalRef} from './smalltalk-kernel.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  parsePrimitiveCode,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0051: the discoverable Block protocol, which is how `whileTrue:`/`whileFalse:` reach their
// loop primitives without the dispatcher ever knowing an object id (ADR 0044 decision 9).
//
// Discovery deliberately mirrors `findSmalltalkKernel` rather than inventing a second bootstrap
// style: one well-known id, a fixed local Shape, a protocol tag, and absent kept distinct from
// corrupt. An image with no protocol object is coherent — its Blocks simply do not loop — while a
// damaged one is an explicit failure, because degrading it to "absent" would turn a broken image
// into a quietly less capable one.
const SMALLTALK_BLOCK_PROTOCOL_V1 = 'smalltalk-block-protocol/v1';
const BLOCK_PROTOCOL_OBJECT_ID = 'smalltalk-block-protocol/v1';
const BLOCK_PROTOCOL_SHAPE_ID = 'smalltalk/block-protocol-shape/v1';

// Each slot names the primitive its target must actually be, so validation is an equality against a
// known name rather than "some primitive is there".
const BLOCK_PROTOCOL_SLOTS = Object.freeze([
  Object.freeze({
    id: 'block-protocol-while-true',
    name: 'whileTrue',
    primitive: SMALLTALK_PRIMITIVE.BLOCK_WHILE_TRUE,
    blockId: 'smalltalk/primitive/block-while-true',
  }),
  Object.freeze({
    id: 'block-protocol-while-false',
    name: 'whileFalse',
    primitive: SMALLTALK_PRIMITIVE.BLOCK_WHILE_FALSE,
    blockId: 'smalltalk/primitive/block-while-false',
  }),
]);

class SmalltalkBlockProtocolError extends TypeError {
  constructor(imageId, detail) {
    super(`Symmetric Smalltalk Block protocol in ${imageId} is corrupt: ${detail}`);
    this.name = 'SmalltalkBlockProtocolError';
    this.imageId = imageId;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Ensure-exact-or-create at both deterministic ids, like every other derived record here: an
// identical artifact left by a partial run is reused and a differing one refused, so a retry after a
// lost acknowledgement converges instead of conflicting.
async function installLoopPrimitive({images, imageId, slot}) {
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${slot.blockId}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(slot.primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive: slot.primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id: slot.blockId,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive: slot.primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkBlockProtocol({images, imageId} = {}) {
  requiredText(imageId, 'image id');
  // ADR 0051 decision 12: the loop answers this image's nil, so it cannot work without a kernel
  // here. Refusing up front beats installing a protocol that is guaranteed to fail at the first
  // send, and it is checked before anything is written.
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel; install the kernel first`);

  // Primitives before the protocol object, so the object never points at a Block that does not yet
  // exist — a partially-written protocol must never be discoverable.
  const slots = {};
  const refs = {};
  for (const slot of BLOCK_PROTOCOL_SLOTS) {
    const ref = await installLoopPrimitive({images, imageId, slot});
    slots[slot.id] = ref;
    refs[slot.name] = ref;
  }

  const shapeRecord = await ensureShape(images, imageId, {
    id: BLOCK_PROTOCOL_SHAPE_ID,
    slots: BLOCK_PROTOCOL_SLOTS.map(({id, name}) => ({id, name})),
  });
  await ensureObject(images, imageId, {
    id: BLOCK_PROTOCOL_OBJECT_ID,
    shape: objectRef(imageId, shapeRecord.id),
    behavior: null,
    slots,
    metadata: {protocol: SMALLTALK_BLOCK_PROTOCOL_V1},
  });

  return Object.freeze({
    protocol: SMALLTALK_BLOCK_PROTOCOL_V1,
    ref: objectRef(imageId, BLOCK_PROTOCOL_OBJECT_ID),
    ...refs,
  });
}

// Validating the object is not validating the loop. A structurally perfect protocol whose slots have
// been repointed passes every check above — the slots are still local, still unpinned, still refs —
// so each ref is followed and the target proven to be the primitive that slot claims.
//
// The cost is justified by what this object is: a routing authority the dispatcher hands control of
// a `whileTrue:` send, and one whose target inherits the caller's frame (ADR 0051 decision 9).
// Accepting a local ref as sufficient would let any Block in the image run with borrowed identity.
async function validateLoopTarget({images, imageId, slot, ref}) {
  const block = await images.getBlock(ref.imageId, ref.objectId);
  if (!block) {
    throw new SmalltalkBlockProtocolError(imageId, `slot ${slot.name} does not reference a Block`);
  }
  const code = block.code && await images.getCodeArtifact(block.code.imageId, block.code.objectId);
  if (!code) {
    throw new SmalltalkBlockProtocolError(imageId, `slot ${slot.name} references a Block with no code artifact`);
  }
  if (code.representation !== SMALLTALK_KERNEL_PRIMITIVE_V1) {
    throw new SmalltalkBlockProtocolError(
      imageId,
      `slot ${slot.name} references a ${code.representation} Block, not a ${SMALLTALK_KERNEL_PRIMITIVE_V1} primitive`,
    );
  }
  let primitive;
  try {
    primitive = parsePrimitiveCode(code);
  } catch (error) {
    throw new SmalltalkBlockProtocolError(imageId, `slot ${slot.name} references an unreadable primitive`, {cause: error});
  }
  // Equality against the expected name, so while-true and while-false cannot be swapped for each
  // other any more than either can be swapped for an unrelated primitive.
  if (primitive !== slot.primitive) {
    throw new SmalltalkBlockProtocolError(
      imageId,
      `slot ${slot.name} references the ${primitive} primitive, not ${slot.primitive}`,
    );
  }
  return ref;
}

async function findSmalltalkBlockProtocol({images, imageId} = {}) {
  requiredText(imageId, 'block protocol image id');
  const cached = images?.cachedProtocol?.(SMALLTALK_BLOCK_PROTOCOL_V1, imageId);
  if (cached) return cached;
  const record = await images.getObject(imageId, BLOCK_PROTOCOL_OBJECT_ID);
  // Absent: this image's Blocks do not loop. Every other outcome below is corrupt.
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_BLOCK_PROTOCOL_V1) {
    throw new SmalltalkBlockProtocolError(imageId, `object does not declare ${SMALLTALK_BLOCK_PROTOCOL_V1}`);
  }
  if (!isLocalRef(record.shape, imageId, BLOCK_PROTOCOL_SHAPE_ID)) {
    throw new SmalltalkBlockProtocolError(imageId, `object does not have shape ${BLOCK_PROTOCOL_SHAPE_ID}`);
  }
  const refs = {};
  for (const slot of BLOCK_PROTOCOL_SLOTS) {
    const value = record.slots?.[slot.id];
    if (!isLocalRef(value, imageId)) {
      throw new SmalltalkBlockProtocolError(imageId, `slot ${slot.name} must be an unpinned local ref`);
    }
    refs[slot.name] = await validateLoopTarget({images, imageId, slot, ref: value});
  }
  const protocol = Object.freeze({protocol: SMALLTALK_BLOCK_PROTOCOL_V1, ref: objectRef(imageId, record.id), record, ...refs});
  return images?.cacheProtocol ? images.cacheProtocol(SMALLTALK_BLOCK_PROTOCOL_V1, imageId, protocol) : protocol;
}

export {
  BLOCK_PROTOCOL_OBJECT_ID,
  BLOCK_PROTOCOL_SHAPE_ID,
  BLOCK_PROTOCOL_SLOTS,
  SMALLTALK_BLOCK_PROTOCOL_V1,
  SmalltalkBlockProtocolError,
  findSmalltalkBlockProtocol,
  installSmalltalkBlockProtocol,
};

import {OBJECT_READ_OPERATION, objectResource} from '../authority/object-resource.js';
import {shapeIndexedKind} from '../object/model.js';
import {isObjectRef} from '../value/index.js';
import {findSmalltalkKernel, readBehavior} from './smalltalk-kernel.js';
import {
  classProvenance,
  methodBindings,
  methodBlockRef,
  methodProvenance,
  methodSource,
} from './smalltalk-class-builder.js';
import {sameRef} from './smalltalk-lookup.js';
import {
  SMALLTALK_METHOD_READ_OPERATION,
  smalltalkMethodPositionResource,
} from './smalltalk-method-position-resource.js';
import {smalltalkMethodPositionToken} from './smalltalk-method-position-token.js';

// The AUTHORIZED native Symmetric Smalltalk browsing seam (ADR 0087, bead lagrange-images-jtz,
// Object Environment E1).
//
// This is an IMAGES semantic API. It is not an Environment-shaped DTO and not a Cuis API: what it
// answers are ordinary native Smalltalk facts about ordinary native Classes, Metaclasses and
// methods, useful to any headless client, and identical whether the class was declared natively or
// arrived through the Cuis native-import adapter.
//
// COMPOSITION, NOT DECODING. Every fact here comes from the owner that already decides it:
//
//   Class/Metaclass identity, superclass, method-dictionary edge   readBehavior          (kernel)
//   the image's nil terminator and Metaclass identity              findSmalltalkKernel   (kernel)
//   selector -> Block bindings, representation-neutral             methodBindings        (class builder)
//   declared instance layout                                       the instance Shape    (object model)
//   object authority operation + resource naming                   object-resource.js    (authority)
//   logical method-position authority vocabulary                   method-position resource (language)
//
// Nothing in this module decodes a Behavior slot id, a MethodDictionary bucket, a Block's code
// artifact or a compiled WASM representation, and nothing here writes.
//
// WHAT DELIBERATELY DOES NOT ESCAPE. Behavior slot ids; the MethodDictionary's representation,
// buckets, tally or seal; backend `_version`; the semantic/WASM artifacts underneath a method; Spur
// oops or Cuis class objects; the import adapter's transient semantic-identity mapping. A caller
// receives names, refs and selectors — never a storage layout to decode.
//
// AUTHORITY. Two operations, two checks, no transitive authority (ADR 0039 §2):
//
//   class browsing   ONE `object/read` on the Class (or Metaclass) OBJECT.
//   method browsing  that SAME class check, AND an independent `smalltalk-method/read` on the
//                    exact logical {image, Class/Metaclass, selector} position.
//
// A class's own MethodDictionary is covered by the class's single check for the same reason a
// Project's member records are covered by the Project's (see project/working-state.js): it is the
// Class's storage representation, sitting at an id derived from the Class, carrying no behavior edge
// of its own (ADR 0049 decision 3), and it is not an independently addressable semantic object. The
// Blocks it BINDS are independently addressable semantic objects. Class authority therefore yields
// selector NAMES and never the method behind one. The method-position grant authorizes resolving
// and reading only the CURRENT method through this semantic seam; it is not `object/read` on the
// returned Block and cannot authorize direct inspection of that Block or a historical revision.
//
// Nothing is inferred from Project membership, from a class reference, or from graph reachability.
// A superclass ref, a class-side ref and a Block ref are LOCATORS: browsing what they name requires
// that object's own grant.
//
// AUTHORIZATION BEFORE EXISTENCE. Every entry point validates its caller-supplied inputs (which
// discloses nothing), then requires, then reads. A denied caller cannot tell an existing class from
// a missing one, or an existing method from a missing one: both are AuthorityError.
//
// PROVENANCE IS OPTIONAL METADATA, and today it is absent. Images owns no durable association from a
// native class or method back to a Cuis package, source or protocol/category: `importCuisNativePackage`
// returns transient associations and writes no side table, and the class builder installs a method's
// semantic program without retaining the text it was compiled from. So `provenance` and a method's
// `source` are reported as `null` rather than reconstructed from the importer or guessed from a
// deterministic id. That is the truthful answer, and it is exactly why a Cuis-imported class browses
// through this one seam like any other: there is no second lane for it to take.
//
// BROWSING ONLY. No edit, rename, recompile or removal semantics live here: a write lane needs its
// own consumer, its own owner decision and its own ADR.

const SMALLTALK_CLASS_DESCRIPTION_V1 = 'smalltalk-class-description/v1';
const SMALLTALK_METHOD_DESCRIPTION_V1 = 'smalltalk-method-description/v1';

// Instance side or class side. A Metaclass is recognized the way the kernel ties the knot —
// `behavior(aMetaclass) == Metaclass` — not by an object-id spelling.
const CLASS_SIDE = Object.freeze({INSTANCE: 'instance', CLASS: 'class'});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function assertRequire(require, label) {
  if (typeof require !== 'function') {
    throw new TypeError(`${label} requires a require(demand) authority-check function`);
  }
  return require;
}

// Caller-supplied input only: this rejects a malformed argument without touching the graph, so it
// cannot become an existence oracle.
function assertLocalClassRef(classRef, imageId, label) {
  if (!isObjectRef(classRef) || classRef.imageId !== imageId) {
    throw new TypeError(`${label} classRef must be an unpinned object ref in ${imageId}`);
  }
  return classRef;
}

const readDemand = (imageId, objectId) => ({
  operation: OBJECT_READ_OPERATION,
  resource: objectResource(imageId, objectId),
});

// The class's declared instance layout, or `null` when it declares none. `null` and `[]` are
// different answers: a Metaclass and the kernel's abstract classes carry the kernel `nil` instance
// shape (they declare no layout at all), while a class declaring zero instance variables has an
// empty one and its instances exist. Slot IDS never escape — a browser gets the ordered names and
// whether instances are indexable, which is what a class definition says.
async function describeLayout({images, instanceShape, nilRef, label}) {
  if (sameRef(instanceShape, nilRef)) return null;
  const shape = await images.getShape(instanceShape.imageId, instanceShape.objectId);
  if (!shape) {
    throw new TypeError(`${label} has a dangling instance shape edge to ${instanceShape.imageId}/${instanceShape.objectId}`);
  }
  return Object.freeze({
    instanceVariables: Object.freeze(shape.slots.map(({name}) => name)),
    indexed: shapeIndexedKind(shape),
  });
}

// Instance side or class side, decided strictly from the kernel's metaclass knot (ADR 0044 decision
// 4) and never from an object-id spelling:
//   * `behavior(aMetaclass) == Metaclass` -> side: 'class', classSide: null
//   * `behavior(aClass) == aMetaclass` where `behavior(aMetaclass) == Metaclass` -> side: 'instance', classSide: aMetaclass
// A dangling or non-Metaclass `behavior` edge is corrupt graph state and is refused rather than
// normalized silently into `side: 'instance', classSide: null`.
async function resolveBehaviorSide({images, classRef, behavior, kernel}) {
  const label = `native class ${classRef.imageId}/${classRef.objectId}`;
  if (sameRef(behavior.behavior, kernel.metaclassClass)) {
    return {side: CLASS_SIDE.CLASS, classSide: null};
  }
  let metaclass;
  try {
    metaclass = await readBehavior(images, behavior.behavior);
  } catch (error) {
    const kind = /^behavior not found:/.test(error?.message ?? '') ? 'dangling' : 'malformed';
    throw new TypeError(
      `${label} has a ${kind} behavior edge to ${behavior.behavior.imageId}/${behavior.behavior.objectId}`,
      {cause: error},
    );
  }
  if (!sameRef(metaclass.behavior, kernel.metaclassClass)) {
    throw new TypeError(
      `${label} behavior edge ${behavior.behavior.imageId}/${behavior.behavior.objectId} is not an instance of Metaclass`,
    );
  }
  return {side: CLASS_SIDE.INSTANCE, classSide: behavior.behavior};
}

// ONE already-authorized, already-read Class/Metaclass record -> the canonical native class
// description. Every field comes from that one record (the selector bindings are read from the
// dictionary edge IT names), so a description can never be assembled from two versions of a class.
// `superclass` and `classSide` are refs the caller may browse NEXT, each under its own grant.
async function describeBehavior({images, imageId, classRef, behavior, kernel}) {
  const label = `native class ${classRef.imageId}/${classRef.objectId}`;
  const {side, classSide} = await resolveBehaviorSide({images, classRef, behavior, kernel});
  return Object.freeze({
    format: SMALLTALK_CLASS_DESCRIPTION_V1,
    class: classRef,
    name: behavior.name.value,
    side,
    // The kernel's `nil` terminates the chain; a root class has no superclass, it does not have a
    // superclass named "nil".
    superclass: sameRef(behavior.superclass, kernel.nil) ? null : behavior.superclass,
    // The class side of an instance-side class is its metaclass — the class's own behavior edge, by
    // the kernel's decision 4 rule. Browsing it needs the metaclass's own `object/read`; this is a
    // locator, not a grant.
    //
    // A Metaclass gets `null`, and there is deliberately no inverse field: the kernel stores a
    // class -> metaclass edge and no metaclass -> sole-instance edge, so answering "which class is
    // this the metaclass of" would mean deriving one object id from another. A browser that wants
    // to toggle sides keeps the class ref it started from.
    classSide,
    layout: await describeLayout({images, instanceShape: behavior.instanceShape, nilRef: kernel.nil, label}),
    // The selectors THIS class implements. Inherited protocol is deliberately absent: an inherited
    // selector is the declaring class's fact, and reporting it here would let one grant speak for
    // objects the caller was never authorized to read.
    selectors: Object.freeze((await methodBindings({images, imageId, classRef, behavior, kernel})).map(({selector}) => selector)),
    // Delegated to the class builder's `classProvenance` owner: returns the normalized durable
    // provenance metadata when retained on the Class/Metaclass record, or `null` when absent.
    provenance: await classProvenance({images, imageId, classRef, behavior}),
  });
}

// AUTHORIZED native class browsing.
//
// Requires ONE `object/read` on the Class (or Metaclass) object named by `classRef`, BEFORE any
// existence disclosure. Returns the frozen canonical description: identity/name, side, superclass,
// class side, declared native layout and the class's own selectors.
async function authorizedDescribeSmalltalkClass({images, imageId, classRef, require} = {}) {
  requiredText(imageId, 'imageId');
  assertLocalClassRef(classRef, imageId, 'authorizedDescribeSmalltalkClass');
  assertRequire(require, 'authorizedDescribeSmalltalkClass');

  require(readDemand(imageId, classRef.objectId));

  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const behavior = await readBehavior(images, classRef);
  return describeBehavior({images, imageId, classRef, behavior, kernel});
}

// AUTHORIZED native method browsing.
//
// Two independent checks, in this order and BEFORE selector resolution:
//   1. `object/read` on the CLASS object — before any existence disclosure, and the same check
//      class browsing makes. It authorizes resolving the selector against the class's own method
//      dictionary, which is the class's storage representation.
//   2. `smalltalk-method/read` on the exact logical {image, Class/Metaclass, selector} position.
//      Its canonical resource is pure public vocabulary, so the caller never has to predict which
//      immutable Block revision currently occupies the position.
//
// Only after BOTH checks succeed may Images resolve whether the selector exists, which Block is
// current, or whether its edge is dangling. A denied caller therefore learns only AuthorityError.
// ONE authorized resolution of a current method position, so the read that DESCRIBES a method and
// the read that prepares to REPLACE one cannot assemble different revisions by accident. Everything
// below it is the same as it has always been; factoring it is what makes "the descriptor and the
// token describe the same resolved binding, from one binding read" a structural fact rather than a
// convention two call sites have to keep.
//
// This is ADR 0087's corrected authority sequence: validate caller input, authorize the
// Class/Metaclass read, authorize the stable logical position independently, then resolve. Class
// authority yields selector names and never the method behind one. A method-position grant follows
// that position across immutable revisions until revoked, but confers no generic Block authority.
async function authorizedMethodPosition({images, imageId, classRef, selector, require, operation}) {
  requiredText(imageId, 'imageId');
  assertLocalClassRef(classRef, imageId, operation);
  requiredText(selector, 'selector');
  assertRequire(require, operation);

  require(readDemand(imageId, classRef.objectId));
  require({
    operation: SMALLTALK_METHOD_READ_OPERATION,
    resource: smalltalkMethodPositionResource(imageId, classRef, selector),
  });

  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const behavior = await readBehavior(images, classRef);
  const {side} = await resolveBehaviorSide({images, classRef, behavior, kernel});
  // The SAME Behavior record and kernel answer the side and the selector binding: one read of the
  // Class and one read of the kernel, so a description can never be assembled from two versions.
  const method = await methodBlockRef({images, imageId, classRef, selector, behavior, kernel});
  if (!method) {
    throw new TypeError(`native class ${classRef.imageId}/${classRef.objectId} does not implement ${selector}`);
  }
  const binding = Object.freeze({selector, method});

  // The binding is only truthful if the Block it names is actually there; a dangling method edge is
  // corrupt graph state, correctly disclosed to a caller authorized for the class and position.
  const block = await images.getBlock(binding.method.imageId, binding.method.objectId);
  if (!block) {
    throw new TypeError(
      `native class ${classRef.imageId}/${classRef.objectId} binds ${selector} to a missing Block: `
      + `${binding.method.imageId}/${binding.method.objectId}`,
    );
  }

  const source = await methodSource({images, imageId, blockRef: binding.method, block});
  const provenance = await methodProvenance({images, imageId, blockRef: binding.method, block});

  return Object.freeze({
    binding,
    descriptor: Object.freeze({
      format: SMALLTALK_METHOD_DESCRIPTION_V1,
      // The Behavior that DECLARES this method, not the receiver class a send happened to start from.
      class: classRef,
      side,
      selector,
      // The exact Block ref the dictionary binds. It is the method's identity for a caller that
      // wants to pin or re-read it; the code, lexical environment and compiled lane behind it are
      // the execution owners' business and stay there.
      method: binding.method,
      // Delegated to the class builder's `methodSource` owner (ADR 0096): returns the durable
      // `<blockId>:source` (`symmetric-smalltalk/source-v0`) text when retained for this revision,
      // or `null` when absent. The browse seam never walks `CodeArtifact.derivedFrom` itself.
      source,
      provenance,
    }),
  });
}

// ADR 0087's canonical method description, gaining nothing. It answers no
// version token: a reader is not a writer, and a caller that only wants to look at a method has no
// business holding a replacement assumption.
async function authorizedDescribeSmalltalkMethod({images, imageId, classRef, selector, require} = {}) {
  return (await authorizedMethodPosition({
    images, imageId, classRef, selector, require, operation: 'authorizedDescribeSmalltalkMethod',
  })).descriptor;
}

// THE WRITER-FACING READ (bead lagrange-images-qax, Object Environment E3). The smallest possible
// addition: exactly the canonical ADR 0087 descriptor, plus an opaque token for the method position
// it just resolved.
//
// Both halves come from ONE resolution, so they cannot describe different revisions — the token is
// minted from the very binding the descriptor reports, not from a second read of the same position.
// That matters because the whole point of the token is to represent what the caller was shown.
//
// It demands exactly what ADR 0087's corrected method read demands and nothing more. Reading in
// order to write is still only reading, so this grants no write authority and asserts none; the replacement
// operation authorizes its own write when it is called. `descriptor.source` stays `null` — this
// seam is not a source editor and E3 is replacement from explicitly supplied source.
async function authorizedReadSmalltalkMethodForUpdate({images, imageId, classRef, selector, require} = {}) {
  const {descriptor, binding} = await authorizedMethodPosition({
    images, imageId, classRef, selector, require, operation: 'authorizedReadSmalltalkMethodForUpdate',
  });
  return Object.freeze({
    descriptor,
    versionToken: smalltalkMethodPositionToken({
      imageId, classRef, selector, method: binding.method,
    }),
  });
}

export {
  CLASS_SIDE,
  SMALLTALK_CLASS_DESCRIPTION_V1,
  SMALLTALK_METHOD_DESCRIPTION_V1,
  authorizedDescribeSmalltalkClass,
  authorizedDescribeSmalltalkMethod,
  authorizedReadSmalltalkMethodForUpdate,
};

import {
  CHARACTER_CLASS_NAME,
  CHARACTER_CODE_POINT_SLOT,
  CHARACTER_SHAPE_ID,
} from './smalltalk-primitives-character.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {assertMethodLane, defineMethods, ensureNamedClass, ensureSmalltalkShape, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {resolveGlobal} from './smalltalk-globals.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {objectRef, textValue} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// The native Character personality: canonical identity for a Unicode scalar, Text>>at: production
// through the same interner, and the smallest ordinary protocol forced by pinned YAXO. Character
// owns the scalar and its measured classification protocols; there is deliberately no case
// or printing protocol.

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.CHARACTER_INTERN]: 'smalltalk/primitive/character-intern',
  [SMALLTALK_PRIMITIVE.TEXT_AT_CHARACTER]: 'smalltalk/primitive/text-at-character',
  [SMALLTALK_PRIMITIVE.TEXT_SIZE]: 'smalltalk/primitive/text-size',
});

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const codeId = `${id}:code`;
  await ensureCodeArtifact(images, imageId, {
    id: codeId,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    languageId: SYMMETRIC_SMALLTALK_ID,
    content: textValue(primitiveCodeContent(primitive)),
    dependencies: [],
    derivedFrom: [],
    metadata: {},
  });
  await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeId),
    environment: null,
    metadata: {},
  });
  return objectRef(imageId, id);
}

async function installSmalltalkCharacterProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('images service is required');
  }
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const shapeRef = await ensureSmalltalkShape(images, imageId, {
    id: CHARACTER_SHAPE_ID,
    slots: [{id: CHARACTER_CODE_POINT_SLOT, name: 'codePoint'}],
  });
  const {classRef, metaclassRef} = await ensureNamedClass({
    images,
    imageId,
    name: CHARACTER_CLASS_NAME,
    superclassRef: kernel.objectClass,
    instanceShapeRef: shapeRef,
  });
  for (const primitive of Object.keys(PRIMITIVE_BLOCK_ID)) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  // Public construction delegates identity and scalar validation to the same literal/Text interner.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: metaclassRef,
    methods: [{
      selector: 'codePoint:', source: '[ :aScalar | ^ primitiveCharacterIntern value: aScalar ]',
      captures: [{
        id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.CHARACTER_INTERN], name: 'primitiveCharacterIntern',
        value: objectRef(imageId, PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.CHARACTER_INTERN]),
      }],
    }],
  });

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.textClass,
    methods: [{
      selector: 'at:',
      program: {
        parameters: [{id: 'at::parameter:0', name: 'index'}],
        captures: [{id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_AT_CHARACTER], name: '$textAtCharacter'}],
        body: {
          op: 'send',
          languageId: SYMMETRIC_SMALLTALK_ID,
          receiver: {op: 'binding', id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_AT_CHARACTER]},
          message: textValue('value:value:'),
          arguments: [{op: 'receiver'}, {op: 'argument', index: 0}],
        },
      },
      captures: [{
        id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_AT_CHARACTER],
        name: '$textAtCharacter',
        value: objectRef(imageId, PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_AT_CHARACTER]),
      }],
    }],
  });

  // Scalar cardinality shares Text indexing's interpretation. Enumeration itself stays in
  // ordinary Smalltalk, so Integer/Block own callback sequencing and exception propagation.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [
      {
        selector: 'size', source: '[ ^ primitiveTextSize value: self ]',
        captures: [{
          id: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_SIZE], name: 'primitiveTextSize',
          value: objectRef(imageId, PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.TEXT_SIZE]),
        }],
      },
      {
        selector: 'do:',
        source: '[ :aBlock | 1 to: self size do: [:index | aBlock value: (self at: index)]. ^ self ]',
      },
    ],
  });

  // Character already durably owns this scalar in its one named slot. Expose it through ordinary
  // instance-variable protocol rather than introducing a second field, host lookup or primitive.
  // The exact seven-member separator relation is the pinned Cuis semantic claim. Although Cuis
  // happens to express membership through Array>>statePointsTo:, generic collection membership is
  // not part of the forcing contract; keep the classification at its Character owner and compose
  // only the existing Integer equality and lazy Boolean protocol.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: [
      {selector: 'codePoint', source: '[ ^ codePoint ]'},
      {selector: 'isAscii', source: '[ ^ self codePoint < 128 ]'},
      // Pinned asciiValue is partial: non-ASCII scalars answer the canonical nil.
      {selector: 'asciiValue', source: '[ ^ self codePoint < 128 ifTrue: [self codePoint] ifFalse: [nil] ]'},
      {selector: 'isDigit', source: '[ ^ self codePoint between: 48 and: 57 ]'},
      {
        selector: 'isLetter',
        source: `[ | scalar |
          scalar := self codePoint.
          255 < scalar ifTrue: [ ^ self isLetterOutsideLatin1 ].
          ^ (scalar between: 65 and: 90) or: [
            (scalar between: 97 and: 122) or: [
              scalar = 170 or: [ scalar = 181 or: [ scalar = 186 or: [
                (scalar between: 192 and: 255) and: [
                  (scalar = 215 or: [ scalar = 247 ]) not ] ] ] ] ] ]
        ]`,
      },
      {
        selector: 'digitValue',
        source: `[ | scalar |
          scalar := self codePoint.
          (scalar between: 48 and: 57) ifTrue: [ ^ scalar - 48 ].
          (scalar between: 65 and: 90) ifTrue: [ ^ scalar - 55 ].
          ^ -1 ]`,
      },
      {
        selector: 'isSeparator',
        source: `[ | scalar |
          scalar := self codePoint.
          ^ scalar = 32 or: [
            scalar = 9 or: [
              scalar = 10 or: [
                scalar = 13 or: [
                  scalar = 12 or: [
                    scalar = 160 or: [ scalar = 8203 ] ] ] ] ] ]
        ]`,
      },
    ],
  });

  return Object.freeze({classRef, shapeRef});
}

// This result constructor names public Array/Character bindings. Its stage runs after global
// publication; basic Character identity and Text production retain their smaller prerequisites.
const CHARACTER_RANGE_METHODS = Object.freeze([Object.freeze({
  selector: 'to:',
  source: `[ :endCharacter | | start stop result index |
    start := self codePoint. stop := endCharacter codePoint.
    result := Array new: (stop - start + 1).
    index := 1.
    start to: stop do: [:scalar |
      result at: index put: (Character codePoint: scalar).
      index := index + 1 ].
    ^ result ]`,
})]);

async function installSmalltalkCharacterRangeProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') throw new TypeError('images service is required');
  assertMethodLane(lane);
  if (!await findSmalltalkKernel({images, imageId})) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  for (const name of ['Array', CHARACTER_CLASS_NAME]) {
    if (!await resolveGlobal({images, imageId, name})) {
      throw new TypeError(`image ${imageId} has not published the global ${name}; publish it first`);
    }
  }
  // Publication alone does not establish protocol in a partially installed image.
  for (const [objectId, selector] of [
    ['smalltalk/metaclass/Array', 'new:'], ['smalltalk/class/Array', 'at:put:'],
    ['smalltalk/metaclass/Character', 'codePoint:'], ['smalltalk/class/Character', 'codePoint'],
    ['smalltalk/class/Integer', 'to:do:'], ['smalltalk/class/Integer', '+'], ['smalltalk/class/Integer', '-'],
  ]) {
    const classRef = objectRef(imageId, objectId);
    if (!await images.getObject(imageId, objectId)
      || !await methodBlockRef({images, imageId, classRef, selector})) {
      throw new TypeError(`image ${imageId} has no ${objectId} ${selector} method; install its protocol first`);
    }
  }
  const classRef = objectRef(imageId, `smalltalk/class/${CHARACTER_CLASS_NAME}`);
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef, methods: CHARACTER_RANGE_METHODS});
  return Object.freeze({classRef});
}

export {
  installSmalltalkCharacterProtocol,
  installSmalltalkCharacterRangeProtocol,
};

