import {booleanValue, isObjectRef, textValue} from '../value/index.js';
import {defineMethods} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0045: Symmetric Smalltalk's conditionals, as ordinary methods on True and False.
//
// Nothing here is a primitive. Each method either evaluates one of its block arguments through an
// ordinary `value` send — which ADR 0044 decision 11 answers without a class — or answers `nil`,
// which it names through an ordinary captured binding rather than through an operation in the
// common IR. The compiler recognizes none of these selectors; a source conditional is a keyword
// send like any other, and the branch is taken by dispatch choosing True's method or False's.
//
// This is an installer, deliberately separate from `installSmalltalkKernel`. The kernel bootstrap
// creates identity; protocol arrives afterwards, per lane, exactly as `+` does. An image with a
// kernel and no control-flow protocol fails as message-not-understood, which is a coherent state.
const NIL_CAPTURE = Object.freeze({id: 'smalltalk/control-flow/nil', name: 'nil'});

// What each class does for each selector. Written as one table rather than hand-built programs so
// the symmetry is checkable by reading it: every selector appears once per class, and no two entries
// can drift apart in shape.
//
//   a number   evaluate that argument, by sending it `value`
//   null       answer nil
//   a boolean  answer that canonical boolean Value (ADR 0056)
//
// The Boolean protocol needed no second publication surface: `and:`/`or:` are the same shape as the
// conditionals — evaluate an argument, or answer without mentioning it — and their laziness falls
// out of that rather than being arranged. An arm that answers a literal never names the argument, so
// the Block simply is not evaluated.
const CONDITIONAL_PROTOCOL = Object.freeze([
  {selector: 'ifTrue:', parameters: ['aBlock'], True: 0, False: null},
  {selector: 'ifFalse:', parameters: ['aBlock'], True: null, False: 0},
  {selector: 'ifTrue:ifFalse:', parameters: ['trueBlock', 'falseBlock'], True: 0, False: 1},
  {selector: 'ifFalse:ifTrue:', parameters: ['falseBlock', 'trueBlock'], True: 1, False: 0},
  // ADR 0056 decision 4. Ordinary methods through ADR 0045's bridge; the compiler learns nothing.
  {selector: 'not', parameters: [], True: false, False: true},
  {selector: 'and:', parameters: ['aBlock'], True: 0, False: false},
  {selector: 'or:', parameters: ['aBlock'], True: true, False: 0},
]);

// ADR 0056 added three rows to the table above, so these are derived by *role* rather than by
// "everything in the table". `SMALLTALK_CONDITIONAL_SELECTORS` is public and has always meant the
// four conditionals; silently widening it would change what an existing name means, which is exactly
// the drift the reserved-word rule guards against one level down.
const BOOLEAN_SELECTORS = Object.freeze(['not', 'and:', 'or:']);

const SMALLTALK_CONDITIONAL_SELECTORS = Object.freeze(
  CONDITIONAL_PROTOCOL.map(({selector}) => selector).filter((selector) => !BOOLEAN_SELECTORS.includes(selector)),
);
const SMALLTALK_BOOLEAN_SELECTORS = Object.freeze([...BOOLEAN_SELECTORS]);
// Everything this installer publishes, for callers that mean exactly that.
const SMALLTALK_CONTROL_FLOW_SELECTORS = Object.freeze(CONDITIONAL_PROTOCOL.map(({selector}) => selector));

// The kernel slot naming each singleton, and the class it is an instance of. `True` and `False` have
// no kernel slot of their own, so the class is read from the singleton rather than named here.
const SINGLETONS = Object.freeze([
  {kernelSlot: 'true', className: 'True'},
  {kernelSlot: 'false', className: 'False'},
]);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// One method, as a semantic program plus the capture values its bindings need. `lagrange-code/v0`
// carries capture *descriptors*; the values live in the Block's lexical environment, which is what
// keeps `nil` an object in the graph rather than a meaning taught to the IR.
function conditionalMethod({selector, parameters, evaluate, nilRef}) {
  const parameterDescriptors = parameters.map((name, index) => ({
    id: `${selector}:parameter:${index}`,
    name,
  }));
  // ADR 0056: an arm that answers a boolean answers the canonical *Value*, not the singleton — the
  // singleton is a dispatch personality (ADR 0045), and a boolean-answering method must not quietly
  // convert one into the other.
  if (typeof evaluate === 'boolean') {
    return {
      selector,
      program: {
        parameters: parameterDescriptors,
        captures: [],
        body: {op: 'literal', value: booleanValue(evaluate)},
      },
      captures: [],
    };
  }
  if (evaluate === null) {
    return {
      selector,
      program: {
        parameters: parameterDescriptors,
        captures: [{...NIL_CAPTURE}],
        body: {op: 'binding', id: NIL_CAPTURE.id},
      },
      captures: [{...NIL_CAPTURE, value: nilRef}],
    };
  }
  return {
    selector,
    program: {
      parameters: parameterDescriptors,
      captures: [],
      // The block is invoked through the existing ordinary value path, so the whole conditional is
      // two sends: one that chose this method, and this one.
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'argument', index: evaluate},
        message: textValue('value'),
        arguments: [],
      },
    },
    captures: [],
  };
}

// The class of a singleton, read from the singleton itself rather than from a kernel slot. `True`
// and `False` have no kernel slot of their own, and going through the object is also the exact path
// the dispatcher's boolean bridge takes — so installing onto anything else would install onto a
// class the bridge does not reach.
async function classOfSingleton(images, singletonRef, label) {
  const record = await images.getObject(singletonRef.imageId, singletonRef.objectId);
  if (!record) throw new TypeError(`Smalltalk kernel ${label} not found: ${singletonRef.imageId}/${singletonRef.objectId}`);
  if (!isObjectRef(record.behavior)) {
    throw new TypeError(`Smalltalk kernel ${label} has no behavior: ${singletonRef.imageId}/${singletonRef.objectId}`);
  }
  return record.behavior;
}

async function installSmalltalkControlFlow({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const installed = {};
  for (const {kernelSlot, className} of SINGLETONS) {
    const classRef = await classOfSingleton(images, kernel[kernelSlot], kernelSlot);
    await defineMethods({
      images,
      compilation,
      imageId,
      classRef,
      lane,
      methods: CONDITIONAL_PROTOCOL.map((entry) => conditionalMethod({
        selector: entry.selector,
        parameters: entry.parameters,
        evaluate: entry[className],
        nilRef: kernel.nil,
      })),
    });
    installed[className] = classRef;
  }
  // ifNil:/ifNotNil: — the nil-checking protocol, installed on UndefinedObject (nil) and
  // Object (everything else). Ordinary Smalltalk methods over the existing conditional
  // and identity protocol: no new primitive, no compiler knowledge.
  //
  // UndefinedObject (nil): ifNil: evaluates the block; ifNotNil: answers nil.
  // Object (everything else): ifNil: answers self; ifNotNil: evaluates the block.
  //
  // The pinned Cuis oracle phrases the Object guard arms (`ProtoObject>>ifNotNil:` and
  // `ProtoObject>>ifNil:ifNotNil:`) as `valueWithPossibleArgument: self` — cull semantics where a
  // zero-argument block is evaluated with no arguments and a one-argument block receives `self`
  // (`BlockClosure>>valueWithPossibleArgument: = numArgs = 0 ifTrue: [self value] ifFalse: [self value: anArg]`).
  const undefinedObjectClass = await classOfSingleton(images, kernel.nil, 'nil');
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: undefinedObjectClass,
    methods: [
      {selector: 'ifNil:', source: '[ :aBlock | ^ aBlock value ]'},
      {selector: 'ifNotNil:', source: '[ :aBlock | ^ nil ]'},
      {selector: 'ifNil:ifNotNil:', source: '[ :nilBlock :ifNotNilBlock | ^ nilBlock value ]'},
    ],
  });
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      {selector: 'ifNil:', source: '[ :aBlock | ^ self ]'},
      {selector: 'ifNotNil:', source: '[ :aBlock | ^ aBlock valueWithPossibleArgument: self ]'},
      {selector: 'ifNil:ifNotNil:', source: '[ :nilBlock :ifNotNilBlock | ^ ifNotNilBlock valueWithPossibleArgument: self ]'},
    ],
  });

  return Object.freeze({
    trueClass: installed.True,
    falseClass: installed.False,
    undefinedObjectClass,
    selectors: SMALLTALK_CONTROL_FLOW_SELECTORS,
  });
}

export {
  NIL_CAPTURE as SMALLTALK_CONTROL_FLOW_NIL_CAPTURE,
  SMALLTALK_BOOLEAN_SELECTORS,
  SMALLTALK_CONDITIONAL_SELECTORS,
  SMALLTALK_CONTROL_FLOW_SELECTORS,
  installSmalltalkControlFlow,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, canonicalizeValue, integerValue} from '../value/index.js';

// ADR 0048 decisions 5 and 6: the durable Dictionary representation, as pure functions.
//
// Kept free of installers, executors and image services on purpose. A test can then prove the
// representation directly rather than only through surface sends, and a later MethodDictionary fast
// path can read the same layout without dragging in the Dictionary protocol.
const DICTIONARY_SHAPE_ID = 'smalltalk/dictionary-shape/v1';
const DICTIONARY_TABLE_SHAPE_ID = 'smalltalk/dictionary-table-shape/v1';
const DICTIONARY_TABLE_SLOT = 'dictionary-table';
const DICTIONARY_TALLY_SLOT = 'dictionary-table-tally';

const DICTIONARY_SHAPE_SLOTS = Object.freeze([{id: DICTIONARY_TABLE_SLOT, name: 'table'}]);
const DICTIONARY_TABLE_SHAPE_SLOTS = Object.freeze([{id: DICTIONARY_TALLY_SLOT, name: 'tally'}]);

// Power of two so the probe start is a mask-equivalent modulo, and at least 8 so a small dictionary
// still has slack before its first growth.
const DICTIONARY_MINIMUM_CAPACITY = 8;
const DICTIONARY_LOAD_NUMERATOR = 3;
const DICTIONARY_LOAD_DENOMINATOR = 4;

// Three Values per bucket. Occupancy is the *hash* cell rather than the key cell, which is what
// leaves `nil` usable as an ordinary key instead of being stolen as an empty sentinel.
const BUCKET_WIDTH = 3;

class SmalltalkDictionaryTableError extends TypeError {
  constructor(message) {
    super(`malformed Dictionary table: ${message}`);
    this.name = 'SmalltalkDictionaryTableError';
  }
}

function isIntegerValue(value) {
  return Boolean(value) && value.kind === VALUE_KIND.INTEGER;
}

function capacityOf(indexedLength) {
  if (indexedLength % BUCKET_WIDTH !== 0) {
    throw new SmalltalkDictionaryTableError(`indexed length ${indexedLength} is not a multiple of ${BUCKET_WIDTH}`);
  }
  const capacity = indexedLength / BUCKET_WIDTH;
  if (capacity < DICTIONARY_MINIMUM_CAPACITY || (capacity & (capacity - 1)) !== 0) {
    throw new SmalltalkDictionaryTableError(`capacity ${capacity} is not a power of two of at least ${DICTIONARY_MINIMUM_CAPACITY}`);
  }
  return capacity;
}

function emptyBuckets(capacity) {
  return Array.from({length: capacity}, () => ({hash: null, key: null, value: null}));
}

// Buckets -> the flat indexed part. `nil` fills all three cells of an empty bucket, so an empty
// bucket is indistinguishable from one that never held anything — there are no tombstones in v1
// because there is no removal.
function indexedFromBuckets(buckets, nilRef) {
  const indexed = [];
  for (const bucket of buckets) {
    if (bucket.hash === null) {
      indexed.push(nilRef, nilRef, nilRef);
      continue;
    }
    indexed.push(bucket.hash, bucket.key, bucket.value);
  }
  return indexed;
}

function bucketsFromIndexed(indexed) {
  const capacity = capacityOf(indexed.length);
  const buckets = [];
  for (let index = 0; index < capacity; index += 1) {
    const base = index * BUCKET_WIDTH;
    const hash = indexed[base];
    if (!isIntegerValue(hash)) {
      buckets.push({hash: null, key: null, value: null});
      continue;
    }
    buckets.push({hash, key: indexed[base + 1], value: indexed[base + 2]});
  }
  return buckets;
}

// Linear probing from the floor-modulo of the hash. Floor rather than truncating remainder because
// a user-defined `hash` may answer a negative Integer, and a negative start index would otherwise
// probe outside the table.
function probeStart(hashValue, capacity) {
  if (!isIntegerValue(hashValue)) {
    throw new SmalltalkDictionaryTableError('a stored or query hash must be an Integer Value');
  }
  const capacityBig = BigInt(capacity);
  const raw = BigInt(hashValue.value) % capacityBig;
  return Number(((raw % capacityBig) + capacityBig) % capacityBig);
}

function* probeSequence(hashValue, capacity) {
  const start = probeStart(hashValue, capacity);
  for (let step = 0; step < capacity; step += 1) {
    yield (start + step) % capacity;
  }
}

function sameStoredHash(left, right) {
  return isIntegerValue(left) && isIntegerValue(right) && BigInt(left.value) === BigInt(right.value);
}

// Growth is decided from the count the table would have *after* the insert, so a table never
// publishes at a load above the limit and then grows on the following write.
function needsGrowth(tallyAfterInsert, capacity) {
  return tallyAfterInsert * DICTIONARY_LOAD_DENOMINATOR > capacity * DICTIONARY_LOAD_NUMERATOR;
}

function grownCapacity(capacity) {
  return capacity * 2;
}

// Reinsertion after growth places entries by their **stored** hashes. A key is never sent `hash`
// again merely because the table grew: that would re-run user code during an internal resize, and
// a key whose hash had since changed would silently relocate.
function reinsert(buckets, capacity) {
  const grown = emptyBuckets(capacity);
  for (const bucket of buckets) {
    if (bucket.hash === null) continue;
    let placed = false;
    for (const index of probeSequence(bucket.hash, capacity)) {
      if (grown[index].hash === null) {
        grown[index] = {...bucket};
        placed = true;
        break;
      }
    }
    if (!placed) throw new SmalltalkDictionaryTableError('grown table has no free bucket, which cannot happen below the load factor');
  }
  return grown;
}

function tallyOf(buckets) {
  return buckets.reduce((count, bucket) => count + (bucket.hash === null ? 0 : 1), 0);
}

// The durable form of a table snapshot, ready for `putObject`. `behavior` is deliberately absent:
// DictionaryTable is a language-owned internal graph object, not a public Smalltalk class.
function tableRecordFields({buckets, shapeRef, nilRef}) {
  return {
    shape: shapeRef,
    slots: {[DICTIONARY_TALLY_SLOT]: integerValue(tallyOf(buckets))},
    indexed: indexedFromBuckets(buckets, nilRef),
    metadata: {smalltalk: 'dictionary-table'},
  };
}

// Read a stored table, validating what the representation promises rather than trusting it. A
// dictionary whose tally disagrees with its buckets would make `size` lie, and a mis-sized indexed
// part would make probing read the wrong cells.
function readTableRecord(record) {
  if (!record || record.kind !== 'object') throw new SmalltalkDictionaryTableError('table record is not an object');
  if (!Object.hasOwn(record, 'indexed')) throw new SmalltalkDictionaryTableError('table record has no indexed part');
  const buckets = bucketsFromIndexed(record.indexed);
  const tally = record.slots?.[DICTIONARY_TALLY_SLOT];
  if (!isIntegerValue(tally)) throw new SmalltalkDictionaryTableError('table tally must be an Integer Value');
  const counted = tallyOf(buckets);
  if (BigInt(tally.value) !== BigInt(counted)) {
    throw new SmalltalkDictionaryTableError(`table tally ${tally.value} disagrees with ${counted} occupied buckets`);
  }
  return {buckets, capacity: buckets.length, tally: counted};
}

function sameCanonicalValue(left, right) {
  return JSON.stringify(canonicalizeValue(left)) === JSON.stringify(canonicalizeValue(right));
}

