  BUCKET_WIDTH,
  DICTIONARY_LOAD_DENOMINATOR,
  DICTIONARY_LOAD_NUMERATOR,
  DICTIONARY_MINIMUM_CAPACITY,
  DICTIONARY_SHAPE_ID,
  DICTIONARY_SHAPE_SLOTS,
  DICTIONARY_TABLE_SHAPE_ID,
  DICTIONARY_TABLE_SHAPE_SLOTS,
  DICTIONARY_TABLE_SLOT,
  DICTIONARY_TALLY_SLOT,
  SHAPE_INDEXED,
  SmalltalkDictionaryTableError,
  bucketsFromIndexed,
  capacityOf,
  emptyBuckets,
  grownCapacity,
  indexedFromBuckets,
  needsGrowth,
  probeSequence,
  probeStart,
  readTableRecord,
  reinsert,
  sameCanonicalValue,
  sameStoredHash,
  tableRecordFields,
  tallyOf,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {objectRef, textValue} from '../value/index.js';
import {
  assertMethodLane,
  defineMethods,
  ensureBlock,
  ensureCodeArtifact,
  ensureNamedClass,
  ensureSmalltalkShape,
} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  DICTIONARY_SHAPE_ID,
  DICTIONARY_SHAPE_SLOTS,
  DICTIONARY_TABLE_SHAPE_ID,
  DICTIONARY_TABLE_SHAPE_SLOTS,
} from './smalltalk-dictionary-table.js';
import {
  SmalltalkKernelConflictError,
  canonicalJson,
  findSmalltalkKernel,
  readBehavior,
} from './smalltalk-kernel.js';
import {sameRef} from './smalltalk-lookup.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0048 decisions 1 and 9: the `Object >> =` / `Object >> ==` / `Object >> ~~` /
// `Object >> hash` protocol and the first public `Dictionary` protocol, installed after kernel
// identity exists exactly as ADRs 0045-0047 install theirs. The compiler and dispatcher learn none
// of these selectors.
//
// Two installers rather than one, because they are separately useful: equality and hashing are
// ordinary Object protocol that a program may want without any collection at all, and a later
// MethodDictionary fast path needs the built-in helpers rather than the Dictionary class.
const DICTIONARY_CLASS_ID = 'smalltalk/class/Dictionary';
const DICTIONARY_METACLASS_ID = 'smalltalk/metaclass/Dictionary';

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS]: 'smalltalk/primitive/built-in-equals',
  [SMALLTALK_PRIMITIVE.BUILT_IN_HASH]: 'smalltalk/primitive/built-in-hash',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE]: 'smalltalk/primitive/dictionary-initialize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_SIZE]: 'smalltalk/primitive/dictionary-size',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY]: 'smalltalk/primitive/dictionary-includes-key',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT]: 'smalltalk/primitive/dictionary-at',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT]: 'smalltalk/primitive/dictionary-at-put',
  [SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO]: 'smalltalk/primitive/dictionary-keys-and-values-do',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS]: 'primitiveEquals',
  [SMALLTALK_PRIMITIVE.BUILT_IN_HASH]: 'primitiveHash',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE]: 'primitiveDictionaryInitialize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_SIZE]: 'primitiveDictionarySize',
  [SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY]: 'primitiveDictionaryIncludesKey',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT]: 'primitiveDictionaryAt',
  [SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT]: 'primitiveDictionaryAtPut',
  [SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO]: 'primitiveDictionaryKeysAndValuesDo',
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

const captureFor = (primitive) => ({id: PRIMITIVE_BLOCK_ID[primitive], name: CAPTURE_NAME[primitive]});
const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

function primitiveSend(capture, args) {
  return {
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: {op: 'binding', id: capture.id},
    message: textValue('value:'.repeat(args.length)),
    arguments: args,
  };
}

// One method reaching one primitive, with the primitive Block bound as an ordinary captured ref in
// the method's own lexical environment.
function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = captureFor(primitive);
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{...capture}],
      body: primitiveSend(capture, args),
    },
    captures: [{...capture, value: objectRef(imageId, capture.id)}],
  };
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}


// `Object >> =`, identity `==` / `~~`, and `Object >> hash`. Every receiver in the image inherits
// them, which is what makes the default relation of decision 2 the language's default rather than a
// Dictionary-private helper.
async function installSmalltalkEqualityProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  for (const primitive of [SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS, SMALLTALK_PRIMITIVE.BUILT_IN_HASH]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      capturedMethod({
        selector: '=',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS,
        parameters: ['anObject'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      // Workstream 3 (MessagePack pressure: the type-mapper dispatch sends `self class == Dictionary`,
      // and the slice also compares symbols, integers, booleans-across-the-bridge and ordinary refs
      // with `==`). `==` is *identity*, and it must NOT route through `=` — `=` is overridable
      // (Association overrides it for value equality), so `^self = anObject` would be wrong.
      //
      // It reuses the SAME built-in primitive as `=` rather than a new one, because ADR 0048 decision
      // 2's relation is already exactly what identity means here: an ObjectRef has genuine
      // (imageId, objectId) identity, while an immediate Value (Integer/Float/Text/Bytes/Boolean)
      // carries no object identity apart from its value, so its identity collapses to value by
      // construction. Two equal-but-distinct Associations are distinct refs -> `==` is false;
      // `1000 == 1000` is value-true because that is the only identity 1000 has. The primitive also
      // applies the ADR 0045 boolean-singleton normalization, which `aBoolean == true` across the
      // bridge requires — a hand-rolled identity primitive would risk dropping it.
      //
      // Like `=`, `==` is an ordinary (overridable) method; Smalltalk convention is not to override
      // it, and the language deliberately does not seal it.
      capturedMethod({
        selector: '==',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_EQUALS,
        parameters: ['anObject'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'hash',
        primitive: SMALLTALK_PRIMITIVE.BUILT_IN_HASH,
        args: [receiver()],
        imageId,
      }),
    ],
  });

  // Pinned Cuis ProtoObject>>~~ is source-level composition through `==`, not a second identity
  // primitive. In this native image `==` is deliberately an ordinary overridable method, so `~~`
  // must send it dynamically and then consume the existing Boolean protocol. Installing this from
  // Smalltalk source keeps binary-selector syntax and both sends in their existing owners.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [{selector: '~~', source: '[ :anObject | ^ (self == anObject) not ]'}],
  });
  return Object.freeze({objectClass: kernel.objectClass});
}


async function installSmalltalkDictionaryProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // The table Shape carries the indexed declaration ADR 0047 introduced; the Dictionary Shape is an
  // ordinary one-slot layout, so a Dictionary's own identity never moves when its contents change.
  await ensureSmalltalkShape(images, imageId, {id: DICTIONARY_SHAPE_ID, slots: [...DICTIONARY_SHAPE_SLOTS]});
  await ensureSmalltalkShape(images, imageId, {
    id: DICTIONARY_TABLE_SHAPE_ID,
    slots: [...DICTIONARY_TABLE_SHAPE_SLOTS],
    indexed: SHAPE_INDEXED.VALUES,
  });

  for (const primitive of [
    SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE,
    SMALLTALK_PRIMITIVE.DICTIONARY_SIZE,
    SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY,
    SMALLTALK_PRIMITIVE.DICTIONARY_AT,
    SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT,
    SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO,
  ]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  const {classRef, metaclassRef} = await ensureNamedClass({
    images,
    imageId,
    name: 'Dictionary',
    superclassRef: kernel.objectClass,
    instanceShapeRef: objectRef(imageId, DICTIONARY_SHAPE_ID),
  });

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: [
      // Overrides `Object >> initialize`, which ADR 0046 installs as `^self`. `new` therefore stays
      // ordinary composition: basicNew leaves `table` nil, and this fills it in.
      capturedMethod({
        selector: 'initialize',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE,
        args: [receiver()],
        imageId,
      }),
      capturedMethod({
        selector: 'size',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_SIZE,
        args: [receiver()],
        imageId,
      }),
      capturedMethod({
        selector: 'includesKey:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY,
        parameters: ['aKey'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'at:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_AT,
        parameters: ['aKey'],
        args: [receiver(), argument(0)],
        imageId,
      }),
      capturedMethod({
        selector: 'at:put:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT,
        parameters: ['aKey', 'aValue'],
        args: [receiver(), argument(0), argument(1)],
        imageId,
      }),
      // Workstream 3 (MessagePack pressure: `writeMap:` walks every pair). The one enumeration
      // primitive — the pairs live in the hidden table representation, so no composition of the
      // protocol above can reach them. Snapshot semantics, no hash/= re-sends and no order promise
      // are documented at the primitive itself.
      capturedMethod({
        selector: 'keysAndValuesDo:',
        primitive: SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO,
        parameters: ['aBlock'],
        args: [receiver(), argument(0)],
        imageId,
      }),
    ],
  });

  // Workstream 3 (MessagePack pressure). Ordinary-source lookup conveniences composed from the
  // primitives above — `MpSettings` and the type mappers read with `at:ifAbsent:`/`at:ifAbsentPut:`.
  // No new primitive and no table access: a miss is one `at:put:` through the existing protocol.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: [
      {
        selector: 'at:ifAbsent:',
        source: '[ :key :aBlock | (self includesKey: key) ifTrue: [ ^ self at: key ] ifFalse: [ ^ aBlock value ] ]',
      },
      {
        selector: 'at:ifAbsentPut:',
        source: '[ :key :aBlock | (self includesKey: key) ifTrue: [ ^ self at: key ] ifFalse: [ ^ self at: key put: (aBlock value) ] ]',
      },
    ],
  });

  // Class-side. Upstream `createDictionary:` sends `Dictionary new: size`, where `size` is only a
  // capacity *hint*. This Dictionary grows on demand from a fixed floor and has no capacity-taking
  // allocation primitive, so the honest minimal class method accepts and ignores the hint. It lives
  // on the metaclass — sending `new:` to the class object dispatches through the metaclass chain,
  // exactly like `Array new:`. `self new` resolves to the inherited zero-argument `Class>>new`
  // (basicNew + initialize), so it terminates rather than recursing into `new:`.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: metaclassRef,
    methods: [
      {selector: 'new:', source: '[ :size | ^ self new ]'},
    ],
  });

  return Object.freeze({classRef, dictionaryShape: objectRef(imageId, DICTIONARY_SHAPE_ID)});
}

export {
  DICTIONARY_CLASS_ID,
  PRIMITIVE_BLOCK_ID as SMALLTALK_DICTIONARY_PRIMITIVE_BLOCK_ID,
  installSmalltalkDictionaryProtocol,
  installSmalltalkEqualityProtocol,
};

import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {utf8Encode} from '../support/portable-bytes.js';
import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  float64ToNumber,
  integerValue,
  isObjectRef,
} from '../value/index.js';

// ADR 0048 decisions 2 and 3: the built-in `=` relation and the stable `hash` that must agree with
// it. Everything here is a pure function of canonical Values, which is what lets a later
// MethodDictionary fast path use the same helpers on Text selectors without executing any Smalltalk.
//
// This is deliberately *not* the `lagrange-code` `equals` op. That op is a frozen language-neutral
// structural comparison; this is one language's equality protocol, and the two must be able to
// disagree without either changing.
const SMALLTALK_EQUALITY_DOMAIN = 'smalltalk/equality/v1';

// The hash is a durable contract, not an implementation detail. Existing persistent tables were laid
// out with it, so replacing the algorithm is a migration decision rather than an optimization.
const SMALLTALK_HASH_BITS = 63n;
const SMALLTALK_HASH_MASK = (1n << SMALLTALK_HASH_BITS) - 1n;

class SmalltalkUnhashableValueError extends TypeError {
  constructor(kind) {
    super(
      `Symmetric Smalltalk has no equality or hash contract for a ${kind} Value; `
      + 'it is graph/history state rather than a Smalltalk receiver',
    );
    this.name = 'SmalltalkUnhashableValueError';
    this.kind = kind;
  }
}

function sameRefIdentity(left, right) {
  return left.imageId === right.imageId && left.objectId === right.objectId;
}

// An integral Float64 and an Integer denote the same number, so they share one normal form. The
// conversion goes through the Float's own value rather than through JavaScript's safe-integer range:
// 2^60 is exactly representable and must hash like the Integer 2^60, while 2^60+1 must not.
function integralFloat(value) {
  const number = float64ToNumber(value);
  if (!Number.isFinite(number) || !Number.isInteger(number)) return null;
  // -0 and +0 both become 0n, which is what makes them one key.
  return BigInt(number);
}

// The equality normal form, and therefore the hash pre-image. Two Values are built-in equal exactly
// when their normal forms are identical, which is what makes `a = b => a hash = b hash` true by
// construction rather than by parallel maintenance of two functions.
//
// NaN is the one deliberate exception: it has a stable normal form, but `=` says it is unequal to
// everything including itself. Dictionary does not repair a key whose own equality relation rejects
// it.
function equalityNormalForm(input) {
  const value = canonicalizeValue(input);
  switch (value.kind) {
    case VALUE_KIND.BOOLEAN:
      return ['boolean', value.value];
    case VALUE_KIND.TEXT:
      return ['text', value.value];
    case VALUE_KIND.BYTES:
      return ['bytes', value.base64];
    case VALUE_KIND.INTEGER:
      return ['number/integer', BigInt(value.value).toString(10)];
    case VALUE_KIND.FLOAT64: {
      const number = float64ToNumber(value);
      if (Number.isNaN(number)) return ['number/nan', value.bits];
      if (!Number.isFinite(number)) return ['number/infinity', number > 0 ? '+' : '-'];
      const integral = integralFloat(value);
      if (integral !== null) return ['number/integer', integral.toString(10)];
      // IEEE64 has exactly one bit pattern per finite non-integral value, so the bits are already a
      // canonical form; only NaN payloads and signed zero needed special handling, and both are
      // handled above.
      return ['number/float64', value.bits];
    }
    case VALUE_KIND.REF:
      return ['ref', value.imageId, value.objectId];
    default:
      throw new SmalltalkUnhashableValueError(value.kind);
  }
}

function builtInEquals(leftInput, rightInput) {
  const left = canonicalizeValue(leftInput);
  const right = canonicalizeValue(rightInput);

  // Identity, and nothing else: no record is read, so `_version`, Shape, behavior and slot contents
  // never participate. Two refs to the same object are equal however much the object has changed.
  if (isObjectRef(left) || isObjectRef(right)) {
    return isObjectRef(left) && isObjectRef(right) && sameRefIdentity(left, right);
  }
  // A pinned ref has no Smalltalk behavior, so it is not equal to anything rather than being an
  // error here; `hash` is where using one as a key actually fails.
  if (left.kind === VALUE_KIND.PINNED_REF || right.kind === VALUE_KIND.PINNED_REF) return false;

  const numericKinds = new Set([VALUE_KIND.INTEGER, VALUE_KIND.FLOAT64]);
  if (numericKinds.has(left.kind) && numericKinds.has(right.kind)) {
    // NaN must be unequal to itself, and no normal form can express that, so numbers are compared
    // directly rather than by comparing normal forms.
    if (left.kind === VALUE_KIND.FLOAT64 && Number.isNaN(float64ToNumber(left))) return false;
    if (right.kind === VALUE_KIND.FLOAT64 && Number.isNaN(float64ToNumber(right))) return false;
    const asBigInt = (value) => (value.kind === VALUE_KIND.INTEGER ? BigInt(value.value) : integralFloat(value));
    const leftInteger = asBigInt(left);
    const rightInteger = asBigInt(right);
    if (leftInteger !== null && rightInteger !== null) return leftInteger === rightInteger;
    // At least one is a non-integral or infinite Float; an Integer can equal neither.
    if (left.kind !== VALUE_KIND.FLOAT64 || right.kind !== VALUE_KIND.FLOAT64) return false;
    return float64ToNumber(left) === float64ToNumber(right);
  }

  if (left.kind !== right.kind) return false;
  switch (left.kind) {
    case VALUE_KIND.BOOLEAN:
      return left.value === right.value;
    case VALUE_KIND.TEXT:
      return left.value === right.value;
    case VALUE_KIND.BYTES:
      // Canonical base64, so string equality is byte equality.
      return left.base64 === right.base64;
    default:
      throw new SmalltalkUnhashableValueError(left.kind);
  }
}

// Deterministic across processes and restarts, because bucket placement in a durable table depends
// on it. A host-randomized or address-derived hash would relocate every key on restart.
function builtInHash(value) {
  const form = equalityNormalForm(value);
  const digest = getDefaultCryptoProvider().sha256(
    utf8Encode(JSON.stringify([SMALLTALK_EQUALITY_DOMAIN, ...form])),
  );
  return integerValue(new DataView(digest.buffer, digest.byteOffset, digest.byteLength).getBigUint64(0, false) & SMALLTALK_HASH_MASK);
}

// ADR 0045 makes the `true`/`false` singleton the effective receiver of a boolean send, so a
// built-in comparison would otherwise see a ref on one side and a boolean Value on the other and
// answer false. Normalizing the two well-known local singletons back to their boolean values keeps
// `true = true` from depending on which side of the bridge each operand arrived through.
function normalizeBooleanSingleton(value, kernel) {
  if (!kernel || !isObjectRef(value)) return value;
  if (sameRefIdentity(value, kernel.true)) return booleanValue(true);
  if (sameRefIdentity(value, kernel.false)) return booleanValue(false);
  return value;
}

export {
  sameRefIdentity,
  SMALLTALK_EQUALITY_DOMAIN,
  SMALLTALK_HASH_BITS,
  SmalltalkUnhashableValueError,
  builtInEquals,
  builtInHash,
  equalityNormalForm,
  normalizeBooleanSingleton,
};

import {canonicalRecordJson} from '../graph/ensure-records.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, isObjectRef, objectRef, textValue} from '../value/index.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {assertMethodLane, ensureNamedClass} from './smalltalk-class-builder.js';
import {KERNEL_CLASSES, ensureObject, ensureShape, findSmalltalkKernel, isLocalRef} from './smalltalk-kernel.js';

// ADR 0057: the durable namespace, and the first-class bindings it maps to.
//
// Three things are kept apart throughout, and most of this module exists to keep them apart:
//
//   name              a Text key in the mapping below
//   binding identity  a GlobalBinding object, stable across rename and rebinding
//   current value     what that binding holds right now
//
// The binding deliberately does not carry its own name — that is what lets renaming preserve
// identity — and it answers `value` and nothing else. A compiled method necessarily holds the
// binding ref in order to *read* the global, so an ordinary setter would make every reader a
// writer: reference is not authority (ADR 0057 decision 2). Rebinding happens through the trusted
// operations here.
const SMALLTALK_GLOBAL_NAMESPACE_V1 = 'smalltalk-global-namespace/v1';
const NAMESPACE_OBJECT_ID = 'smalltalk-global-namespace/v1';
// ADR 0002: Shapes are immutable, and a structural change creates a new shape identity. ADR 0061
// adds the parent slot, so the namespace Shape is v2 — never a mutation of v1. v1 is kept as a
// constant so a namespace record written before 0061 still validates (dual-read) and is migrated
// to v2 the first time its mapping is rewritten.
const NAMESPACE_SHAPE_ID_V1 = 'smalltalk/global-namespace-shape/v1';
const NAMESPACE_SHAPE_ID = 'smalltalk/global-namespace-shape/v2';
const NAMESPACE_PARENT_SLOT = 'namespace-parent';
const GLOBAL_BINDING_SHAPE_ID = 'smalltalk/global-binding-shape/v1';
const GLOBAL_BINDING_VALUE_SLOT = 'global-binding-value';
const GLOBAL_BINDING_CLASS_ID = 'smalltalk/class/GlobalBinding';

// Core installers choose stable, readable ids. The *generic* service never derives one — see
// `publish`, which requires the caller to supply it.
const globalBindingId = (name) => `smalltalk/global-binding/${name}`;

class SmalltalkNamespaceError extends TypeError {
  constructor(imageId, detail) {
    super(`Symmetric Smalltalk global namespace in ${imageId} is corrupt: ${detail}`);
    this.name = 'SmalltalkNamespaceError';
    this.imageId = imageId;
  }
}

class SmalltalkGlobalConflictError extends TypeError {
  constructor(name, detail) {
    super(`global ${name} ${detail}`);
    this.name = 'SmalltalkGlobalConflictError';
    this.globalName = name;
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// The mapping is an indexed part rather than named Shape slots. A Shape's identity is its layout, so
// slots would turn every publication, rename and removal into a structural migration of the
// namespace object; an indexed part lets the mapping mutate while the Shape stays fixed.
//
// Canonical order — sorted by name — so two images that published the same globals in different
// orders hold the same record, and so a rewrite is a diff rather than a reshuffle.
function encodePairs(entries) {
  const indexed = [];
  for (const [name, binding] of [...entries].sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))) {
    indexed.push(textValue(name), binding);
  }
  return indexed;
}

function decodePairs(imageId, indexed) {
  if (!Array.isArray(indexed)) throw new SmalltalkNamespaceError(imageId, 'the mapping is not an indexed part');
  if (indexed.length % 2 !== 0) {
    throw new SmalltalkNamespaceError(imageId, `the mapping has an odd number of entries (${indexed.length})`);
  }
  const entries = new Map();
  let previousName = null;
  for (let index = 0; index < indexed.length; index += 2) {
    const name = indexed[index];
    const binding = indexed[index + 1];
    if (name?.kind !== VALUE_KIND.TEXT || name.value.length === 0) {
      throw new SmalltalkNamespaceError(imageId, `entry ${index / 2} has a non-Text name`);
    }
    if (!isLocalRef(binding, imageId)) {
      throw new SmalltalkNamespaceError(imageId, `entry ${name.value} must map to an unpinned local ref`);
    }
    if (entries.has(name.value)) throw new SmalltalkNamespaceError(imageId, `duplicate name ${name.value}`);
    // The representation is *promised* canonical, so an out-of-order mapping is corrupt rather than
    // something to quietly normalise on the next write. Accepting it would mean two images holding
    // the same globals could hold different records, which is the property canonical order exists
    // to rule out.
    if (previousName !== null && previousName >= name.value) {
      throw new SmalltalkNamespaceError(imageId, `entries are not in canonical order: ${previousName} before ${name.value}`);
    }
    previousName = name.value;
    entries.set(name.value, binding);
  }
  return entries;
}

async function assertIsBinding({images, imageId, name, binding}) {
  const record = await images.getObject(binding.imageId, binding.objectId);
  if (!record) throw new SmalltalkNamespaceError(imageId, `${name} maps to a missing object`);
  if (!isLocalRef(record.shape, imageId, GLOBAL_BINDING_SHAPE_ID)) {
    throw new SmalltalkNamespaceError(imageId, `${name} maps to an object that is not a GlobalBinding`);
  }
  if (!isLocalRef(record.behavior, imageId, GLOBAL_BINDING_CLASS_ID)) {
    throw new SmalltalkNamespaceError(imageId, `${name} maps to an object whose behavior is not GlobalBinding`);
  }
  return record;
}

// Installs the binding class, its read protocol, and an empty namespace. Needs only the kernel and
// the instance-variable protocol — deliberately not `Association`, allocation or equality, so a
// binding can exist before the classes it will name.
async function installSmalltalkGlobalNamespace({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const bindingShape = await ensureShape(images, imageId, {
    id: GLOBAL_BINDING_SHAPE_ID,
    slots: [{id: GLOBAL_BINDING_VALUE_SLOT, name: 'value'}],
  });
  const {classRef} = await ensureNamedClass({
    images, imageId, name: 'GlobalBinding', instanceShapeRef: objectRef(imageId, bindingShape.id),
  });
  // `value` and nothing else. There is no `value:`, by decision: see the header.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef, methods: [{selector: 'value', source: '[ value ]'}],
  });

  // ADR 0061: one slot, the optional parent edge. This is the v2 Shape — v1 had no slots. The slot
  // is always present in a v2 namespace object — `putObject` enforces exact slot-set match — so
  // "no parent" is a nil Value here, never an omitted slot. The root is the parentless namespace.
  const namespaceShape = await ensureShape(images, imageId, {
    id: NAMESPACE_SHAPE_ID,
    slots: [{id: NAMESPACE_PARENT_SLOT, name: 'parent'}],
    indexed: SHAPE_INDEXED.VALUES,
  });
  // Created empty, but *not* ensured against an empty mapping: the mapping has its own lifecycle
  // once anything is published, exactly as a binding's value does. Ensuring exactness here would
  // make re-running the installer conflict with every global published since — the same mistake as
  // resetting a rebound value on republication.
  // Admission is the ensure owner's, in SEED mode (the empty mapping is only the initial value);
  // the domain check — whatever came back must be a real namespace, so a squatter is refused
  // rather than adopted — is ours and runs on created and adopted records alike.
  await ensureObject(images, imageId, {
    id: NAMESPACE_OBJECT_ID,
    shape: objectRef(imageId, namespaceShape.id),
    behavior: null,
    slots: {[NAMESPACE_PARENT_SLOT]: kernel.nil},
    indexed: [],
    metadata: {protocol: SMALLTALK_GLOBAL_NAMESPACE_V1},
  }, {seed: true});
  await findSmalltalkGlobalNamespace({images, imageId});

  // The kernel classes are published here because they already exist and this installer is the
  // first thing that can name anything. Everything else is published deliberately by whoever
  // installs it — publication is an operation, never a side effect of creating a class.
  for (const {name} of KERNEL_CLASSES) {
    await publishGlobal({
      images, imageId, name, bindingId: globalBindingId(name),
      value: objectRef(imageId, `smalltalk/class/${name}`),
    });
  }

  return Object.freeze({
    protocol: SMALLTALK_GLOBAL_NAMESPACE_V1,
    ref: objectRef(imageId, NAMESPACE_OBJECT_ID),
    bindingClass: classRef,
  });
}

// An explicit publication step for classes a protocol installer created. Deliberately a separate
// call rather than something `ensureNamedClass` does: a class may exist and remain unnameable, which
// is what keeps a future private or project namespace possible (ADR 0057 decision 1).
async function publishSmalltalkClassGlobals({images, imageId, names} = {}) {
  requiredText(imageId, 'image id');
  if (!Array.isArray(names) || names.length === 0) throw new TypeError('names must be a non-empty array');
  const published = {};
  for (const name of names) {
    const classId = `smalltalk/class/${name}`;
    if (!await images.getObject(imageId, classId)) {
      throw new TypeError(`image ${imageId} has no class ${name} to publish`);
    }
    published[name] = await publishGlobal({
      images, imageId, name, bindingId: globalBindingId(name), value: objectRef(imageId, classId),
    });
  }
  return Object.freeze(published);
}

// ADR 0061: the parent edge. A namespace object stores it in the `namespace-parent` slot: the
// kernel nil for the root, a ref to another namespace otherwise. Reading it is tolerant of the
// pre-0061 root, which was written with `slots: {}` before the Shape grew the slot — absence reads
// as no parent, and the first rewrite carries the slot forward. `nilRef` is the kernel nil, the
// only value besides a namespace ref the slot may hold.
function namespaceParentRef(imageId, record, nilRef) {
  const parent = record.slots?.[NAMESPACE_PARENT_SLOT];
  if (parent === undefined || parent === null) return null;
  if (!isLocalRef(parent, imageId)) {
    throw new SmalltalkNamespaceError(imageId, `the parent slot holds a non-local value, not a namespace ref or nil`);
  }
  // The kernel nil means "no parent"; any other local ref names the parent namespace.
  if (nilRef && parent.objectId === nilRef.objectId) return null;
  return parent;
}

// Generalized finder (ADR 0061). `findSmalltalkGlobalNamespace` is the root special case; this one
// reads any namespace by id. Absent stays distinct from corrupt, as with every other discoverable
// protocol here: an image without the object simply has no such namespace, while a damaged one is
// an explicit failure.
async function findNamespace({images, imageId, namespaceId = NAMESPACE_OBJECT_ID} = {}) {
  requiredText(imageId, 'namespace image id');
  requiredText(namespaceId, 'namespace id');
  const record = await images.getObject(imageId, namespaceId);
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_GLOBAL_NAMESPACE_V1) {
    throw new SmalltalkNamespaceError(imageId, `${namespaceId} does not declare ${SMALLTALK_GLOBAL_NAMESPACE_V1}`);
  }
  // Dual-read: a namespace written before ADR 0061 has the v1 (slotless) Shape; a nested one or a
  // migrated root has v2. Both are namespaces; only v2 can carry a parent edge.
  const isNamespaceShape = isLocalRef(record.shape, imageId, NAMESPACE_SHAPE_ID)
    || isLocalRef(record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  if (!isNamespaceShape) {
    throw new SmalltalkNamespaceError(imageId, `${namespaceId} does not have a namespace Shape`);
  }
  const entries = decodePairs(imageId, record.indexed);
  for (const [name, binding] of entries) {
    await assertIsBinding({images, imageId, name, binding});
  }
  // The kernel nil is the only non-namespace value the parent slot may hold; look it up to read the
  // edge. An image with a namespace always has a kernel (the installer needs one), so this is safe.
  const kernel = await findSmalltalkKernel({images, imageId});
  return Object.freeze({
    protocol: SMALLTALK_GLOBAL_NAMESPACE_V1,
    record,
    entries,
    parent: namespaceParentRef(imageId, record, kernel?.nil ?? null),
  });
}

// Absent stays distinct from corrupt, as with every other discoverable protocol here: an image
// without a namespace simply has no globals, while a damaged one is an explicit failure.
async function findSmalltalkGlobalNamespace({images, imageId} = {}) {
  return await findNamespace({images, imageId, namespaceId: NAMESPACE_OBJECT_ID});
}

async function requireNamespace({images, imageId, namespaceId = NAMESPACE_OBJECT_ID}) {
  const namespace = await findNamespace({images, imageId, namespaceId});
  if (!namespace) {
    throw new TypeError(`image ${imageId} has no global namespace ${namespaceId}; install it first`);
  }
  return namespace;
}

async function writeMapping({images, imageId, namespace, entries}) {
  // Writes this namespace's own id and preserves its slots — critically the parent edge. Writing
  // `slots: {}` would erase the parent on every publish/rename/remove in a nested namespace. A
  // record still on the v1 (slotless) Shape is MIGRATED to v2 here: it gains the parent slot (nil,
  // since a v1 record is the root and the root is parentless) and the v2 Shape ref, so ADR 0002's
  // immutability is honored — v1 is never mutated, the object just moves to the new Shape.
  const kernel = await findSmalltalkKernel({images, imageId});
  const onV1 = isLocalRef(namespace.record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  const slots = onV1
    ? {[NAMESPACE_PARENT_SLOT]: kernel.nil}
    : (namespace.record.slots && Object.hasOwn(namespace.record.slots, NAMESPACE_PARENT_SLOT)
      ? namespace.record.slots
      : {[NAMESPACE_PARENT_SLOT]: kernel.nil});
  await images.putObject(imageId, {
    id: namespace.record.id,
    shape: onV1 ? objectRef(imageId, NAMESPACE_SHAPE_ID) : namespace.record.shape,
    behavior: namespace.record.behavior,
    slots,
    indexed: encodePairs(entries),
    metadata: namespace.record.metadata,
  }, {expectedVersion: namespace.record._version});
}

// The trusted management seam. None of this is Smalltalk protocol.
//
// `publish` is retry-safe in the way an installer needs: a binding that already exists keeps the
// value it has. Re-running an installer must not undo a legitimate rebind — the current value has
// its own lifecycle now, and only `rebind` is allowed to change it.
async function publishGlobal({images, imageId, name, bindingId, value, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(name, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});

  // Preflight, before anything is created. Checking the mapping only after minting the candidate
  // would leave an orphan GlobalBinding behind on every rejected publication.
  const mapped = namespace.entries.get(name);
  if (mapped) {
    if (mapped.objectId !== bindingId) {
      throw new SmalltalkGlobalConflictError(name, `is already bound to ${mapped.objectId}, not ${bindingId}`);
    }
    await assertIsBinding({images, imageId, name, binding: mapped});
    return objectRef(imageId, bindingId);
  }

  // SEED mode: the initial value is only a seed — a binding already there keeps the value it has
  // (re-running an installer must not undo a rebind) and a concurrent creator never overwrites.
  // The domain check that it IS a binding runs on created and adopted records alike.
  await ensureObject(images, imageId, {
    id: bindingId,
    shape: objectRef(imageId, GLOBAL_BINDING_SHAPE_ID),
    behavior: objectRef(imageId, GLOBAL_BINDING_CLASS_ID),
    slots: {[GLOBAL_BINDING_VALUE_SLOT]: value},
    metadata: {},
  }, {seed: true});
  await assertIsBinding({images, imageId, name, binding: objectRef(imageId, bindingId)});

  const entries = new Map(namespace.entries);
  entries.set(name, objectRef(imageId, bindingId));
  await writeMapping({images, imageId, namespace, entries});
  return objectRef(imageId, bindingId);
}

async function resolveGlobal({images, imageId, name, namespaceId = NAMESPACE_OBJECT_ID}) {
  const namespace = await findNamespace({images, imageId, namespaceId});
  return namespace?.entries.get(name) ?? null;
}

// ADR 0061 / ADR 0097: re-export an existing GlobalBinding from `fromNamespaceId` into
// `toNamespaceId` (optionally under alias `as`), sharing the identical GlobalBinding object
// without creating a second GlobalBinding record.
async function reexportGlobal({
  images,
  imageId,
  name,
  fromNamespaceId = NAMESPACE_OBJECT_ID,
  toNamespaceId,
  as = name,
} = {}) {
  requiredText(imageId, 'image id');
  requiredText(name, 'global name');
  requiredText(fromNamespaceId, 'source namespace id');
  requiredText(toNamespaceId, 'target namespace id');
  requiredText(as, 'target global name');

  const sourceNamespace = await requireNamespace({images, imageId, namespaceId: fromNamespaceId});
  const binding = sourceNamespace.entries.get(name);
  if (!binding) {
    throw new SmalltalkGlobalConflictError(name, `is not published in ${fromNamespaceId}`);
  }
  await assertIsBinding({images, imageId, name, binding});

  const targetNamespace = await requireNamespace({images, imageId, namespaceId: toNamespaceId});
  const existing = targetNamespace.entries.get(as);
  if (existing) {
    if (existing.objectId !== binding.objectId) {
      throw new SmalltalkGlobalConflictError(as, `is already bound to ${existing.objectId}, not ${binding.objectId}`);
    }
    await assertIsBinding({images, imageId, name: as, binding: existing});
    return binding;
  }

  const entries = new Map(targetNamespace.entries);
  entries.set(as, binding);
  await writeMapping({images, imageId, namespace: targetNamespace, entries});
  return binding;
}

async function reexportGlobals({
  images,
  imageId,
  names,
  fromNamespaceId = NAMESPACE_OBJECT_ID,
  toNamespaceId,
} = {}) {
  requiredText(imageId, 'image id');
  requiredText(fromNamespaceId, 'source namespace id');
  requiredText(toNamespaceId, 'target namespace id');
  if (!Array.isArray(names) || names.length === 0) throw new TypeError('names must be a non-empty array');
  const reexported = {};
  for (const name of names) {
    reexported[name] = await reexportGlobal({images, imageId, name, fromNamespaceId, toNamespaceId});
  }
  return Object.freeze(reexported);
}

// Changes the value on a stable identity. Already-compiled code observes it because it holds the
// binding, not the value.
async function rebindGlobal({images, imageId, bindingId, value}) {
  requiredText(bindingId, 'global binding id');
  const record = await images.getObject(imageId, bindingId);
  if (!record) throw new TypeError(`no global binding ${imageId}/${bindingId}`);
  await assertIsBinding({images, imageId, name: bindingId, binding: objectRef(imageId, bindingId)});
  const current = record.slots?.[GLOBAL_BINDING_VALUE_SLOT];
  if (canonicalRecordJson(current) === canonicalRecordJson(value)) return objectRef(imageId, bindingId);
  await images.putObject(imageId, {
    id: bindingId,
    shape: record.shape,
    behavior: record.behavior,
    slots: {[GLOBAL_BINDING_VALUE_SLOT]: value},
    metadata: record.metadata,
  }, {expectedVersion: record._version});
  return objectRef(imageId, bindingId);
}

// The same binding under a new name: identity survives, so compiled code is unaffected. The caller
// must name the identity it believes it is moving. That makes retry convergence part of the one API
// contract rather than an optional stronger mode: after a lost acknowledgement, the retry succeeds
// only when that same identity is already at the destination.
async function renameGlobal({images, imageId, from, to, bindingId, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(from, 'global name');
  requiredText(to, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});
  const binding = namespace.entries.get(from);
  const target = namespace.entries.get(to);

  if (!binding) {
    if (target && target.objectId === bindingId) return target;
    if (target) {
      throw new SmalltalkGlobalConflictError(to, `is bound to ${target.objectId}, not ${bindingId}`);
    }
    throw new SmalltalkGlobalConflictError(from, 'is not published');
  }
  if (binding.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(from, `is bound to ${binding.objectId}, not ${bindingId}`);
  }
  if (target && target.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(to, `is already bound to ${target.objectId}`);
  }
  // The desired mapping already exists to the expected binding: an ensure-style no-op.
  if (target && from === to) return binding;
  const entries = new Map(namespace.entries);
  entries.delete(from);
  entries.set(to, binding);
  await writeMapping({images, imageId, namespace, entries});
  return binding;
}

// Withdraws a *name*, but only for the identity the caller names. The binding object stays, so code
// already holding it keeps working. Identity is required for the same ABA reason as rename: if a
// removal commits, its acknowledgement is lost, and another actor republishes the same spelling to a
// different binding, the original retry must conflict rather than delete the new binding.
async function removeGlobal({images, imageId, name, bindingId, namespaceId = NAMESPACE_OBJECT_ID}) {
  requiredText(name, 'global name');
  requiredText(bindingId, 'global binding id');
  const namespace = await requireNamespace({images, imageId, namespaceId});
  const mapped = namespace.entries.get(name);
  if (!mapped) return false;
  if (mapped.objectId !== bindingId) {
    throw new SmalltalkGlobalConflictError(name, `is bound to ${mapped.objectId}, not ${bindingId}`);
  }
  const entries = new Map(namespace.entries);
  entries.delete(name);
  await writeMapping({images, imageId, namespace, entries});
  return true;
}

// ADR 0061: create a nested namespace. Same Shape and protocol as the root, at a caller-chosen id,
// with a parent edge (defaulting to the root). Exact-or-create: re-creating the same namespace with
// the same parent is a no-op; a conflict on id or parent is loud. The parent must exist and be a
// namespace. A fresh node cannot already be on a cycle, so the only self-cycle to refuse is
// parent === self.
async function createNamespace({images, imageId, namespaceId, parent = NAMESPACE_OBJECT_ID}) {
  requiredText(imageId, 'image id');
  requiredText(namespaceId, 'namespace id');
  requiredText(parent, 'parent namespace id');
  if (namespaceId === parent) {
    throw new SmalltalkNamespaceError(imageId, `a namespace cannot be its own parent: ${namespaceId}`);
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  // The parent must be a real namespace; this also validates the root exists for a default parent.
  await requireNamespace({images, imageId, namespaceId: parent});
  // SEED mode: the empty mapping is only the initial value (the namespace fills afterwards under
  // its own CAS), so a present or concurrently created namespace is adopted; the domain check —
  // same namespace, same parent — runs on whatever came back, created, present or won by a race.
  await ensureObject(images, imageId, {
    id: namespaceId,
    shape: objectRef(imageId, NAMESPACE_SHAPE_ID),
    behavior: null,
    slots: {[NAMESPACE_PARENT_SLOT]: objectRef(imageId, parent)},
    indexed: [],
    metadata: {protocol: SMALLTALK_GLOBAL_NAMESPACE_V1},
  }, {seed: true});
  const found = await findNamespace({images, imageId, namespaceId});
  const foundParent = found.parent?.objectId ?? null;
  if (foundParent !== parent) {
    throw new SmalltalkGlobalConflictError(
      namespaceId,
      `already exists with parent ${foundParent ?? 'none'}, not ${parent}`,
    );
  }
  return objectRef(imageId, namespaceId);
}

// ADR 0061: (re)set a namespace's parent. Refuses to close a cycle: walking the proposed parent's
// chain to the root must not pass through this namespace. Identity-scoped by CAS on the record
// version, like the mapping writes.
async function setNamespaceParent({images, imageId, namespaceId, parent}) {
  requiredText(imageId, 'image id');
  requiredText(namespaceId, 'namespace id');
  requiredText(parent, 'parent namespace id');
  if (namespaceId === parent) {
    throw new SmalltalkNamespaceError(imageId, `a namespace cannot be its own parent: ${namespaceId}`);
  }
  const namespace = await requireNamespace({images, imageId, namespaceId});
  // The proposed parent must be a namespace, and reaching the root from it must not pass through
  // this namespace — that is the cycle.
  const visited = new Set();
  let cursor = parent;
  for (;;) {
    if (cursor === namespaceId) {
      throw new SmalltalkNamespaceError(
        imageId,
        `setting the parent of ${namespaceId} to ${parent} would close a cycle`,
      );
    }
    if (visited.has(cursor)) {
      throw new SmalltalkNamespaceError(imageId, `the proposed parent chain already has a cycle at ${cursor}`);
    }
    visited.add(cursor);
    const ancestor = await findNamespace({images, imageId, namespaceId: cursor});
    if (!ancestor) throw new SmalltalkNamespaceError(imageId, `the proposed parent ${cursor} is not a namespace`);
    if (!ancestor.parent) break;
    cursor = ancestor.parent.objectId;
  }
  // Gaining or changing a parent edge requires the v2 Shape (v1 has no parent slot): migrate a v1
  // record as part of the same write, honoring ADR 0002 immutability.
  const onV1 = isLocalRef(namespace.record.shape, imageId, NAMESPACE_SHAPE_ID_V1);
  const slots = {
    ...(onV1 ? {} : (namespace.record.slots ?? {})),
    [NAMESPACE_PARENT_SLOT]: objectRef(imageId, parent),
  };
  await images.putObject(imageId, {
    id: namespace.record.id,
    shape: onV1 ? objectRef(imageId, NAMESPACE_SHAPE_ID) : namespace.record.shape,
    behavior: namespace.record.behavior,
    slots,
    indexed: namespace.record.indexed,
    metadata: namespace.record.metadata,
  }, {expectedVersion: namespace.record._version});
  return objectRef(imageId, namespaceId);
}

// Name -> binding id, for the compiler. Transient: it is read per compilation and never stored.
//
// ADR 0061: resolution walks the parent chain from `namespaceId` outward to the root, and a nearer
// namespace's name shadows a farther one's (inner-wins). The walk is the compile-time lookup the
// ADR describes; the artifact the compiler produces still carries only binding ids, never a path.
// The chain is acyclic by construction (the management seam refuses a cycle-closing parent), but
// the walk defends itself anyway: a corrupted cycle is a namespace error, never a silent loop.
async function globalDeclarations({images, imageId, namespaceId = NAMESPACE_OBJECT_ID}) {
  const merged = new Map();
  const visited = new Set();
  let currentId = namespaceId;
  // Walk outward, recording which names are already claimed by a nearer namespace. First writer
  // wins, so a child name is never overwritten by its parent's.
  for (;;) {
    if (visited.has(currentId)) {
      throw new SmalltalkNamespaceError(imageId, `the namespace parent chain has a cycle at ${currentId}`);
    }
    visited.add(currentId);
    const namespace = await findNamespace({images, imageId, namespaceId: currentId});
    if (!namespace) {
      // A missing namespace is only legal as the caller's own starting point being absent — an
      // image with no globals at all. A parent that points nowhere is a dangling edge = corrupt.
      if (currentId === namespaceId && currentId === NAMESPACE_OBJECT_ID) return {};
      throw new SmalltalkNamespaceError(imageId, `the namespace ${currentId} named in a parent chain does not exist`);
    }
    for (const [name, binding] of namespace.entries) {
      if (!merged.has(name)) merged.set(name, binding.objectId);
    }
    if (!namespace.parent) return Object.fromEntries(merged);
    currentId = namespace.parent.objectId;
  }
}

export {
  GLOBAL_BINDING_CLASS_ID,
  GLOBAL_BINDING_SHAPE_ID,
  GLOBAL_BINDING_VALUE_SLOT,
  NAMESPACE_OBJECT_ID,
  NAMESPACE_PARENT_SLOT,
  NAMESPACE_SHAPE_ID,
  NAMESPACE_SHAPE_ID_V1,
  SMALLTALK_GLOBAL_NAMESPACE_V1,
  SmalltalkGlobalConflictError,
  SmalltalkNamespaceError,
  createNamespace,
  findNamespace,
  findSmalltalkGlobalNamespace,
  globalBindingId,
  globalDeclarations,
  installSmalltalkGlobalNamespace,
  publishGlobal,
  publishSmalltalkClassGlobals,
  rebindGlobal,
  reexportGlobal,
  reexportGlobals,
  removeGlobal,
  renameGlobal,
  resolveGlobal,
  setNamespaceParent,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {ensureShape} from '../graph/ensure-records.js';
import {integerValue, objectRef, textValue} from '../value/index.js';
import {
  assertMethodLane,
  defineClass,
  defineMethods,
  ensureBlock,
  ensureCodeArtifact,
} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  SmalltalkKernelConflictError,
  findSmalltalkKernel,
  readBehavior,
} from './smalltalk-kernel.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {sameRef} from './smalltalk-lookup.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0047 is intentionally post-bootstrap, like allocation and control flow. The kernel remains
// identity-only; Array is the first ordinary class whose instance Shape has an indexed part.
const ARRAY_INSTANCE_SHAPE_ID = 'smalltalk/array-instance-shape/v1';
const ARRAY_CLASS_ID = 'smalltalk/class/Array';
const ARRAY_METACLASS_ID = 'smalltalk/metaclass/Array';

const INDEXED_PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED]: 'smalltalk/primitive/basic-new-sized',
  [SMALLTALK_PRIMITIVE.INDEXED_SIZE]: 'smalltalk/primitive/indexed-size',
  [SMALLTALK_PRIMITIVE.INDEXED_AT]: 'smalltalk/primitive/indexed-at',
  [SMALLTALK_PRIMITIVE.INDEXED_AT_PUT]: 'smalltalk/primitive/indexed-at-put',
});

const CAPTURE = Object.freeze({
  [SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED],
    name: 'primitiveBasicNewSized',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_SIZE]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_SIZE],
    name: 'primitiveIndexedSize',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_AT]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_AT],
    name: 'primitiveIndexedAt',
  }),
  [SMALLTALK_PRIMITIVE.INDEXED_AT_PUT]: Object.freeze({
    id: INDEXED_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT],
    name: 'primitiveIndexedAtPut',
  }),
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

const parameter = (id, name = id) => ({id, name});
const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

const oneBasedToZeroBased = (expression) => ({
  op: 'integer-add',
  left: expression,
  right: {op: 'literal', value: integerValue(-1)},
});

function primitiveSend(capture, args) {
  return {
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: {op: 'binding', id: capture.id},
    message: textValue('value:'.repeat(args.length)),
    arguments: args,
  };
}

function methodProgram(parameters, capture, body) {
  return {
    parameters,
    captures: capture ? [{...capture}] : [],
    body,
  };
}

function capturedMethod(selector, parameters, capture, args) {
  return {
    selector,
    program: methodProgram(parameters, capture, primitiveSend(capture, args)),
    captures: [{...capture, value: null}],
  };
}

async function ensureArrayShape(images, imageId) {
  const desired = {id: ARRAY_INSTANCE_SHAPE_ID, slots: [], indexed: SHAPE_INDEXED.VALUES};
  const shape = await ensureShape(images, imageId, desired, {conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id)});
  return shape;
}

function requireSameRef(actual, expected, imageId) {
  if (!sameRef(actual, expected)) throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID);
}

async function ensureArrayClass({images, imageId, kernel, shapeRef}) {
  const classRef = objectRef(imageId, ARRAY_CLASS_ID);
  const metaclassRef = objectRef(imageId, ARRAY_METACLASS_ID);
  const existing = await images.getObject(imageId, ARRAY_CLASS_ID);
  if (!existing) {
    return await defineClass({
      images,
      imageId,
      name: 'Array',
      superclassRef: kernel.objectClass,
      instanceShapeRef: shapeRef,
    });
  }

  // Once the class record exists, defineClass completed all four class-graph writes. Calling it
  // again after methods have begun to publish would wrongly demand that the method dictionaries be
  // empty again. Rediscovery therefore validates only the immutable class definition and leaves
  // method dictionaries to defineMethods, which has its own retry-safe exactness contract.
  let behavior;
  let metaclass;
  try {
    behavior = await readBehavior(images, classRef);
    metaclass = await readBehavior(images, metaclassRef);
  } catch (error) {
    throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID, {cause: error});
  }
  if (behavior.name.value !== 'Array' || metaclass.name.value !== 'Array class') {
    throw new SmalltalkKernelConflictError('class', imageId, ARRAY_CLASS_ID);
  }
  requireSameRef(behavior.record.behavior, metaclassRef, imageId);
  requireSameRef(behavior.superclass, kernel.objectClass, imageId);
  requireSameRef(behavior.instanceShape, shapeRef, imageId);

  const objectBehavior = await readBehavior(images, kernel.objectClass);
  requireSameRef(metaclass.record.behavior, kernel.metaclassClass, imageId);
  requireSameRef(metaclass.superclass, objectBehavior.record.behavior, imageId);
  requireSameRef(metaclass.instanceShape, kernel.nil, imageId);
  return Object.freeze({classRef, metaclassRef});
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = INDEXED_PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

function bindCapture(method, imageId) {
  if (!method.captures) return method;
  return {
    ...method,
    captures: method.captures.map((entry) => ({
      ...entry,
      value: objectRef(imageId, entry.id),
    })),
  };
}

function protocolFor({kernel, arrayClass, imageId}) {
  const basicNewSized = CAPTURE[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED];
  const indexedSize = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_SIZE];
  const indexedAt = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_AT];
  const indexedAtPut = CAPTURE[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT];
  const index = oneBasedToZeroBased(argument(0));

  return [
    {
      classRef: kernel.classClass,
      methods: [bindCapture(capturedMethod(
        'basicNew:',
        [parameter('size')],
        basicNewSized,
        [receiver(), argument(0)],
      ), imageId)],
    },
    {
      classRef: arrayClass.metaclassRef,
      methods: [{
        selector: 'new:',
        program: methodProgram(
          [parameter('size')],
          null,
          {
            op: 'send',
            languageId: SYMMETRIC_SMALLTALK_ID,
            receiver: receiver(),
            message: textValue('basicNew:'),
            arguments: [argument(0)],
          },
        ),
      }],
    },
    {
      classRef: arrayClass.classRef,
      methods: [
        bindCapture(capturedMethod('size', [], indexedSize, [receiver()]), imageId),
        bindCapture(capturedMethod('at:', [parameter('index')], indexedAt, [receiver(), index]), imageId),
        bindCapture(capturedMethod(
          'at:put:',
          [parameter('index'), parameter('value')],
          indexedAtPut,
          [receiver(), index, argument(1)],
        ), imageId),
      ],
    },
  ];
}

async function installSmalltalkIndexedProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Deterministic publication order makes a partial run recoverable by replaying the installer:
  // layout -> class graph -> primitive Blocks -> ordinary methods.
  const shape = await ensureArrayShape(images, imageId);
  const arrayClass = await ensureArrayClass({
    images,
    imageId,
    kernel,
    shapeRef: objectRef(imageId, shape.id),
  });

  const primitives = {};
  for (const primitive of [
    SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED,
    SMALLTALK_PRIMITIVE.INDEXED_SIZE,
    SMALLTALK_PRIMITIVE.INDEXED_AT,
    SMALLTALK_PRIMITIVE.INDEXED_AT_PUT,
  ]) {
    primitives[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }

  for (const {classRef, methods} of protocolFor({kernel, arrayClass, imageId})) {
    await defineMethods({images, compilation, imageId, classRef, methods, lane});
  }

  return Object.freeze({
    arrayClass: arrayClass.classRef,
    arrayMetaclass: arrayClass.metaclassRef,
    arrayInstanceShape: objectRef(imageId, shape.id),
    basicNewSizedPrimitive: primitives[SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED],
    indexedSizePrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_SIZE],
    indexedAtPrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_AT],
    indexedAtPutPrimitive: primitives[SMALLTALK_PRIMITIVE.INDEXED_AT_PUT],
  });
}

// `do:` for Array, installed as a separate post-Block/Integer step because it
// composes the indexed primitives with the Block enumeration loop (which is not
// yet installed when `installSmalltalkIndexedProtocol` runs). A general
// collection protocol the upstream MessagePack encoder needs (`writeArray:`
// sends `array do:`); Array is a kernel class outside the `Collection`
// hierarchy, so it does not inherit the library's `Collection do:`.
const ARRAY_ENUMERATION_METHODS = Object.freeze([
  // `first`, measured Cuis `SequenceableCollection>>first` (`^self at: 1`), required by the
  // imported Life code (`set:at:` reads `pattern first size`, bead lagrange-images-nfv1.3).
  // The out-of-range case stays the measured one: an empty collection refuses at `at:`.
  {selector: 'first', source: '[ ^ self at: 1 ]'},
  // Fill preserves the receiver and its length. The loop bound is read once, and indexed
  // writes retain the supplied Value/ref exactly; no bulk storage or copying rule lives here.
  {selector: 'atAllPut:', source: '[ :anObject | 1 to: self size do: [:index | self at: index put: anObject]. self ]'},
  {
    selector: 'do:',
    source: `[ :aBlock | | index |
      index := 1.
      [ index <= self size ] whileTrue: [
        aBlock value: (self at: index).
        index := index + 1 ] ]`,
  },
]);

async function installSmalltalkArrayEnumerationProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  await defineMethodsFromSource({
    images, compilation, imageId, lane,
    classRef: objectRef(imageId, ARRAY_CLASS_ID),
    methods: ARRAY_ENUMERATION_METHODS,
  });
  return Object.freeze({protocol: 'smalltalk-array-enumeration/v1'});
}

export {
  ARRAY_INSTANCE_SHAPE_ID,
  CAPTURE as SMALLTALK_INDEXED_CAPTURE,
  INDEXED_PRIMITIVE_BLOCK_ID as SMALLTALK_INDEXED_PRIMITIVE_BLOCK_ID,
  installSmalltalkArrayEnumerationProtocol,
  installSmalltalkIndexedProtocol,
};

import {objectRef, textValue} from '../value/index.js';
import {
  defineMethods,
  reconcileMethods,
  ensureBlock,
  ensureCodeArtifact,
} from './smalltalk-class-builder.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {globalDeclarations} from './smalltalk-globals.js';
import {classVariableDeclarations} from './smalltalk-class-variables.js';
import {visibleInstanceShape} from './smalltalk-lookup.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {
  INSTANCE_SLOT_READ_CAPTURE,
  ARRAY_BINDING_ID,
  CHARACTER_BINDING_ID,
  NIL_BINDING_ID,
  NIL_CAPTURE,
  NON_LOCAL_RETURN_CAPTURE,
  INSTANCE_SLOT_WRITE_CAPTURE,
  SUPER_SEND_CAPTURE,
  SYMBOL_BINDING_ID,
  compileSymmetricSmalltalkSemanticBlock,
} from './symmetric-smalltalk-semantic.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0050: the class-scoped compilation entry point, and the primitive Blocks it binds against.
//
// This is a *sibling* of `compileSymmetricSmalltalkSemanticBlock`, not a stage above it. That
// compiler already resolves names and already rejects an unbound root name at that moment, so there
// is no later point where an unresolved name survives for someone else to bind. The class arrives as
// an argument, exactly as `captures` already does, and the Block compiler is untouched.
const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ]: 'smalltalk/primitive/instance-slot-read',
  [SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE]: 'smalltalk/primitive/instance-slot-write',
  // ADR 0055. `^` lowers to a send to this, bound through the same seam and reserved the same way.
  [SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN]: 'smalltalk/primitive/non-local-return',
  // ADR 0089. `super <selector>` lowers to a send to this, through the same seam again. It belongs
  // to the CLASS-SCOPED binder rather than to the Block compiler for the same reason `^` does: a
  // super send starts above the DEFINING Behavior of a method, so a compilation with no method home
  // has nothing to start above.
  [SMALLTALK_PRIMITIVE.SUPER_SEND]: 'smalltalk/primitive/super-send',
});

// Owned by the class-scoped binder, which injects them for instance-variable access and for `^`.
const RESERVED_CAPTURE_NAMES = new Set([
  INSTANCE_SLOT_READ_CAPTURE, INSTANCE_SLOT_WRITE_CAPTURE, NON_LOCAL_RETURN_CAPTURE, NIL_CAPTURE,
  SUPER_SEND_CAPTURE,
]);
// The nil binding id joins the primitive ids: reserving a name without its id would let a caller
// bind the same id under a different name and shadow the intrinsic from outside the compiler.
const RESERVED_CAPTURE_IDS = new Set([...Object.values(PRIMITIVE_BLOCK_ID), NIL_BINDING_ID]);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkInstanceVariableProtocol({images, imageId} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const installed = {};
  for (const primitive of Object.keys(PRIMITIVE_BLOCK_ID)) {
    installed[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }
  return Object.freeze({
    readPrimitive: installed[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ],
    writePrimitive: installed[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE],
    nonLocalReturnPrimitive: installed[SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN],
    superSendPrimitive: installed[SMALLTALK_PRIMITIVE.SUPER_SEND],
  });
}

// name -> stable slot id, for the names a method of this class may see. The *name* lives here and in
// the Shape; the compiled method carries only the id (ADR 0050 decision 2), which is why a rename
// that preserves the id leaves existing methods working.
async function instanceVariableBindings({images, imageId, classRef} = {}) {
  requiredText(imageId, 'image id');
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  // The same strict walk the runtime permission check uses, so the binder cannot offer a name
  // the primitive would then refuse, and neither can report corruption as an unbound name.
  const shape = await visibleInstanceShape({images, behaviorRef: classRef, nilRef: kernel.nil});
  if (!shape) return Object.freeze({});
  const bindings = {};
  for (const {id, name} of shape.slots) {
    if (Object.hasOwn(bindings, name)) {
      throw new TypeError(`instance shape ${shape.id} declares duplicate slot name: ${name}`);
    }
    bindings[name] = id;
  }
  return Object.freeze(bindings);
}

// A method may capture named values, exactly as a Block may. This is how a method names anything
// that is not a parameter, temporary or instance variable — a class, for instance, since source has
// no global namespace: `Array` is a captured ref, not a resolvable global.
//
// Compilation and installation are kept apart. What the *compiler* needs is a declaration — a name
// bound to a stable capture id — and it answers the program's capture list. Every declaration is in
// that list, referenced or not. Binding values is installation's job, because a value is per image
// while a declaration is not.
//
// Two forms are accepted and both mean the same thing to the compiler:
//
//   {name: captureId}                  a declaration map
//   [{name, id, value?}]               declarations, optionally carrying installation values
//
// Duplicates are refused in either form rather than resolved by position. A repeated name would make
// the meaning of that name in source depend on declaration order, and a repeated id would collapse
// two declarations into one binding — the same first-wins defect this substrate rejects everywhere.
function normalizeCaptureDeclarations(captures) {
  const entries = Array.isArray(captures)
    ? captures.map((entry) => {
      if (!entry || typeof entry !== 'object') throw new TypeError('a capture declaration must be an object');
      return {name: entry.name, id: entry.id, value: entry.value};
    })
    : Object.entries(captures ?? {}).map(([name, id]) => ({name, id, value: undefined}));

  const names = new Set();
  const ids = new Set();
  for (const entry of entries) {
    requiredText(entry.name, 'capture name');
    requiredText(entry.id, 'capture id');
    // The binder adds its own captures for the slot primitives, and they are spread *after* the
    // caller's — so a colliding declaration would be silently replaced, value and all, which is
    // exactly what the uniform capture contract is supposed to prevent. Refuse instead.
    if (RESERVED_CAPTURE_NAMES.has(entry.name)) {
      throw new TypeError(`capture name ${entry.name} is reserved for instance-variable access`);
    }
    if (RESERVED_CAPTURE_IDS.has(entry.id)) {
      throw new TypeError(`capture id ${entry.id} is reserved for instance-variable access`);
    }
    if (names.has(entry.name)) throw new TypeError(`method declares capture name ${entry.name} twice`);
    if (ids.has(entry.id)) throw new TypeError(`method declares capture id ${entry.id} twice`);
    names.add(entry.name);
    ids.add(entry.id);
  }
  return entries;
}

// The class-scoped entry point: parse -> compile *with the defining class* -> semantic program.
async function compileSymmetricSmalltalkMethod({
  images,
  imageId,
  classRef,
  selector,
  source,
  captures = {},
  // ADR 0057: the caller's namespace snapshot, where it has one. Reading it again here would let a
  // rename or removal between the two reads change what a batch of methods meant.
  globals: suppliedGlobals = null,
  // ADR 0061: which namespace this method compiles in, when no snapshot is supplied. Defaults to
  // the root, preserving ADR 0057 for existing callers.
  namespaceId,
} = {}) {
  requiredText(selector, 'selector');
  const declared = normalizeCaptureDeclarations(captures);
  const instanceVariables = await instanceVariableBindings({images, imageId, classRef});
  // The primitives arrive as ordinary root captures, so an instance-variable reference lowers to an
  // ordinary send and nothing downstream of the compiler learns a new concept. They are added only
  // when the source actually names an instance variable, so a method that uses none carries none.
  // One namespace snapshot per batch, supplied by the caller where there is one: reading it twice
  // would let a rename or removal between the reads change what compilation meant.
  const globals = suppliedGlobals ?? await globalDeclarations({images, imageId, namespaceId});
  const compiled = compileSymmetricSmalltalkSemanticBlock(source, {
    globals,
    captures: {
      ...Object.fromEntries(declared.map(({name, id}) => [name, id])),
      [INSTANCE_SLOT_READ_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ],
      [INSTANCE_SLOT_WRITE_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE],
    },
    // ADR 0055: made *available* rather than declared. A declaration becomes a program capture
    // whether or not the source references it, so declaring this eagerly would give every method a
    // dependency it may never use. The lowering requests it on first `^`, which needs no second
    // inspection of the source.
    intrinsics: {
      [NON_LOCAL_RETURN_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.NON_LOCAL_RETURN],
      // ADR 0089, offered on exactly the same terms: made available rather than declared, so a
      // method that never writes `super` carries no binding for it.
      [SUPER_SEND_CAPTURE]: PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.SUPER_SEND],
      // `nil` is deliberately absent: the semantic compiler owns that intrinsic and offers it to
      // every compilation, so declaring it here would be a second definition to keep in step.
    },
    instanceVariables,
    // This entry point is the class-scoped one, so its compilations have a method to return from.
    methodHome: true,
    classVariables: await classVariableDeclarations({images, imageId, classRef}),
  });

  // Every declaration becomes a program capture, referenced or not — that is the block compiler's
  // existing behaviour for root captures and this path does not change it. What is returned is the
  // program's own capture list, in its own order, with no values: this is compilation, and a value
  // is an installation concern.
  return Object.freeze({
    selector,
    program: compiled.program,
    representation: compiled.representation,
    instanceVariables,
    captures: compiled.program.captures.map(({id, name}) => Object.freeze({id, name})),
    // Transient provenance: which of those captures are globals this compilation resolved.
    globalBindingIdsUsed: compiled.globalBindingIdsUsed,
    // Transient provenance: which of those captures are class variables this compilation resolved.
    classVariableBindingIdsUsed: compiled.classVariableBindingIdsUsed,
  });
}

// Compile methods from source against their defining class and install them. This is where a
// capture declaration acquires its value: the slot primitives resolve to their well-known Blocks in
// this image, and anything else must have been supplied by the caller.
async function methodsFromSource({
  images, compilation, imageId, classRef, methods, lane, namespaceId, retainSource = false, install,
}) {
  if (!Array.isArray(methods) || methods.length === 0) throw new TypeError('methods must be a non-empty array');
  if (typeof retainSource !== 'boolean') throw new TypeError('retainSource must be a boolean');
  const primitiveIds = new Set(Object.values(PRIMITIVE_BLOCK_ID));
  // Resolved once: `nil` means this image's kernel nil, and a method that never writes it carries
  // no binding to resolve.
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const kernelNil = kernel.nil;
  // One snapshot for the whole batch, used for compilation and nothing else. Global captures are
  // identified by *provenance* below, never by testing an id against this map. ADR 0061: the
  // namespace the batch compiles in, defaulting to the root.
  const globals = await globalDeclarations({images, imageId, namespaceId});
  const compiled = [];
  for (const {selector, source, captures, expectedCurrent, retainSource: entryRetainSource, category, provenance} of methods) {
    if (entryRetainSource !== undefined && typeof entryRetainSource !== 'boolean') {
      throw new TypeError(`method ${selector} retainSource must be a boolean`);
    }
    const shouldRetainSource = entryRetainSource ?? retainSource;
    const declared = normalizeCaptureDeclarations(captures ?? {});
    const supplied = new Map(declared.map(({id, value}) => [id, value]));
    const method = await compileSymmetricSmalltalkMethod({
      images, imageId, classRef, selector, source, captures, globals,
    });
    // Exactly what this method resolved as a global or class variable — so an explicit capture
    // keeps its caller's value even when its id happens to equal a published binding id.
    const resolvedGlobals = new Set(method.globalBindingIdsUsed ?? []);
    const resolvedClassVars = new Set(method.classVariableBindingIdsUsed ?? []);
    const bound = method.captures.map(({id, name}) => {
      if (primitiveIds.has(id)) return {id, name, value: objectRef(imageId, id)};
      // ADR 0056: the nil intrinsic resolves to this image's kernel nil, exactly as the slot
      // primitives resolve to this image's Blocks.
      if (id === NIL_BINDING_ID) return {id, name, value: kernelNil};
      // The symbol intrinsic binds to the image-local interner primitive Block.
      if (id === SYMBOL_BINDING_ID) return {id, name, value: objectRef(imageId, 'smalltalk/primitive/symbol-intern')};
      // Character literals use the image-local interner primitive. The semantic artifact carries
      // only the code point; the image-specific ref enters at method installation.
      if (id === CHARACTER_BINDING_ID) {
        return {id, name, value: objectRef(imageId, 'smalltalk/primitive/character-intern')};
      }
      // The array intrinsic binds to this image's Array class (for the `#()` empty literal).
      if (id === ARRAY_BINDING_ID) return {id, name, value: objectRef(imageId, 'smalltalk/class/Array')};
      // ADR 0057: a resolved global binds to that binding object in *this* image. The artifact
      // carried only the id; the ref appears here, at installation.
      if (resolvedGlobals.has(id)) return {id, name, value: objectRef(imageId, id)};
      // A resolved class variable binds to the ClassVariableBinding object in this image.
      if (resolvedClassVars.has(id)) return {id, name, value: objectRef(imageId, id)};
      const value = supplied.get(id);
      if (value === undefined) {
        throw new TypeError(
          `method ${selector} declares capture ${name} without a value; every declared capture `
          + 'becomes a binding in the installed method, so installation needs a value for each',
        );
      }
      return {id, name, value};
    });
    // Pass-through, not policy: `expectedCurrent` is the caller's observed binding and the class
    // builder owns entirely what it means. Compilation neither reads it nor is affected by it, and
    // dropping it here would silently turn a guarded replacement into an unguarded one.
    compiled.push({
      selector: method.selector,
      program: method.program,
      captures: bound,
      ...(shouldRetainSource ? {source} : {}),
      ...(category !== undefined ? {category} : {}),
      ...(provenance !== undefined ? {provenance} : {}),
      ...(expectedCurrent === undefined ? {} : {expectedCurrent}),
    });
  }
  return await install({images, compilation, imageId, classRef, lane, methods: compiled});
}

// DEFINITION is unchanged, deliberately (bead lagrange-images-it3). Defining a method is add-only
// and can carry no `expectedCurrent` at all — the class builder refuses one there — so there is no
// observed revision whose lane could be preserved, and the neutral default it has always had stays
// spelled right here.
async function defineMethodsFromSource(options = {}) {
  return await methodsFromSource({...options, lane: options.lane ?? 'neutral', install: defineMethods});
}

// RECONCILIATION is the one line bead lagrange-images-it3 changes, and it changes only what happens
// when the caller named NO lane. Spelling `?? 'neutral'` here made "no lane named" indistinguishable
// from "neutral named" by the time it reached the installer, so a REPLACEMENT guarded by a WASM
// revision was silently recompiled into the neutral lane. The lane now travels as the caller wrote
// it — including not at all — to the class builder, which owns the default, the derivation and the
// refusals in one place. A caller that DOES name a lane still gets exactly the lane it named, and an
// unguarded reconciliation that names none still gets neutral: neither path changes.
async function reconcileMethodsFromSource(options = {}) {
  return await methodsFromSource({...options, lane: options.lane, install: reconcileMethods});
}

export {
  PRIMITIVE_BLOCK_ID as SMALLTALK_INSTANCE_SLOT_PRIMITIVE_BLOCK_ID,
  compileSymmetricSmalltalkMethod,
  defineMethodsFromSource,
  reconcileMethodsFromSource,
  installSmalltalkInstanceVariableProtocol,
  instanceVariableBindings,
};

import {booleanValue, objectRef, textValue} from '../value/index.js';
import {assertMethodLane, defineMethods, ensureBlock, ensureCodeArtifact, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {resolveGlobal} from './smalltalk-globals.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0053: Integer ordering and arithmetic, installed as ordinary methods over language-owned
// primitives. `lagrange-code/v0` stays frozen — no comparison op is added — and the compiler learns
// no selector: `<` is found by the same Behavior walk as `+` and `ifTrue:`.
//
// One comparison primitive, three derived methods. Four primitives would be four chances for the set
// to disagree, and a `>=` that parts company with `<` at exactly one boundary is the classic form of
// that bug.
const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN]: 'smalltalk/primitive/integer-less-than',
  [SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT]: 'smalltalk/primitive/integer-subtract',
  [SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY]: 'smalltalk/primitive/integer-multiply',
  [SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE]: 'smalltalk/primitive/integer-floor-divide',
  [SMALLTALK_PRIMITIVE.INTEGER_MODULO]: 'smalltalk/primitive/integer-modulo',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_AND]: 'smalltalk/primitive/integer-bit-and',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_OR]: 'smalltalk/primitive/integer-bit-or',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR]: 'smalltalk/primitive/integer-bit-xor',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT]: 'smalltalk/primitive/integer-bit-shift',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN]: 'primitiveIntegerLessThan',
  [SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT]: 'primitiveIntegerSubtract',
  [SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY]: 'primitiveIntegerMultiply',
  [SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE]: 'primitiveIntegerFloorDivide',
  [SMALLTALK_PRIMITIVE.INTEGER_MODULO]: 'primitiveIntegerModulo',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_AND]: 'primitiveIntegerBitAnd',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_OR]: 'primitiveIntegerBitOr',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR]: 'primitiveIntegerBitXor',
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT]: 'primitiveIntegerBitShift',
});

const captureFor = (primitive) => Object.freeze({
  id: PRIMITIVE_BLOCK_ID[primitive],
  name: CAPTURE_NAME[primitive],
});

const RECEIVER = Object.freeze({op: 'receiver'});
const ARGUMENT = Object.freeze({op: 'argument', index: 0});

// `aPrimitive value: x value: y` — an ordinary Block send, which ADR 0044 decision 11 answers
// without a class. A method never *is* a primitive; it captures one and sends to it.
const applyPrimitive = (primitive, left, right) => ({
  op: 'send',
  languageId: SYMMETRIC_SMALLTALK_ID,
  receiver: {op: 'binding', id: PRIMITIVE_BLOCK_ID[primitive]},
  message: textValue('value:value:'),
  arguments: [left, right],
});

// ADR 0053 decision 2. `not` does not exist — ADR 0045 deferred it — and inventing it to spell two
// methods would be scope creep, so the negation lives inside these two installed programs using the
// neutral `if`. That is a lower-level semantic producer using the IR directly, which ADR 0045
// permits; what it forbids is Smalltalk *source* conditionals becoming compiler special cases.
const negated = (condition) => ({
  op: 'if',
  condition,
  then: {op: 'literal', value: booleanValue(false)},
  else: {op: 'literal', value: booleanValue(true)},
});

const LESS_THAN = SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN;

// The installed protocol, as it reads in Smalltalk:
//
//   Integer >> <   primitiveIntegerLessThan value: self value: other
//   Integer >> >   primitiveIntegerLessThan value: other value: self
//   Integer >> <=  (primitiveIntegerLessThan value: other value: self) not
//   Integer >> >=  (primitiveIntegerLessThan value: self  value: other) not
const INTEGER_METHODS = [
  {selector: '<', primitive: LESS_THAN, body: applyPrimitive(LESS_THAN, RECEIVER, ARGUMENT)},
  {selector: '>', primitive: LESS_THAN, body: applyPrimitive(LESS_THAN, ARGUMENT, RECEIVER)},
  {selector: '<=', primitive: LESS_THAN, body: negated(applyPrimitive(LESS_THAN, ARGUMENT, RECEIVER))},
  {selector: '>=', primitive: LESS_THAN, body: negated(applyPrimitive(LESS_THAN, RECEIVER, ARGUMENT))},
  {
    selector: '-',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT, RECEIVER, ARGUMENT),
  },
  {
    selector: '*',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY, RECEIVER, ARGUMENT),
  },
  {
    selector: '//',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE, RECEIVER, ARGUMENT),
  },
  {
    selector: '\\\\',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_MODULO,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_MODULO, RECEIVER, ARGUMENT),
  },
  // Workstream 3. Bitwise protocol, one method per primitive. These are the general Integer
  // operations upstream MessagePack reaches for (`bitOr:` in size headers, `bitAnd:`/`bitShift:` in
  // dialect byte extraction); nothing about them names MessagePack.
  {
    selector: 'bitAnd:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_AND,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_AND, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitOr:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_OR,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_OR, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitXor:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR, RECEIVER, ARGUMENT),
  },
  {
    selector: 'bitShift:',
    primitive: SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT,
    body: applyPrimitive(SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT, RECEIVER, ARGUMENT),
  },
];

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Ensure-exact-or-create at both deterministic ids, like every other derived record here.
async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${id}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(primitive)),
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive},
  });
  return objectRef(imageId, block.id);
}

async function installSmalltalkIntegerProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Primitives first: a method's environment may not point at a Block that does not yet exist.
  const primitives = {};
  for (const primitive of Object.keys(PRIMITIVE_BLOCK_ID)) {
    primitives[primitive] = await installPrimitiveBlock({images, imageId, primitive});
  }

  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.integerClass,
    methods: INTEGER_METHODS.map(({selector, primitive, body}) => {
      const capture = captureFor(primitive);
      return {
        selector,
        program: {parameters: [{id: `${selector}:arg`, name: 'other'}], captures: [{...capture}], body},
        captures: [{...capture, value: primitives[primitive]}],
      };
    }),
  });

  // Workstream 3 (MessagePack pressure). Ordinary-source Integer protocol over the comparisons and
  // arithmetic above — no new primitive, no compiler knowledge. Reached for by real upstream source:
  // `writeInteger:` guards with `anInteger between: 0 and: 127`; `readArraySized:` loops `1 to: size
  // do:`; `readMapSized:` loops `timesRepeat:`; `readInt8` negates. `negated`, `between:and:` and the
  // loops are written against `<`, `<=`, `-`, `+`, `and:` and `whileTrue:`, all of which resolve at
  // dispatch like any other send.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.integerClass,
    methods: [
      {selector: 'negated', source: '[ ^ 0 - self ]'},
      // `abs`, measured Cuis Number>>abs (`self < 0 ifTrue: [^0 - self] ^ self`), required by
      // the imported Life code's interval construction (bead lagrange-images-nfv1.3).
      {selector: 'abs', source: '[ self < 0 ifTrue: [ ^ 0 - self ]. ^ self ]'},
      // `min:`/`max:`, measured Cuis magnitudes (`self < another ifTrue: [...]`), required by
      // the imported Life `set:at:` clamping (bead lagrange-images-nfv1.3).
      {selector: 'min:', source: '[ :another | self < another ifTrue: [ ^ self ] ifFalse: [ ^ another ] ]'},
      {selector: 'max:', source: '[ :another | self < another ifTrue: [ ^ another ] ifFalse: [ ^ self ] ]'},
      {selector: 'between:and:', source: '[ :min :max | ^ (min <= self) and: [ self <= max ] ]'},
      {
        selector: 'to:do:',
        source: `[ :stop :aBlock | | i |
          i := self.
          [ i <= stop ] whileTrue: [ aBlock value: i. i := i + 1 ].
          ^ self ]`,
      },
      {selector: 'timesRepeat:', source: '[ :aBlock | 1 to: self do: [ :i | aBlock value ]. ^ self ]'},
      // Binary selector convenience for bitShift:. `a >> b` shifts right by b (negative bitShift);
      // `a << b` shifts left by b (positive bitShift). Written against the installed primitive,
      // not a new one.
      {selector: '>>', source: '[ :shift | ^ self bitShift: 0 - shift ]'},
      {selector: '<<', source: '[ :shift | ^ self bitShift: shift ]'},
    ],
  });

  return Object.freeze({integerClass: kernel.integerClass, ...primitives});
}

// Native Integer PRINTING protocol, added because a real imported consumer sends it: the pinned
// upstream Cuis JSON package's own extension is
//
//   jsonWriteOn: aWriteStream
//       ^ self printOn: aWriteStream base: 10
//
// and nothing in this image implemented `printOn:base:` (bead lagrange-images-nv1.6). This is
// ordinary native Integer protocol usable by any native code — not a JSON helper, not a Cuis
// compatibility method, and not something the stream owns. It writes to its argument through
// ordinary message sends, exactly as the real protocol does, so the stream it is handed decides
// what write protocol is actually required.
//
// RECORDED REAL-CUIS ORACLE (pinned VM + Cuis7.9-8090 image; the transcript is on the bead), taken
// through the real `WriteStream on: String new` ... `printOn:base:` ... `contents` route:
//
//   3    -> '3'          0   -> '0'          1  -> '1'      9   -> '9'      10  -> '10'
//   -3   -> '-3'         -1  -> '-1'         -10 -> '-10'   100 -> '100'    1073741823 -> '1073741823'
//   123456789012345678901234567890  -> '123456789012345678901234567890'
//   -123456789012345678901234567890 -> '-123456789012345678901234567890'
//
// Base 10 is the only base a consumer backs, and it is the only base the proof claims. The digit
// arithmetic is base-generic because it is written with `//` and `\\`, so the method DECLARES the
// domain it is correct on — 2 to 36 — and refuses anything else by sending a selector nothing
// implements, which is this repository's usual way of refusing rather than guessing. That range is
// not decoration: without it `base: 1` never terminates (`value // 1` is `value` forever, and
// nothing in the executor imposes a step budget), and a negative base silently answers punctuation
// because `48 + digit` for a negative digit is still a legal byte. Within the declared range the
// digit-to-byte step needs the ordinary letter branch, since `48 + digit` alone would produce
// nonsense above 9; one base-16 case is checked against real Cuis so that branch is not unproven.
//
// No new primitive. Digits come from the Integer arithmetic this file already installs, and the
// text comes from the existing `Array` -> `ByteArray class >> fromArray:` -> `ByteArray >> utf8Text`
// conversion the byte-sequence protocol already owns. Nothing here invents character or text
// semantics; if a digit could not have been turned into text with what already exists, that would
// have been a gap to classify at the byte/text owner rather than to hide inside Integer.
const INTEGER_PRINTING_METHODS = Object.freeze([Object.freeze({
  selector: 'printOn:base:',
  source: `[ :aStream :base | | value negative digits index bytes digit |
    (base between: 2 and: 36) ifFalse: [ ^ self printBaseOutOfRange: base ].
    negative := self < 0.
    value := negative ifTrue: [ self negated ] ifFalse: [ self ].
    digits := 1.
    index := value // base.
    [ index > 0 ] whileTrue: [ digits := digits + 1. index := index // base ].
    bytes := Array new: (negative ifTrue: [ digits + 1 ] ifFalse: [ digits ]).
    negative ifTrue: [ bytes at: 1 put: 45 ].
    index := bytes size.
    digits timesRepeat: [
      digit := value \\\\ base.
      bytes at: index put: (digit < 10 ifTrue: [ 48 + digit ] ifFalse: [ 55 + digit ]).
      value := value // base.
      index := index - 1 ].
    aStream nextPutAll: (ByteArray fromArray: bytes) utf8Text.
    ^ self ]`,
})]);

// Separate from the protocol installer above only because of ORDER: this method names the `Array`
// and `ByteArray` globals, and global publication happens after the Integer protocol is installed.
// Ownership is unchanged — native Integer semantics stay in this module; the standard image just
// sequences this stage after the namespace exists.
async function installSmalltalkIntegerPrintingProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Restored prerequisites, checked where the cause is still visible rather than as a
  // doesNotUnderstand inside a method body on first use. Two different things are required and
  // they fail differently, so both are checked:
  //
  //   the GLOBALS, because the source names `Array` and `ByteArray` and an unpublished name is a
  //   compile-time unbound name;
  //   the installed METHODS, because publication says nothing about protocol. `ByteArray` in
  //   particular is a KERNEL class whose global the namespace installer publishes unconditionally,
  //   so a global check alone passes on an image that never ran the byte-sequence protocol and the
  //   method then dies on first use with `fromArray:` not understood. That is exactly the
  //   half-installed hazard `smalltalk-library.js` documents, and checking the global is both too
  //   weak here and no substitute for reading the method.
  for (const name of ['Array', 'ByteArray']) {
    if (!await resolveGlobal({images, imageId, name})) {
      throw new TypeError(`image ${imageId} has not published the global ${name}; publish it first`);
    }
  }
  const required = [
    ['smalltalk/metaclass/ByteArray', 'fromArray:'],
    ['smalltalk/class/ByteArray', 'utf8Text'],
    ['smalltalk/metaclass/Array', 'new:'],
    ['smalltalk/class/Array', 'at:put:'],
  ];
  for (const [objectId, selector] of required) {
    const classRef = objectRef(imageId, objectId);
    if (!await images.getObject(imageId, objectId)
      || !await methodBlockRef({images, imageId, classRef, selector})) {
      throw new TypeError(`image ${imageId} has no ${objectId} ${selector} method; install its protocol first`);
    }
  }
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.integerClass, methods: INTEGER_PRINTING_METHODS,
  });
  return Object.freeze({integerClass: kernel.integerClass});
}

export {
  INTEGER_METHODS,
  INTEGER_PRINTING_METHODS,
  PRIMITIVE_BLOCK_ID as SMALLTALK_INTEGER_PRIMITIVE_BLOCK_ID,
  installSmalltalkIntegerPrintingProtocol,
  installSmalltalkIntegerProtocol,
};

// Native `Interval`, added because the real imported application names it: the pinned upstream
// Cuis Life code iterates with `(1 to: cells height) do:` — a `to:` answered by an Interval, then
// `do:` — which is a DIFFERENT message chain from the `to:do:` the Integer owner already serves.
// The native compiler otherwise answered `message not understood: to: sent to an integer Value`
// (bead lagrange-images-nfv1.3). This is an ordinary native Smalltalk class published as an
// ordinary global — NOT a Cuis compatibility class.
//
// RECORDED REAL-CUIS ORACLE (pinned Cuis7.8.sources, upstream's own bodies, minimized to the
// protocol the measured acceptance path sends):
//
//   ivars                 start, stop, count
//   class>>from:to:by:    from start to stop in increments of step, count computed up front
//   Number>>to:           ^Interval from: self to: stop by: 1
//   Interval>>do:         enumerate start..stop inclusive, answer self
//
// `by:` with negative or non-integer steps, `at:`, `collect:`, `select:`, `size`/`first`/`last`
// accessors and the rest of SequenceableCollection breadth remain absent. Execution pressure
// adds protocol one proven consumer at a time.
import {ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

const INTERVAL_SHAPE_ID = 'smalltalk/interval-instance-shape/v1';

const INTERVAL_CLASS_METHODS = Object.freeze([
  // Measured Cuis computes the COUNT up front, never accumulating by adding the step.
  {
    selector: 'from:to:by:',
    source: `[ :aStart :aStop :aStep | | interval c actualStop |
      c := 0.
      aStep > 0 ifTrue: [
        aStop >= aStart ifTrue: [ c := ((aStop - aStart) // aStep) + 1 ] ].
      aStep < 0 ifTrue: [
        aStop <= aStart ifTrue: [ c := ((aStart - aStop) // (0 - aStep)) + 1 ] ].
      actualStop := c > 0
        ifTrue: [ aStart + ((c - 1) * aStep) ]
        ifFalse: [ aStart ].
      interval := self new.
      interval setStart: aStart stop: actualStop count: c.
      ^ interval ]`,
  },
]);

const INTERVAL_METHODS = Object.freeze([
  {selector: 'setStart:stop:count:', source: '[ :aStart :aStop :aCount | start := aStart. stop := aStop. count := aCount ]'},
  {selector: 'step', source: '[ ^ count > 1 ifTrue: [ (stop - start) // (count - 1) ] ifFalse: [ 1 ] ]'},
  {selector: 'size', source: '[ ^ count ]'},
  {selector: 'isEmpty', source: '[ ^ count = 0 ]'},
  {selector: 'first', source: '[ ^ start ]'},
  {selector: 'last', source: '[ ^ stop ]'},
  {selector: 'at:', source: '[ :anIndex | ^ start + ((anIndex - 1) * self step) ]'},
  {
    selector: 'do:',
    source: `[ :aBlock | | i n s |
      s := self step.
      i := start.
      n := 0.
      [ n < count ] whileTrue: [ aBlock value: i. i := i + s. n := n + 1 ].
      ^ self ]`,
  },
]);

// The measured constructor entry: Number>>to: and Number>>to:by:, plus collection enumeration
// methods on Interval that name `OrderedCollection`. A separate composition stage, after Interval
// is published through the namespace, because the bodies name globals.
const INTEGER_TO_METHOD = Object.freeze({
  selector: 'to:',
  source: '[ :aStop | ^ Interval from: self to: aStop by: 1 ]',
});

const INTEGER_TO_BY_METHOD = Object.freeze({
  selector: 'to:by:',
  source: '[ :aStop :aStep | ^ Interval from: self to: aStop by: aStep ]',
});

const INTERVAL_COLLECTION_METHODS = Object.freeze([
  {
    selector: 'collect:',
    source: `[ :aBlock | | result |
      result := OrderedCollection new.
      self do: [ :each | result add: (aBlock value: each) ].
      ^ result asArray ]`,
  },
  {
    selector: 'select:',
    source: `[ :aBlock | | result |
      result := OrderedCollection new.
      self do: [ :each |
        (aBlock value: each) ifTrue: [ result add: each ] ].
      ^ result asArray ]`,
  },
  {selector: 'asArray', source: '[ ^ self collect: [ :each | each ] ]'},
]);

async function installSmalltalkIntervalProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  const instanceShapeRef = await ensureSmalltalkShape(images, imageId, {
    id: INTERVAL_SHAPE_ID,
    slots: [{id: 'interval-start', name: 'start'}, {id: 'interval-stop', name: 'stop'}, {id: 'interval-count', name: 'count'}],
  });
  const {classRef, metaclassRef} = await ensureNamedClass({
    images, imageId, name: 'Interval', superclassRef: objectRef(imageId, 'smalltalk/class/Object'), instanceShapeRef,
  });
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef: metaclassRef, methods: INTERVAL_CLASS_METHODS});
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef, methods: INTERVAL_METHODS});
  return Object.freeze({classRef, metaclassRef});
}

async function installSmalltalkIntervalConstructionProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/class/Integer'),
    methods: [INTEGER_TO_METHOD, INTEGER_TO_BY_METHOD],
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/class/Interval'),
    methods: INTERVAL_COLLECTION_METHODS,
  });
}

export {INTERVAL_SHAPE_ID, INTERVAL_CLASS_METHODS, INTERVAL_METHODS, INTEGER_TO_METHOD, INTEGER_TO_BY_METHOD, installSmalltalkIntervalProtocol, installSmalltalkIntervalConstructionProtocol};

import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';
import {ensureObject as ensureRecordObject, ensureObjects, ensureShape as ensureRecordShape} from '../graph/ensure-records.js';
import {VALUE_KIND, isObjectRef, objectRef, textValue} from '../value/index.js';
import {
  METHOD_DICTIONARY_SHAPE_ID,
  buildMethodBuckets,
  isMethodDictionary,
  methodDictionaryRecordFields,
} from './smalltalk-method-dictionary.js';
import {ensureMethodDictionaryShape} from './smalltalk-method-dictionary-migration.js';
import {currentSelectorBindings} from './smalltalk-class-builder.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// The Symmetric Smalltalk kernel: the durable object graph ADR 0044 dispatches against.
//
// This module installs and rediscovers it. It deliberately performs no dispatch: execution starts
// depending on the kernel in a later change, once dispatch-image context exists. What lands here is
// identity — the shapes, the singleton and class graph, and a way to find all of it again from
// nothing but an image id.
//
// Discoverability is the point. Returning refs from an installer is not enough: the refs die with
// the process while the image survives, so the kernel is reachable at one well-known object id and
// everything else is found through it. The dispatcher will know this protocol, never an `Integer`
// object id.
const SMALLTALK_KERNEL_PROTOCOL_V1 = 'smalltalk-kernel/v1';
const SMALLTALK_KERNEL_OBJECT_ID = 'smalltalk-kernel/v1';

// Fixed shapes, per ADR 0044 decision 1. A Behavior's shape never changes, which is what keeps
// adding a method from restructuring the class.
const BEHAVIOR_SHAPE_ID = 'smalltalk/behavior-shape/v1';
const KERNEL_SHAPE_ID = 'smalltalk/kernel-shape/v1';
const EMPTY_SHAPE_ID = 'smalltalk/empty-shape/v1';

const BEHAVIOR_SLOTS = Object.freeze([
  {id: 'behavior-name', name: 'name'},
  {id: 'behavior-superclass', name: 'superclass'},
  {id: 'behavior-methods', name: 'methods'},
  {id: 'behavior-instance-shape', name: 'instanceShape'},
]);

// The kernel carries the immediate-value classes decision 5 dispatches through, the singletons of
// decision 7, and the three classes the metaclass knot is tied from.
const KERNEL_SLOTS = Object.freeze([
  {id: 'kernel-nil', name: 'nil'},
  {id: 'kernel-true', name: 'true'},
  {id: 'kernel-false', name: 'false'},
  {id: 'kernel-object-class', name: 'objectClass'},
  {id: 'kernel-class-class', name: 'classClass'},
  {id: 'kernel-metaclass-class', name: 'metaclassClass'},
  {id: 'kernel-boolean-class', name: 'booleanClass'},
  {id: 'kernel-integer-class', name: 'integerClass'},
  {id: 'kernel-float-class', name: 'floatClass'},
  {id: 'kernel-text-class', name: 'textClass'},
  {id: 'kernel-byte-array-class', name: 'byteArrayClass'},
]);

const KERNEL_SLOT_BY_NAME = Object.freeze(Object.fromEntries(
  KERNEL_SLOTS.map(({id, name}) => [name, id]),
));

// ADR 0044 decision 2. Generic Shapes reject a duplicate slot *id* and say nothing about names, so
// two slots may both be named `+` and a find-based lookup would resolve by position. That is a
// MethodDictionary invariant, checked here, and deliberately not imposed on generic Shape — which
// has other legitimate users whose slot names are not selectors.
function methodDictionarySlots(selectors) {
  if (!Array.isArray(selectors)) throw new TypeError('method dictionary selectors must be an array');
  const seen = new Set();
  return selectors.map((selector, index) => {
    if (typeof selector !== 'string' || selector.length === 0) {
      throw new TypeError(`method dictionary selector ${index} must be non-empty text`);
    }
    if (seen.has(selector)) {
      throw new TypeError(`method dictionary declares duplicate selector: ${selector}`);
    }
    seen.add(selector);
    return {id: `selector:${base64urlEncode(utf8Encode(selector))}`, name: selector};
  });
}

// Bootstrap must be safe on a populated image and restartable after a partial failure. The two
// record kinds fail differently on their own: `putObject` is an upsert, so a plain write would
// silently replace an existing `smalltalk/nil` or `Integer`; `putShape` is create-once, so a retry
// after a half-finished install would be rejected by the shapes it had already written.
//
// One rule covers both. Every bootstrap write is ensure-exact-or-create:
//
//   absent                  -> create
//   present and identical   -> reuse, write nothing
//   present and different   -> fail, overwrite nothing
class SmalltalkKernelConflictError extends TypeError {
  constructor(kind, imageId, objectId) {
    super(`${kind} ${imageId}/${objectId} already exists and differs from the kernel definition; refusing to overwrite it`);
    this.name = 'SmalltalkKernelConflictError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

// Key order is not part of a record's meaning, so compare a canonical projection rather than
// whatever order the caller or the backend happened to produce. Shared by the Smalltalk builders'
// own (non-admission) comparisons; admission itself lives in graph/ensure-records.js.
function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value ?? null);
}

// Shape admission is owned by graph/ensure-records.js (layout = slots + indexed, ADR 0047; insert-
// only; convergent under a concurrent first install). Only the conflict class is Smalltalk's.
async function ensureShape(service, imageId, desired) {
  return await ensureRecordShape(service, imageId, desired, {
    conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id),
  });
}

// Object admission is owned by graph/ensure-records.js (insert-only; convergent on an identical
// concurrent winner; conflict on a divergent one; identity = shape/behavior/slots/indexed-when-
// present/metadata, ADR 0060). The kernel only requests the object and names its conflict class.
async function ensureObject(service, imageId, desired, {seed = false} = {}) {
  return await ensureRecordObject(service, imageId, desired, {
    seed,
    conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id),
  });
}

// The global invariant, checked against stored data rather than assumed from how it was built.
// Generic graph writes can produce a dictionary shape with duplicate selector names, and any
// name-based lookup over that resolves by position — the first-wins defect ADR 0044 decision 2
// exists to remove. Validating the *whole* shape rather than only the selector being sent is what
// makes the invariant global rather than incidental to the send.
function assertUniqueSelectorShape(shape, label) {
  const seen = new Set();
  for (const {name} of shape.slots) {
    if (seen.has(name)) throw new TypeError(`${label} declares duplicate selector: ${name}`);
    seen.add(name);
  }
  return shape;
}

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['putShape', 'getShape', 'putObject', 'getObject']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

// Cross-image shape and slot references are legal, so an object id alone is not identity. Another
// image may hold its own `smalltalk/behavior-shape/v1`, and treating a ref to it as this image's
// kernel shape would misclassify a foreign record.
function isLocalRef(value, imageId, objectId) {
  return isObjectRef(value) && value.imageId === imageId && (objectId === undefined || value.objectId === objectId);
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// The kernel classes. `super` is the instance-side superclass name; the metaclass chain is derived
// from it by decision 4 rather than written out, so the two cannot drift apart.
const KERNEL_CLASSES = Object.freeze([
  {name: 'Object', super: null},
  {name: 'Class', super: 'Object'},
  {name: 'Metaclass', super: 'Object'},
  {name: 'UndefinedObject', super: 'Object'},
  {name: 'Boolean', super: 'Object'},
  {name: 'True', super: 'Boolean'},
  {name: 'False', super: 'Boolean'},
  {name: 'Integer', super: 'Object'},
  {name: 'Float', super: 'Object'},
  {name: 'Text', super: 'Object'},
  {name: 'ByteArray', super: 'Object'},
]);

const classId = (name) => `smalltalk/class/${name}`;
const metaclassId = (name) => `smalltalk/metaclass/${name}`;
const methodsId = (ownerId) => `${ownerId}/methods`;


// ADR 0049 decision 7: a class defined after this ADR gets the hashed representation immediately.
//
// Tolerant of a legacy record at the same id on purpose. Installing this machinery migrates nothing
// (decision 7), so re-running an installer against an image bootstrapped before it must reuse the
// legacy dictionary rather than demand it be replaced — that is a job for explicit migration, not a
// side effect of running the installer again.
// A record at this deterministic id is reused only when it is *provably* a valid legacy method
// dictionary. Accepting any non-hashed object would contradict both the ensure-exact-or-create rule
// and ADR 0049's promise that a class defined now gets the hashed representation: an unrelated
// squatter would be adopted as the class's method dictionary.
async function isLegacyMethodDictionary(service, imageId, record) {
  if (!record || record.kind !== 'object') return false;
  if (isMethodDictionary(record)) return false;
  // An empty legacy dictionary is structurally an ordinary empty object, so structure alone cannot
  // tell one from an unrelated record squatting on this deterministic id. Every legacy dictionary
  // this substrate ever wrote declares itself one, so the tag is the discriminator — a metadata
  // *label*, which hides no ref and is exactly what metadata is for.
  if (record.metadata?.smalltalk !== 'method-dictionary') return false;
  if (!isObjectRef(record.shape)) return false;
  // Delegate structural, selector-uniqueness, undeclared-slot and local-Block-ref validation to the
  // class builder's single `currentSelectorBindings` owner (bead lagrange-images-jtz.6).
  try {
    await currentSelectorBindings({
      images: service,
      dictionaryRef: objectRef(imageId, record.id),
      record,
      nilRef: null,
    });
    return true;
  } catch {
    return false;
  }
}

async function emptyMethodDictionaryRequest(service, imageId, id, metadata, nilRef) {
  const existing = await service.getObject(imageId, id);
  if (await isLegacyMethodDictionary(service, imageId, existing)) return {existing};
  const {buckets} = buildMethodBuckets([]);
  return {desired: {
    id,
    ...methodDictionaryRecordFields({
      buckets,
      shapeRef: objectRef(imageId, METHOD_DICTIONARY_SHAPE_ID),
      nilRef,
      metadata,
    }),
  }};
}

// The class builder also uses this exported single-dictionary admission seam.
async function ensureEmptyMethodDictionary(service, imageId, id, metadata, nilRef) {
  const {existing, desired} = await emptyMethodDictionaryRequest(service, imageId, id, metadata, nilRef);
  return existing ?? await ensureObject(service, imageId, desired);
}

// The fixed language-owned pair, in durable history order. Legacy recognition stays in the
// same private request owner as the five-argument helper; exact admission stays in ensureObjects.
// Only newly missing records share a transaction. An adopted dictionary is never rewritten.
async function ensureEmptyMethodDictionaryAndBehavior(service, imageId, {behavior, nilRef} = {}) {
  requiredText(imageId, 'image id');
  requiredText(behavior?.id, 'Behavior id');
  const dictionaryId = methodsId(behavior.id);
  if (!isLocalRef(behavior.shape, imageId, BEHAVIOR_SHAPE_ID)
    || !isLocalRef(behavior.slots?.['behavior-methods'], imageId, dictionaryId)) {
    throw new TypeError('dictionary/Behavior pair requires the local Behavior shape and matching methods edge');
  }
  for (const method of ['getObject', 'getRecord', 'createRecords']) {
    if (typeof service?.[method] !== 'function') throw new TypeError(`dictionary/Behavior pair requires images.${method}`);
  }
  const {existing, desired} = await emptyMethodDictionaryRequest(
    service, imageId, dictionaryId, {owner: behavior.id}, nilRef,
  );
  const stored = await ensureObjects(service, imageId, desired ? [desired, behavior] : [behavior], {
    conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id),
  });
  return Object.freeze({dictionary: existing ?? stored[0], behavior: stored[stored.length - 1]});
}

async function installSmalltalkKernel({images, imageId} = {}) {
  const service = assertImages(images);
  requiredText(imageId, 'kernel image id');
  for (const method of ['getRecord', 'createRecords']) {
    if (typeof service[method] !== 'function') throw new TypeError(`kernel installer requires images.${method}`);
  }
  const ref = (objectId) => objectRef(imageId, objectId);

  await ensureMethodDictionaryShape(service, imageId);
  const shapes = {
    behavior: await ensureShape(service, imageId, {id: BEHAVIOR_SHAPE_ID, slots: [...BEHAVIOR_SLOTS]}),
    kernel: await ensureShape(service, imageId, {id: KERNEL_SHAPE_ID, slots: [...KERNEL_SLOTS]}),
    empty: await ensureShape(service, imageId, {id: EMPTY_SHAPE_ID, slots: []}),
  };
  // Assemble each existing metaclass/class phase in historical dictionary/Behavior order. The
  // kernel alone recognizes valid legacy dictionaries; the generic ensure owner sees only exact
  // object requests, and atomically admits each phase's missing subset after a partial install.
  const behaviorGraph = [];
  const admitBehaviorPhase = async () => {
    await ensureObjects(service, imageId, behaviorGraph, {
      conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id),
    });
    behaviorGraph.length = 0;
  };
  const describeBehavior = async ({id, name, superclassRef, behaviorRef, instanceShapeRef}) => {
    const {desired: dictionary} = await emptyMethodDictionaryRequest(
      service, imageId, methodsId(id), {owner: id}, ref('smalltalk/nil'),
    );
    if (dictionary) behaviorGraph.push(dictionary);
    behaviorGraph.push({
      id,
      shape: ref(BEHAVIOR_SHAPE_ID),
      behavior: behaviorRef,
      slots: {
        'behavior-name': textValue(name),
        'behavior-superclass': superclassRef,
        'behavior-methods': ref(methodsId(id)),
        'behavior-instance-shape': instanceShapeRef,
      },
      metadata: {smalltalk: 'behavior', name},
    });
  };

  // The singletons first, so `nil` exists to stand in every absent slot. They are ordinary objects
  // with no slots; what makes them singular is that the kernel names them.
  const singletons = {};
  for (const [slotName, className, objectId] of [
    ['nil', 'UndefinedObject', 'smalltalk/nil'],
    ['true', 'True', 'smalltalk/true'],
    ['false', 'False', 'smalltalk/false'],
  ]) {
    singletons[slotName] = await ensureObject(service, imageId, {
      id: objectId,
      shape: ref(EMPTY_SHAPE_ID),
      behavior: ref(classId(className)),
      slots: {},
      metadata: {smalltalk: 'singleton', name: slotName},
    });
  }
  const nilRef = ref('smalltalk/nil');

  // Metaclasses. `behavior(aMetaclass) == Metaclass` for every one of them, including Metaclass's
  // own metaclass — which is the knot: `behavior(Metaclass class) == Metaclass`.
  //
  // Decision 4's chain rule is applied here rather than written out per class, so the class and
  // metaclass hierarchies cannot drift apart: `C class superclass == S class`, with `Object class
  // superclass == Class` as the root case.
  for (const {name, super: superName} of KERNEL_CLASSES) {
    await describeBehavior({
      id: metaclassId(name),
      name: `${name} class`,
      superclassRef: superName === null ? ref(classId('Class')) : ref(metaclassId(superName)),
      behaviorRef: ref(classId('Metaclass')),
      instanceShapeRef: nilRef,
    });
  }
  await admitBehaviorPhase();

  // Classes. `behavior(aClass) == that class's metaclass`, and `nil` stands for "no superclass".
  for (const {name, super: superName} of KERNEL_CLASSES) {
    await describeBehavior({
      id: classId(name),
      name,
      superclassRef: superName === null ? nilRef : ref(classId(superName)),
      behaviorRef: ref(metaclassId(name)),
      instanceShapeRef: nilRef,
    });
  }
  await admitBehaviorPhase();

  const kernel = await ensureObject(service, imageId, {
    id: SMALLTALK_KERNEL_OBJECT_ID,
    shape: ref(KERNEL_SHAPE_ID),
    behavior: ref(classId('Object')),
    slots: {
      'kernel-nil': ref('smalltalk/nil'),
      'kernel-true': ref('smalltalk/true'),
      'kernel-false': ref('smalltalk/false'),
      'kernel-object-class': ref(classId('Object')),
      'kernel-class-class': ref(classId('Class')),
      'kernel-metaclass-class': ref(classId('Metaclass')),
      'kernel-boolean-class': ref(classId('Boolean')),
      'kernel-integer-class': ref(classId('Integer')),
      'kernel-float-class': ref(classId('Float')),
      'kernel-text-class': ref(classId('Text')),
      'kernel-byte-array-class': ref(classId('ByteArray')),
    },
    metadata: {protocol: SMALLTALK_KERNEL_PROTOCOL_V1},
  });

  return Object.freeze({
    protocol: SMALLTALK_KERNEL_PROTOCOL_V1,
    ref: ref(SMALLTALK_KERNEL_OBJECT_ID),
    kernel,
    shapes: Object.freeze(shapes),
    singletons: Object.freeze(singletons),
  });
}

// Rediscovery: one image id in, the whole kernel out. Nothing here depends on having run the
// installer in this process.
async function findSmalltalkKernel({images, imageId} = {}) {
  const service = assertImages(images);
  requiredText(imageId, 'kernel image id');
  const cached = service.cachedProtocol?.(SMALLTALK_KERNEL_PROTOCOL_V1, imageId);
  if (cached) return cached;
  const record = await service.getObject(imageId, SMALLTALK_KERNEL_OBJECT_ID);
  if (!record) return null;
  if (record.metadata?.protocol !== SMALLTALK_KERNEL_PROTOCOL_V1) {
    throw new TypeError(
      `object ${imageId}/${SMALLTALK_KERNEL_OBJECT_ID} does not declare ${SMALLTALK_KERNEL_PROTOCOL_V1}`,
    );
  }
  // Declaring the protocol is not enough: the record must actually have the kernel shape, in this
  // image, and every slot must be an unpinned local ref. Otherwise a partially-written or
  // deliberately-shaped impostor would be handed to the dispatcher.
  if (!isLocalRef(record.shape, imageId, KERNEL_SHAPE_ID)) {
    throw new TypeError(`Smalltalk kernel ${imageId}/${record.id} does not have shape ${KERNEL_SHAPE_ID}`);
  }
  const slots = {};
  for (const {id, name} of KERNEL_SLOTS) {
    const value = record.slots[id];
    if (!isLocalRef(value, imageId)) {
      throw new TypeError(`Smalltalk kernel slot ${name} must be an unpinned ref in ${imageId}`);
    }
    slots[name] = value;
  }
  const kernel = Object.freeze({protocol: SMALLTALK_KERNEL_PROTOCOL_V1, ref: objectRef(imageId, record.id), record, ...slots});
  return service.cacheProtocol ? service.cacheProtocol(SMALLTALK_KERNEL_PROTOCOL_V1, imageId, kernel) : kernel;
}

// ADR 0044 decision 10: a behavior record means what its own shape says it means. A fixed-shape
// Behavior gets ADR 0044 lookup; anything else is a legacy behavior and keeps legacy lookup.
// Installing the kernel therefore reinterprets nothing that already exists.
function isBehaviorObject(record) {
  return Boolean(record)
    && record.kind === 'object'
    && isLocalRef(record.shape, record.imageId, BEHAVIOR_SHAPE_ID);
}

async function readBehavior(images, ref, {record: preloaded = null} = {}) {
  const service = assertImages(images);
  const record = preloaded ?? await service.getObject(ref.imageId, ref.objectId);
  if (!record) throw new TypeError(`behavior not found: ${ref.imageId}/${ref.objectId}`);
  if (!isBehaviorObject(record)) throw new TypeError(`not a ${BEHAVIOR_SHAPE_ID} behavior: ${ref.objectId}`);
  // The next change makes this part of dispatch, so the slot types are checked here rather than
  // trusted there.
  const name = record.slots['behavior-name'];
  if (name?.kind !== VALUE_KIND.TEXT) throw new TypeError(`behavior ${ref.objectId} name must be a text Value`);
  if (!isLocalRef(record.behavior, record.imageId)) {
    throw new TypeError(`behavior ${ref.objectId} behavior must be an unpinned ref in ${record.imageId}`);
  }
  const refSlots = {};
  for (const [slotId, label] of [
    ['behavior-superclass', 'superclass'],
    ['behavior-methods', 'methods'],
    ['behavior-instance-shape', 'instanceShape'],
  ]) {
    const value = record.slots[slotId];
    if (!isLocalRef(value, record.imageId)) {
      throw new TypeError(`behavior ${ref.objectId} ${label} must be an unpinned ref in ${record.imageId}`);
    }
    refSlots[label] = value;
  }
  return Object.freeze({record, name, behavior: record.behavior, ...refSlots});
}

// ADR 0044 decision 8's policy half, scoped exactly as the ADR scopes it: ADR 0043 decision 9 is
// superseded for bootstrapped *Symmetric Smalltalk* execution, so an artifact of any other language
// gets nothing back and its temporaries start UNBOUND — even in an image that carries a kernel.
//
// Deliberately unmemoized. Bootstrap is an installer for an existing image, so a runtime that
// observed an image before its kernel existed must see the kernel afterwards; caching would make
// execution depend on what the process happened to observe earlier rather than on current graph
// state. A cache without an invalidation contract hides later graph changes too, and there is no
// such contract to write against yet.
function createSmalltalkTemporaryInitializer() {
  return async ({images, dispatchImage, languageId}) => {
    if (!dispatchImage || languageId !== SYMMETRIC_SMALLTALK_ID) return null;
    const kernel = await findSmalltalkKernel({images, imageId: dispatchImage});
    return kernel ? kernel.nil : null;
  };
}

export {
  BEHAVIOR_SHAPE_ID,
  KERNEL_CLASSES,
  ensureEmptyMethodDictionary,
  ensureEmptyMethodDictionaryAndBehavior,
  isLegacyMethodDictionary,
  createSmalltalkTemporaryInitializer,
  SmalltalkKernelConflictError,
  canonicalJson,
  assertUniqueSelectorShape,
  ensureObject,
  ensureShape,
  isLocalRef,
  BEHAVIOR_SLOTS,
  EMPTY_SHAPE_ID,
  KERNEL_SHAPE_ID,
  KERNEL_SLOTS,
  KERNEL_SLOT_BY_NAME,
  SMALLTALK_KERNEL_OBJECT_ID,
  SMALLTALK_KERNEL_PROTOCOL_V1,
  findSmalltalkKernel,
  installSmalltalkKernel,
  isBehaviorObject,
  methodDictionarySlots,
  readBehavior,
};

import {findSmalltalkBlockProtocol} from './smalltalk-block-protocol.js';
import {findSmalltalkBlockUnwindProtocol} from './smalltalk-conditions.js';
import {resolveGlobal} from './smalltalk-globals.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {assertMethodLane, ensureNamedClass, ensureSmalltalkShape, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

// The first image-resident library: ordinary Smalltalk classes written with the facilities ADRs
// 0043-0050 built, and nothing else. No collection-specific primitive is added here, and none is
// used — every method below is source that the class-scoped compiler binds like any other.
//
// It is a substrate exercise as much as a library. Where an idiom is unavailable the code uses what
// exists rather than reaching for a host operation, and the awkwardness is left visible on purpose:
//
//   no conditions            a refusal is signalled by sending a selector nothing implements, so
//                            an out-of-range access fails as a message-not-understood naming the
//                            collection's own concept rather than raising anything
//
// Three of those gaps are now closed, and the awkwardness went with each. ADR 0051 gave Blocks
// `whileTrue:`/`whileFalse:`, so iteration is a loop rather than recursion under the 256-activation
// limit. ADR 0053 gave Integer `<=`, so a traversal states its bound instead of counting up to
// `tally + 1` and comparing with `=` — and `at:`, `first`, `last` and `removeLast` become possible,
// because each is a bounds check and a bounds check is an ordering question. ADR 0055 gave `^` a
// home, so `includes:` answers from inside its loop instead of carrying a `found` flag out.
//
// Each of those is a general language gap rather than a collection concern, and each is recorded in
// `docs/roadmap.md` rather than papered over here.

const ASSOCIATION_SHAPE_ID = 'smalltalk/association-instance-shape/v1';
const ORDERED_COLLECTION_SHAPE_ID = 'smalltalk/ordered-collection-instance-shape/v1';

// The hierarchy's root. `Collection` holds no state of its own — the enumeration protocol is
// written against `do:`, which a subclass supplies — so it carries no instance Shape and nothing
// here binds an instance variable. That is what lets the shared protocol live above every concrete
// collection without either duplicating it or pushing the subclass's layout up into the parent.
//
// `species` answers the class a derived collection should be made of. The default is the receiver's
// own class, which is what Smalltalk specifies and what `collect:`/`select:` need; a class whose
// derived collections should be something else (a SortedCollection answering an OrderedCollection,
// a Set answering a list for `collect:`) overrides `species`, not the enumeration methods.
const COLLECTION_METHODS = [
  {selector: 'species', source: '[ self class ]'},
  // Enumeration composes `do:` rather than touching any subclass state. `detect:ifNone:` returns
  // from inside its loop (ADR 0055), and `inject:into:` threads an accumulator — both ordinary
  // Smalltalk over `do:`, with no primitive and no compiler involvement.
  {
    selector: 'collect:',
    source: `[ :aBlock | | result |
      result := self species new.
      self do: [ :each | result add: (aBlock value: each) ].
      ^ result ]`,
  },
  {
    selector: 'select:',
    source: `[ :aBlock | | result |
      result := self species new.
      self do: [ :each | (aBlock value: each) ifTrue: [ result add: each ] ].
      ^ result ]`,
  },
  {
    selector: 'detect:ifNone:',
    source: `[ :aBlock :noneBlock |
      self do: [ :each | (aBlock value: each) ifTrue: [ ^ each ] ].
      ^ noneBlock value ]`,
  },
  {
    selector: 'inject:into:',
    source: `[ :initial :binaryBlock | | accumulator |
      accumulator := initial.
      self do: [ :each | accumulator := binaryBlock value: accumulator value: each ].
      ^ accumulator ]`,
  },
];

const ASSOCIATION_METHODS = [
  {selector: 'key', source: '[ key ]'},
  {selector: 'value', source: '[ value ]'},
  {selector: 'key:value:', source: '[ :aKey :aValue | key := aKey. value := aValue. self ]'},
  {selector: 'value:', source: '[ :aValue | value := aValue. self ]'},
  // A same-class guard first, because sending `key` to an arbitrary object would be
  // message-not-understood rather than an answer of false.
  {
    selector: '=',
    source: `[ :other |
      (other class = self class)
        ifTrue: [ (key = other key) and: [ value = other value ] ]
        ifFalse: [ false ] ]`,
  },
  // Equal Associations must hash alike (ADR 0048 decision 4). Hashing the key alone satisfies that
  // and is what a Dictionary of Associations wants.
  {selector: 'hash', source: '[ key hash ]'},
];



const ORDERED_COLLECTION_METHODS = [
  {
    selector: 'initialize',
    source: '[ contents := Array new: 4. tally := 0. self ]',
  },
  {selector: 'size', source: '[ tally ]'},
  {selector: 'isEmpty', source: '[ tally = 0 ]'},

  // Growth is a policy of this class, not of storage — exactly as ADR 0047 decision 6 said it would
  // be: an OrderedCollection is an ordinary object holding an Array plus a size and a growth policy.
  {selector: 'add:', source: '[ :item | self ensureRoom. tally := tally + 1. contents at: tally put: item. item ]'},
  {selector: 'ensureRoom', source: '[ (tally = contents size) ifTrue: [ self grow ] ]'},
  {
    selector: 'grow',
    source: `[ | bigger |
      bigger := Array new: (contents size + contents size).
      self copyInto: bigger.
      contents := bigger.
      self ]`,
  },

  // Iteration is a loop (ADR 0051) that states its bound with `<=` (ADR 0053), rather than
  // recursion counting up to `tally + 1` to avoid an ordering comparison that did not exist.
  {
    selector: 'copyInto:',
    source: `[ :target | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        target at: index put: (contents at: index).
        index := index + 1 ] ]`,
  },
  {
    selector: 'do:',
    source: `[ :aBlock | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        aBlock value: (contents at: index).
        index := index + 1 ] ]`,
  },
  // Answers from inside the loop (ADR 0055). The `found` temporary this used to carry existed only
  // because a Block could not return from its enclosing method; it went with the gap rather than
  // surviving as decoration.
  {
    selector: 'includes:',
    source: `[ :item | | index |
      index := 1.
      [ index <= tally ] whileTrue: [
        (item = (contents at: index)) ifTrue: [ ^ true ] ifFalse: [ false ].
        index := index + 1 ].
      false ]`,
  },
  // ADR 0053's point. Each of these is a bounds check, which is why none existed before an ordering
  // comparison did.
  //
  // The bound is the collection's own `tally`, never the backing Array's capacity: `contents at:`
  // succeeds for any index up to capacity, so a collection that deferred to it would cheerfully
  // answer whatever slack the growth policy left behind.
  //
  // A refusal is an ordinary signal (ADR 0054), so a caller can handle it — which is what makes
  // `at:ifAbsent:` writable in Smalltalk rather than needing a second primitive. Before that ADR
  // this sent `errorIndexOutOfBounds:`, which nothing implemented, so the failure arrived as a
  // message-not-understood that no one could catch.
  {
    selector: 'at:',
    source: `[ :index |
      (index < 1)
        ifTrue: [ (IndexOutOfRange new) signal ]
        ifFalse: [ (index <= tally)
          ifTrue: [ contents at: index ]
          ifFalse: [ (IndexOutOfRange new) signal ] ] ]`,
  },
  // Expressible only because the refusal is catchable: the alternative Block is evaluated by
  // handling the collection's own signal, with no new protocol underneath it.
  {
    selector: 'at:ifAbsent:',
    source: '[ :index :aBlock | [ self at: index ] on: IndexOutOfRange do: [ :e | aBlock value ] ]',
  },
  {selector: 'first', source: '[ self at: 1 ]'},
  {selector: 'last', source: '[ self at: tally ]'},
  // The vacated slot is cleared, not merely hidden. `at:` would refuse to answer it either way, but
  // the backing Array is a durable object: leaving the ref there keeps the removed element
  // graph-reachable, so a large collection drained to empty would retain every element it ever held.
  {
    selector: 'removeLast',
    source: `[ | item |
      (tally < 1)
        ifTrue: [ (EmptyCollection new) signal ]
        ifFalse: [
          item := contents at: tally.
          contents at: tally put: nil.
          tally := tally - 1.
          item ] ]`,
  },
  // Higher-order enumeration no longer lives here: it moved to Collection with the rest of the
  // shared protocol, written against `do:` and `species` rather than `contents`/`tally`. What
  // remains is OrderedCollection's own layout and growth — the parts Collection cannot know.
  {
    selector: 'asArray',
    source: `[ | result |
      result := Array new: tally.
      self copyInto: result.
      result ]`,
  },
];

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Both go through the shared ensure-exact-or-create helpers. Accepting *any* record at a
// deterministic id would adopt an unrelated object as this class or its layout — the rule the
// repository applies to every derived id, and the reason `defineClass` alone is not enough for
// rediscovery once methods exist.
async function ensureLibraryClass({images, imageId, name, shapeId, slots, superclassRef = null}) {
  // A stateless class carries no instance Shape. `ensureNamedClass` answers nil for it, and
  // `defineClass`'s complete-layout rule is satisfied because a nil-shape ancestor declares nothing
  // a subclass could drop.
  const instanceShapeRef = shapeId
    ? await ensureSmalltalkShape(images, imageId, {id: shapeId, slots})
    : null;
  return (await ensureNamedClass({images, imageId, name, superclassRef, instanceShapeRef})).classRef;
}

// Installed after the kernel protocols this library is written against: allocation (ADR 0046),
// conditionals (0045), Array (0047), equality (0048) and instance variables (0050).
async function installSmalltalkLibrary({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const associationRef = await ensureLibraryClass({
    images,
    imageId,
    name: 'Association',
    shapeId: ASSOCIATION_SHAPE_ID,
    slots: [{id: 'association-key', name: 'key'}, {id: 'association-value', name: 'value'}],
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: associationRef, methods: ASSOCIATION_METHODS,
  });

  // Collection before its subclass: OrderedCollection names it as superclass, and Collection's
  // shared enumeration is defined once here rather than repeated per concrete collection.
  const collectionRef = await ensureLibraryClass({images, imageId, name: 'Collection'});
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: collectionRef, methods: COLLECTION_METHODS,
  });

  const orderedCollectionRef = await ensureLibraryClass({
    images,
    imageId,
    name: 'OrderedCollection',
    superclassRef: collectionRef,
    shapeId: ORDERED_COLLECTION_SHAPE_ID,
    slots: [
      {id: 'ordered-collection-contents', name: 'contents'},
      {id: 'ordered-collection-tally', name: 'tally'},
    ],
  });
  // Restored prerequisites. Every traversal loops, so an image without ADR 0051's Block protocol
  // would install methods that compile cleanly and fail with "Block does not understand:
  // whileFalse:" on first use. Refused here instead, where the cause is still visible.
  if (!await findSmalltalkBlockProtocol({images, imageId})) {
    throw new TypeError(`image ${imageId} has no Smalltalk Block protocol; install it first`);
  }
  // Checked as installed *methods*, not as the presence of the primitive Blocks: the Integer
  // installer publishes its primitives before its methods, so a Block-existence check would pass on
  // a half-installed protocol with `<`, `<=` and `-` still absent.
  for (const selector of ['<', '<=', '-']) {
    if (!await methodBlockRef({images, imageId, classRef: kernel.integerClass, selector})) {
      throw new TypeError(`image ${imageId} has no Integer ${selector} method; install the Integer protocol first`);
    }
  }
  // The unwind protocol object is published *before* the condition classes and their methods, so
  // checking only for it would pass on a half-installed protocol with `Exception >> signal` still
  // missing — the same partial-install hazard the Integer check already closes. Checked as an
  // installed method on a class this library actually signals.
  if (!await findSmalltalkBlockUnwindProtocol({images, imageId})) {
    throw new TypeError(`image ${imageId} has no Smalltalk condition protocol; install it first`);
  }
  const exceptionClass = objectRef(imageId, 'smalltalk/class/Exception');
  if (!await images.getObject(imageId, exceptionClass.objectId)
    || !await methodBlockRef({images, imageId, classRef: exceptionClass, selector: 'signal'})) {
    throw new TypeError(`image ${imageId} has no Exception signal method; install the condition protocol first`);
  }
  for (const name of ['IndexOutOfRange', 'EmptyCollection']) {
    if (!await images.getObject(imageId, `smalltalk/class/${name}`)) {
      throw new TypeError(`image ${imageId} has no ${name} class; install the condition protocol first`);
    }
  }
  // ADR 0057: this library's source names `Array`, `IndexOutOfRange` and `EmptyCollection`, so
  // those globals must have been published. Checked here, where the cause is visible, rather than
  // failing later as an unbound name inside a method body.
  for (const name of ['Array', 'IndexOutOfRange', 'EmptyCollection']) {
    if (!await resolveGlobal({images, imageId, name})) {
      throw new TypeError(`image ${imageId} has not published the global ${name}; publish it first`);
    }
  }

  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: orderedCollectionRef,
    // No captures at all: every class these methods name is resolved through the image's namespace
    // (ADR 0057), so the installer no longer has to know which classes each method mentions.
    methods: ORDERED_COLLECTION_METHODS,
  });

  return Object.freeze({
    association: associationRef,
    collection: collectionRef,
    orderedCollection: orderedCollectionRef,
  });
}

export {
  ASSOCIATION_METHODS,
  ASSOCIATION_SHAPE_ID,
  COLLECTION_METHODS,
  ORDERED_COLLECTION_METHODS,
  ORDERED_COLLECTION_SHAPE_ID,
  installSmalltalkLibrary,
};

import {VALUE_KIND, isObjectRef, textValue} from '../value/index.js';
import {TupleMap, TupleSet} from '../support/tuple-map.js';
import {
  isMethodDictionary,
  lookupSelectorInTable,
  validateMethodDictionary,
} from './smalltalk-method-dictionary.js';
import {
  assertUniqueSelectorShape,
  findSmalltalkKernel,
  isBehaviorObject,
  readBehavior,
} from './smalltalk-kernel.js';

// ADR 0044 method lookup: walk the receiver's Behavior and its superclasses until the selector is
// found. Three failures are kept apart on purpose, because they mean different things and a caller
// that cannot tell them apart cannot respond correctly to any of them.
//
//   malformed Behavior     a record claiming the fixed shape whose slots do not hold what that
//                          shape promises. A structural defect in one record.
//   dangling edge          a well-formed Behavior whose superclass or method dictionary does not
//                          resolve. Corrupt or incomplete graph state, not a message miss.
//   not understood         the walk completed and no class implements the selector. An ordinary
//                          language-level outcome.
class SmalltalkMalformedBehaviorError extends TypeError {
  constructor(ref, cause) {
    super(`malformed Behavior ${ref.imageId}/${ref.objectId}: ${cause.message}`, {cause});
    this.name = 'SmalltalkMalformedBehaviorError';
    this.behavior = ref;
  }
}

// Callers hold records in some places and refs in others; a record has `id` where a ref has
// `objectId`, so normalize before formatting or the message reads `app/undefined`.
function asRef(value) {
  if (!value) return {imageId: 'unknown', objectId: 'unknown'};
  return {imageId: value.imageId, objectId: value.objectId ?? value.id};
}

class SmalltalkDanglingEdgeError extends TypeError {
  constructor(edge, fromValue, refValue) {
    const from = asRef(fromValue);
    const ref = asRef(refValue);
    super(
      `Behavior ${from.imageId}/${from.objectId} has a dangling ${edge} edge to `
      + `${ref.imageId}/${ref.objectId}; the object graph is incomplete`,
    );
    this.name = 'SmalltalkDanglingEdgeError';
    this.edge = edge;
    this.from = from;
    this.target = ref;
  }
}

class SmalltalkMessageNotUnderstoodError extends TypeError {
  constructor(selector, receiverDescription) {
    super(`Symmetric Smalltalk message not understood: ${selector} sent to ${receiverDescription}`);
    this.name = 'SmalltalkMessageNotUnderstoodError';
    this.selector = selector;
  }
}

class SmalltalkKernelMissingError extends TypeError {
  constructor(imageId, kind) {
    super(
      `image ${imageId} has no Smalltalk kernel, so a ${kind} Value has no class to dispatch through`,
    );
    this.name = 'SmalltalkKernelMissingError';
    this.imageId = imageId;
  }
}

// Decision 5: an immediate Value has no `behavior` field, so its class comes from its kind. Which
// image's class is a question the dispatch image answers.
//
// `boolean` is deliberately absent. ADR 0045 supersedes its row: a boolean Value bridges to the
// dispatch image's `true`/`false` singleton and then resolves that object's behavior edge like any
// other object receiver. `Boolean` is still reached — `True` and `False` inherit from it — but not
// by dispatching a classless immediate through it.
const KERNEL_CLASS_FOR_KIND = Object.freeze({
  [VALUE_KIND.INTEGER]: 'integerClass',
  [VALUE_KIND.FLOAT64]: 'floatClass',
  [VALUE_KIND.TEXT]: 'textClass',
  [VALUE_KIND.BYTES]: 'byteArrayClass',
});

function sameRef(left, right) {
  return Boolean(left) && Boolean(right)
    && left.kind === right.kind
    && left.imageId === right.imageId
    && left.objectId === right.objectId;
}

async function loadBehavior(images, ref, {edge = null, from = null, record: preloaded = null} = {}) {
  const record = preloaded ?? await images.getObject(ref.imageId, ref.objectId);
  // An absent target is a dangling edge when we arrived along one, and a malformed receiver
  // otherwise. Both are graph problems; neither is a selector miss.
  if (!record) {
    if (edge) throw new SmalltalkDanglingEdgeError(edge, from, ref);
    throw new SmalltalkDanglingEdgeError('behavior', from ?? ref, ref);
  }
  try {
    return await readBehavior(images, ref, {record});
  } catch (error) {
    throw new SmalltalkMalformedBehaviorError(ref, error);
  }
}

// ADR 0049 decision 5a. Whole-table validation is `O(n)`; doing it per send would reinstate exactly
// the cost this representation removes. It is therefore done once per *record version*.
//
// This caches a structural fact about one immutable record version, never a lookup answer, so it
// cannot mask a method addition or a migration: whatever would change the answer also changes the
// `_version` in the key. That version component is the invalidation contract ADR 0044 decision 8
// requires before any durable-graph read may be memoized — without one, this would be forbidden.
class MethodDictionaryValidationCache {
  constructor() {
    this.validated = new TupleMap(3);
  }

  read(record, ref, nilRef) {
    const key = [record.imageId, record.id, String(record._version)];
    const hit = this.validated.get(key);
    if (hit) return hit;
    const table = validateMethodDictionary(record, ref, nilRef);
    this.validated.set(key, table);
    return table;
  }
}

async function methodAt(images, behavior, selector, nilRef, validationCache = null) {
  const dictionaryRef = behavior.methods;
  const dictionary = await images.getObject(dictionaryRef.imageId, dictionaryRef.objectId);
  if (!dictionary) {
    throw new SmalltalkDanglingEdgeError('methods', behavior.record, dictionaryRef);
  }

  // ADR 0049 decision 2: a record is read as what its own Shape says it is, so a hashed and a
  // legacy dictionary can sit in one superclass chain and resolve identically. Installing the new
  // format reinterprets nothing.
  if (isMethodDictionary(dictionary)) {
    const table = validationCache
      ? validationCache.read(dictionary, dictionaryRef, nilRef)
      : validateMethodDictionary(dictionary, dictionaryRef, nilRef);
    // One record read, and no Shape fetch: the selector set is the record's own indexed part.
    return lookupSelectorInTable(table, textValue(selector));
  }

  const shape = await images.getShape(dictionary.shape.imageId, dictionary.shape.objectId);
  if (!shape) {
    throw new SmalltalkDanglingEdgeError('method dictionary shape', dictionary, dictionary.shape);
  }
  // The invariant is that selector names are globally unique in a dictionary, so the whole shape is
  // validated rather than only the selector being sent. Checking one name would leave a corrupt
  // dictionary usable for every other selector.
  try {
    assertUniqueSelectorShape(shape, `method dictionary ${dictionaryRef.imageId}/${dictionaryRef.objectId}`);
  } catch (error) {
    throw new SmalltalkMalformedBehaviorError(dictionaryRef, error);
  }
  const slot = shape.slots.find(({name}) => name === selector);
  if (!slot) return null;
  const method = dictionary.slots[slot.id];
  if (!isObjectRef(method)) {
    throw new SmalltalkMalformedBehaviorError(
      dictionaryRef,
      new TypeError(`method slot for ${selector} must contain an unpinned Block ref`),
    );
  }
  return method;
}

// The walk. Terminates when a Behavior's superclass is the kernel's `nil`, compared as a full ref
// rather than by object id.
//
// That comparison is defence in depth today rather than an active discriminator: `readBehavior`
// requires a superclass to be a local ref, so a foreign `smalltalk/nil` is rejected as a malformed
// Behavior before the chain could reach here, and within one image the two comparisons coincide. It
// is written this way so that relaxing the locality rule for cross-image inheritance would not
// silently turn every image's `smalltalk/nil` into a chain terminator.
async function lookupSelector({
  images, behaviorRef, behaviorRecord = null, selector, nilRef, receiverDescription, validationCache = null,
}) {
  const visited = new TupleSet(2);
  let currentRef = behaviorRef;
  let currentRecord = behaviorRecord;
  let edge = null;
  let from = null;

  while (!sameRef(currentRef, nilRef)) {
    const key = [currentRef.imageId, currentRef.objectId];
    if (visited.has(key)) {
      throw new TypeError(
        `Symmetric Smalltalk superclass cycle at ${currentRef.imageId}/${currentRef.objectId}`,
      );
    }
    visited.add(key);

    const behavior = await loadBehavior(images, currentRef, {edge, from, record: currentRecord});
    currentRecord = null;
    const method = await methodAt(images, behavior, selector, nilRef, validationCache);
    // ADR 0050 decision 5: *which* Behavior's dictionary supplied the method is a permission fact,
    // and this walk is the only place it is known. Reconstructing it later by asking which
    // dictionary holds a Block would be neither unique — a Block may legitimately sit in two — nor
    // trustworthy, since that answer comes from graph data a forged artifact can arrange.
    if (method) return {method, definingBehavior: currentRef};

    from = behavior.record;
    edge = 'superclass';
    currentRef = behavior.superclass;
  }

  throw new SmalltalkMessageNotUnderstoodError(selector, receiverDescription);
}

// ADR 0050 decision 5, as corrected: the layout a method of this Behavior may name. One
// implementation, shared by the binder and by the runtime permission check, because two would be two
// chances to disagree about what is visible and two different answers for corrupt graph state.
//
// Strict on purpose. Returning "no layout" for a cycle or a dangling Shape would convert corruption
// into an ordinary denial at runtime and into `unbound Symmetric Smalltalk name` at compile time —
// the same laundering of structural failure into a language-level outcome that ADR 0044's three-way
// split exists to prevent.
//
// `null` means exactly one thing: the walk reached the kernel `nil` terminator having found no
// declared layout.
async function visibleInstanceShape({images, behaviorRef, nilRef}) {
  const visited = new TupleSet(2);
  let currentRef = behaviorRef;

  while (!sameRef(currentRef, nilRef)) {
    if (!isObjectRef(currentRef)) {
      throw new TypeError('instance layout walk reached a non-ref superclass edge');
    }
    // Tuple-keyed, never a joined string: object ids are arbitrary non-empty text, so no separator
    // can make `imageId/objectId` injective.
    const key = [currentRef.imageId, currentRef.objectId];
    if (visited.has(key)) {
      throw new TypeError(
        `instance layout walk hit a superclass cycle at ${currentRef.imageId}/${currentRef.objectId}; `
        + 'the visible layout cannot be determined',
      );
    }
    visited.add(key);

    const behavior = await loadBehavior(images, currentRef, {edge: 'superclass', from: currentRef});
    if (!sameRef(behavior.instanceShape, nilRef)) {
      const shape = await images.getShape(behavior.instanceShape.imageId, behavior.instanceShape.objectId);
      if (!shape) throw new SmalltalkDanglingEdgeError('instanceShape', behavior.record, behavior.instanceShape);
      return shape;
    }
    currentRef = behavior.superclass;
  }
  return null;
}

// The class a receiver dispatches through, and the image that answers "which Integer?".
//
// `effectiveReceiver` is non-null only where the language nominates a different receiver from the
// one the message was sent to. That is the ADR 0045 boolean bridge and, today, nothing else.
async function behaviorRefFor({images, receiver, dispatchImage}) {
  if (isObjectRef(receiver)) {
    const record = await images.getObject(receiver.imageId, receiver.objectId);
    if (!record) {
      throw new TypeError(`Symmetric Smalltalk receiver not found: ${receiver.imageId}/${receiver.objectId}`);
    }
    return {record, behavior: record.behavior, effectiveReceiver: null};
  }
  // ADR 0045 decisions 2 and 3. A boolean Value is not boxed and gains nothing; for the duration of
  // this one send the dispatch image's `true` or `false` object *is* the receiver, so the method's
  // `self` is genuinely the singleton and lookup starts at `True` or `False` rather than at a class
  // chosen from a kind.
  if (receiver.kind === VALUE_KIND.BOOLEAN) {
    const kernel = await findSmalltalkKernel({images, imageId: dispatchImage});
    if (!kernel) throw new SmalltalkKernelMissingError(dispatchImage, receiver.kind);
    const singleton = receiver.value ? kernel.true : kernel.false;
    const record = await images.getObject(singleton.imageId, singleton.objectId);
    if (!record) {
      throw new TypeError(
        `Symmetric Smalltalk kernel singleton ${singleton.imageId}/${singleton.objectId} not found; `
        + 'the object graph is incomplete',
      );
    }
    return {record, behavior: record.behavior, effectiveReceiver: singleton, kernel};
  }
  // Decision 5a: an immediate Value carries no image, so the sender's dispatch image supplies one.
  const slotName = KERNEL_CLASS_FOR_KIND[receiver.kind];
  if (!slotName) return {record: null, behavior: null, effectiveReceiver: null};
  const kernel = await findSmalltalkKernel({images, imageId: dispatchImage});
  if (!kernel) throw new SmalltalkKernelMissingError(dispatchImage, receiver.kind);
  return {record: null, behavior: kernel[slotName], effectiveReceiver: null, kernel};
}

export {
  KERNEL_CLASS_FOR_KIND,
  MethodDictionaryValidationCache,
  SmalltalkDanglingEdgeError,
  SmalltalkKernelMissingError,
  SmalltalkMalformedBehaviorError,
  SmalltalkMessageNotUnderstoodError,
  behaviorRefFor,
  isBehaviorObject,
  visibleInstanceShape,
  lookupSelector,
  sameRef,
};

import {isObjectRef, objectRef, textValue} from '../value/index.js';
import {ensureObject, ensureShape} from '../graph/ensure-records.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {
  SmalltalkKernelConflictError,
  findSmalltalkKernel,
  readBehavior,
} from './smalltalk-kernel.js';
import {currentSelectorBindings} from './smalltalk-class-builder.js';
import {
  METHOD_DICTIONARY_SHAPE_ID,
  METHOD_DICTIONARY_SHAPE_SLOTS,
  SEAL_METADATA_KEY,
  buildMethodBuckets,
  isMethodDictionary,
  isSealed,
  methodDictionaryRecordFields,
  migratedDictionaryId,
  validateMethodDictionary,
} from './smalltalk-method-dictionary.js';

// ADR 0049 decision 7: migrating one Behavior's method dictionary from the ADR 0044 shape-backed
// representation to the hashed one.
//
// The whole design exists to answer one race. Method addition writes the *dictionary* guarded by the
// dictionary's version; migration writes the *Behavior* guarded by the Behavior's version. Those
// guards are disjoint, so an addition landing between migration's read and its swap changes neither
// record the swap is conditioned on — the CAS succeeds and the added method disappears with the
// abandoned dictionary.
//
// The irony is exact: ADR 0044 decision 1 gave Behaviors a fixed shape precisely so adding a method
// would not touch them, and that is what makes the Behavior's version useless here. Re-reading the
// legacy dictionary just before the swap narrows the window without closing it.
//
// So both writers are routed through the one record they share:
//
//   1. read legacy L at version v, validate it completely
//   2. seal L      CAS on L, expectedVersion = v      <- the serialization point
//   3. build the hashed dictionary at a deterministic id
//   4. CAS Behavior.methods:  L -> H
class SmalltalkMigrationConflictError extends TypeError {
  constructor(kind, ref) {
    super(
      `Symmetric Smalltalk method dictionary migration for ${ref.imageId}/${ref.objectId} lost a `
      + `${kind} race; nothing was published, and an identical retry will converge`,
    );
    this.name = 'SmalltalkMigrationConflictError';
    this.kind = kind;
  }
}

async function ensureMethodDictionaryShape(images, imageId) {
  const desired = {id: METHOD_DICTIONARY_SHAPE_ID, slots: [...METHOD_DICTIONARY_SHAPE_SLOTS], indexed: SHAPE_INDEXED.VALUES};
  const shape = await ensureShape(images, imageId, desired, {conflict: (kind, image, id) => new SmalltalkKernelConflictError(kind, image, id)});
  return shape;
}

// The legacy representation, read through the single shared `currentSelectorBindings` owner
// (bead lagrange-images-jtz.6) so migration, browsing, write planning and kernel adoption enforce
// the exact same rule set before the seal.
async function readLegacyEntries(images, dictionaryRef, record) {
  const bindings = await currentSelectorBindings({images, dictionaryRef, record, nilRef: null});
  return [...bindings.entries()].map(([selector, method]) => [textValue(selector), method]);
}

// Ensure-exact-or-create at the deterministic target. A retry after a committed-but-unacknowledged
// write finds its own previous output and reuses it rather than leaving another orphan — which is
// the whole reason this id is deterministic rather than fresh per attempt (contrast ADR 0048
// decision 6, where an unbounded series of snapshots needs the opposite rule).
// Admission of the migrated dictionary is the ensure owner's (insert-only; convergent on an
// identical concurrent winner; conflict on a divergent one). Only the conflict label is ours.
async function ensureMigratedDictionary(images, imageId, desired) {
  return await ensureObject(images, imageId, desired, {
    conflict: (kind, image, id) => new SmalltalkKernelConflictError('method dictionary', image, id),
  });
}

async function migrateMethodDictionary({images, imageId, behaviorRef} = {}) {
  if (!isObjectRef(behaviorRef) || behaviorRef.imageId !== imageId) {
    throw new TypeError(`migrateMethodDictionary behavior must be an unpinned ref in ${imageId}`);
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  const behaviorRecord = await images.getObject(behaviorRef.imageId, behaviorRef.objectId);
  if (!behaviorRecord) throw new TypeError(`Behavior not found: ${behaviorRef.imageId}/${behaviorRef.objectId}`);
  const behavior = await readBehavior(images, behaviorRef);
  const dictionaryRef = behavior.methods;

  const legacy = await images.getObject(dictionaryRef.imageId, dictionaryRef.objectId);
  if (!legacy) throw new TypeError(`method dictionary not found: ${dictionaryRef.imageId}/${dictionaryRef.objectId}`);

  // Already migrated is a success, not an error: migration must be safe to run twice, and a caller
  // that lost an acknowledgement cannot tell the difference.
  if (isMethodDictionary(legacy)) {
    return Object.freeze({migrated: false, dictionary: dictionaryRef, reason: 'already hashed'});
  }

  // Step 1. Read and validate before touching anything.
  const entries = await readLegacyEntries(images, dictionaryRef, legacy);

  // Step 2. Seal — the serialization point. If a method was added since step 1, the CAS fails and
  // the caller retries from a read that includes it.
  if (!isSealed(legacy)) {
    try {
      await images.putObject(imageId, {
        id: legacy.id,
        shape: legacy.shape,
        behavior: legacy.behavior ?? null,
        slots: legacy.slots,
        metadata: {...legacy.metadata, [SEAL_METADATA_KEY]: true},
      }, {expectedVersion: legacy._version});
    } catch (error) {
      if (error?.name === 'VersionConflictError') throw new SmalltalkMigrationConflictError('method-addition', dictionaryRef);
      throw error;
    }
  }

  // Step 3. Build the hashed dictionary. Still invisible: nothing points at it yet.
  await ensureMethodDictionaryShape(images, imageId);
  const {buckets} = buildMethodBuckets(entries);
  const migratedId = migratedDictionaryId(behaviorRef.objectId);
  const stored = await ensureMigratedDictionary(images, imageId, {
    id: migratedId,
    ...methodDictionaryRecordFields({
      buckets,
      shapeRef: objectRef(imageId, METHOD_DICTIONARY_SHAPE_ID),
      nilRef: kernel.nil,
      metadata: {owner: behaviorRef.objectId, migratedFrom: dictionaryRef.objectId},
    }),
  });
  validateMethodDictionary(await images.getObject(imageId, stored.id), objectRef(imageId, stored.id), kernel.nil);

  // Step 4. One CAS on the Behavior's methods edge. A reader sees the complete legacy dictionary or
  // the complete hashed one; the sealed legacy record stays readable and dispatchable until this
  // lands, so a crash here is a visible stall rather than a broken class.
  try {
    await images.putObject(imageId, {
      id: behaviorRecord.id,
      shape: behaviorRecord.shape,
      behavior: behaviorRecord.behavior,
      slots: {...behaviorRecord.slots, 'behavior-methods': objectRef(imageId, stored.id)},
      metadata: behaviorRecord.metadata,
    }, {expectedVersion: behaviorRecord._version});
  } catch (error) {
    if (error?.name === 'VersionConflictError') throw new SmalltalkMigrationConflictError('behavior', behaviorRef);
    throw error;
  }

  return Object.freeze({migrated: true, dictionary: objectRef(imageId, stored.id), from: dictionaryRef});
}

export {
  SmalltalkMigrationConflictError,
  ensureMethodDictionaryShape,
  migrateMethodDictionary,
};

import {SHAPE_INDEXED} from '../object/model.js';
import {VALUE_KIND, integerValue, isObjectRef} from '../value/index.js';
import {builtInEquals, builtInHash} from './smalltalk-equality.js';
import {
  DICTIONARY_MINIMUM_CAPACITY,
  bucketsFromIndexed,
  capacityOf,
  emptyBuckets,
  grownCapacity,
  indexedFromBuckets,
  needsGrowth,
  probeSequence,
  reinsert,
  tallyOf,
} from './smalltalk-dictionary-table.js';

// ADR 0049. The selector-to-Block mapping that dispatch reads, as a fixed-Shape kernel
// representation rather than a Smalltalk class.
//
// The whole file is pure with respect to Smalltalk: nothing here sends a message, so lookup cannot
// re-enter the dispatcher while it is trying to find the method a send would run. That is the
// property ADR 0048 decision 12 promised and the reason this is not an ordinary Dictionary — a
// Dictionary must honour an overridden `hash`/`=`, and a dispatcher must not.
const METHOD_DICTIONARY_SHAPE_ID = 'smalltalk/method-dictionary-shape/v1';
const METHOD_DICTIONARY_TALLY_SLOT = 'method-dictionary-tally';
const METHOD_DICTIONARY_SHAPE_SLOTS = Object.freeze([
  {id: METHOD_DICTIONARY_TALLY_SLOT, name: 'tally'},
]);

// ADR 0049 decision 7. Migration is one-shot per Behavior, so its output is a named durable thing
// and gets a deterministic id — the opposite of ADR 0048's per-snapshot fresh identity, and for the
// opposite reason: a retry must find its own previous output instead of leaving another orphan.
const migratedDictionaryId = (behaviorObjectId) => `${behaviorObjectId}/methods/hashed/v1`;

class SmalltalkMalformedMethodDictionaryError extends TypeError {
  constructor(ref, reason) {
    super(`malformed method dictionary ${ref.imageId}/${ref.objectId}: ${reason}`);
    this.name = 'SmalltalkMalformedMethodDictionaryError';
    this.dictionary = ref;
  }
}

// ADR 0049 decision 2: recognition is by the *local* fixed Shape. Another image may hold its own
// Shape at this id, so identity is the (imageId, objectId) pair — the same rule `isBehaviorObject`
// applies to the Behavior shape.
function isMethodDictionary(record) {
  return Boolean(record)
    && record.kind === 'object'
    && isObjectRef(record.shape)
    && record.shape.imageId === record.imageId
    && record.shape.objectId === METHOD_DICTIONARY_SHAPE_ID;
}

const isIntegerValue = (value) => Boolean(value) && value.kind === VALUE_KIND.INTEGER;
const isTextValue = (value) => Boolean(value) && value.kind === VALUE_KIND.TEXT;

// The full structural validation of decision 5, run once per record version behind the cache of
// decision 5a. Everything it checks is a way a record could physically hide a method while looking
// like an ordinary selector miss, which is the failure the malformed/not-understood split exists to
// prevent.
function sameRefValue(left, right) {
  return isObjectRef(left) && isObjectRef(right)
    && left.imageId === right.imageId && left.objectId === right.objectId;
}

function validateMethodDictionary(record, ref, nilRef) {
  const fail = (reason) => {
    throw new SmalltalkMalformedMethodDictionaryError(ref ?? {imageId: record?.imageId, objectId: record?.id}, reason);
  };
  if (!isObjectRef(nilRef)) fail('validation needs this image kernel nil to recognize an empty bucket');

  // Decision 3: a behavior edge would make this dispatchable, which is exactly the dynamic protocol
  // decision 2 denies it. Structural, not conventional.
  if (record.behavior !== null && record.behavior !== undefined) fail('a method dictionary must have no behavior edge');
  if (!Object.hasOwn(record, 'indexed')) fail('a method dictionary must carry an indexed part');

  let capacity;
  try {
    capacity = capacityOf(record.indexed.length);
  } catch (error) {
    fail(error.message);
  }

  // The raw triples, *before* the shared parser sees them. `bucketsFromIndexed` reads any non-Integer
  // hash cell as an empty bucket, which is right for a table this code built and wrong as a
  // validation input: a corrupted hash cell would become an "empty" bucket, the evidence would be
  // gone before this function could reject it, and - because an empty bucket ends a probe - the
  // selector would vanish and report as an ordinary message-not-understood.
  //
  // So occupancy is decided here, from the cell's actual kind, and anything that is neither a
  // well-formed occupied triple nor a well-formed empty one is corruption.
  for (let index = 0; index < record.indexed.length; index += 3) {
    const [hash, key, method] = record.indexed.slice(index, index + 3);
    const bucket = index / 3;
    if (isIntegerValue(hash)) {
      if (!isTextValue(key)) fail(`bucket ${bucket} selector must be a Text Value`);
      if (key.value.length === 0) fail(`bucket ${bucket} selector must not be empty`);
      if (!isObjectRef(method)) fail(`bucket ${bucket} method must be an unpinned ref`);
      if (method.imageId !== record.imageId) fail(`bucket ${bucket} method must be local to ${record.imageId}`);
      continue;
    }
    // An empty bucket is all three cells holding this image's nil, and nothing else. Comparing the
    // full ref rather than an object id keeps a foreign `smalltalk/nil` from passing as empty.
    if (!sameRefValue(hash, nilRef) || !sameRefValue(key, nilRef) || !sameRefValue(method, nilRef)) {
      fail(`bucket ${bucket} is neither an occupied triple nor an empty one`);
    }
  }

  const buckets = bucketsFromIndexed(record.indexed);
  const tally = record.slots?.[METHOD_DICTIONARY_TALLY_SLOT];
  if (!isIntegerValue(tally)) fail('tally must be an Integer Value');
  if (BigInt(tally.value) !== BigInt(tallyOf(buckets))) {
    fail(`tally ${tally.value} disagrees with ${tallyOf(buckets)} occupied buckets`);
  }

  const seen = new Set();
  for (const [index, bucket] of buckets.entries()) {
    if (bucket.hash === null) continue;
    // The stored hash must be the built-in hash of the stored selector, or a probe would look in
    // the wrong place for a selector that is physically present.
    const expected = builtInHash(bucket.key);
    if (BigInt(bucket.hash.value) !== BigInt(expected.value)) {
      fail(`bucket ${index} stores hash ${bucket.hash.value} for selector ${bucket.key.value}`);
    }
    // Two buckets holding one selector make one method unreachable — the ADR 0044 decision 2 defect
    // in the new format, where it would resolve by probe order instead of by slot order.
    if (seen.has(bucket.key.value)) fail(`selector ${bucket.key.value} appears in more than one bucket`);
    seen.add(bucket.key.value);
  }

  // Probe reachability. An occupied bucket separated from its home by an empty bucket is invisible
  // to lookup, which would read as an ordinary miss rather than as the corruption it is.
  for (const [index, bucket] of buckets.entries()) {
    if (bucket.hash === null) continue;
    let reachable = false;
    for (const probe of probeSequence(bucket.hash, capacity)) {
      if (probe === index) {
        reachable = true;
        break;
      }
      if (buckets[probe].hash === null) break;
    }
    if (!reachable) fail(`bucket ${index} is unreachable from its own probe sequence`);
  }

  return {buckets, capacity, tally: tallyOf(buckets)};
}

// Decision 5: pure hash, pure probe, pure comparison. No send anywhere on this path.
function lookupSelectorInTable({buckets, capacity}, selectorValue) {
  const hash = builtInHash(selectorValue);
  for (const index of probeSequence(hash, capacity)) {
    const bucket = buckets[index];
    if (bucket.hash === null) return null;
    if (BigInt(bucket.hash.value) === BigInt(hash.value) && builtInEquals(bucket.key, selectorValue)) {
      return bucket.value;
    }
  }
  return null;
}

function capacityForEntries(count) {
  let capacity = DICTIONARY_MINIMUM_CAPACITY;
  while (needsGrowth(count, capacity)) capacity = grownCapacity(capacity);
  return capacity;
}

// Build a complete set of buckets from `[selectorTextValue, methodRef]` pairs. Used by creation,
// by every method addition, and by migration, so all three produce byte-identical layouts for the
// same selector set — which is what makes the deterministic migration target reusable on retry.
function buildMethodBuckets(entries) {
  const capacity = capacityForEntries(entries.length);
  let buckets = emptyBuckets(capacity);
  const placed = new Set();
  // Sorted, so the layout is a function of the selector set rather than of insertion order.
  const sorted = [...entries].sort(([left], [right]) => (left.value < right.value ? -1 : left.value > right.value ? 1 : 0));
  for (const [selector, method] of sorted) {
    if (placed.has(selector.value)) throw new TypeError(`method dictionary declares duplicate selector: ${selector.value}`);
    placed.add(selector.value);
    const hash = builtInHash(selector);
    let done = false;
    for (const index of probeSequence(hash, capacity)) {
      if (buckets[index].hash === null) {
        buckets[index] = {hash, key: selector, value: method};
        done = true;
        break;
      }
    }
    if (!done) throw new TypeError('no free bucket below the load factor, which cannot happen');
  }
  void reinsert;
  return {buckets, capacity};
}

function methodDictionaryRecordFields({buckets, shapeRef, nilRef, metadata = {}}) {
  return {
    shape: shapeRef,
    // No behavior: decision 3 makes its absence structural.
    slots: {[METHOD_DICTIONARY_TALLY_SLOT]: integerValue(tallyOf(buckets))},
    indexed: indexedFromBuckets(buckets, nilRef),
    metadata: {smalltalk: 'method-dictionary', ...metadata},
  };
}

function entriesFromBuckets(buckets) {
  return buckets.filter(({hash}) => hash !== null).map(({key, value}) => [key, value]);
}

// ADR 0049 decision 7. A seal is a durable marker saying "this record is being migrated and no
// longer accepts additions". It hides no ref, dispatch ignores it entirely, and only the method
// installer consults it.
const SEAL_METADATA_KEY = 'sealedForMigration';
const isSealed = (record) => record?.metadata?.[SEAL_METADATA_KEY] === true;

export {
  METHOD_DICTIONARY_SHAPE_ID,
  METHOD_DICTIONARY_SHAPE_SLOTS,
  METHOD_DICTIONARY_TALLY_SLOT,
  SEAL_METADATA_KEY,
  SHAPE_INDEXED,
  SmalltalkMalformedMethodDictionaryError,
  buildMethodBuckets,
  capacityForEntries,
  entriesFromBuckets,
  isMethodDictionary,
  isSealed,
  lookupSelectorInTable,
  methodDictionaryRecordFields,
  migratedDictionaryId,
  validateMethodDictionary,
};

import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';
import {isObjectRef} from '../value/index.js';

// Public authority vocabulary for reading the CURRENT native Smalltalk method at one logical
// position. The position is stable while immutable Block revisions change, and is nameable from
// the public semantic locator alone: image, declaring Class/Metaclass and selector. Naming it reads
// no graph state and discloses no method existence.
//
// Every input is arbitrary text. Encoding each part independently is mandatory: joining raw text
// would let separators in one part collide with separators between parts. base64url excludes `.`,
// so the three-part encoding is injective by construction.
const SMALLTALK_METHOD_POSITION_RESOURCE_V0 = 'smalltalk-method-position-resource/v0';
const SMALLTALK_METHOD_READ_OPERATION = 'smalltalk-method/read';
const PART_SEPARATOR = '.';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function encodePart(value) {
  return base64urlEncode(utf8Encode(value));
}

function smalltalkMethodPositionResource(imageId, classRef, selector) {
  const localImageId = requiredText(imageId, 'method position resource imageId');
  if (!isObjectRef(classRef) || classRef.imageId !== localImageId) {
    throw new TypeError(`method position resource classRef must be an unpinned object ref in ${localImageId}`);
  }
  return [
    encodePart(localImageId),
    encodePart(requiredText(classRef.objectId, 'method position resource class objectId')),
    encodePart(requiredText(selector, 'method position resource selector')),
  ].join(PART_SEPARATOR);
}

export {
  SMALLTALK_METHOD_POSITION_RESOURCE_V0,
  SMALLTALK_METHOD_READ_OPERATION,
  smalltalkMethodPositionResource,
};

import {objectResource} from '../authority/object-resource.js';
import {isObjectRef, objectRef} from '../value/index.js';
import {base64urlDecode, base64urlEncode, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';

// Opaque optimistic-concurrency token for a native Smalltalk METHOD POSITION (bead
// lagrange-images-qax, Object Environment E3).
//
// ADR 0086 already decided what a method position is: `{Class/Metaclass, selector}` is the logical
// position, and the Block currently bound there is that position's immutable current revision. So
// this token represents the observed state of THAT position and nothing wider.
//
// NOT WHOLE-DICTIONARY. A MethodDictionary-scoped token would make an unrelated actor editing `bar`
// invalidate a token read for `foo`, which publishes storage transaction granularity as semantic
// concurrency granularity. The dictionary CAS remains the persistence mechanism underneath; that is
// an implementation fact and deliberately not what this token means.
//
// NOT THE BLOCK REF. A token that WAS the ref would be indistinguishable from something the browse
// seam already hands out, so it could not express an assumption ABOUT that ref — which is the whole
// job. The observed binding is one of the things this token is scoped to, not the token itself, and
// the token is useless as a ref: it names a position as well as a revision, and a caller cannot
// pass it anywhere a ref is expected.
//
// Opacity here is a CONTRACT, not a secret. This module is internal to the language owner and is
// not published through the public roots, so a caller receives tokens and returns them; it is not
// claimed that the format is underivable by someone who reimplements it.
//
//   token scoped to a position + its observed revision  !=  token is either of those
//
// The caller still supplies the class and selector separately; the token confirms an assumption
// rather than naming a target. A token minted for another class or another selector is REFUSED
// rather than reinterpreted, and the refusal discloses nothing about that other position.
//
// Callers may compare and round-trip a token. They must not interpret, order or do arithmetic on
// one. No MethodDictionary version, no backend `_version` and no storage identity appears in it —
// the only revision-bearing thing inside is the immutable revision identity ADR 0086 already made
// public through the browse seam.
const SMALLTALK_METHOD_POSITION_TOKEN_V0 = 'smalltalk-method-position/v0';
// `objectResource`'s own separator; base64url excludes it, which is what keeps the pair recoverable.
const OBSERVED_SEPARATOR = '.';

class SmalltalkMethodPositionTokenError extends TypeError {
  constructor(message) {
    super(message);
    this.name = 'SmalltalkMethodPositionTokenError';
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new SmalltalkMethodPositionTokenError(`${label} must be a non-empty string`);
  }
  return value;
}

// The value owner decides what an unpinned object ref is; hand-rolling the check would admit a
// ref-shaped object carrying extra keys.
function assertRef(ref, label) {
  if (!isObjectRef(ref)) {
    throw new SmalltalkMethodPositionTokenError(`${label} must be an unpinned object ref`);
  }
  requiredText(ref.imageId, `${label} imageId`);
  requiredText(ref.objectId, `${label} objectId`);
  return ref;
}

// The position half: which image, which Behavior, which selector.
//
// The class ref must be LOCAL to the image, exactly as the browse seam requires of a class ref, so
// that `classRef.imageId` is part of the identity rather than an ignored field. Without this a
// token minted for `{app, C}` would be accepted against `{app, elsewhere/C}` — a position the seam
// itself would refuse as malformed — because only the objectId would have been compared.
//
// Every part goes through `objectResource`, never string concatenation. `object-resource.js` says
// why in terms: neither an imageId nor an objectId forbids a separator, so a hand-built name is not
// injective, and base64url is used precisely because its alphabet excludes the separator. That rule
// applies to a selector and to a method ref just as much as to an object resource, so nothing here
// is joined by hand.
function positionScope(imageId, classRef, selector) {
  requiredText(imageId, 'method position imageId');
  assertRef(classRef, 'method position class');
  if (classRef.imageId !== imageId) {
    throw new SmalltalkMethodPositionTokenError(
      `method position class ${classRef.imageId}/${classRef.objectId} is not local to ${imageId}`,
    );
  }
  return `${objectResource(imageId, classRef.objectId)}`
    + `.${base64urlEncode(utf8Encode(requiredText(selector, 'method position selector')))}`;
}

// The observed half: the immutable current revision the caller read, named the same injective way.
// Encoded rather than embedded as a ref, so the token cannot be mistaken for one or used as one.
function observedRevision(method) {
  assertRef(method, 'method position binding');
  return objectResource(method.imageId, method.objectId);
}

function smalltalkMethodPositionToken({imageId, classRef, selector, method} = {}) {
  return `${SMALLTALK_METHOD_POSITION_TOKEN_V0}:${positionScope(imageId, classRef, selector)}`
    + `:${observedRevision(method)}`;
}

// Answers the observed binding ONLY when the token was issued for exactly this position. A token
// for another class or selector is rejected rather than reinterpreted, and the caller learns
// nothing about that other position from the failure.
function parseSmalltalkMethodPositionToken(token, {imageId, classRef, selector} = {}) {
  const text = requiredText(token, 'method position token');
  const parts = text.split(':');
  if (parts.length !== 3 || parts[0] !== SMALLTALK_METHOD_POSITION_TOKEN_V0) {
    throw new SmalltalkMethodPositionTokenError(`malformed ${SMALLTALK_METHOD_POSITION_TOKEN_V0} token`);
  }
  if (parts[1] !== positionScope(imageId, classRef, selector)) {
    throw new SmalltalkMethodPositionTokenError(
      `${SMALLTALK_METHOD_POSITION_TOKEN_V0} token was issued for a different method position`,
    );
  }
  // A crafted token can carry text that is not base64url at all, and the decoder raises a plain
  // TypeError for it. That must not cross this seam: a malformed token is a malformed TOKEN, an
  // Images-native semantic outcome, not a foreign error from a byte helper.
  //
  // The re-encode is the same canonicality guard `version-token.js` and `object-resource.js` apply,
  // and for the same reason: base64 decoding silently drops leftover bits, so several distinct
  // texts decode alike and a mutated token would otherwise parse as a valid one.
  let observed;
  try {
    const [image, object] = parts[2].split(OBSERVED_SEPARATOR);
    const decodedImage = utf8DecodeLossy(base64urlDecode(image));
    const decodedObject = utf8DecodeLossy(base64urlDecode(object));
    observed = Object.freeze({imageId: decodedImage, objectId: decodedObject});
  } catch {
    throw new SmalltalkMethodPositionTokenError(`malformed ${SMALLTALK_METHOD_POSITION_TOKEN_V0} token`);
  }
  if (observed.imageId.length === 0 || observed.objectId.length === 0
    || observedRevision(objectRef(observed.imageId, observed.objectId)) !== parts[2]) {
    throw new SmalltalkMethodPositionTokenError(`malformed ${SMALLTALK_METHOD_POSITION_TOKEN_V0} token`);
  }
  return observed;
}

export {
  SMALLTALK_METHOD_POSITION_TOKEN_V0,
  SmalltalkMethodPositionTokenError,
  parseSmalltalkMethodPositionToken,
  smalltalkMethodPositionToken,
};

import {LAGRANGE_CODE_V0} from '../code/lagrange-code-v0.js';
import {LAGRANGE_CODE_V1, LAGRANGE_CODE_V2} from '../code/lagrange-code-v1.js';
import {NEUTRAL_EXPRESSION_V0} from '../execution/neutral-expression-v0.js';
import {NEUTRAL_EXPRESSION_V1, NEUTRAL_EXPRESSION_V2} from '../execution/neutral-expression-v1.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {objectRef, textValue} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// Nested Block publication, shared by standalone Block installation and by method installation.
//
// One implementation on purpose. Two recursive installers would eventually disagree about v0/v1
// selection, capture handling, deterministic ids or which executable target a nested Block gets —
// and the disagreement would surface as a Block that runs correctly in one path and not the other.
//
// Every write is ensure-exact-or-create, because a method's nested ids are derived from the method's
// own deterministic id: a partial install must converge on an identical retry rather than collide
// with its own earlier output.

// The semantic representation is chosen once for the whole tree, so the executable target follows
// from it rather than being decided independently per node.
const EXECUTABLE_TARGET = Object.freeze({
  [LAGRANGE_CODE_V0]: NEUTRAL_EXPRESSION_V0,
  [LAGRANGE_CODE_V1]: NEUTRAL_EXPRESSION_V1,
  [LAGRANGE_CODE_V2]: NEUTRAL_EXPRESSION_V2,
});

function executableTargetFor(representation) {
  const target = EXECUTABLE_TARGET[representation];
  if (!target) throw new TypeError(`no executable target for semantic representation ${representation}`);
  return target;
}

function blockSuffix(blockId) {
  return blockId.replace(/[^A-Za-z0-9_-]+/g, '_');
}

function directNestedBlocks(expression, result = []) {
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) return result;
  switch (expression.op) {
    case 'block':
      result.push(expression);
      return result;
    case 'send':
      directNestedBlocks(expression.receiver, result);
      for (const argument of expression.arguments) directNestedBlocks(argument, result);
      return result;
    case 'apply':
      directNestedBlocks(expression.callee, result);
      for (const argument of expression.arguments) directNestedBlocks(argument, result);
      return result;
    // A Block is very often the right-hand side of an assignment or a statement of a sequence, so
    // omitting these would silently install no prototype for it.
    case 'binding-write':
      directNestedBlocks(expression.value, result);
      return result;
    case 'sequence':
      for (const statement of expression.statements) directNestedBlocks(statement, result);
      return result;
    case 'integer-add':
    case 'equals':
      directNestedBlocks(expression.left, result);
      directNestedBlocks(expression.right, result);
      return result;
    case 'if':
      directNestedBlocks(expression.condition, result);
      directNestedBlocks(expression.then, result);
      directNestedBlocks(expression.else, result);
      return result;
    default:
      return result;
  }
}

// Nested identity is derived from the root's identity plus the *semantic* block id, so a method's
// nested Blocks inherit the method's deterministic naming and a rebuild lands on the same records.
function nestedIds(rootId, blockId) {
  const suffix = blockSuffix(blockId);
  return Object.freeze({
    semanticId: `${rootId}:semantic:${suffix}`,
    codeId: `${rootId}:code:${suffix}`,
    prototypeId: `${rootId}:prototype:${suffix}`,
  });
}

async function installNestedPrototypes({
  images,
  compilation,
  imageId,
  rootId,
  parentSemanticRef,
  program,
  representation,
  languageId = SYMMETRIC_SMALLTALK_ID,
}) {
  const prototypes = {};
  for (const nested of directNestedBlocks(program.body)) {
    const ids = nestedIds(rootId, nested.blockId);
    const semanticArtifact = await ensureCodeArtifact(images, imageId, {
      id: ids.semanticId,
      languageId,
      representation,
      content: textValue(JSON.stringify(nested.program)),
      derivedFrom: [parentSemanticRef],
      metadata: {semanticBlockId: nested.blockId},
    });
    // Depth first: a child's prototype must exist before its parent's executable artifact names it.
    const childPrototypes = await installNestedPrototypes({
      images,
      compilation,
      imageId,
      rootId,
      parentSemanticRef: objectRef(imageId, semanticArtifact.id),
      program: nested.program,
      representation,
      languageId,
    });
    const codeArtifact = await compilation.compileArtifact(
      objectRef(imageId, semanticArtifact.id),
      {
        id: ids.codeId,
        targetRepresentation: executableTargetFor(representation),
        options: {blockPrototypes: childPrototypes},
        metadata: {semanticBlockId: nested.blockId},
      },
    );
    const prototype = await ensureBlock(images, imageId, {
      id: ids.prototypeId,
      code: objectRef(imageId, codeArtifact.id),
      metadata: {prototype: true, semanticBlockId: nested.blockId},
    });
    prototypes[nested.blockId] = objectRef(imageId, prototype.id);
  }
  return Object.freeze(prototypes);
}

export {
  EXECUTABLE_TARGET,
  blockSuffix,
  directNestedBlocks,
  executableTargetFor,
  installNestedPrototypes,
  nestedIds,
};

// Native `Point`, added because a real imported consumer names it: the pinned upstream Cuis Life
// package constructs and decomposes grid positions in its own unchanged code (`LifeModel>>
// surrounding:` sends `Point x: y:` and `x@`-adjacent arithmetic, and `LifeArray>>at:` reads
// `x`/`y`). The native compiler otherwise answered `unbound Symmetric Smalltalk name: Point`.
// This is an ordinary native Smalltalk class published as an ordinary global — NOT a Cuis
// compatibility class; the Cuis import adapter resolves the name through the image's global
// namespace exactly as it resolves `Array`.
//
// SCOPE. Exactly the protocol the acceptance path sends, and nothing more:
//
//   Point class >> x:y:          the position constructor the source builds
//   Point       >> x / y         the coordinate readers the source reads
//   Point       >> isPoint       measured Cuis type query (Object>>isPoint answers false)
//   Point       >> initializePvtX:y:  the measured private Cuis initializer
//
// RECORDED REAL-CUIS ORACLE (pinned Cuis7.8.sources / 7.9 image, read out of the pinned sources,
// not recollected):
//
//   Point class>>x:y:   ^self new initializePvtX: anX y: anY
//   Point>>x            ^x        (direct ivar accessors)
//   Point>>y            ^y
//   Point>>isPoint      ^ true
//   Object>>isPoint     ^ false
//   Integer>>@          <primitive 18> fallback ^Point x: self y: y
//
// `* +` and the full Cuis point-arithmetic table remain absent. Execution pressure adds
// protocol one proven consumer at a time. `Integer>>@` is installed here (as the measured
// construction entry, the same ownership lane as `Array>>asSet` living with the Set owner) in a
// separate composition stage AFTER `Point` is published, because its body names the `Point` global.
import {ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {objectRef} from '../value/index.js';

const POINT_SHAPE_ID = 'smalltalk/point-instance-shape/v1';

const POINT_CLASS_METHODS = Object.freeze([
  {selector: 'x:y:', source: '[ :anX :anY | | p | p := self new. p initializePvtX: anX y: anY. ^ p ]'},
]);

const POINT_METHODS = Object.freeze([
  {selector: 'initializePvtX:y:', source: '[ :xValue :yValue | x := xValue. y := yValue ]'},
  {selector: 'x', source: '[ ^x ]'},
  {selector: 'y', source: '[ ^y ]'},
  {selector: 'isPoint', source: '[ ^ true ]'},
]);

const INTEGER_AT_METHOD = Object.freeze({
  selector: '@',
  source: '[ :y | ^ Point x: self y: y ]',
});

const OBJECT_IS_POINT_METHOD = Object.freeze({
  selector: 'isPoint',
  source: '[ ^ false ]',
});

async function installSmalltalkPointProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  const instanceShapeRef = await ensureSmalltalkShape(images, imageId, {
    id: POINT_SHAPE_ID, slots: [{id: 'point-x', name: 'x'}, {id: 'point-y', name: 'y'}],
  });
  const {classRef, metaclassRef} = await ensureNamedClass({
    images, imageId, name: 'Point', superclassRef: objectRef(imageId, 'smalltalk/class/Object'), instanceShapeRef,
  });
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef: metaclassRef, methods: POINT_CLASS_METHODS});
  await defineMethodsFromSource({images, compilation, imageId, lane, classRef, methods: POINT_METHODS});
  return Object.freeze({classRef, metaclassRef});
}

// Composition stage, after Point is published through the namespace: naming it in ordinary
// source preserves GlobalBinding dereference semantics at runtime.
async function installSmalltalkPointConstructionProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/class/Object'),
    methods: [OBJECT_IS_POINT_METHOD],
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/class/Integer'),
    methods: [INTEGER_AT_METHOD],
  });
}

export {POINT_SHAPE_ID, POINT_CLASS_METHODS, POINT_METHODS, INTEGER_AT_METHOD, OBJECT_IS_POINT_METHOD, installSmalltalkPointProtocol, installSmalltalkPointConstructionProtocol};

import {EXCEPTION_SHAPE_ID} from './smalltalk-condition-ids.js';
import {
