// ADR 0089. The one primitive whose argument count is not fixed, because the message it forwards is
// not fixed: `super foo`, `super + x` and `super at: k put: v` are one operation with one, two and
// three arguments. Spelled as an explicit set rather than by giving the arity map a second shape, so
// every other primitive keeps its exact-arity guard untouched and the variadic case is enumerable.
const SMALLTALK_PRIMITIVE_VARIADIC = Object.freeze(new Set([SMALLTALK_PRIMITIVE.SUPER_SEND]));

// One locality rule for every primitive. A foreign primitive Block must fail rather than answer a
// foreign kernel's class, allocate into somebody else's image, or mutate a foreign indexed object.
class SmalltalkPrimitiveLocalityError extends TypeError {
  constructor(primitive, primitiveImage, ref) {
    super(
      `Symmetric Smalltalk ${primitive} primitive in ${primitiveImage} cannot act on `
      + `${ref.imageId}/${ref.objectId}; a primitive is local to its own image`,
    );
    this.name = 'SmalltalkPrimitiveLocalityError';
    this.primitive = primitive;
    this.primitiveImage = primitiveImage;
  }
}

class SmalltalkPrimitiveReceiverError extends TypeError {
  constructor(primitive, description) {
    super(`Symmetric Smalltalk ${primitive} primitive cannot act on ${description}`);
    this.name = 'SmalltalkPrimitiveReceiverError';
    this.primitive = primitive;
  }
}

function parsePrimitiveCode(code) {
  if (code.content?.kind !== VALUE_KIND.TEXT) {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must be a text Value`);
  }
  let declaration;
  try {
    declaration = JSON.parse(code.content.value);
  } catch (error) {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must contain valid JSON`, {cause: error});
  }
  const keys = Object.keys(declaration ?? {});
  if (keys.length !== 1 || keys[0] !== 'primitive') {
    throw new TypeError(`${SMALLTALK_KERNEL_PRIMITIVE_V1} content must contain exactly primitive`);
  }
  if (!SMALLTALK_PRIMITIVE_NAMES.includes(declaration.primitive)) {
    throw new TypeError(`unknown ${SMALLTALK_KERNEL_PRIMITIVE_V1} primitive: ${declaration.primitive}`);
  }
  return declaration.primitive;
}

function primitiveCodeContent(primitive) {
  if (!SMALLTALK_PRIMITIVE_NAMES.includes(primitive)) {
    throw new TypeError(`unknown ${SMALLTALK_KERNEL_PRIMITIVE_V1} primitive: ${primitive}`);
  }
  return JSON.stringify({primitive});
}

function assertLocalRef(value, primitiveImage, primitive, description) {
  if (!isObjectRef(value)) {
    throw new SmalltalkPrimitiveReceiverError(
      primitive,
      value?.kind ? `a ${value.kind} Value; ${description}` : `a non-ref; ${description}`,
    );
  }
  if (value.imageId !== primitiveImage) {
    throw new SmalltalkPrimitiveLocalityError(primitive, primitiveImage, value);
  }
  return value;
}

// ADR 0052 decision 6: writing into a slot, an indexed part or a Dictionary makes a value durably
// reachable, so it is an escape. Each of these boundaries rewrites the value through the one central
// promoter and then performs its existing write unchanged — the promotion is the boundary's job, not
// the graph guard's.
//
// A context without `promote` is an execution that predates this seam rather than an error: the
// value passes through, and the graph guard still refuses a transient ref, so a missed boundary
// fails loudly instead of silently persisting a dangling reference.
//
// ADR 0060: a slot or indexed write is a durability boundary *only when the receiver is durable*.
// Writing a transient value into a transient receiver keeps both inside the arena — nothing has
// escaped yet — so the value must NOT be promoted, or every `OrderedCollection`'s backing store
// would become durable the instant it is assigned. `receiver` is the object being written into;
// when it is a transient ref the write stays in the arena and the value passes through unpromoted.
async function promoted(context, value, receiver = null) {
  if (typeof context?.promote !== 'function') return value;
  if (receiver !== null && isTransientRef(receiver)) return value;
  return await context.promote(value);
}

function requireSendMessage(context, primitive, purpose = 'send hash and =') {
  if (typeof context?.sendMessage !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a message runtime to ${purpose}`);
  }
  return context.sendMessage;
}

// ADR 0089. Deliberately NOT `sendMessage`: this activates a method the LANGUAGE already resolved,
// and re-entering ordinary dispatch would look the selector up again from the receiver's own
// Behavior — the exact starting point a super send exists to avoid.
function requireInvokeResolvedMethod(context, primitive, purpose = 'activate the method it resolved') {
  if (typeof context?.invokeResolvedMethod !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a message runtime to ${purpose}`);
  }
  return context.invokeResolvedMethod;
}

// ADR 0054 decision 8. A host failure that has a condition class becomes an ordinary Smalltalk
// signal, so it is catchable — and resumable, since a handler's `resume:` answers the operation.
//
// Absent the condition protocol, the host error is thrown as before. That is what keeps an image
// without ADR 0054 working unchanged rather than acquiring a dependency it never installed.
async function signalHostCondition({
  images, primitiveImage, context, classId, hostError, newObjectId, maxIdentityAttempts,
}) {
  const facade = context?.conditions;
  const sendMessage = context?.sendMessage;
  if (!facade || typeof sendMessage !== 'function') throw hostError;
  const classRecord = await images.getObject(primitiveImage, classId);
  if (!classRecord) throw hostError;

  // ADR 0060 decision 2: a condition created, signalled, handled and discarded inside one execution
  // never leaves the arena, so a handled condition costs no durable object. An unhandled one
  // crosses the root boundary and is promoted there — exactly when its information must outlive
  // the execution. Minted into the arena like `basicNew`; the record form below is unchanged, so
  // promotion is a copy.
  if (typeof context?.mintObject === 'function') {
    const instanceRef = context.mintObject({
      imageId: primitiveImage,
      shape: objectRef(primitiveImage, EXCEPTION_SHAPE_ID),
      behavior: objectRef(primitiveImage, classId),
      slots: {'exception-message-text': textValue(hostError.message)},
      metadata: {},
    });
    // An ordinary send, exactly as below — the receiver is the arena ref, resolved arena-first.
    return await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: instanceRef,
      message: textValue('signal'),
      arguments: [],
    });
  }

  // ADR 0054 decision 1a: a condition is an ordinary object, so it is allocated by ordinary rules —
  // including ADR 0046's identity retry. Writing once at `expectedVersion: 0` would turn an id
  // collision into a failure where every other allocation simply picks another candidate.
  const instance = await (async () => {
    for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
      const candidate = newObjectId();
      if (typeof candidate !== 'string' || candidate.length === 0) {
        throw new TypeError('Smalltalk object identity generator must answer non-empty text');
      }
      try {
        return await images.putObject(primitiveImage, {
          id: candidate,
          shape: objectRef(primitiveImage, EXCEPTION_SHAPE_ID),
          behavior: objectRef(primitiveImage, classId),
          slots: {'exception-message-text': textValue(hostError.message)},
          metadata: {},
        }, {expectedVersion: 0});
      } catch (error) {
        if (error?.name !== 'VersionConflictError') throw error;
      }
    }
    throw new TypeError(
      `Symmetric Smalltalk could not find a free object identity in ${primitiveImage} `
      + `after ${maxIdentityAttempts} attempts`,
    );
  })();

  // An ordinary send, so the handler search, the transfer protocol and resumption are exactly the
  // ones Smalltalk code gets — this is not a second signalling path.
  return await sendMessage({
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: objectRef(primitiveImage, instance.id),
    message: textValue('signal'),
    arguments: [],
  });
}

// ADR 0051 decision 4. Every other primitive is applied as `aPrimitive value: x`, so
// `assertBlockApplicationReceiver` can demand that the activation's receiver *is* the Block. A loop
// primitive is dispatched instead, with the condition Block as receiver, so that guard cannot apply
// and something must replace it — otherwise `aLoopPrimitive value: aBlock` would arrive with the
// primitive itself as the condition, which is precisely the bypass the structural rule below closes.
//
// "Kernel-primitive Block" is the existing structural test and nothing else: the Block's CodeArtifact
// has representation `smalltalk-kernel-primitive/v1`. That is already how the dispatcher decides
// frame inheritance for a Block send, so this reuses a definition the system depends on rather than
// adding a second, weaker notion of "is a primitive" that the two could drift apart on.
//
// The Dictionary enumeration primitive shares this guard for its pair Block, for the same reason:
// a Block about to be applied on a primitive's behalf must not itself be a kernel primitive.
async function assertLoopBlock({images, value, primitive, role}) {
  // A direct `invokeBlock` leaves the receiver null, which `assertBlockApplicationReceiver` treats as
  // the legitimate direct-application case. For a loop primitive it is not legitimate at all: there
  // is no condition Block, so say that rather than failing later on an untagged value.
  if (value === null || value === undefined) {
    throw new SmalltalkPrimitiveReceiverError(
      primitive,
      `no ${role}; a loop primitive is reachable only by dispatching whileTrue: or whileFalse:`,
    );
  }
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${ref.kind} Value as the ${role}`);
  }
  const block = await images.getBlock(ref.imageId, ref.objectId);
  if (!block) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `${ref.imageId}/${ref.objectId} as the ${role}, which is not a Block`);
  }
  const code = block.code && await images.getCodeArtifact(block.code.imageId, block.code.objectId);
  if (code?.representation === SMALLTALK_KERNEL_PRIMITIVE_V1) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a kernel-primitive Block as the ${role}`);
  }
  return ref;
}

export {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  SMALLTALK_PRIMITIVE_ARITY,
  SMALLTALK_PRIMITIVE_NAMES,
  SMALLTALK_PRIMITIVE_VARIADIC,
  SmalltalkPrimitiveLocalityError,
  SmalltalkPrimitiveReceiverError,
  assertLocalRef,
  assertLoopBlock,
  parsePrimitiveCode,
  primitiveCodeContent,
  promoted,
  requireInvokeResolvedMethod,
  requireSendMessage,
  signalHostCondition,
};

import {base64Decode, bytesEqual, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';
import {
  VALUE_KIND,
  bytesValue,
  canonicalizeValue,
  integerValue,
  textValue,
} from '../value/index.js';
import {SmalltalkPrimitiveReceiverError} from './smalltalk-primitive-support.js';

// WS3 Text/ByteArray slice: a tiny byte-sequence primitive family over the
// native immutable Value representations.
//
// A Text Value (`{kind:'text', value}`) and an immediate bytes Value
// (`{kind:'bytes', base64}`) are *physically different models* from Array's
// indexed-object storage (ADR 0047): the bytes Value is a Value, dispatching
// through the kernel's `ByteArray` class, not an indexed image object. The
// directive is explicit — do NOT widen the ADR 0047 indexed primitives
// (`indexed-size`/`indexed-at`) to bytes Values, and do NOT create a second
// ByteArray as an indexed image object. This family is the byte-sequence
// equivalent of `symbol-intern`/`class-of`: language-owned primitives over the
// native representations.
//
// UTF-8 is the only codec here, matching the upstream Pharo portable-util
// precedent (which overrides `bytesFromString:`/`stringFromBytes:` with an
// explicit UTF-8 codec rather than a generic `asByteArray`). `asByteArray` /
// `asString` are deliberately NOT defined as UTF-8 — encoding is dialect
// policy, not a default.
//
// Refusal rules (directives): malformed UTF-8 decode is refused, never
// lossy-replaced; an ill-formed/lone-surrogate Text source is refused, never
// silently substituted.

function requireText(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.TEXT) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} Value; ${primitive} requires a Text Value`);
  }
  return normalized.value;
}

function requireBytes(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.BYTES) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} Value; ${primitive} requires a ByteArray Value`);
  }
  return base64Decode(normalized.base64);
}

// A lone surrogate is ill-formed Unicode scalar data: there is no valid UTF-8
// encoding for it, so encode must refuse rather than emit a replacement char.
function assertWellFormedText(text, primitive) {
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = text.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) {
        throw new SmalltalkPrimitiveReceiverError(
          primitive, 'a Text Value containing a lone surrogate (ill-formed Unicode scalar data)',
        );
      }
      index += 1; // skip the low surrogate of a valid pair
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      throw new SmalltalkPrimitiveReceiverError(
        primitive, 'a Text Value containing a lone surrogate (ill-formed Unicode scalar data)',
      );
    }
  }
  return text;
}

// Strict UTF-8 decode: a lossy decode substitutes U+FFFD for malformed
// sequences, so decode is validated by re-encoding and comparing — any lossy
// substitution changes the bytes and is detected. Overlong forms and
// out-of-range sequences are likewise rejected by the round-trip check.
function decodeUtf8Strict(bytes, primitive) {
  const text = utf8DecodeLossy(bytes);
  if (!bytesEqual(utf8Encode(text), bytes)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, 'a malformed UTF-8 byte sequence; decode refused');
  }
  return text;
}

async function textUtf8Bytes({value}) {
  const text = assertWellFormedText(requireText(value, 'text-utf8-bytes'), 'text-utf8-bytes');
  return bytesValue(utf8Encode(text));
}

// The scalar counterpart of Text>>utf8Bytes, kept in this same codec owner and routed through the
// same portable utf8Encode operation. WriteStream is its first consumer: Character owns and
// discloses the valid scalar through ordinary `codePoint`; this operation owns only encoding that
// scalar as bytes. It is intentionally not Character protocol and knows no Character object shape,
// identity or image record.
async function unicodeScalarUtf8Bytes({value}) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError(
      'unicode-scalar-utf8-bytes', `a ${normalized.kind} Value; a Unicode scalar integer is required`,
    );
  }
  const scalar = BigInt(normalized.value);
  if (scalar < 0n || scalar > 0x10ffffn || (scalar >= 0xd800n && scalar <= 0xdfffn)) {
    throw new SmalltalkPrimitiveReceiverError(
      'unicode-scalar-utf8-bytes', `${scalar.toString()} is not a Unicode scalar value`,
    );
  }
  return bytesValue(utf8Encode(String.fromCodePoint(Number(scalar))));
}

async function byteArrayUtf8Text({value}) {
  const buffer = requireBytes(value, 'bytearray-utf8-text');
  return textValue(decodeUtf8Strict(buffer, 'bytearray-utf8-text'));
}

async function byteArraySize({value}) {
  return integerValue(requireBytes(value, 'bytearray-size').length);
}

async function byteArrayAt({value, indexValue}) {
  const buffer = requireBytes(value, 'bytearray-at');
  const normalized = canonicalizeValue(indexValue);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError('bytearray-at', `a ${normalized.kind} index; index must be an Integer Value`);
  }
  const oneBased = BigInt(normalized.value);
  // 1-based indexing, matching Array>>at: / Smalltalk collection convention.
  if (oneBased < 1n || oneBased > BigInt(buffer.length)) {
    throw new RangeError(
      `Symmetric Smalltalk bytearray-at index ${oneBased.toString()} is outside the 1..${buffer.length} range`,
    );
  }
  return integerValue(buffer[Number(oneBased) - 1]);
}

// `fromArray:` backing: an Array (or OrderedCollection's `asArray` result) of
// integer bytes -> a native bytes Value. Every element is validated 0..255 —
// a non-integer or out-of-range element is refused, never truncated.
async function arrayToByteArray({images, primitiveImage, value}) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.REF) {
    throw new SmalltalkPrimitiveReceiverError(
      'array-to-bytearray', `a ${normalized.kind} Value; the source must be an Array of integers`,
    );
  }
  const record = await images.getObject(primitiveImage, normalized.objectId);
  if (!record || !Array.isArray(record.indexed)) {
    throw new SmalltalkPrimitiveReceiverError(
      'array-to-bytearray', `${normalized.objectId}, which has no indexed integer storage`,
    );
  }
  const bytes = new Uint8Array(record.indexed.length);
  for (let index = 0; index < record.indexed.length; index += 1) {
    const element = canonicalizeValue(record.indexed[index]);
    if (element.kind !== VALUE_KIND.INTEGER) {
      throw new SmalltalkPrimitiveReceiverError(
        'array-to-bytearray', `an Array whose element ${index + 1} is a ${element.kind} Value, not an integer byte`,
      );
    }
    const byte = BigInt(element.value);
    if (byte < 0n || byte > 255n) {
      throw new RangeError(`Symmetric Smalltalk array-to-bytearray element ${index + 1} value ${byte.toString()} is not in 0..255`);
    }
    bytes[index] = Number(byte);
  }
  return bytesValue(bytes);
}

export {
  arrayToByteArray,
  byteArrayAt,
  byteArraySize,
  byteArrayUtf8Text,
  textUtf8Bytes,
  unicodeScalarUtf8Bytes,
};

import {
  VALUE_KIND,
  canonicalizeValue,
  integerValue,
  objectRef,
} from '../value/index.js';
import {ensureObject} from '../graph/ensure-records.js';
import {SmalltalkPrimitiveReceiverError} from './smalltalk-primitive-support.js';

// Character identity is language-owned, not a generic Value kind. The pinned Cuis oracle proves
// Characters distinct from both Integer and one-character String, while literal, indexed and
// streamed production of one code point answer equal and identical Characters. Deterministic
// image-local objects preserve precisely that contract and compose with ordinary Object identity.
const CHARACTER_CLASS_NAME = 'Character';
const CHARACTER_SHAPE_ID = 'smalltalk/character-shape/v1';
const CHARACTER_CODE_POINT_SLOT = 'character-code-point';

function scalarCodePoint(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError(
      primitive, `a ${normalized.kind} Value; the Character code point must be an Integer Value`,
    );
  }
  const codePoint = BigInt(normalized.value);
  if (codePoint < 0n || codePoint > 0x10ffffn || (codePoint >= 0xd800n && codePoint <= 0xdfffn)) {
    throw new RangeError(`Symmetric Smalltalk ${primitive} code point ${codePoint} is not a Unicode scalar value`);
  }
  return Number(codePoint);
}

function characterObjectId(codePoint) {
  const scalar = scalarCodePoint(integerValue(codePoint), 'character-identity');
  return `smalltalk/character/${scalar.toString(16)}`;
}

async function characterIntern({images, primitiveImage, value}) {
  const codePoint = scalarCodePoint(value, 'character-intern');
  const id = characterObjectId(codePoint);
  await ensureObject(images, primitiveImage, {
    id,
    shape: objectRef(primitiveImage, CHARACTER_SHAPE_ID),
    behavior: objectRef(primitiveImage, `smalltalk/class/${CHARACTER_CLASS_NAME}`),
    slots: {[CHARACTER_CODE_POINT_SLOT]: integerValue(codePoint)},
    metadata: {},
  });
  return objectRef(primitiveImage, id);
}

function textCodePoints(text, primitive) {
  const points = [];
  for (let index = 0; index < text.length;) {
    const codePoint = text.codePointAt(index);
    if (codePoint >= 0xd800 && codePoint <= 0xdfff) {
      throw new SmalltalkPrimitiveReceiverError(
        primitive, 'a Text Value containing a lone surrogate rather than Unicode scalar text',
      );
    }
    points.push(codePoint);
    index += codePoint > 0xffff ? 2 : 1;
  }
  return points;
}

function textSize({value}) {
  const text = canonicalizeValue(value);
  if (text.kind !== VALUE_KIND.TEXT) {
    throw new SmalltalkPrimitiveReceiverError(
      'text-size', `a ${text.kind} Value; the receiver must be a Text Value`,
    );
  }
  return integerValue(textCodePoints(text.value, 'text-size').length);
}

async function textAtCharacter({images, primitiveImage, value, indexValue}) {
  const text = canonicalizeValue(value);
  if (text.kind !== VALUE_KIND.TEXT) {
    throw new SmalltalkPrimitiveReceiverError(
      'text-at-character', `a ${text.kind} Value; the receiver must be a Text Value`,
    );
  }
  const index = canonicalizeValue(indexValue);
  if (index.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError(
      'text-at-character', `a ${index.kind} index; index must be an Integer Value`,
    );
  }
  const points = textCodePoints(text.value, 'text-at-character');
  const oneBased = BigInt(index.value);
  if (oneBased < 1n || oneBased > BigInt(points.length)) {
    throw new RangeError(
      `Symmetric Smalltalk text-at-character index ${oneBased} is outside the 1..${points.length} range`,
    );
  }
  return await characterIntern({
    images,
    primitiveImage,
    value: integerValue(points[Number(oneBased) - 1]),
  });
}

export {
  CHARACTER_CLASS_NAME,
  CHARACTER_CODE_POINT_SLOT,
  CHARACTER_SHAPE_ID,
  characterIntern,
  characterObjectId,
  textAtCharacter,
  textSize,
};

import {
  NoActiveOccurrenceError,
  UnhandledConditionError,
  performNonLocalReturn,
  runConditionHandler,
  runUnwindProtection,
  signalConditionOccurrence,
  transferConditionOccurrence,
} from '../execution/conditions.js';
import {sameRefIdentity} from './smalltalk-equality.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {behaviorRefFor} from './smalltalk-lookup.js';
import {
  SMALLTALK_PRIMITIVE,
  SmalltalkPrimitiveReceiverError,
  assertLoopBlock,
  requireSendMessage,
} from './smalltalk-primitive-support.js';
import {TupleSet} from '../support/tuple-map.js';
import {
  VALUE_KIND,
  canonicalizeValue,
  isObjectRef,
  textValue,
} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// The control-transfer primitives: loops (ADR 0051), unwind protection and the condition transfer
// protocol (ADR 0054), and non-local return (ADR 0055). Everything here manipulates activations and
// scopes rather than durable object state.

class SmalltalkUnhandledConditionError extends UnhandledConditionError {
  constructor(description) {
    super(description, `unhandled Smalltalk condition: ${description}`);
    this.name = 'SmalltalkUnhandledConditionError';
  }
}

class SmalltalkNoActiveOccurrenceError extends NoActiveOccurrenceError {
  constructor(operation) {
    super(operation);
    this.name = 'SmalltalkNoActiveOccurrenceError';
  }
}

// ADR 0055. `^ expr` lowers to `$nonLocalReturn value: expr`, so this primitive runs with the home
// method's frame already in hand: a kernel-primitive send INHERITS the caller's frame (ADR 0050 rule
// 2), and a closure activation RESTORES the frame it was created in (rule 3). Chained, those two
// rules hand it the home frame with no new propagation.
//
// It never catches its own transfer, because it only *borrows* that frame — decision 3a makes
// stopping the transfer the owner's job.
function nonLocalReturn({activation, context, primitive}) {
  return performNonLocalReturn({
    context,
    value: activation.arguments[0],
    requireConditionRuntimeMessage: `Symmetric Smalltalk ${primitive} primitive requires a condition runtime`,
  });
}

// ADR 0054. The unwind operations and the transfer protocol.
//
// All three Block operations share one shape: establish a scope on the execution's condition
// runtime, run the protected Block, and leave the scope on the way out however that happens.
function requireConditions(context, primitive) {
  const facade = context?.conditions;
  if (!facade || typeof facade.captureAuthority !== 'function' || typeof facade.invoke !== 'function') {
    throw new TypeError(`Symmetric Smalltalk ${primitive} primitive requires a condition runtime`);
  }
  return facade;
}

// A condition handles another when its class is the same or an ancestor. Walked through the ordinary
// Behavior chain, so a user-defined Exception subclass participates without the runtime knowing it
// exists.
async function conditionIsKindOf({images, conditionClass, candidateClass}) {
  let current = candidateClass;
  const seen = new TupleSet(2);
  while (isObjectRef(current)) {
    if (sameRefIdentity(current, conditionClass)) return true;
    if (seen.has([current.imageId, current.objectId])) return false;
    seen.add([current.imageId, current.objectId]);
    const behavior = await images.getObject(current.imageId, current.objectId);
    if (!behavior) return false;
    const superclass = behavior.slots?.['behavior-superclass'];
    current = isObjectRef(superclass) ? superclass : null;
  }
  return false;
}

async function classOfCondition({images, primitiveImage, condition}) {
  const {behavior} = await behaviorRefFor({images, receiver: condition, dispatchImage: primitiveImage});
  return behavior;
}

async function blockOnDo({images, activation, context, primitive}) {
  const protectedBlock = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'protected block',
  });
  const [conditionClass, handlerBlock] = activation.arguments;
  if (!isObjectRef(canonicalizeValue(conditionClass))) {
    throw new SmalltalkPrimitiveReceiverError(primitive, 'a non-class as the condition class');
  }
  const handler = await assertLoopBlock({images, value: handlerBlock, primitive, role: 'handler block'});
  const facade = requireConditions(context, primitive);
  // Captured here, at establishment: the handler runs with the rights in force where `on:do:` was
  // written, never with the signaller's.
  return await runConditionHandler({
    facade,
    conditionClass,
    handlerBlock: handler,
    protectedBlock,
  });
}

async function blockEnsure({images, activation, context, primitive, onlyWhenCurtailed}) {
  const protectedBlock = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'protected block',
  });
  const cleanupBlock = await assertLoopBlock({
    images, value: activation.arguments[0], primitive, role: 'cleanup block',
  });
  const facade = requireConditions(context, primitive);
  // Every non-normal exit, not only a catchable condition: a host trap crossing this scope travels
  // as an ordinary throw and must run the cleanup too. Protection that only fired for catchable
  // failures would stop working exactly when something unexpected happened.
  return await runUnwindProtection({
    facade,
    kind: primitive,
    protectedBlock,
    cleanupBlock,
    onlyWhenCurtailed,
  });
}

async function conditionSignal({images, primitiveImage, activation, context, primitive}) {
  const condition = canonicalizeValue(activation.arguments[0]);
  if (!isObjectRef(condition)) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${condition.kind} Value as the condition`);
  }
  const facade = requireConditions(context, primitive);
  const conditionClass = await classOfCondition({images, primitiveImage, condition});

  // A handler for class H catches a condition of class C when C is H or a subclass of it.
  return await signalConditionOccurrence({
    facade,
    condition,
    matches: async (handled) =>
      await conditionIsKindOf({images, conditionClass: handled, candidateClass: conditionClass}),
    describeCondition: () => {
      // Name the condition's CLASS, not only the instance. An unhandled condition is a diagnostic
      // that has to survive into a stack trace and a test assertion, and an object id alone says
      // nothing about what was signalled; the class is what a reader greps for.
      // A record may legitimately carry a null behavior, so this never assumes one; an unhandled
      // condition must not turn into a TypeError about the diagnostic itself.
      const named = conditionClass ? `${conditionClass.imageId}/${conditionClass.objectId}` : 'an unknown class';
      return `${named} (${condition.imageId}/${condition.objectId})`;
    },
    createUnhandledError: (description) => new SmalltalkUnhandledConditionError(description),
  });
}

function conditionTransferOut({facade, condition, value, kind, primitive}) {
  return transferConditionOccurrence({
    facade,
    sameCondition: (candidate) => sameRefIdentity(candidate, condition),
    value,
    kind,
    operation: primitive,
    createNoActiveOccurrenceError: (operation) => new SmalltalkNoActiveOccurrenceError(operation),
  });
}

// The loop itself. Every evaluation is an ordinary nested `value` send through the execution
// context, never a direct execution of the Block's code, so lexical frame restoration, authority
// attenuation, the dispatch image and cell arenas are inherited rather than reimplemented here.
//
// Constant activation depth falls out of the shape rather than from any bookkeeping: each `await`
// returns before the next send begins, so the sends are siblings from this one activation rather
// than a nesting chain, and depth does not grow with iteration count.
async function blockWhile({images, activation, context, primitive, wanted}) {
  const condition = await assertLoopBlock({
    images, value: activation.receiver, primitive, role: 'condition',
  });
  const body = !wanted && activation.arguments.length === 0 ? null : await assertLoopBlock({
    images, value: activation.arguments[0], primitive, role: 'body',
  });
  const sendMessage = requireSendMessage(context, primitive);

  // ADR 0051 decision 12: the loop answers the condition image's nil, rediscovered from that image's
  // current kernel rather than captured at install time — a captured nil would keep answering after
  // the image's kernel changed underneath it. Resolved before the first iteration so a broken kernel
  // fails as a kernel failure rather than after the body has already had effects.
  const conditionImage = condition.imageId;
  const kernel = await findSmalltalkKernel({images, imageId: conditionImage});
  if (!kernel) {
    throw new TypeError(
      `Symmetric Smalltalk ${primitive} primitive requires a Smalltalk kernel in ${conditionImage} to answer nil`,
    );
  }

  for (;;) {
    context?.checkCancelled?.();
    const verdict = canonicalizeValue(await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: condition,
      message: textValue('value'),
      arguments: [],
    }));
    // ADR 0051 decision 7: a canonical boolean, and nothing else. Accepting more would introduce a
    // second, looser notion of truth beside the polymorphism ADR 0045 established.
    if (verdict.kind !== VALUE_KIND.BOOLEAN) {
      throw new TypeError(
        `Symmetric Smalltalk ${primitive} condition answered a ${verdict.kind} Value; a Boolean is required`,
      );
    }
    if (verdict.value !== wanted) return kernel.nil;
    if (body !== null) await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: body,
      message: textValue('value'),
      arguments: [],
    });
  }
}

export {
  SmalltalkNoActiveOccurrenceError,
  SmalltalkUnhandledConditionError,
  blockEnsure,
  blockOnDo,
  blockWhile,
  conditionSignal,
  conditionTransferOut,
  nonLocalReturn,
  requireConditions,
};

import {HOST_CONDITION_CLASS} from './smalltalk-condition-ids.js';
import {
  DICTIONARY_TABLE_SHAPE_ID,
  DICTIONARY_TABLE_SLOT,
  DICTIONARY_MINIMUM_CAPACITY,
  emptyBuckets,
  grownCapacity,
  needsGrowth,
  probeSequence,
  readTableRecord,
  reinsert,
  sameCanonicalValue,
  sameStoredHash,
  tableRecordFields,
} from './smalltalk-dictionary-table.js';
import {
  builtInEquals,
  builtInHash,
  normalizeBooleanSingleton,
} from './smalltalk-equality.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {SmalltalkDanglingEdgeError} from './smalltalk-lookup.js';
import {
  SMALLTALK_PRIMITIVE,
  SmalltalkPrimitiveLocalityError,
  assertLocalRef,
  assertLoopBlock,
  promoted,
  signalHostCondition,
} from './smalltalk-primitive-support.js';
import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  integerValue,
  isObjectRef,
  objectRef,
  textValue,
} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// ADR 0048 decisions 2 and 3, at the primitive boundary. The helpers themselves are pure; what the
// primitive adds is the ADR 0045 bridge normalization, so `true = true` does not depend on whether
// each operand arrived as the singleton ref or as the canonical boolean.
// General Dictionary lookup is defined to *send* hash and =, so an execution context without a
// message runtime cannot serve these primitives — failing here is clearer than a lookup that
// silently used the built-in helper and ignored a user override.
async function builtInEqualsPrimitive({images, primitiveImage, left, right}) {
  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  return booleanValue(builtInEquals(
    normalizeBooleanSingleton(left, kernel),
    normalizeBooleanSingleton(right, kernel),
  ));
}

async function builtInHashPrimitive({images, primitiveImage, value}) {
  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  return builtInHash(normalizeBooleanSingleton(value, kernel));
}

// ADR 0048 decisions 7 and 8.
//
// A Dictionary operation is the first primitive that runs *arbitrary Smalltalk* in the middle of a
// durable mutation: it sends `hash` to the query key and `=` to stored keys, and those methods may
// send further messages or mutate state — including this very Dictionary. Everything below is shaped
// by that: read first, run user code, build a complete next snapshot, then compare-and-set exactly
// one ref.
class SmalltalkDictionaryKeyNotFoundError extends TypeError {
  constructor(dictionaryRef) {
    super(`Symmetric Smalltalk Dictionary ${dictionaryRef.imageId}/${dictionaryRef.objectId} has no such key`);
    this.name = 'SmalltalkDictionaryKeyNotFoundError';
  }
}

// A failed swap is never retried: retrying would re-execute user `hash`/`=` methods and could
// duplicate whatever effects they had.
class SmalltalkDictionaryConflictError extends TypeError {
  constructor(dictionaryRef) {
    super(
      `Symmetric Smalltalk Dictionary ${dictionaryRef.imageId}/${dictionaryRef.objectId} changed while `
      + 'its hash/= methods were running; the mutation is refused rather than retried, because a retry '
      + 'would re-execute that user code',
    );
    this.name = 'SmalltalkDictionaryConflictError';
  }
}

class SmalltalkDictionaryProtocolError extends TypeError {
  constructor(message) {
    super(`Symmetric Smalltalk Dictionary protocol violation: ${message}`);
    this.name = 'SmalltalkDictionaryProtocolError';
  }
}

async function loadDictionary({images, primitiveImage, value, primitive}) {
  assertLocalRef(value, primitiveImage, primitive, 'a Dictionary');
  const record = await images.getObject(value.imageId, value.objectId);
  if (!record) throw new SmalltalkDanglingEdgeError('dictionary', value, value);
  const tableRef = record.slots?.[DICTIONARY_TABLE_SLOT];
  if (!isObjectRef(tableRef)) {
    throw new SmalltalkDictionaryProtocolError(
      `${value.imageId}/${value.objectId} has no table; a Dictionary must be initialized before use`,
    );
  }
  if (tableRef.imageId !== primitiveImage) {
    throw new SmalltalkPrimitiveLocalityError(primitive, primitiveImage, tableRef);
  }
  const tableRecord = await images.getObject(tableRef.imageId, tableRef.objectId);
  if (!tableRecord) throw new SmalltalkDanglingEdgeError('dictionary table', value, tableRef);
  return {record, tableRef, table: readTableRecord(tableRecord)};
}

// The two places user code enters a primitive. Both results are checked before anything is written:
// a broken `hash` or `=` must fail the operation, not corrupt a table.
async function sendHash({sendMessage, key, kernel}) {
  const result = await sendMessage({
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: key,
    message: textValue('hash'),
    arguments: [],
  });
  const normalized = canonicalizeValue(result);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkDictionaryProtocolError(`hash answered a ${normalized.kind} Value; hash must answer an Integer`);
  }
  return normalized;
}

async function sendEquals({sendMessage, storedKey, queryKey}) {
  const result = await sendMessage({
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: storedKey,
    message: textValue('='),
    arguments: [queryKey],
  });
  const normalized = canonicalizeValue(result);
  if (normalized.kind !== VALUE_KIND.BOOLEAN) {
    throw new SmalltalkDictionaryProtocolError(`= answered a ${normalized.kind} Value; = must answer a Boolean`);
  }
  return normalized.value;
}

// One probe, shared by every read and by the write path, so lookup and insertion can never disagree
// about where a key lives. Answers the matching bucket index, or the first free one.
async function locate({buckets, capacity, hash, key, sendMessage}) {
  let firstFree = null;
  for (const index of probeSequence(hash, capacity)) {
    const bucket = buckets[index];
    if (bucket.hash === null) {
      if (firstFree === null) firstFree = index;
      // Open addressing with no deletion: the first empty bucket ends the run, so a key that is not
      // here cannot be further along.
      return {found: null, free: firstFree};
    }
    if (sameStoredHash(bucket.hash, hash) && await sendEquals({sendMessage, storedKey: bucket.key, queryKey: key})) {
      return {found: index, free: firstFree};
    }
  }
  return {found: null, free: firstFree};
}

async function dictionaryInitialize({images, primitiveImage, value, newObjectId, maxIdentityAttempts}) {
  const primitive = SMALLTALK_PRIMITIVE.DICTIONARY_INITIALIZE;
  assertLocalRef(value, primitiveImage, primitive, 'a Dictionary');
  const record = await images.getObject(value.imageId, value.objectId);
  if (!record) throw new SmalltalkDanglingEdgeError('dictionary', value, value);
  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel`);

  const tableRef = await publishTable({
    images,
    primitiveImage,
    buckets: emptyBuckets(DICTIONARY_MINIMUM_CAPACITY),
    kernel,
    newObjectId,
    maxIdentityAttempts,
  });
  await images.putObject(primitiveImage, {
    id: record.id,
    shape: record.shape,
    behavior: record.behavior,
    slots: {...record.slots, [DICTIONARY_TABLE_SLOT]: tableRef},
    metadata: record.metadata,
  }, {expectedVersion: record._version});
  return value;
}

// A published table is never rewritten, so every snapshot gets a fresh identity under the same
// create-once rule ADR 0046 gave ordinary allocation.
async function publishTable({images, primitiveImage, buckets, kernel, newObjectId, maxIdentityAttempts}) {
  const fields = tableRecordFields({
    buckets,
    shapeRef: objectRef(primitiveImage, DICTIONARY_TABLE_SHAPE_ID),
    nilRef: kernel.nil,
  });
  for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
    const candidate = newObjectId();
    if (typeof candidate !== 'string' || candidate.length === 0) {
      throw new TypeError('Smalltalk object identity generator must answer non-empty text');
    }
    try {
      const stored = await images.putObject(primitiveImage, {id: candidate, ...fields}, {expectedVersion: 0});
      return objectRef(primitiveImage, stored.id);
    } catch (error) {
      if (error?.name !== 'VersionConflictError') throw error;
    }
  }
  throw new TypeError(`Symmetric Smalltalk Dictionary could not find a free table identity in ${primitiveImage}`);
}

async function dictionarySize({images, primitiveImage, value}) {
  const {table} = await loadDictionary({
    images, primitiveImage, value, primitive: SMALLTALK_PRIMITIVE.DICTIONARY_SIZE,
  });
  return integerValue(table.tally);
}

async function dictionaryLookup({images, primitiveImage, value, keyValue, primitive, sendMessage}) {
  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel`);
  const {table} = await loadDictionary({images, primitiveImage, value, primitive});
  const hash = await sendHash({sendMessage, key: keyValue, kernel});
  const {found} = await locate({
    buckets: table.buckets, capacity: table.capacity, hash, key: keyValue, sendMessage,
  });
  return {found, table};
}

async function dictionaryIncludesKey({images, primitiveImage, value, keyValue, sendMessage}) {
  const {found} = await dictionaryLookup({
    images, primitiveImage, value, keyValue, sendMessage,
    primitive: SMALLTALK_PRIMITIVE.DICTIONARY_INCLUDES_KEY,
  });
  return booleanValue(found !== null);
}

async function dictionaryAt({
  images, primitiveImage, value, keyValue, sendMessage, context, newObjectId, maxIdentityAttempts,
}) {
  const {found, table} = await dictionaryLookup({
    images, primitiveImage, value, keyValue, sendMessage,
    primitive: SMALLTALK_PRIMITIVE.DICTIONARY_AT,
  });
  // ADR 0054 decision 8: a missing key is a catchable `KeyNotFound`, so `at:ifAbsent:` over a
  // Dictionary is writable in Smalltalk for the same reason it is over an OrderedCollection.
  if (found === null) {
    return await signalHostCondition({
      images,
      primitiveImage,
      context,
      classId: HOST_CONDITION_CLASS.keyNotFound,
      hostError: new SmalltalkDictionaryKeyNotFoundError(value),
      newObjectId,
      maxIdentityAttempts,
    });
  }
  return table.buckets[found].value;
}

async function dictionaryAtPut({
  images, primitiveImage, value, keyValue, newValue, sendMessage, newObjectId, maxIdentityAttempts, context,
}) {
  const primitive = SMALLTALK_PRIMITIVE.DICTIONARY_AT_PUT;
  // Both, because a Dictionary makes its keys durably reachable exactly as it does its values.
  keyValue = await promoted(context, keyValue);
  newValue = await promoted(context, newValue);
  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel`);

  // Step 1: the version observed here is what the final swap is conditioned on.
  const {record, table} = await loadDictionary({images, primitiveImage, value, primitive});
  const observedVersion = record._version;

  // Steps 2 and 3: user code runs here, and may do anything at all.
  const hash = await sendHash({sendMessage, key: keyValue, kernel});
  const {found, free} = await locate({
    buckets: table.buckets, capacity: table.capacity, hash, key: keyValue, sendMessage,
  });

  const stored = canonicalizeValue(newValue);
  // The one recognized no-op: an equal key already holding the exact same canonical Value. This is
  // canonical-Value identity of the *stored value*, not a second dynamic `=` send, and it is what
  // makes an exact caller retry after a lost acknowledgement idempotent in durable state.
  //
  // It is still a claim about durable state made *after* arbitrary user code ran, so it is
  // conditioned on exactly the version the write path CASes against. Returning from the stale
  // snapshot alone would let a re-entrant `hash`/`=` mutate this Dictionary while the outer
  // operation reported success — a false success, which is worse than the conflict it hides.
  if (found !== null && sameCanonicalValue(table.buckets[found].value, stored)) {
    const current = await images.getObject(value.imageId, value.objectId);
    if (!current || current._version !== observedVersion) throw new SmalltalkDictionaryConflictError(value);
    return stored;
  }

  // Step 4: a complete next snapshot, in memory.
  let buckets = table.buckets.map((bucket) => ({...bucket}));
  if (found !== null) {
    buckets[found] = {...buckets[found], value: stored};
  } else {
    let capacity = table.capacity;
    if (needsGrowth(table.tally + 1, capacity)) {
      capacity = grownCapacity(capacity);
      buckets = reinsert(buckets, capacity);
    }
    let placed = false;
    for (const index of probeSequence(hash, capacity)) {
      if (buckets[index].hash === null) {
        buckets[index] = {hash, key: canonicalizeValue(keyValue), value: stored};
        placed = true;
        break;
      }
    }
    if (!placed) throw new SmalltalkDictionaryProtocolError('no free bucket below the load factor, which cannot happen');
    void free;
  }

  // Step 5: publish the new table under fresh identity. Still invisible: nothing points at it.
  const tableRef = await publishTable({
    images, primitiveImage, buckets, kernel, newObjectId, maxIdentityAttempts,
  });

  // Step 6: one compare-and-set. A reader sees the old complete mapping or the new one.
  try {
    await images.putObject(primitiveImage, {
      id: record.id,
      shape: record.shape,
      behavior: record.behavior,
      slots: {...record.slots, [DICTIONARY_TABLE_SLOT]: tableRef},
      metadata: record.metadata,
    }, {expectedVersion: observedVersion});
  } catch (error) {
    // The freshly written table is now unreachable garbage. That is strictly better than installing
    // a snapshot built from state some other mutation has already superseded.
    if (error?.name === 'VersionConflictError') throw new SmalltalkDictionaryConflictError(value);
    throw error;
  }
  return stored;
}

// Workstream 3 (MessagePack pressure: `writeMap:` walks every pair). The one enumeration
// operation, Dictionary-owned: the bucket triples live below ordinary message sends, so no
// Smalltalk composition of the existing protocol can visit the pairs — `at:` needs a key it does
// not have yet. This is categorically different from `between:and:`, which is expressible over
// `<` and stays source-only. It is deliberately NOT a generic "iterate object internals"
// operation: it acts only on an initialized Dictionary, through the same `loadDictionary` that
// validates the representation for every other Dictionary primitive.
//
// What it promises, and does not:
//   snapshot     the pairs are fixed before the first Block runs. The loaded table record is an
//                immutable published snapshot (ADR 0048 decision 5), so a Block that mutates this
//                Dictionary swaps the `table` ref to a *new* snapshot while this traversal keeps
//                visiting the complete mapping it started from — mutation during enumeration never
//                invalidates the traversal, and never makes a pair appear twice or half-updated.
//   no rehash    neither `hash` nor `=` is sent. Enumeration visits stored pairs; it looks nothing
//                up, so user equality code runs zero times here.
//   no order     bucket order is a representation accident (it moves on growth), so no iteration
//                order is promised. Code that needs one must sort what it collects.
async function dictionaryKeysAndValuesDo({images, primitiveImage, value, blockValue, sendMessage}) {
  const primitive = SMALLTALK_PRIMITIVE.DICTIONARY_KEYS_AND_VALUES_DO;
  const {table} = await loadDictionary({images, primitiveImage, value, primitive});
  // The same structural Block guard the loop primitives use, for the same reason: the pair Block is
  // about to be applied on this primitive's behalf, and a kernel-primitive Block handed in here
  // would run a primitive with Dictionary-chosen arguments.
  const block = await assertLoopBlock({images, value: blockValue, primitive, role: 'pair block'});
  const pairs = table.buckets
    .filter((bucket) => bucket.hash !== null)
    .map((bucket) => ({key: bucket.key, value: bucket.value}));
  for (const pair of pairs) {
    // An ordinary `value:value:` send, exactly like a loop body (ADR 0051): lexical frame
    // restoration, authority attenuation and the dispatch image are inherited, not reimplemented.
    // Each `await` returns before the next send begins, so the sends are siblings and activation
    // depth does not grow with the number of pairs.
    await sendMessage({
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: block,
      message: textValue('value:value:'),
      arguments: [pair.key, pair.value],
    });
  }
  // Answers the receiver, as Smalltalk enumeration protocol does.
  return value;
}

export {
  SmalltalkDictionaryConflictError,
  SmalltalkDictionaryKeyNotFoundError,
  SmalltalkDictionaryProtocolError,
  builtInEqualsPrimitive,
  builtInHashPrimitive,
  dictionaryAt,
  dictionaryAtPut,
  dictionaryIncludesKey,
  dictionaryInitialize,
  dictionaryKeysAndValuesDo,
  dictionarySize,
};

import {HOST_CONDITION_CLASS} from './smalltalk-condition-ids.js';
import {
  VALUE_KIND,
  booleanValue,
  canonicalizeValue,
  integerValue,
} from '../value/index.js';
import {
  SMALLTALK_PRIMITIVE,
  signalHostCondition,
} from './smalltalk-primitive-support.js';

// ADR 0053. Two Integers, and nothing else: mixed Integer/Float *ordering and arithmetic* need
// coercion rules this ADR deliberately defers. Mixed *equality* is untouched — ADR 0048 already
// decided that an Integer equals a finite integral Float of the same mathematical value.
class SmalltalkIntegerOperandError extends TypeError {
  constructor(primitive, kind, position) {
    super(`Symmetric Smalltalk ${primitive} primitive requires two Integers; the ${position} is a ${kind} Value`);
    this.name = 'SmalltalkIntegerOperandError';
    this.primitive = primitive;
  }
}

class SmalltalkDivideByZeroError extends TypeError {
  constructor(primitive) {
    super(`Symmetric Smalltalk ${primitive} primitive cannot divide by zero`);
    this.name = 'SmalltalkDivideByZeroError';
    this.primitive = primitive;
  }
}

const SMALLTALK_INTEGER_ARITY = Object.freeze({
  [SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_MODULO]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_AND]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_OR]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR]: 2,
  [SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT]: 2,
});

function integerOperands(primitive, left, right) {
  const a = canonicalizeValue(left);
  const b = canonicalizeValue(right);
  if (a.kind !== VALUE_KIND.INTEGER) throw new SmalltalkIntegerOperandError(primitive, a.kind, 'receiver');
  if (b.kind !== VALUE_KIND.INTEGER) throw new SmalltalkIntegerOperandError(primitive, b.kind, 'argument');
  // BigInt throughout: an Integer Value is arbitrary precision, and a host number round-trip would
  // silently round anything past 2^53.
  return [BigInt(a.value), BigInt(b.value)];
}

// q = floor(a / b). Host BigInt division truncates toward zero, so the correction below is the whole
// point of this primitive existing rather than the operator being wired straight through.
function floorDivide(a, b) {
  const quotient = a / b;
  return (a % b !== 0n) && ((a < 0n) !== (b < 0n)) ? quotient - 1n : quotient;
}

async function integerOperation(primitive, left, right, {
  images, primitiveImage, context, newObjectId, maxIdentityAttempts,
}) {
  const [a, b] = integerOperands(primitive, left, right);
  // ADR 0054 decision 8: divide-by-zero is a catchable `ZeroDivide`, and a handler that resumes
  // answers the division. Absent the condition protocol it stays the host error it was.
  const divideByZero = async () => await signalHostCondition({
    images,
    primitiveImage,
    context,
    classId: HOST_CONDITION_CLASS.zeroDivide,
    hostError: new SmalltalkDivideByZeroError(primitive),
    newObjectId,
    maxIdentityAttempts,
  });
  switch (primitive) {
    case SMALLTALK_PRIMITIVE.INTEGER_LESS_THAN:
      return booleanValue(a < b);
    case SMALLTALK_PRIMITIVE.INTEGER_SUBTRACT:
      return integerValue(a - b);
    case SMALLTALK_PRIMITIVE.INTEGER_MULTIPLY:
      return integerValue(a * b);
    case SMALLTALK_PRIMITIVE.INTEGER_FLOOR_DIVIDE:
      if (b === 0n) return await divideByZero();
      return integerValue(floorDivide(a, b));
    // BigInt bitwise semantics match Smalltalk's two's-complement-at-arbitrary-precision exactly:
    // a negative receiver behaves as the infinite two's-complement bit string, which is what
    // `16rFF bitAnd: -1` must answer. `bitShift:` takes a signed count — negative shifts right —
    // mirroring `Integer>>bitShift:` rather than adding a second selector.
    case SMALLTALK_PRIMITIVE.INTEGER_BIT_AND:
      return integerValue(a & b);
    case SMALLTALK_PRIMITIVE.INTEGER_BIT_OR:
      return integerValue(a | b);
    case SMALLTALK_PRIMITIVE.INTEGER_BIT_XOR:
      return integerValue(a ^ b);
    case SMALLTALK_PRIMITIVE.INTEGER_BIT_SHIFT:
      return integerValue(b < 0n ? a >> -b : a << b);
    default:
      // r = a - q*b, so the remainder takes the divisor's sign: 0 <= r < b for b > 0, and
      // b < r <= 0 for b < 0. That range — not the reconstruction identity, which a truncating
      // implementation also satisfies — is what makes `\\` usable for hashing and indexing.
      if (b === 0n) return await divideByZero();
      return integerValue(a - floorDivide(a, b) * b);
  }
}

export {
  SMALLTALK_INTEGER_ARITY,
  SmalltalkDivideByZeroError,
  SmalltalkIntegerOperandError,
  integerOperation,
};

import {SHAPE_INDEXED, shapeIndexedKind} from '../object/model.js';
import {HOST_CONDITION_CLASS} from './smalltalk-condition-ids.js';
import {
  VALUE_KIND,
  canonicalizeValue,
  integerValue,
  isObjectRef,
  objectRef,
} from '../value/index.js';
import {findSmalltalkKernel, readBehavior} from './smalltalk-kernel.js';
import {classStateCompanionFor} from './smalltalk-class-state.js';
import {subclassRegistryId} from './smalltalk-subclasses.js';
import {
  SmalltalkDanglingEdgeError,
  SmalltalkMalformedBehaviorError,
  behaviorRefFor,
  sameRef,
  visibleInstanceShape,
} from './smalltalk-lookup.js';
import {
  SMALLTALK_PRIMITIVE,
  SmalltalkPrimitiveLocalityError,
  SmalltalkPrimitiveReceiverError,
  assertLocalRef,
  promoted,
  signalHostCondition,
} from './smalltalk-primitive-support.js';

// The object-shaped primitives: class identity, allocation, the indexed part, and instance-slot
// access. Everything here acts on one object's durable record and runs no user code beyond the
// conditions a failure may signal.

// The Array instance layout `subclasses-of` builds its answer with. Same well-known id the
// indexed protocol installs; the registry object itself shares this Shape.
const ARRAY_INSTANCE_SHAPE_ID = 'smalltalk/array-instance-shape/v1';

// ADR 0046: `instanceShape == nil` means "not instantiable", never "empty instance". Kept distinct
// from a malformed Behavior and from a dangling Shape edge.
class SmalltalkNotInstantiableError extends TypeError {
  constructor(classRef) {
    super(
      `${classRef.imageId}/${classRef.objectId} has no instance shape, so it cannot be instantiated; `
      + 'an instantiable class points at a Shape, and an empty Shape is not nil',
    );
    this.name = 'SmalltalkNotInstantiableError';
    this.classRef = classRef;
  }
}

class SmalltalkNotIndexedError extends TypeError {
  constructor(primitive, ref) {
    super(
      `Symmetric Smalltalk ${primitive} requires an indexed object layout; `
      + `${ref.imageId}/${ref.objectId} does not declare indexed values`,
    );
    this.name = 'SmalltalkNotIndexedError';
    this.primitive = primitive;
    this.ref = ref;
  }
}

class SmalltalkIndexedBoundsError extends RangeError {
  constructor(primitive, zeroBasedIndex, size) {
    super(
      `Symmetric Smalltalk ${primitive} index ${zeroBasedIndex.toString()} is outside `
      + `the 0-based indexed part of size ${size}`,
    );
    this.name = 'SmalltalkIndexedBoundsError';
    this.primitive = primitive;
    this.index = zeroBasedIndex.toString();
    this.size = size;
  }
}

// ADR 0046 decision 9. Deliberately routed through the same `behaviorRefFor` the dispatcher uses, so
// `class` cannot drift from what a send would actually dispatch through.
async function classOf({images, primitiveImage, value}) {
  if (isObjectRef(value) && value.imageId !== primitiveImage) {
    throw new SmalltalkPrimitiveLocalityError(SMALLTALK_PRIMITIVE.CLASS_OF, primitiveImage, value);
  }
  if (isObjectRef(value) && !(await images.getObject(value.imageId, value.objectId))) {
    const block = typeof images.getBlock === 'function'
      ? await images.getBlock(value.imageId, value.objectId)
      : null;
    if (block) {
      const blockClassRef = objectRef(primitiveImage, 'smalltalk/class/BlockClosure');
      if (await images.getObject(primitiveImage, blockClassRef.objectId)) {
        return blockClassRef;
      }
    }
  }
  const {behavior} = await behaviorRefFor({images, receiver: value, dispatchImage: primitiveImage});
  if (!isObjectRef(behavior)) {
    throw new SmalltalkPrimitiveReceiverError(
      SMALLTALK_PRIMITIVE.CLASS_OF,
      isObjectRef(value)
        ? `${value.imageId}/${value.objectId}, which has no behavior`
        : `a ${value.kind} Value`,
    );
  }
  return behavior;
}

async function loadAllocationClass({images, primitiveImage, classValue, primitive}) {
  assertLocalRef(classValue, primitiveImage, primitive, 'only an unpinned class ref allocates');

  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel to allocate against`);

  const record = await images.getObject(classValue.imageId, classValue.objectId);
  if (!record) throw new SmalltalkDanglingEdgeError('class', classValue, classValue);
  let behavior;
  try {
    behavior = await readBehavior(images, classValue);
  } catch (error) {
    throw new SmalltalkMalformedBehaviorError(classValue, error);
  }

  if (sameRef(behavior.instanceShape, kernel.nil)) throw new SmalltalkNotInstantiableError(classValue);

  const shapeRef = behavior.instanceShape;
  const shape = await images.getShape(shapeRef.imageId, shapeRef.objectId);
  if (!shape) throw new SmalltalkDanglingEdgeError('instanceShape', behavior.record, shapeRef);
  return {kernel, behavior, shapeRef, shape};
}

function nonNegativeSize(value, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} size; size must be an Integer Value`);
  }
  const size = BigInt(normalized.value);
  if (size < 0n) throw new RangeError(`Symmetric Smalltalk ${primitive} size must be non-negative`);
  // Durable indices are unbounded integer Values, but this JavaScript representation is an Array.
  // Fail explicitly rather than letting an implementation RangeError or allocation overflow define
  // language behavior by accident.
  if (size > 0xffff_ffffn) {
    throw new RangeError(`Symmetric Smalltalk ${primitive} size exceeds the current indexed-object implementation limit`);
  }
  return Number(size);
}

async function allocate({
  images,
  primitiveImage,
  classValue,
  primitive,
  indexedSize = null,
  newObjectId,
  maxIdentityAttempts,
  context = null,
}) {
  const {kernel, shapeRef, shape} = await loadAllocationClass({
    images, primitiveImage, classValue, primitive,
  });
  const indexedKind = shapeIndexedKind(shape);
  if (indexedSize !== null && indexedKind !== SHAPE_INDEXED.VALUES) {
    throw new SmalltalkNotIndexedError(primitive, classValue);
  }

  const slots = Object.fromEntries(shape.slots.map(({id}) => [id, kernel.nil]));
  // `basicNew` on an indexed class means its zero-length form. `basicNew:` supplies the fixed size.
  // A non-indexed shape omits the property entirely, preserving the old record form.
  const indexed = indexedKind === SHAPE_INDEXED.VALUES
    ? Array.from({length: indexedSize ?? 0}, () => kernel.nil)
    : null;

  // ADR 0060 decision 3. Inside an execution the object begins in the arena: the executor's
  // `mintObject` supplies a transient identity and holds the record, so allocation costs no durable
  // write unless the object escapes. The layout is identical to the durable form below, so
  // promotion is a copy, not a translation.
  if (typeof context?.mintObject === 'function') {
    return context.mintObject({
      imageId: primitiveImage,
      shape: shapeRef,
      behavior: classValue,
      slots,
      indexed,
      metadata: {},
    });
  }

  // ADR 0046 identity rule: a known collision chooses another candidate; every other failure
  // surfaces, and a new Smalltalk send always begins with a fresh candidate.
  for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
    const candidate = newObjectId();
    if (typeof candidate !== 'string' || candidate.length === 0) {
      throw new TypeError('Smalltalk object identity generator must answer non-empty text');
    }
    try {
      const stored = await images.putObject(primitiveImage, {
        id: candidate,
        shape: shapeRef,
        behavior: classValue,
        slots,
        ...(indexed === null ? {} : {indexed}),
        metadata: {},
      }, {expectedVersion: 0});
      return objectRef(primitiveImage, stored.id);
    } catch (error) {
      if (error?.name !== 'VersionConflictError') throw error;
    }
  }
  throw new TypeError(
    `Symmetric Smalltalk ${primitive} could not find a free object identity in ${primitiveImage} `
    + `after ${maxIdentityAttempts} attempts`,
  );
}

async function basicNew({images, primitiveImage, classValue, newObjectId, maxIdentityAttempts, context = null}) {
  return await allocate({
    images,
    primitiveImage,
    classValue,
    primitive: SMALLTALK_PRIMITIVE.BASIC_NEW,
    newObjectId,
    maxIdentityAttempts,
    context,
  });
}

async function basicNewSized({images, primitiveImage, classValue, sizeValue, newObjectId, maxIdentityAttempts, context = null}) {
  const size = nonNegativeSize(sizeValue, SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED);
  return await allocate({
    images,
    primitiveImage,
    classValue,
    primitive: SMALLTALK_PRIMITIVE.BASIC_NEW_SIZED,
    indexedSize: size,
    newObjectId,
    maxIdentityAttempts,
    context,
  });
}

async function loadIndexedObject({images, primitiveImage, value, primitive}) {
  const ref = assertLocalRef(value, primitiveImage, primitive, 'only an unpinned object ref has indexed state');
  const record = await images.getObject(ref.imageId, ref.objectId);
  if (!record) throw new SmalltalkDanglingEdgeError('indexed receiver', ref, ref);
  const shape = await images.getShape(record.shape.imageId, record.shape.objectId);
  if (!shape) throw new SmalltalkDanglingEdgeError('shape', record, record.shape);
  if (shapeIndexedKind(shape) !== SHAPE_INDEXED.VALUES || !Object.hasOwn(record, 'indexed')) {
    throw new SmalltalkNotIndexedError(primitive, ref);
  }
  return record;
}

function zeroBasedIndex(value, length, primitive) {
  const normalized = canonicalizeValue(value);
  if (normalized.kind !== VALUE_KIND.INTEGER) {
    throw new SmalltalkPrimitiveReceiverError(primitive, `a ${normalized.kind} index; index must be an Integer Value`);
  }
  const index = BigInt(normalized.value);
  if (index < 0n || index >= BigInt(length)) throw new SmalltalkIndexedBoundsError(primitive, index, length);
  return Number(index);
}

async function indexedSize({images, primitiveImage, value}) {
  const record = await loadIndexedObject({
    images, primitiveImage, value, primitive: SMALLTALK_PRIMITIVE.INDEXED_SIZE,
  });
  return integerValue(record.indexed.length);
}

// ADR 0054 decision 8. `zeroBasedIndex` stays synchronous and keeps throwing — it is used where
// there is no execution context — so the signalling wrapper lives at the two sites that have one.
async function boundedIndex({
  images, primitiveImage, context, newObjectId, maxIdentityAttempts, indexValue, length, primitive,
}) {
  try {
    return {index: zeroBasedIndex(indexValue, length, primitive)};
  } catch (error) {
    if (!(error instanceof SmalltalkIndexedBoundsError)) throw error;
    return {
      resumed: await signalHostCondition({
        images,
        primitiveImage,
        context,
        classId: HOST_CONDITION_CLASS.indexBounds,
        hostError: error,
        newObjectId,
        maxIdentityAttempts,
      }),
    };
  }
}

async function indexedAt({images, primitiveImage, value, indexValue, context, newObjectId, maxIdentityAttempts}) {
  const record = await loadIndexedObject({
    images, primitiveImage, value, primitive: SMALLTALK_PRIMITIVE.INDEXED_AT,
  });
  const bounded = await boundedIndex({
    images, primitiveImage, context, newObjectId, maxIdentityAttempts, indexValue,
    length: record.indexed.length, primitive: SMALLTALK_PRIMITIVE.INDEXED_AT,
  });
  // A handler that resumed answers the access itself.
  if (Object.hasOwn(bounded, 'resumed')) return bounded.resumed;
  return record.indexed[bounded.index];
}

async function indexedAtPut({
  images, primitiveImage, value, indexValue, newValue, context, newObjectId, maxIdentityAttempts,
}) {
  const record = await loadIndexedObject({
    images, primitiveImage, value, primitive: SMALLTALK_PRIMITIVE.INDEXED_AT_PUT,
  });
  const bounded = await boundedIndex({
    images, primitiveImage, context, newObjectId, maxIdentityAttempts, indexValue,
    length: record.indexed.length, primitive: SMALLTALK_PRIMITIVE.INDEXED_AT_PUT,
  });
  if (Object.hasOwn(bounded, 'resumed')) return bounded.resumed;
  const index = bounded.index;
  // `value` is the receiver: writing into a transient indexed object keeps the value in the arena.
  const storedValue = canonicalizeValue(await promoted(context, newValue, value));
  const indexed = [...record.indexed];
  indexed[index] = storedValue;
  await images.putObject(primitiveImage, {
    id: record.id,
    shape: record.shape,
    behavior: record.behavior,
    slots: record.slots,
    indexed,
    metadata: record.metadata,
  }, {expectedVersion: record._version});
  return storedValue;
}

// ADR 0050 decisions 5, 5a and 6. Two checks that answer different questions, kept apart because
// collapsing them is exactly how the Parent/Child hole opens:
//
//   may this method name this slot?   the slot is declared by the defining Behavior's visible layout
//   does this object have it?         the slot is in the target's *current* Shape
//
// Plus the one that makes both meaningful: the target must be this activation's `self`, proved from
// the transient frame rather than trusted from the argument.
class SmalltalkSlotAccessError extends TypeError {
  constructor(primitive, reason) {
    super(`Symmetric Smalltalk ${primitive} refused: ${reason}`);
    this.name = 'SmalltalkSlotAccessError';
    this.primitive = primitive;
  }
}

class SmalltalkSlotFrameMissingError extends TypeError {
  constructor(primitive) {
    super(
      `Symmetric Smalltalk ${primitive} has no method frame; instance state is reachable only from a `
      + 'method of the declaring class, and a closure that outlived its execution no longer has one',
    );
    this.name = 'SmalltalkSlotFrameMissingError';
    this.primitive = primitive;
  }
}

function sameValueRef(left, right) {
  if (isObjectRef(left) && isObjectRef(right)) {
    return left.imageId === right.imageId && left.objectId === right.objectId;
  }
  return JSON.stringify(canonicalizeValue(left)) === JSON.stringify(canonicalizeValue(right));
}

async function resolveSlotAccess({images, primitiveImage, primitive, target, slotIdValue, context}) {
  const frame = context?.invocationFrame ?? null;
  if (!frame || !Object.hasOwn(frame, 'self') || !Object.hasOwn(frame, 'definingBehavior')) {
    throw new SmalltalkSlotFrameMissingError(primitive);
  }
  if (slotIdValue?.kind !== VALUE_KIND.TEXT || slotIdValue.value.length === 0) {
    throw new SmalltalkSlotAccessError(primitive, 'a slot id must be non-empty text');
  }
  // Proved, not arranged by the compiler: a method is ordinary durable data, so a forged artifact
  // could otherwise pass any object at all.
  if (!sameValueRef(target, frame.self)) {
    throw new SmalltalkSlotAccessError(primitive, 'instance state is reachable only on the method own self');
  }
  assertLocalRef(target, primitiveImage, primitive, 'an instance');

  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel`);

  // Shared with the binder, and strict: a cycle or a dangling instance Shape raises here rather
  // than presenting as "this method may not name that slot". Permission comes from the DEFINING
  // behavior: a method may name exactly the slots its own defining metaclass/class declares.
  const layout = await visibleInstanceShape({images, behaviorRef: frame.definingBehavior, nilRef: kernel.nil});
  if (!layout?.slots.some(({id}) => id === slotIdValue.value)) {
    throw new SmalltalkSlotAccessError(
      primitive,
      `${slotIdValue.value} is not declared by ${frame.definingBehavior.imageId}/${frame.definingBehavior.objectId}`,
    );
  }

  const record = await images.getObject(target.imageId, target.objectId);
  if (!record) throw new SmalltalkDanglingEdgeError('instance', target, target);
  const shape = await images.getShape(record.shape.imageId, record.shape.objectId);
  if (!shape) throw new SmalltalkDanglingEdgeError('instance shape', record, record.shape);
  if (shape.slots.some(({id}) => id === slotIdValue.value)) {
    // Ordinary instance access: the receiver's own record physically carries the slot.
    return {record, slotId: slotIdValue.value};
  }

  // Class-instance access (WS3 prereq B completion): the receiver is a class object and the slot
  // is not physically in the fixed Behavior shape, so the logical class-instance slot resolves to
  // the DYNAMIC self class's companion. Permission already came from the defining behavior above;
  // receiver/layout compatibility now comes from the dynamic class's metaclass, and physical
  // storage from that dynamic class's companion.
  const routing = await classStateCompanionFor({images, selfRef: target});
  if (!routing) {
    throw new SmalltalkSlotAccessError(
      primitive,
      `${slotIdValue.value} is absent from the current shape of ${target.imageId}/${target.objectId}`,
    );
  }
  // The dynamic class's metaclass must itself declare the slot — an inherited class-side method
  // running on a class whose class-instance layout lacks the slot is refused, not silently routed.
  const dynamicShape = await images.getShape(
    routing.metaclassInstanceShapeRef.imageId, routing.metaclassInstanceShapeRef.objectId,
  );
  if (!dynamicShape?.slots.some(({id}) => id === slotIdValue.value)) {
    throw new SmalltalkSlotAccessError(
      primitive,
      `${slotIdValue.value} is absent from the class-instance layout of ${routing.className}`,
    );
  }
  const companion = await images.getObject(routing.companionRef.imageId, routing.companionRef.objectId);
  if (!companion) {
    throw new SmalltalkDanglingEdgeError('class-state companion', target, routing.companionRef);
  }
  return {record: companion, slotId: slotIdValue.value};
}

async function instanceSlotRead({images, primitiveImage, target, slotIdValue, context}) {
  const {record, slotId} = await resolveSlotAccess({
    images, primitiveImage, primitive: SMALLTALK_PRIMITIVE.INSTANCE_SLOT_READ, target, slotIdValue, context,
  });
  return record.slots[slotId];
}

// Class-hierarchy introspection (WS3). Reads the receiver class's durable subclass registry and
// answers an image Array of its direct-subclass refs — the same spirit as `class-of` reading the
// behavior edge. Absence reads as empty: kernel classes maintain no registries (the kernel
// installer writes its class graph directly), so `Integer subclasses` is empty even though a
// fuller image would give it subclasses. The Array is built like any allocated indexed object —
// arena-minted inside an execution, durable create-once outside one — never a hidden host value.
async function subclassesOf({images, primitiveImage, value, newObjectId, maxIdentityAttempts, context = null}) {
  const primitive = SMALLTALK_PRIMITIVE.SUBCLASSES_OF;
  const ref = assertLocalRef(value, primitiveImage, primitive, 'only a class has subclasses');

  const kernel = await findSmalltalkKernel({images, imageId: primitiveImage});
  if (!kernel) throw new TypeError(`image ${primitiveImage} has no Smalltalk kernel`);

  let behavior;
  try {
    behavior = await readBehavior(images, ref);
  } catch (error) {
    throw new SmalltalkMalformedBehaviorError(ref, error);
  }
  const className = behavior.name.value;

  let elements = [];
  const registry = await images.getObject(primitiveImage, subclassRegistryId(className));
  if (registry && Array.isArray(registry.indexed)) elements = registry.indexed;

  const arrayShapeRef = objectRef(primitiveImage, ARRAY_INSTANCE_SHAPE_ID);
  const arrayClassRef = objectRef(primitiveImage, 'smalltalk/class/Array');
  // ADR 0060 decision 3, exactly as `allocate`: inside an execution the Array begins in the arena,
  // durable only if it escapes. The layout is identical to the durable form, so promotion is a copy.
  if (typeof context?.mintObject === 'function') {
    return context.mintObject({
      imageId: primitiveImage,
      shape: arrayShapeRef,
      behavior: arrayClassRef,
      slots: {},
      indexed: elements,
      metadata: {},
    });
  }
  // ADR 0046 identity rule, as `allocate`: a known collision chooses another candidate.
  for (let attempt = 0; attempt < maxIdentityAttempts; attempt += 1) {
    const candidate = newObjectId();
    try {
      const stored = await images.putObject(primitiveImage, {
        id: candidate,
        shape: arrayShapeRef,
        behavior: arrayClassRef,
        slots: {},
        indexed: elements,
        metadata: {},
      }, {expectedVersion: 0});
      return objectRef(primitiveImage, stored.id);
    } catch (error) {
      if (error?.name !== 'VersionConflictError') throw error;
    }
  }
  throw new TypeError(
    `Symmetric Smalltalk ${primitive} could not find a free object identity in ${primitiveImage} `
    + `after ${maxIdentityAttempts} attempts`,
  );
}

async function instanceSlotWrite({images, primitiveImage, target, slotIdValue, newValue, context}) {
  const {record, slotId} = await resolveSlotAccess({
    images, primitiveImage, primitive: SMALLTALK_PRIMITIVE.INSTANCE_SLOT_WRITE, target, slotIdValue, context,
  });
  // `target` is the receiver: writing into a transient object keeps the value in the arena.
  const stored = canonicalizeValue(await promoted(context, newValue, target));
  await images.putObject(primitiveImage, {
    id: record.id,
    shape: record.shape,
    behavior: record.behavior,
    slots: {...record.slots, [slotId]: stored},
    // Everything else survives. ADR 0047's review found the mutation binding erasing an indexed part
    // it did not carry forward; a named-slot write rebuilds a whole record for the same reason.
    ...(Object.hasOwn(record, 'indexed') ? {indexed: record.indexed} : {}),
    metadata: record.metadata,
  }, {expectedVersion: record._version});
  return stored;
}

