import {installSmalltalkConditionProtocol, installSmalltalkExceptionAccessors, CONDITION_CLASSES} from './smalltalk-conditions.js';
import {installSmalltalkControlFlow} from './smalltalk-control-flow.js';
import {installSmalltalkDictionaryProtocol, installSmalltalkEqualityProtocol} from './smalltalk-dictionary.js';
import {
  installSmalltalkGlobalNamespace,
  publishSmalltalkClassGlobals,
} from './smalltalk-globals.js';
import {installSmalltalkArrayEnumerationProtocol, installSmalltalkIndexedProtocol} from './smalltalk-indexed.js';
import {installSmalltalkInstanceVariableProtocol} from './smalltalk-instance-variables.js';
import {installSmalltalkIntegerPrintingProtocol, installSmalltalkIntegerProtocol} from './smalltalk-integer.js';
import {findSmalltalkKernel, installSmalltalkKernel} from './smalltalk-kernel.js';
import {installSmalltalkLibrary} from './smalltalk-library.js';
import {
  installSmalltalkReadStreamProtocol,
  installSmalltalkTextReadStreamProtocol,
  installSmalltalkStreamBreadthProtocol,
} from './smalltalk-read-stream.js';
import {installSmalltalkSetProtocol, installSmalltalkArraySetConversion} from './smalltalk-set.js';
import {installSmalltalkSubclassProtocol} from './smalltalk-subclasses.js';
import {installSmalltalkSymbolProtocol} from './smalltalk-symbol.js';
import {installSmalltalkStringEqualityProtocol} from './smalltalk-string-equality.js';
import {installSmalltalkCharacterProtocol, installSmalltalkCharacterRangeProtocol} from './smalltalk-character.js';
import {installSmalltalkArray2DProtocol, installSmalltalkArray2DCopyProtocol} from './smalltalk-array2d.js';
import {installSmalltalkIntervalProtocol, installSmalltalkIntervalConstructionProtocol} from './smalltalk-interval.js';
import {installSmalltalkActiveModelProtocol} from './smalltalk-active-model.js';
