// The normal, complete Symmetric Smalltalk image. This is composition, not a new semantic layer:
// every record is still owned by the installer that defines it, and all of those low-level
// installers remain public for tests, partial personalities and future bootstrap work.
const SYMMETRIC_SMALLTALK_STANDARD_IMAGE_V1 = 'symmetric-smalltalk-standard-image/v1';

// `+` predates the protocol installers and is deliberately still the old `integer-add` semantic op.
// Many suites install this exact method by hand. The standard image makes that established behavior
// part of the normal composition without adding a primitive, selector special case or new IR op.
const INTEGER_PLUS_METHOD = Object.freeze({
  selector: '+',
  program: Object.freeze({
    parameters: Object.freeze([Object.freeze({id: 'plus:arg', name: 'n'})]),
    captures: Object.freeze([]),
    body: Object.freeze({
      op: 'integer-add',
      left: Object.freeze({op: 'receiver'}),
      right: Object.freeze({op: 'argument', index: 0}),
    }),
  }),
});

const PRE_LIBRARY_PUBLIC_CLASSES = Object.freeze([
  'Array',
  'Character',
  ...CONDITION_CLASSES.map(({name}) => name),
  'Dictionary',
]);
const LIBRARY_PUBLIC_CLASSES = Object.freeze(['Association', 'Collection', 'OrderedCollection']);
// After the library and the byte-sequence protocol: `contents` builds a text result through
// `ByteArray`, answers a collection result through Collection's `species`, and names the
// `OrderedCollection`, `Text` and `ByteArray` globals.
const POST_LIBRARY_PUBLIC_CLASSES = Object.freeze(['WriteStream']);
const SET_PUBLIC_CLASSES = Object.freeze(['Set']);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function installIntegerAddition({images, compilation, imageId, lane, kernel}) {
  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.integerClass,
    methods: [INTEGER_PLUS_METHOD],
  });
  return Object.freeze({integerClass: kernel.integerClass});
}

async function installSymmetricSmalltalkStandardImage({
  images,
  compilation,
  imageId,
  lane = 'neutral',
} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  // Composition has stronger requirements than any one low-level installer, so validate them before
  // publishing the first kernel record. A missing dependency is a caller error, not a recoverable
  // partial standard-image installation.
  if (!images || typeof images.getImage !== 'function' || typeof images.getObject !== 'function') {
    throw new TypeError('images service with getImage/getObject is required');
  }
  if (!compilation || typeof compilation.compileArtifact !== 'function') {
    throw new TypeError('compilation service with compileArtifact is required');
  }

  // The image lifecycle belongs to the caller. `getImage` owns the missing-image diagnosis; this
  // installer merely requires the image to exist and never creates one as a side effect.
  await images.getImage(imageId);

  const options = {images, compilation, imageId, lane};

  // Bootstrap and standard-image replay are intentionally different operations. Once the kernel
  // exists its method dictionaries are expected to grow, so rerunning the bootstrap installer would
  // incorrectly compare those live dictionaries with bootstrap's empty definitions. Rediscover an
  // existing kernel instead. If an interrupted bootstrap never published the kernel record, rerun
  // the bootstrap installer from the start and let its ensure-exact writes converge.
  let kernel = await findSmalltalkKernel({images, imageId});
  let kernelInstall = null;
  if (!kernel) {
    kernelInstall = await installSmalltalkKernel({images, imageId});
    kernel = await findSmalltalkKernel({images, imageId});
  }
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel after installation`);

  // This order is intentionally boring and mirrors the dependency order the first real library
  // forced tests to spell by hand. A stage may assume everything above it, and nothing below it.
  const allocation = await installSmalltalkAllocationProtocol(options);
  const equality = await installSmalltalkEqualityProtocol(options);
  const controlFlow = await installSmalltalkControlFlow(options);
  const indexed = await installSmalltalkIndexedProtocol(options);
  const instanceVariables = await installSmalltalkInstanceVariableProtocol({images, imageId});
  // Hierarchy-scoped shared bindings (ADR 0057's class-scoped analog). The concept becomes
  // load-bearing through the import path: a canonical manifest class may DECLARE class-variable
  // names, and its package's own code reads and writes them. This must exist before that import,
  // and it is ensure-based, so replay is free.
  const classVariables = await installSmalltalkClassVariableSupport({images, compilation, imageId, lane});
  const blocks = await installSmalltalkBlockProtocol({images, imageId});
  const integers = await installSmalltalkIntegerProtocol(options);
  const integerAddition = await installIntegerAddition({...options, kernel});
  const conditions = await installSmalltalkConditionProtocol(options);
  // After both instance variables (0050) and conditions: the Exception accessor is a separate pass
  // so the condition installer never takes the slot-read dependency it deliberately avoids.
  const exceptionAccessors = await installSmalltalkExceptionAccessors(options);
  const dictionary = await installSmalltalkDictionaryProtocol(options);
  const symbol = await installSmalltalkSymbolProtocol(options);
  await installSmalltalkStringTestingProtocol(options);
  // Character literals and Text indexing share one canonical, image-local Character interner.
  // Character remains distinct from both Text and Integer without widening the generic Value model.
  const character = await installSmalltalkCharacterProtocol(options);
  // Native Text/ByteArray protocol over the byte-sequence primitives (WS3). Independent of the
  // library — Text/ByteArray are native Values dispatching through their kernel classes.
  const textByteArray = await installSmalltalkTextByteArrayProtocol(options);
  // String equality shares Text spelling/hash; its prerequisites include Symbol type testing
  // and the Text conversion above. Publish it before application collections are populated.
  await installSmalltalkStringEqualityProtocol(options);

  // Namespace publication is deliberately separate from class creation. Installing the namespace
  // publishes the kernel classes; the public post-kernel classes are named explicitly here. In
  // particular GlobalBinding stays implementation machinery rather than becoming a user global.
  const globals = await installSmalltalkGlobalNamespace(options);
  await publishSmalltalkClassGlobals({images, imageId, names: [...PRE_LIBRARY_PUBLIC_CLASSES]});
  // Character ranges compose the published Array and Character bindings.
  await installSmalltalkCharacterRangeProtocol(options);

  // Integer PRINTING, after the namespace because its source names the `Array` and `ByteArray`
  // globals. Ownership is unchanged — the Integer module owns it; only the ordering lives here.
  const integerPrinting = await installSmalltalkIntegerPrintingProtocol(options);

  const library = await installSmalltalkLibrary(options);
  await publishSmalltalkClassGlobals({images, imageId, names: [...LIBRARY_PUBLIC_CLASSES]});

  // `Array do:`, a general collection protocol the upstream encoder needs. After the library
  // because it composes the indexed primitives with the Block enumeration loop, which is not yet
  // installed when the indexed protocol runs; Array is a kernel class outside `Collection`.
  const arrayEnumeration = await installSmalltalkArrayEnumerationProtocol(options);

  // Class-hierarchy introspection. After the library because `subclasses`/`allSubclasses` are
  // ordinary Smalltalk written against OrderedCollection and the Integer loop; the registry
  // itself is maintained by `defineClass`, so every class already defined (kernel included) is
  // introspectable the moment this protocol lands.
  const subclasses = await installSmalltalkSubclassProtocol(options);

  // An ordinary native stream class, published as an ordinary global. It is here because a real
  // imported consumer named it (bead lagrange-images-nv1.4: the pinned upstream Cuis JSON package
  // writes `WriteStream on: String new`), but nothing about it is Cuis-specific — the import
  // adapter resolves the name through this namespace exactly as it would `Array`. After the
  // library and the byte-sequence protocol, whose methods and globals `contents` both needs.
  const writeStream = await installSmalltalkWriteStreamProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: [...POST_LIBRARY_PUBLIC_CLASSES]});

  // Set membership delegates to Dictionary; conversion needs Array enumeration and a published
  // Set global. Keep class publication in composition, as for every other standard class.
  const set = await installSmalltalkSetProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: [...SET_PUBLIC_CLASSES]});
  await installSmalltalkArraySetConversion(options);

  const readStream = await installSmalltalkReadStreamProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: ['ReadStream']});
  await installSmalltalkTextReadStreamProtocol(options);
  await installSmalltalkStreamBreadthProtocol(options);

  // Two native value-model classes required by real imported application code (M5, bead
  // lagrange-images-nfv1.3, classified by the frozen nfv1.1 measurement). `Array2D` because
  // Life's own `LifeArray` extends it and the witness reaches its measured grid protocol;
  // `TextModel` because `LifeModel` extends it and the unchanged `nextState` fires events with
  // zero subscribers; `Point` because the unchanged grid code constructs and decomposes
  // positions. Each is an ordinary native class published as an ordinary global; the Cuis
  // import adapter's correspondence seam resolves only their SEALED identities to them, never
  // by name-guessing. Publication then its derived construction/copy stages, as everywhere
  // above: bodies naming the globals compile only after publication.
  const point = await installSmalltalkPointProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: ['Point']});
  await installSmalltalkPointConstructionProtocol(options);
  const array2d = await installSmalltalkArray2DProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: ['Array2D']});
  await installSmalltalkArray2DCopyProtocol(options);
  const activeModel = await installSmalltalkActiveModelProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: ['TextModel']});
  // `Interval`, because the imported Life code iterates with `(a to: b) do:` — a `to:` answered
  // by an Interval and then `do:`, which is a different message chain from Integer's `to:do:`.
  const interval = await installSmalltalkIntervalProtocol(options);
  await publishSmalltalkClassGlobals({images, imageId, names: ['Interval']});
  await installSmalltalkIntervalConstructionProtocol(options);

  return Object.freeze({
    protocol: SYMMETRIC_SMALLTALK_STANDARD_IMAGE_V1,
    imageId,
    lane,
    kernel,
    kernelInstall,
    protocols: Object.freeze({
      allocation,
      equality,
      controlFlow,
      indexed,
      instanceVariables,
      classVariables,
      blocks,
      integers,
      integerAddition,
      integerPrinting,
      conditions,
      exceptionAccessors,
      dictionary,
      symbol,
      character,
      textByteArray,
      globals,
      arrayEnumeration,
      subclasses,
      writeStream,
      set,
      readStream,
      point,
      array2d,
      activeModel,
      interval,
    }),
    classes: Object.freeze({
      Array: indexed.arrayClass,
      Dictionary: dictionary.classRef,
      Character: character.classRef,
      Association: library.association,
      Collection: library.collection,
      OrderedCollection: library.orderedCollection,
      WriteStream: writeStream.classRef,
      Set: set.classRef,
      ReadStream: readStream.classRef,
      Point: point.classRef,
      Array2D: array2d.classRef,
      TextModel: activeModel.classRef,
      Interval: interval.classRef,
      ...Object.fromEntries(CONDITION_CLASSES.map(({name}) => [name, conditions[name]])),
    }),
    library,
  });
}

export {
  INTEGER_PLUS_METHOD as SMALLTALK_STANDARD_INTEGER_PLUS_METHOD,
  LIBRARY_PUBLIC_CLASSES as SMALLTALK_STANDARD_LIBRARY_PUBLIC_CLASSES,
  POST_LIBRARY_PUBLIC_CLASSES as SMALLTALK_STANDARD_POST_LIBRARY_PUBLIC_CLASSES,
  PRE_LIBRARY_PUBLIC_CLASSES as SMALLTALK_STANDARD_PRE_LIBRARY_PUBLIC_CLASSES,
  SYMMETRIC_SMALLTALK_STANDARD_IMAGE_V1,
  installSymmetricSmalltalkStandardImage,
};

import {objectRef} from '../value/index.js';
import {assertMethodLane, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {SYMBOL_CLASS_NAME} from './smalltalk-primitives-symbol.js';

// YAXO compares an interned element name with tokenizer Text. Equality and hash must move
// together, while Object's default relation, reference identity and interning stay unchanged.
// Spelling and its hash are obtained through ordinary protocol, never by decoding Symbol records.
async function installSmalltalkStringEqualityProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') throw new TypeError('images service is required');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);
  const symbolClass = objectRef(imageId, `smalltalk/class/${SYMBOL_CLASS_NAME}`);
  const trueClass = (await images.getObject(kernel.true.imageId, kernel.true.objectId)).behavior;
  const falseClass = (await images.getObject(kernel.false.imageId, kernel.false.objectId)).behavior;
  // Check every required stage before the first method publication. The class builder owns
  // selector storage and corruption checks; this owner only states its protocol prerequisites.
  for (const [classRef, name, selectors] of [
    [kernel.objectClass, 'Object', ['==', 'hash', 'isString']],
    [kernel.textClass, 'Text', ['asString', 'isString']],
    [symbolClass, 'Symbol', ['asString', 'isString']],
    [trueClass, 'True', ['and:']], [falseClass, 'False', ['and:']],
  ]) for (const selector of selectors) {
    if (!await methodBlockRef({images, imageId, classRef, selector})) {
      throw new TypeError(`image ${imageId} has no ${name} ${selector} method`);
    }
  }
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [{selector: '=', source: '[ :other | other isString and: [ self == other asString ] ]'}],
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: symbolClass,
    methods: [
      {selector: '=', source: '[ :other | self asString = other ]'},
      {selector: 'hash', source: '[ self asString hash ]'},
    ],
  });
}

export {installSmalltalkStringEqualityProtocol};

import {isObjectRef, objectRef, textValue} from '../value/index.js';
import {ensureObject, ensureShape} from '../graph/ensure-records.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {SMALLTALK_PRIMITIVE} from './smalltalk-primitive-support.js';
import {findSmalltalkKernel, readBehavior} from './smalltalk-kernel.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {assertMethodLane, ensureBlock, ensureCodeArtifact} from './smalltalk-class-builder.js';
import {SMALLTALK_KERNEL_PRIMITIVE_V1} from './smalltalk-primitives.js';
import {primitiveCodeContent} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// Class-hierarchy introspection: the durable subclass registry and the
// `subclasses`/`allSubclasses` protocol.
//
// A class's direct subclasses are ordinary durable image state, never hidden JS
// state and never a new field on the fixed Behavior shape (which would be a
// durable-schema migration touching every class). Each class has a registry
// object at a deterministic id whose indexed part holds direct-subclass refs.
// `defineClass` maintains it (see `maintainSubclassRegistries`); the
// `subclasses-of` primitive reads it into an image Array; the Smalltalk
// `subclasses`/`allSubclasses` methods compose over it with OrderedCollection.
//
// Owner: the Symmetric Smalltalk personality. No Value/generic-Object/backend
// change; the registry rides the ordinary object model.

const SUBCLASS_REGISTRY_SHAPE_ID = 'smalltalk/subclass-registry-shape/v1';
const SUBCLASSES_OF_BLOCK_ID = 'smalltalk/primitive/subclasses-of';
const SUBCLASSES_OF_CAPTURE = Object.freeze({id: SUBCLASSES_OF_BLOCK_ID, name: 'primitiveSubclassesOf'});

class SmalltalkSubclassRegistryConflictError extends TypeError {
  constructor(registryRef, subclassRef = null) {
    super(
      `subclass registry ${registryRef.imageId}/${registryRef.objectId} changed or is malformed; `
      + 'refusing to overwrite it',
    );
    this.name = 'SmalltalkSubclassRegistryConflictError';
    this.imageId = registryRef.imageId;
    this.objectId = registryRef.objectId;
    this.subclassRef = subclassRef;
  }
}

function subclassRegistryId(className) {
  return `smalltalk/subclasses/${className}`;
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function ensureRegistryShape(images, imageId) {
  const desired = {
    id: SUBCLASS_REGISTRY_SHAPE_ID, slots: [], indexed: SHAPE_INDEXED.VALUES,
  };
  const shape = await ensureShape(images, imageId, desired);
  return objectRef(imageId, shape.id);
}

// The registry's shape is well-known and lazily ensured, but the registry record
// for a class is created on first append (or first explicit ensure), so a class
// nobody ever subclassed has no record at all — and absence reads as empty.
async function ensureSubclassRegistry({images, imageId, className}) {
  const shapeRef = await ensureRegistryShape(images, imageId);
  const id = subclassRegistryId(className);
  const ref = objectRef(imageId, id);
  const conflict = () => new SmalltalkSubclassRegistryConflictError(ref);
  // The empty registry is only a SEED: the record is appended to afterwards under its own CAS, so
  // a present (or concurrently created) registry is adopted as it is — never overwritten by a
  // late creator, and never compared for identity (ensure owner, seed mode).
  const record = await ensureObject(images, imageId, {
    id, shape: shapeRef, behavior: null, slots: {}, indexed: [], metadata: {smalltalk: 'subclass-registry'},
  }, {seed: true, conflict});
  const members = subclassRegistryMembers(record, ref);
  return {ref, record, members};
}

// The indexed member set is the only mutable part of a registry. Seed admission deliberately
// adopts an already-present record, so this owner must validate every immutable field and the set
// invariant before it interprets that record as subclass state.
function subclassRegistryMembers(record, registryRef) {
  const conflict = () => new SmalltalkSubclassRegistryConflictError(registryRef);
  if (
    !record
    || record.kind !== 'object'
    || record.imageId !== registryRef.imageId
    || record.id !== registryRef.objectId
    || !isObjectRef(record.shape)
    || record.shape.imageId !== registryRef.imageId
    || record.shape.objectId !== SUBCLASS_REGISTRY_SHAPE_ID
    || record.behavior !== null
    || !record.slots
    || typeof record.slots !== 'object'
    || Array.isArray(record.slots)
    || Object.keys(record.slots).length !== 0
    || !record.metadata
    || record.metadata.smalltalk !== 'subclass-registry'
    || Object.keys(record.metadata).length !== 1
    || !Array.isArray(record.indexed)
  ) {
    throw conflict();
  }

  const seen = new Set();
  for (const member of record.indexed) {
    if (!isObjectRef(member) || member.imageId !== registryRef.imageId) throw conflict();
    const key = member.objectId;
    if (seen.has(key)) throw conflict();
    seen.add(key);
  }
  return record.indexed;
}

// Membership-guarded append: replaying `defineClass` never duplicates an entry.
async function appendSubclass({images, imageId, superclassName, subclassRef}) {
  const {ref: registryRef, record, members: current} = await ensureSubclassRegistry({
    images, imageId, className: superclassName,
  });
  const present = current.some(
    (ref) => isObjectRef(ref) && ref.imageId === subclassRef.imageId && ref.objectId === subclassRef.objectId,
  );
  if (present) return;
  try {
    await images.putObject(imageId, {
      id: record.id,
      shape: record.shape,
      behavior: null,
      slots: record.slots,
      indexed: [...current, subclassRef],
      metadata: record.metadata,
    }, {expectedVersion: record._version});
  } catch (error) {
    if (error?.name !== 'VersionConflictError') throw error;

    // The CAS remains authoritative. Classify its winner once, by this owner's set semantics:
    // another contender adding the same ref completed our request, while every other winner is a
    // domain conflict. There is no second write and therefore no unbounded retry or overwrite.
    const winner = await images.getObject(registryRef.imageId, registryRef.objectId);
    let winnerMembers;
    try {
      winnerMembers = subclassRegistryMembers(winner, registryRef);
    } catch {
      throw new SmalltalkSubclassRegistryConflictError(registryRef, subclassRef);
    }
    if (winnerMembers.some(
      (ref) => ref.imageId === subclassRef.imageId && ref.objectId === subclassRef.objectId,
    )) return;
    throw new SmalltalkSubclassRegistryConflictError(registryRef, subclassRef);
  }
}

// `defineClass` calls this for every class it defines. It registers the CLASS
// object's superclass edge (never the metaclass's derived one) in the
// superclass's registry, and ensures this class's own empty registry. Lazy and
// tolerant: bootstrap classes are defined before the registry Shape exists, and
// absence reads as empty, so this converges on retry rather than failing the
// definition. The superclass edge is the one `defineClass` was given — `Object`
// for a default superclass, so ordinary classes register under `Object`.
async function maintainSubclassRegistries({images, imageId, className, classRef, superclassRef, nilRef}) {
  requiredText(className, 'class name');
  // Ensure this class's own (empty) registry first so every class is introspectable.
  await ensureSubclassRegistry({images, imageId, className});
  if (!isObjectRef(superclassRef) || (nilRef && superclassRef.objectId === nilRef.objectId)) return;
  // The root Object class has no superclass to register under; its superclass
  // edge is the kernel nil, handled above.
  const superclassName = (await readBehavior(images, superclassRef)).name;
  if (superclassName?.kind !== 'text' || superclassName.value.length === 0) return;
  await appendSubclass({images, imageId, superclassName: superclassName.value, subclassRef: classRef});
}

// The protocol methods, written in Smalltalk over OrderedCollection and the
// `subclasses-of` primitive. `subclasses` answers the direct set;
// `allSubclasses` walks it transitively (depth-first, order-insensitive by
// contract — membership is what callers may rely on).
const SUBCLASS_PROTOCOL_METHODS = Object.freeze([
  {
    selector: 'subclasses',
    source: `[ | arr coll |
      arr := primitiveSubclassesOf value: self.
      coll := OrderedCollection new.
      1 to: arr size do: [:i | coll add: (arr at: i)].
      ^ coll ]`,
  },
  {
    selector: 'allSubclasses',
    source: `[ | result work |
      result := OrderedCollection new.
      work := OrderedCollection new.
      self subclasses do: [:s | work add: s].
      [ work isEmpty ] whileFalse: [
        | current |
        current := work removeLast.
        result add: current.
        current subclasses do: [:s | work add: s].
      ].
      ^ result ]`,
  },
]);

async function installSmalltalkSubclassProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // The primitive Block, published on the same `smalltalk-kernel-primitive/v1`
  // seam as the other kernel primitives.
  const code = await ensureCodeArtifact(images, imageId, {
    id: `${SUBCLASSES_OF_BLOCK_ID}:code`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    content: textValue(primitiveCodeContent(SMALLTALK_PRIMITIVE.SUBCLASSES_OF)),
    metadata: {smalltalk: 'kernel-primitive', primitive: SMALLTALK_PRIMITIVE.SUBCLASSES_OF},
  });
  const primitiveBlock = await ensureBlock(images, imageId, {
    id: SUBCLASSES_OF_BLOCK_ID,
    code: objectRef(imageId, code.id),
    environment: null,
    metadata: {smalltalk: 'kernel-primitive', primitive: SMALLTALK_PRIMITIVE.SUBCLASSES_OF},
  });

  // The methods live on Class so every class understands them; an instance does
  // not (defence-in-depth behind the primitive's own receiver guard).
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.classClass,
    methods: SUBCLASS_PROTOCOL_METHODS.map(({selector, source}) => ({
      selector,
      source,
      captures: [{...SUBCLASSES_OF_CAPTURE, value: objectRef(imageId, primitiveBlock.id)}],
    })),
  });

  return Object.freeze({
    protocol: 'smalltalk-subclass-protocol/v1',
    subclassesOfPrimitive: objectRef(imageId, primitiveBlock.id),
    classClass: kernel.classClass,
  });
}

export {
  SUBCLASS_REGISTRY_SHAPE_ID,
  SmalltalkSubclassRegistryConflictError,
  installSmalltalkSubclassProtocol,
  maintainSubclassRegistries,
  subclassRegistryId,
};

import {
  SYMBOL_CLASS_NAME,
  SYMBOL_SHAPE_ID,
  SYMBOL_SPELLING_SLOT,
} from './smalltalk-primitives-symbol.js';
import {
  SMALLTALK_PRIMITIVE,
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  primitiveCodeContent,
} from './smalltalk-primitive-support.js';
import {defineMethods, ensureNamedClass, ensureSmalltalkShape} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {objectRef, textValue} from '../value/index.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// Symbol protocol installation: the Symbol class, its Shape, the interner primitive,
// Object>>perform: / perform:with:, and Text>>asSymbol through the same interner as literals.
//
// This is a primitive-backed protocol (Pattern B): primitive Blocks installed first,
// then methods that capture refs to them and send value:/value:value:.

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.SYMBOL_INTERN]: 'smalltalk/primitive/symbol-intern',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND]: 'smalltalk/primitive/perform-send',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH]: 'smalltalk/primitive/perform-send-with',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.SYMBOL_INTERN]: '$symbol',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND]: '$performSend',
  [SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH]: '$performSendWith',
});

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const codeId = `${id}:code`;
  await ensureCodeArtifact(images, imageId, {
    id: codeId,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    languageId: SYMMETRIC_SMALLTALK_ID,
    content: textValue(primitiveCodeContent(primitive)),
    dependencies: [],
    derivedFrom: [],
    metadata: {},
  });
  await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeId),
    environment: null,
    metadata: {},
  });
  return objectRef(imageId, id);
}

function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = {
    id: PRIMITIVE_BLOCK_ID[primitive],
    name: CAPTURE_NAME[primitive],
  };
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{id: capture.id, name: capture.name}],
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'binding', id: capture.id},
        message: textValue('value:'.repeat(args.length)),
        arguments: args,
      },
    },
    captures: [{id: capture.id, name: capture.name, value: objectRef(imageId, capture.id)}],
  };
}

async function installSmalltalkSymbolProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('images service is required');
  }
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // 1. Install the Shape
  await ensureSmalltalkShape(images, imageId, {
    id: SYMBOL_SHAPE_ID,
    slots: [{id: SYMBOL_SPELLING_SLOT, name: 'spelling'}],
  });

  // 2. Install primitive Blocks
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.SYMBOL_INTERN});
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND});
  await installPrimitiveBlock({images, imageId, primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH});

  // 3. Create the Symbol class
  const {classRef: symbolClassRef} = await ensureNamedClass({
    images,
    imageId,
    name: SYMBOL_CLASS_NAME,
    superclassRef: kernel.objectClass,
    instanceShapeRef: objectRef(imageId, SYMBOL_SHAPE_ID),
  });

  // 4. Install Symbol>>asString — answers the spelling slot. Uses the class-scoped
  //    compiler so the instance variable read goes through the ordinary slot primitive.
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: symbolClassRef,
    methods: [{selector: 'asString', source: '[ spelling ]'}],
  });

  // 5. Install Object>>perform: and Object>>perform:with: on the Object class
  await defineMethods({
    images,
    compilation,
    imageId,
    lane,
    classRef: kernel.objectClass,
    methods: [
      capturedMethod({
        selector: 'perform:',
        primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND,
        parameters: ['aSymbol'],
        args: [{op: 'receiver'}, {op: 'argument', index: 0}],
        imageId,
      }),
      capturedMethod({
        selector: 'perform:with:',
        primitive: SMALLTALK_PRIMITIVE.PERFORM_SEND_WITH,
        parameters: ['aSymbol', 'anObject'],
        args: [{op: 'receiver'}, {op: 'argument', index: 0}, {op: 'argument', index: 1}],
        imageId,
      }),
    ],
  });

  // The real YAXO element-name initializer reaches this conversion. The existing interner owns
  // arbitrary spelling and canonical identity; Text adds only an ordinary call to it.
  await defineMethods({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [capturedMethod({
      selector: 'asSymbol', primitive: SMALLTALK_PRIMITIVE.SYMBOL_INTERN,
      args: [{op: 'receiver'}], imageId,
    })],
  });

  return Object.freeze({symbolClass: symbolClassRef});
}

