import {objectRef, textValue} from '../value/index.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {assertMethodLane, defineMethods} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {
  SMALLTALK_KERNEL_PRIMITIVE_V1,
  SMALLTALK_PRIMITIVE,
  primitiveCodeContent,
} from './smalltalk-primitives.js';
import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

// WS3 Text/ByteArray slice: the Smalltalk protocol over the byte-sequence
// primitive family (smalltalk-primitives-bytes.js).
//
//   Text       >> utf8Bytes        primitiveTextUtf8Bytes value: self
//   (private) Unicode scalar       primitiveUnicodeScalarUtf8Bytes value: scalar
//   Text       >> asString/isEmpty ordinary Text protocol (the latter forced by ADR 0091)
//   ByteArray  >> utf8Text         primitiveByteArrayUtf8Text value: self
//   ByteArray  >> size             primitiveByteArraySize value: self
//   ByteArray  >> at:              primitiveByteArrayAt value: self value: index
//   ByteArray class >> fromArray:  ^ primitiveArrayToByteArray value: anArray
//
// `Text` is a native text Value and `ByteArray` a native bytes Value — both
// dispatch through their kernel classes, so the methods land on those classes
// directly (Pattern B, like Symbol). `fromArray:` is the explicit, narrowly
// named conversion from an integer Array buffer; it validates every element.
//
// ByteArray stays immutable for this slice: no `at:put:`, and no widening of
// the ADR 0047 indexed primitives to bytes Values.

const PRIMITIVE_BLOCK_ID = Object.freeze({
  [SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES]: 'smalltalk/primitive/text-utf8-bytes',
  [SMALLTALK_PRIMITIVE.UNICODE_SCALAR_UTF8_BYTES]: 'smalltalk/primitive/unicode-scalar-utf8-bytes',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT]: 'smalltalk/primitive/bytearray-utf8-text',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE]: 'smalltalk/primitive/bytearray-size',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_AT]: 'smalltalk/primitive/bytearray-at',
  [SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY]: 'smalltalk/primitive/array-to-bytearray',
});

const CAPTURE_NAME = Object.freeze({
  [SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES]: '$textUtf8Bytes',
  [SMALLTALK_PRIMITIVE.UNICODE_SCALAR_UTF8_BYTES]: '$unicodeScalarUtf8Bytes',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT]: '$byteArrayUtf8Text',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE]: '$byteArraySize',
  [SMALLTALK_PRIMITIVE.BYTEARRAY_AT]: '$byteArrayAt',
  [SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY]: '$arrayToByteArray',
});

async function installPrimitiveBlock({images, imageId, primitive}) {
  const id = PRIMITIVE_BLOCK_ID[primitive];
  const codeId = `${id}:code`;
  await ensureCodeArtifact(images, imageId, {
    id: codeId,
    representation: SMALLTALK_KERNEL_PRIMITIVE_V1,
    languageId: SYMMETRIC_SMALLTALK_ID,
    content: textValue(primitiveCodeContent(primitive)),
    dependencies: [],
    derivedFrom: [],
    metadata: {},
  });
  await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeId),
    environment: null,
    metadata: {},
  });
  return objectRef(imageId, id);
}

function capturedMethod({selector, primitive, parameters = [], args, imageId}) {
  const capture = {id: PRIMITIVE_BLOCK_ID[primitive], name: CAPTURE_NAME[primitive]};
  return {
    selector,
    program: {
      parameters: parameters.map((name, index) => ({id: `${selector}:parameter:${index}`, name})),
      captures: [{id: capture.id, name: capture.name}],
      body: {
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: {op: 'binding', id: capture.id},
        message: textValue('value:'.repeat(args.length)),
        arguments: args,
      },
    },
    captures: [{id: capture.id, name: capture.name, value: objectRef(imageId, capture.id)}],
  };
}

const argument = (index) => ({op: 'argument', index});
const receiver = () => ({op: 'receiver'});

async function installSmalltalkTextByteArrayProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  if (!images || typeof images.getObject !== 'function') {
    throw new TypeError('images service is required');
  }
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  for (const primitive of [
    SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES,
    SMALLTALK_PRIMITIVE.UNICODE_SCALAR_UTF8_BYTES,
    SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT,
    SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE,
    SMALLTALK_PRIMITIVE.BYTEARRAY_AT,
    SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY,
  ]) {
    await installPrimitiveBlock({images, imageId, primitive});
  }

  // Text >> utf8Bytes
  await defineMethods({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [capturedMethod({
      selector: 'utf8Bytes', primitive: SMALLTALK_PRIMITIVE.TEXT_UTF8_BYTES, args: [receiver()], imageId,
    })],
  });

  // Ordinary Text protocol. `asString` answers the receiver: a Text's string form is itself. The
  // `isEmpty` predicate is forced by the first consumer of native `Text class>>streamContents:`:
  // unchanged YAXO `XMLTokenizer>>nextWhitespace` observes the returned text through exactly that
  // selector. Its separately classified earlier `~~` dependency is now product equality protocol;
  // no fixture participates. Equality with the empty Text is sufficient and keeps this in ordinary
  // Smalltalk; no byte/string-size primitive or broader collection inheritance is invented.
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: kernel.textClass,
    methods: [
      {selector: 'asString', source: '[ ^ self ]'},
      {selector: 'isEmpty', source: "[ ^ self = '' ]"},
    ],
  });

  // ByteArray >> utf8Text / size / at:
  await defineMethods({
    images, compilation, imageId, lane, classRef: kernel.byteArrayClass,
    methods: [
      capturedMethod({
        selector: 'utf8Text', primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_UTF8_TEXT, args: [receiver()], imageId,
      }),
      capturedMethod({
        selector: 'size', primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_SIZE, args: [receiver()], imageId,
      }),
      capturedMethod({
        selector: 'at:',
        primitive: SMALLTALK_PRIMITIVE.BYTEARRAY_AT,
        parameters: ['index'],
        args: [receiver(), argument(0)],
        imageId,
      }),
    ],
  });

  // ByteArray class >> fromArray: — the explicit, narrowly named conversion from
  // an integer Array buffer; the primitive validates every element 0..255.
  await defineMethods({
    images, compilation, imageId, lane, classRef: objectRef(imageId, 'smalltalk/metaclass/ByteArray'),
    methods: [capturedMethod({
      selector: 'fromArray:',
      primitive: SMALLTALK_PRIMITIVE.ARRAY_TO_BYTEARRAY,
      parameters: ['anArray'],
      args: [argument(0)],
      imageId,
    })],
  });

  return Object.freeze({
    protocol: 'smalltalk-text-bytearray/v1',
    textClass: kernel.textClass,
    byteArrayClass: kernel.byteArrayClass,
  });
}

export {
  PRIMITIVE_BLOCK_ID as SMALLTALK_TEXT_CODEC_PRIMITIVE_BLOCK_ID,
  installSmalltalkTextByteArrayProtocol,
};

import {assertMethodLane, ensureNamedClass, ensureSmalltalkShape, methodBlockRef} from './smalltalk-class-builder.js';
import {defineMethodsFromSource} from './smalltalk-instance-variables.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {resolveGlobal} from './smalltalk-globals.js';
import {objectRef} from '../value/index.js';
import {SMALLTALK_PRIMITIVE} from './smalltalk-primitives.js';
import {SMALLTALK_TEXT_CODEC_PRIMITIVE_BLOCK_ID} from './smalltalk-text-bytearray.js';

// A native `WriteStream`, added because a real imported consumer names it: the pinned upstream
// Cuis JSON package opens `Json class>>render:` with `WriteStream on: String new` and closes it
// with `contents`, and the native compiler answered `unbound Symmetric Smalltalk name: WriteStream`
// (bead lagrange-images-nv1.4). This is an ordinary native Smalltalk class published as an
// ordinary global, usable by any native code — NOT a Cuis compatibility class. The Cuis import
// adapter knows nothing about the name: it resolves here the same way `Array` or `Dictionary`
// does, through the image's global namespace at compile time.
//
// SCOPE. Exactly the protocol the acceptance path sends, and nothing else:
//
//   WriteStream class >> on:          the stream the source constructs
//   WriteStream       >> nextPutAll:  chunk write (bead lagrange-images-nv1.8)
//   WriteStream       >> nextPut:     Character element write (bead lagrange-images-xxm.14)
//   WriteStream       >> reset        reuse the same stream for a new written prefix (p6u)
//   WriteStream       >> contents     the answer it takes back out
//   Text class        >> streamContents:  evaluate one producer Block through that stream owner
//
// `with:`, arbitrary positioning and byte-stream breadth remain absent. Execution
// pressure adds protocol one proven consumer at a time. `nextPut:` is now earned by unchanged YAXO
// XMLTokenizer>>nextWhitespace after its preceding Character classification became executable.
// `Text class >> streamContents:` is ordinary native Text protocol: the Cuis importer owns only
// the exact foreign receiver-name adaptation that reaches it.
//
// RECORDED REAL-CUIS ORACLE (pinned VM + Cuis7.9-8090 image, probed directly; the full transcript
// is on bead lagrange-images-nv1.4). These are measurements, not Squeak/Pharo recollection:
//
//   (WriteStream on: 'hello') contents  =  ''        `on:` positions at the BEGINNING and
//   (WriteStream with: 'hello') contents = 'hello'   DISCARDS existing content. It is not append;
//                                                    append is `with:`, a selector nothing here
//                                                    needs. A probe using an EMPTY argument cannot
//                                                    tell the two apart, which is why the oracle
//                                                    was rerun with a non-empty one.
//   contents preserves the backing SPECIES           String -> String, Array -> Array,
//                                                    OrderedCollection -> OrderedCollection.
//   contents answers a FRESH COPY every call         not identical to the backing, not identical
//                                                    across two calls, equal across two calls.
//   contents is the WRITTEN PREFIX only              after one write over a 5-element backing it
//                                                    answers 1 element.
//
// and the upstream source itself, read out of the pinned image rather than paraphrased:
//
//   contents   readLimit := readLimit max: position.
//              ^ (collection copyFrom: 1 to: position) asStreamResult.
//   on: arg1   super on: arg1 thatCanBeModified. readLimit := 0. writeLimit := arg1 size.
//
// WHY `contents` IS WHAT IT IS. Upstream answers a PREFIX COPY, and its class preservation is a
// consequence of `copyFrom:to:` being class-preserving rather than of any explicit species send.
// That is the shape this class now follows: build the answer, preserving the backing's class.
//
// That handoff has since been taken, and taken further than the note expected: `contents` no longer
// asks the backing to build anything. It constructs the answer itself, preserving the backing's
// class, which is what upstream's copy does. See `contents` below.
//
// KNOWN DIVERGENCE, asserted by a test rather than only described here. Cuis implements `species`
// on OBJECT, so upstream every backing answers it. This image implements `species` only on
// COLLECTION. That no longer limits the two backings that matter — a text backing is built without
// `species` at all, and a Collection answers it — but any OTHER backing (Array, Dictionary, Symbol,
// ByteArray) still fails visibly with a message-not-understood naming `species`. Adding
// `Object >> species` would close that, and would match upstream, but it would not have made a
// text backing work (`Text new` is not instantiable) and no consumer streams over the others, so
// it stays out as breadth this milestone forbids.
//
// NOT MODELLED. Cuis puts WriteStream under `PositionableStream`, and its `on:` also resets a
// position and a read limit. This class is a direct subclass of Object and models no position:
// writes append and `contents` consumes the current accumulation. The measured `reset` operation
// starts a new written prefix by clearing that accumulation, preserving the stream and backing.
// Arbitrary positioning or reading this stream would require a broader state model; neither is
// part of the currently forced protocol.

// v2: the chunk-write protocol added an instance variable, and a Shape record is immutable, so the
// structural change gets a new Shape identity rather than a rewrite (ADR 0047). An image that
// already holds the v1 class gets an explicit definition conflict from the class owner, which is
// the designed outcome — never a silent adoption of a differently-shaped class.
const WRITE_STREAM_SHAPE_ID = 'smalltalk/write-stream-instance-shape/v2';

// RETIRED: `WriteStreamContentsNeedsSpeciesPreservingResult`. The previous slice signalled that
// named condition once anything had been written, because `contents` could not then produce a
// result and answering an empty collection would have been a silent wrong answer. `contents` now
// produces the result, so the condition is unreachable and is gone rather than left as a class
// nothing can raise. Its NAME was never a decision about the repair, and the repair it named is
// not the one that was taken.

// `on:` is two-sided here for the reason it is two-sided in Cuis (verified against the pinned
// image: the instance-side `on:` is implemented in `WriteStream` itself, the class-side one in
// `PositionableStream class`). The class-side entry point allocates through the ordinary
// `Class >> new` path and hands off to the instance-side initializer, which is the only writer of
// the instance variable. No third private selector is invented for it.
const WRITE_STREAM_CLASS_METHODS = [
  {selector: 'on:', source: '[ :aCollection | ^ self new on: aCollection ]'},
];

// The class is captured directly because this method is installed in the same transaction-shaped
// owner that first creates WriteStream, before the standard-image composition root publishes the
// class as a global. This is dependency injection, not a second stream implementation: every bit
// of allocation, accumulation and result construction is still sent to the one WriteStream owner.
const TEXT_STREAM_WRITE_STREAM_CAPTURE = Object.freeze({
  name: 'NativeWriteStream',
  id: 'smalltalk/text-stream/write-stream-class',
});

const WRITE_STREAM_SCALAR_CODEC_CAPTURE = Object.freeze({
  name: 'UnicodeScalarUtf8Bytes',
  id: SMALLTALK_TEXT_CODEC_PRIMITIVE_BLOCK_ID[SMALLTALK_PRIMITIVE.UNICODE_SCALAR_UTF8_BYTES],
});

const TEXT_STREAM_CLASS_METHODS = Object.freeze([Object.freeze({
  selector: 'streamContents:',
  source: `[ :aBlock | | stream |
    stream := NativeWriteStream on: ''.
    aBlock value: stream.
    ^ stream contents ]`,
})]);

const WRITE_STREAM_METHODS = [
  {selector: 'on:', source: '[ :aCollection | collection := aCollection. written := nil. ^ self ]'},
  // The one write selector execution actually named. It answers the STREAM, which is what upstream
  // does — measured, because the widespread Squeak/Pharo recollection is that `nextPutAll:` answers
  // its argument, and the pinned image shows otherwise (`answerIsStream=true`).
  //
  // THE ACCUMULATION. Upstream accumulates by mutating an indexed backing in place
  // (`collection replaceFrom: position + 1 to: ... with: ... startingAt: 1`). The native path has
  // no equivalent: the acceptance path's backing is an empty native Text, which is an immutable
  // VALUE, and this image has no text concatenation, no `replaceFrom:to:with:startingAt:` and no
  // mutable String. So the stream owns what it was given, in order, and `contents` builds the
  // answer from it. Still exposed by no selector — the accumulation is how the stream works, not
  // part of what it promises. Each entry carries a private Boolean tag so the one state retains
  // whether the caller wrote a collection chunk or one stream element; it is not a second channel.
  {
    selector: 'nextPutAll:',
    source: `[ :aCollection |
      written isNil ifTrue: [ written := OrderedCollection new ].
      written add: (Association new key: false value: aCollection).
      ^ self ]`,
  },
  // The pinned UnicodeString stream is Utf8EncodedWriteStream and its nextPut: implicitly answers
  // self. Keep the Character itself in the SAME ordered accumulation as chunk writes; conversion
  // belongs to the one contents constructor below, not to a second channel or nextPutAll: alias.
  {
    selector: 'nextPut:',
    source: `[ :anObject |
      written isNil ifTrue: [ written := OrderedCollection new ].
      written add: (Association new key: true value: anObject).
      ^ self ]`,
  },
  // THE ANSWER, built here rather than asked of the backing (bead lagrange-images-nv1.7).
  //
  // This REMOVES AN INCORRECT MECHANISM rather than working around a missing one, and that is the
  // part worth reading. Upstream `contents` is
  //
  //     ^ (collection copyFrom: 1 to: position) asStreamResult
  //
  // measured out of the pinned image — a CLASS-PRESERVING COPY of the written prefix. It never
  // sends `species` at all. The earlier `collection species new` was a stand-in that was never a
  // transcription of upstream: it happened to work only because `Collection >> species` exists,
  // and it could never have worked for the acceptance path, because `Text new` raises
  // SmalltalkNotInstantiableError — a Text is a Value, not an allocatable object. Adding
  // `Object >> species` would not have fixed that; it would have turned one visible failure into
  // another. So the stream constructs the result itself, preserving the backing's CLASS exactly as
  // the upstream copy does.
  //
  // Two constructions, because this image has two kinds of backing and they are built differently:
  //   a text backing   the accumulated chunks/elements' bytes, through the existing
  //                    `utf8Bytes` -> `ByteArray class >> fromArray:` -> `ByteArray >> utf8Text`
  //                    conversion that `Integer >> printOn:base:` already uses. Nothing is added to
  //                    Text, which stays an immutable Value with exactly the protocol it had.
  //   a collection     `species new` filled from the chunks' elements. That is the ordinary
  //                    Collection rule, already installed, and it is correct here because a
  //                    Collection IS allocatable.
  // Any other backing fails visibly on `species`, as before.
  //
  // ON SEED SPECIES, stated rather than papered over: upstream distinguishes a String-seeded from a
  // UnicodeString-seeded stream, and the result follows the seed (measured:
  // `unicodeSeedResultClass=UnicodeString` with the same textual value). This image has exactly ONE
  // textual class — `Text` IS the text Value — so that distinction has no native counterpart to
  // lose. What the native rule preserves is the only textual class there is, and a text-backed
  // stream answers a Text. If a second native textual representation ever exists, this method is
  // where the distinction has to be made, and it will need more than `class == Text`.
  //
  // An EMPTY accumulation is not a special case: zero chunks contribute zero elements, so an
  // unwritten stream answers an empty result of the backing's class, which is what nv1.4 proved.
  // An EMPTY WRITE contributes nothing either, so it answers empty too — which is exactly
  // upstream, where `nextPutAll: ''` leaves `position` at 0 and `contents` answers ''. The
  // call-based divergence the previous slice knowingly carried is gone.
  {
    selector: 'contents',
    source: `[ | bytes result |
      collection class == Text ifTrue: [
        bytes := OrderedCollection new.
        written isNil ifFalse: [
          written do: [ :entry | | chunkBytes index |
            entry key ifTrue: [
              chunkBytes := UnicodeScalarUtf8Bytes value: entry value codePoint ].
            entry key ifFalse: [ chunkBytes := entry value utf8Bytes ].
            index := 1.
            [ index <= chunkBytes size ] whileTrue: [
              bytes add: (chunkBytes at: index).
              index := index + 1 ] ] ].
        ^ (ByteArray fromArray: bytes asArray) utf8Text ].
      collection class == ByteArray ifTrue: [
        bytes := OrderedCollection new.
        written isNil ifFalse: [
          written do: [ :entry | | chunkBytes index |
            entry key ifTrue: [ bytes add: entry value ].
            entry key ifFalse: [
              chunkBytes := entry value.
              index := 1.
              [ index <= chunkBytes size ] whileTrue: [
                bytes add: (chunkBytes at: index).
                index := index + 1 ] ] ] ].
        ^ ByteArray fromArray: bytes asArray ].
      result := collection species new.
      written isNil ifFalse: [
        written do: [ :entry |
          entry key ifTrue: [ result add: entry value ].
          entry key ifFalse: [ entry value do: [ :each | result add: each ] ] ] ].
      ^ result ]`,
    captures: [WRITE_STREAM_SCALAR_CODEC_CAPTURE],
  },
  // Pinned UnicodeString writeStream reset answers self and empty contents. With only append,
  // contents and reset exposed, forgetting the written prefix preserves that exact behavior.
  {selector: 'reset', source: '[ written := nil. ^ self ]'},
];

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

async function installSmalltalkWriteStreamProtocol({images, compilation, imageId, lane = 'neutral'} = {}) {
  requiredText(imageId, 'image id');
  assertMethodLane(lane);
  const kernel = await findSmalltalkKernel({images, imageId});
  if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel`);

  // Restored prerequisite, checked where the cause is still visible rather than as a
  // doesNotUnderstand inside a method body later. `contents` answers through `species`, which this
  // image installs on Collection, so what must exist is that installed METHOD — not the Collection
  // global. Checking the global would be both too weak and too strong: a Collection class whose
  // methods are not yet defined would pass it, and an image with the library fully installed but
  // Collection unpublished would fail it although `species` works there perfectly well. This is
  // the same read-the-installed-method rule `smalltalk-library.js` applies to its own
  // prerequisites, and for the same stated reason.
  // Existence first, then the method: `methodBlockRef` reads a Behavior, so asking it about a
  // class that was never defined raises `behavior not found` rather than answering "absent".
  // This is the exact two-step `smalltalk-library.js` uses for its own `Exception >> signal` check.
  // Every method this class's source calls, in the class that must implement it. Checked as
  // installed METHODS rather than as class or global existence, because publication says nothing
  // about protocol and a half-installed image would otherwise compile cleanly and fail on first
  // use — `ByteArray` in particular is a KERNEL class whose global the namespace publishes
  // unconditionally, so a global check alone passes on an image that never ran the byte-sequence
  // protocol. `isNil`, `ifTrue:` and `ifFalse:` each need BOTH halves, since the receiver may be
  // either.
  const required = [
    ['smalltalk/class/Collection', 'species'],
    ['smalltalk/class/OrderedCollection', 'add:'],
    ['smalltalk/class/Association', 'key'],
    ['smalltalk/class/Association', 'value'],
    ['smalltalk/class/Association', 'key:value:'],
    ['smalltalk/class/Text', 'utf8Bytes'],
    ['smalltalk/class/Character', 'codePoint'],
    ['smalltalk/class/ByteArray', 'utf8Text'],
    ['smalltalk/class/ByteArray', 'size'],
    ['smalltalk/class/ByteArray', 'at:'],
    ['smalltalk/metaclass/ByteArray', 'fromArray:'],
    ['smalltalk/class/OrderedCollection', 'do:'],
    ['smalltalk/class/OrderedCollection', 'asArray'],
    ['smalltalk/class/Object', 'isNil'],
    ['smalltalk/class/UndefinedObject', 'isNil'],
    ['smalltalk/class/True', 'ifTrue:'],
    ['smalltalk/class/False', 'ifTrue:'],
    ['smalltalk/class/True', 'ifFalse:'],
    ['smalltalk/class/False', 'ifFalse:'],
    ['smalltalk/class/Object', 'class'],
    ['smalltalk/class/Class', 'new'],
  ];
  for (const [objectId, selector] of required) {
    const classRef = objectRef(imageId, objectId);
    if (!await images.getObject(imageId, objectId)
      || !await methodBlockRef({images, imageId, classRef, selector})) {
      throw new TypeError(`image ${imageId} has no ${objectId} ${selector} method; install the library first`);
    }
  }
  // The source also NAMES these globals, which is a compile-time requirement distinct from the
  // protocol above.
  for (const name of ['Association', 'OrderedCollection', 'Text', 'ByteArray']) {
    if (!await resolveGlobal({images, imageId, name})) {
      throw new TypeError(`image ${imageId} has not published the global ${name}; publish it first`);
    }
  }

  const instanceShapeRef = await ensureSmalltalkShape(images, imageId, {
    id: WRITE_STREAM_SHAPE_ID,
    slots: [
      {id: 'write-stream-collection', name: 'collection'},
      // Internal, and exposed by no selector: see the note on `nextPutAll:`.
      {id: 'write-stream-written', name: 'written'},
    ],
  });
  const {classRef, metaclassRef} = await ensureNamedClass({
    images, imageId, name: 'WriteStream', superclassRef: null, instanceShapeRef,
  });


  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef,
    methods: WRITE_STREAM_METHODS.map((method) => ({
      ...method,
      captures: method.captures?.map((capture) => ({
        ...capture,
        value: objectRef(imageId, capture.id),
      })),
    })),
  });
  await defineMethodsFromSource({
    images, compilation, imageId, lane, classRef: metaclassRef, methods: WRITE_STREAM_CLASS_METHODS,
  });
  await defineMethodsFromSource({
    images,
    compilation,
    imageId,
    lane,
    classRef: objectRef(imageId, 'smalltalk/metaclass/Text'),
    methods: TEXT_STREAM_CLASS_METHODS.map((method) => ({
      ...method,
      captures: [{...TEXT_STREAM_WRITE_STREAM_CAPTURE, value: classRef}],
    })),
  });

  return Object.freeze({classRef, metaclassRef});
}

export {
  WRITE_STREAM_CLASS_METHODS,
  WRITE_STREAM_METHODS,
  WRITE_STREAM_SHAPE_ID,
  installSmalltalkWriteStreamProtocol,
};

import {uuid as randomUUID} from '../support/default-crypto.js';
import {ensureBlock, ensureCodeArtifact, ensureLexicalEnvironment} from '../graph/ensure-records.js';
import {
  ARRAY_BINDING_ID,
  CHARACTER_BINDING_ID,
  NIL_BINDING_ID,
  SYMBOL_BINDING_ID,
} from './symmetric-smalltalk-semantic.js';
import {findSmalltalkKernel} from './smalltalk-kernel.js';
import {globalDeclarations} from './smalltalk-globals.js';
import {LAGRANGE_CODE_V0} from '../code/lagrange-code-v0.js';
import {LAGRANGE_CODE_V1} from '../code/lagrange-code-v1.js';
import {CompilationService, createDefaultCodeCompilerRegistry} from '../compilation/index.js';
import {NEUTRAL_EXPRESSION_V0} from '../execution/neutral-expression-v0.js';
import {NEUTRAL_EXPRESSION_V1} from '../execution/neutral-expression-v1.js';
import {objectRef, textValue} from '../value/index.js';
import {
  executableTargetFor,
  installNestedPrototypes,
} from './smalltalk-nested-blocks.js';
import {compileSymmetricSmalltalkSemanticBlock} from './symmetric-smalltalk-semantic.js';
import {SYMMETRIC_SMALLTALK_ID, SYMMETRIC_SMALLTALK_SOURCE_V0} from './symmetric-smalltalk.js';

const SYMMETRIC_SMALLTALK_SYNTAX_V0 = 'symmetric-smalltalk/syntax-v0';

function compileSymmetricSmalltalkBlock(source, options = {}) {
  // `nil` needs nothing here: the semantic compiler owns that intrinsic and offers it to every
  // compilation (ADR 0056), so this wrapper cannot get it wrong or out of step.
  //
  // Globals are different: they are image state, so an image-scoped caller reads them and hands the
  // resolved declarations down. This function stays synchronous and storage-free (ADR 0057), and a
  // caller with no declarations gets exactly today's behaviour.
  const {syntax, program, representation, globalBindingIdsUsed} =
    compileSymmetricSmalltalkSemanticBlock(source, options);
  return Object.freeze({syntax, semanticProgram: program, program, representation, globalBindingIdsUsed});
}

// Deterministic per Block, so an identical retry converges like every other write here.
//
// The identity is deliberately conditional. A Block that uses only `nil` keeps ADR 0056's existing
// `${id}:nil-environment`, because renaming it would change the durable definition of every
// pre-0057 nil Block and stop reinstallation converging. A Block that uses globals gets the broader
// identity instead.
async function ensureCompilerSuppliedEnvironment({
  images, imageId, id, parent, program, globalBindingIdsUsed,
}) {
  const captures = program.captures ?? [];
  const captureIds = new Set(captures.map(({id: captureId}) => captureId));
  const usesNil = captureIds.has(NIL_BINDING_ID);
  const usesSymbol = captureIds.has(SYMBOL_BINDING_ID);
  const usesCharacter = captureIds.has(CHARACTER_BINDING_ID);
  const usesArray = captureIds.has(ARRAY_BINDING_ID);
  // Exactly the globals compilation resolved — never every published id that happens to appear
  // among the captures. An explicit caller capture may legitimately use an id that is also a
  // published binding, and substituting the binding object for the caller's value would collapse
  // two meanings onto one identity.
  //
  // The *name* comes from the semantic program's capture descriptor, not from the current namespace.
  // Namespace aliases are compile-time lookup affordances; once a name resolved to identity X, adding
  // another alias for X must not change the durable definition of an already-compiled Block on retry.
  const resolved = new Set(globalBindingIdsUsed ?? []);
  const globalCaptures = [];
  for (const bindingId of resolved) {
    const capture = captures.find(({id}) => id === bindingId);
    if (!capture) {
      throw new TypeError(`global binding ${bindingId} was resolved but is absent from the semantic capture list`);
    }
    globalCaptures.push(capture);
  }
  if (!usesNil && !usesSymbol && !usesCharacter && !usesArray && globalCaptures.length === 0) return parent;

  const bindings = {};
  if (usesNil) {
    const kernel = await findSmalltalkKernel({images, imageId});
    if (!kernel) throw new TypeError(`image ${imageId} has no Smalltalk kernel; nil has no value there`);
    bindings[NIL_BINDING_ID] = {name: 'nil', value: kernel.nil};
  }
  if (usesSymbol) {
    bindings[SYMBOL_BINDING_ID] = {name: '$symbol', value: objectRef(imageId, 'smalltalk/primitive/symbol-intern')};
  }
  if (usesCharacter) {
    bindings[CHARACTER_BINDING_ID] = {
      name: '$character', value: objectRef(imageId, 'smalltalk/primitive/character-intern'),
    };
  }
  if (usesArray) {
    // The empty literal Array `#()` lowers to `new: 0` against this image's Array class. The
    // compiler carries only the intrinsic id; the image-local class ref lives here, in the
    // environment — never in the semantic artifact.
    bindings[ARRAY_BINDING_ID] = {name: '$array', value: objectRef(imageId, 'smalltalk/class/Array')};
  }
  for (const {id: bindingId, name} of globalCaptures) {
    // The image-local ref lives here, in the environment — never in the semantic artifact.
    bindings[bindingId] = {name, value: objectRef(imageId, bindingId)};
  }

  const environmentId = globalCaptures.length === 0 && !usesSymbol && !usesCharacter && !usesArray
    ? `${id}:nil-environment`
    : `${id}:compiler-environment`;
  const record = await ensureLexicalEnvironment(images, imageId, {
    id: environmentId,
    ...(parent ? {parent} : {}),
    bindings,
  });
  return objectRef(imageId, record.id);
}

function resolveCompilation(images, compilation) {
  if (compilation) {
    if (typeof compilation.compileArtifact !== 'function') throw new TypeError('compilation service must implement compileArtifact');
    return compilation;
  }
  return new CompilationService({images, compilers: createDefaultCodeCompilerRegistry()});
}

async function installSymmetricSmalltalkBlock({
  images,
  compilation = null,
  imageId,
  source,
  id = randomUUID(),
  captures = {},
  environment = null,
  metadata = {},
  // ADR 0061: which namespace this Block compiles in. Defaulting to the root reproduces ADR 0057's
  // behavior for every existing caller; a nested namespace's chain is walked to resolve globals.
  namespaceId,
} = {}) {
  if (!images || typeof images.putCodeArtifact !== 'function' || typeof images.putBlock !== 'function') {
    throw new TypeError('images service with code-artifact and block persistence is required');
  }
  const compiler = resolveCompilation(images, compilation);
  // The image-scoped seam: the namespace is read here, asynchronously, and passed into the
  // synchronous compiler as a transient name -> binding-id map. The chain walk happens inside
  // globalDeclarations; the compiler itself still only sees a flat map.
  const globals = await globalDeclarations({images, imageId, namespaceId});
  const {syntax, semanticProgram, representation, globalBindingIdsUsed} =
    compileSymmetricSmalltalkBlock(source, {captures, globals});

  // Ensure-exact-or-create, like every other deterministic-id write in this repository. These were
  // direct `put`s, which made an *identical* retry fail on the first record — so a partially
  // completed installation could not be completed by repeating it. Pre-existing and unrelated to
  // any one feature; converted here because ADR 0056 is the first thing to depend on it.
  const sourceArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:source`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SYMMETRIC_SMALLTALK_SOURCE_V0,
    content: textValue(source),
    metadata,
  });
  const syntaxArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:syntax`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation: SYMMETRIC_SMALLTALK_SYNTAX_V0,
    content: textValue(JSON.stringify(syntax)),
    derivedFrom: [objectRef(imageId, sourceArtifact.id)],
  });
  const semanticArtifact = await ensureCodeArtifact(images, imageId, {
    id: `${id}:semantic`,
    languageId: SYMMETRIC_SMALLTALK_ID,
    representation,
    content: textValue(JSON.stringify(semanticProgram)),
    derivedFrom: [objectRef(imageId, syntaxArtifact.id)],
  });

  const blockPrototypes = await installNestedPrototypes({
    images,
    compilation: compiler,
    imageId,
    rootId: id,
    parentSemanticRef: objectRef(imageId, semanticArtifact.id),
    program: semanticProgram,
    representation,
  });
  const codeArtifact = await compiler.compileArtifact(
    objectRef(imageId, semanticArtifact.id),
    {
      id: `${id}:code`,
      targetRepresentation: executableTargetFor(representation),
      options: {blockPrototypes},
    },
  );
  // ADR 0056 decision 2a, generalised by ADR 0057. Only a program that actually binds something the
  // compiler supplies needs an environment, so a Block using neither `nil` nor a global keeps
  // today's path exactly and writes no extra record.
  //
  // When one is needed it *parents* the caller's rather than copying its bindings: the caller's
  // environment is a record with its own lifecycle, and a copy would be a second answer to the same
  // question that could later drift from it. The chain walk is already the composition mechanism.
  //
  // One environment, not two wrappers, when a program uses both.
  const blockEnvironment = await ensureCompilerSuppliedEnvironment({
    images, imageId, id, parent: environment, program: semanticProgram, globalBindingIdsUsed,
  });

  const block = await ensureBlock(images, imageId, {
    id,
    code: objectRef(imageId, codeArtifact.id),
    environment: blockEnvironment,
    metadata,
  });
  return Object.freeze({
    syntax,
    semanticProgram,
    representation,
    // Transient provenance: which global bindings this compilation actually resolved. It is not
    // written to any artifact — lagrange-code stays a language-neutral representation — but callers
    // that bind captures need it, because a capture id alone never says why the capture exists.
    globalBindingIdsUsed,
    sourceArtifact,
    syntaxArtifact,
    semanticArtifact,
    codeArtifact,
    blockPrototypes,
    block,
  });
}

async function evaluateSymmetricSmalltalkBlock({runtime, arguments: args = [], ...installOptions} = {}) {
  if (!runtime?.images || !runtime?.invocations || !runtime?.executor) {
    throw new TypeError('runtime with images, invocations and executor is required');
  }
  const installed = await installSymmetricSmalltalkBlock({
    images: runtime.images,
    compilation: runtime.compilation ?? null,
    ...installOptions,
  });
  const activation = await runtime.invocations.invokeBlock(
    objectRef(installed.block.imageId, installed.block.id),
    args,
  );
  return await runtime.executor.execute(activation);
}

export {
  SYMMETRIC_SMALLTALK_SYNTAX_V0,
  compileSymmetricSmalltalkBlock,
  evaluateSymmetricSmalltalkBlock,
  installSymmetricSmalltalkBlock,
};

import {VALUE_KIND, isObjectRef} from '../value/index.js';
import {findSmalltalkKernel, isBehaviorObject} from './smalltalk-kernel.js';
import {
  MethodDictionaryValidationCache,
  SmalltalkDanglingEdgeError,
  behaviorRefFor,
  lookupSelector,
} from './smalltalk-lookup.js';
import {findSmalltalkBlockProtocol} from './smalltalk-block-protocol.js';
import {findSmalltalkBlockUnwindProtocol} from './smalltalk-conditions.js';
import {SMALLTALK_KERNEL_PRIMITIVE_V1} from './smalltalk-primitives.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';
import {NEUTRAL_EXPRESSION_V0} from '../execution/neutral-expression-v0.js';
import {NEUTRAL_EXPRESSION_V1, NEUTRAL_EXPRESSION_V2} from '../execution/neutral-expression-v1.js';
import {
  WASM_FUNCTION_V1,
  WASM_FUNCTION_V2,
  functionModuleRef,
  readFunctionSelection,
} from '../wasm/function-contract.js';
import {moduleFunctionOf, readModuleDescriptor} from '../wasm/module-contract.js';

function assertImages(images) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['getObject', 'getShape', 'getBlock', 'getCodeArtifact']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  return images;
}

// The only two selectors the dispatcher recognizes for a Block beyond `value`. Mapping selector to
// protocol slot name keeps the dispatcher's knowledge to "which slot", never "which object".
const LOOP_SELECTOR = Object.freeze({
  'whileTrue:': 'whileTrue',
  'whileFalse:': 'whileFalse',
  whileFalse: 'whileFalse',
});

// ADR 0054. A separate protocol object from the loop one, so the dispatcher still knows only slot
// names and never an object id, and an image with loops but no unwind protocol stays coherent.
const UNWIND_SELECTOR = Object.freeze({
  'on:do:': {slot: 'onDo', arity: 2},
  'ensure:': {slot: 'ensure', arity: 1},
  'ifCurtailed:': {slot: 'ifCurtailed', arity: 1},
});

function blockValueSelector(argumentCount) {
  if (!Number.isInteger(argumentCount) || argumentCount < 0) throw new TypeError('argument count must be a non-negative integer');
  return argumentCount === 0 ? 'value' : Array.from({length: argumentCount}, () => 'value:').join('');
}

// Block-evaluation owner arity introspection for `BlockClosure>>valueWithPossibleArgument:` (bead
// lagrange-images-4j9). Reads the parameter count from the Block's compiled executable contract
// (neutral-expression or WASM function/module) so `valueWithPossibleArgument:` evaluates `[self value]`
// when `numArgs = 0` and `[self value: anArg]` otherwise, matching the pinned Cuis oracle.
async function blockParameterCount(images, code) {
  if (
    code?.representation === NEUTRAL_EXPRESSION_V0
    || code?.representation === NEUTRAL_EXPRESSION_V1
    || code?.representation === NEUTRAL_EXPRESSION_V2
  ) {
    let parsed;
    try {
      parsed = JSON.parse(code.content?.value);
    } catch (error) {
      throw new TypeError(`${code.representation} content must be valid JSON`, {cause: error});
    }
    if (!Number.isInteger(parsed?.parameters) || parsed.parameters < 0) {
      throw new TypeError(`${code.representation} parameters must be a non-negative integer`);
    }
    return parsed.parameters;
  }
  if (code?.representation === WASM_FUNCTION_V1 || code?.representation === WASM_FUNCTION_V2) {
    const selection = readFunctionSelection(code);
    const moduleRef = functionModuleRef(code);
    const moduleArtifact = await images.getCodeArtifact(moduleRef.imageId, moduleRef.objectId);
    if (!moduleArtifact) throw new TypeError(`WASM module not found: ${moduleRef.imageId}/${moduleRef.objectId}`);
    return moduleFunctionOf(readModuleDescriptor(moduleArtifact), {entry: selection.entry}).parameters;
  }
  return null;
}

// The pre-ADR-0044 convention, unchanged: a behavior object whose *shape slot names* are selectors.
// Lifted here rather than reimplemented, so an already-stored object keeps answering exactly as it
// did before any kernel existed.
async function legacyLookup(images, behavior, selector) {
  const shape = await images.getShape(behavior.shape.imageId, behavior.shape.objectId);
  if (!shape) {
    throw new TypeError(`Symmetric Smalltalk behavior shape not found: ${behavior.shape.imageId}/${behavior.shape.objectId}`);
  }
  // Deliberately the pre-0044 TypeError and wording. Decision 10 preserves what an already-stored
  // object *means*, and a failure is part of that meaning: a legacy receiver that did not
  // understand a selector must still fail exactly as it did before any kernel existed.
  const methodSlot = shape.slots.find(({name}) => name === selector);
  if (!methodSlot) throw new TypeError(`Symmetric Smalltalk message not understood: ${selector}`);
  const blockRef = behavior.slots[methodSlot.id];
  if (!isObjectRef(blockRef)) {
    throw new TypeError(`Symmetric Smalltalk method slot ${methodSlot.id} must contain a Block ref`);
  }
  const block = await images.getBlock(blockRef.imageId, blockRef.objectId);
  if (!block) {
    throw new TypeError(`Symmetric Smalltalk method Block not found: ${blockRef.imageId}/${blockRef.objectId}`);
  }
  return blockRef;
}

// ADR 0045 decision 7: the key is present only when the language actually nominates a different
// receiver, so an ordinary send produces exactly the `{block}` resolution it always has.
function resolution(block, effectiveReceiver, frame = null) {
  return Object.freeze({
    ...(effectiveReceiver ? {effectiveReceiver} : {}),
    ...(frame ? {frame} : {}),
    block,
  });
}

function createSymmetricSmalltalkDispatcher({
  // Per dispatcher/runtime, so it lives and dies with the runtime that owns it rather than leaking
  // between images or across tests. Transient runtime state: never durable, never a Value, and
  // correct to drop at any moment (ADR 0049 decision 5a).
  validationCache = new MethodDictionaryValidationCache(),
} = {}) {
  if (validationCache !== null && typeof validationCache?.read !== 'function') {
    throw new TypeError('validationCache must implement read(record, ref, nilRef) or be null');
  }
  return Object.freeze({
    languageId: SYMMETRIC_SMALLTALK_ID,

    async resolveMessage(request, context) {
      const images = assertImages(context?.images);
      if (request.languageId !== SYMMETRIC_SMALLTALK_ID) {
        throw new TypeError(`unexpected language id for Symmetric Smalltalk dispatcher: ${request.languageId}`);
      }
      if (request.message?.kind !== VALUE_KIND.TEXT) {
        throw new TypeError('Symmetric Smalltalk v0 messages must be text Values');
      }
      const selector = request.message.value;

      // ADR 0044 decision 11: a Block answers value/value: without a class. Checked first, as it
      // always has been.
      if (isObjectRef(request.receiver)) {
        const blockReceiver = await images.getBlock(request.receiver.imageId, request.receiver.objectId);
        if (blockReceiver) {
          // ADR 0051: two more operations on the classless Block personality. The protocol is
          // looked up in the *condition* Block's image — which is the receiver, and therefore
          // already the dispatch image a nested send would compute — so the image that owns the
          // send owns the loop, and the answered nil is that image's.
          //
          // The dispatcher learns a protocol tag and two slot meanings, never an object id
          // (ADR 0044 decision 9). An image with no protocol falls through to the ordinary
          // does-not-understand below, which is the coherent answer for an image whose Blocks
          // simply do not loop; a corrupt one throws out of `findSmalltalkBlockProtocol` rather
          // than being degraded to that.
          const loopSlot = LOOP_SELECTOR[selector];
          if (loopSlot && request.arguments.length === (selector === 'whileFalse' ? 0 : 1)) {
            const protocol = await findSmalltalkBlockProtocol({images, imageId: request.receiver.imageId});
            // Decision 9: the loop primitive is the language's own host operation, so it inherits
            // the caller's frame. The condition and body do not — they are reached by ordinary
            // `value` sends, which inherit nothing.
            if (protocol) return Object.freeze({block: protocol[loopSlot], inheritsFrame: true});
          }
          const unwind = UNWIND_SELECTOR[selector];
          if (unwind && request.arguments.length === unwind.arity) {
            const protocol = await findSmalltalkBlockUnwindProtocol({images, imageId: request.receiver.imageId});
            // Same rule as the loop primitives: the unwind primitive is the language's own host
            // operation and inherits the caller's frame, while the protected, handler and cleanup
            // Blocks are invoked in their own right and inherit nothing.
            if (protocol) return Object.freeze({block: protocol[unwind.slot], inheritsFrame: true});
          }
          const code = await images.getCodeArtifact(blockReceiver.code.imageId, blockReceiver.code.objectId);
          if (selector === 'valueWithPossibleArgument:' && request.arguments.length === 1) {
            const parameterCount = await blockParameterCount(images, code);
            if (parameterCount !== null) {
              // Pinned Cuis BlockClosure>>valueWithPossibleArgument: anArg —
              //   numArgs = 0 ifTrue: [self value] ifFalse: [self value: anArg]
              const effectiveArguments = parameterCount === 0 ? [] : request.arguments;
              return code?.representation === SMALLTALK_KERNEL_PRIMITIVE_V1
                ? Object.freeze({block: request.receiver, effectiveArguments, inheritsFrame: true})
                : Object.freeze({block: request.receiver, effectiveArguments});
            }
          }
          const expected = blockValueSelector(request.arguments.length);
          if (selector !== expected) throw new TypeError(`Symmetric Smalltalk Block does not understand: ${selector}`);
          // ADR 0050 decision 5a. A kernel-primitive Block is how a method reaches a host operation,
          // so it inherits the invoking method's frame — that is the only way the slot primitives
          // can see whose `self` they are acting on. Every *other* Block send inherits nothing: a
          // method must not lend its identity to a Block it merely happens to invoke.
          return code?.representation === SMALLTALK_KERNEL_PRIMITIVE_V1
            ? Object.freeze({block: request.receiver, inheritsFrame: true})
            : Object.freeze({block: request.receiver});
        }
      }

      // Decision 5a: an immediate Value has no image of its own, so the dispatch image says which
      // kernel's Integer, Text and so on apply.
      const dispatchImage = context?.dispatchImage
        ?? (isObjectRef(request.receiver) ? request.receiver.imageId : null);
      if (!isObjectRef(request.receiver) && dispatchImage === null) {
        throw new TypeError(
          'Symmetric Smalltalk needs a dispatch image to send to an immediate Value; '
          + 'a top-level send must supply one',
        );
      }

      // ADR 0045 decision 2: for a boolean receiver this answers the dispatch image's `true`/`false`
      // singleton, which then behaves exactly like an ordinary object receiver.
      const {behavior, effectiveReceiver, kernel: receiverKernel} = await behaviorRefFor({
        images,
        receiver: request.receiver,
        dispatchImage,
      });
      // What the method actually runs against, and therefore what every failure below should name.
      // Describing the original boolean here would report `undefined/undefined` for a bridged send
      // and, worse, would hide which singleton failed to understand the selector.
      const activeReceiver = effectiveReceiver ?? request.receiver;
      const receiverDescription = isObjectRef(activeReceiver)
        ? `${activeReceiver.imageId}/${activeReceiver.objectId}`
        : `a ${activeReceiver.kind} Value`;
      if (!behavior) {
        throw new TypeError(
          isObjectRef(activeReceiver)
            ? `Symmetric Smalltalk receiver has no behavior: ${receiverDescription}`
            : `Symmetric Smalltalk cannot dispatch a ${activeReceiver.kind} Value`,
        );
      }

      const behaviorRecord = await images.getObject(behavior.imageId, behavior.objectId);
      if (!behaviorRecord) {
        throw new TypeError(`Symmetric Smalltalk behavior not found: ${behavior.imageId}/${behavior.objectId}`);
      }

      // ADR 0044 decision 10. A behavior record means what its own shape says it means, so
      // installing a kernel reinterprets nothing that already exists.
      if (!isBehaviorObject(behaviorRecord)) {
        return resolution(await legacyLookup(images, behaviorRecord, selector), effectiveReceiver);
      }

      const kernel = (receiverKernel && behavior.imageId === dispatchImage)
        ? receiverKernel
        : await findSmalltalkKernel({images, imageId: behavior.imageId});
      if (!kernel) {
        throw new TypeError(
          `image ${behavior.imageId} holds a fixed-shape Behavior but no Smalltalk kernel to terminate lookup`,
        );
      }
      const {method: blockRef, definingBehavior} = await lookupSelector({
        images,
        behaviorRef: behavior,
        behaviorRecord,
        selector,
        nilRef: kernel.nil,
        receiverDescription,
        validationCache,
      });
      // A selector that resolved to a Block ref which does not load is incomplete graph state, not
      // a message the receiver failed to understand.
      const method = await images.getBlock(blockRef.imageId, blockRef.objectId);
      if (!method) throw new SmalltalkDanglingEdgeError('method', behavior, blockRef);
      // ADR 0050 decision 5b: the trusted facts of this dispatch travel in the resolution, and the
      // invocation layer turns them into a transient envelope. They never reach the activation.
      return resolution(blockRef, effectiveReceiver, {definingBehavior, self: activeReceiver});
    },
  });
}

export {blockValueSelector, createSymmetricSmalltalkDispatcher};

import {
  SymmetricSmalltalkSyntaxError,
  tokenizeSymmetricSmalltalk,
  isAssignmentToken,
  isReservedWord,
  isNegativeIntegerLiteralAt,
} from './symmetric-smalltalk-tokenizer.js';

// One rule, one message shape, for every site that would otherwise decide independently.
function assertNotReserved(token, action) {
  if (isReservedWord(token.value)) {
    throw new SymmetricSmalltalkSyntaxError(
      `cannot ${action} ${token.value}: it is a reserved word`, token.start,
    );
  }
}

function node(kind, fields = {}) {
  return Object.freeze({kind, ...fields});
}

class Parser {
  constructor(source, {allowLegacyAssign = false, allowEmpty = false} = {}) {
    this.source = source;
    this.tokens = tokenizeSymmetricSmalltalk(source);
    this.index = 0;
    this.allowLegacyAssign = allowLegacyAssign === true;
    this.allowEmpty = allowEmpty === true;
    // The Cuis legacy assignment arrow is dialect syntax, never native syntax. The tokenizer keeps
    // it a DISTINCT token precisely so that no grammar position can absorb it (before this, `a _ b`
    // parsed as the unary-send chain `((a _) b)` and compiled). The refusal lives here, once, for
    // every position the token could appear in — direct native source has only canonical `:=`.
    // The Cuis import adapter parses dialect source with `allowLegacyAssign: true` so the arrow
    // produces a canonical `assign` AST node at the import boundary; that is the one loud division
    // between the two languages.
    if (!this.allowLegacyAssign) {
      const legacyArrow = this.tokens.find((token) => token.type === 'legacyAssign');
      if (legacyArrow) {
        throw new SymmetricSmalltalkSyntaxError(
          'the legacy assignment arrow `_` is Cuis dialect syntax, not native Symmetric Smalltalk; native assignment is `:=`',
          legacyArrow.start,
        );
      }
    }
  }

  current() {
    return this.tokens[this.index];
  }

  advance() {
    const token = this.current();
    if (token.type !== 'eof') this.index += 1;
    return token;
  }

  match(type) {
    if (this.current().type !== type) return null;
    return this.advance();
  }

  expect(type, message = `expected ${type}`) {
    const token = this.current();
    if (token.type !== type) throw new SymmetricSmalltalkSyntaxError(message, token.start);
    return this.advance();
  }

  peek(offset = 1) {
    return this.tokens[Math.min(this.index + offset, this.tokens.length - 1)];
  }

  parseSource() {
    const body = this.parseBody('eof', {allowEmpty: this.allowEmpty});
    this.expect('eof', 'unexpected trailing input');
    return body;
  }

  // Assignment binds loosest and is right-associative, so `a := b := 1` assigns both and
  // `x := a foo: b` assigns the whole message result.
  parseExpression() {
    const next = this.peek();
    const isAssign = this.allowLegacyAssign ? isAssignmentToken(next) : next.type === 'assign';
    if (this.current().type === 'identifier' && isAssign) {
      const target = this.advance();
      assertNotReserved(target, 'assign to');
      this.advance();
      return node('assign', {name: target.value, value: this.parseExpression()});
    }
    const expression = this.parseKeywordMessage();
    return this.parseCascadesAfter(expression);
  }

  // A cascade binds tighter than assignment: `x := self foo; bar` cascades on the *value*, so the
  // whole thing is the assigned expression, and `x` receives `self foo` — the first message's
  // answer, as Smalltalk defines a cascade's value.
  //
  // The cascaded receiver is the receiver of the first message, not the first message's answer:
  // `OrderedCollection new add: 1; add: 2` sends both `add:` to the *collection*, exactly as `;`
  // means in Smalltalk. So the cascade node keeps the receiver and each message's selector and
  // arguments, and the compiler decides how the receiver is evaluated once.
  parseCascadesAfter(expression) {
    if (expression.kind !== 'send' || this.current().type !== ';') return expression;
    const first = {selector: expression.selector, arguments: expression.arguments};
    const messages = [first];
    while (this.match(';')) {
      if (this.current().type === 'identifier') {
        const token = this.advance();
        assertNotReserved(token, 'send unary message');
        messages.push({selector: token.value, arguments: Object.freeze([])});
        continue;
      }
      if (this.current().type === 'binary') {
        const selector = this.advance().value;
        messages.push({selector, arguments: Object.freeze([this.parseUnaryMessage()])});
        continue;
      }
      if (this.current().type === 'keyword') {
        let selector = '';
        const argumentsList = [];
        while (this.current().type === 'keyword') {
          selector += this.advance().value;
          argumentsList.push(this.parseBinaryMessage());
        }
        messages.push({selector, arguments: Object.freeze(argumentsList)});
        continue;
      }
      throw new SymmetricSmalltalkSyntaxError('expected a message after ;', this.current().start);
    }
    return node('cascade', {receiver: expression.receiver, messages: Object.freeze(messages)});
  }

  // `| a b |` declarations followed by `.`-separated statements. A single statement with no
  // temporaries returns the bare expression, so programs that need none compile to exactly the
  // artifact they compile to today.
  parseBody(terminator, {allowEmpty = false} = {}) {
    const temporaries = this.parseTemporaries();
    const statements = [];
    for (;;) {
      if (this.current().type === terminator) break;
      // ADR 0055. A return is a *statement*, not an expression: `^ a foo` returns the whole send,
      // and `x := ^ 1` is not a thing. Parsing it here rather than in `parseExpression` is what
      // makes that true by construction.
      if (this.current().type === 'caret') {
        const caret = this.advance();
        statements.push(node('return', {value: this.parseExpression(), start: caret.start}));
      } else {
        statements.push(this.parseExpression());
      }
      // Statements after a return still *parse*: they are unreachable, not ill-formed, and the ADR
      // requires proving that they do not run rather than that they cannot be written.
      if (!this.match('.')) break;
    }
    if (statements.length === 0) {
      if (allowEmpty) {
        return node('sequence', {
          temporaries: Object.freeze(temporaries),
          statements: Object.freeze([]),
        });
      }
      throw new SymmetricSmalltalkSyntaxError('expected at least one statement', this.current().start);
    }
    if (temporaries.length === 0 && statements.length === 1) return statements[0];
    return node('sequence', {
      temporaries: Object.freeze(temporaries),
      statements: Object.freeze(statements),
    });
  }

  parseTemporaries() {
    if (this.current().type !== '|') return [];
    this.advance();
    const names = [];
    while (this.current().type === 'identifier') {
      const token = this.advance();
      assertNotReserved(token, 'declare a temporary named');
      if (names.includes(token.value)) {
        throw new SymmetricSmalltalkSyntaxError(`duplicate temporary ${token.value}`, token.start);
      }
      names.push(token.value);
    }
    this.expect('|', 'expected | after temporary declarations');
    return names;
  }

  parseKeywordMessage() {
    let receiver = this.parseBinaryMessage();
    if (this.current().type !== 'keyword') return receiver;

    let selector = '';
    const argumentsList = [];
    while (this.current().type === 'keyword') {
      selector += this.advance().value;
      argumentsList.push(this.parseBinaryMessage());
    }
    receiver = node('send', {receiver, selector, arguments: Object.freeze(argumentsList)});
    return receiver;
  }

  parseBinaryMessage() {
    let receiver = this.parseUnaryMessage();
    while (this.current().type === 'binary') {
      const selector = this.advance().value;
      const argument = this.parseUnaryMessage();
      receiver = node('send', {
        receiver,
        selector,
        arguments: Object.freeze([argument]),
      });
    }
    return receiver;
  }

  parseUnaryMessage() {
    let receiver = this.parsePrimary();
    while (this.current().type === 'identifier') {
      const token = this.advance();
      assertNotReserved(token, 'send unary message');
      receiver = node('send', {
        receiver,
        selector: token.value,
        arguments: Object.freeze([]),
      });
    }
    return receiver;
  }

  parsePrimary() {
    const token = this.current();
    // Operand position only: a leading `-` here is a sign, never the binary
    // selector `parseBinaryMessage` consumes after a receiver. `5-3` and `a-3`
    // are unaffected because their `-` is read in binary-message position.
    if (isNegativeIntegerLiteralAt(this.tokens, this.index)) {
      this.advance(); // consume '-'
      const digits = this.advance(); // consume the integer
      return node('integer', {value: `-${digits.value}`});
    }
    if (token.type === 'integer') {
      this.advance();
      return node('integer', {value: token.value});
    }
    if (token.type === 'string') {
      this.advance();
      return node('string', {value: token.value});
    }
    if (token.type === 'character') {
      this.advance();
      return node('character', {value: token.value});
    }
    if (token.type === 'symbol') {
      this.advance();
      return node('symbol', {value: token.value});
    }
    if (token.type === 'identifier') {
      this.advance();
      // The reserved words read as identifiers and are not names: each becomes its own syntax
      // node, so no later stage can mistake one for something bindable.
      if (token.value === 'self') return node('self');
      // ADR 0089. `super` becomes its own node exactly as `self` does, and deliberately carries no
      // value of its own: the compiler consumes it only as a send's receiver and refuses it
      // anywhere else. Making it a node here is what stops a later stage mistaking it for a name.
      if (token.value === 'super') return node('super');
      if (token.value === 'true') return node('true');
      if (token.value === 'false') return node('false');
      if (token.value === 'nil') return node('nil');
      return node('name', {name: token.value});
    }
    if (this.match('(')) {
      const expression = this.parseExpression();
      this.expect(')', 'expected )');
      return expression;
    }
    // Literal Array `#( ... )` (WS3 empty form; elements demanded by the M4 vertical, bead
    // lagrange-images-x4i). An element position accepts only true literals — integers (with an
    // optional minus sign), Strings, Characters, symbols (hash-marked or, per Smalltalk's literal-array
    // rule, bare identifiers), the boolean/nil reserved words, and nested literal Arrays. Bare
    // identifiers are SYMBOLS here, never variable references, and any other construct (sends,
    // blocks, parentheses) is refused deterministically rather than half-parsed.
    if (this.match('arrayOpen')) {
      const elements = [];
      while (this.current().type !== ')') {
        elements.push(this.parseArrayLiteralElement());
      }
      this.expect(')', 'expected ) to close a literal Array');
      return node('arrayLiteral', {elements: Object.freeze(elements)});
    }
    if (this.match('byteArrayOpen')) {
      return this.parseByteArrayLiteralAfterOpen();
    }
    if (this.match('[')) return this.parseBlockAfterOpen(token.start);
    throw new SymmetricSmalltalkSyntaxError('expected expression', token.start);
  }

  parseByteArrayLiteralAfterOpen() {
    const bytes = [];
    while (this.current().type !== ']') {
      const token = this.current();
      if (token.type === 'eof') {
        throw new SymmetricSmalltalkSyntaxError('expected ] to close a literal ByteArray', token.start);
      }
      if (token.type !== 'integer') {
        throw new SymmetricSmalltalkSyntaxError(
          'byte-array literal elements must be integers in 0..255',
          token.start,
        );
      }
      const parsed = BigInt(token.value);
      if (parsed < 0n || parsed > 255n) {
        throw new SymmetricSmalltalkSyntaxError(
          'byte-array literal elements must be integers in 0..255',
          token.start,
        );
      }
      this.advance();
      bytes.push(Number(parsed));
    }
    this.expect(']', 'expected ] to close a literal ByteArray');
    return node('byteArrayLiteral', {bytes: Object.freeze(bytes)});
  }

  parseArrayLiteralElement() {
    const token = this.current();
    if (isNegativeIntegerLiteralAt(this.tokens, this.index)) {
      this.advance();
      const digits = this.advance();
      return node('integer', {value: `-${digits.value}`});
    }
    if (token.type === 'integer' || token.type === 'string' || token.type === 'character' || token.type === 'symbol') {
      this.advance();
      return node(token.type, {value: token.value});
    }
    if (token.type === 'identifier') {
      this.advance();
      if (token.value === 'true') return node('true');
      if (token.value === 'false') return node('false');
      if (token.value === 'nil') return node('nil');
      // Smalltalk's literal-array rule: a bare identifier element is a Symbol.
      return node('symbol', {value: token.value});
    }
    if (token.type === 'arrayOpen') {
      this.advance();
      const elements = [];
      while (this.current().type !== ')') {
        elements.push(this.parseArrayLiteralElement());
      }
      this.expect(')', 'expected ) to close a nested literal Array');
      return node('arrayLiteral', {elements: Object.freeze(elements)});
    }
    if (token.type === 'byteArrayOpen') {
      this.advance();
      return this.parseByteArrayLiteralAfterOpen();
    }
    throw new SymmetricSmalltalkSyntaxError(
      'literal Array elements must be literals: integers, Strings, Characters, symbols, '
      + 'true/false/nil or a nested literal Array', token.start,
    );
  }

  parseBlockAfterOpen(start) {
    const parameters = [];
    while (this.match(':')) {
      const nameToken = this.expect('identifier', 'expected block parameter name');
      assertNotReserved(nameToken, 'declare a block parameter named');
      if (parameters.includes(nameToken.value)) {
        throw new SymmetricSmalltalkSyntaxError(`duplicate block parameter ${nameToken.value}`, nameToken.start);
      }
      parameters.push(nameToken.value);
    }
    if (parameters.length > 0) this.expect('|', 'expected | after block parameters');
    // WS3 (general language widening): an empty block `[]` is Standard Smalltalk
    // and answers nil when evaluated. Upstream dispatch uses it as the "no value"
    // idiom (`at: key ifAbsent: []`). This is block-level only: a program still
    // requires at least one statement.
    const body = this.current().type === ']' ? node('nil') : this.parseBody(']');
    const close = this.expect(']', 'expected ]');
    return node('block', {
      parameters: Object.freeze(parameters),
      body,
      start,
      end: close.end,
    });
  }
}

function parseSymmetricSmalltalk(source) {
  return new Parser(source).parseSource();
}

function parseSymmetricSmalltalkDialect(source, {allowEmpty = true} = {}) {
  return new Parser(source, {allowLegacyAssign: true, allowEmpty}).parseSource();
}

function parseSymmetricSmalltalkBlock(source) {
  const syntax = parseSymmetricSmalltalk(source);
  if (syntax.kind !== 'block') {
    throw new SymmetricSmalltalkSyntaxError('expected a block as the compilation unit', 0);
  }
  return syntax;
}

function formatArrayLiteralElement(element) {
  switch (element.kind) {
    case 'integer':
      return element.value;
    case 'string':
      return `'${element.value.replaceAll("'", "''")}'`;
    case 'character':
      return `$${element.value}`;
    case 'symbol':
      return `#${element.value}`;
    case 'true':
    case 'false':
    case 'nil':
      return element.kind;
    case 'arrayLiteral':
      return `#(${element.elements.map(formatArrayLiteralElement).join(' ')})`;
    case 'byteArrayLiteral':
      return `#[${element.bytes.join(' ')}]`;
    default:
      throw new TypeError(`unexpected array literal element kind: ${element.kind}`);
  }
}

function parenthesizeIf(condition, text) {
  return condition ? `(${text})` : text;
}

function formatMessageSendChain(selector, args) {
  if (args.length === 0) return selector;
  if (!selector.endsWith(':')) {
    const arg = args[0];
    const needsParens = arg.kind === 'assign'
      || arg.kind === 'cascade'
      || (arg.kind === 'send' && arg.arguments.length > 0);
    return `${selector} ${parenthesizeIf(needsParens, formatAstExpression(arg))}`;
  }
  const parts = selector.match(/[^:]+:/g);
  return parts.map((part, index) => {
    const arg = args[index];
    const needsParens = arg.kind === 'assign'
      || arg.kind === 'cascade'
      || (arg.kind === 'send' && arg.selector.endsWith(':'));
    return `${part} ${parenthesizeIf(needsParens, formatAstExpression(arg))}`;
  }).join(' ');
}

function formatSendExpression(receiver, selector, args) {
  const receiverNeedsParens = args.length === 0
    ? (receiver.kind === 'assign' || receiver.kind === 'cascade' || (receiver.kind === 'send' && receiver.arguments.length > 0))
    : (receiver.kind === 'assign' || receiver.kind === 'cascade' || (receiver.kind === 'send' && receiver.selector.endsWith(':')));
  const recvText = parenthesizeIf(receiverNeedsParens, formatAstExpression(receiver));
  return `${recvText} ${formatMessageSendChain(selector, args)}`;
}

function formatInlineBody(bodyAst) {
  const temporaries = bodyAst.kind === 'sequence' ? bodyAst.temporaries : [];
  const statements = bodyAst.kind === 'sequence' ? bodyAst.statements : [bodyAst];
  const parts = [];
  if (temporaries.length > 0) parts.push(`| ${temporaries.join(' ')} |`);
  if (statements.length > 0) {
    parts.push(statements.map(formatAstStatement).join('. '));
  }
  return parts.join(' ');
}

function formatAstExpression(node) {
  switch (node.kind) {
    case 'integer':
      return node.value;
    case 'string':
      return `'${node.value.replaceAll("'", "''")}'`;
    case 'character':
      return `$${node.value}`;
    case 'symbol':
      return `#${node.value}`;
    case 'self':
    case 'super':
    case 'true':
    case 'false':
    case 'nil':
      return node.kind;
    case 'name':
      return node.name;
    case 'arrayLiteral':
      return `#(${node.elements.map(formatArrayLiteralElement).join(' ')})`;
    case 'byteArrayLiteral':
      return `#[${node.bytes.join(' ')}]`;
    case 'block': {
      if (node.parameters.length === 0 && node.body.kind === 'nil') return '[]';
      const params = node.parameters.length === 0
        ? ''
        : ` ${node.parameters.map((param) => `:${param}`).join(' ')} |`;
      return `[${params} ${formatInlineBody(node.body)} ]`;
    }
    case 'assign':
      return `${node.name} := ${formatAstExpression(node.value)}`;
    case 'send':
      return formatSendExpression(node.receiver, node.selector, node.arguments);
    case 'cascade': {
      const first = formatSendExpression(
        node.receiver,
        node.messages[0].selector,
        node.messages[0].arguments,
      );
      const rest = node.messages
        .slice(1)
        .map(({selector, arguments: args}) => formatMessageSendChain(selector, args));
      return `${first}; ${rest.join('; ')}`;
    }
    default:
      throw new TypeError(`unexpected AST expression kind: ${node.kind}`);
  }
}

function formatAstStatement(statement) {
  if (statement.kind === 'return') {
    return `^ ${formatAstExpression(statement.value)}`;
  }
  return formatAstExpression(statement);
}

function formatSymmetricSmalltalkMethodBlock(parameters, bodyAst) {
  const parameterSource = parameters.length === 0
    ? ''
    : ` ${parameters.map((name) => `:${name}`).join(' ')} |`;
  const temporaries = bodyAst.kind === 'sequence' ? bodyAst.temporaries : [];
  const statements = bodyAst.kind === 'sequence' ? bodyAst.statements : [bodyAst];
  const lines = [];
  if (temporaries.length > 0) {
    lines.push(`| ${temporaries.join(' ')} |`);
  }
  for (const statement of statements) {
    lines.push(`${formatAstStatement(statement)}.`);
  }
  lines.push('self');
  return `[${parameterSource}\n${lines.join('\n')}\n]`;
}

export {
  formatSymmetricSmalltalkMethodBlock,
  parseSymmetricSmalltalk,
  parseSymmetricSmalltalkBlock,
  parseSymmetricSmalltalkDialect,
};

import {booleanValue, bytesValue, integerValue, textValue} from '../value/index.js';
import {LAGRANGE_CODE_V0} from '../code/lagrange-code-v0.js';
import {LAGRANGE_CODE_V1} from '../code/lagrange-code-v1.js';
import {parseSymmetricSmalltalkBlock} from './symmetric-smalltalk-parser.js';
import {isReservedWord} from './symmetric-smalltalk-tokenizer.js';
import {SYMMETRIC_SMALLTALK_ID} from './symmetric-smalltalk.js';

function normalizeRootCaptures(captures) {
  if (!captures || typeof captures !== 'object' || Array.isArray(captures)) {
    throw new TypeError('captures must be an object mapping source name to stable binding id');
  }
  const result = new Map();
  const ids = new Set();
  for (const [name, id] of Object.entries(captures)) {
    if (!name) throw new TypeError('capture name must not be empty');
    // The fourth site of ADR 0056 decision 3, and the one the parser cannot reach: captures are
    // supplied programmatically rather than written in source.
    if (isReservedWord(name)) throw new TypeError(`capture name ${name} is a reserved word`);
    // The compiler's own intrinsic, reserved in both directions. Reserving only the name would let
    // a caller bind the *id* under another name and shadow `nil`'s meaning from outside the
    // compiler — the same reason `$nonLocalReturn` and the slot primitives reserve both.
    if (name === NIL_CAPTURE) throw new TypeError(`capture name ${NIL_CAPTURE} is reserved for the nil intrinsic`);
    if (name === SYMBOL_CAPTURE) throw new TypeError(`capture name ${SYMBOL_CAPTURE} is reserved for the symbol intrinsic`);
    if (name === CHARACTER_CAPTURE) throw new TypeError(`capture name ${CHARACTER_CAPTURE} is reserved for the character intrinsic`);
    // The compiler owns this whole key namespace. Reserving only the ids it happens to use would
    // let a caller supply an internal-looking name and slip past the global collision check, which
    // distinguishes its own captures by exactly this prefix.
    if (name.startsWith(GLOBAL_CAPTURE_PREFIX)) {
      throw new TypeError(`capture name ${name} is reserved: ${GLOBAL_CAPTURE_PREFIX} belongs to the compiler`);
    }
    if (typeof id !== 'string' || id.length === 0) throw new TypeError(`capture binding id for ${name} must be non-empty text`);
    if (id === NIL_BINDING_ID) throw new TypeError(`capture binding id ${NIL_BINDING_ID} is reserved for the nil intrinsic`);
    if (id === SYMBOL_BINDING_ID) throw new TypeError(`capture binding id ${SYMBOL_BINDING_ID} is reserved for the symbol intrinsic`);
    if (id === CHARACTER_BINDING_ID) throw new TypeError(`capture binding id ${CHARACTER_BINDING_ID} is reserved for the character intrinsic`);
    if (ids.has(id)) throw new TypeError(`duplicate capture binding id: ${id}`);
    ids.add(id);
    result.set(name, id);
  }
  return result;
}

// Which semantic representation this compilation unit needs, decided from what the program actually
// does rather than from what the parser happened to emit. A source that needs none of ADR 0043's
// semantics must still compile to exactly its lagrange-code/v0 artifact, so this asks about
// meaning: more than one statement, a declared temporary, or an assignment.
//
// A cell-mode capture is not tested for separately: capturing a mutable cell requires a temporary
// to have been declared, so temporaries already subsume it.
function needsMutableLexicalState(syntax) {
  if (!syntax || typeof syntax !== 'object') return false;
  switch (syntax.kind) {
    case 'assign':
      return true;
    case 'sequence':
      if (syntax.temporaries.length > 0 || syntax.statements.length > 1) return true;
      return syntax.statements.some((statement) => needsMutableLexicalState(statement));
    case 'block':
      return needsMutableLexicalState(syntax.body);
    // ADR 0055. A return wraps an ordinary expression, so v1 features hidden under one — an
    // assignment, a multi-statement Block — must still be seen. Omitting this case classifies
    // `^ [ | t | t := 1. t ]` as v0 and the artifact is then rejected against the closed v0 grammar.
    case 'return':
      return needsMutableLexicalState(syntax.value);
    // A cascade always lowers to hidden temporaries plus a statement sequence: the receiver must be
    // evaluated once even when it is already a plain name, because the alternative — replaying the
    // receiver expression per message — evaluates a send several times. So a cascade needs v1
    // regardless of what it is made of.
    case 'cascade':
      return true;
    case 'send':
      return needsMutableLexicalState(syntax.receiver)
        || syntax.arguments.some((argument) => needsMutableLexicalState(argument));
    // Symbol and Character literals need no mutable state. Their image-local identities are
    // supplied through intrinsics later, just as nil's is; that does not make the source stateful.
    case 'symbol':
    case 'character':
    case 'byteArrayLiteral':
      return false;
    // A non-empty literal Array lowers to the cascade machinery's hidden temporaries, so it needs
    // the mutable-lexical-state (v1) grammar for exactly the same reason a cascade does. The empty
    // form remains a single send in v0.
    case 'arrayLiteral':
      return syntax.elements.length > 0;
    default:
      return false;
  }
}

// One decision for the whole tree. A nested program is embedded verbatim in its parent's `block`
// op and is also installed as its own artifact, and both readers validate against a closed grammar
// — so a v1 program cannot carry a v0-shaped child, nor the reverse.
function selectSemanticRepresentation(syntax) {
  return needsMutableLexicalState(syntax) ? LAGRANGE_CODE_V1 : LAGRANGE_CODE_V0;
}

// ADR 0050. An instance variable is not a new kind of expression: it lowers to an ordinary send of a
// language-owned primitive, reached through ordinary captures, so nothing downstream of the compiler
// learns a new concept. These names are internal to the binder and cannot collide with source names,
// which the tokenizer restricts to identifier characters.
const INSTANCE_SLOT_READ_CAPTURE = '$instanceSlotRead';
// ADR 0055: reserved for the compiler's `^` lowering, like the slot-primitive captures above.
const NON_LOCAL_RETURN_CAPTURE = '$nonLocalReturn';
// ADR 0056 decision 2. `nil` is a language-owned image object, so it cannot be a literal Value —
// the generic model has no nil kind and does not get one. It lowers to a reserved binding whose id
// is stable across images; installation supplies that image's kernel nil.
const NIL_CAPTURE = '$nil';
const NIL_BINDING_ID = 'smalltalk/intrinsic/nil';
// Symbol literals lower to a send of the spelling to the image-local interner, exactly as
// `nil` lowers to a read of the nil intrinsic. The compiled artifact carries only the canonical
// spelling as a Text literal — never an image-specific Symbol ref.
const SYMBOL_CAPTURE = '$symbol';
const SYMBOL_BINDING_ID = 'smalltalk/intrinsic/symbol';
// A Character is distinct from Text and Integer in the measured language: `$< = '<'` and
// `$< = 60` are both false, while String indexing and streaming answer the same Character identity
// as the literal. Lower through the image-local Character interner so the common IR and generic
// Value model learn neither a new operation nor a new Value kind. The semantic artifact carries
// only the Unicode code point as an Integer literal.
const CHARACTER_CAPTURE = '$character';
const CHARACTER_BINDING_ID = 'smalltalk/intrinsic/character';
// The empty literal Array `#()` (WS3) lowers to `new: 0` sent to the image-local Array class,
// reached through this intrinsic — exactly as Symbol lowers to a send to the interner and `nil`
// to a read of the nil intrinsic. The compiler names no class and bakes no image-local ref: the
// binding carries the id only, and installation supplies that image's Array class.
const ARRAY_CAPTURE = '$array';
const ARRAY_BINDING_ID = 'smalltalk/intrinsic/array';
// Internal capture key for a resolved global. Prefixed so it cannot collide with any source name —
// the tokenizer restricts those to identifier characters.
const GLOBAL_CAPTURE_PREFIX = '$global:';
// Internal capture key for a resolved class variable. Same prefixing rationale as globals.
const CLASS_VAR_CAPTURE_PREFIX = '$classVar:';
const INSTANCE_SLOT_WRITE_CAPTURE = '$instanceSlotWrite';
// ADR 0089. `super` is a receiver MARKER, not a value, so it lowers exactly the way `^` does: to an
// ordinary send of a language-owned primitive reached through a reserved capture the class-scoped
// binder makes available. `lagrange-code` therefore learns nothing about Smalltalk inheritance, and
// the compiled artifact names no class — WHICH Behavior lookup must start above is the running
// method's defining Behavior, a trusted runtime fact of the invocation frame that neither source
// nor a compiled artifact may state.
const SUPER_SEND_CAPTURE = '$superSend';

class SemanticScope {
  constructor({
    parent = null, path, parameters = [], rootCaptures = new Map(), instanceVariables = new Map(),
    methodHome = false, intrinsics = new Map(), globals = new Map(), classVariables = new Map(),
  } = {}) {
    // ADR 0057. Name -> binding id, resolved from the image's namespace by the *caller* and handed
    // in. This compiler stays synchronous and image-independent: it never reads storage, and what it
    // emits is binding identity rather than any image-specific ref.
    this.globals = parent ? parent.globals : globals;
    // Class variables: name -> binding id, resolved from the class hierarchy by the *caller*.
    // Same compiler-purity rule as globals: the compiler sees only the flat map.
    this.classVariables = parent ? parent.classVariables : classVariables;
    // Which class-variable bindings this compilation actually resolved. Transient provenance,
    // exactly like globalsUsed.
    this.classVarsUsed = parent ? parent.classVarsUsed : new Set();
    // ADR 0057. Which global bindings this compilation actually resolved. Transient compiler
    // metadata — never part of `lagrange-code` — and the only correct answer to "is this capture a
    // global?", because a capture id does not say *why* the capture exists.
    this.globalsUsed = parent ? parent.globalsUsed : new Set();
    // ADR 0055. Reserved bindings the binder makes *available* without declaring. A declaration
    // becomes a program capture whether or not the source references it, so declaring the return
    // intrinsic eagerly would give every method a dependency it may never use. Requested on first
    // lowering instead, which needs no second inspection of the source.
    this.intrinsics = parent ? parent.intrinsics : intrinsics;
    // ADR 0055. Whether this compilation has a method to return from. Carried explicitly rather
    // than inferred from the presence of instance variables — a method with no instance variables
    // still has a home, and a standalone Block with captures still has none.
    this.methodHome = methodHome || parent?.methodHome === true;
    this.parent = parent;
    this.instanceVariables = parent ? parent.instanceVariables : instanceVariables;
    this.path = path;
    this.parameters = new Map();
    parameters.forEach((name, index) => {
      this.parameters.set(name, Object.freeze({
        id: `${path}:parameter:${index}`,
        name,
        index,
      }));
    });
    this.temporaries = new Map();
    this.captures = new Map();
    if (!parent) {
      for (const [name, id] of rootCaptures) {
        this.captures.set(name, Object.freeze({id, name, source: null, mutable: false}));
      }
    }
  }

  // Declared before the statements are compiled, so `| total | total := 0` resolves.
  declareTemporaries(names) {
    names.forEach((name, index) => {
      if (this.parameters.has(name)) {
        throw new TypeError(`temporary ${name} shadows a parameter of the same activation`);
      }
      this.temporaries.set(name, Object.freeze({
        id: `${this.path}:temporary:${index}`,
        name,
      }));
    });
  }

  // Compiler-introduced bindings the source cannot name or collide with — `$` is not an identifier
  // character, so nothing reachable through `resolveName` ever reads one. A cascade uses these for
  // the shared receiver and the first message's answer.
  declareHiddenTemporary(key) {
    if (this.temporaries.has(key)) throw new TypeError(`duplicate hidden temporary ${key}`);
    const id = `${this.path}:${key}`;
    this.temporaries.set(key, Object.freeze({id, name: key}));
    return id;
  }

  addCapture(key, provided) {
    if (!this.captures.has(key)) {
      this.captures.set(key, Object.freeze({
        id: provided.id,
        name: provided.name,
        source: provided.value,
        mutable: provided.mutable === true,
      }));
    }
    return this.captures.get(key);
  }

  // ADR 0050 decision 3: lexical bindings first, and the instance variable only where resolution
  // would otherwise raise `unbound Symmetric Smalltalk name` — never earlier. A parameter named `x`
  // therefore shadows an instance variable named `x`.
  instanceSlot(name) {
    return this.instanceVariables.get(name) ?? null;
  }

  // Built in the *originating* scope, so `self` and the primitive capture resolve through this
  // scope's own chain. That is what makes an instance variable inside a nested Block mean the
  // defining method's receiver (ADR 0050 decision 10).
  canReturn() {
    return this.methodHome === true;
  }

  instanceSlotRead(slotId) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(INSTANCE_SLOT_READ_CAPTURE),
      message: textValue('value:value:'),
      arguments: Object.freeze([this.resolveSelf(), Object.freeze({op: 'literal', value: textValue(slotId)})]),
    });
  }

  // ADR 0055. `^ expr` lowers to `$nonLocalReturn value: expr` — an ordinary send, so
  // `lagrange-code` gains no operation for it. `resolveName` walks the capture chain exactly as it
  // does for the slot primitives, so a nested Block inherits the binding by ordinary propagation.
  rootScope() {
    let scope = this;
    while (scope.parent) scope = scope.parent;
    return scope;
  }

  // Seeds the reserved binding at the root the first time a `^` is lowered, then resolves it by the
  // ordinary capture walk — so a nested Block inherits it exactly as it inherits anything else.
  requireIntrinsic(name) {
    const root = this.rootScope();
    const id = root.intrinsics.get(name);
    if (!id) throw new TypeError(`no ${name} intrinsic is available in this compilation`);
    if (!root.captures.has(name)) {
      root.captures.set(name, Object.freeze({id, name, source: null, mutable: false}));
    }
    return this.resolveName(name);
  }

  nonLocalReturn(valueExpression) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.requireIntrinsic(NON_LOCAL_RETURN_CAPTURE),
      message: textValue('value:'),
      arguments: Object.freeze([valueExpression]),
    });
  }

  // ADR 0089. `super foo: a bar: b` lowers to `$superSend value: 'foo:bar:' value: a value: b`.
  //
  // The selector travels as an ordinary Text literal and the arguments as ordinary expressions; the
  // RECEIVER of the resulting message is not mentioned at all, because a super send does not change
  // it — the primitive sends to the invoking method's own `self`. `requireIntrinsic` walks the
  // capture chain exactly as `^` does, so a nested Block inherits the binding by ordinary
  // propagation rather than by a second mechanism.
  superSend(selector, argumentExpressions) {
    const values = [
      Object.freeze({op: 'literal', value: textValue(selector)}),
      ...argumentExpressions,
    ];
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.requireIntrinsic(SUPER_SEND_CAPTURE),
      // The Block-application selector for this argument count, spelled here exactly as the slot
      // primitives spell theirs: one `value:` for the selector plus one per message argument.
      message: textValue('value:'.repeat(values.length)),
      arguments: Object.freeze(values),
    });
  }

  instanceSlotWrite(slotId, valueExpression) {
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(INSTANCE_SLOT_WRITE_CAPTURE),
      message: textValue('value:value:value:'),
      arguments: Object.freeze([
        this.resolveSelf(),
        Object.freeze({op: 'literal', value: textValue(slotId)}),
        valueExpression,
      ]),
    });
  }

  resolveName(name) {
    const parameter = this.parameters.get(name);
    if (parameter) return Object.freeze({op: 'argument', index: parameter.index});
    const temporary = this.temporaries.get(name);
    if (temporary) return Object.freeze({op: 'binding', id: temporary.id});
    const capture = this.captures.get(name);
    if (capture) return Object.freeze({op: 'binding', id: capture.id});
    const provided = this.parent ? this.parent.provideName(name) : null;
    if (provided) return Object.freeze({op: 'binding', id: this.addCapture(name, provided).id});
    const slotId = this.instanceSlot(name);
    if (slotId) return this.instanceSlotRead(slotId);
    // Class variables resolve after instance variables and before globals. A subclass method
    // can read an ancestor's class var; an unrelated class cannot resolve it by name.
    const classVar = this.resolveClassVariable(name);
    if (classVar) return classVar;
    // Globals resolve LAST, so no future publication can change what a name already means inside a
    // method that binds it lexically or as an instance variable.
    const global = this.resolveGlobal(name);
    if (global) return global;
    throw new TypeError(`unbound Symmetric Smalltalk name: ${name}`);
  }

  // A global read is a `value` send to the binding — an ordinary send, so `lagrange-code` gains
  // nothing. The capture is requested on first use, so a method mentioning no global carries none,
  // and a nested Block that is the only user still acquires it through the ordinary capture walk.
  resolveGlobal(name) {
    const bindingId = this.globals.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    // An explicit caller capture must not silently share a durable binding id with a resolved
    // global: two different meanings collapsing onto one environment key is exactly the sort of
    // aliasing that answers the wrong object.
    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(GLOBAL_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the global binding id ${bindingId}`);
      }
    }

    // Keyed by the *binding*, not by the source name. Keying by name would make the capture shadow
    // the global on every later read — `resolveName` finds a capture before it reaches global
    // resolution, so the second `Array` in a method would answer the binding object rather than the
    // class. It also makes an alias free: two names resolving to one binding share one capture,
    // which the closed capture grammar requires.
    const key = `${GLOBAL_CAPTURE_PREFIX}${bindingId}`;
    this.globalsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value'),
      arguments: Object.freeze([]),
    });
  }

  // A class-variable read is a `value` send to the binding — an ordinary send, exactly like a
  // global read. The capture is keyed by the binding identity, not the source name.
  resolveClassVariable(name) {
    const bindingId = this.classVariables.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    // Same collision check as globals: an explicit caller capture must not silently share a
    // durable binding id with a resolved class variable.
    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(CLASS_VAR_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the class-variable binding id ${bindingId}`);
      }
    }

    const key = `${CLASS_VAR_CAPTURE_PREFIX}${bindingId}`;
    this.classVarsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value'),
      arguments: Object.freeze([]),
    });
  }

  // A class-variable write is a `value:` send to the binding — an ordinary send. Unlike globals,
  // class variables are mutable shared state, so assignment lowers to `value: newValue`.
  resolveClassVariableWrite(name, valueExpression) {
    const bindingId = this.classVariables.get(name);
    if (!bindingId) return null;
    const root = this.rootScope();

    for (const [key, capture] of root.captures) {
      if (capture.id === bindingId && !key.startsWith(CLASS_VAR_CAPTURE_PREFIX)) {
        throw new TypeError(`capture ${key} collides with the class-variable binding id ${bindingId}`);
      }
    }

    const key = `${CLASS_VAR_CAPTURE_PREFIX}${bindingId}`;
    this.classVarsUsed.add(bindingId);
    if (!root.captures.has(key)) {
      root.captures.set(key, Object.freeze({id: bindingId, name, source: null, mutable: false}));
    }
    return Object.freeze({
      op: 'send',
      languageId: SYMMETRIC_SMALLTALK_ID,
      receiver: this.resolveName(key),
      message: textValue('value:'),
      arguments: Object.freeze([valueExpression]),
    });
  }

  // Assignment needs a cell, so only a temporary — or a capture that resolves to one — qualifies.
  // Parameters and the receiver are not assignable, and a root capture names a durable environment
  // binding rather than a cell, which ADR 0043 decision 2 keeps out of assignment's reach.
  // Resolution finds the binding *first* and checks write legality *second*; it never keeps
  // searching for something assignable. So a parameter named `x` shadows an instance variable named
  // `x` for writes too, and `x := 5` stays illegal rather than becoming a slot write.
  resolveWrite(name) {
    if (this.parameters.has(name)) throw new TypeError(`cannot assign to parameter ${name}`);
    const temporary = this.temporaries.get(name);
    if (temporary) return {kind: 'binding', id: temporary.id};
    const existing = this.captures.get(name);
    if (existing) {
      if (!existing.mutable) throw new TypeError(`cannot assign to captured binding ${name}`);
      return {kind: 'binding', id: existing.id};
    }
    const provided = this.parent ? this.parent.provideName(name) : null;
    if (provided) {
      if (provided.mutable !== true) throw new TypeError(`cannot assign to captured binding ${name}`);
      return {kind: 'binding', id: this.addCapture(name, provided).id};
    }
    const slotId = this.instanceSlot(name);
    if (slotId) return {kind: 'instance', slotId};
    // Class variables are writable: assignment lowers to a `value:` send on the binding.
    if (this.classVariables.has(name)) {
      return {kind: 'classVariable', name};
    }
    // ADR 0057: assignment never reaches a global, and the check sits *last* so it matches the read
    // order — a temporary or instance variable of the same name shadows a global for writes exactly
    // as it does for reads. A known global then gets a diagnosis saying what is actually wrong,
    // rather than being reported as an unbound name; nothing is lowered and no setter exists.
    if (this.globals.has(name)) {
      throw new TypeError(`global assignment is not supported: ${name}`);
    }
    throw new TypeError(`unbound Symmetric Smalltalk name: ${name}`);
  }

  resolveSelf() {
    if (!this.parent) return Object.freeze({op: 'receiver'});
    const provided = this.parent.provideSelf();
    const capture = this.addCapture('$self', provided);
    return Object.freeze({op: 'binding', id: capture.id});
  }

  provideName(name) {
    const parameter = this.parameters.get(name);
    if (parameter) {
      return Object.freeze({
        id: parameter.id,
        name: parameter.name,
        mutable: false,
        value: Object.freeze({op: 'argument', index: parameter.index}),
      });
    }
    // A temporary is the one thing a nested Block must reach by cell rather than by snapshot.
    const temporary = this.temporaries.get(name);
    if (temporary) {
      return Object.freeze({
        id: temporary.id,
        name: temporary.name,
        mutable: true,
        value: Object.freeze({op: 'binding', id: temporary.id}),
      });
    }
    const capture = this.captures.get(name);
    if (capture) {
      return Object.freeze({
        id: capture.id,
        name: capture.name,
        mutable: capture.mutable,
        value: Object.freeze({op: 'binding', id: capture.id}),
      });
    }
    if (!this.parent) return null;
    // Ask upward directly rather than going through `resolveName`. Since ADR 0050 `resolveName` may
    // answer an *instance variable* — an expression, not a capture — and then there is nothing here
    // for a descendant to capture. Answering null in that case is right: the originating scope
    // resolves the instance variable itself, which is what makes the read reach the defining
    // method's receiver from any depth.
    const provided = this.parent.provideName(name);
    if (!provided) return null;
    const inherited = this.addCapture(name, provided);
    return Object.freeze({
      id: inherited.id,
      name: inherited.name,
      mutable: inherited.mutable,
      value: Object.freeze({op: 'binding', id: inherited.id}),
    });
  }

  provideSelf() {
    if (!this.parent) {
      return Object.freeze({
        id: `${this.path}:self`,
        name: 'self',
        mutable: false,
        value: Object.freeze({op: 'receiver'}),
      });
    }
    this.resolveSelf();
    const capture = this.captures.get('$self');
    return Object.freeze({
      id: capture.id,
      name: capture.name,
      mutable: capture.mutable,
      value: Object.freeze({op: 'binding', id: capture.id}),
    });
  }

  parameterDescriptors() {
    return Object.freeze([...this.parameters.values()].map(({id, name}) => Object.freeze({id, name})));
  }

  temporaryDescriptors() {
    return Object.freeze([...this.temporaries.values()].map(({id, name}) => Object.freeze({id, name})));
  }

  captureDescriptors(representation) {
    return Object.freeze([...this.captures.values()].map(({id, name, mutable}) => (
      representation === LAGRANGE_CODE_V1
        ? Object.freeze({id, mode: mutable ? 'cell' : 'snapshot', name})
        : Object.freeze({id, name})
    )));
  }

  // What the enclosing activation must supply when it creates the Block. A cell-mode capture
  // deliberately carries no value expression: there is nothing to evaluate, which is what stops a
  // snapshot reappearing under a different name.
  captureInitializers(representation) {
    const entries = [...this.captures.values()].filter(({source}) => source !== null);
    return Object.freeze(entries.map(({id, name, source, mutable}) => {
      if (representation !== LAGRANGE_CODE_V1) return Object.freeze({id, name, value: source});
      return mutable
        ? Object.freeze({id, mode: 'cell', name})
        : Object.freeze({id, mode: 'snapshot', name, value: source});
    }));
  }
}

// `receiverExpression` is already lowered: cascades compile their receiver once into a hidden
// temporary and hand every message the same binding read.
function compileSend(receiverExpression, selector, args, scope, state) {
  return Object.freeze({
    op: 'send',
    languageId: SYMMETRIC_SMALLTALK_ID,
    receiver: receiverExpression,
    message: textValue(selector),
    arguments: Object.freeze(args.map((entry) => compileExpression(entry, scope, state))),
  });
}

function compileExpression(syntax, scope, state) {
  switch (syntax.kind) {
    case 'integer':
      return Object.freeze({op: 'literal', value: integerValue(syntax.value)});
    case 'string':
      return Object.freeze({op: 'literal', value: textValue(syntax.value)});
    case 'byteArrayLiteral':
      return Object.freeze({
        op: 'literal',
        value: bytesValue(Uint8Array.from(syntax.bytes)),
      });
    case 'character':
      return Object.freeze({
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: scope.requireIntrinsic(CHARACTER_CAPTURE),
        message: textValue('value:'),
        arguments: Object.freeze([
          Object.freeze({op: 'literal', value: integerValue(syntax.value.codePointAt(0))}),
        ]),
      });
    case 'self':
      return scope.resolveSelf();
    // ADR 0056 decision 1: the canonical boolean Values themselves, not the kernel singletons. The
    // singleton is only ever a *dispatch* personality (ADR 0045), so compiling the literal to a ref
    // would undo that separation at the source level.
    case 'true':
      return Object.freeze({op: 'literal', value: booleanValue(true)});
    case 'false':
      return Object.freeze({op: 'literal', value: booleanValue(false)});
    // Requested lazily, so a program that never writes `nil` carries no binding for it and its
    // installer writes no environment (ADR 0055's rule, applied again).
    case 'nil':
      return scope.requireIntrinsic(NIL_CAPTURE);
    // A symbol literal lowers to an ordinary send of the canonical spelling to the interner
    // primitive, reached through the intrinsic capture walk. The artifact carries only the
    // spelling as a Text literal — no image-specific Symbol ref, no new lagrange-code op.
    case 'symbol':
      return Object.freeze({
        op: 'send',
        languageId: SYMMETRIC_SMALLTALK_ID,
        receiver: scope.requireIntrinsic(SYMBOL_CAPTURE),
        message: textValue('value:'),
        arguments: Object.freeze([Object.freeze({op: 'literal', value: textValue(syntax.value)})]),
      });
    // Literal Array `#( )` (WS3 empty form) and its literal-element extension (bead
    // lagrange-images-x4i, forced by the unchanged `XMLTokenizer class>>initialize`). An
    // N-element literal lowers to the SAME machinery the cascade lowering already owns: the
    // Array-class construction is evaluated ONCE into a hidden temporary, then N ordinary ordered
    // `at:put:` sends fill it. No new lagrange-code op, no generic Value array-literal kind, and
    // nothing image-local baked into the artifact — the `$array`/`$character`/symbol intrinsics
    // carry ids only, and installation supplies this image's owners. Element positions accepted
    // only true literals (parser-enforced), so no evaluation order or side effects hide here.
    case 'arrayLiteral': {
      if (syntax.elements.length === 0) {
        return Object.freeze({
          op: 'send',
          languageId: SYMMETRIC_SMALLTALK_ID,
          receiver: scope.requireIntrinsic(ARRAY_CAPTURE),
          message: textValue('new:'),
          arguments: Object.freeze([Object.freeze({op: 'literal', value: integerValue(0)})]),
        });
      }
      const arrayId = scope.declareHiddenTemporary(`$arrayLiteral:${state.nextArrayLiteral++}`);
      const statements = [
        Object.freeze({
          op: 'binding-write',
          id: arrayId,
          value: Object.freeze({
            op: 'send',
            languageId: SYMMETRIC_SMALLTALK_ID,
            receiver: scope.requireIntrinsic(ARRAY_CAPTURE),
            message: textValue('new:'),
            arguments: Object.freeze([Object.freeze({op: 'literal', value: integerValue(syntax.elements.length)})]),
          }),
        }),
        ...syntax.elements.map((element, index) => compileSend(
          Object.freeze({op: 'binding', id: arrayId}),
          'at:put:',
          [Object.freeze({kind: 'integer', value: String(index + 1)}), element],
          scope,
          state,
        )),
        Object.freeze({op: 'binding', id: arrayId}),
      ];
      return Object.freeze({op: 'sequence', statements: Object.freeze(statements)});
    }
    case 'name':
      return scope.resolveName(syntax.name);
    // ADR 0089. `super` is not a value. It exists only as the receiver marker of a message send, and
    // `case 'send'` consumes it there; reaching this point means the source used it as an ordinary
    // expression — a bare `super`, an argument, the right-hand side of an assignment. There is no
    // object to answer, and inventing a proxy would make `super` a second RECEIVER, which is
    // precisely what it is not.
    case 'super':
      throw new TypeError('super is not a value: it may only be the receiver of a message send');
    case 'return': {
      // A Block compiled with no method context has no home to return from, and never could have —
      // that is a fact about the compilation, so it is reported here rather than at invocation. It
      // is deliberately distinct from an escaped method Block, which compiled legitimately and
      // fails later because its home died.
      if (!scope.canReturn()) {
        throw new TypeError('non-local return requires a method home: `^` is only valid inside a method');
      }
      return scope.nonLocalReturn(compileExpression(syntax.value, scope, state));
    }
    case 'assign': {
      const target = scope.resolveWrite(syntax.name);
      const value = compileExpression(syntax.value, scope, state);
      if (target.kind === 'instance') return scope.instanceSlotWrite(target.slotId, value);
      if (target.kind === 'classVariable') return scope.resolveClassVariableWrite(target.name, value);
      return Object.freeze({op: 'binding-write', id: target.id, value});
    }
    case 'send':
      // ADR 0089, and the only place the super receiver marker is consumed. Unary, binary and
      // keyword sends all arrive here, so all three forms fall out of one lowering. `self` is
      // unchanged — the primitive sends to the running method's own `self` — so the ONLY difference
      // from the ordinary case below is where selector lookup starts.
      if (syntax.receiver.kind === 'super') {
        // The same rule, and the same reason, as `^`: a compilation with no method home has no
        // defining Behavior to start above, and never could have. Reported here rather than at
        // invocation, because it is a fact about the compilation.
        if (!scope.canReturn()) {
          throw new TypeError('super requires a method home: `super` is only valid inside a method');
        }
        return scope.superSend(
          syntax.selector,
          syntax.arguments.map((argument) => compileExpression(argument, scope, state)),
        );
      }
      return compileSend(
        compileExpression(syntax.receiver, scope, state), syntax.selector, syntax.arguments, scope, state,
      );
    // `receiver m1; m2; m3` lowers to ordinary v1 state and sends — the IR gains no cascade op:
    //
    //   $recv := <receiver>.
    //   $first := $recv m1.
    //   $recv m2.
    //   $recv m3.
    //   $first
    //
    // which is exactly the cascade contract: the receiver is evaluated once, every message goes to
    // that object in source order, and the cascade answers the first message's value. Hidden
    // temporaries carry both, so nothing the source wrote is rewritten and no name can collide.
    case 'cascade': {
      // ADR 0089 records this boundary rather than widening quietly. The cascade lowering evaluates
      // its receiver ONCE into a hidden temporary, and a super send has no receiver value to put
      // there — `super` moves lookup, it does not denote an object — so a cascade on `super` would
      // need cascade semantics of its own. The forcing consumer is an ordinary keyword super send,
      // so this is refused deterministically instead of being half-supported.
      if (syntax.receiver.kind === 'super') {
        throw new TypeError(
          'a cascade receiver may not be super: a cascade evaluates its receiver once into a '
          + 'temporary, and super denotes no value to evaluate',
        );
      }
      const receiverId = scope.declareHiddenTemporary(`$cascadeReceiver:${state.nextCascade}`);
      const answerId = scope.declareHiddenTemporary(`$cascadeAnswer:${state.nextCascade}`);
      state.nextCascade += 1;
      const receiverRead = Object.freeze({op: 'binding', id: receiverId});
      const statements = [
        Object.freeze({
          op: 'binding-write',
          id: receiverId,
          value: compileExpression(syntax.receiver, scope, state),
        }),
        ...syntax.messages.map(({selector, arguments: args}, index) => {
          const send = compileSend(receiverRead, selector, args, scope, state);
          return index === 0
            ? Object.freeze({op: 'binding-write', id: answerId, value: send})
            : send;
        }),
        Object.freeze({op: 'binding', id: answerId}),
      ];
      return Object.freeze({op: 'sequence', statements: Object.freeze(statements)});
    }
    case 'block': {
      const blockId = `${state.path}/block:${state.nextBlock}`;
      state.nextBlock += 1;
      const nested = compileBlockSyntax(syntax, {
        parent: scope,
        path: blockId,
        representation: state.representation,
      });
      return Object.freeze({
        op: 'block',
        blockId,
        captures: nested.captureInitializers,
        program: nested.program,
      });
    }
    // Temporaries belong to the activation, so a sequence is only ever a Block body and is
    // compiled by compileBlockSyntax. Reaching here would mean a scope had gone missing.
    case 'sequence':
      throw new TypeError('a statement sequence may only appear as a block body');
    default:
      throw new TypeError(`unsupported Symmetric Smalltalk syntax kind: ${syntax.kind}`);
  }
}

function compileBody(syntax, scope, state) {
  if (syntax.kind !== 'sequence') return compileExpression(syntax, scope, state);
  scope.declareTemporaries(syntax.temporaries);
  const statements = Object.freeze(syntax.statements.map((statement) => compileExpression(statement, scope, state)));
  return statements.length === 1 ? statements[0] : Object.freeze({op: 'sequence', statements});
}

function compileBlockSyntax(syntax, {
  parent = null,
  path = 'root',
  rootCaptures = new Map(),
  instanceVariables = new Map(),
  representation = LAGRANGE_CODE_V0,
  methodHome = false,
  intrinsics = new Map(),
  globals = new Map(),
  classVariables = new Map(),
} = {}) {
  const scope = new SemanticScope({
    parent, path, parameters: syntax.parameters, rootCaptures, instanceVariables, methodHome,
    intrinsics, globals, classVariables,
  });
  const state = {path, nextBlock: 0, nextCascade: 0, nextArrayLiteral: 0, representation};
  const body = compileBody(syntax.body, scope, state);
  const program = representation === LAGRANGE_CODE_V1
    ? Object.freeze({
      parameters: scope.parameterDescriptors(),
      temporaries: scope.temporaryDescriptors(),
      captures: scope.captureDescriptors(representation),
      body,
    })
    : Object.freeze({
      parameters: scope.parameterDescriptors(),
      captures: scope.captureDescriptors(representation),
      body,
    });
  return Object.freeze({
    program,
    captureInitializers: scope.captureInitializers(representation),
    globalBindingIdsUsed: Object.freeze([...scope.globalsUsed]),
    classVariableBindingIdsUsed: Object.freeze([...scope.classVarsUsed]),
  });
}

function compileSymmetricSmalltalkSemanticBlock(source, {
  captures = {}, instanceVariables = {}, methodHome = false, intrinsics = {}, globals = {},
  classVariables = {},
} = {}) {
  // ADR 0056: `nil` is the compiler's own intrinsic, so it is supplied here rather than by each
  // caller. Centralised for two reasons — every Symmetric Smalltalk compilation can write `nil`
  // whatever entry point it came through, and no caller can redefine what `nil` means. A caller may
  // still add intrinsics of its own; it may not replace this one, and saying so beats silently
  // winning an ordering race with it.
  if (Object.hasOwn(intrinsics, NIL_CAPTURE)) {
    throw new TypeError(`the ${NIL_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  if (Object.hasOwn(intrinsics, SYMBOL_CAPTURE)) {
    throw new TypeError(`the ${SYMBOL_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  if (Object.hasOwn(intrinsics, CHARACTER_CAPTURE)) {
    throw new TypeError(`the ${CHARACTER_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  if (Object.hasOwn(intrinsics, ARRAY_CAPTURE)) {
    throw new TypeError(`the ${ARRAY_CAPTURE} intrinsic is owned by the compiler and cannot be replaced`);
  }
  const syntax = parseSymmetricSmalltalkBlock(source);
  const representation = selectSemanticRepresentation(syntax);
  const compiled = compileBlockSyntax(syntax, {
    path: 'root',
    rootCaptures: normalizeRootCaptures(captures),
    instanceVariables: new Map(Object.entries(instanceVariables)),
    representation,
    methodHome,
    intrinsics: new Map([
      ...Object.entries(intrinsics),
      [NIL_CAPTURE, NIL_BINDING_ID],
      [SYMBOL_CAPTURE, SYMBOL_BINDING_ID],
      [CHARACTER_CAPTURE, CHARACTER_BINDING_ID],
      [ARRAY_CAPTURE, ARRAY_BINDING_ID],
    ]),
    globals: new Map(Object.entries(globals)),
    classVariables: new Map(Object.entries(classVariables)),
  });
  return Object.freeze({
    syntax,
    program: compiled.program,
    representation,
    globalBindingIdsUsed: compiled.globalBindingIdsUsed,
    classVariableBindingIdsUsed: compiled.classVariableBindingIdsUsed,
  });
}

export {
  ARRAY_BINDING_ID,
  ARRAY_CAPTURE,
  CHARACTER_BINDING_ID,
  CHARACTER_CAPTURE,
  SUPER_SEND_CAPTURE,
  CLASS_VAR_CAPTURE_PREFIX,
  INSTANCE_SLOT_READ_CAPTURE,
  NIL_BINDING_ID,
  NIL_CAPTURE,
  NON_LOCAL_RETURN_CAPTURE,
  INSTANCE_SLOT_WRITE_CAPTURE,
  SYMBOL_BINDING_ID,
  SYMBOL_CAPTURE,
  compileSymmetricSmalltalkSemanticBlock,
  needsMutableLexicalState,
  selectSemanticRepresentation,
};

const BINARY_SELECTOR_CHARS = new Set('+-*/=<>~&,@%?!\\'.split(''));

// Symbol literal characters. `#` begins a symbol; what follows determines the form:
// identifier chars (unary), keyword sequence (`#at:put:`), or binary selector chars (`#+`).
// Quoted symbols are deliberately not supported.

// ADR 0056 decision 3. Reserved pseudo-literals: they read as identifiers but are not names, so
// nothing may declare, capture, shadow or assign to one.
//
// Owned here, in one place, because the checks that enforce it are spread across block parameters,
// temporaries, assignment targets and explicit captures — four sites that would otherwise drift, as
// they already had: `self` was refused as a temporary and as an assignment target but accepted as a
// block parameter.
//
// ADR 0089 adds `super` to exactly this set rather than to the identifier path. Leaving it an
// ordinary name is the pre-0089 defect — it resolved as nothing and reported `unbound Symmetric
// Smalltalk name: super` — and binding it as a global would be worse, because `super` names no
// object at all: it is a receiver MARKER whose only effect is to move where lookup starts. Being
// reserved here is what makes a parameter, temporary, assignment target or explicit capture called
// `super` a refusal at all four existing sites instead of a fifth rule.
const RESERVED_WORDS = Object.freeze(new Set(['self', 'super', 'true', 'false', 'nil']));

function isReservedWord(name) {
  return RESERVED_WORDS.has(name);
}

class SymmetricSmalltalkSyntaxError extends SyntaxError {
  constructor(message, position) {
    super(`${message} at ${position}`);
    this.name = 'SymmetricSmalltalkSyntaxError';
    this.position = position;
  }
}

// WS3 (general language widening): a negative integer literal such as `-32` is
// Standard Smalltalk syntax, and the runtime's `0 - 32` already evaluates to a
// negative Value, so the literal is not new semantics — it is the canonical
// spelling of a value that already exists. The tokenizer still emits `-` as a
// binary selector so that `5-3`, `a-3` and `5 - 3` keep their binary-send
// meaning; the parser calls this only at an operand position (the start of a
// primary), where a leading `-` can only be a sign. `-16r1F` is covered too.
function isNegativeIntegerLiteralAt(tokens, index) {
  const minus = tokens[index];
  const next = tokens[index + 1];
  return Boolean(
    minus && minus.type === 'binary' && minus.value === '-'
    && next && next.type === 'integer',
  );
}

function isIdentifierStart(char) {
  return /[A-Za-z_]/.test(char ?? '');
}

function isIdentifierPart(char) {
  return /[A-Za-z0-9_]/.test(char ?? '');
}

// The two assignment spellings a token stream can carry: native `:=` and the Cuis legacy arrow,
// which the tokenizer keeps as the DISTINCT `legacyAssign` token below. Token-level
// declaration/binding scans (the Cuis import adapter's bound-names analysis) must recognize both
// through this ONE predicate rather than re-deciding the pair at every scan site.
function isAssignmentToken(token) {
  return token?.type === 'assign' || token?.type === 'legacyAssign';
}

// The Cuis legacy assignment arrow, measured against the pinned Cuis scanner/parser (bead
// lagrange-images-xxm.3, oracle executed on the pinned Cuis7.9-8090 image): at a token boundary,
// a standalone `_` token scans as the assignment arrow IFF the next character is NOT a letter,
// digit, underscore or colon (Scanner>>xUnderscore, stamp jmv 26/Apr/2023: #leftArrow when the following
// character's type is outside {xLetter, xDigit, xUnderscore, xColon}). Every other underscore form
// is a Cuis-legal identifier/keyword form — `_foo`, `_7`, `__`, `foo_`, `a_b`, the `_:` keyword —
// and stays on the ordinary identifier path, which is why `_` remains an identifier character
// above. Measured: `a _ b` assigns 7; `a _7` SENDS the unary selector `_7`; `a_7` is ONE
// identifier; a bare `_` is not a legal selector. The tokenizer emits the arrow as a distinct
// token and decides nothing further: the native parser refuses it outright, and the Cuis import
// adapter translates it to canonical `:=` at the import boundary.
function isLegacyAssignmentArrowAt(source, index) {
  return source[index] === '_' && !/[A-Za-z0-9_:]/.test(source[index + 1] ?? '');
}

// Character literal syntax is ordinary native Smalltalk syntax, owned here rather than by the
// Cuis adapter. The pinned Cuis 7.9-8090 oracle (bead lagrange-images-xxm.10) establishes the exact
// lexical boundary: `$` consumes ONE following Unicode code point, including whitespace, newline,
// quote, apostrophe and `$` itself; there is no JavaScript-style escape grammar and no separating
// whitespace is required before a following message. A physical end of source contributes Cuis's
// scanner end marker, Character U+001A, so a final `$` denotes that character rather than being an
// unterminated token. Strings and comments are scanned before this branch, hence their dollars stay
// data or ignored comment text.
const SMALLTALK_END_OF_SOURCE_CHARACTER = '\u001a';

function characterLiteralAt(source, index) {
  const valueIndex = index + 1;
  if (valueIndex >= source.length) {
    return Object.freeze({value: SMALLTALK_END_OF_SOURCE_CHARACTER, end: source.length});
  }
  const codePoint = source.codePointAt(valueIndex);
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) {
    throw new SymmetricSmalltalkSyntaxError('character literal must contain a Unicode scalar value', index);
  }
  const value = String.fromCodePoint(codePoint);
  return Object.freeze({value, end: valueIndex + value.length});
}

function tokenizeSymmetricSmalltalk(source) {
  if (typeof source !== 'string') throw new TypeError('source must be text');
  const tokens = [];
  let index = 0;

  const push = (type, value, start = index) => tokens.push(Object.freeze({type, value, start, end: index}));

  while (index < source.length) {
    const char = source[index];

    if (/\s/.test(char)) {
      index += 1;
      continue;
    }

    if (char === '"') {
      const start = index;
      index += 1;
      while (index < source.length && source[index] !== '"') index += 1;
      if (index >= source.length) throw new SymmetricSmalltalkSyntaxError('unterminated comment', start);
      index += 1;
      continue;
    }

    // Symbol literal: `#` followed by identifier chars (unary), a keyword sequence
    // (`#at:put:`), or binary selector chars (`#+`). The token carries the canonical
    // selector text. No quoted/arbitrary symbol syntax.
    if (char === '#') {
      const start = index;
      index += 1; // consume '#'
      if (index >= source.length) {
        throw new SymmetricSmalltalkSyntaxError('bare # is not a valid symbol literal', start);
      }
      const next = source[index];
      // Literal Array `#( ... )` (WS3): `#(` opens a literal Array, distinct from a symbol.
      // `#[ ... ]` (byte-array literal) is deliberately NOT this facility — its resulting class
      // and element restrictions differ, and it is classified separately when upstream demands it.
      if (next === '(') {
        index += 1; // consume '('
        push('arrayOpen', '(', start);
        continue;
      }
      if (next === '[') {
        index += 1; // consume '['
        push('byteArrayOpen', '[', start);
        continue;
      }
      if (isIdentifierStart(next)) {
        // Unary or keyword symbol: read identifier chars, then optionally ':' sequences
        let value = '';
        while (index < source.length) {
          if (isIdentifierPart(source[index])) {
            value += source[index];
            index += 1;
            continue;
          }
          if (source[index] === ':' && source[index + 1] !== '=') {
            value += ':';
            index += 1;
            continue;
          }
          break;
        }
        push('symbol', value, start);
        continue;
      }
      if (BINARY_SELECTOR_CHARS.has(next)) {
        let value = '';
        while (index < source.length && BINARY_SELECTOR_CHARS.has(source[index])) {
          value += source[index];
          index += 1;
        }
        push('symbol', value, start);
        continue;
      }
      throw new SymmetricSmalltalkSyntaxError(
        `invalid symbol literal: #${next}`, start,
      );
    }

    if (char === "'") {
      const start = index;
      index += 1;
      let value = '';
      let closed = false;
      while (index < source.length) {
        if (source[index] === "'") {
          if (source[index + 1] === "'") {
            value += "'";
            index += 2;
            continue;
          }
          index += 1;
          closed = true;
          break;
        }
        value += source[index];
        index += 1;
      }
      if (!closed) throw new SymmetricSmalltalkSyntaxError('unterminated string', start);
      push('string', value, start);
      continue;
    }

    if (char === '$') {
      const start = index;
      const literal = characterLiteralAt(source, index);
      index = literal.end;
      push('character', literal.value, start);
      continue;
    }

    if (/[0-9]/.test(char)) {
      const start = index;
      while (/[0-9]/.test(source[index] ?? '')) index += 1;
      // ADR 0057 workstream 3. `<base>r<digits>` is a radix integer literal (`16rFF`, `2r1010`).
      // Radix is source syntax, never runtime representation: the token carries the canonical
      // decimal text an ordinary literal would, so the parser, the semantic layer and the durable
      // Value model (which accepts only `/^-?\d+$/`) never learn a radix existed. A leading `-` is
      // a binary selector send in source order (`0 - 16r80`), not part of the literal.
      if (source[index] === 'r' || source[index] === 'R') {
        const baseText = source.slice(start, index);
        const base = Number.parseInt(baseText, 10);
        index += 1; // consume the `r`
        const digitsStart = index;
        while (/[0-9A-Za-z]/.test(source[index] ?? '')) index += 1;
        const digits = source.slice(digitsStart, index);
        if (digits === '' || !/^\d+$/.test(baseText) || base < 2 || base > 36) {
          throw new SymmetricSmalltalkSyntaxError(`malformed radix literal ${baseText}r${digits}`, start);
        }
        // Per-digit validation catches `2r102`, which a bulk parse would silently truncate.
        let value = 0n;
        const radix = BigInt(base);
        for (const digitChar of digits) {
          const digit = Number.parseInt(digitChar, 36);
          if (digit >= base) {
            throw new SymmetricSmalltalkSyntaxError(
              `digit ${digitChar} is out of range for radix ${base} in ${baseText}r${digits}`, start,
            );
          }
          value = value * radix + BigInt(digit);
        }
        push('integer', value.toString(10), start);
        continue;
      }
      push('integer', source.slice(start, index), start);
      continue;
    }

    // The measured legacy assignment arrow comes first once `_` is at a token boundary: a bare
    // `_` NOT followed by an identifier character is never an identifier. `_foo` and friends fall
    // through to the ordinary identifier path below, exactly as the pinned Cuis oracle answers;
    // an underscore already reached inside `a_b` was consumed by that identifier's scan.
    if (isLegacyAssignmentArrowAt(source, index)) {
      const start = index;
      index += 1;
      push('legacyAssign', '_', start);
      continue;
    }

    if (isIdentifierStart(char)) {
      const start = index;
      index += 1;
      while (isIdentifierPart(source[index])) index += 1;
      const name = source.slice(start, index);
      // `:` only makes a keyword when it is not the start of `:=`.
      if (source[index] === ':' && source[index + 1] !== '=') {
        index += 1;
        push('keyword', `${name}:`, start);
      } else {
        push('identifier', name, start);
      }
      continue;
    }

    if (BINARY_SELECTOR_CHARS.has(char)) {
      const start = index;
      index += 1;
      while (BINARY_SELECTOR_CHARS.has(source[index])) index += 1;
      push('binary', source.slice(start, index), start);
      continue;
    }

    if (char === ':' && source[index + 1] === '=') {
      const start = index;
      index += 2;
      push('assign', ':=', start);
      continue;
    }

    // ADR 0055: `^` is syntax, not a binary selector, so it gets its own token and cannot be
    // absorbed into an adjacent operator the way `^=` otherwise would be.
    if (char === '^') {
      const start = index;
      index += 1;
      push('caret', '^', start);
      continue;
    }

    if ('[]()|:.;'.includes(char)) {
      const start = index;
      index += 1;
      push(char, char, start);
      continue;
    }

    throw new SymmetricSmalltalkSyntaxError(`unexpected character ${JSON.stringify(char)}`, index);
  }

  tokens.push(Object.freeze({type: 'eof', value: '', start: index, end: index}));
  return Object.freeze(tokens);
}

export {
  SMALLTALK_END_OF_SOURCE_CHARACTER,
  RESERVED_WORDS,
  isReservedWord,
  isAssignmentToken,
  isNegativeIntegerLiteralAt,
  SymmetricSmalltalkSyntaxError,
  tokenizeSymmetricSmalltalk,
};

const SYMMETRIC_SMALLTALK_ID = 'symmetric-smalltalk';
const SYMMETRIC_SMALLTALK_SOURCE_V0 = 'symmetric-smalltalk/source-v0';

const SYMMETRIC_SMALLTALK = Object.freeze({
  id: SYMMETRIC_SMALLTALK_ID,
  name: 'Symmetric Smalltalk',
  status: 'seed',
  executionModel: 'image-resident',
  principles: Object.freeze([
    'everything user-visible is an object',
    'message send is the ordinary composition mechanism',
    'blocks are the uniform executable/compositional representation',
    'language implementation should become image-resident over time',
    'syntax is a language personality, not a persistence boundary',
  ]),
  capabilities: Object.freeze({
    parse: true,
    compile: true,
    evaluate: true,
    bootstrap: false,
  }),
});

export {SYMMETRIC_SMALLTALK, SYMMETRIC_SMALLTALK_ID, SYMMETRIC_SMALLTALK_SOURCE_V0};

export * from './model.js';
export * from './migration.js';
export {referencesOfRecord} from '../graph/references.js';
export * from './version-token.js';

import {canonicalizeValue, isObjectRef, objectRef} from '../value/index.js';
import {
  SHAPE_INDEXED,
  assertObjectMatchesShape,
  assertShapeRecord,
  createObjectRecord,
  shapeIndexedKind,
} from './model.js';

const IMAGE_SHAPE_MIGRATION_PLAN_V1 = 'lagrange-image-shape-migration-plan/v1';
const IMAGE_SHAPE_MIGRATION_RECEIPT_V1 = 'lagrange-image-shape-migration-receipt/v1';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function normalizeShapeIdInput(shapeOrId, label) {
  if (typeof shapeOrId === 'string' && shapeOrId.length > 0) return shapeOrId;
  if (isObjectRef(shapeOrId)) return shapeOrId.objectId;
  if (shapeOrId && typeof shapeOrId === 'object' && typeof shapeOrId.id === 'string' && shapeOrId.id.length > 0) {
    return shapeOrId.id;
  }
  throw new TypeError(`${label} must be a non-empty shape id, shape ObjectRef, or shape record`);
}

function buildShapeSlotMigrationPlan({
  fromShape,
  toShape,
  slotMapping = {},
  defaultSlotValues = {},
  defaultSlotValue = null,
  allowDropIndexed = false,
} = {}) {
  assertShapeRecord(fromShape);
  assertShapeRecord(toShape);
  if (!slotMapping || typeof slotMapping !== 'object' || Array.isArray(slotMapping)) {
    throw new TypeError('slotMapping must be a plain object');
  }
  if (!defaultSlotValues || typeof defaultSlotValues !== 'object' || Array.isArray(defaultSlotValues)) {
    throw new TypeError('defaultSlotValues must be a plain object');
  }

  const fromIndexed = shapeIndexedKind(fromShape);
  const toIndexed = shapeIndexedKind(toShape);
  if (fromIndexed === SHAPE_INDEXED.VALUES && toIndexed === SHAPE_INDEXED.NONE && !allowDropIndexed) {
    throw new TypeError(
      `shape migration from ${fromShape.id} to ${toShape.id} drops indexed values storage without allowDropIndexed`,
    );
  }

  const fromSlotById = new Map(fromShape.slots.map((slot) => [slot.id, slot]));
  const fromSlotByName = new Map();
  for (const slot of fromShape.slots) {
    if (!fromSlotByName.has(slot.name)) {
      fromSlotByName.set(slot.name, slot);
    }
  }

  const mappedSourceSlotIds = new Set();
  const slotActions = [];

  for (const targetSlot of toShape.slots) {
    const explicitKey = Object.hasOwn(slotMapping, targetSlot.id)
      ? slotMapping[targetSlot.id]
      : Object.hasOwn(slotMapping, targetSlot.name)
        ? slotMapping[targetSlot.name]
        : null;

    let sourceSlot = null;
    if (explicitKey !== null && explicitKey !== undefined) {
      requiredText(explicitKey, `slotMapping target for ${targetSlot.name}`);
      sourceSlot = fromSlotById.get(explicitKey) ?? fromSlotByName.get(explicitKey) ?? null;
      if (!sourceSlot) {
        throw new TypeError(
          `slotMapping for target slot ${targetSlot.name} (${targetSlot.id}) references missing source slot ${explicitKey} in shape ${fromShape.id}`,
        );
      }
    } else {
      sourceSlot = fromSlotById.get(targetSlot.id) ?? fromSlotByName.get(targetSlot.name) ?? null;
    }

    if (sourceSlot) {
      mappedSourceSlotIds.add(sourceSlot.id);
      slotActions.push(
        Object.freeze({
          targetSlotId: targetSlot.id,
          targetSlotName: targetSlot.name,
          action: 'copy',
          sourceSlotId: sourceSlot.id,
          sourceSlotName: sourceSlot.name,
        }),
      );
    } else {
      const rawDefault = Object.hasOwn(defaultSlotValues, targetSlot.id)
        ? defaultSlotValues[targetSlot.id]
        : Object.hasOwn(defaultSlotValues, targetSlot.name)
          ? defaultSlotValues[targetSlot.name]
          : defaultSlotValue;
      if (rawDefault === null || rawDefault === undefined) {
        throw new TypeError(
          `new slot ${targetSlot.name} (${targetSlot.id}) in shape ${toShape.id} requires a default Value in defaultSlotValues or defaultSlotValue`,
        );
      }
      const canonicalDefault = canonicalizeValue(rawDefault);
      slotActions.push(
        Object.freeze({
          targetSlotId: targetSlot.id,
          targetSlotName: targetSlot.name,
          action: 'initialize',
          defaultValue: canonicalDefault,
        }),
      );
    }
  }

  const removedSlots = fromShape.slots
    .filter((slot) => !mappedSourceSlotIds.has(slot.id))
    .map((slot) => Object.freeze({id: slot.id, name: slot.name}));

  return Object.freeze({
    fromShapeId: fromShape.id,
    toShapeId: toShape.id,
    fromIndexed,
    toIndexed,
    slotActions: Object.freeze(slotActions),
    removedSlots: Object.freeze(removedSlots),
  });
}

function migrateObjectRecordToShape(
  objectRecord,
  {
    fromShape,
    toShape,
    slotMapping = {},
    defaultSlotValues = {},
    defaultSlotValue = null,
    allowDropIndexed = false,
    _compiledPlan = null,
  } = {},
) {
  assertObjectMatchesShape(objectRecord, fromShape);
  assertShapeRecord(toShape);

  const plan =
    _compiledPlan
    ?? buildShapeSlotMigrationPlan({
      fromShape,
      toShape,
      slotMapping,
      defaultSlotValues,
      defaultSlotValue,
      allowDropIndexed,
    });

  const nextSlots = {};
  for (const step of plan.slotActions) {
    if (step.action === 'copy') {
      nextSlots[step.targetSlotId] = objectRecord.slots[step.sourceSlotId];
    } else {
      nextSlots[step.targetSlotId] = step.defaultValue;
    }
  }

  const nextInput = {
    id: objectRecord.id,
    imageId: objectRecord.imageId,
    shape: objectRef(toShape.imageId, toShape.id),
    behavior: objectRecord.behavior ?? null,
    slots: nextSlots,
    metadata: objectRecord.metadata ?? {},
  };

  if (plan.toIndexed === SHAPE_INDEXED.VALUES) {
    nextInput.indexed = Object.hasOwn(objectRecord, 'indexed') ? [...objectRecord.indexed] : [];
  }

  const migrated = createObjectRecord(nextInput);
  assertObjectMatchesShape(migrated, toShape);
  return migrated;
}

function matchesBehaviorFilter(record, behaviorFilter, imageId) {
  if (!behaviorFilter) return true;
  const targetId = typeof behaviorFilter === 'string'
    ? behaviorFilter
    : isObjectRef(behaviorFilter)
      ? behaviorFilter.objectId
      : null;
  requiredText(targetId, 'behaviorFilter');
  return (
    isObjectRef(record.behavior)
    && record.behavior.imageId === imageId
    && record.behavior.objectId === targetId
  );
}

async function planImageShapeMigration({
  images,
  imageId,
  fromShapeId,
  toShapeId,
  behaviorFilter = null,
  slotMapping = {},
  defaultSlotValues = {},
  defaultSlotValue = null,
  allowDropIndexed = false,
} = {}) {
  if (!images || typeof images.getShape !== 'function' || typeof images.listObjects !== 'function') {
    throw new TypeError('planImageShapeMigration requires an ImageService with getShape and listObjects');
  }
  requiredText(imageId, 'imageId');
  const resolvedFromId = normalizeShapeIdInput(fromShapeId, 'fromShapeId');
  const resolvedToId = normalizeShapeIdInput(toShapeId, 'toShapeId');

  const fromShape = await images.getShape(imageId, resolvedFromId);
  if (!fromShape) {
    throw new TypeError(`source shape not found: ${imageId}/${resolvedFromId}`);
  }
  const toShape = await images.getShape(imageId, resolvedToId);
  if (!toShape) {
    throw new TypeError(`target shape not found: ${imageId}/${resolvedToId}`);
  }

  const compiledPlan = buildShapeSlotMigrationPlan({
    fromShape,
    toShape,
    slotMapping,
    defaultSlotValues,
    defaultSlotValue,
    allowDropIndexed,
  });

  if (resolvedFromId === resolvedToId) {
    return Object.freeze({
      format: IMAGE_SHAPE_MIGRATION_PLAN_V1,
      imageId,
      fromShapeId: resolvedFromId,
      toShapeId: resolvedToId,
      slotActions: compiledPlan.slotActions,
      removedSlots: compiledPlan.removedSlots,
      objectIds: Object.freeze([]),
      objectCount: 0,
      migratedRecords: Object.freeze([]),
    });
  }

  const allObjects = await images.listObjects(imageId);
  const candidates = allObjects
    .filter(
      (obj) =>
        isObjectRef(obj.shape)
        && obj.shape.imageId === imageId
        && obj.shape.objectId === resolvedFromId
        && matchesBehaviorFilter(obj, behaviorFilter, imageId),
    )
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  const migratedRecords = candidates.map((obj) =>
    migrateObjectRecordToShape(obj, {
      fromShape,
      toShape,
      _compiledPlan: compiledPlan,
    }),
  );

  return Object.freeze({
    format: IMAGE_SHAPE_MIGRATION_PLAN_V1,
    imageId,
    fromShapeId: resolvedFromId,
    toShapeId: resolvedToId,
    slotActions: compiledPlan.slotActions,
    removedSlots: compiledPlan.removedSlots,
    objectIds: Object.freeze(migratedRecords.map((r) => r.id)),
    objectCount: migratedRecords.length,
    migratedRecords: Object.freeze(migratedRecords),
  });
}

async function migrateImageObjectsToShape({
  images,
  imageId,
  fromShapeId,
  toShapeId,
  behaviorFilter = null,
  slotMapping = {},
  defaultSlotValues = {},
  defaultSlotValue = null,
  allowDropIndexed = false,
  dryRun = false,
} = {}) {
  if (!images || typeof images.putObject !== 'function') {
    throw new TypeError('migrateImageObjectsToShape requires an ImageService with putObject');
  }
  const plan = await planImageShapeMigration({
    images,
    imageId,
    fromShapeId,
    toShapeId,
    behaviorFilter,
    slotMapping,
    defaultSlotValues,
    defaultSlotValue,
    allowDropIndexed,
  });

  if (!dryRun) {
    for (const migratedRecord of plan.migratedRecords) {
      await images.putObject(imageId, {
        id: migratedRecord.id,
        shape: migratedRecord.shape,
        behavior: migratedRecord.behavior ?? null,
        slots: migratedRecord.slots,
        ...(Object.hasOwn(migratedRecord, 'indexed') ? {indexed: migratedRecord.indexed} : {}),
        metadata: migratedRecord.metadata ?? {},
      });
    }
  }

  return Object.freeze({
    format: IMAGE_SHAPE_MIGRATION_RECEIPT_V1,
    imageId,
    fromShapeId: plan.fromShapeId,
    toShapeId: plan.toShapeId,
    dryRun: Boolean(dryRun),
    migratedObjectIds: plan.objectIds,
    migratedCount: plan.objectCount,
    slotActions: plan.slotActions,
    removedSlots: plan.removedSlots,
  });
}

export {
  IMAGE_SHAPE_MIGRATION_PLAN_V1,
  IMAGE_SHAPE_MIGRATION_RECEIPT_V1,
  buildShapeSlotMigrationPlan,
  migrateImageObjectsToShape,
  migrateObjectRecordToShape,
  planImageShapeMigration,
};

import {canonicalizeValue, isObjectRef, isReference} from '../value/index.js';

const SHAPE_INDEXED = Object.freeze({
  NONE: 'none',
  VALUES: 'values',
});

function normalizeMetadata(metadata, label = 'metadata') {
  const seen = new Set();
  function visit(value, path) {
    if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
    if (typeof value === 'number') {
      if (!Number.isFinite(value)) throw new TypeError(`${path} must use finite JSON numbers`);
      return value;
    }
    if (typeof value !== 'object') throw new TypeError(`${path} must be JSON-compatible metadata`);
    if (isReference(value)) throw new TypeError(`${path} must not contain object references; graph edges belong in slots`);
    if (seen.has(value)) throw new TypeError(`${path} must not be cyclic`);
    seen.add(value);
    try {
      if (Array.isArray(value)) return value.map((entry, index) => visit(entry, `${path}[${index}]`));
      if (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) {
        throw new TypeError(`${path} must contain only plain objects and arrays`);
      }
      const normalized = {};
      for (const [key, entry] of Object.entries(value)) normalized[key] = visit(entry, `${path}.${key}`);
      return normalized;
    } finally {
      seen.delete(value);
    }
  }
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) throw new TypeError(`${label} must be an object`);
  return visit(metadata, label);
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function normalizeShapeSlots(slots) {
  if (!Array.isArray(slots)) throw new TypeError('shape slots must be an array');
  const seen = new Set();
  return slots.map((slot) => {
    if (!slot || typeof slot !== 'object' || Array.isArray(slot)) throw new TypeError('shape slot must be an object');
    const keys = Object.keys(slot).sort();
    if (keys.length !== 2 || keys[0] !== 'id' || keys[1] !== 'name') throw new TypeError('shape slot must contain exactly id and name');
    const id = requiredText(slot.id, 'slot id');
    const name = requiredText(slot.name, 'slot name');
    if (seen.has(id)) throw new TypeError(`duplicate slot id: ${id}`);
    seen.add(id);
    return Object.freeze({id, name});
  });
}

function normalizeShapeIndexed(indexed) {
  if (indexed !== SHAPE_INDEXED.NONE && indexed !== SHAPE_INDEXED.VALUES) {
    throw new TypeError(`shape indexed declaration must be ${SHAPE_INDEXED.NONE} or ${SHAPE_INDEXED.VALUES}`);
  }
  return indexed;
}

function shapeIndexedKind(shape) {
  if (!shape || shape.kind !== 'shape') throw new TypeError('record is not a shape');
  return normalizeShapeIndexed(Object.hasOwn(shape, 'indexed') ? shape.indexed : SHAPE_INDEXED.NONE);
}

// ADR 0047 keeps old records exact: absence of `indexed` is interpreted as `none`, but merely
// reading or rewriting an old Shape does not materialize a new field into its durable form.
function createShapeRecord(input) {
  const {id, imageId, slots = [], metadata = {}, updatedAt = null} = input ?? {};
  const record = {
    kind: 'shape',
    id: requiredText(id, 'shape id'),
    imageId: requiredText(imageId, 'shape imageId'),
    slots: normalizeShapeSlots(slots),
    metadata: normalizeMetadata(metadata, 'shape metadata'),
    updatedAt,
  };
  if (Object.hasOwn(input, 'indexed')) record.indexed = normalizeShapeIndexed(input.indexed);
  return Object.freeze(record);
}

function assertShapeRecord(record) {
  if (!record || record.kind !== 'shape') throw new TypeError('record is not a shape');
  createShapeRecord(record);
  return record;
}

function shapeSlotIds(shape) {
  assertShapeRecord(shape);
  return new Set(shape.slots.map(({id}) => id));
}

function normalizeRef(value, label) {
  const normalized = canonicalizeValue(value);
  if (!isObjectRef(normalized)) throw new TypeError(`${label} must be an unpinned object ref`);
  return normalized;
}

function normalizeObjectSlots(slots) {
  if (!slots || typeof slots !== 'object' || Array.isArray(slots)) throw new TypeError('object slots must be keyed by stable slot id');
  const normalized = {};
  for (const [slotId, value] of Object.entries(slots)) {
    requiredText(slotId, 'slot id');
    normalized[slotId] = canonicalizeValue(value);
  }
  return Object.freeze(normalized);
}

function normalizeIndexedValues(indexed) {
  if (!Array.isArray(indexed)) throw new TypeError('object indexed part must be an array of canonical Values');
  return Object.freeze(indexed.map((value) => canonicalizeValue(value)));
}

// As for Shape, preserving property absence matters: old object records did not carry an indexed
// part, and loading one must not manufacture one. An explicitly present empty array is different —
// it is the zero-length indexed part of a Shape that declares `values`.
function createObjectRecord(input) {
  const {id, imageId, shape, behavior = null, slots = {}, metadata = {}, updatedAt = null} = input ?? {};
  const record = {
    kind: 'object',
    id: requiredText(id, 'object id'),
    imageId: requiredText(imageId, 'object imageId'),
    shape: normalizeRef(shape, 'object shape'),
    behavior: behavior === null ? null : normalizeRef(behavior, 'object behavior'),
    slots: normalizeObjectSlots(slots),
    metadata: normalizeMetadata(metadata, 'object metadata'),
    updatedAt,
  };
  if (Object.hasOwn(input, 'indexed')) record.indexed = normalizeIndexedValues(input.indexed);
  return Object.freeze(record);
}

function assertObjectRecord(record) {
  if (!record || record.kind !== 'object') throw new TypeError('record is not an object');
  createObjectRecord(record);
  return record;
}

function assertObjectMatchesShape(record, shape) {
  assertObjectRecord(record);
  assertShapeRecord(shape);
  const expected = shapeSlotIds(shape);
  const actual = new Set(Object.keys(record.slots));
  const missing = [...expected].filter((slotId) => !actual.has(slotId));
  const extra = [...actual].filter((slotId) => !expected.has(slotId));
  if (missing.length || extra.length) {
    throw new TypeError(`object slots do not match shape ${shape.id}; missing: ${missing.join(', ') || '-'}; extra: ${extra.join(', ') || '-'}`);
  }

  const indexedKind = shapeIndexedKind(shape);
  const hasIndexed = Object.hasOwn(record, 'indexed');
  if (indexedKind === SHAPE_INDEXED.VALUES && !hasIndexed) {
    throw new TypeError(`object does not match shape ${shape.id}; indexed values part is required`);
  }
  if (indexedKind === SHAPE_INDEXED.NONE && hasIndexed) {
    throw new TypeError(`object does not match shape ${shape.id}; shape declares no indexed part`);
  }
  return record;
}

export {
  SHAPE_INDEXED,
  assertObjectMatchesShape,
  assertObjectRecord,
  assertShapeRecord,
  createObjectRecord,
  createShapeRecord,
  normalizeMetadata,
  shapeIndexedKind,
  shapeSlotIds,
};

import {objectResource} from '../authority/object-resource.js';
import {base64urlDecode, base64urlEncode, utf8DecodeLossy, utf8Encode} from '../support/portable-bytes.js';

// Opaque optimistic-concurrency tokens for image objects, per ADR 0042 decision 5.
//
// The token is scoped to the object it was issued for. An unscoped token carrying only a
// backend version would silently succeed against a different object that happens to sit at the
// same version: authority would still prevent an escalation, but the compare-and-set would have
// failed to represent the caller's assumption about *this* object, which is the entire point of
// supplying one.
//
//   token scoped to object identity  !=  token is object identity
//
// The caller still supplies the object id separately; the token confirms the assumption rather
// than naming the target. And the scope is object-wide rather than per binding or per field
// mapping, so a future version-aware projection can issue a token usable by any legitimate
// mutation binding over that object.
//
// Callers may compare and round-trip a token. They must not interpret, order or do arithmetic
// on one — which is why the backend's numeric version never appears in it verbatim.
const OBJECT_VERSION_TOKEN_V0 = 'object-version/v0';

class ObjectVersionTokenError extends TypeError {
  constructor(message) {
    super(message);
    this.name = 'ObjectVersionTokenError';
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new ObjectVersionTokenError(`${label} must be a non-empty string`);
  }
  return value;
}

// The faithful domain of the current backends: the mock computes `actualVersion + 1` in
// JavaScript Numbers and the Lagrange adapter converts SQL versions with `Number(...)`. Signed
// 64-bit would advertise more exactness than exists.
function assertBackendVersion(value) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new ObjectVersionTokenError('object version must be a non-negative safe integer');
  }
  return value;
}

function objectVersionToken(imageId, objectId, backendVersion) {
  const scope = objectResource(
    requiredText(imageId, 'object version imageId'),
    requiredText(objectId, 'object version objectId'),
  );
  const version = base64urlEncode(utf8Encode(String(assertBackendVersion(backendVersion))));
  // `objectResource` is base64url plus '.', so ':' is an unambiguous separator.
  return `${OBJECT_VERSION_TOKEN_V0}:${scope}:${version}`;
}

// Returns the backend version only when the token was issued for exactly this object. A token
// for another object is rejected rather than reinterpreted, and the caller learns nothing about
// the other object from the failure.
function parseObjectVersionToken(token, imageId, objectId) {
  const text = requiredText(token, 'object version token');
  const parts = text.split(':');
  if (parts.length !== 3 || parts[0] !== OBJECT_VERSION_TOKEN_V0) {
    throw new ObjectVersionTokenError(`malformed ${OBJECT_VERSION_TOKEN_V0} token`);
  }
  const expectedScope = objectResource(
    requiredText(imageId, 'object version imageId'),
    requiredText(objectId, 'object version objectId'),
  );
  if (parts[1] !== expectedScope) {
    throw new ObjectVersionTokenError('object version token was issued for a different object');
  }
  const decoded = base64urlDecode(parts[2]);
  if (base64urlEncode(decoded) !== parts[2]) {
    throw new ObjectVersionTokenError(`malformed ${OBJECT_VERSION_TOKEN_V0} token`);
  }
  const version = Number(utf8DecodeLossy(decoded));
  if (!/^\d+$/.test(utf8DecodeLossy(decoded))) {
    throw new ObjectVersionTokenError(`malformed ${OBJECT_VERSION_TOKEN_V0} token`);
  }
  return assertBackendVersion(version);
}

// THE ONE conditional persistence seam for a token holder (ADR 0042 decision 5,
// ADR 0080). The backend's VersionConflictError carries collection, key,
// expectedVersion and actualVersion, and puts both numbers in its message.
// Propagating it — even as a `cause`, which would leave actualVersion reachable —
// would defeat the opaque token outright. Every lane that persists under a
// caller-supplied token therefore writes through here, and a conflict says only
// that the caller's assumption was stale: no actual version, no replacement
// token, no cause. The put itself is the image service's put (CAS + history in
// one backend transaction); this owner adds nothing but the translation.
class ObjectMutationConflictError extends Error {
  constructor(imageId, objectId) {
    super(`object mutation conflict: the supplied version token is stale for ${imageId}/${objectId}`);
    this.name = 'ObjectMutationConflictError';
    this.imageId = imageId;
    this.objectId = objectId;
  }
}

async function putObjectAtExpectedVersion(images, imageId, input, expectedVersion) {
  assertBackendVersion(expectedVersion);
  try {
    return await images.putObject(imageId, input, {expectedVersion});
  } catch (error) {
    if (error?.name === 'VersionConflictError') {
      // Deliberately no cause: attaching it would leave actualVersion reachable.
      throw new ObjectMutationConflictError(imageId, input.id);
    }
    throw error;
  }
}

export {
  OBJECT_VERSION_TOKEN_V0,
  ObjectMutationConflictError,
  ObjectVersionTokenError,
  objectVersionToken,
  parseObjectVersionToken,
  putObjectAtExpectedVersion,
};

