import {OBJECT_READ_OPERATION, objectResource} from '../authority/object-resource.js';
import {diffImageFrontiers, reconstructImageRecordsAtFrontier} from '../graph/diff.js';
import {isObjectRef} from '../value/index.js';
import {normalizeProjectDescriptor, normalizeProjectReleaseManifest} from './model.js';
import {PROJECT_SHAPE_ID, projectObjectId, readProjectDescriptor} from './working-state.js';

const PROJECT_DESCRIPTOR_DIFF_V1 = 'lagrange-project-descriptor-diff/v1';
const PROJECT_RELEASE_DIFF_V1 = 'lagrange-project-release-diff/v1';
const PROJECT_NONE_ID = 'lagrange-project/none/v1';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function sameRef(a, b) {
  if (a === null && b === null) return true;
  return isObjectRef(a) && isObjectRef(b) && a.imageId === b.imageId && a.objectId === b.objectId;
}

function diffProjectDescriptors(fromProject, toProject) {
  const from = normalizeProjectDescriptor(fromProject);
  const to = normalizeProjectDescriptor(toProject);

  const fromByKey = new Map(from.members.map((member) => [member.key, member]));
  const toByKey = new Map(to.members.map((member) => [member.key, member]));
  const allKeys = [...new Set([...fromByKey.keys(), ...toByKey.keys()])].sort(compareText);

  const addedMembers = [];
  const removedMembers = [];
  const modifiedMembers = [];
  const unchangedMembers = [];

  for (const key of allKeys) {
    const before = fromByKey.get(key) ?? null;
    const after = toByKey.get(key) ?? null;
    if (!before) {
      addedMembers.push(after);
    } else if (!after) {
      removedMembers.push(before);
    } else {
      const roleChanged = before.role !== after.role;
      const targetChanged = !sameRef(before.target, after.target);
      if (roleChanged || targetChanged) {
        modifiedMembers.push(
          Object.freeze({
            key,
            before,
            after,
            roleChanged,
            targetChanged,
          }),
        );
      } else {
        unchangedMembers.push(after);
      }
    }
  }

  const nameChanged = from.name !== to.name;
  const namespaceChanged = !sameRef(from.namespace, to.namespace);
  const identical =
    from.projectId === to.projectId &&
    !nameChanged &&
    !namespaceChanged &&
    addedMembers.length === 0 &&
    removedMembers.length === 0 &&
    modifiedMembers.length === 0;

  return Object.freeze({
    format: PROJECT_DESCRIPTOR_DIFF_V1,
    fromProjectId: from.projectId,
    toProjectId: to.projectId,
    fromName: from.name,
    toName: to.name,
    nameChanged,
    fromNamespace: from.namespace,
    toNamespace: to.namespace,
    namespaceChanged,
    identical,
    addedMembers: Object.freeze(addedMembers),
    removedMembers: Object.freeze(removedMembers),
    modifiedMembers: Object.freeze(modifiedMembers),
    unchangedMembers: Object.freeze(unchangedMembers),
  });
}

function diffProjectReleases(fromRelease, toRelease) {
  const from = normalizeProjectReleaseManifest(fromRelease);
  const to = normalizeProjectReleaseManifest(toRelease);

  const fromByKey = new Map(from.members.map((member) => [member.key, member]));
  const toByKey = new Map(to.members.map((member) => [member.key, member]));
  const allKeys = [...new Set([...fromByKey.keys(), ...toByKey.keys()])].sort(compareText);

  const addedMembers = [];
  const removedMembers = [];
  const modifiedMembers = [];
  const unchangedMembers = [];

  for (const key of allKeys) {
    const before = fromByKey.get(key) ?? null;
    const after = toByKey.get(key) ?? null;
    if (!before) {
      addedMembers.push(after);
    } else if (!after) {
      removedMembers.push(before);
    } else {
      const roleChanged = before.role !== after.role;
      const representationChanged = before.representation !== after.representation;
      const contentIdentityChanged = before.contentIdentity !== after.contentIdentity;
      if (roleChanged || representationChanged || contentIdentityChanged) {
        modifiedMembers.push(
          Object.freeze({
            key,
            before,
            after,
            roleChanged,
            representationChanged,
            contentIdentityChanged,
          }),
        );
      } else {
        unchangedMembers.push(after);
      }
    }
  }

  const depKey = (dep) => `${dep.projectId}\u0000${dep.releaseId}`;
  const fromDeps = new Map(from.dependencies.map((dep) => [depKey(dep), dep]));
  const toDeps = new Map(to.dependencies.map((dep) => [depKey(dep), dep]));
  const allDepKeys = [...new Set([...fromDeps.keys(), ...toDeps.keys()])].sort(compareText);
  const addedDependencies = [];
  const removedDependencies = [];
  for (const k of allDepKeys) {
    if (!fromDeps.has(k)) addedDependencies.push(toDeps.get(k));
    else if (!toDeps.has(k)) removedDependencies.push(fromDeps.get(k));
  }

  const profileChanged = from.profileId !== to.profileId;
  return Object.freeze({
    format: PROJECT_RELEASE_DIFF_V1,
    fromProjectId: from.projectId,
    toProjectId: to.projectId,
    fromReleaseId: from.releaseId,
    toReleaseId: to.releaseId,
    fromProfileId: from.profileId,
    toProfileId: to.profileId,
    profileChanged,
    identical: from.releaseId === to.releaseId,
    addedMembers: Object.freeze(addedMembers),
    removedMembers: Object.freeze(removedMembers),
    modifiedMembers: Object.freeze(modifiedMembers),
    unchangedMembers: Object.freeze(unchangedMembers),
    addedDependencies: Object.freeze(addedDependencies),
    removedDependencies: Object.freeze(removedDependencies),
  });
}

async function authorizedDiffProjects({
  images,
  fromImageId,
  fromProjectId,
  toImageId = fromImageId,
  toProjectId = fromProjectId,
  require,
} = {}) {
  requiredText(fromImageId, 'fromImageId');
  requiredText(fromProjectId, 'fromProjectId');
  requiredText(toImageId, 'toImageId');
  requiredText(toProjectId, 'toProjectId');
  if (typeof require !== 'function') {
    throw new TypeError('authorizedDiffProjects requires a require(demand) authority-check function');
  }

  const fromResource = objectResource(fromImageId, projectObjectId(fromProjectId));
  const toResource = objectResource(toImageId, projectObjectId(toProjectId));
  const resources =
    fromResource.imageId === toResource.imageId && fromResource.objectId === toResource.objectId
      ? [fromResource]
      : [fromResource, toResource].sort(
          (a, b) => compareText(a.imageId, b.imageId) || compareText(a.objectId, b.objectId),
        );

  for (const resource of resources) {
    require({operation: OBJECT_READ_OPERATION, resource});
  }

  const fromDescriptor = await readProjectDescriptor({
    images,
    imageId: fromImageId,
    projectId: fromProjectId,
  });
  const toDescriptor = await readProjectDescriptor({
    images,
    imageId: toImageId,
    projectId: toProjectId,
  });
  return diffProjectDescriptors(fromDescriptor, toDescriptor);
}

function assembleProjectDescriptorFromRecords(records, projectId) {
  const byId = new Map(records.map((record) => [record.id, record]));
  const idRef = projectObjectId(projectId);
  const project = byId.get(idRef);
  if (
    !project ||
    project.kind !== 'object' ||
    !isObjectRef(project.shape) ||
    project.shape.objectId !== PROJECT_SHAPE_ID ||
    project.slots?.['project-id']?.value !== projectId
  ) {
    throw new TypeError(`durable Project not found at requested frontier: ${idRef}`);
  }
  const memberRefs = Array.isArray(project.indexed) ? project.indexed : [];
  const members = [];
  for (const ref of memberRefs) {
    const member = byId.get(ref.objectId);
    if (!member) {
      throw new TypeError(`durable Project member not found at requested frontier: ${ref.objectId}`);
    }
    members.push({
      key: member.slots['project-member-key'].value,
      role: member.slots['project-member-role'].value,
      target: member.slots['project-member-target'],
    });
  }
  const namespace = project.slots['project-namespace'];
  return normalizeProjectDescriptor({
    format: 'lagrange-project/v1',
    projectId: project.slots['project-id'].value,
    name: project.slots['project-name'].value,
    namespace: isObjectRef(namespace) && namespace.objectId !== PROJECT_NONE_ID ? namespace : null,
    members,
  });
}

async function diffProjectAtFrontiers({
  images,
  imageId,
  projectId,
  fromFrontier,
  toFrontier,
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  const fromRecords = await reconstructImageRecordsAtFrontier({
    images,
    imageId,
    frontier: fromFrontier,
  });
  const toRecords = await reconstructImageRecordsAtFrontier({
    images,
    imageId,
    frontier: toFrontier,
  });
  const fromDescriptor = assembleProjectDescriptorFromRecords(fromRecords, projectId);
  const toDescriptor = assembleProjectDescriptorFromRecords(toRecords, projectId);
  const projectDiff = diffProjectDescriptors(fromDescriptor, toDescriptor);
  const frontierDiff = await diffImageFrontiers({
    images,
    imageId,
    fromFrontier,
    toFrontier,
  });
  return Object.freeze({
    projectDiff,
    frontierDiff,
  });
}

export {
  PROJECT_DESCRIPTOR_DIFF_V1,
  PROJECT_RELEASE_DIFF_V1,
  authorizedDiffProjects,
  diffProjectAtFrontiers,
  diffProjectDescriptors,
  diffProjectReleases,
};

import {
  assertGraphBundleV1,
  contentIdentityForBundle,
  exportGraphBundle,
  GRAPH_BUNDLE_V1,
} from '../graph/bundle.js';
import {normalizeProjectReleaseManifest} from './model.js';

// The graph release materializer (ADR 0075, Decisions 1–6): the ONE owner of
//
//   selected Project members -> portable graph release material.
//
// It ORCHESTRATES the existing owners and absorbs none of them: it receives the
// selected semantic members and a scoped {getRecord} read facade from the Project
// release-capture coordinator (never GraphImageService, a backend, a frontier or
// an authority surface), drives exactly ONE multi-root export through the graph
// bundle owner, and freezes the release-material package contract. It does NOT
// bracket frontiers (capture coordinator), walk durable edges itself (bundle
// owner), define manifest/releaseId semantics (Project model) or publish target
// records (GraphImageService.createRecords).

const PROJECT_RELEASE_MATERIAL_V1 = 'lagrange-project-release-material/v1';

class ProjectGraphReleaseMaterializationError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ProjectGraphReleaseMaterializationError';
    Object.assign(this, details);
  }
}

function fail(message, details) {
  throw new ProjectGraphReleaseMaterializationError(message, details);
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) fail(`${label} must be a non-empty string`);
  return value;
}

function isPlainMap(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Recursively freeze an isolated copy of the package material so later mutation
// cannot make `material.contentIdentity != contentIdentityForBundle(material.bundle)`.
function deepFreeze(value) {
  if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) deepFreeze(entry);
  }
  return Object.freeze(value);
}

// Canonical code-unit ordering for key-set comparisons.
function sortedKeys(map) {
  return Object.keys(map).sort();
}

// ADR 0075 Decisions 2–4: ONE multi-root export for the whole selection, fully
// closed. `reader` is the coordinator's scoped read facade; ONLY its getRecord is
// used — frontier/stability semantics never reach this module or the bundle
// owner. `members` are the selected semantic Project members ({key, role,
// target}); only their keys and targets are read — this module learns no role
// semantics.
async function materializeProjectGraphRelease({reader, members, crypto} = {}) {
  if (!reader || typeof reader.getRecord !== 'function') {
    fail('materializeProjectGraphRelease requires a scoped reader with getRecord');
  }
  if (!Array.isArray(members) || members.length === 0) {
    fail('materializeProjectGraphRelease requires a non-empty selected member list');
  }

  // The narrowness is by construction: the bundle owner's `images` seam is built
  // from the reader's getRecord and NOTHING else, even if the caller handed a
  // richer session object. No frontier, assertStable, frontierMap, createRecords,
  // backend, put* or authority method can leak through.
  const images = {getRecord: (imageId, objectId) => reader.getRecord(imageId, objectId)};

  // Decision 2: ONE multi-root export. Root labels are the Project member keys —
  // caller-owned opaque labels at the bundle boundary; the bundle owner never
  // learns they are Project member keys.
  const roots = {};
  for (const member of members) {
    if (isPlainMap(member) && typeof member.key === 'string' && member.key.length > 0) {
      if (Object.hasOwn(roots, member.key)) fail(`duplicate selected member key: ${member.key}`);
      roots[member.key] = member.target;
    } else {
      fail('selected members must carry a non-empty string key and a target ref');
    }
  }

  // Decision 4: fully closed portable material. EVERY unpinned ref is internal —
  // including cross-Image refs (the bundle owner's cross-Image-external DEFAULT is
  // deliberately not used for release material). Pinned refs remain
  // external-by-construction inside the bundle owner.
  const referencePolicy = {classify: () => 'internal'};

  const {bundle, contentIdentity} = await exportGraphBundle({images, roots, referencePolicy, crypto});

  // The executable proof that development Image/ObjectRef identity cannot enter
  // Project release identity through the graph bundle: externals MUST be empty.
  // A reachable pinned ref therefore fails the release loudly — it is NOT bound,
  // read, dropped or reclassified; there is no historical read and no
  // "source-bound release" category.
  if (Object.keys(bundle.externals).length !== 0) {
    fail(
      `Project graph release material is not fully closed: ${Object.keys(bundle.externals).length} external requirement(s) remain `
      + `(a reachable pinned ref is a hard v1 failure)`,
      {externals: bundle.externals},
    );
  }

  // Decision 3: EVERY selected member's materialization is the WHOLE-bundle
  // identity. Coarse-but-truthful manifest v1 identity — no per-root hashes, no
  // manifest v2. No source ObjectRefs appear in materializations.
  const materializations = {};
  for (const member of members) {
    materializations[member.key] = Object.freeze({
      representation: GRAPH_BUNDLE_V1,
      contentIdentity,
    });
  }

  return {bundle, contentIdentity, materializations};
}

// --- ProjectReleaseMaterial/v1 (ADR 0075 Decision 6) -----------------------------
// One immutable, content-addressed package per release, internally LINKED to the
// release (not merely colocated with it).

// Intrinsic validation: exact v1 fields, supported format, non-empty identity
// texts, the graph-bundle representation, a valid v1 bundle whose recomputed
// content identity MATCHES the package's, and empty externals.
function normalizeProjectReleaseMaterial(value, {crypto} = {}) {
  if (!isPlainMap(value)) fail('Project release material must be a plain object');
  const keys = Object.keys(value).sort();
  const expected = ['bundle', 'contentIdentity', 'format', 'projectId', 'releaseId', 'representation'];
  if (keys.join(',') !== expected.join(',')) {
    fail(`Project release material must have exactly the v1 fields {${expected.join(', ')}}; got {${keys.join(', ')}}`);
  }
  if (value.format !== PROJECT_RELEASE_MATERIAL_V1) {
    fail(`unsupported Project release material format: ${JSON.stringify(value.format)}`);
  }
  requiredText(value.projectId, 'Project release material projectId');
  requiredText(value.releaseId, 'Project release material releaseId');
  requiredText(value.contentIdentity, 'Project release material contentIdentity');
  if (value.representation !== GRAPH_BUNDLE_V1) {
    fail(`Project release material representation must be ${GRAPH_BUNDLE_V1}: ${JSON.stringify(value.representation)}`);
  }
  try {
    assertGraphBundleV1(value.bundle);
  } catch (error) {
    fail(`Project release material bundle is invalid: ${error.message}`, {cause: error});
  }
  if (Object.keys(value.bundle.externals).length !== 0) {
    fail('Project release material bundle must be fully closed (externals empty)');
  }
  const actual = contentIdentityForBundle(value.bundle, {crypto});
  if (actual !== value.contentIdentity) {
    fail(`Project release material contentIdentity does not match its bundle: declared ${value.contentIdentity}, actual ${actual}`);
  }
  return value;
}

// THE release <-> material linkage owner. Validates an ALREADY-SUPPLIED material
// package intrinsically AND against the release it claims to belong to, then
// returns an ISOLATED, DEEPLY FROZEN snapshot of that material. Both the capture
// constructor (createProjectReleaseMaterial) and the installation coordinator
// route through this ONE definition — linkage rules are never copied.
//
// The isolated snapshot matters: installation has an async import between
// validation and descriptor creation, and the caller must not be able to mutate a
// previously validated material object during that window.
function validateProjectReleaseMaterialForRelease({release, material, crypto} = {}) {
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  normalizeProjectReleaseMaterial(material, {crypto});

  // Release linkage: the package's identity fields match the release; EVERY
  // release member carries this representation and the whole-bundle identity; and
  // the bundle root-key set EXACTLY equals the release member-key set (canonical
  // code-unit comparison — no extra root, no missing root). This is the ADR 0075
  // Decision 8 property that makes a later installation's semantic-mismatch
  // failure impossible after import succeeds.
  if (material.projectId !== normalizedRelease.projectId) {
    fail(`material projectId ${JSON.stringify(material.projectId)} does not match the release projectId`);
  }
  if (material.releaseId !== normalizedRelease.releaseId) {
    fail(`material releaseId ${JSON.stringify(material.releaseId)} does not match the release releaseId`);
  }
  for (const member of normalizedRelease.members) {
    if (member.representation !== GRAPH_BUNDLE_V1) {
      fail(`release member ${member.key} representation ${JSON.stringify(member.representation)} does not match the material representation`);
    }
    if (member.contentIdentity !== material.contentIdentity) {
      fail(`release member ${member.key} contentIdentity does not match the material contentIdentity`);
    }
  }
  // Exact sequence equality after canonical sorting — NEVER a joined-string
  // comparison: member keys/root labels are arbitrary opaque text, so
  // concatenation is not injective (["ab","c"] and ["a","bc"] both join to "abc",
  // the same defect class PR #166 repaired for ObjectRef bookkeeping). A false
  // positive here would let malformed material pass preflight, commit the graph
  // import, and only then have createProjectInstallation reject the roots — an
  // orphan imported graph. Structural equality only.
  const rootKeys = sortedKeys(material.bundle.roots);
  const memberKeys = normalizedRelease.members.map(({key}) => key).sort();
  const sameKeySet = rootKeys.length === memberKeys.length
    && rootKeys.every((key, index) => key === memberKeys[index]);
  if (!sameKeySet) {
    fail('bundle root-key set must exactly equal the release member-key set');
  }

  // Isolate AND immobilize: the returned snapshot cannot be mutated into a state
  // where material.contentIdentity != contentIdentityForBundle(material.bundle),
  // and caller-side mutation of the original cannot race the async window.
  return deepFreeze(structuredClone(material));
}

// Construct + link: the candidate package is assembled from the release and then
// routed through THE SAME linked-validation owner — one definition of
// release<->material linkage.
function createProjectReleaseMaterial({release, bundle, contentIdentity, crypto} = {}) {
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  const candidate = {
    format: PROJECT_RELEASE_MATERIAL_V1,
    projectId: normalizedRelease.projectId,
    releaseId: normalizedRelease.releaseId,
    representation: GRAPH_BUNDLE_V1,
    contentIdentity,
    bundle,
  };
  return validateProjectReleaseMaterialForRelease({release: normalizedRelease, material: candidate, crypto});
}

export {
  GRAPH_BUNDLE_V1,
  PROJECT_RELEASE_MATERIAL_V1,
  ProjectGraphReleaseMaterializationError,
  createProjectReleaseMaterial,
  materializeProjectGraphRelease,
  normalizeProjectReleaseMaterial,
  validateProjectReleaseMaterialForRelease,
};

import {ensureShape} from '../graph/ensure-records.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {canonicalizeValue, isObjectRef, objectRef, textValue} from '../value/index.js';
import {PROJECT_INSTALLATION_V1, normalizeProjectInstallation} from './model.js';

// Durable ProjectInstallation/v1 storage translation (ADR 0076 Decisions 3, 4,
// 9, 10 and 12). These are ordinary target-Image Shapes and Objects. The stable
// head is the sole installation commit point; this owner never scans for or
// adopts a snapshot/member record that is not reachable from that head.

const PROJECT_INSTALLATION_HEAD_SHAPE_ID = 'lagrange-project-installation/head-shape/v1';
const PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID = 'lagrange-project-installation/snapshot-shape/v1';
const PROJECT_INSTALLATION_MEMBER_SHAPE_ID = 'lagrange-project-installation/member-shape/v1';

const SLOT = Object.freeze({
  projectId: 'installation-project-id',
  snapshot: 'installation-snapshot',
  releaseId: 'installation-release-id',
  memberKey: 'installation-member-key',
  role: 'installation-member-role',
  representation: 'installation-member-representation',
  contentIdentity: 'installation-member-content-identity',
  target: 'installation-member-target',
});

const INSTALLATION_SHAPES = Object.freeze([
  Object.freeze({
    id: PROJECT_INSTALLATION_HEAD_SHAPE_ID,
    slots: Object.freeze([
      Object.freeze({id: SLOT.projectId, name: 'projectId'}),
      Object.freeze({id: SLOT.snapshot, name: 'snapshot'}),
    ]),
    indexed: SHAPE_INDEXED.NONE,
  }),
  Object.freeze({
    id: PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID,
    slots: Object.freeze([
      Object.freeze({id: SLOT.projectId, name: 'projectId'}),
      Object.freeze({id: SLOT.releaseId, name: 'releaseId'}),
    ]),
    indexed: SHAPE_INDEXED.VALUES,
  }),
  Object.freeze({
    id: PROJECT_INSTALLATION_MEMBER_SHAPE_ID,
    slots: Object.freeze([
      Object.freeze({id: SLOT.memberKey, name: 'key'}),
      Object.freeze({id: SLOT.role, name: 'role'}),
      Object.freeze({id: SLOT.representation, name: 'representation'}),
      Object.freeze({id: SLOT.contentIdentity, name: 'contentIdentity'}),
      Object.freeze({id: SLOT.target, name: 'target'}),
    ]),
    indexed: SHAPE_INDEXED.NONE,
  }),
]);

class ProjectInstallationStateError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ProjectInstallationStateError';
    Object.assign(this, details);
  }
}

function fail(message, details) {
  throw new ProjectInstallationStateError(message, details);
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function requireImages(images, methods) {
  if (!images || typeof images !== 'object' || methods.some((method) => typeof images[method] !== 'function')) {
    throw new TypeError(`images must provide ${methods.join(' and ')}`);
  }
  return images;
}

function installationHeadObjectId(projectId) {
  return `lagrange-project-installation/${requiredText(projectId, 'projectId')}/head`;
}

// Admission goes through the ONE Shape ensure owner (graph/ensure-records.js); this translator
// contributes only its fixed definitions and its corruption taxonomy for a divergent occupant.
async function ensureOneShape(images, targetImageId, expected) {
  return await ensureShape(images, targetImageId, {
    id: expected.id,
    slots: expected.slots,
    ...(expected.indexed === SHAPE_INDEXED.VALUES ? {indexed: expected.indexed} : {}),
  }, {
    conflict: () => new ProjectInstallationStateError(`Project installation Shape ${expected.id} diverges from its fixed definition`),
  });
}

async function ensureInstallationShapes({images, targetImageId} = {}) {
  requireImages(images, ['getRecord', 'putShape']);
  requiredText(targetImageId, 'targetImageId');
  for (const shape of INSTALLATION_SHAPES) {
    // eslint-disable-next-line no-await-in-loop
    await ensureOneShape(images, targetImageId, shape);
  }
  return Object.freeze({
    headShape: objectRef(targetImageId, PROJECT_INSTALLATION_HEAD_SHAPE_ID),
    snapshotShape: objectRef(targetImageId, PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID),
    memberShape: objectRef(targetImageId, PROJECT_INSTALLATION_MEMBER_SHAPE_ID),
  });
}

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) deepFreeze(entry);
    Object.freeze(value);
  }
  return value;
}

function materializeInstallationSnapshotRecords({installation, provenance = null, crypto} = {}) {
  const normalized = normalizeProjectInstallation(installation);
  const activeCrypto = crypto ?? getDefaultCryptoProvider();
  if (!activeCrypto || typeof activeCrypto.uuid !== 'function') {
    throw new TypeError('crypto must provide uuid');
  }

  const memberRecords = normalized.members.map((member) => ({
    kind: 'object',
    id: requiredText(activeCrypto.uuid(), 'member record id'),
    shape: objectRef(normalized.targetImageId, PROJECT_INSTALLATION_MEMBER_SHAPE_ID),
    slots: {
      [SLOT.memberKey]: textValue(member.key),
      [SLOT.role]: textValue(member.role),
      [SLOT.representation]: textValue(member.representation),
      [SLOT.contentIdentity]: textValue(member.contentIdentity),
      [SLOT.target]: member.target,
    },
  }));
  const snapshotId = requiredText(activeCrypto.uuid(), 'snapshot record id');
  const snapshot = {
    kind: 'object',
    id: snapshotId,
    shape: objectRef(normalized.targetImageId, PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID),
    slots: {
      [SLOT.projectId]: textValue(normalized.projectId),
      [SLOT.releaseId]: textValue(normalized.releaseId),
    },
    indexed: memberRecords.map(({id}) => objectRef(normalized.targetImageId, id)),
    ...(provenance !== null && provenance !== undefined ? {metadata: {provenance}} : {}),
  };
  return deepFreeze({
    memberRecords,
    snapshot,
    snapshotRef: objectRef(normalized.targetImageId, snapshotId),
  });
}

function materializeInstallationRecords({installation, provenance = null, crypto} = {}) {
  // The Project model remains the semantic owner. This normalization validates
  // the caller's descriptor and supplies canonical member order; the translator
  // only maps that canonical meaning to ordinary record specs.
  const normalized = normalizeProjectInstallation(installation);
  const {memberRecords, snapshot, snapshotRef} = materializeInstallationSnapshotRecords({
    installation: normalized,
    provenance,
    crypto,
  });
  const head = {
    kind: 'object',
    id: installationHeadObjectId(normalized.projectId),
    shape: objectRef(normalized.targetImageId, PROJECT_INSTALLATION_HEAD_SHAPE_ID),
    slots: {
      [SLOT.projectId]: textValue(normalized.projectId),
      [SLOT.snapshot]: snapshotRef,
    },
  };
  return deepFreeze([...memberRecords, snapshot, head]);
}

function sameRef(value, imageId, objectId) {
  return isObjectRef(value) && value.imageId === imageId && value.objectId === objectId;
}

function requireStoredObject(record, {id, targetImageId, shapeId, slotIds, indexed}) {
  if (!record || record.kind !== 'object') fail(`Project installation object ${id} is malformed`);
  if (record.id !== id || record.imageId !== targetImageId) {
    fail(`Project installation object ${id} has inconsistent durable identity`);
  }
  if (!sameRef(record.shape, targetImageId, shapeId)) {
    fail(`Project installation object ${id} has the wrong Shape`);
  }
  if (record.behavior !== null) fail(`Project installation object ${id} must not have behavior`);
  const actualSlots = Object.keys(record.slots ?? {}).sort();
  const expectedSlots = [...slotIds].sort();
  if (actualSlots.length !== expectedSlots.length || actualSlots.some((slot, index) => slot !== expectedSlots[index])) {
    fail(`Project installation object ${id} has malformed slots`);
  }
  if (indexed) {
    if (!Array.isArray(record.indexed)) fail(`Project installation object ${id} has malformed indexed members`);
  } else if (Object.hasOwn(record, 'indexed')) {
    fail(`Project installation object ${id} must not have an indexed part`);
  }
  return record;
}

function requireStoredValue(value, label, kind) {
  let normalized;
  try {
    normalized = canonicalizeValue(value);
  } catch (cause) {
    fail(`${label} is malformed`, {cause});
  }
  if (normalized.kind !== kind) fail(`${label} is malformed`);
  return normalized;
}

function requireStoredText(value, label) {
  const normalized = requireStoredValue(value, label, 'text');
  if (normalized.value.length === 0) fail(`${label} is malformed`);
  return normalized.value;
}

function requireStoredRef(value, label, targetImageId) {
  const normalized = requireStoredValue(value, label, 'ref');
  if (normalized.imageId !== targetImageId) fail(`${label} must belong to target Image ${targetImageId}`);
  return normalized;
}

async function readManagedProjectInstallationState({images, targetImageId, projectId} = {}) {
  requireImages(images, ['getRecord']);
  requiredText(targetImageId, 'targetImageId');
  requiredText(projectId, 'projectId');

  const headId = installationHeadObjectId(projectId);
  const head = await images.getRecord(targetImageId, headId);
  if (!head) return null;
  requireStoredObject(head, {
    id: headId,
    targetImageId,
    shapeId: PROJECT_INSTALLATION_HEAD_SHAPE_ID,
    slotIds: [SLOT.projectId, SLOT.snapshot],
    indexed: false,
  });
  const headProjectId = requireStoredText(head.slots[SLOT.projectId], 'head projectId');
  if (headProjectId !== projectId) fail('head projectId does not match its stable head key');
  const snapshotRef = requireStoredRef(head.slots[SLOT.snapshot], 'head snapshot ref', targetImageId);

  const snapshot = await images.getRecord(targetImageId, snapshotRef.objectId);
  if (!snapshot) fail(`Project installation snapshot is missing: ${snapshotRef.objectId}`);
  requireStoredObject(snapshot, {
    id: snapshotRef.objectId,
    targetImageId,
    shapeId: PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID,
    slotIds: [SLOT.projectId, SLOT.releaseId],
    indexed: true,
  });
  const snapshotProjectId = requireStoredText(snapshot.slots[SLOT.projectId], 'snapshot projectId');
  if (snapshotProjectId !== headProjectId) fail('snapshot projectId does not match the stable head projectId');
  const releaseId = requireStoredText(snapshot.slots[SLOT.releaseId], 'snapshot releaseId');

  const members = [];
  for (const [index, storedRef] of snapshot.indexed.entries()) {
    const memberRef = requireStoredRef(storedRef, `snapshot member ref ${index}`, targetImageId);
    // eslint-disable-next-line no-await-in-loop
    const member = await images.getRecord(targetImageId, memberRef.objectId);
    if (!member) fail(`Project installation member is missing: ${memberRef.objectId}`);
    requireStoredObject(member, {
      id: memberRef.objectId,
      targetImageId,
      shapeId: PROJECT_INSTALLATION_MEMBER_SHAPE_ID,
      slotIds: [SLOT.memberKey, SLOT.role, SLOT.representation, SLOT.contentIdentity, SLOT.target],
      indexed: false,
    });
    members.push({
      key: requireStoredText(member.slots[SLOT.memberKey], `member ${index} key`),
      role: requireStoredText(member.slots[SLOT.role], `member ${index} role`),
      representation: requireStoredText(member.slots[SLOT.representation], `member ${index} representation`),
      contentIdentity: requireStoredText(member.slots[SLOT.contentIdentity], `member ${index} contentIdentity`),
      target: requireStoredValue(member.slots[SLOT.target], `member ${index} target`, 'ref'),
    });
  }

  let installation;
  try {
    installation = normalizeProjectInstallation({
      format: PROJECT_INSTALLATION_V1,
      projectId: headProjectId,
      releaseId,
      targetImageId,
      members,
    });
  } catch (cause) {
    fail(`Project installation state is invalid: ${cause.message}`, {cause});
  }

  const provenance =
    snapshot.metadata?.provenance !== undefined && snapshot.metadata?.provenance !== null
      ? deepFreeze(structuredClone(snapshot.metadata.provenance))
      : null;

  return Object.freeze({
    installation,
    descriptor: installation,
    headId: head.id,
    headVersion: head._version ?? null,
    snapshotId: snapshot.id,
    provenance,
  });
}

async function readManagedProjectInstallation({images, targetImageId, projectId} = {}) {
  const state = await readManagedProjectInstallationState({images, targetImageId, projectId});
  return state ? state.installation : null;
}

async function listManagedProjectInstallations({images, targetImageId} = {}) {
  requireImages(images, ['getRecord', 'listObjects']);
  requiredText(targetImageId, 'targetImageId');
  const objects = await images.listObjects(targetImageId);
  const installations = [];
  for (const obj of objects) {
    if (isObjectRef(obj.shape) && obj.shape.objectId === PROJECT_INSTALLATION_HEAD_SHAPE_ID) {
      const projectId = obj.slots?.[SLOT.projectId]?.value;
      if (typeof projectId === 'string' && projectId.length > 0 && obj.id === installationHeadObjectId(projectId)) {
        // eslint-disable-next-line no-await-in-loop
        const inst = await readManagedProjectInstallation({images, targetImageId, projectId});
        if (inst) installations.push(inst);
      }
    }
  }
  installations.sort((a, b) => (a.projectId < b.projectId ? -1 : a.projectId > b.projectId ? 1 : 0));
  return Object.freeze(installations);
}

export {
  PROJECT_INSTALLATION_HEAD_SHAPE_ID,
  PROJECT_INSTALLATION_MEMBER_SHAPE_ID,
  PROJECT_INSTALLATION_SNAPSHOT_SHAPE_ID,
  ProjectInstallationStateError,
  ensureInstallationShapes,
  installationHeadObjectId,
  listManagedProjectInstallations,
  materializeInstallationRecords,
  materializeInstallationSnapshotRecords,
  readManagedProjectInstallation,
  readManagedProjectInstallationState,
};

