  normalizeProjectReleaseManifest,
  planProjectUpgrade,
} from './model.js';

const PROJECT_INSTALLATION_PROVENANCE_V1 = 'lagrange-project-installation-provenance/v1';

// Managed Project installation coordinator (ADR 0076 Decisions 2, 4–9, 11 and
// 13). This is the ONE owner of lifecycle sequencing only. Graph translation,
// descriptor semantics, durable-state translation and atomic publication remain
// delegated to their existing owners.

class ManagedProjectInstallationError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ManagedProjectInstallationError';
    Object.assign(this, details);
  }
}

class ManagedProjectInstallationConflictError extends ManagedProjectInstallationError {
  constructor({targetImageId, projectId, currentReleaseId, desiredReleaseId}) {
    super(
      `managed Project ${projectId} in Image ${targetImageId} is at release ${currentReleaseId}; `
      + `desired release ${desiredReleaseId} requires upgrade`,
      {targetImageId, projectId, currentReleaseId, desiredReleaseId},
    );
    this.name = 'ManagedProjectInstallationConflictError';
  }
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new ManagedProjectInstallationError(`${label} must be a non-empty string`);
  }
  return value;
}

function requireImages(images) {
  const methods = ['getRecord', 'putShape', 'createRecords'];
  if (!images || typeof images !== 'object' || methods.some((method) => typeof images[method] !== 'function')) {
    throw new ManagedProjectInstallationError(`images must provide ${methods.join(', ')}`);
  }
  return images;
}

function decideExisting(existing, desiredRelease) {
  if (existing.releaseId === desiredRelease.releaseId) return existing;
  throw new ManagedProjectInstallationConflictError({
    targetImageId: existing.targetImageId,
    projectId: desiredRelease.projectId,
    currentReleaseId: existing.releaseId,
    desiredReleaseId: desiredRelease.releaseId,
  });
}

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) deepFreeze(entry);
    Object.freeze(value);
  }
  return value;
}

async function discoverReusableSubgraphBindings({
  images,
  desiredRelease,
  desiredBundle,
  candidateMembers = [],
  crypto,
} = {}) {
  const preboundLocalRefs = {};
  const reusedMemberKeys = [];
  const reusedInstallationMap = new Map();
  if (!Array.isArray(candidateMembers) || candidateMembers.length === 0) {
    return {preboundLocalRefs, reusedMemberKeys, reusedInstallations: []};
  }

  // Index candidate installed members by both (key) and (subBundle contentIdentity).
  const candidateExportsByKey = new Map();
  const candidateExportsByIdentity = new Map();
  for (const cand of candidateMembers) {
    // eslint-disable-next-line no-await-in-loop
    const exported = await exportGraphBundleWithSourceMap({
      images,
      roots: {root: cand.target},
      referencePolicy: {classify: () => 'internal'},
      crypto,
    });
    const entry = {
      ...exported,
      sourceProjectId: cand.sourceProjectId ?? null,
      sourceReleaseId: cand.sourceReleaseId ?? null,
    };
    if (!candidateExportsByKey.has(cand.key)) {
      candidateExportsByKey.set(cand.key, entry);
    }
    if (!candidateExportsByIdentity.has(exported.contentIdentity)) {
      candidateExportsByIdentity.set(exported.contentIdentity, entry);
    }
  }

  for (const member of desiredRelease.members) {
    const rootLocalId = desiredBundle.roots[member.key];
    // eslint-disable-next-line no-await-in-loop
    const desiredSub = await extractSubBundleFromBundle({
      bundle: desiredBundle,
      rootLocalId,
      rootKey: 'root',
      crypto,
    });

    // Prefer same-key candidate if its sub-bundle contentIdentity matches; otherwise fall back to any candidate with matching sub-bundle contentIdentity.
    const sameKeyCand = candidateExportsByKey.get(member.key);
    const matchingExport =
      sameKeyCand && sameKeyCand.contentIdentity === desiredSub.contentIdentity
        ? sameKeyCand
        : candidateExportsByIdentity.get(desiredSub.contentIdentity) ?? null;

    if (matchingExport) {
      reusedMemberKeys.push(member.key);
      if (matchingExport.sourceProjectId && matchingExport.sourceReleaseId) {
        const instKey = `${matchingExport.sourceProjectId}:${matchingExport.sourceReleaseId}`;
        reusedInstallationMap.set(instKey, {
          projectId: matchingExport.sourceProjectId,
          releaseId: matchingExport.sourceReleaseId,
        });
      }
      for (const [subLocalId, bundleLocalId] of Object.entries(desiredSub.subLocalToBundleLocal)) {
        if (!Object.hasOwn(preboundLocalRefs, bundleLocalId)) {
          preboundLocalRefs[bundleLocalId] = matchingExport.localToSourceRef[subLocalId];
        }
      }
    }
  }

  const reusedInstallations = [...reusedInstallationMap.values()].sort((a, b) =>
    a.projectId < b.projectId ? -1 : a.projectId > b.projectId ? 1 : 0,
  );
  return {preboundLocalRefs, reusedMemberKeys, reusedInstallations};
}

async function installManagedProjectRelease({
  images,
  targetImageId,
  release,
  material,
  reuseExistingInstallations = false,
  provenance = null,
  crypto,
} = {}) {
  requireImages(images);
  requiredText(targetImageId, 'targetImageId');

  // Complete semantic preflight before any target-side write. The existing
  // owners isolate and freeze both inputs, so caller mutation cannot race the
  // later preparation/publication window.
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  const validatedMaterial = validateProjectReleaseMaterialForRelease({
    release: normalizedRelease,
    material,
    crypto,
  });

  // The deterministic head is the sole installation witness. Existing state
  // short-circuits before Shape bootstrap, id minting or publication.
  const existing = await readManagedProjectInstallation({
    images,
    targetImageId,
    projectId: normalizedRelease.projectId,
  });
  if (existing) return decideExisting(existing, normalizedRelease);

  // Shapes are harmless schema, never installation state. Their owner handles
  // concurrent bootstrap and fixed-definition divergence.
  await ensureInstallationShapes({images, targetImageId});

  let preboundLocalRefs = {};
  let reusedMemberKeys = [];
  let reusedInstallations = [];
  if (reuseExistingInstallations && typeof images.listObjects === 'function') {
    const otherInstallations = await listManagedProjectInstallations({images, targetImageId});
    const candidateMembers = otherInstallations.flatMap((inst) =>
      inst.members.map((m) => ({
        ...m,
        sourceProjectId: inst.projectId,
        sourceReleaseId: inst.releaseId,
      })),
    );
    const discovered = await discoverReusableSubgraphBindings({
      images,
      desiredRelease: normalizedRelease,
      desiredBundle: validatedMaterial.bundle,
      candidateMembers,
      crypto,
    });
    preboundLocalRefs = discovered.preboundLocalRefs;
    reusedMemberKeys = discovered.reusedMemberKeys;
    reusedInstallations = discovered.reusedInstallations;
  }

  // One shared graph owner prepares fresh ids/refs without durable effect.
  const plan = await prepareGraphBundleImport({
    images,
    targetImageId,
    bundle: validatedMaterial.bundle,
    expectedContentIdentity: validatedMaterial.contentIdentity,
    preboundLocalRefs,
    crypto,
  });
  const installation = createProjectInstallation({
    release: normalizedRelease,
    targetImageId,
    targets: plan.roots,
  });
  const totalBundleRecords = Object.keys(validatedMaterial.bundle.records).length;
  const installationProvenance =
    provenance !== null || reuseExistingInstallations
      ? deepFreeze({
          format: PROJECT_INSTALLATION_PROVENANCE_V1,
          operation: 'install',
          projectId: normalizedRelease.projectId,
          targetImageId,
          fromReleaseId: null,
          toReleaseId: normalizedRelease.releaseId,
          sourceReleaseProvenance: provenance ? structuredClone(provenance) : null,
          reusedMemberKeys: [...reusedMemberKeys].sort(),
          replacedMemberKeys: [],
          installedMemberKeys: normalizedRelease.members
            .map((m) => m.key)
            .filter((k) => !reusedMemberKeys.includes(k)),
          importedMemberKeys: normalizedRelease.members
            .map((m) => m.key)
            .filter((k) => !reusedMemberKeys.includes(k))
            .sort(),
          detachedMemberKeys: [],
          reusedInstallations,
          reusedRecordCount: totalBundleRecords - plan.recordInputs.length,
          createdRecordCount: plan.recordInputs.length,
        })
      : null;
  const installationRecords = materializeInstallationRecords({
    installation,
    provenance: installationProvenance,
    crypto,
  });

  // The sole installation effect: graph + members + snapshot + deterministic
  // head are insert-only candidates in ONE createRecords transaction. Only a
  // conflict on that exact head key is an install race; every other collision or
  // failure propagates unchanged and the batch owner guarantees zero partials.
  try {
    await images.createRecords(targetImageId, [...plan.recordInputs, ...installationRecords]);
  } catch (error) {
    const headId = installationHeadObjectId(normalizedRelease.projectId);
    if (!(error instanceof VersionConflictError) || error.key !== headId) throw error;
    const winner = await readManagedProjectInstallation({
      images,
      targetImageId,
      projectId: normalizedRelease.projectId,
    });
    if (!winner) {
      throw new ManagedProjectInstallationError(
        `managed Project head ${headId} conflicted but no committed installation can be read`,
        {cause: error, targetImageId, projectId: normalizedRelease.projectId},
      );
    }
    return decideExisting(winner, normalizedRelease);
  }

  return installation;
}

async function upgradeManagedProjectRelease({
  images,
  targetImageId,
  release,
  material,
  expectedReleaseId = null,
  reuseUnchangedMembers = true,
  reuseAcrossInstallations = false,
  provenance = null,
  crypto,
} = {}) {
  requireImages(images);
  if (typeof images.putObject !== 'function') {
    throw new ManagedProjectInstallationError('images must provide putObject for upgradeManagedProjectRelease');
  }
  requiredText(targetImageId, 'targetImageId');
  if (expectedReleaseId !== null && expectedReleaseId !== undefined) {
    requiredText(expectedReleaseId, 'expectedReleaseId');
  }

  const normalizedRelease = normalizeProjectReleaseManifest(release);
  const validatedMaterial = validateProjectReleaseMaterialForRelease({
    release: normalizedRelease,
    material,
    crypto,
  });

  const existingState = await readManagedProjectInstallationState({
    images,
    targetImageId,
    projectId: normalizedRelease.projectId,
  });
  if (!existingState) {
    throw new ManagedProjectInstallationError(
      `cannot upgrade absent managed Project ${normalizedRelease.projectId} in Image ${targetImageId}`,
      {targetImageId, projectId: normalizedRelease.projectId},
    );
  }

  if (
    expectedReleaseId !== null
    && expectedReleaseId !== undefined
    && existingState.installation.releaseId !== expectedReleaseId
  ) {
    throw new ManagedProjectInstallationConflictError({
      targetImageId,
      projectId: normalizedRelease.projectId,
      currentReleaseId: existingState.installation.releaseId,
      desiredReleaseId: expectedReleaseId,
    });
  }

  const reconciliation = planProjectUpgrade({
    installation: existingState.installation,
    nextRelease: normalizedRelease,
  });

  if (existingState.installation.releaseId === normalizedRelease.releaseId) {
    const memberKeys = existingState.installation.members.map((m) => m.key);
    return deepFreeze({
      installation: existingState.installation,
      reconciliation,
      upgraded: false,
      previousReleaseId: existingState.installation.releaseId,
      reusedMemberKeys: memberKeys,
      replacedMemberKeys: [],
      installedMemberKeys: [],
      importedMemberKeys: [],
      detachedMemberKeys: [],
      reusedRecordCount: Object.keys(validatedMaterial.bundle.records).length,
      createdRecordCount: 0,
      provenance: existingState.provenance,
    });
  }

  await ensureInstallationShapes({images, targetImageId});

  let preboundLocalRefs = {};
  let reusedMemberKeys = [];
  let reusedInstallations = [];
  if (reuseUnchangedMembers) {
    const candidateMembers = existingState.installation.members.map((m) => ({
      ...m,
      sourceProjectId: existingState.installation.projectId,
      sourceReleaseId: existingState.installation.releaseId,
    }));
    if (reuseAcrossInstallations && typeof images.listObjects === 'function') {
      const allInstallations = await listManagedProjectInstallations({images, targetImageId});
      for (const inst of allInstallations) {
        if (inst.projectId !== normalizedRelease.projectId) {
          for (const m of inst.members) {
            candidateMembers.push({
              ...m,
              sourceProjectId: inst.projectId,
              sourceReleaseId: inst.releaseId,
            });
          }
        }
      }
    }
    const discovered = await discoverReusableSubgraphBindings({
      images,
      desiredRelease: normalizedRelease,
      desiredBundle: validatedMaterial.bundle,
      candidateMembers,
      crypto,
    });
    preboundLocalRefs = discovered.preboundLocalRefs;
    reusedMemberKeys = discovered.reusedMemberKeys;
    reusedInstallations = discovered.reusedInstallations;
  }

  const plan = await prepareGraphBundleImport({
    images,
    targetImageId,
    bundle: validatedMaterial.bundle,
    expectedContentIdentity: validatedMaterial.contentIdentity,
    preboundLocalRefs,
    crypto,
  });

  const installation = createProjectInstallation({
    release: normalizedRelease,
    targetImageId,
    targets: plan.roots,
  });

  const totalBundleRecords = Object.keys(validatedMaterial.bundle.records).length;
  const reusedSet = new Set(reusedMemberKeys);
  const replacedMemberKeys = reconciliation.actions
    .filter((a) => (a.kind === 'replace' || a.kind === 'retain') && !reusedSet.has(a.key))
    .map((a) => a.key);
  const installedMemberKeys = reconciliation.actions
    .filter((a) => a.kind === 'install' && !reusedSet.has(a.key))
    .map((a) => a.key);
  const importedMemberKeys = [...replacedMemberKeys, ...installedMemberKeys].sort();
  const detachedMemberKeys = reconciliation.actions
    .filter((a) => a.kind === 'detach')
    .map((a) => a.key);
  const reusedRecordCount = totalBundleRecords - plan.recordInputs.length;
  const createdRecordCount = plan.recordInputs.length;

  const installationProvenance = deepFreeze({
    format: PROJECT_INSTALLATION_PROVENANCE_V1,
    operation: 'upgrade',
    projectId: normalizedRelease.projectId,
    targetImageId,
    previousReleaseId: existingState.installation.releaseId,
    fromReleaseId: existingState.installation.releaseId,
    toReleaseId: normalizedRelease.releaseId,
    sourceReleaseProvenance: provenance ? structuredClone(provenance) : null,
    reusedMemberKeys: [...reusedMemberKeys].sort(),
    replacedMemberKeys,
    installedMemberKeys,
    importedMemberKeys,
    detachedMemberKeys,
    reusedInstallations,
    reusedRecordCount,
    createdRecordCount,
  });

  const {memberRecords, snapshot, snapshotRef} = materializeInstallationSnapshotRecords({
    installation,
    provenance: installationProvenance,
    crypto,
  });

  // 1. Atomically publish any new graph records + the new installation member and snapshot records.
  // Until the deterministic head is updated below, these records are unreachable from the head.
  await images.createRecords(targetImageId, [...plan.recordInputs, ...memberRecords, snapshot]);

  // 2. Atomically advance the deterministic head via CAS at expectedVersion: existingState.headVersion.
  try {
    await images.putObject(
      targetImageId,
      {
        id: existingState.headId,
        shape: objectRef(targetImageId, PROJECT_INSTALLATION_HEAD_SHAPE_ID),
        behavior: null,
        slots: {
          'installation-project-id': textValue(normalizedRelease.projectId),
          'installation-snapshot': snapshotRef,
        },
      },
      {expectedVersion: existingState.headVersion},
    );
  } catch (error) {
    if (!(error instanceof VersionConflictError)) throw error;
    const winner = await readManagedProjectInstallationState({
      images,
      targetImageId,
      projectId: normalizedRelease.projectId,
    });
    if (winner && winner.installation.releaseId === normalizedRelease.releaseId) {
      return deepFreeze({
        installation: winner.installation,
        reconciliation,
        upgraded: false,
        previousReleaseId: existingState.installation.releaseId,
        reusedMemberKeys,
        replacedMemberKeys,
        installedMemberKeys,
        importedMemberKeys,
        detachedMemberKeys,
        reusedRecordCount,
        createdRecordCount,
        provenance: winner.provenance,
      });
    }
    throw new ManagedProjectInstallationConflictError({
      targetImageId,
      projectId: normalizedRelease.projectId,
      currentReleaseId: winner?.installation?.releaseId ?? existingState.installation.releaseId,
      desiredReleaseId: normalizedRelease.releaseId,
    });
  }

  return deepFreeze({
    installation,
    reconciliation,
    upgraded: true,
    previousReleaseId: existingState.installation.releaseId,
    reusedMemberKeys: [...reusedMemberKeys].sort(),
    replacedMemberKeys,
    installedMemberKeys,
    importedMemberKeys,
    detachedMemberKeys,
    reusedRecordCount,
    createdRecordCount,
    provenance: installationProvenance,
  });
}

async function authorizedUpgradeManagedProjectRelease({
  authority,
  authorityContext,
  images,
  targetImageId,
  release,
  material,
  expectedReleaseId = null,
  reuseUnchangedMembers = true,
  reuseAcrossInstallations = false,
  provenance = null,
  require,
  crypto,
} = {}) {
  requireImages(images);
  if (typeof images.putObject !== 'function') {
    throw new ManagedProjectInstallationError('images must provide putObject for authorizedUpgradeManagedProjectRelease');
  }
  requiredText(targetImageId, 'targetImageId');
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  validateProjectReleaseMaterialForRelease({
    release: normalizedRelease,
    material,
    crypto,
  });

  const headResource = objectResource(targetImageId, installationHeadObjectId(normalizedRelease.projectId));
  if (typeof require === 'function') {
    if (require.length >= 2) {
      require(OBJECT_WRITE_OPERATION, headResource);
    } else {
      require({operation: OBJECT_WRITE_OPERATION, resource: headResource});
    }
  } else if (authority && typeof authority.require === 'function') {
    authority.require(authorityContext, {
      operation: OBJECT_WRITE_OPERATION,
      resource: headResource,
    });
  } else {
    throw new TypeError(
      'authorizedUpgradeManagedProjectRelease requires either a require function or {authority, authorityContext}',
    );
  }

  return await upgradeManagedProjectRelease({
    images,
    targetImageId,
    release: normalizedRelease,
    material,
    expectedReleaseId,
    reuseUnchangedMembers,
    reuseAcrossInstallations,
    provenance,
    crypto,
  });
}

export {
  ManagedProjectInstallationConflictError,
  ManagedProjectInstallationError,
  PROJECT_INSTALLATION_PROVENANCE_V1,
  authorizedUpgradeManagedProjectRelease,
  installManagedProjectRelease,
  upgradeManagedProjectRelease,
};

import {OBJECT_READ_OPERATION, objectResource} from '../authority/object-resource.js';
import {reconstructImageRecordsAtFrontier} from '../graph/diff.js';
import {mergeImageFrontiers} from '../graph/merge.js';
import {isObjectRef, objectRef} from '../value/index.js';
import {normalizeProjectDescriptor, normalizeProjectReleaseManifest} from './model.js';
import {PROJECT_SHAPE_ID, projectObjectId, readProjectDescriptor} from './working-state.js';

const PROJECT_DESCRIPTOR_MERGE_V1 = 'lagrange-project-descriptor-merge/v1';
const PROJECT_RELEASE_MERGE_V1 = 'lagrange-project-release-merge/v1';
const PROJECT_NONE_ID = 'lagrange-project/none/v1';

const PROJECT_MERGE_CONFLICT_KINDS = Object.freeze({
  PROJECT_ID_MISMATCH: 'project-id-mismatch',
  NAME_CONFLICT: 'name-conflict',
  NAMESPACE_CONFLICT: 'namespace-conflict',
  MEMBER_ADD_ADD_CONFLICT: 'member-add-add-conflict',
  MEMBER_DELETE_MODIFY_CONFLICT: 'member-delete-modify-conflict',
  MEMBER_MODIFY_CONFLICT: 'member-modify-conflict',
  PROFILE_CONFLICT: 'profile-conflict',
  DEPENDENCY_VERSION_CONFLICT: 'dependency-version-conflict',
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-negative non-empty string`);
  }
  return value;
}

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function sameRef(a, b, {ignoreImageId = false} = {}) {
  if (a === null && b === null) return true;
  if (!isObjectRef(a) || !isObjectRef(b)) return false;
  if (ignoreImageId) return a.objectId === b.objectId;
  return a.imageId === b.imageId && a.objectId === b.objectId;
}

function rehomeRef(ref, targetImageId) {
  if (!ref || !isObjectRef(ref) || !targetImageId) return ref;
  return objectRef(targetImageId, ref.objectId);
}

function rehomeMember(member, targetImageId) {
  if (!member || !targetImageId) return member;
  return Object.freeze({
    key: member.key,
    role: member.role,
    target: rehomeRef(member.target, targetImageId),
  });
}

function membersEqual(a, b, {ignoreImageId = false} = {}) {
  if (!a && !b) return true;
  if (!a || !b) return false;
  return a.role === b.role && sameRef(a.target, b.target, {ignoreImageId});
}

function mergeProjectDescriptors(
  baseProject,
  leftProject,
  rightProject,
  {targetImageId = null, ignoreImageId = false, resolutions = {}} = {},
) {
  const base = normalizeProjectDescriptor(baseProject);
  const left = normalizeProjectDescriptor(leftProject);
  const right = normalizeProjectDescriptor(rightProject);

  const conflicts = [];
  const nameResolution = resolutions?.name;
  const namespaceResolution = resolutions?.namespace;
  const memberResolutions = resolutions?.members ?? {};

  if (base.projectId !== left.projectId || base.projectId !== right.projectId) {
    conflicts.push(
      Object.freeze({
        conflictKind: PROJECT_MERGE_CONFLICT_KINDS.PROJECT_ID_MISMATCH,
        base: base.projectId,
        left: left.projectId,
        right: right.projectId,
      }),
    );
  }

  // 1. Three-way merge Project name
  let mergedName = base.name;
  if (left.name === base.name) {
    mergedName = right.name;
  } else if (right.name === base.name || left.name === right.name) {
    mergedName = left.name;
  } else if (nameResolution === 'left') {
    mergedName = left.name;
  } else if (nameResolution === 'right') {
    mergedName = right.name;
  } else if (typeof nameResolution === 'string' && nameResolution.length > 0) {
    mergedName = nameResolution;
  } else {
    conflicts.push(
      Object.freeze({
        conflictKind: PROJECT_MERGE_CONFLICT_KINDS.NAME_CONFLICT,
        base: base.name,
        left: left.name,
        right: right.name,
      }),
    );
  }

  // 2. Three-way merge Project namespace
  let mergedNamespace = rehomeRef(base.namespace, targetImageId);
  const leftNsUnchanged = sameRef(left.namespace, base.namespace, {ignoreImageId});
  const rightNsUnchanged = sameRef(right.namespace, base.namespace, {ignoreImageId});
  const leftNsEqualsRight = sameRef(left.namespace, right.namespace, {ignoreImageId});
  if (leftNsUnchanged) {
    mergedNamespace = rehomeRef(right.namespace, targetImageId);
  } else if (rightNsUnchanged || leftNsEqualsRight) {
    mergedNamespace = rehomeRef(left.namespace, targetImageId);
  } else if (namespaceResolution === 'left') {
    mergedNamespace = rehomeRef(left.namespace, targetImageId);
  } else if (namespaceResolution === 'right') {
    mergedNamespace = rehomeRef(right.namespace, targetImageId);
  } else {
    conflicts.push(
      Object.freeze({
        conflictKind: PROJECT_MERGE_CONFLICT_KINDS.NAMESPACE_CONFLICT,
        base: base.namespace,
        left: left.namespace,
        right: right.namespace,
      }),
    );
  }

  // 3. Three-way merge Project members by member.key
  const baseByKey = new Map(base.members.map((m) => [m.key, m]));
  const leftByKey = new Map(left.members.map((m) => [m.key, m]));
  const rightByKey = new Map(right.members.map((m) => [m.key, m]));
  const allKeys = [
    ...new Set([...baseByKey.keys(), ...leftByKey.keys(), ...rightByKey.keys()]),
  ].sort(compareText);

  const mergedMembers = [];
  const memberChanges = [];

  for (const key of allKeys) {
    const bMem = baseByKey.get(key) ?? null;
    const lMem = leftByKey.get(key) ?? null;
    const rMem = rightByKey.get(key) ?? null;
    const resolution = Object.hasOwn(memberResolutions, key) ? memberResolutions[key] : undefined;

    if (!bMem) {
      if (lMem && !rMem) {
        const m = rehomeMember(lMem, targetImageId);
        mergedMembers.push(m);
        memberChanges.push(Object.freeze({key, action: 'added-left', member: m}));
        continue;
      }
      if (!lMem && rMem) {
        const m = rehomeMember(rMem, targetImageId);
        mergedMembers.push(m);
        memberChanges.push(Object.freeze({key, action: 'added-right', member: m}));
        continue;
      }
      if (lMem && rMem) {
        if (membersEqual(lMem, rMem, {ignoreImageId})) {
          const m = rehomeMember(lMem, targetImageId);
          mergedMembers.push(m);
          memberChanges.push(Object.freeze({key, action: 'added-both', member: m}));
          continue;
        }
        if (resolution === 'left') {
          const m = rehomeMember(lMem, targetImageId);
          mergedMembers.push(m);
          memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
        } else if (resolution === 'right') {
          const m = rehomeMember(rMem, targetImageId);
          mergedMembers.push(m);
          memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
        } else {
          conflicts.push(
            Object.freeze({
              conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_ADD_ADD_CONFLICT,
              key,
              base: null,
              left: lMem,
              right: rMem,
            }),
          );
        }
      }
      continue;
    }

    if (!lMem && !rMem) {
      memberChanges.push(Object.freeze({key, action: 'removed-both', member: null}));
      continue;
    }

    if (!lMem && rMem) {
      if (membersEqual(rMem, bMem, {ignoreImageId})) {
        memberChanges.push(Object.freeze({key, action: 'removed-left', member: null}));
        continue;
      }
      if (resolution === 'left') {
        memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: null}));
      } else if (resolution === 'right') {
        const m = rehomeMember(rMem, targetImageId);
        mergedMembers.push(m);
        memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_DELETE_MODIFY_CONFLICT,
            key,
            deletedSide: 'left',
            modifiedSide: 'right',
            base: bMem,
            left: null,
            right: rMem,
          }),
        );
        mergedMembers.push(rehomeMember(bMem, targetImageId));
      }
      continue;
    }

    if (lMem && !rMem) {
      if (membersEqual(lMem, bMem, {ignoreImageId})) {
        memberChanges.push(Object.freeze({key, action: 'removed-right', member: null}));
        continue;
      }
      if (resolution === 'right') {
        memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: null}));
      } else if (resolution === 'left') {
        const m = rehomeMember(lMem, targetImageId);
        mergedMembers.push(m);
        memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_DELETE_MODIFY_CONFLICT,
            key,
            deletedSide: 'right',
            modifiedSide: 'left',
            base: bMem,
            left: lMem,
            right: null,
          }),
        );
        mergedMembers.push(rehomeMember(bMem, targetImageId));
      }
      continue;
    }

    // Present in base, left, and right
    const lUnchanged = membersEqual(lMem, bMem, {ignoreImageId});
    const rUnchanged = membersEqual(rMem, bMem, {ignoreImageId});
    const lrEqual = membersEqual(lMem, rMem, {ignoreImageId});

    if (lUnchanged && rUnchanged) {
      mergedMembers.push(rehomeMember(bMem, targetImageId));
      continue;
    }
    if (lUnchanged) {
      const m = rehomeMember(rMem, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'modified-right', member: m}));
      continue;
    }
    if (rUnchanged) {
      const m = rehomeMember(lMem, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'modified-left', member: m}));
      continue;
    }
    if (lrEqual) {
      const m = rehomeMember(lMem, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'modified-both-identical', member: m}));
      continue;
    }

    // Both modified: check if one side changed role and the other changed target
    const lRoleUnchanged = lMem.role === bMem.role;
    const rRoleUnchanged = rMem.role === bMem.role;
    const lrRoleSame = lMem.role === rMem.role;
    const roleConflict = !lRoleUnchanged && !rRoleUnchanged && !lrRoleSame;

    const lTargetUnchanged = sameRef(lMem.target, bMem.target, {ignoreImageId});
    const rTargetUnchanged = sameRef(rMem.target, bMem.target, {ignoreImageId});
    const lrTargetSame = sameRef(lMem.target, rMem.target, {ignoreImageId});
    const targetConflict = !lTargetUnchanged && !rTargetUnchanged && !lrTargetSame;

    if (!roleConflict && !targetConflict) {
      const mergedRole = lRoleUnchanged ? rMem.role : lMem.role;
      const mergedTarget = lTargetUnchanged ? rMem.target : lMem.target;
      const m = rehomeMember({key, role: mergedRole, target: mergedTarget}, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'merged-member', member: m}));
      continue;
    }

    if (resolution === 'left') {
      const m = rehomeMember(lMem, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
    } else if (resolution === 'right') {
      const m = rehomeMember(rMem, targetImageId);
      mergedMembers.push(m);
      memberChanges.push(Object.freeze({key, action: 'resolved-conflict', member: m}));
    } else {
      conflicts.push(
        Object.freeze({
          conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_MODIFY_CONFLICT,
          key,
          base: bMem,
          left: lMem,
          right: rMem,
          roleConflict,
          targetConflict,
        }),
      );
      mergedMembers.push(rehomeMember(bMem, targetImageId));
    }
  }

  const mergedDescriptor = normalizeProjectDescriptor({
    format: 'lagrange-project/v1',
    projectId: base.projectId,
    name: mergedName,
    namespace: mergedNamespace,
    members: mergedMembers,
  });

  return Object.freeze({
    format: PROJECT_DESCRIPTOR_MERGE_V1,
    projectId: base.projectId,
    clean: conflicts.length === 0,
    mergedDescriptor,
    memberChanges: Object.freeze(memberChanges),
    conflicts: Object.freeze(conflicts),
  });
}

function releaseMembersEqual(a, b) {
  if (!a && !b) return true;
  if (!a || !b) return false;
  return (
    a.role === b.role &&
    a.representation === b.representation &&
    a.contentIdentity === b.contentIdentity
  );
}

function mergeProjectReleases(baseRelease, leftRelease, rightRelease) {
  const base = normalizeProjectReleaseManifest(baseRelease);
  const left = normalizeProjectReleaseManifest(leftRelease);
  const right = normalizeProjectReleaseManifest(rightRelease);

  const conflicts = [];

  if (base.projectId !== left.projectId || base.projectId !== right.projectId) {
    conflicts.push(
      Object.freeze({
        conflictKind: PROJECT_MERGE_CONFLICT_KINDS.PROJECT_ID_MISMATCH,
        base: base.projectId,
        left: left.projectId,
        right: right.projectId,
      }),
    );
  }

  let mergedProfileId = base.profileId;
  if (left.profileId === base.profileId) {
    mergedProfileId = right.profileId;
  } else if (right.profileId === base.profileId || left.profileId === right.profileId) {
    mergedProfileId = left.profileId;
  } else {
    conflicts.push(
      Object.freeze({
        conflictKind: PROJECT_MERGE_CONFLICT_KINDS.PROFILE_CONFLICT,
        base: base.profileId,
        left: left.profileId,
        right: right.profileId,
      }),
    );
  }

  const baseByKey = new Map(base.members.map((m) => [m.key, m]));
  const leftByKey = new Map(left.members.map((m) => [m.key, m]));
  const rightByKey = new Map(right.members.map((m) => [m.key, m]));
  const allKeys = [
    ...new Set([...baseByKey.keys(), ...leftByKey.keys(), ...rightByKey.keys()]),
  ].sort(compareText);

  const mergedMembers = [];
  const memberChanges = [];

  for (const key of allKeys) {
    const bMem = baseByKey.get(key) ?? null;
    const lMem = leftByKey.get(key) ?? null;
    const rMem = rightByKey.get(key) ?? null;

    if (!bMem) {
      if (lMem && !rMem) {
        mergedMembers.push(lMem);
        memberChanges.push(Object.freeze({key, action: 'added-left', member: lMem}));
      } else if (!lMem && rMem) {
        mergedMembers.push(rMem);
        memberChanges.push(Object.freeze({key, action: 'added-right', member: rMem}));
      } else if (lMem && rMem) {
        if (releaseMembersEqual(lMem, rMem)) {
          mergedMembers.push(lMem);
          memberChanges.push(Object.freeze({key, action: 'added-both', member: lMem}));
        } else {
          conflicts.push(
            Object.freeze({
              conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_ADD_ADD_CONFLICT,
              key,
              base: null,
              left: lMem,
              right: rMem,
            }),
          );
        }
      }
      continue;
    }

    if (!lMem && !rMem) {
      memberChanges.push(Object.freeze({key, action: 'removed-both', member: null}));
      continue;
    }
    if (!lMem && rMem) {
      if (releaseMembersEqual(rMem, bMem)) {
        memberChanges.push(Object.freeze({key, action: 'removed-left', member: null}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_DELETE_MODIFY_CONFLICT,
            key,
            deletedSide: 'left',
            modifiedSide: 'right',
            base: bMem,
            left: null,
            right: rMem,
          }),
        );
        mergedMembers.push(bMem);
      }
      continue;
    }
    if (lMem && !rMem) {
      if (releaseMembersEqual(lMem, bMem)) {
        memberChanges.push(Object.freeze({key, action: 'removed-right', member: null}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_DELETE_MODIFY_CONFLICT,
            key,
            deletedSide: 'right',
            modifiedSide: 'left',
            base: bMem,
            left: lMem,
            right: null,
          }),
        );
        mergedMembers.push(bMem);
      }
      continue;
    }

    const lUnchanged = releaseMembersEqual(lMem, bMem);
    const rUnchanged = releaseMembersEqual(rMem, bMem);
    const lrEqual = releaseMembersEqual(lMem, rMem);

    if (lUnchanged && rUnchanged) {
      mergedMembers.push(bMem);
    } else if (lUnchanged) {
      mergedMembers.push(rMem);
      memberChanges.push(Object.freeze({key, action: 'modified-right', member: rMem}));
    } else if (rUnchanged) {
      mergedMembers.push(lMem);
      memberChanges.push(Object.freeze({key, action: 'modified-left', member: lMem}));
    } else if (lrEqual) {
      mergedMembers.push(lMem);
      memberChanges.push(Object.freeze({key, action: 'modified-both-identical', member: lMem}));
    } else {
      conflicts.push(
        Object.freeze({
          conflictKind: PROJECT_MERGE_CONFLICT_KINDS.MEMBER_MODIFY_CONFLICT,
          key,
          base: bMem,
          left: lMem,
          right: rMem,
        }),
      );
      mergedMembers.push(bMem);
    }
  }

  // Merge dependencies by projectId
  const baseDeps = new Map(base.dependencies.map((d) => [d.projectId, d]));
  const leftDeps = new Map(left.dependencies.map((d) => [d.projectId, d]));
  const rightDeps = new Map(right.dependencies.map((d) => [d.projectId, d]));
  const allDepProjects = [
    ...new Set([...baseDeps.keys(), ...leftDeps.keys(), ...rightDeps.keys()]),
  ].sort(compareText);

  const mergedDependencies = [];
  const dependencyChanges = [];

  for (const depProjectId of allDepProjects) {
    const bDep = baseDeps.get(depProjectId) ?? null;
    const lDep = leftDeps.get(depProjectId) ?? null;
    const rDep = rightDeps.get(depProjectId) ?? null;

    if (!bDep) {
      if (lDep && !rDep) {
        mergedDependencies.push(lDep);
        dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'added-left', dependency: lDep}));
      } else if (!lDep && rDep) {
        mergedDependencies.push(rDep);
        dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'added-right', dependency: rDep}));
      } else if (lDep && rDep) {
        if (lDep.releaseId === rDep.releaseId) {
          mergedDependencies.push(lDep);
          dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'added-both', dependency: lDep}));
        } else {
          conflicts.push(
            Object.freeze({
              conflictKind: PROJECT_MERGE_CONFLICT_KINDS.DEPENDENCY_VERSION_CONFLICT,
              projectId: depProjectId,
              base: null,
              left: lDep,
              right: rDep,
            }),
          );
        }
      }
      continue;
    }

    if (!lDep && !rDep) {
      dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'removed-both', dependency: null}));
      continue;
    }
    if (!lDep && rDep) {
      if (rDep.releaseId === bDep.releaseId) {
        dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'removed-left', dependency: null}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.DEPENDENCY_VERSION_CONFLICT,
            projectId: depProjectId,
            base: bDep,
            left: null,
            right: rDep,
          }),
        );
        mergedDependencies.push(bDep);
      }
      continue;
    }
    if (lDep && !rDep) {
      if (lDep.releaseId === bDep.releaseId) {
        dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'removed-right', dependency: null}));
      } else {
        conflicts.push(
          Object.freeze({
            conflictKind: PROJECT_MERGE_CONFLICT_KINDS.DEPENDENCY_VERSION_CONFLICT,
            projectId: depProjectId,
            base: bDep,
            left: lDep,
            right: null,
          }),
        );
        mergedDependencies.push(bDep);
      }
      continue;
    }

    if (lDep.releaseId === bDep.releaseId && rDep.releaseId === bDep.releaseId) {
      mergedDependencies.push(bDep);
    } else if (lDep.releaseId === bDep.releaseId) {
      mergedDependencies.push(rDep);
      dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'modified-right', dependency: rDep}));
    } else if (rDep.releaseId === bDep.releaseId || lDep.releaseId === rDep.releaseId) {
      mergedDependencies.push(lDep);
      dependencyChanges.push(Object.freeze({projectId: depProjectId, action: 'modified-left', dependency: lDep}));
    } else {
      conflicts.push(
        Object.freeze({
          conflictKind: PROJECT_MERGE_CONFLICT_KINDS.DEPENDENCY_VERSION_CONFLICT,
          projectId: depProjectId,
          base: bDep,
          left: lDep,
          right: rDep,
        }),
      );
      mergedDependencies.push(bDep);
    }
  }

  return Object.freeze({
    format: PROJECT_RELEASE_MERGE_V1,
    projectId: base.projectId,
    mergedProfileId,
    clean: conflicts.length === 0,
    mergedMembers: Object.freeze(mergedMembers),
    mergedDependencies: Object.freeze(mergedDependencies),
    memberChanges: Object.freeze(memberChanges),
    dependencyChanges: Object.freeze(dependencyChanges),
    conflicts: Object.freeze(conflicts),
  });
}

function assembleProjectDescriptorFromRecords(records, projectId) {
  const byId = new Map(records.map((record) => [record.id, record]));
  const idRef = projectObjectId(projectId);
  const project = byId.get(idRef);
  if (
    !project ||
    project.kind !== 'object' ||
    !isObjectRef(project.shape) ||
    project.shape.objectId !== PROJECT_SHAPE_ID ||
    project.slots?.['project-id']?.value !== projectId
  ) {
    throw new TypeError(`durable Project not found at requested frontier: ${idRef}`);
  }
  const memberRefs = Array.isArray(project.indexed) ? project.indexed : [];
  const members = [];
  for (const ref of memberRefs) {
    const member = byId.get(ref.objectId);
    if (!member) {
      throw new TypeError(`durable Project member not found at requested frontier: ${ref.objectId}`);
    }
    members.push({
      key: member.slots['project-member-key'].value,
      role: member.slots['project-member-role'].value,
      target: member.slots['project-member-target'],
    });
  }
  const namespace = project.slots['project-namespace'];
  return normalizeProjectDescriptor({
    format: 'lagrange-project/v1',
    projectId: project.slots['project-id'].value,
    name: project.slots['project-name'].value,
    namespace: isObjectRef(namespace) && namespace.objectId !== PROJECT_NONE_ID ? namespace : null,
    members,
  });
}

async function mergeProjectAtFrontiers({
  images,
  imageId,
  projectId,
  baseFrontier,
  leftFrontier,
  rightFrontier,
  resolutions = {},
} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  const [baseRecords, leftRecords, rightRecords] = await Promise.all([
    reconstructImageRecordsAtFrontier({images, imageId, frontier: baseFrontier}),
    reconstructImageRecordsAtFrontier({images, imageId, frontier: leftFrontier}),
    reconstructImageRecordsAtFrontier({images, imageId, frontier: rightFrontier}),
  ]);
  const baseDescriptor = assembleProjectDescriptorFromRecords(baseRecords, projectId);
  const leftDescriptor = assembleProjectDescriptorFromRecords(leftRecords, projectId);
  const rightDescriptor = assembleProjectDescriptorFromRecords(rightRecords, projectId);

  const projectMerge = mergeProjectDescriptors(baseDescriptor, leftDescriptor, rightDescriptor, {
    targetImageId: imageId,
    resolutions: resolutions?.project ?? {},
  });
  const frontierMerge = await mergeImageFrontiers({
    images,
    imageId,
    baseFrontier,
    leftFrontier,
    rightFrontier,
    resolutions: resolutions?.records ?? {},
  });

  return Object.freeze({
    projectMerge,
    frontierMerge,
  });
}

async function authorizedMergeProjects({
  images,
  baseImageId,
  baseProjectId,
  leftImageId = baseImageId,
  leftProjectId = baseProjectId,
  rightImageId = baseImageId,
  rightProjectId = baseProjectId,
  targetImageId = baseImageId,
  resolutions = {},
  require,
} = {}) {
  requiredText(baseImageId, 'baseImageId');
  requiredText(baseProjectId, 'baseProjectId');
  requiredText(leftImageId, 'leftImageId');
  requiredText(leftProjectId, 'leftProjectId');
  requiredText(rightImageId, 'rightImageId');
  requiredText(rightProjectId, 'rightProjectId');
  if (typeof require !== 'function') {
    throw new TypeError('authorizedMergeProjects requires a require(demand) authority-check function');
  }

  const rawResources = [
    objectResource(baseImageId, projectObjectId(baseProjectId)),
    objectResource(leftImageId, projectObjectId(leftProjectId)),
    objectResource(rightImageId, projectObjectId(rightProjectId)),
  ];
  const uniqueByKey = new Map();
  for (const res of rawResources) {
    uniqueByKey.set(`${res.imageId}\u0000${res.objectId}`, res);
  }
  const orderedResources = [...uniqueByKey.values()].sort(
    (a, b) => compareText(a.imageId, b.imageId) || compareText(a.objectId, b.objectId),
  );
  for (const resource of orderedResources) {
    require({operation: OBJECT_READ_OPERATION, resource});
  }

  const [baseDescriptor, leftDescriptor, rightDescriptor] = await Promise.all([
    readProjectDescriptor({images, imageId: baseImageId, projectId: baseProjectId}),
    readProjectDescriptor({images, imageId: leftImageId, projectId: leftProjectId}),
    readProjectDescriptor({images, imageId: rightImageId, projectId: rightProjectId}),
  ]);

  const crossImage = baseImageId !== leftImageId || baseImageId !== rightImageId;
  return mergeProjectDescriptors(baseDescriptor, leftDescriptor, rightDescriptor, {
    targetImageId,
    ignoreImageId: crossImage,
    resolutions,
  });
}

export {
  PROJECT_DESCRIPTOR_MERGE_V1,
  PROJECT_MERGE_CONFLICT_KINDS,
  PROJECT_RELEASE_MERGE_V1,
  authorizedMergeProjects,
  mergeProjectAtFrontiers,
  mergeProjectDescriptors,
  mergeProjectReleases,
};

import {getDefaultCryptoProvider} from '../support/default-crypto.js';
import {bytesToHex, utf8Encode} from '../support/portable-bytes.js';
import {canonicalizeValue, isObjectRef} from '../value/index.js';

const PROJECT_DESCRIPTOR_V1 = 'lagrange-project/v1';
const PROJECT_DEPLOYMENT_PROFILE_V1 = 'lagrange-project-deployment-profile/v1';
const PROJECT_RELEASE_MANIFEST_V1 = 'lagrange-project-release-manifest/v1';
const PROJECT_RELEASE_PROVENANCE_V1 = 'lagrange-project-release-provenance/v1';
const PROJECT_INSTALLATION_V1 = 'lagrange-project-installation/v1';
const PROJECT_RECONCILIATION_V1 = 'lagrange-project-reconciliation/v1';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function compareText(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function plainRecord(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be a plain record`);
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError(`${label} must be a plain record`);
  }
  return value;
}

function assertExactKeys(value, expected, label) {
  const actual = Object.keys(value).sort(compareText);
  const wanted = [...expected].sort(compareText);
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
}

function normalizeRef(value, label) {
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) throw new TypeError(`${label} must be an unpinned object ref`);
  return ref;
}

function normalizeUniqueTexts(values, label) {
  if (!Array.isArray(values)) throw new TypeError(`${label} must be an array`);
  const normalized = values.map((value, index) => requiredText(value, `${label}[${index}]`));
  const unique = new Set(normalized);
  if (unique.size !== normalized.length) throw new TypeError(`${label} must not contain duplicates`);
  return Object.freeze([...normalized].sort(compareText));
}

function normalizeProjectMember(value, label = 'project member') {
  plainRecord(value, label);
  assertExactKeys(value, ['key', 'role', 'target'], label);
  return Object.freeze({
    key: requiredText(value.key, `${label}.key`),
    role: requiredText(value.role, `${label}.role`),
    target: normalizeRef(value.target, `${label}.target`),
  });
}

function normalizeProjectDescriptor(value) {
  plainRecord(value, 'Project descriptor');
  assertExactKeys(value, ['format', 'members', 'name', 'namespace', 'projectId'], 'Project descriptor');
  if (value.format !== PROJECT_DESCRIPTOR_V1) {
    throw new TypeError(`unsupported Project descriptor format: ${value.format}`);
  }
  if (!Array.isArray(value.members)) throw new TypeError('Project members must be an array');
  const members = value.members.map((member, index) => normalizeProjectMember(member, `Project members[${index}]`));
  members.sort((a, b) => compareText(a.key, b.key));
  const seen = new Set();
  for (const member of members) {
    if (seen.has(member.key)) throw new TypeError(`duplicate Project member key: ${member.key}`);
    seen.add(member.key);
  }
  return Object.freeze({
    format: PROJECT_DESCRIPTOR_V1,
    projectId: requiredText(value.projectId, 'Project projectId'),
    name: requiredText(value.name, 'Project name'),
    namespace: value.namespace === null ? null : normalizeRef(value.namespace, 'Project namespace'),
    members: Object.freeze(members),
  });
}

function createProjectId() {
  return `project:${getDefaultCryptoProvider().uuid()}`;
}

function createProjectDescriptor({projectId = createProjectId(), name, namespace = null, members = []} = {}) {
  return normalizeProjectDescriptor({
    format: PROJECT_DESCRIPTOR_V1,
    projectId,
    name,
    namespace,
    members,
  });
}

function normalizeDeploymentProfile(value) {
  plainRecord(value, 'Project deployment profile');
  assertExactKeys(value, ['format', 'members', 'profileId', 'projectId'], 'Project deployment profile');
  if (value.format !== PROJECT_DEPLOYMENT_PROFILE_V1) {
    throw new TypeError(`unsupported Project deployment profile format: ${value.format}`);
  }
  const members = normalizeUniqueTexts(value.members, 'Project deployment profile members');
  if (members.length === 0) throw new TypeError('Project deployment profile must select at least one member');
  return Object.freeze({
    format: PROJECT_DEPLOYMENT_PROFILE_V1,
    projectId: requiredText(value.projectId, 'Project deployment profile projectId'),
    profileId: requiredText(value.profileId, 'Project deployment profile profileId'),
    members,
  });
}

function createDeploymentProfile({project, profileId, members} = {}) {
  const normalizedProject = normalizeProjectDescriptor(project);
  const profile = normalizeDeploymentProfile({
    format: PROJECT_DEPLOYMENT_PROFILE_V1,
    projectId: normalizedProject.projectId,
    profileId,
    members,
  });
  selectProjectMembers(normalizedProject, profile);
  return profile;
}

function selectProjectMembers(project, profile) {
  const normalizedProject = normalizeProjectDescriptor(project);
  const normalizedProfile = normalizeDeploymentProfile(profile);
  if (normalizedProject.projectId !== normalizedProfile.projectId) {
    throw new TypeError(
      `deployment profile projectId ${normalizedProfile.projectId} does not match Project ${normalizedProject.projectId}`,
    );
  }
  const byKey = new Map(normalizedProject.members.map((member) => [member.key, member]));
  return Object.freeze(normalizedProfile.members.map((key) => {
    const member = byKey.get(key);
    if (!member) throw new TypeError(`deployment profile selects unknown Project member: ${key}`);
    return member;
  }));
}

function normalizeReleaseMember(value, label = 'Project release member') {
  plainRecord(value, label);
  assertExactKeys(value, ['contentIdentity', 'key', 'representation', 'role'], label);
  return Object.freeze({
    key: requiredText(value.key, `${label}.key`),
    role: requiredText(value.role, `${label}.role`),
    representation: requiredText(value.representation, `${label}.representation`),
    contentIdentity: requiredText(value.contentIdentity, `${label}.contentIdentity`),
  });
}

function normalizeReleaseDependency(value, label = 'Project release dependency') {
  plainRecord(value, label);
  assertExactKeys(value, ['projectId', 'releaseId'], label);
  return Object.freeze({
    projectId: requiredText(value.projectId, `${label}.projectId`),
    releaseId: requiredText(value.releaseId, `${label}.releaseId`),
  });
}

function canonicalJsonValue(value) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('canonical JSON numbers must be finite');
    return value;
  }
  if (Array.isArray(value)) return value.map((entry) => canonicalJsonValue(entry));
  plainRecord(value, 'canonical JSON value');
  const result = {};
  for (const key of Object.keys(value).sort(compareText)) result[key] = canonicalJsonValue(value[key]);
  return result;
}

function releaseBody({projectId, profileId, members, dependencies}) {
  return {projectId, profileId, members, dependencies};
}

function releaseIdentity(body) {
  const canonical = JSON.stringify(canonicalJsonValue(body));
  return `sha256:${bytesToHex(getDefaultCryptoProvider().sha256(utf8Encode(canonical)))}`;
}

function normalizeReleaseMembers(values) {
  if (!Array.isArray(values)) throw new TypeError('Project release members must be an array');
  const members = values.map((member, index) => normalizeReleaseMember(member, `Project release members[${index}]`));
  members.sort((a, b) => compareText(a.key, b.key));
  const seen = new Set();
  for (const member of members) {
    if (seen.has(member.key)) throw new TypeError(`duplicate Project release member key: ${member.key}`);
    seen.add(member.key);
  }
  if (members.length === 0) throw new TypeError('Project release must contain at least one member');
  return Object.freeze(members);
}

function normalizeReleaseDependencies(values, projectId) {
  if (!Array.isArray(values)) throw new TypeError('Project release dependencies must be an array');
  const dependencies = values.map((dependency, index) =>
    normalizeReleaseDependency(dependency, `Project release dependencies[${index}]`));
  dependencies.sort((a, b) =>
    compareText(a.projectId, b.projectId) || compareText(a.releaseId, b.releaseId));
  const seen = new Set();
  for (const dependency of dependencies) {
    const key = `${dependency.projectId}\u0000${dependency.releaseId}`;
    if (seen.has(key)) throw new TypeError(`duplicate Project release dependency: ${dependency.projectId}/${dependency.releaseId}`);
    seen.add(key);
    if (dependency.projectId === projectId) {
      throw new TypeError('Project release must not depend directly on another release of itself');
    }
  }
  return Object.freeze(dependencies);
}

function normalizeProjectReleaseManifest(value) {
  plainRecord(value, 'Project release manifest');
  assertExactKeys(value, ['dependencies', 'format', 'members', 'profileId', 'projectId', 'releaseId'], 'Project release manifest');
  if (value.format !== PROJECT_RELEASE_MANIFEST_V1) {
    throw new TypeError(`unsupported Project release manifest format: ${value.format}`);
  }
  const projectId = requiredText(value.projectId, 'Project release projectId');
  const profileId = requiredText(value.profileId, 'Project release profileId');
  const members = normalizeReleaseMembers(value.members);
  const dependencies = normalizeReleaseDependencies(value.dependencies, projectId);
  const expectedReleaseId = releaseIdentity(releaseBody({projectId, profileId, members, dependencies}));
  if (value.releaseId !== expectedReleaseId) {
    throw new TypeError(`Project releaseId does not match canonical content; expected ${expectedReleaseId}`);
  }
  return Object.freeze({format: PROJECT_RELEASE_MANIFEST_V1, projectId, profileId, releaseId: expectedReleaseId, members, dependencies});
}

function normalizeMaterializations(value, selectedMembers) {
  plainRecord(value, 'Project release materializations');
  const selectedKeys = new Set(selectedMembers.map(({key}) => key));
  for (const key of Object.keys(value)) {
    if (!selectedKeys.has(key)) throw new TypeError(`materialization supplied for unselected Project member: ${key}`);
  }
  const result = [];
  for (const member of selectedMembers) {
    const materialization = value[member.key];
    plainRecord(materialization, `materialization for Project member ${member.key}`);
    assertExactKeys(materialization, ['contentIdentity', 'representation'], `materialization for Project member ${member.key}`);
    result.push(Object.freeze({
      key: member.key,
      role: member.role,
      representation: requiredText(materialization.representation, `materialization ${member.key}.representation`),
      contentIdentity: requiredText(materialization.contentIdentity, `materialization ${member.key}.contentIdentity`),
    }));
  }
  return result;
}

function createProjectReleaseManifest({project, profile, materializations, dependencies = []} = {}) {
  const normalizedProject = normalizeProjectDescriptor(project);
  const normalizedProfile = normalizeDeploymentProfile(profile);
  const selectedMembers = selectProjectMembers(normalizedProject, normalizedProfile);
  const members = normalizeReleaseMembers(normalizeMaterializations(materializations, selectedMembers));
  const normalizedDependencies = normalizeReleaseDependencies(dependencies, normalizedProject.projectId);
  const body = releaseBody({projectId: normalizedProject.projectId, profileId: normalizedProfile.profileId, members, dependencies: normalizedDependencies});
  return normalizeProjectReleaseManifest({format: PROJECT_RELEASE_MANIFEST_V1, ...body, releaseId: releaseIdentity(body)});
}

function normalizeFrontierRevision(value, label) {
  let revision;
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
    revision = BigInt(value);
  } else if (typeof value === 'bigint') {
    if (value < 0n) throw new TypeError(`${label} must be a non-negative integer`);
    revision = value;
  } else if (typeof value === 'string' && /^\d+$/.test(value)) {
    revision = BigInt(value);
  } else {
    throw new TypeError(`${label} must be a non-negative integer or decimal string`);
  }
  return revision.toString(10);
}

function normalizeFrontierMap(value) {
  plainRecord(value, 'Project release sourceFrontiers');
  const imageIds = Object.keys(value).sort(compareText);
  if (imageIds.length === 0) throw new TypeError('Project release sourceFrontiers must not be empty');
  const normalized = {};
  for (const imageId of imageIds) {
    requiredText(imageId, 'Project release frontier imageId');
    normalized[imageId] = normalizeFrontierRevision(value[imageId], `Project release frontier ${imageId}`);
  }
  return Object.freeze(normalized);
}

function normalizeMemberSource(value, label = 'Project release member source') {
  plainRecord(value, label);
  assertExactKeys(value, ['key', 'source'], label);
  return Object.freeze({key: requiredText(value.key, `${label}.key`), source: normalizeRef(value.source, `${label}.source`)});
}

function normalizeProjectReleaseProvenance(value) {
  plainRecord(value, 'Project release provenance');
  assertExactKeys(value, ['format', 'memberSources', 'projectId', 'releaseId', 'sourceFrontiers'], 'Project release provenance');
  if (value.format !== PROJECT_RELEASE_PROVENANCE_V1) {
    throw new TypeError(`unsupported Project release provenance format: ${value.format}`);
  }
  if (!Array.isArray(value.memberSources)) throw new TypeError('Project release memberSources must be an array');
  const memberSources = value.memberSources.map((source, index) => normalizeMemberSource(source, `Project release memberSources[${index}]`));
  memberSources.sort((a, b) => compareText(a.key, b.key));
  const seen = new Set();
  for (const source of memberSources) {
    if (seen.has(source.key)) throw new TypeError(`duplicate Project release member source key: ${source.key}`);
    seen.add(source.key);
  }
  if (memberSources.length === 0) throw new TypeError('Project release provenance must contain at least one member source');
  return Object.freeze({
    format: PROJECT_RELEASE_PROVENANCE_V1,
    projectId: requiredText(value.projectId, 'Project release provenance projectId'),
    releaseId: requiredText(value.releaseId, 'Project release provenance releaseId'),
    sourceFrontiers: normalizeFrontierMap(value.sourceFrontiers),
    memberSources: Object.freeze(memberSources),
  });
}

function createProjectReleaseProvenance({release, project, sourceFrontiers} = {}) {
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  const normalizedProject = normalizeProjectDescriptor(project);
  if (normalizedProject.projectId !== normalizedRelease.projectId) {
    throw new TypeError('Project release provenance Project does not match release projectId');
  }
  const projectMembers = new Map(normalizedProject.members.map((member) => [member.key, member]));
  const memberSources = normalizedRelease.members.map((releaseMember) => {
    const member = projectMembers.get(releaseMember.key);
    if (!member) throw new TypeError(`release member is not present in provenance Project: ${releaseMember.key}`);
    if (member.role !== releaseMember.role) {
      throw new TypeError(`release member role no longer matches provenance Project: ${releaseMember.key}`);
    }
    return Object.freeze({key: releaseMember.key, source: member.target});
  });
  const frontiers = normalizeFrontierMap(sourceFrontiers);
  for (const {source} of memberSources) {
    if (!Object.hasOwn(frontiers, source.imageId)) {
      throw new TypeError(`Project release sourceFrontiers does not cover member source image: ${source.imageId}`);
    }
  }
  return normalizeProjectReleaseProvenance({
    format: PROJECT_RELEASE_PROVENANCE_V1,
    projectId: normalizedRelease.projectId,
    releaseId: normalizedRelease.releaseId,
    sourceFrontiers: frontiers,
    memberSources,
  });
}

function normalizeInstallationMember(value, targetImageId, label = 'Project installation member') {
  plainRecord(value, label);
  assertExactKeys(value, ['contentIdentity', 'key', 'representation', 'role', 'target'], label);
  const target = normalizeRef(value.target, `${label}.target`);
  if (target.imageId !== targetImageId) {
    throw new TypeError(`${label}.target must belong to installation target image ${targetImageId}`);
  }
  return Object.freeze({
    key: requiredText(value.key, `${label}.key`),
    role: requiredText(value.role, `${label}.role`),
    representation: requiredText(value.representation, `${label}.representation`),
    contentIdentity: requiredText(value.contentIdentity, `${label}.contentIdentity`),
    target,
  });
}

function normalizeProjectInstallation(value) {
  plainRecord(value, 'Project installation');
  assertExactKeys(value, ['format', 'members', 'projectId', 'releaseId', 'targetImageId'], 'Project installation');
  if (value.format !== PROJECT_INSTALLATION_V1) {
    throw new TypeError(`unsupported Project installation format: ${value.format}`);
  }
  const targetImageId = requiredText(value.targetImageId, 'Project installation targetImageId');
  if (!Array.isArray(value.members)) throw new TypeError('Project installation members must be an array');
  const members = value.members.map((member, index) => normalizeInstallationMember(member, targetImageId, `Project installation members[${index}]`));
  members.sort((a, b) => compareText(a.key, b.key));
  const seen = new Set();
  for (const member of members) {
    if (seen.has(member.key)) throw new TypeError(`duplicate Project installation member key: ${member.key}`);
    seen.add(member.key);
  }
  if (members.length === 0) throw new TypeError('Project installation must contain at least one member');
  return Object.freeze({
    format: PROJECT_INSTALLATION_V1,
    projectId: requiredText(value.projectId, 'Project installation projectId'),
    releaseId: requiredText(value.releaseId, 'Project installation releaseId'),
    targetImageId,
    members: Object.freeze(members),
  });
}

function createProjectInstallation({release, targetImageId, targets} = {}) {
  const normalizedRelease = normalizeProjectReleaseManifest(release);
  plainRecord(targets, 'Project installation targets');
  const releaseKeys = new Set(normalizedRelease.members.map(({key}) => key));
  for (const key of Object.keys(targets)) {
    if (!releaseKeys.has(key)) throw new TypeError(`installation target supplied for unknown release member: ${key}`);
  }
  const members = normalizedRelease.members.map((releaseMember) => {
    if (!Object.hasOwn(targets, releaseMember.key)) {
      throw new TypeError(`missing installation target for release member: ${releaseMember.key}`);
    }
    return {
      key: releaseMember.key,
      role: releaseMember.role,
      representation: releaseMember.representation,
      contentIdentity: releaseMember.contentIdentity,
      target: targets[releaseMember.key],
    };
  });
  return normalizeProjectInstallation({format: PROJECT_INSTALLATION_V1, projectId: normalizedRelease.projectId, releaseId: normalizedRelease.releaseId, targetImageId, members});
}

function frozenMaterial(member) {
  return Object.freeze({role: member.role, representation: member.representation, contentIdentity: member.contentIdentity});
}

function planProjectUpgrade({installation, nextRelease} = {}) {
  const current = normalizeProjectInstallation(installation);
  const next = normalizeProjectReleaseManifest(nextRelease);
  if (current.projectId !== next.projectId) {
    throw new TypeError(`cannot upgrade Project ${current.projectId} with release for ${next.projectId}`);
  }
  const currentByKey = new Map(current.members.map((member) => [member.key, member]));
  const nextByKey = new Map(next.members.map((member) => [member.key, member]));
  const keys = [...new Set([...currentByKey.keys(), ...nextByKey.keys()])].sort(compareText);
  const actions = keys.map((key) => {
    const installed = currentByKey.get(key) ?? null;
    const desired = nextByKey.get(key) ?? null;
    if (!installed) return Object.freeze({kind: 'install', key, desired: frozenMaterial(desired)});
    if (!desired) {
      return Object.freeze({kind: 'detach', key, target: installed.target, installed: frozenMaterial(installed)});
    }
    if (
      installed.role === desired.role &&
      installed.representation === desired.representation &&
      installed.contentIdentity === desired.contentIdentity
    ) {
      return Object.freeze({kind: 'retain', key, target: installed.target, material: frozenMaterial(installed)});
    }
    return Object.freeze({kind: 'replace', key, target: installed.target, installed: frozenMaterial(installed), desired: frozenMaterial(desired)});
  });
  return Object.freeze({
    format: PROJECT_RECONCILIATION_V1,
    projectId: current.projectId,
    targetImageId: current.targetImageId,
    fromReleaseId: current.releaseId,
    toReleaseId: next.releaseId,
    actions: Object.freeze(actions),
  });
}

export {
  PROJECT_DEPLOYMENT_PROFILE_V1,
  PROJECT_DESCRIPTOR_V1,
  PROJECT_INSTALLATION_V1,
  PROJECT_RECONCILIATION_V1,
  PROJECT_RELEASE_MANIFEST_V1,
  PROJECT_RELEASE_PROVENANCE_V1,
  createDeploymentProfile,
  createProjectDescriptor,
  createProjectId,
  createProjectInstallation,
  createProjectReleaseManifest,
  createProjectReleaseProvenance,
  normalizeDeploymentProfile,
  normalizeProjectDescriptor,
  normalizeProjectInstallation,
  normalizeProjectReleaseManifest,
  normalizeProjectReleaseProvenance,
  planProjectUpgrade,
  selectProjectMembers,
};

import {isObjectRef, objectRef, textValue} from '../value/index.js';
import {SHAPE_INDEXED} from '../object/model.js';
import {OBJECT_READ_OPERATION, OBJECT_WRITE_OPERATION, objectResource} from '../authority/object-resource.js';
import {objectVersionToken, parseObjectVersionToken, putObjectAtExpectedVersion} from '../object/version-token.js';
import {normalizeProjectDescriptor} from './model.js';
import {ensureObject, ensureShape} from '../graph/ensure-records.js';

// Durable Project working state: the image-level Project library/service
// (ownership.md row "Image-level Project working-state semantics").
//
// The representation is ordinary durable image objects/refs — no special backend
// Project record (ADR 0073 guardrail). A working Project is:
//
//   Project object   id    project/<projectId>
//                    shape lagrange-project/project/v1
//                    slots project-id (text), name (text), namespace (ref or nil)
//                    indexed  refs to the Project's member objects (any order)
//
//   member object    id    project/<projectId>/member/<key>
//                    shape lagrange-project/member/v1
//                    slots member-key (text), role (text), target (unpinned ref)
//
// Members are separate objects so that changing a target is a slot update on a
// stable member id — the member *key* is the identity, never the target ref.
// The Project object's indexed part is only a linkage set; storage order is
// irrelevant because the descriptor model sorts members by key.
//
// This module owns only the storage/read translation. The pure Project model
// (`src/project/model.js`, ADR 0073) remains the SOLE owner of descriptor /
// release / deployment semantics: `projectStateFromRecord` hands the assembled
// record straight to `normalizeProjectDescriptor`, so duplicate-key, shape and
// canonicalization rules live in exactly one place.
//
// PROJECT VERSION TOKEN (ADR 0080). A version-aware read returns the canonical
// descriptor together with an opaque version token, and both originate from the
// SAME Project-object record obtained by ONE Project-object read
// (`projectStateFromRecord` is the single assembly point). The token is the
// existing object-scoped `objectVersionToken` of the Project OBJECT ONLY — not
// of everything reachable through the descriptor: adding a member rewrites the
// Project's indexed linkage set (token changes), retargeting an existing member
// rewrites only the member record (token unchanged while the descriptor's
// target did change). Backing `_version` never escapes.
//
// Authority: Project membership conveys NO authority over the referenced object
// (ADR 0073). These are plain graph reads/writes; no authorization is added or
// implied here.
//
// THE UNIT-LEVEL PROJECT READ RULE (the authorized semantic read seam below).
// ADR 0039 §2 says "authority for A must not imply authority for B" — that rule
// is about refs as LOCATORS TO INDEPENDENT objects. A Project's backing member
// records are NOT independent objects: they ARE the Project's storage
// representation (members are separate objects only so a retarget is a slot
// update on a stable member id; the member key is the identity). Therefore ONE
// authorized `object/read` on the Project object authorizes reading the
// Project's own backing member records — this is the Project-semantic rule this
// module owns, NOT a transitive ref-follow. It does NOT extend to member
// TARGETS: a target is merely a locator, and reading a target's CONTENT still
// independently requires `object/read` on that target object. Membership itself
// creates NO grants.

const PROJECT_SHAPE_ID = 'lagrange-project/project/v1';
const PROJECT_MEMBER_SHAPE_ID = 'lagrange-project/member/v1';
// A module-owned "absent" marker for the optional namespace slot. Object slots must
// hold canonical Values and a Shape requires every slot to be present, so "no
// namespace" cannot be a raw null. This well-known empty object stands for absence
// (language-neutral — not the Smalltalk kernel nil) and reads back as `null`.
const PROJECT_NONE_ID = 'lagrange-project/none/v1';

const SLOT = Object.freeze({
  projectId: 'project-id',
  name: 'project-name',
  namespace: 'project-namespace',
  memberKey: 'project-member-key',
  role: 'project-member-role',
  target: 'project-member-target',
});

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function projectObjectId(projectId) {
  return `project/${requiredText(projectId, 'projectId')}`;
}

function projectMemberObjectId(projectId, key) {
  return `${projectObjectId(projectId)}/member/${requiredText(key, 'member key')}`;
}

const PROJECT_NONE_SHAPE_ID = 'lagrange-project/none-shape/v1';

// Shape/marker admission for the Project representation goes through the ONE ensure owner
// (graph/ensure-records.js): insert-only, layout-checked, and convergent when two fresh-image
// callers race — the loser adopts the winner's identical record instead of failing (bead ea8).
async function ensureShapes(images, imageId) {
  const noneShapeRef = objectRef(imageId, PROJECT_NONE_SHAPE_ID);
  await ensureShape(images, imageId, {id: PROJECT_NONE_SHAPE_ID, slots: []});
  await ensureObject(images, imageId, {
    id: PROJECT_NONE_ID, shape: noneShapeRef, behavior: null, slots: {}, metadata: {project: 'none'},
  });
  const projectShapeRef = objectRef(imageId, PROJECT_SHAPE_ID);
  await ensureShape(images, imageId, {
    id: PROJECT_SHAPE_ID,
    slots: [
      {id: SLOT.projectId, name: 'projectId'},
      {id: SLOT.name, name: 'name'},
      {id: SLOT.namespace, name: 'namespace'},
    ],
    indexed: SHAPE_INDEXED.VALUES,
  });
  const memberShapeRef = objectRef(imageId, PROJECT_MEMBER_SHAPE_ID);
  await ensureShape(images, imageId, {
    id: PROJECT_MEMBER_SHAPE_ID,
    slots: [
      {id: SLOT.memberKey, name: 'key'},
      {id: SLOT.role, name: 'role'},
      {id: SLOT.target, name: 'target'},
    ],
  });
  return {projectShapeRef, memberShapeRef};
}

function requireUnpinnedRef(value, label) {
  if (!isObjectRef(value)) throw new TypeError(`${label} must be an unpinned object ref`);
  return value;
}

// Create a durable working Project. Stable `projectId` (opaque text per ADR 0073;
// the caller supplies the semantic id, e.g. from `createProjectId()`), a display
// `name`, an optional `namespace` ref, and an empty member set. Create-or-return
// by stable id: `name`/`namespace` are INITIAL mutable state used only when the
// Project does not exist yet; an existing valid Project with this stable id is
// returned unchanged (see the replay-identity note below); a foreign occupant of
// the id is an error.
async function createProject({images, imageId, projectId, name, namespace = null} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  requiredText(name, 'Project name');
  if (namespace !== null) requireUnpinnedRef(namespace, 'Project namespace');
  const {projectShapeRef} = await ensureShapes(images, imageId);

  const id = projectObjectId(projectId);
  // REPLAY IDENTITY (ADR 0080 decision 4): `projectId` is the creation identity;
  // `name` and `namespace` are mutable Project state and therefore cannot also
  // be replay identity. A valid Project already at this stable id is returned
  // AS IT CURRENTLY IS — its mutable state is neither compared to the request
  // (a replay after a rename must not reject) nor reset from it (a replay must
  // not restore an old name). Only an occupant that is not the expected Project
  // representation with this stable id is a conflict.
  const existing = await images.getObject(imageId, id);
  if (existing) {
    assertProjectRecord(existing, projectId, id);
    return objectRef(imageId, id);
  }
  // Insert-only (expectedVersion 0): the create commits only if the id is STILL
  // absent. A concurrent or delayed replay whose existence read raced this put
  // therefore cannot overwrite a Project that meanwhile came to exist (restoring
  // an old name, or wiping its member linkage); it loses the CAS and falls into
  // the same return-as-it-currently-is path.
  try {
    await images.putObject(imageId, {
      id,
      shape: projectShapeRef,
      behavior: null,
      slots: {
        [SLOT.projectId]: textValue(projectId),
        [SLOT.name]: textValue(name),
        [SLOT.namespace]: namespace ?? objectRef(imageId, PROJECT_NONE_ID),
      },
      indexed: [],
      metadata: {project: 'working-state'},
    }, {expectedVersion: 0});
  } catch (error) {
    if (error?.name !== 'VersionConflictError') throw error;
    const raced = await images.getObject(imageId, id);
    assertProjectRecord(raced, projectId, id);
  }
  return objectRef(imageId, id);
}

// Add (or, with the same key and role, retarget) a Project member. `key` is the
// stable Project-local member identity; `role` is language/tool policy text;
// `target` is an unpinned ref that may point into another Image. A different
// member already holding `key` is refused. Changing only the target keeps the
// same member object id, preserving member-key identity.
async function addProjectMember({images, imageId, projectId, key, role, target} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  requiredText(key, 'member key');
  requiredText(role, 'member role');
  requireUnpinnedRef(target, 'member target');
  const {memberShapeRef} = await ensureShapes(images, imageId);

  const projectIdRef = projectObjectId(projectId);
  const project = await images.getObject(imageId, projectIdRef);
  if (!project) throw new TypeError(`durable Project not found: ${projectIdRef}`);

  const memberId = projectMemberObjectId(projectId, key);
  const existingMember = await images.getObject(imageId, memberId);
  const memberRef = objectRef(imageId, memberId);
  if (existingMember) {
    if (existingMember.slots?.[SLOT.role]?.value !== role) {
      throw new TypeError(`Project member key ${key} already exists with a different role`);
    }
    // Retarget: update only the target slot on the stable member id.
    if (!sameRefValue(existingMember.slots?.[SLOT.target], target)) {
      await images.putObject(imageId, {
        id: memberId,
        shape: memberShapeRef,
        behavior: null,
        slots: {
          [SLOT.memberKey]: textValue(key),
          [SLOT.role]: textValue(role),
          [SLOT.target]: target,
        },
        metadata: existingMember.metadata ?? {project: 'member'},
      }, {expectedVersion: existingMember._version});
    }
    return memberRef;
  }

  await images.putObject(imageId, {
    id: memberId,
    shape: memberShapeRef,
    behavior: null,
    slots: {
      [SLOT.memberKey]: textValue(key),
      [SLOT.role]: textValue(role),
      [SLOT.target]: target,
    },
    metadata: {project: 'member'},
  });

  // Link the member into the Project's indexed set (membership-guarded; storage
  // order is irrelevant because the descriptor model sorts members by key).
  const current = Array.isArray(project.indexed) ? project.indexed : [];
  if (!current.some((ref) => isObjectRef(ref) && ref.objectId === memberId)) {
    await images.putObject(imageId, {
      id: projectIdRef,
      shape: project.shape,
      behavior: null,
      slots: project.slots,
      indexed: [...current, memberRef],
      metadata: project.metadata ?? {project: 'working-state'},
    }, {expectedVersion: project._version});
  }
  return memberRef;
}

function sameRefValue(a, b) {
  return isObjectRef(a) && isObjectRef(b) && a.imageId === b.imageId && a.objectId === b.objectId;
}

// The ONE validation of an object occupying `project/<projectId>`: it must be
// the expected Project representation (Shape lagrange-project/project/v1) and
// carry the expected stable project id in its private slot. Any other occupant
// of the id is an integrity conflict, never silently read as a Project.
function assertProjectRecord(record, projectId, idRef) {
  if (!record) throw new TypeError(`durable Project not found: ${idRef}`);
  if (
    !isObjectRef(record.shape) || record.shape.objectId !== PROJECT_SHAPE_ID ||
    record.slots?.[SLOT.projectId]?.value !== projectId
  ) {
    throw new TypeError(`durable Project ${projectId} is not the expected Project representation`);
  }
  return record;
}

// THE single Project-state assembly: from ONE already-read (and validated)
// Project record to `{descriptor, versionToken}`. Every piece of the descriptor's
// Project state (stable id, name, namespace, member linkage) AND the token come
// from this one `project` record; the Project object is never reread here. The
// backing member records are read while assembling (they are the Project's own
// storage representation), and the assembled record is handed unchanged to
// `normalizeProjectDescriptor`, so the pure model owns every descriptor rule
// (key uniqueness, sorting, ref and shape checks). A member ref that dangles
// surfaces the graph's own dangling-edge outcome rather than a Project-specific
// one. The token is `objectVersionToken` of the Project object at the version of
// this record (ADR 0042 decision 5): opaque, object-scoped, never raw `_version`.
// Its scope is `idRef` — the very object id the caller was authorized for — so
// authorization resource and token scope are identical by construction.
async function projectStateFromRecord({images, imageId, idRef, project}) {
  const memberRefs = Array.isArray(project.indexed) ? project.indexed : [];
  const members = [];
  for (const ref of memberRefs) {
    const record = await images.getObject(imageId, ref.objectId);
    if (!record) throw new TypeError(`durable Project member not found: ${ref.objectId}`);
    members.push({
      key: record.slots[SLOT.memberKey].value,
      role: record.slots[SLOT.role].value,
      target: record.slots[SLOT.target],
    });
  }

  const namespace = project.slots[SLOT.namespace];
  const descriptor = normalizeProjectDescriptor({
    format: 'lagrange-project/v1',
    projectId: project.slots[SLOT.projectId].value,
    name: project.slots[SLOT.name].value,
    // The none-marker reads back as the model's `namespace: null`.
    namespace: isObjectRef(namespace) && namespace.objectId !== PROJECT_NONE_ID ? namespace : null,
    members,
  });
  return Object.freeze({
    descriptor,
    versionToken: objectVersionToken(imageId, idRef, project._version),
  });
}

// Read the Project object EXACTLY ONCE, validate it as the expected Project
// representation for `projectId`, and assemble `{descriptor, versionToken}`
// from that one record. A missing Project is an error.
async function readProjectState({images, imageId, projectId} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  const idRef = projectObjectId(projectId);
  const project = assertProjectRecord(await images.getObject(imageId, idRef), projectId, idRef);
  return projectStateFromRecord({images, imageId, idRef, project});
}

// Read a durable working Project back into the canonical Project descriptor:
// the versioned read with the token discarded (one implementation, not two).
// For a valid Project this is behavior-identical to the pre-ADR-0080 read; it is
// stricter only for a malformed occupant of `project/<id>` (wrong Shape, or a
// stored project-id that differs from the requested one, which previously
// leaked through as the descriptor's projectId) and for a record without a
// backend `_version` (the token is always derived, even when discarded).
async function readProjectDescriptor(args) {
  return (await readProjectState(args)).descriptor;
}

function assertRequire(require, label) {
  if (typeof require !== 'function') {
    throw new TypeError(`${label} requires a require(demand) authority-check function`);
  }
  return require;
}

// The AUTHORIZED version-aware semantic Project read seam (ADR 0080): the
// authoritative internal operation behind every authorized Project read.
//
// `require` is the caller-supplied authority check (a closure over an issued,
// LIVE authority context — e.g. `(demand) => authorityService.require(context,
// demand)`). A revoked context fails closed with AuthorityError (the intended
// behavior). This function:
//   1. Authorizes `object/read` on the Project object BEFORE any existence
//      disclosure, so a denied caller learns AuthorityError whether or not the
//      Project exists (no-existence-oracle — the same property as
//      image-object-read-binding/v1). The Project object id is derived HERE
//      (projectObjectId), so the caller never builds a storage id.
//   2. Reads the Project object exactly once (readProjectState), validates it as
//      the expected Project representation, and assembles BOTH the canonical
//      descriptor and the opaque Project version token from that ONE record. The
//      single require on the Project object IS the authority boundary (see the
//      unit-level rule above): the backing member records are read internally
//      as the Project's own storage, with NO per-member authority and NO grants
//      created.
//
// The result is a frozen `{descriptor, versionToken}`: the canonical descriptor
// {format, projectId, name, namespace, members:[{key, role, target}]} — no
// backing ids, Shape ids, or slot ids escape — and the opaque, object-scoped
// version token of the Project OBJECT (scope: the Project object only, see the
// module header). A dangling member ref surfaces a distinct TypeError to an
// AUTHORIZED reader (the no-existence-oracle covers the Project object; a
// corrupt Project is a separate integrity error, correctly disclosed to one who
// may read it).
// TOCTOU note: the require check and the subsequent read are two steps (the
// Project could change between); for a reader this is benign — the token
// describes exactly the record the descriptor was assembled from, and a later
// conditional mutation supplying that token is caught by the storage CAS.
async function authorizedReadProject({images, imageId, projectId, require} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  assertRequire(require, 'authorizedReadProject');
  require({operation: OBJECT_READ_OPERATION, resource: objectResource(imageId, projectObjectId(projectId))});
  return readProjectState({images, imageId, projectId});
}

// The AUTHORIZED descriptor-only read: `authorizedReadProject` with the token
// discarded. Behavior-identical to the versioned seam (same authorization
// ordering, same single Project-object read, same canonical descriptor); it
// exists so read-only consumers keep a stable return shape.
async function authorizedReadProjectDescriptor({images, imageId, projectId, require} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  assertRequire(require, 'authorizedReadProjectDescriptor');
  return (await authorizedReadProject({images, imageId, projectId, require})).descriptor;
}

// The AUTHORIZED Project rename (ADR 0080 decision 5): the first Project
// semantic mutation, and deliberately the ONLY one — not a generic slot or
// semantic-write lane. Ordering:
//   1. Validate every non-storage input first: ids, the new name, the mandatory
//      expected token (it must be a well-formed opaque token issued for THIS
//      Project object — checked purely over caller-supplied input, disclosing
//      nothing), and the require function.
//   2. Require `object/write` on the Project object BEFORE any existence read:
//      a denied caller learns AuthorityError whether or not the Project exists.
//   3. Only then read the Project object (once) and validate it as the expected
//      Project representation with the expected stable id. This read is
//      read-for-write; nothing from it reaches the caller.
//   4. Translate the semantic field `name` to its private slot HERE (no caller
//      sees a slot id) and persist through the one conditional-persistence seam
//      with the caller's expected version as a REAL storage precondition: the
//      backend CAS, not a JavaScript compare, decides — a change between the
//      validation read and the write is caught atomically.
// A stale token surfaces as the existing opaque ObjectMutationConflictError
// (no actual/current version, no replacement token, no cause): the caller
// learns only that its expected state is stale and must perform a new
// authorized read. Success returns the NEW opaque Project token (frozen
// `{versionToken}`) — the Project object's version, so an outstanding token is
// invalidated by any Project-object write (rename, member add) and by nothing
// else (a member retarget rewrites only the member record).
// A same-name rename is NOT refused here: refusing would need a JavaScript
// compare in the path that is deliberately pure CAS, and would break idempotent
// retry after a lost response (the caller re-sends with its token and needs the
// resulting token back). Filtering no-ops is a concern above this seam.
async function authorizedRenameProject({images, imageId, projectId, name, expectedVersionToken, require} = {}) {
  requiredText(imageId, 'imageId');
  requiredText(projectId, 'projectId');
  requiredText(name, 'Project name');
  requiredText(expectedVersionToken, 'expectedVersionToken');
  assertRequire(require, 'authorizedRenameProject');
  const idRef = projectObjectId(projectId);
  const expectedVersion = parseObjectVersionToken(expectedVersionToken, imageId, idRef);

  require({operation: OBJECT_WRITE_OPERATION, resource: objectResource(imageId, idRef)});

  const project = assertProjectRecord(await images.getObject(imageId, idRef), projectId, idRef);
  const stored = await putObjectAtExpectedVersion(images, imageId, {
    id: idRef,
    shape: project.shape,
    behavior: null,
    slots: {...project.slots, [SLOT.name]: textValue(name)},
    indexed: Array.isArray(project.indexed) ? project.indexed : [],
    metadata: project.metadata ?? {project: 'working-state'},
  }, expectedVersion);
  return Object.freeze({versionToken: objectVersionToken(imageId, idRef, stored._version)});
}

export {
  PROJECT_MEMBER_SHAPE_ID,
  PROJECT_SHAPE_ID,
  addProjectMember,
  authorizedReadProject,
  authorizedReadProjectDescriptor,
  authorizedRenameProject,
  createProject,
  projectMemberObjectId,
  projectObjectId,
  readProjectDescriptor,
};

// The narrow host crypto/random primitive contract (ADR: host portability, beads
// lagrange-images-g58, lagrange-images-16q). PORTABLE — no Node imports.
//
// Crypto is a true HOST PRIMITIVE seam, but lagrange-images retains ALL semantic
// ownership. A provider computes primitives ONLY. The contract is deliberately the
// narrowest the executed portable-client acceptance closure needs — it is NOT
// modeled on the broad Node `node:crypto` API, and no host is asked to supply
// Node's personality.
//
// THE CONTRACT IS SYNCHRONOUS. `typeFingerprint` (inside the synchronous
// `packCompositeValue`), `objectVersionToken`, and the observation cursor
// `encode`/`decode` all run deep inside synchronous executor code paths, so an
// async provider contract (e.g. WebCrypto) would not be injectable there without
// a forbidden semantic/IO change. A synchronous contract is exactly what a native
// JS host (Node crypto, a native SHA-256/AES binding, a seeded test provider) can
// supply directly. Hosts whose only crypto is async are NOT a target of this
// seam; that is a separate finding to report, not to shim over.
//
// All byte inputs/outputs are `Uint8Array` (never a Node Buffer). Semantics:
//
//   secureRandomBytes(length)      -> Uint8Array  cryptographically secure random
//   sha256(bytes)                  -> Uint8Array(32)  raw digest bytes
//   aes256gcmEncrypt({key, iv, plaintext}) -> {ciphertext, tag}   both Uint8Array;
//                                            key 32 bytes, iv 12 bytes, tag 16 bytes
//   aes256gcmDecrypt({key, iv, ciphertext, tag}) -> Uint8Array plaintext; throws on
//                                            authentication/integrity failure
//   uuid()                         -> string  RFC 4122 version 4 (random) UUID
//
// POLICY LIVES ABOVE. `image-observation-binding` alone decides the cursor format,
// the AES-GCM policy (key derivation, IV length, tag layout), what is
// authenticated, parsing, and integrity-failure handling. A provider never sees a
// cursor — only key/iv/plaintext/ciphertext/tag.
//
// IMPLEMENTATIONS. The Node reference implementation is `node-crypto-provider.js`
// (imported only by the Node composition root). This module stays import-clean so
// the portable runtime's static closure never touches `node:crypto`.

const REQUIRED_METHODS = Object.freeze([
  'secureRandomBytes',
  'sha256',
  'aes256gcmEncrypt',
  'aes256gcmDecrypt',
  'uuid',
]);

// Validate that a candidate supplies the full contract and freeze it. Every
// provider — the Node reference and any host-supplied one — passes through here so
// the contract has exactly one definition.
function assertCryptoProvider(candidate) {
  if (!candidate || typeof candidate !== 'object') {
    throw new TypeError('crypto provider must be an object');
  }
  for (const method of REQUIRED_METHODS) {
    if (typeof candidate[method] !== 'function') {
      throw new TypeError(`crypto provider must supply ${method}()`);
    }
  }
  return Object.freeze(candidate);
}

export {
  REQUIRED_METHODS as CRYPTO_PROVIDER_METHODS,
  assertCryptoProvider,
};

// Default crypto provider registry (ADR: host portability, beads
// lagrange-images-g58, lagrange-images-16q). PORTABLE — no Node imports.
//
// The pure, synchronous semantic functions that need a host primitive
// (`typeFingerprint`, the composite codec fingerprint, `objectVersionToken`, the
// observation cursor) are called deep inside synchronous executor paths where no
// provider can be threaded through an argument list without a forbidden signature
// change. They therefore resolve the ACTIVE provider here.
//
// THIS MODULE NEVER IMPORTS THE NODE PROVIDER. Keeping `node-crypto-provider.js`
// out of this module's static closure is what lets a non-Node host load the whole
// portable runtime without touching `node:crypto`. The Node composition root
// (`src/runtime.js`) installs the Node reference provider exactly once, at
// composition time, via `installNodeCryptoProvider()` below; a non-Node host calls
// `setDefaultCryptoProvider(nativeProvider)` BEFORE any semantic work that needs
// UUID/SHA/AES.
//
// This is a process-wide default for the language-neutral pure functions — NOT a
// per-request authority or policy channel; the observation lane's per-install
// cursor secret remains the security-relevant input and is unaffected.

import {assertCryptoProvider} from './crypto-provider.js';

let activeDefault = null;

function getDefaultCryptoProvider() {
  if (activeDefault === null) {
    throw new TypeError(
      'no crypto provider installed: the Node composition root installs one automatically; '
      + 'a portable host must call setDefaultCryptoProvider(nativeProvider) before semantic work',
    );
  }
  return activeDefault;
}

function setDefaultCryptoProvider(provider) {
  activeDefault = assertCryptoProvider(provider);
}

// Test/reset hook: drop the active provider so the next install starts clean.
function resetDefaultCryptoProvider() {
  activeDefault = null;
}

// Convenience for the many identity-minting call sites (binding/block/object ids)
// that only need a random UUID: resolve the active provider's uuid(). This keeps
// node:crypto's randomUUID out of every semantic module without threading a
// provider argument through pure identity helpers.
function uuid() {
  return getDefaultCryptoProvider().uuid();
}

export {
  getDefaultCryptoProvider,
  resetDefaultCryptoProvider,
  setDefaultCryptoProvider,
  uuid,
};

// Host-portable byte utilities (ADR: host portability, bead lagrange-images-g58).
//
// OWNERSHIP. Binary layout semantics stay owned entirely here; this module is the
// single internal home for the standard language-neutral machinery every
// language-neutral binary operation in lagrange-images is built on:
//
//   Uint8Array / DataView / TextEncoder / TextDecoder / internal base64/base64url.
//
// Node `Buffer` is NOT a host capability and is never accepted or returned by these
// primitives. Every function operates on and returns `Uint8Array` (the standard,
// host-portable binary type). Because Node's `Buffer` IS a `Uint8Array` subclass,
// a Node caller that still holds a Buffer can pass it anywhere a `Uint8Array` is
// accepted and it will behave identically — but nothing here constructs or exposes
// a Buffer, so a non-Node host needs no Buffer global.
//
// The on-wire bytes are frozen by compatibility: these primitives exist to produce
// exactly the same bytes the previous Buffer-based implementation produced.

const BASE64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const BASE64URL_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

// Lazily-created shared coders. TextEncoder/TextDecoder are standard on every ES host
// that matters (browsers, Node >= 11, Deno, Bun, QuickJS-NG with the standard module,
// WASM component hosts); they are language-neutral, not a Node personality.
let sharedEncoder = null;
function textEncoder() {
  if (sharedEncoder === null) sharedEncoder = new TextEncoder();
  return sharedEncoder;
}

function utf8Encode(text) {
  return textEncoder().encode(text);
}

// Strict UTF-8 decode: `fatal: true` refuses malformed sequences instead of
// substituting U+FFFD, matching the strictness the byte primitives require. A fresh
// decoder per call because `fatal` is a construction-time option.
function utf8DecodeStrict(bytes) {
  return new TextDecoder('utf-8', {fatal: true}).decode(bytes);
}

// Lenient UTF-8 decode (U+FFFD substitution), matching Buffer's default toString.
// Used only where the previous implementation relied on lossy decode for a
// round-trip comparison; the strictness decision stays at the call site.
function utf8DecodeLossy(bytes) {
  return new TextDecoder('utf-8', {fatal: false}).decode(bytes);
}

function concatBytes(chunks) {
  let total = 0;
  for (const chunk of chunks) total += chunk.length;
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    if (a[index] !== b[index]) return false;
  }
  return true;
}

// --- base64 / base64url -------------------------------------------------------
//
// Self-contained codecs so no host base64 facility (Buffer, atob/btoa) is required.
// The URL-safe variant is RFC 4648 base64url WITHOUT padding (matching Node's
// 'base64url' encoding, which omits '='). The standard variant uses '+'/'/' and
// emits padding exactly as Node's 'base64' encoding does.

function encodeBase64With(bytes, alphabet, pad) {
  let out = '';
  for (let index = 0; index < bytes.length; index += 3) {
    const b0 = bytes[index];
    const b1 = index + 1 < bytes.length ? bytes[index + 1] : undefined;
    const b2 = index + 2 < bytes.length ? bytes[index + 2] : undefined;
    out += alphabet[b0 >> 2];
    out += alphabet[((b0 & 0x03) << 4) | (b1 === undefined ? 0 : b1 >> 4)];
    out += b1 === undefined ? (pad ? '=' : '') : alphabet[((b1 & 0x0f) << 2) | (b2 === undefined ? 0 : b2 >> 6)];
    out += b2 === undefined ? (pad ? '=' : '') : alphabet[b2 & 0x3f];
  }
  return out;
}

function decodeBase64With(text, alphabet, label) {
  const reverse = new Map();
  for (let index = 0; index < 64; index += 1) reverse.set(alphabet[index], index);
  const bytes = [];
  let accumulator = 0;
  let bits = 0;
  for (const char of text) {
    if (char === '=') break; // padding terminates the meaningful input
    const value = reverse.get(char);
    if (value === undefined) throw new TypeError(`${label} contains an invalid base64 character`);
    accumulator = (accumulator << 6) | value;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((accumulator >> bits) & 0xff);
    }
  }
  return new Uint8Array(bytes);
}

function base64Encode(bytes) {
  return encodeBase64With(bytes, BASE64_ALPHABET, true);
}

function base64Decode(text) {
  return decodeBase64With(text, BASE64_ALPHABET, 'base64 input');
}

function base64urlEncode(bytes) {
  return encodeBase64With(bytes, BASE64URL_ALPHABET, false);
}

function base64urlDecode(text) {
  return decodeBase64With(text, BASE64URL_ALPHABET, 'base64url input');
}

// --- hex ----------------------------------------------------------------------
//
// `bytesToHex` / `hexToBytes` cover the digest-as-hex call sites (derivation cache,
// release identity, equality hash) that previously used Buffer `.toString('hex')`.

function bytesToHex(bytes) {
  let out = '';
  for (let index = 0; index < bytes.length; index += 1) {
    out += bytes[index].toString(16).padStart(2, '0');
  }
  return out;
}

function hexToBytes(text) {
  if (text.length % 2 !== 0 || !/^[0-9a-fA-F]*$/.test(text)) {
    throw new TypeError('hex input must be an even-length string of hexadecimal digits');
  }
  const out = new Uint8Array(text.length / 2);
  for (let index = 0; index < out.length; index += 1) {
    out[index] = parseInt(text.slice(index * 2, index * 2 + 2), 16);
  }
  return out;
}

export {
  base64Decode,
  base64Encode,
  base64urlDecode,
  base64urlEncode,
  bytesEqual,
  bytesToHex,
  concatBytes,
  hexToBytes,
  utf8DecodeLossy,
  utf8DecodeStrict,
  utf8Encode,
};

// Map and Set keyed by a tuple of strings, nested one Map level per part.
//
// This exists because joining a multi-part identity into one string key is not injective. Image
// ids, object ids, representations, roles and authority operations are all arbitrary non-empty
// text, so no separator is safe: for any separator `s`, the parts `a+s+b` and `c` join to the same
// string as `a` and `b+s+c`. That has already produced three real defects in this repo — a
// non-injective authority resource name (ADR 0039), closure cells resolving to the wrong closure
// (ADR 0043), and the grant key below.
//
// A nested lookup has no encoding to audit, so the mistake becomes unavailable rather than
// discouraged. Prefer this to inventing another separator; reach for `objectResource()` only when a
// single *durable* string is genuinely required, and make that one injective by construction.
class TupleMap {
  #arity;
  #root = new Map();
  #size = 0;

  constructor(arity) {
    if (!Number.isInteger(arity) || arity < 1) throw new TypeError('tuple arity must be a positive integer');
    this.#arity = arity;
  }

  get arity() { return this.#arity; }
  get size() { return this.#size; }

  #assertParts(parts) {
    if (!Array.isArray(parts) || parts.length !== this.#arity) {
      throw new TypeError(`tuple key must have exactly ${this.#arity} parts`);
    }
    for (const part of parts) {
      if (typeof part !== 'string') throw new TypeError('tuple key parts must be strings');
    }
    return parts;
  }

  #resolve(parts, create) {
    let level = this.#root;
    for (let index = 0; index < this.#arity - 1; index += 1) {
      let next = level.get(parts[index]);
      if (!next) {
        if (!create) return null;
        next = new Map();
        level.set(parts[index], next);
      }
      level = next;
    }
    return level;
  }

  set(parts, value) {
    this.#assertParts(parts);
    const leaf = this.#resolve(parts, true);
    const last = parts[this.#arity - 1];
    if (!leaf.has(last)) this.#size += 1;
    leaf.set(last, value);
    return this;
  }

  get(parts) {
    this.#assertParts(parts);
    return this.#resolve(parts, false)?.get(parts[this.#arity - 1]);
  }

  has(parts) {
    this.#assertParts(parts);
    return this.#resolve(parts, false)?.has(parts[this.#arity - 1]) ?? false;
  }

  // Prunes the intermediate levels it empties, so a long-lived cache that deletes as often as it
  // inserts does not accumulate empty Maps forever.
  delete(parts) {
    this.#assertParts(parts);
    const path = [];
    let level = this.#root;
    for (let index = 0; index < this.#arity - 1; index += 1) {
      const next = level.get(parts[index]);
      if (!next) return false;
      path.push([level, parts[index]]);
      level = next;
    }
    if (!level.delete(parts[this.#arity - 1])) return false;
    this.#size -= 1;
    for (let index = path.length - 1; index >= 0; index -= 1) {
      const [parent, part] = path[index];
      if (parent.get(part).size > 0) break;
      parent.delete(part);
    }
    return true;
  }

  clear() {
    this.#root.clear();
    this.#size = 0;
  }

  // Nested/prefix-grouped, NOT insertion-ordered: the nesting groups every key sharing a prefix,
  // so setting a/1, b/1, a/2 iterates a/1, a/2, b/1. Preserving global Map order would cost a
  // parallel index that no consumer here needs. A consumer that requires a particular order must
  // sort explicitly — the compiler registries do, with `compareTuples`.
  //
  // Each key is handed back as its parts, never as a string an accidental `split` could re-derive
  // wrongly.
  *entries() {
    const walk = function* walk(level, depth, prefix) {
      if (depth === 0) {
        for (const [last, value] of level) yield [[...prefix, last], value];
        return;
      }
      for (const [part, next] of level) yield* walk(next, depth - 1, [...prefix, part]);
    };
    yield* walk(this.#root, this.#arity - 1, []);
  }

  *keys() {
    for (const [parts] of this.entries()) yield parts;
  }

  *values() {
    for (const [, value] of this.entries()) yield value;
  }

  [Symbol.iterator]() {
    return this.entries();
  }
}

const PRESENT = Symbol('lagrange.tuple-set.present');

class TupleSet {
  #entries;

  constructor(arity, parts = []) {
    this.#entries = new TupleMap(arity);
    for (const entry of parts) this.add(entry);
  }

  get arity() { return this.#entries.arity; }
  get size() { return this.#entries.size; }

  add(parts) {
    this.#entries.set(parts, PRESENT);
    return this;
  }

  has(parts) {
    return this.#entries.has(parts);
  }

  delete(parts) {
    return this.#entries.delete(parts);
  }

  clear() {
    this.#entries.clear();
  }

  *values() {
    yield* this.#entries.keys();
  }

  [Symbol.iterator]() {
    return this.values();
  }
}

export {TupleMap, TupleSet};

const VALUE_KIND = Object.freeze({
  BOOLEAN: 'boolean',
  INTEGER: 'integer',
  FLOAT64: 'float64',
  TEXT: 'text',
  BYTES: 'bytes',
  REF: 'ref',
  PINNED_REF: 'pinned-ref',
});

export {VALUE_KIND};

import {base64Decode, base64Encode} from '../support/portable-bytes.js';
import {VALUE_KIND} from './kinds.js';

const freeze = (record) => Object.freeze(record);
const invalid = (message) => new TypeError(message);

function booleanValue(value) {
  if (typeof value !== 'boolean') throw invalid('boolean value must be a boolean');
  return freeze({kind: VALUE_KIND.BOOLEAN, value});
}

function integerValue(value) {
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value)) throw invalid('number input for integer must be a safe integer; use bigint or a decimal string');
  } else if (typeof value === 'string') {
    if (!/^-?\d+$/.test(value)) throw invalid('integer string must be decimal');
  } else if (typeof value !== 'bigint') {
    throw invalid('integer must be a bigint, safe integer, or decimal string');
  }
  return freeze({kind: VALUE_KIND.INTEGER, value: BigInt(value).toString(10)});
}

function float64FromBits(bits) {
  if (typeof bits !== 'string' || !/^[0-9a-fA-F]{16}$/.test(bits)) throw invalid('float64 bits must be 16 hexadecimal characters');
  return freeze({kind: VALUE_KIND.FLOAT64, bits: bits.toLowerCase()});
}

function float64Value(value) {
  if (typeof value !== 'number') throw invalid('float64 value must be a number');
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, value, false);
  return float64FromBits(view.getBigUint64(0, false).toString(16).padStart(16, '0'));
}

function float64ToNumber(value) {
  if (!value || value.kind !== VALUE_KIND.FLOAT64) throw invalid('value is not a float64');
  const normalized = float64FromBits(value.bits);
  const view = new DataView(new ArrayBuffer(8));
  view.setBigUint64(0, BigInt(`0x${normalized.bits}`), false);
  return view.getFloat64(0, false);
}

function textValue(value) {
  if (typeof value !== 'string') throw invalid('text value must be a string');
  return freeze({kind: VALUE_KIND.TEXT, value});
}

function bytesFromBase64(base64) {
  if (typeof base64 !== 'string') throw invalid('bytes base64 must be a string');
  const decoded = base64Decode(base64);
  if (base64Encode(decoded) !== base64) throw invalid('bytes value must use canonical base64');
  return freeze({kind: VALUE_KIND.BYTES, base64});
}

function bytesValue(value) {
  let bytes;
  if (value instanceof ArrayBuffer) bytes = new Uint8Array(value);
  else if (ArrayBuffer.isView(value)) bytes = new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  else throw invalid('bytes value must be an ArrayBuffer or typed-array view');
  return bytesFromBase64(base64Encode(bytes));
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw invalid(`${label} must be a non-empty string`);
  return value;
}

function objectRef(imageId, objectId) {
  return freeze({kind: VALUE_KIND.REF, imageId: requiredText(imageId, 'imageId'), objectId: requiredText(objectId, 'objectId')});
}

function pinnedRef(imageId, objectId, revision) {
  if (!['string', 'number', 'bigint'].includes(typeof revision)) throw invalid('revision must be text or integer');
  if (typeof revision === 'number' && !Number.isSafeInteger(revision)) throw invalid('numeric revision must be a safe integer');
  const text = String(revision);
  if (text.length === 0) throw invalid('revision must not be empty');
  return freeze({kind: VALUE_KIND.PINNED_REF, imageId: requiredText(imageId, 'imageId'), objectId: requiredText(objectId, 'objectId'), revision: text});
}

function sameKeys(value, names) {
  const actual = Object.keys(value).sort();
  const expected = [...names].sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}

function canonicalizeValue(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw invalid('value must be a tagged record');
  switch (value.kind) {
    case VALUE_KIND.BOOLEAN:
      if (!sameKeys(value, ['kind', 'value'])) throw invalid('malformed boolean value');
      return booleanValue(value.value);
    case VALUE_KIND.INTEGER:
      if (!sameKeys(value, ['kind', 'value'])) throw invalid('malformed integer value');
      return integerValue(value.value);
    case VALUE_KIND.FLOAT64:
      if (!sameKeys(value, ['kind', 'bits'])) throw invalid('malformed float value');
      return float64FromBits(value.bits);
    case VALUE_KIND.TEXT:
      if (!sameKeys(value, ['kind', 'value'])) throw invalid('malformed text value');
      return textValue(value.value);
    case VALUE_KIND.BYTES:
