function compileWasmV1ModuleEntries(entries, {
  allowApply = false,
  optimizeClosures = false,
  intraModuleDirectCalls = false,
  intraModuleCallTargets = null,
} = {}) {
  if (!Array.isArray(entries) || entries.length === 0) throw new TypeError('WASM module entries must be a non-empty array');
  const normalizedEntries = entries.map(normalizeModuleEntry);
  const entryNames = new Set();
  const memberIndices = new Set();
  for (const entry of normalizedEntries) {
    if (entryNames.has(entry.entry)) throw new TypeError(`duplicate WASM export entry: ${entry.entry}`);
    if (memberIndices.has(entry.memberIndex)) throw new TypeError(`duplicate WASM member index: ${entry.memberIndex}`);
    entryNames.add(entry.entry);
    memberIndices.add(entry.memberIndex);
  }

  const effectiveEntries = optimizeClosures
    ? normalizedEntries.map((entry) => ({
      ...entry,
      program: optimizeNonEscapingClosures(entry.program).program,
    }))
    : normalizedEntries;
  const directCalls = (intraModuleDirectCalls || intraModuleCallTargets)
    ? planIntraModuleDirectCalls(effectiveEntries, {intraModuleCallTargets})
    : null;

  const literals = {values: [], keys: new Map()};
  const state = {
    sendSites: [],
    closureSites: [],
    effects: [],
    effectIndex: new WeakMap(),
    directCalls,
    directCallSites: new WeakMap(),
    intraModuleDirectCalls: [],
    currentEntryName: null,
  };
  const plans = [];

  for (const entry of effectiveEntries) {
    const program = entry.program;
    if (!program || !Array.isArray(program.parameters) || !Array.isArray(program.captures) || !Array.isArray(program.temporaries)) {
      throw new TypeError(`WASM module entry ${entry.entry} program must contain parameters, temporaries and captures arrays`);
    }
    const sendStart = state.sendSites.length;
    const closureStart = state.closureSites.length;
    state.currentEntryName = entry.entry;
    analyzeEffects(program.body, state, {tail: true, allowApply: allowApply || entry.allowApply});
    // Only snapshot captures become entry parameters. A cell capture is reached through the host
    // cell table, so it has no handle position anywhere in the ABI.
    const snapshotCaptures = program.captures.filter(({mode}) => mode !== 'cell');
    const captureIds = snapshotCaptures.map(({id}) => id);
    const {bindings: cellBindings, slots: cellSlots} = cellBindingsOf(program);
    plans.push({
      entry: entry.entry,
      memberIndex: entry.memberIndex,
      program,
      parameterCount: program.parameters.length,
      captureIds,
      captureIndex: new Map(captureIds.map((id, index) => [id, index])),
      cellBindings,
      cellSlots,
      sendSiteIndices: Array.from({length: state.sendSites.length - sendStart}, (_, offset) => sendStart + offset),
      closureSiteIndices: Array.from({length: state.closureSites.length - closureStart}, (_, offset) => closureStart + offset),
    });
  }

  const firstFunctionIndex = BASE_IMPORT_COUNT_V1 + state.effects.length;
  const bodies = plans.map((plan) => compileExpression(plan.program.body, {
    ...state,
    firstFunctionIndex,
    parameterCount: plan.parameterCount,
    captureIndex: plan.captureIndex,
    cellSlots: plan.cellSlots,
    literals,
  }));

  const effectTypes = state.effects.map(({arity}) => functionType(Array.from({length: arity}, () => I32), [I32]));
  const functionTypes = plans.map((plan) =>
    functionType(Array.from({length: 1 + plan.parameterCount + plan.captureIds.length}, () => I32), [I32]));
  const types = vector([
    functionType([I32], [I32]),
    functionType([I32, I32], [I32]),
    ...effectTypes,
    ...functionTypes,
  ]);
  const effectImports = state.effects.map((effect, effectIndex) => {
    const name = effect.kind === 'send'
      ? `send_site_${effect.kindIndex}`
      : `make_block_site_${effect.kindIndex}`;
    return functionImport(WASM_IMPORT_MODULE, name, 2 + effectIndex);
  });
  const imports = vector([
    functionImport(WASM_IMPORT_MODULE, 'literal', 0),
    functionImport(WASM_IMPORT_MODULE, 'integer_add', 1),
    functionImport(WASM_IMPORT_MODULE, 'equals', 1),
    functionImport(WASM_IMPORT_MODULE, 'is_true', 0),
    // Synchronous and cell-only. They resolve through the host's ActivationCells and raise if the
    // slot is not a cell, so no durable-environment lookup can answer them.
    functionImport(WASM_IMPORT_MODULE, 'cell_get', 0),
    functionImport(WASM_IMPORT_MODULE, 'cell_set', 1),
    ...effectImports,
  ]);
  const firstFunctionTypeIndex = 2 + state.effects.length;
  const functions = vector(plans.map((_, index) => [...u32(firstFunctionTypeIndex + index)]));
  const exports = vector(plans.map((plan, index) => functionExport(plan.entry, firstFunctionIndex + index)));
  const code = vector(bodies.map((bodyExpression) => {
    const functionBody = [0x00, ...bodyExpression, 0x0b];
    return [...u32(functionBody.length), ...functionBody];
  }));

  const functionDescriptors = Object.freeze(plans.map((plan) => Object.freeze({
    entry: plan.entry,
    memberIndex: plan.memberIndex,
    parameters: plan.parameterCount,
    captures: Object.freeze(plan.captureIds),
    cellBindings: plan.cellBindings,
    sendSiteIndices: Object.freeze(plan.sendSiteIndices),
    closureSiteIndices: Object.freeze(plan.closureSiteIndices),
  })));

  return Object.freeze({
    bytes: new Uint8Array([
      0x00, 0x61, 0x73, 0x6d,
      0x01, 0x00, 0x00, 0x00,
      ...section(1, types),
      ...section(2, imports),
      ...section(3, functions),
      ...section(7, exports),
      ...section(10, code),
    ]),
    literals: Object.freeze(literals.values),
    sendSites: Object.freeze(state.sendSites),
    closureSites: Object.freeze(state.closureSites),
    functions: functionDescriptors,
    intraModuleDirectCalls: Object.freeze([...state.intraModuleDirectCalls]),
  });
}

function compileWasmV1Module(program, options = {}) {
  const compiled = compileWasmV1ModuleEntries([{entry: WASM_ENTRY_V0, memberIndex: 0, program}], options);
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
    cellBindings: descriptor.cellBindings,
  });
}

function compileWasmV2Module(program, options = {}) {
  const compiled = compileWasmV1ModuleEntries(
    [{entry: WASM_ENTRY_V0, memberIndex: 0, program, allowApply: true}],
    {...options, allowApply: true},
  );
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
    cellBindings: descriptor.cellBindings,
  });
}

const lagrangeCodeV1ToWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V1) throw new TypeError(`source must be ${LAGRANGE_CODE_V1}`);
    const compiled = compileWasmV1Module(parseLagrangeCodeV1Program(source));
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_VALUE_HANDLE_ABI_V1,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: [],
      },
      metadata: {
        semanticRepresentation: LAGRANGE_CODE_V1,
      },
    });
  },
});

const lagrangeCodeV2ToWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V2) throw new TypeError(`source must be ${LAGRANGE_CODE_V2}`);
    const compiled = compileWasmV2Module(parseLagrangeCodeV2Program(source));
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_VALUE_HANDLE_ABI_V1,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: [],
      },
      metadata: {
        semanticRepresentation: LAGRANGE_CODE_V2,
      },
    });
  },
});

const lagrangeCodeV1GroupToWasmModuleCompiler = Object.freeze({
  async compile({group, members}) {
    if (group.policyId !== WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1) {
      throw new TypeError(`unsupported WASM compilation group policy: ${group.policyId}`);
    }
    if (group.options?.physicalLayout !== 'shared-module') {
      throw new TypeError('WASM shared-module compiler requires physicalLayout=shared-module');
    }
    const entries = members.map((source, memberIndex) => {
      if (source.representation !== LAGRANGE_CODE_V1 && source.representation !== LAGRANGE_CODE_V2) {
        throw new TypeError(`WASM group member ${memberIndex} must be ${LAGRANGE_CODE_V1}`);
      }
      const isV2 = source.representation === LAGRANGE_CODE_V2;
      return {
        entry: `run_${memberIndex}`,
        memberIndex: Number.isInteger(group.options?.memberIndices?.[memberIndex])
          ? group.options.memberIndices[memberIndex]
          : memberIndex,
        program: isV2 ? parseLagrangeCodeV2Program(source) : parseLagrangeCodeV1Program(source),
        allowApply: isV2,
        semanticBlockId: source.metadata?.semanticBlockId ?? null,
      };
    });
    const semanticRepresentation = members.some((source) => source.representation === LAGRANGE_CODE_V2)
      ? LAGRANGE_CODE_V2
      : LAGRANGE_CODE_V1;
    const compiled = compileWasmV1ModuleEntries(entries, {
      optimizeClosures: group.options?.optimizeClosures === true,
      intraModuleDirectCalls: group.options?.intraModuleDirectCalls === true,
      intraModuleCallTargets: group.options?.intraModuleCallTargets ?? null,
    });
    return Object.freeze({
      bytes: compiled.bytes,
      contract: {
        abi: WASM_VALUE_HANDLE_ABI_V1,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: [],
      },
      metadata: {
        semanticRepresentation,
        groupPolicyId: group.policyId,
        physicalLayout: 'shared-module',
        ...(compiled.intraModuleDirectCalls.length > 0
          ? {intraModuleDirectCalls: compiled.intraModuleDirectCalls}
          : {}),
      },
    });
  },
});

export {
  BASE_IMPORT_COUNT_V1,
  WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1,
  WasmV1TailEffectRestrictionError,
  compileWasmV1Module,
  compileWasmV1ModuleEntries,
  compileWasmV2Module,
  isWasmV1TailEffectRestrictionError,
  lagrangeCodeV1GroupToWasmModuleCompiler,
  lagrangeCodeV1ToWasmModuleCompiler,
  lagrangeCodeV2ToWasmModuleCompiler,
};

import {ensureCodeArtifact} from '../graph/ensure-records.js';
import {
  I32,
  functionExport,
  functionImport,
  functionType,
  s32,
  section,
  u32,
  vector,
} from './encoding.js';
import {LAGRANGE_CODE_V0, parseLagrangeCodeProgram} from '../code/lagrange-code-v0.js';
import {bindClosurePrototypes, describeWasmFunctionV2} from './function-contract.js';
import {WASM_MODULE_V2, moduleFunctionOf, readModuleDescriptor, soleModuleEntry} from './module-contract.js';
import {canonicalizeValue, isObjectRef, isReference, objectRef} from '../value/index.js';
import {
  WASM_ENTRY_V0,
  WASM_IMPORT_MODULE,
  WASM_VALUE_HANDLE_ABI_V0,
} from './abi.js';

const BASE_IMPORT_COUNT = 4;
const WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V0 = 'wasm-nested-block-tree/v0';









function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function collectLiteral(literals, value) {
  const normalized = canonicalizeValue(value);
  if (isReference(normalized)) throw new TypeError('WASM backend v0 does not embed reference literals; use arguments/captures instead');
  const key = JSON.stringify(normalized);
  const existing = literals.keys.get(key);
  if (existing !== undefined) return existing;
  const index = literals.values.length;
  literals.values.push(normalized);
  literals.keys.set(key, index);
  return index;
}

function collectSendSite(state, expression) {
  const message = canonicalizeValue(expression.message);
  if (isReference(message)) throw new TypeError('WASM backend v0 does not place reference messages in module metadata');
  const kindIndex = state.sendSites.length;
  state.sendSites.push(Object.freeze({
    languageId: requiredText(expression.languageId, 'send languageId'),
    message,
    arity: expression.arguments.length,
  }));
  const effectIndex = state.effects.length;
  state.effects.push(Object.freeze({kind: 'send', kindIndex, arity: 1 + expression.arguments.length}));
  state.effectIndex.set(expression, effectIndex);
}

function normalizeClosureCapture(capture, index) {
  exactKeys(capture, ['id', 'name', 'value'], `WASM closure capture ${index}`);
  return Object.freeze({
    id: requiredText(capture.id, `WASM closure capture ${index} id`),
    name: requiredText(capture.name, `WASM closure capture ${index} name`),
  });
}

function collectClosureSite(state, expression) {
  if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
  const captures = Object.freeze(expression.captures.map(normalizeClosureCapture));
  const kindIndex = state.closureSites.length;
  state.closureSites.push(Object.freeze({
    blockId: requiredText(expression.blockId, 'WASM semantic block id'),
    captures,
  }));
  const effectIndex = state.effects.length;
  state.effects.push(Object.freeze({kind: 'closure', kindIndex, arity: captures.length}));
  state.effectIndex.set(expression, effectIndex);
}

function analyzeEffects(expression, state, {tail = false} = {}) {
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) throw new TypeError('WASM compiler expression must be an object');
  switch (expression.op) {
    case 'literal':
    case 'argument':
    case 'receiver':
    case 'binding':
      return;
    case 'integer-add':
    case 'equals':
      analyzeEffects(expression.left, state);
      analyzeEffects(expression.right, state);
      return;
    case 'if':
      analyzeEffects(expression.condition, state);
      analyzeEffects(expression.then, state, {tail});
      analyzeEffects(expression.else, state, {tail});
      return;
    case 'send':
      if (!tail) throw new TypeError('WASM backend v0 supports message sends only in tail position');
      if (!Array.isArray(expression.arguments)) throw new TypeError('WASM send arguments must be an array');
      analyzeEffects(expression.receiver, state);
      for (const argument of expression.arguments) analyzeEffects(argument, state);
      collectSendSite(state, expression);
      return;
    case 'block':
      if (!tail) throw new TypeError('WASM backend v0 supports nested Block creation only in tail position');
      if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
      expression.captures.forEach((capture, index) => {
        normalizeClosureCapture(capture, index);
        analyzeEffects(capture.value, state);
      });
      collectClosureSite(state, expression);
      return;
    default:
      throw new TypeError(`WASM backend v0 does not support semantic op: ${expression.op}`);
  }
}

function compileExpression(expression, context) {
  switch (expression.op) {
    case 'literal': {
      const index = collectLiteral(context.literals, expression.value);
      return [0x41, ...s32(index), 0x10, ...u32(0)];
    }
    case 'argument': {
      if (!Number.isInteger(expression.index) || expression.index < 0 || expression.index >= context.parameterCount) {
        throw new TypeError(`WASM argument index out of range: ${expression.index}`);
      }
      return [0x20, ...u32(1 + expression.index)];
    }
    case 'receiver':
      return [0x20, ...u32(0)];
    case 'binding': {
      const captureIndex = context.captureIndex.get(expression.id);
      if (captureIndex === undefined) throw new TypeError(`WASM binding is not declared as a capture: ${expression.id}`);
      return [0x20, ...u32(1 + context.parameterCount + captureIndex)];
    }
    case 'integer-add':
      return [...compileExpression(expression.left, context), ...compileExpression(expression.right, context), 0x10, ...u32(1)];
    case 'equals':
      return [...compileExpression(expression.left, context), ...compileExpression(expression.right, context), 0x10, ...u32(2)];
    case 'if':
      return [
        ...compileExpression(expression.condition, context),
        0x10, ...u32(3),
        0x04, I32,
        ...compileExpression(expression.then, context),
        0x05,
        ...compileExpression(expression.else, context),
        0x0b,
      ];
    case 'send':
      return [
        ...compileExpression(expression.receiver, context),
        ...expression.arguments.flatMap((argument) => compileExpression(argument, context)),
        0x10, ...u32(BASE_IMPORT_COUNT + context.effectIndex.get(expression)),
      ];
    case 'block':
      return [
        ...expression.captures.flatMap((capture) => compileExpression(capture.value, context)),
        0x10, ...u32(BASE_IMPORT_COUNT + context.effectIndex.get(expression)),
      ];
    default:
      throw new TypeError(`WASM backend v0 does not support semantic op: ${expression.op}`);
  }
}

function normalizeModuleEntry(value, index) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`WASM module entry ${index} must be an object`);
  const entry = requiredText(value.entry, `WASM module entry ${index} name`);
  if (!Number.isInteger(value.memberIndex) || value.memberIndex < 0) {
    throw new TypeError(`WASM module entry ${index} memberIndex must be a non-negative integer`);
  }
  return Object.freeze({entry, memberIndex: value.memberIndex, program: value.program});
}

function compileWasmModuleEntries(entries) {
  if (!Array.isArray(entries) || entries.length === 0) throw new TypeError('WASM module entries must be a non-empty array');
  const normalizedEntries = entries.map(normalizeModuleEntry);
  const entryNames = new Set();
  const memberIndices = new Set();
  for (const entry of normalizedEntries) {
    if (entryNames.has(entry.entry)) throw new TypeError(`duplicate WASM export entry: ${entry.entry}`);
    if (memberIndices.has(entry.memberIndex)) throw new TypeError(`duplicate WASM member index: ${entry.memberIndex}`);
    entryNames.add(entry.entry);
    memberIndices.add(entry.memberIndex);
  }

  const literals = {values: [], keys: new Map()};
  const state = {sendSites: [], closureSites: [], effects: [], effectIndex: new WeakMap()};
  const plans = [];

  for (const entry of normalizedEntries) {
    const program = entry.program;
    if (!program || !Array.isArray(program.parameters) || !Array.isArray(program.captures)) {
      throw new TypeError(`WASM module entry ${entry.entry} program must contain parameters and captures arrays`);
    }
    const sendStart = state.sendSites.length;
    const closureStart = state.closureSites.length;
    analyzeEffects(program.body, state, {tail: true});
    const parameterCount = program.parameters.length;
    const captureIds = program.captures.map(({id}) => id);
    const captureIndex = new Map(captureIds.map((id, captureIndexValue) => [id, captureIndexValue]));
    plans.push({
      entry: entry.entry,
      memberIndex: entry.memberIndex,
      program,
      parameterCount,
      captureIds,
      captureIndex,
      sendSiteIndices: Array.from({length: state.sendSites.length - sendStart}, (_, offset) => sendStart + offset),
      closureSiteIndices: Array.from({length: state.closureSites.length - closureStart}, (_, offset) => closureStart + offset),
    });
  }

  const bodies = plans.map((plan) => compileExpression(plan.program.body, {
    ...state,
    parameterCount: plan.parameterCount,
    captureIndex: plan.captureIndex,
    literals,
  }));

  const effectTypes = state.effects.map(({arity}) => functionType(Array.from({length: arity}, () => I32), [I32]));
  const functionTypes = plans.map((plan) =>
    functionType(Array.from({length: 1 + plan.parameterCount + plan.captureIds.length}, () => I32), [I32]));
  const types = vector([
    functionType([I32], [I32]),
    functionType([I32, I32], [I32]),
    ...effectTypes,
    ...functionTypes,
  ]);
  const effectImports = state.effects.map((effect, effectIndex) => {
    const name = effect.kind === 'send'
      ? `send_site_${effect.kindIndex}`
      : `make_block_site_${effect.kindIndex}`;
    return functionImport(WASM_IMPORT_MODULE, name, 2 + effectIndex);
  });
  const imports = vector([
    functionImport(WASM_IMPORT_MODULE, 'literal', 0),
    functionImport(WASM_IMPORT_MODULE, 'integer_add', 1),
    functionImport(WASM_IMPORT_MODULE, 'equals', 1),
    functionImport(WASM_IMPORT_MODULE, 'is_true', 0),
    ...effectImports,
  ]);
  const firstFunctionTypeIndex = 2 + state.effects.length;
  const functions = vector(plans.map((_, index) => [...u32(firstFunctionTypeIndex + index)]));
  const firstFunctionIndex = BASE_IMPORT_COUNT + state.effects.length;
  const exports = vector(plans.map((plan, index) => functionExport(plan.entry, firstFunctionIndex + index)));
  const code = vector(bodies.map((bodyExpression) => {
    const functionBody = [0x00, ...bodyExpression, 0x0b];
    return [...u32(functionBody.length), ...functionBody];
  }));

  const functionDescriptors = Object.freeze(plans.map((plan) => Object.freeze({
    entry: plan.entry,
    memberIndex: plan.memberIndex,
    parameters: plan.parameterCount,
    captures: Object.freeze(plan.captureIds),
    sendSiteIndices: Object.freeze(plan.sendSiteIndices),
    closureSiteIndices: Object.freeze(plan.closureSiteIndices),
  })));

  return Object.freeze({
    bytes: new Uint8Array([
      0x00, 0x61, 0x73, 0x6d,
      0x01, 0x00, 0x00, 0x00,
      ...section(1, types),
      ...section(2, imports),
      ...section(3, functions),
      ...section(7, exports),
      ...section(10, code),
    ]),
    literals: Object.freeze(literals.values),
    sendSites: Object.freeze(state.sendSites),
    closureSites: Object.freeze(state.closureSites),
    functions: functionDescriptors,
  });
}

function compileWasmModule(program) {
  const compiled = compileWasmModuleEntries([{entry: WASM_ENTRY_V0, memberIndex: 0, program}]);
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
  });
}

const lagrangeCodeV0ToWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V0) throw new TypeError(`source must be ${LAGRANGE_CODE_V0}`);
    const program = parseLagrangeCodeProgram(source);
    const compiled = compileWasmModule(program);
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_VALUE_HANDLE_ABI_V0,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: [],
      },
      metadata: {
        semanticRepresentation: LAGRANGE_CODE_V0,
      },
    });
  },
});

const lagrangeCodeGroupToWasmModuleCompiler = Object.freeze({
  async compile({group, members}) {
    if (group.policyId !== WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V0) {
      throw new TypeError(`unsupported WASM compilation group policy: ${group.policyId}`);
    }
    if (group.options?.physicalLayout !== 'shared-module') {
      throw new TypeError('WASM shared-module compiler requires physicalLayout=shared-module');
    }
    const entries = members.map((source, memberIndex) => {
      if (source.representation !== LAGRANGE_CODE_V0) {
        throw new TypeError(`WASM group member ${memberIndex} must be ${LAGRANGE_CODE_V0}`);
      }
      return {
        entry: `run_${memberIndex}`,
        memberIndex,
        program: parseLagrangeCodeProgram(source),
      };
    });
    const compiled = compileWasmModuleEntries(entries);
    return Object.freeze({
      bytes: compiled.bytes,
      contract: {
        abi: WASM_VALUE_HANDLE_ABI_V0,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: [],
      },
      metadata: {
        semanticRepresentation: LAGRANGE_CODE_V0,
        groupPolicyId: group.policyId,
        physicalLayout: 'shared-module',
      },
    });
  },
});

function normalizePrototypeMap(blockPrototypes) {
  if (!blockPrototypes || typeof blockPrototypes !== 'object' || Array.isArray(blockPrototypes)) {
    throw new TypeError('blockPrototypes must be an object keyed by semantic block id');
  }
  const result = new Map();
  for (const [blockId, value] of Object.entries(blockPrototypes)) {
    requiredText(blockId, 'block prototype id');
    const ref = canonicalizeValue(value);
    if (!isObjectRef(ref)) throw new TypeError(`block prototype ${blockId} must be an unpinned object ref`);
    result.set(blockId, ref);
  }
  return result;
}

// The module's function table is read through the canonical accessor (either durable version);
// this is the compile-side counterpart of the executors' readModuleContract and never touches the
// representation schema itself.
function moduleFunctionDescriptor(moduleArtifact, entry) {
  return moduleFunctionOf(readModuleDescriptor(moduleArtifact), {entry});
}

// The function artifact a compilation selects: described ONCE by the function-contract owner
// (wasm-function/v2). Nothing module-owned is copied onto the function.
function describeWasmFunctionArtifact({
  functionId,
  languageId,
  semanticRef,
  moduleRef,
  descriptor,
  closurePrototypes,
  prototypeRefs = [],
}) {
  return describeWasmFunctionV2({
    functionId,
    languageId,
    semanticRef,
    moduleRef,
    entry: descriptor.entry,
    closurePrototypes,
    prototypeRefs,
  });
}

async function assembleWasmFunctionArtifact({
  images,
  semanticRef,
  moduleRef,
  functionId,
  entry,
  blockPrototypes = {},
} = {}) {
  if (!images || typeof images.getCodeArtifact !== 'function' || typeof images.putCodeArtifact !== 'function' || typeof images.getBlock !== 'function') {
    throw new TypeError('images service with code artifact and Block access is required');
  }
  const semantic = await images.getCodeArtifact(semanticRef.imageId, semanticRef.objectId);
  if (!semantic || semantic.representation !== LAGRANGE_CODE_V0) throw new TypeError(`semanticRef must reference ${LAGRANGE_CODE_V0}`);
  const normalizedModuleRef = canonicalizeValue(moduleRef);
  if (!isObjectRef(normalizedModuleRef)) throw new TypeError('moduleRef must be an unpinned object ref');
  const moduleArtifact = await images.getCodeArtifact(normalizedModuleRef.imageId, normalizedModuleRef.objectId);
  if (!moduleArtifact) throw new TypeError('moduleRef must reference a WASM module artifact');
  const moduleDescriptor = readModuleDescriptor(moduleArtifact);
  const descriptor = moduleFunctionOf(moduleDescriptor, {entry: requiredText(entry, 'WASM function entry')});
  const {closurePrototypes, prototypeRefs} = bindClosurePrototypes({
    descriptor,
    closureSites: moduleDescriptor.closureSites,
    prototypes: normalizePrototypeMap(blockPrototypes),
  });
  for (const ref of prototypeRefs) {
    if (!await images.getBlock(ref.imageId, ref.objectId)) {
      throw new TypeError(`WASM Block prototype not found: ${ref.imageId}/${ref.objectId}`);
    }
  }

  // The complete wasm-function/v2 contract, in one place. A caller deciding whether an existing
  // artifact may be reused compares against this same description, so "exact" cannot drift apart
  // from what assembly would actually write.
  const input = describeWasmFunctionArtifact({
    functionId,
    languageId: semantic.languageId,
    semanticRef,
    moduleRef: normalizedModuleRef,
    descriptor,
    closurePrototypes,
    prototypeRefs,
  });
  // Ensure-exact-or-create, like every other deterministic-id write in this substrate. The function
  // id is derived, so a commit whose acknowledgement was lost would otherwise make an identical
  // retry collide with the artifact it had just written. `ensureWasmFunction` performs a stricter
  // describe-based check before calling here; the nested-tree path calls this directly and has no
  // such caller-side guard.
  const functionArtifact = await ensureCodeArtifact(images, semanticRef.imageId, input);
  return Object.freeze({moduleArtifact, functionArtifact});
}

async function compileWasmFunctionArtifact({
  images,
  compilation,
  semanticRef,
  moduleId,
  functionId,
  blockPrototypes = {},
} = {}) {
  if (!compilation || typeof compilation.compileArtifact !== 'function') throw new TypeError('compilation service is required');
  const moduleArtifact = await compilation.compileArtifact(semanticRef, {
    targetRepresentation: WASM_MODULE_V2,
    id: moduleId,
  });
  return await assembleWasmFunctionArtifact({
    images,
    semanticRef,
    moduleRef: objectRef(moduleArtifact.imageId, moduleArtifact.id),
    functionId,
    entry: soleModuleEntry(readModuleDescriptor(moduleArtifact)),
    blockPrototypes,
  });
}

export {
  WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V0,
  assembleWasmFunctionArtifact,
  describeWasmFunctionArtifact,
  moduleFunctionDescriptor,
  compileWasmFunctionArtifact,
  compileWasmModule,
  compileWasmModuleEntries,
  lagrangeCodeGroupToWasmModuleCompiler,
  lagrangeCodeV0ToWasmModuleCompiler,
};

// WebAssembly binary-format encoders, shared by the v0 and v1 backends.
//
// Extracted verbatim so the v1 backend can be a separate module rather than a set of branches
// inside the v0 one. ADR 0043's WASM lane advances the ABI, and the surest way to leave
// lagrange-value-handle/v0 byte-identical is for its compiler not to change at all.
const I32 = 0x7f;
const FUNC = 0x60;

function u32(value) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError('u32 LEB value must be a non-negative integer');
  const out = [];
  let current = value >>> 0;
  do {
    let byte = current & 0x7f;
    current >>>= 7;
    if (current !== 0) byte |= 0x80;
    out.push(byte);
  } while (current !== 0);
  return out;
}

function s32(value) {
  if (!Number.isInteger(value)) throw new TypeError('s32 LEB value must be an integer');
  const out = [];
  let current = value | 0;
  while (true) {
    let byte = current & 0x7f;
    current >>= 7;
    const sign = byte & 0x40;
    const done = (current === 0 && sign === 0) || (current === -1 && sign !== 0);
    if (!done) byte |= 0x80;
    out.push(byte);
    if (done) return out;
  }
}

function text(value) {
  const bytes = [...new TextEncoder().encode(value)];
  return [...u32(bytes.length), ...bytes];
}

function vector(entries) {
  return [...u32(entries.length), ...entries.flat()];
}

function section(id, payload) {
  return [id, ...u32(payload.length), ...payload];
}

function functionType(parameters, results) {
  return [FUNC, ...vector(parameters.map((value) => [value])), ...vector(results.map((value) => [value]))];
}

function functionImport(module, name, typeIndex) {
  return [...text(module), ...text(name), 0x00, ...u32(typeIndex)];
}

function functionExport(name, functionIndex) {
  return [...text(name), 0x00, ...u32(functionIndex)];
}

export {
  FUNC,
  I32,
  functionExport,
  functionImport,
  functionType,
  s32,
  section,
  text,
  u32,
  vector,
};

import {assertWasmFunctionArtifactAnyVersion, functionModuleRef, resolveFunctionContract} from './function-contract.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {ValueHandleArena, WASM_IMPORT_MODULE, WASM_VALUE_HANDLE_ABI_V1} from './abi.js';
import {readCellThrough, writeCellThrough} from './cell-access.js';
import {WasmModuleCache} from './module-cache.js';
import {readModuleDescriptor, readModuleImplementationBytes} from './module-contract.js';
import {WASM_INSTANCE_REUSE_STATELESS_V0, WasmInstancePool} from './instance-pool.js';

// The lagrange-value-handle/v1 executor. Separate from the v0 one on purpose: every metadata
// normalizer here branches on the v1 ABI, and the v0 normalizers never learn to accept the v1
// shape. An artifact means exactly what its declared ABI says it means.
function requireNonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeLiterals(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract literals must be an array');
  return Object.freeze(value.map((literal) => canonicalizeValue(literal)));
}

function normalizeIndexList(value, limit, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((entry, index) => {
    const site = requireNonNegativeInteger(entry, `${label} ${index}`);
    if (site >= limit) throw new TypeError(`${label} ${index} is out of range`);
    if (seen.has(site)) throw new TypeError(`${label} contains duplicate index ${site}`);
    seen.add(site);
    return site;
  }));
}

// Defence in depth: general metadata normalization already rejects object references, but this is
// an invariant of the ABI reader and the new one should not be laxer than the frozen one.
function assertNonReferenceMessage(message, index) {
  if (isReference(message)) throw new TypeError(`WASM send site ${index} message must not hide a graph reference`);
  return message;
}

function normalizeSendSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract sendSites must be an array');
  return Object.freeze(value.map((site, index) => {
    if (site && typeof site === 'object' && !Array.isArray(site) && site.kind === 'apply') {
      exactKeys(site, ['kind', 'arity'], `WASM apply site ${index}`);
      return Object.freeze({
        kind: 'apply',
        arity: requireNonNegativeInteger(site.arity, `WASM apply site ${index} arity`),
      });
    }
    exactKeys(site, ['languageId', 'message', 'arity'], `WASM send site ${index}`);
    return Object.freeze({
      languageId: requiredText(site.languageId, `WASM send site ${index} languageId`),
      message: assertNonReferenceMessage(canonicalizeValue(site.message), index),
      arity: requireNonNegativeInteger(site.arity, `WASM send site ${index} arity`),
    });
  }));
}

// v1 closure sites carry a per-capture mode. This normalizer requires it: a v0-shaped site reaching
// a v1 module is a mismatch, not something to interpret generously.
function normalizeClosureSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract closureSites must be an array');
  return Object.freeze(value.map((site, siteIndex) => {
    exactKeys(site, ['blockId', 'captures'], `WASM closure site ${siteIndex}`);
    requiredText(site.blockId, `WASM closure site ${siteIndex} blockId`);
    if (!Array.isArray(site.captures)) throw new TypeError(`WASM closure site ${siteIndex} captures must be an array`);
    const captures = Object.freeze(site.captures.map((capture, captureIndex) => {
      const label = `WASM closure site ${siteIndex} capture ${captureIndex}`;
      exactKeys(capture, ['id', 'mode', 'name'], label);
      const mode = requiredText(capture.mode, `${label} mode`);
      if (mode !== 'snapshot' && mode !== 'cell') throw new TypeError(`${label} mode must be snapshot or cell`);
      return Object.freeze({
        id: requiredText(capture.id, `${label} id`),
        name: requiredText(capture.name, `${label} name`),
        mode,
      });
    }));
    return Object.freeze({blockId: site.blockId, captures});
  }));
}

function normalizeCellBindings(value, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((binding, index) => {
    exactKeys(binding, ['id', 'name', 'source'], `${label} ${index}`);
    const id = requiredText(binding.id, `${label} ${index} id`);
    if (seen.has(id)) throw new TypeError(`${label} declares duplicate cell binding ${id}`);
    seen.add(id);
    const source = requiredText(binding.source, `${label} ${index} source`);
    if (source !== 'temporary' && source !== 'capture') {
      throw new TypeError(`${label} ${index} source must be temporary or capture`);
    }
    return Object.freeze({id, name: requiredText(binding.name, `${label} ${index} name`), source});
  }));
}

function normalizeCaptureIds(value, label = 'WASM function metadata.captures') {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  return Object.freeze(value.map((id, index) => requiredText(id, `${label} ${index}`)));
}



function normalizeModuleFunctions(value, sendSites, closureSites) {
  if (value === undefined) return null;
  if (!Array.isArray(value) || value.length === 0) {
    throw new TypeError('WASM module contract functions must be a non-empty array');
  }
  const entries = new Set();
  const memberIndices = new Set();
  return Object.freeze(value.map((descriptor, index) => {
    exactKeys(
      descriptor,
      ['entry', 'memberIndex', 'parameters', 'captures', 'cellBindings', 'sendSiteIndices', 'closureSiteIndices'],
      `WASM module function ${index}`,
    );
    const entry = requiredText(descriptor.entry, `WASM module function ${index} entry`);
    const memberIndex = requireNonNegativeInteger(descriptor.memberIndex, `WASM module function ${index} memberIndex`);
    if (entries.has(entry)) throw new TypeError(`duplicate WASM module function entry: ${entry}`);
    if (memberIndices.has(memberIndex)) throw new TypeError(`duplicate WASM module function memberIndex: ${memberIndex}`);
    entries.add(entry);
    memberIndices.add(memberIndex);
    return Object.freeze({
      entry,
      memberIndex,
      parameters: requireNonNegativeInteger(descriptor.parameters, `WASM module function ${index} parameters`),
      captures: normalizeCaptureIds(descriptor.captures, `WASM module function ${index} captures`),
      cellBindings: normalizeCellBindings(descriptor.cellBindings, `WASM module function ${index} cellBindings`),
      sendSiteIndices: normalizeIndexList(descriptor.sendSiteIndices, sendSites.length, `WASM module function ${index} sendSiteIndices`),
      closureSiteIndices: normalizeIndexList(descriptor.closureSiteIndices, closureSites.length, `WASM module function ${index} closureSiteIndices`),
    });
  }));
}



function recordPending(pending, effect) {
  if (pending.effect !== null) throw new TypeError('WASM activation attempted more than one pending host effect');
  pending.effect = Object.freeze(effect);
  return 0;
}

function createRebindableHostEnvironment(literals, sendSites, closureSites) {
  const holder = {current: null};
  const current = () => {
    if (!holder.current) throw new TypeError('WASM instance host environment is not bound to an activation');
    return holder.current;
  };
  const lagrange = {
    literal(index) {
      const state = current();
      if (!Number.isInteger(index) || index < 0 || index >= literals.length) throw new TypeError(`WASM literal index out of range: ${index}`);
      return state.arena.put(literals[index]);
    },
    integer_add(left, right) {
      return current().arena.integerAdd(left, right);
    },
    equals(left, right) {
      return current().arena.equals(left, right);
    },
    is_true(handle) {
      return current().arena.isTrue(handle);
    },
    // Synchronous, and resolved through *this activation's* descriptor. A slot index means nothing
    // on its own: a shared module holds several semantic Blocks whose static binding ids all start
    // at `root:`, so a module-global table would confuse unrelated slots that share a name.
    cell_get(slot) {
      const state = current();
      return state.arena.put(readCellThrough(state.readCell, state.cellBinding(slot)));
    },
    // Assignment is an expression, so this returns the handle of the value written.
    cell_set(slot, handle) {
      const state = current();
      const binding = state.cellBinding(slot);
      const value = state.arena.get(handle, `WASM cell_set value handle for slot ${slot}`);
      return state.arena.put(writeCellThrough(state.writeCell, binding, value));
    },
  };

  sendSites.forEach((site, siteIndex) => {
    lagrange[`send_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeSendSites.has(siteIndex)) throw new TypeError(`inactive WASM send site invoked: ${siteIndex}`);
      if (handles.length !== 1 + site.arity) {
        throw new TypeError(`WASM send site ${siteIndex} expected ${1 + site.arity} handles, received ${handles.length}`);
      }
      if (site.kind === 'apply') {
        return recordPending(state.pending, {
          kind: 'apply',
          request: Object.freeze({
            callee: state.arena.get(handles[0], `WASM apply site ${siteIndex} callee handle`),
            arguments: Object.freeze(handles.slice(1).map((handle, argumentIndex) =>
              state.arena.get(handle, `WASM apply site ${siteIndex} argument ${argumentIndex} handle`))),
          }),
        });
      }
      return recordPending(state.pending, {
        kind: 'send',
        request: Object.freeze({
          languageId: site.languageId,
          receiver: state.arena.get(handles[0], `WASM send site ${siteIndex} receiver handle`),
          message: site.message,
          arguments: Object.freeze(handles.slice(1).map((handle, argumentIndex) =>
            state.arena.get(handle, `WASM send site ${siteIndex} argument ${argumentIndex} handle`))),
        }),
      });
    };
  });

  closureSites.forEach((site, siteIndex) => {
    // Arity counts snapshot captures only. A cell capture occupies no handle position, so there is
    // no channel through which a snapshot of a mutable cell could enter the closure — the host
    // reconstructs the full capture list, marking cell captures for createClosure to resolve
    // against the declaring frame.
    const snapshotCaptures = site.captures.filter(({mode}) => mode === 'snapshot');
    lagrange[`make_block_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeClosureSites.has(siteIndex)) throw new TypeError(`inactive WASM closure site invoked: ${siteIndex}`);
      if (handles.length !== snapshotCaptures.length) {
        throw new TypeError(`WASM closure site ${siteIndex} expected ${snapshotCaptures.length} handles, received ${handles.length}`);
      }
      const prototype = state.closurePrototypes.get(siteIndex);
      if (!prototype) throw new TypeError(`WASM closure prototype missing at execution: ${site.blockId}`);
      let handleIndex = 0;
      const captures = Object.freeze(site.captures.map((capture) => {
        if (capture.mode === 'cell') {
          return Object.freeze({id: capture.id, name: capture.name, mode: 'cell'});
        }
        const handle = handles[handleIndex];
        handleIndex += 1;
        return Object.freeze({
          id: capture.id,
          name: capture.name,
          mode: 'snapshot',
          value: state.arena.get(handle, `WASM closure site ${siteIndex} capture ${capture.id} handle`),
        });
      }));
      return recordPending(state.pending, {kind: 'closure', request: Object.freeze({prototype, captures})});
    };
  });

  return Object.freeze({
    imports: {[WASM_IMPORT_MODULE]: lagrange},
    // Lexical cell access is per-activation state, exactly like the value arena and the active
    // effect sites, so a pooled instance rebinds all of it on every checkout.
    bind({arena, descriptor, closurePrototypes, pending, readCell, writeCell}) {
      if (holder.current) throw new TypeError('WASM instance host environment is already bound');
      const cellBindings = descriptor.cellBindings;
      holder.current = {
        arena,
        closurePrototypes,
        pending,
        readCell,
        writeCell,
        cellBinding(slot) {
          if (!Number.isInteger(slot) || slot < 0 || slot >= cellBindings.length) {
            throw new TypeError(`WASM cell slot out of range for ${descriptor.entry}: ${slot}`);
          }
          return cellBindings[slot];
        },
        activeSendSites: new Set(descriptor.sendSiteIndices),
        activeClosureSites: new Set(descriptor.closureSiteIndices),
      };
    },
    // Clears everything, so nothing from one activation is reachable from the next checkout of a
    // pooled instance.
    unbind() {
      if (!holder.current) throw new TypeError('WASM instance host environment is not bound');
      holder.current = null;
    },
  });
}

function instanceReuseMode(moduleArtifact) {
  const mode = moduleArtifact.metadata?.instanceReuse;
  if (mode === undefined) return null;
  if (mode !== WASM_INSTANCE_REUSE_STATELESS_V0) throw new TypeError(`unsupported WASM instance reuse contract: ${mode}`);
  return mode;
}

async function createInstanceSlot(compiledModule, literals, sendSites, closureSites) {
  const host = createRebindableHostEnvironment(literals, sendSites, closureSites);
  const instance = await WebAssembly.instantiate(compiledModule, host.imports);
  return Object.freeze({instance, host});
}

async function acquireInstance({moduleArtifact, compiledModule, instancePool, literals, sendSites, closureSites}) {
  if (instanceReuseMode(moduleArtifact) === WASM_INSTANCE_REUSE_STATELESS_V0) {
    return await instancePool.acquire(
      moduleArtifact,
      async () => await createInstanceSlot(compiledModule, literals, sendSites, closureSites),
    );
  }
  const slot = await createInstanceSlot(compiledModule, literals, sendSites, closureSites);
  let released = false;
  return Object.freeze({
    slot,
    release() {
      if (released) throw new TypeError('WASM one-shot instance lease already released');
      released = true;
    },
  });
}

function requireCellOperations(context) {
  for (const operation of ['readCell', 'writeCell', 'declareTemporaries']) {
    if (typeof context[operation] !== 'function') {
      throw new TypeError(`the lagrange-value-handle/v1 ABI requires the ${operation} execution operation`);
    }
  }
}

function createWasmFunctionV1CellExecutor({
  moduleCache = new WasmModuleCache(),
  instancePool = new WasmInstancePool(),
} = {}) {
  if (!moduleCache || typeof moduleCache.get !== 'function' || typeof moduleCache.stats !== 'function') {
    throw new TypeError('moduleCache must be a WasmModuleCache-compatible object');
  }
  if (!instancePool || typeof instancePool.acquire !== 'function' || typeof instancePool.stats !== 'function') {
    throw new TypeError('instancePool must be a WasmInstancePool-compatible object');
  }
  return Object.freeze({
    moduleCache,
    instancePool,
    async execute({activation, code}, context, resolved = null) {
      if (!resolved) assertWasmFunctionArtifactAnyVersion(code);
      requireCellOperations(context);
      const moduleRef = functionModuleRef(code);
      const moduleArtifact = resolved?.moduleArtifact ?? await context.images.getCodeArtifact(moduleRef.imageId, moduleRef.objectId);
      if (!moduleArtifact) throw new TypeError(`WASM module not found: ${moduleRef.imageId}/${moduleRef.objectId}`);
      const contract = readModuleDescriptor(moduleArtifact);
      const resolveImplementation = (ref) => context.images.getCodeArtifact(ref.imageId, ref.objectId);
      if (contract.abi !== WASM_VALUE_HANDLE_ABI_V1) {
        throw new TypeError(`WASM module ABI does not match ${WASM_VALUE_HANDLE_ABI_V1}`);
      }
      const literals = normalizeLiterals(contract.literals);
      const sendSites = normalizeSendSites(contract.sendSites);
      const closureSites = normalizeClosureSites(contract.closureSites);
      const fn = resolveFunctionContract(
        code,
        Object.freeze({...contract, functions: normalizeModuleFunctions(contract.functions, sendSites, closureSites), closureSites}),
        resolved?.selection ? {selection: resolved.selection} : {},
      );
      const {descriptor, closurePrototypes} = fn;
      const parameterCount = descriptor.parameters;
      const captureIds = descriptor.captures;
      if (activation.arguments.length !== parameterCount) {
        throw new TypeError(`WASM activation expected ${parameterCount} arguments, received ${activation.arguments.length}`);
      }
      const compiledModule = await moduleCache.get(moduleArtifact, () => readModuleImplementationBytes(moduleArtifact, {resolveImplementation}));

      // Only temporaries: this activation declares the cells it owns. A cell capture already
      // exists in the frame that declared it, and declaring one here would shadow it with a fresh
      // empty cell. Declaring host-side rather than in the guest is what keeps frame machinery out
      // of the ABI — the module knows slot indices, the host owns which cell each one is.
      context.declareTemporaries(descriptor.cellBindings.filter(({source}) => source === 'temporary'));

      const arena = new ValueHandleArena({receiverAbsent: activation.receiver === null});
      const receiverHandle = activation.receiver === null ? 0 : arena.put(activation.receiver);
      const argumentHandles = activation.arguments.map((value) => arena.put(value));
      // Snapshot captures are still resolved before entry and passed as handles, exactly as in v0.
      // Cell captures are not resolved here at all; they are reached through cell_get/cell_set.
      const captureHandles = [];
      for (const bindingId of captureIds) captureHandles.push(arena.put(await context.lookupBinding(bindingId)));
      const pending = {effect: null};

      const lease = await acquireInstance({
        moduleArtifact,
        compiledModule,
        instancePool,
        literals,
        sendSites,
        closureSites,
      });
      let bound = false;
      let released = false;
      let result;
      let tailEffect = null;
      try {
        context.checkCancelled?.();
        context.recordWasmState?.({
          wasmState: 'running',
          suspensionCount: 0,
          resumedCount: 0,
          lastSuspension: null,
        });
        lease.slot.host.bind({
          arena,
          descriptor,
          closurePrototypes,
          pending,
          readCell: context.readCell,
          writeCell: context.writeCell,
        });
        bound = true;
        const entry = lease.slot.instance.exports[fn.entry];
        if (typeof entry !== 'function') throw new TypeError(`WASM function entry not found: ${fn.entry}`);
        const resultHandle = entry(receiverHandle, ...argumentHandles, ...captureHandles);

        if (pending.effect !== null) {
          if (resultHandle !== 0) throw new TypeError('WASM tail host effect must return reserved handle 0');
          tailEffect = pending.effect;
        } else {
          result = arena.get(resultHandle, 'WASM result handle');
        }

        lease.slot.host.unbind();
        bound = false;
        context.recordWasmState?.({wasmState: 'completed'});
        lease.release();
        released = true;
      } catch (error) {
        try {
          context.recordWasmState?.({wasmState: 'retired', event: 'retire'});
        } catch {}
        if (bound) {
          try { lease.slot.host.unbind(); } catch {}
          bound = false;
        }
        if (!released) {
          try { lease.release({retire: true}); } catch {}
          released = true;
        }
        throw error;
      }

      if (tailEffect !== null) {
        if (tailEffect.kind === 'send') {
          if (typeof context.sendMessage !== 'function') throw new TypeError('WASM message send requires a message runtime');
          return canonicalizeValue(await context.sendMessage(tailEffect.request));
        }
        if (tailEffect.kind === 'apply') {
          if (typeof context.invokeBlock !== 'function') throw new TypeError('WASM callable application requires a Block invocation runtime');
          return canonicalizeValue(await context.invokeBlock(tailEffect.request.callee, tailEffect.request.arguments));
        }
        if (tailEffect.kind === 'closure') {
          if (typeof context.createClosure !== 'function') throw new TypeError('WASM closure creation requires a closure runtime');
          return canonicalizeValue(await context.createClosure(tailEffect.request));
        }
        throw new TypeError(`unknown WASM host effect kind: ${tailEffect.kind}`);
      }

      return canonicalizeValue(result);
    },
  });
}

export {createWasmFunctionV1CellExecutor};

import {assertWasmFunctionArtifactAnyVersion, functionModuleRef, resolveFunctionContract} from './function-contract.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {
  WASM_IMPORT_MODULE,
  WASM_VALUE_HANDLE_ABI_V0,
  ValueHandleArena,
} from './abi.js';
import {
  WASM_INSTANCE_REUSE_STATELESS_V0,
  WasmInstancePool,
} from './instance-pool.js';
import {WasmModuleCache} from './module-cache.js';
import {readModuleDescriptor, readModuleImplementationBytes} from './module-contract.js';

function requireNonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeCaptures(value, label = 'WASM function metadata.captures') {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  return Object.freeze(value.map((id, index) => {
    if (typeof id !== 'string' || id.length === 0) throw new TypeError(`${label} ${index} must be a non-empty binding id`);
    return id;
  }));
}

function normalizeIndexList(value, limit, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((entry, index) => {
    const normalized = requireNonNegativeInteger(entry, `${label} ${index}`);
    if (normalized >= limit) throw new TypeError(`${label} ${index} is out of range`);
    if (seen.has(normalized)) throw new TypeError(`${label} contains duplicate index ${normalized}`);
    seen.add(normalized);
    return normalized;
  }));
}

function normalizeLiterals(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract literals must be an array');
  return Object.freeze(value.map((entry) => canonicalizeValue(entry)));
}

function normalizeSendSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract sendSites must be an array');
  return Object.freeze(value.map((site, index) => {
    exactKeys(site, ['languageId', 'message', 'arity'], `WASM send site ${index}`);
    if (typeof site.languageId !== 'string' || site.languageId.length === 0) {
      throw new TypeError(`WASM send site ${index} languageId must be a non-empty string`);
    }
    const message = canonicalizeValue(site.message);
    if (isReference(message)) throw new TypeError(`WASM send site ${index} message must not hide a graph reference`);
    return Object.freeze({
      languageId: site.languageId,
      message,
      arity: requireNonNegativeInteger(site.arity, `WASM send site ${index} arity`),
    });
  }));
}

function normalizeClosureSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract closureSites must be an array');
  return Object.freeze(value.map((site, siteIndex) => {
    exactKeys(site, ['blockId', 'captures'], `WASM closure site ${siteIndex}`);
    if (typeof site.blockId !== 'string' || site.blockId.length === 0) {
      throw new TypeError(`WASM closure site ${siteIndex} blockId must be non-empty text`);
    }
    if (!Array.isArray(site.captures)) throw new TypeError(`WASM closure site ${siteIndex} captures must be an array`);
    const captures = Object.freeze(site.captures.map((capture, captureIndex) => {
      exactKeys(capture, ['id', 'name'], `WASM closure site ${siteIndex} capture ${captureIndex}`);
      if (typeof capture.id !== 'string' || capture.id.length === 0) throw new TypeError(`WASM closure capture ${captureIndex} id must be non-empty text`);
      if (typeof capture.name !== 'string' || capture.name.length === 0) throw new TypeError(`WASM closure capture ${captureIndex} name must be non-empty text`);
      return Object.freeze({id: capture.id, name: capture.name});
    }));
    return Object.freeze({blockId: site.blockId, captures});
  }));
}

function normalizeModuleFunctions(value, sendSites, closureSites) {
  if (value === undefined) return null;
  if (!Array.isArray(value) || value.length === 0) throw new TypeError('WASM module contract functions must be a non-empty array');
  const entries = new Set();
  const memberIndices = new Set();
  return Object.freeze(value.map((descriptor, index) => {
    exactKeys(
      descriptor,
      ['entry', 'memberIndex', 'parameters', 'captures', 'sendSiteIndices', 'closureSiteIndices'],
      `WASM module function ${index}`,
    );
    if (typeof descriptor.entry !== 'string' || descriptor.entry.length === 0) throw new TypeError(`WASM module function ${index} entry must be non-empty text`);
    if (entries.has(descriptor.entry)) throw new TypeError(`duplicate WASM module function entry: ${descriptor.entry}`);
    entries.add(descriptor.entry);
    const memberIndex = requireNonNegativeInteger(descriptor.memberIndex, `WASM module function ${index} memberIndex`);
    if (memberIndices.has(memberIndex)) throw new TypeError(`duplicate WASM module function memberIndex: ${memberIndex}`);
    memberIndices.add(memberIndex);
    return Object.freeze({
      entry: descriptor.entry,
      memberIndex,
      parameters: requireNonNegativeInteger(descriptor.parameters, `WASM module function ${index} parameters`),
      captures: normalizeCaptures(descriptor.captures, `WASM module function ${index} captures`),
      sendSiteIndices: normalizeIndexList(descriptor.sendSiteIndices, sendSites.length, `WASM module function ${index} sendSiteIndices`),
      closureSiteIndices: normalizeIndexList(descriptor.closureSiteIndices, closureSites.length, `WASM module function ${index} closureSiteIndices`),
    });
  }));
}




function recordPending(pending, effect) {
  if (pending.effect !== null) throw new TypeError('WASM activation attempted more than one pending host effect');
  pending.effect = Object.freeze(effect);
  return 0;
}

function createRebindableHostEnvironment(literals, sendSites, closureSites) {
  const holder = {current: null};
  const current = () => {
    if (!holder.current) throw new TypeError('WASM instance host environment is not bound to an activation');
    return holder.current;
  };
  const lagrange = {
    literal(index) {
      const state = current();
      if (!Number.isInteger(index) || index < 0 || index >= literals.length) throw new TypeError(`WASM literal index out of range: ${index}`);
      return state.arena.put(literals[index]);
    },
    integer_add(left, right) {
      return current().arena.integerAdd(left, right);
    },
    equals(left, right) {
      return current().arena.equals(left, right);
    },
    is_true(handle) {
      return current().arena.isTrue(handle);
    },
  };

  sendSites.forEach((site, siteIndex) => {
    lagrange[`send_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeSendSites.has(siteIndex)) throw new TypeError(`inactive WASM send site invoked: ${siteIndex}`);
      if (handles.length !== 1 + site.arity) {
        throw new TypeError(`WASM send site ${siteIndex} expected ${1 + site.arity} handles, received ${handles.length}`);
      }
      return recordPending(state.pending, {
        kind: 'send',
        request: Object.freeze({
          languageId: site.languageId,
          receiver: state.arena.get(handles[0], `WASM send site ${siteIndex} receiver handle`),
          message: site.message,
          arguments: Object.freeze(handles.slice(1).map((handle, argumentIndex) =>
            state.arena.get(handle, `WASM send site ${siteIndex} argument ${argumentIndex} handle`))),
        }),
      });
    };
  });

  closureSites.forEach((site, siteIndex) => {
    lagrange[`make_block_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeClosureSites.has(siteIndex)) throw new TypeError(`inactive WASM closure site invoked: ${siteIndex}`);
      if (handles.length !== site.captures.length) {
        throw new TypeError(`WASM closure site ${siteIndex} expected ${site.captures.length} handles, received ${handles.length}`);
      }
      const prototype = state.closurePrototypes.get(siteIndex);
      if (!prototype) throw new TypeError(`WASM closure prototype missing at execution: ${site.blockId}`);
      return recordPending(state.pending, {
        kind: 'closure',
        request: Object.freeze({
          prototype,
          captures: Object.freeze(site.captures.map((capture, captureIndex) => Object.freeze({
            id: capture.id,
            name: capture.name,
            value: state.arena.get(handles[captureIndex], `WASM closure site ${siteIndex} capture ${captureIndex} handle`),
          }))),
        }),
      });
    };
  });

  return Object.freeze({
    imports: {[WASM_IMPORT_MODULE]: lagrange},
    bind({arena, descriptor, closurePrototypes, pending}) {
      if (holder.current) throw new TypeError('WASM instance host environment is already bound');
      holder.current = {
        arena,
        closurePrototypes,
        pending,
        activeSendSites: new Set(descriptor.sendSiteIndices),
        activeClosureSites: new Set(descriptor.closureSiteIndices),
      };
    },
    unbind() {
      if (!holder.current) throw new TypeError('WASM instance host environment is not bound');
      holder.current = null;
    },
  });
}

function instanceReuseMode(moduleArtifact) {
  const mode = moduleArtifact.metadata?.instanceReuse;
  if (mode === undefined) return null;
  if (mode !== WASM_INSTANCE_REUSE_STATELESS_V0) throw new TypeError(`unsupported WASM instance reuse contract: ${mode}`);
  return mode;
}

async function createInstanceSlot(compiledModule, literals, sendSites, closureSites) {
  const host = createRebindableHostEnvironment(literals, sendSites, closureSites);
  const instance = await WebAssembly.instantiate(compiledModule, host.imports);
