// The single decoder/describer for a compiled WASM FUNCTION artifact (ADR 0082, bead
// lagrange-images-o8a): the counterpart of module-contract.js one level up.
//
// A function artifact selects ONE exported entry of a compiled module and binds that entry's
// closure sites to prototype Blocks. Everything else the executors need (ABI, parameter count,
// captures, cellBindings, site indices) is the MODULE's function-table entry, resolved through the
// module accessor — it is never duplicated on the function.
//
// wasm-function/v2 (canonical): content = canonical JSON {entry, closurePrototypes:[{blockId,
// siteIndex, derivedFromIndex}]}; the module is reached through exactly ONE `role: module`
// dependency (single authority for the module binding, never repeated in JSON). Prototype Blocks
// are named by index into `derivedFrom` ([semantic, module, ...prototypes]) because a dependency
// edge must target a code artifact and a prototype is a Block; `derivedFrom` is preserved by the
// portable bundle, so the binding survives release.
//
// wasm-function/v1 (FROZEN): content = module ref; metadata mirrors {abi, entry, parameters,
// captures, [cellBindings], closurePrototypes}. Still executable in-image through this decoder,
// which cross-checks the mirrors against the module exactly as the executors used to; never
// produced; does not survive release (metadata is stripped).
import {canonicalizeValue, isObjectRef, textValue} from '../value/index.js';
import {
  WASM_FUNCTION_MODULE_DEPENDENCY_ROLE,
  WASM_FUNCTION_V1,
  WASM_FUNCTION_V2,
  assertWasmFunctionArtifact as assertWasmFunctionV1Artifact,
} from '../code/wasm-artifacts.js';
import {canonicalJson, moduleFunctionOf} from './module-contract.js';

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function requiredIndex(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const keys = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (keys.length !== wanted.length || keys.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

// The function-owned selection: which entry, and which prototype Block binds each closure site.
function normalizeFunctionSelection(selection, label = 'WASM function selection') {
  exactKeys(selection, ['entry', 'closurePrototypes'], label);
  if (!Array.isArray(selection.closurePrototypes)) throw new TypeError(`${label}.closurePrototypes must be an array`);
  return Object.freeze({
    entry: requiredText(selection.entry, `${label}.entry`),
    closurePrototypes: Object.freeze(selection.closurePrototypes.map((entry, index) => {
      exactKeys(entry, ['blockId', 'siteIndex', 'derivedFromIndex'], `${label}.closurePrototypes[${index}]`);
      const derivedFromIndex = requiredIndex(entry.derivedFromIndex, `${label}.closurePrototypes[${index}].derivedFromIndex`);
      if (derivedFromIndex < 2) throw new TypeError(`${label}.closurePrototypes[${index}].derivedFromIndex must follow the semantic and module provenance entries`);
      return Object.freeze({
        blockId: requiredText(entry.blockId, `${label}.closurePrototypes[${index}].blockId`),
        siteIndex: requiredIndex(entry.siteIndex, `${label}.closurePrototypes[${index}].siteIndex`),
        derivedFromIndex,
      });
    })),
  });
}

function encodeFunctionSelectionContent(selection) {
  return canonicalJson(normalizeFunctionSelection(selection));
}

function moduleDependencyRef(artifact) {
  const deps = (artifact.dependencies ?? []).filter((d) => d.role === WASM_FUNCTION_MODULE_DEPENDENCY_ROLE);
  if (deps.length !== 1) throw new TypeError(`${WASM_FUNCTION_V2} must have exactly one ${WASM_FUNCTION_MODULE_DEPENDENCY_ROLE} dependency`);
  const ref = canonicalizeValue(deps[0].artifact);
  if (!isObjectRef(ref)) throw new TypeError(`${WASM_FUNCTION_V2} module must be an unpinned object ref`);
  return ref;
}

function assertWasmFunctionV2Artifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== WASM_FUNCTION_V2) {
    throw new TypeError(`artifact is not ${WASM_FUNCTION_V2}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError(`${WASM_FUNCTION_V2} content must be a canonical-JSON text Value`);
  let parsed;
  try {
    parsed = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError(`${WASM_FUNCTION_V2} content must be valid JSON`, {cause: error});
  }
  if (canonicalJson(normalizeFunctionSelection(parsed, `${WASM_FUNCTION_V2} content`)) !== artifact.content.value) {
    throw new TypeError(`${WASM_FUNCTION_V2} content is not the canonical serialization of its selection`);
  }
  moduleDependencyRef(artifact);
  return artifact;
}

function assertWasmFunctionArtifactAnyVersion(artifact) {
  if (artifact?.representation === WASM_FUNCTION_V2) return assertWasmFunctionV2Artifact(artifact);
  if (artifact?.representation === WASM_FUNCTION_V1) return assertWasmFunctionV1Artifact(artifact);
  throw new TypeError(`not a WASM function artifact: ${artifact?.representation ?? 'missing'}`);
}

// The module a function executes in: the v2 dependency edge, or the frozen v1 content ref.
function functionModuleRef(artifact) {
  if (artifact?.representation === WASM_FUNCTION_V2) return moduleDependencyRef(assertWasmFunctionV2Artifact(artifact));
  if (artifact?.representation === WASM_FUNCTION_V1) {
    const ref = canonicalizeValue(assertWasmFunctionV1Artifact(artifact).content);
    if (!isObjectRef(ref)) throw new TypeError(`${WASM_FUNCTION_V1} content must reference a WASM module artifact`);
    return ref;
  }
  throw new TypeError(`not a WASM function artifact: ${artifact?.representation ?? 'missing'}`);
}

// The function's own selection {entry, closurePrototypes} plus, for frozen v1 only, the metadata
// mirrors that the v1 contract cross-checks against the module.
function readFunctionSelection(artifact) {
  if (artifact?.representation === WASM_FUNCTION_V2) {
    assertWasmFunctionV2Artifact(artifact);
    return Object.freeze({...normalizeFunctionSelection(JSON.parse(artifact.content.value)), mirrors: null});
  }
  if (artifact?.representation === WASM_FUNCTION_V1) {
    assertWasmFunctionV1Artifact(artifact);
    const md = artifact.metadata;
    const prototypes = md.closurePrototypes ?? [];
    if (!Array.isArray(prototypes)) throw new TypeError(`${WASM_FUNCTION_V1} metadata.closurePrototypes must be an array`);
    return Object.freeze({
      entry: md.entry,
      closurePrototypes: Object.freeze(prototypes.map((entry, index) => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) throw new TypeError(`WASM closure prototype ${index} must be an object`);
        const keys = Object.keys(entry).sort().join(',');
        // The oldest v1 form omitted siteIndex (positional); the later one names it.
        if (keys !== 'blockId,derivedFromIndex' && keys !== 'blockId,derivedFromIndex,siteIndex') {
          throw new TypeError(`WASM closure prototype ${index} has unsupported fields`);
        }
        return Object.freeze({...entry});
      })),
      mirrors: Object.freeze({
        abi: md.abi,
        parameters: md.parameters,
        captures: Object.freeze([...(md.captures ?? [])]),
        ...(Object.hasOwn(md, 'cellBindings') ? {cellBindings: md.cellBindings} : {}),
      }),
    });
  }
  throw new TypeError(`not a WASM function artifact: ${artifact?.representation ?? 'missing'}`);
}

function sameStrings(left, right) {
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

// Resolve the function against its module's (already normalized) contract: the active function
// descriptor, the ABI, and the closure-site -> prototype Block binding. `moduleContract.functions`
// must be the executor-normalized function table (exact keys, validated site indices) and
// `moduleContract.closureSites` the normalized sites, so the checks here are the last word.
function resolveFunctionContract(artifact, moduleContract, {selection = readFunctionSelection(artifact)} = {}) {
  const descriptor = moduleFunctionOf(moduleContract, {entry: selection.entry});
  if (selection.mirrors) {
    // Frozen v1: the mirrors must agree with the module, exactly as the executors always required.
    const m = selection.mirrors;
    if (m.abi !== moduleContract.abi) throw new TypeError(`WASM function ABI ${m.abi} does not match module ABI ${moduleContract.abi}`);
    if (descriptor.parameters !== m.parameters) throw new TypeError('WASM function parameter metadata does not match module entry');
    if (!sameStrings(descriptor.captures, m.captures)) throw new TypeError('WASM function capture metadata does not match module entry');
    if (descriptor.cellBindings !== undefined || m.cellBindings !== undefined) {
      if (canonicalJson(descriptor.cellBindings ?? []) !== canonicalJson(m.cellBindings ?? [])) {
        throw new TypeError('WASM function cell binding metadata does not match module entry');
      }
    }
  }
  const closureSites = moduleContract.closureSites;
  const entries = selection.closurePrototypes;
  if (entries.length !== descriptor.closureSiteIndices.length) {
    throw new TypeError('WASM closure prototype count does not match module function closure sites');
  }
  const closurePrototypes = new Map();
  entries.forEach((entry, localIndex) => {
    const siteIndex = entry.siteIndex === undefined
      ? descriptor.closureSiteIndices[localIndex]
      : requiredIndex(entry.siteIndex, `WASM closure prototype ${localIndex} siteIndex`);
    if (siteIndex !== descriptor.closureSiteIndices[localIndex]) {
      throw new TypeError(`WASM closure prototype ${localIndex} does not match module function closure site index`);
    }
    const site = closureSites[siteIndex];
    if (!site || entry.blockId !== site.blockId) {
      throw new TypeError(`WASM closure prototype ${localIndex} does not match closure site ${site?.blockId ?? siteIndex}`);
    }
    const derivedFromIndex = requiredIndex(entry.derivedFromIndex, `WASM closure prototype ${localIndex} derivedFromIndex`);
    const derivedFrom = artifact.derivedFrom ?? [];
    if (derivedFromIndex < 2 || derivedFromIndex >= derivedFrom.length) {
      throw new TypeError(`WASM closure prototype ${localIndex} derivedFromIndex is out of range`);
    }
    const ref = canonicalizeValue(derivedFrom[derivedFromIndex]);
    if (!isObjectRef(ref)) throw new TypeError(`WASM closure prototype ${localIndex} must resolve to an unpinned Block ref`);
    closurePrototypes.set(siteIndex, ref);
  });
  return Object.freeze({entry: selection.entry, abi: moduleContract.abi, descriptor, closurePrototypes});
}

// Bind a function's closure sites to prototype Blocks — the ONE place the {blockId, siteIndex,
// derivedFromIndex} entries and the derivedFrom layout [semantic, module, ...prototypes] are
// decided. `prototypes` maps semantic block id -> Block ref; every closure site of the selected
// entry must be bound and no prototype may go unused. The caller (an assembler) verifies the
// prototype Blocks exist; this owner verifies the binding against the module contract.
function bindClosurePrototypes({descriptor, closureSites, prototypes} = {}) {
  if (!(prototypes instanceof Map)) throw new TypeError('prototypes must be a Map of semantic block id -> Block ref');
  const remaining = new Map(prototypes);
  const prototypeRefs = [];
  const closurePrototypes = [];
  for (const [localIndex, siteIndex] of descriptor.closureSiteIndices.entries()) {
    const site = closureSites[siteIndex];
    if (!site) throw new TypeError(`WASM function closure site index out of range: ${siteIndex}`);
    const ref = prototypes.get(site.blockId);
    if (!ref) throw new TypeError(`missing WASM Block prototype for semantic block: ${site.blockId}`);
    const normalized = canonicalizeValue(ref);
    if (!isObjectRef(normalized)) throw new TypeError(`block prototype ${site.blockId} must be an unpinned object ref`);
    prototypeRefs.push(normalized);
    closurePrototypes.push(Object.freeze({blockId: site.blockId, siteIndex, derivedFromIndex: 2 + localIndex}));
    remaining.delete(site.blockId);
  }
  if (remaining.size > 0) throw new TypeError(`unused WASM Block prototype: ${remaining.keys().next().value}`);
  return Object.freeze({closurePrototypes: Object.freeze(closurePrototypes), prototypeRefs: Object.freeze(prototypeRefs)});
}

// THE durable v2 function artifact, described once. `prototypeRefs` are the Block refs the closure
// prototypes index into (derivedFrom = [semantic, module, ...prototypeRefs]).
function describeWasmFunctionV2({functionId, languageId, semanticRef, moduleRef, entry, closurePrototypes = [], prototypeRefs = []} = {}) {
  requiredText(functionId, 'WASM function id');
  const semantic = canonicalizeValue(semanticRef);
  const module = canonicalizeValue(moduleRef);
  if (!isObjectRef(semantic)) throw new TypeError('WASM function semanticRef must be an unpinned object ref');
  if (!isObjectRef(module)) throw new TypeError('WASM function moduleRef must be an unpinned object ref');
  const selection = normalizeFunctionSelection({entry, closurePrototypes});
  for (const [index, prototype] of selection.closurePrototypes.entries()) {
    if (prototype.derivedFromIndex >= 2 + prototypeRefs.length) {
      throw new TypeError(`WASM closure prototype ${index} derivedFromIndex names no supplied prototype`);
    }
  }
  return Object.freeze({
    id: functionId,
    languageId,
    representation: WASM_FUNCTION_V2,
    content: textValue(canonicalJson(selection)),
    dependencies: [{role: WASM_FUNCTION_MODULE_DEPENDENCY_ROLE, artifact: module}],
    derivedFrom: [semantic, module, ...prototypeRefs.map((ref) => canonicalizeValue(ref))],
    metadata: {},
  });
}

export {
  WASM_FUNCTION_MODULE_DEPENDENCY_ROLE,
  WASM_FUNCTION_V1,
  WASM_FUNCTION_V2,
  assertWasmFunctionArtifactAnyVersion,
  assertWasmFunctionV2Artifact,
  bindClosurePrototypes,
  describeWasmFunctionV2,
  encodeFunctionSelectionContent,
  functionModuleRef,
  normalizeFunctionSelection,
  readFunctionSelection,
  resolveFunctionContract,
};

import {WASM_VALUE_HANDLE_ABI_V0, WASM_VALUE_HANDLE_ABI_V1} from './abi.js';
import {createWasmFunctionV1Executor as createTailWasmFunctionV1Executor} from './executor.js';
import {WasmInstancePool} from './instance-pool.js';
import {WasmModuleCache} from './module-cache.js';
import {
  WASM_RESUMABLE_VALUE_HANDLE_ABI_V1,
  WASM_RESUMABLE_VALUE_HANDLE_ABI_V2,
} from './resumable-abi.js';
import {createResumableWasmFunctionV1Executor} from './resumable-executor.js';
import {createWasmFunctionV1CellExecutor} from './executor-v1.js';
import {createResumableWasmFunctionV2Executor} from './resumable-executor-v2.js';
import {assertWasmFunctionArtifactAnyVersion, functionModuleRef, readFunctionSelection} from './function-contract.js';
import {readModuleDescriptor} from './module-contract.js';

function createWasmFunctionV1Executor({
  moduleCache = new WasmModuleCache(),
  instancePool = new WasmInstancePool(),
} = {}) {
  const tail = createTailWasmFunctionV1Executor({moduleCache, instancePool});
  const resumable = createResumableWasmFunctionV1Executor({moduleCache, instancePool});
  const cells = createWasmFunctionV1CellExecutor({moduleCache, instancePool});
  const resumableCells = createResumableWasmFunctionV2Executor({moduleCache, instancePool});

  return Object.freeze({
    moduleCache,
    instancePool,
    async execute(request, context) {
      // The MODULE's ABI decides which contract the pair is read under (ADR 0082): a function
      // artifact selects an entry and carries no ABI of its own. The module is resolved once here
      // and handed to the chosen executor, so a dispatch costs no second read.
      const code = request?.code;
      assertWasmFunctionArtifactAnyVersion(code);
      const moduleRef = functionModuleRef(code);
      const moduleArtifact = await context.images.getCodeArtifact(moduleRef.imageId, moduleRef.objectId);
      if (!moduleArtifact) throw new TypeError(`WASM module not found: ${moduleRef.imageId}/${moduleRef.objectId}`);
      const abi = readModuleDescriptor(moduleArtifact).abi;
      // Decoded once here; the executor resolves the contract from this selection without re-parsing.
      const resolved = Object.freeze({moduleArtifact, selection: readFunctionSelection(code)});
      if (abi === WASM_VALUE_HANDLE_ABI_V0) return await tail.execute(request, context, resolved);
      if (abi === WASM_VALUE_HANDLE_ABI_V1) return await cells.execute(request, context, resolved);
      if (abi === WASM_RESUMABLE_VALUE_HANDLE_ABI_V1) return await resumable.execute(request, context, resolved);
      if (abi === WASM_RESUMABLE_VALUE_HANDLE_ABI_V2) return await resumableCells.execute(request, context, resolved);
      throw new TypeError(`unsupported WASM module ABI: ${abi}`);
    },
  });
}

export {createWasmFunctionV1Executor};

import {canonicalizeValue, integerValue} from '../value/index.js';

function requiredPositiveInteger(value, label) {
  if (!Number.isInteger(value) || value <= 0) {
    throw new TypeError(`${label} must be a positive integer`);
  }
  return value;
}

/**
 * Computes the set of ANF/CPS plan variable identifiers that are free (live)
 * in `plan`. Used at each suspension point (`effect`) to retain only Value
 * handles that are actually referenced in `plan.next`.
 */
function collectFreePlanVariables(plan, bound = new Set()) {
  const free = new Set();

  const use = (id) => {
    if (typeof id === 'string' && id.length > 0 && !bound.has(id)) {
      free.add(id);
    }
  };

  const visit = (node, currentBound) => {
    if (!node || typeof node !== 'object') return;
    switch (node.kind) {
      case 'let': {
        if (node.op === 'cell-set') {
          if ( !currentBound.has(node.value)) free.add(node.value);
        } else if (node.op === 'integer-add' || node.op === 'equals') {
          if (!currentBound.has(node.left)) free.add(node.left);
          if (!currentBound.has(node.right)) free.add(node.right);
        } else if (node.op === 'direct-call') {
          for (const argId of node.callValues ?? []) {
            if (!currentBound.has(argId)) free.add(argId);
          }
        }
        const nextBound = new Set(currentBound);
        nextBound.add(node.id);
        visit(node.next, nextBound);
        return;
      }
      case 'if': {
        if (!currentBound.has(node.condition)) free.add(node.condition);
        visit(node.then, currentBound);
        visit(node.else, currentBound);
        return;
      }
      case 'return': {
        use(node.value);
        if (!currentBound.has(node.value)) free.add(node.value);
        return;
      }
      case 'effect': {
        for (const reqId of node.requestValues ?? []) {
          if (!currentBound.has(reqId)) free.add(reqId);
        }
        const nextBound = new Set(currentBound);
        nextBound.add(node.resultId);
        visit(node.next, nextBound);
        return;
      }
      case 'effect-terminal': {
        for (const reqId of node.requestValues ?? []) {
          if (!currentBound.has(reqId)) free.add(reqId);
        }
        for (const savedId of node.savedValues ?? []) {
          if (!currentBound.has(savedId)) free.add(savedId);
        }
        return;
      }
      default:
        return;
    }
  };

  visit(plan, bound);
  return free;
}

/**
 * Given a continuation plan (`plan.next` at an `effect` suspension point) and
 * the ordered list of `available` variables in scope, returns the subset of
 * `available` variables that are genuinely live across the suspension point,
 * along with the eliminated dead variables.
 */
function analyzeLivePlanVariables(continuationPlan, available) {
  if (!Array.isArray(available)) {
    throw new TypeError('available variables must be an array');
  }
  const free = collectFreePlanVariables(continuationPlan);
  const seen = new Set();
  const savedValues = [];
  const eliminatedValues = [];
  for (const id of available) {
    if (seen.has(id)) continue;
    seen.add(id);
    if (free.has(id)) {
      savedValues.push(id);
    } else {
      eliminatedValues.push(id);
    }
  }
  return Object.freeze({
    savedValues: Object.freeze(savedValues),
    eliminatedValues: Object.freeze(eliminatedValues),
    freeVariables: Object.freeze([...free]),
  });
}

function smalltalkValueSelectorArity(message) {
  if (!message || message.kind !== 'text' || typeof message.value !== 'string') return null;
  if (message.value === 'value') return 0;
  if (/^(value:)+$/.test(message.value)) {
    return message.value.split(':').length - 1;
  }
  return null;
}

function isPureSubstitutionExpression(expr) {
  if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return false;
  return expr.op === 'literal'
    || expr.op === 'argument'
    || expr.op === 'receiver'
    || expr.op === 'binding';
}

function cloneExpression(expr) {
  return JSON.parse(JSON.stringify(expr));
}

function rewriteInlinedBody(expr, {argumentMap, bindingMap, receiverExpr}) {
  if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return expr;
  switch (expr.op) {
    case 'literal':
      return cloneExpression(expr);
    case 'receiver':
      return receiverExpr ? cloneExpression(receiverExpr) : cloneExpression(expr);
    case 'argument': {
      const replacement = argumentMap.get(expr.index);
      if (!replacement) {
        throw new TypeError(`inlined closure argument index out of range: ${expr.index}`);
      }
      return cloneExpression(replacement);
    }
    case 'binding': {
      const mapped = bindingMap.get(expr.id);
      if (mapped) return cloneExpression(mapped);
      return cloneExpression(expr);
    }
    case 'binding-write': {
      const mapped = bindingMap.get(expr.id);
      const targetId = mapped && mapped.op === 'binding' ? mapped.id : expr.id;
      return {
        op: 'binding-write',
        id: targetId,
        value: rewriteInlinedBody(expr.value, {argumentMap, bindingMap, receiverExpr}),
      };
    }
    case 'sequence':
      return {
        op: 'sequence',
        statements: expr.statements.map((stmt) =>
          rewriteInlinedBody(stmt, {argumentMap, bindingMap, receiverExpr})),
      };
    case 'integer-add':
    case 'equals':
      return {
        op: expr.op,
        left: rewriteInlinedBody(expr.left, {argumentMap, bindingMap, receiverExpr}),
        right: rewriteInlinedBody(expr.right, {argumentMap, bindingMap, receiverExpr}),
      };
    case 'if':
      return {
        op: 'if',
        condition: rewriteInlinedBody(expr.condition, {argumentMap, bindingMap, receiverExpr}),
        then: rewriteInlinedBody(expr.then, {argumentMap, bindingMap, receiverExpr}),
        else: rewriteInlinedBody(expr.else, {argumentMap, bindingMap, receiverExpr}),
      };
    case 'send':
      return {
        op: 'send',
        languageId: expr.languageId,
        message: cloneExpression(expr.message),
        receiver: rewriteInlinedBody(expr.receiver, {argumentMap, bindingMap, receiverExpr}),
        arguments: (expr.arguments ?? []).map((arg) =>
          rewriteInlinedBody(arg, {argumentMap, bindingMap, receiverExpr})),
      };
    case 'apply':
      return {
        op: 'apply',
        callee: rewriteInlinedBody(expr.callee, {argumentMap, bindingMap, receiverExpr}),
        arguments: (expr.arguments ?? []).map((arg) =>
          rewriteInlinedBody(arg, {argumentMap, bindingMap, receiverExpr})),
      };
    case 'block':
    case 'make-block':
      return {
        ...cloneExpression(expr),
        captures: (expr.captures ?? []).map((cap) => {
          if (cap.mode === 'cell') {
            const mapped = bindingMap.get(cap.id);
            return mapped && mapped.op === 'binding'
              ? {...cap, id: mapped.id}
              : cloneExpression(cap);
          }
          if (cap.value) {
            return {
              ...cap,
              value: rewriteInlinedBody(cap.value, {argumentMap, bindingMap, receiverExpr}),
            };
          }
          return cloneExpression(cap);
        }),
      };
    default:
      return cloneExpression(expr);
  }
}

function containsNestedBlock(expr) {
  if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return false;
  switch (expr.op) {
    case 'block':
    case 'make-block':
      return true;
    case 'binding-write':
      return containsNestedBlock(expr.value);
    case 'sequence':
      return (expr.statements ?? []).some(containsNestedBlock);
    case 'integer-add':
    case 'equals':
      return containsNestedBlock(expr.left) || containsNestedBlock(expr.right);
    case 'if':
      return containsNestedBlock(expr.condition)
        || containsNestedBlock(expr.then)
        || containsNestedBlock(expr.else);
    case 'send':
      return containsNestedBlock(expr.receiver)
        || (expr.arguments ?? []).some(containsNestedBlock);
    case 'apply':
      return containsNestedBlock(expr.callee)
        || (expr.arguments ?? []).some(containsNestedBlock);
    default:
      return false;
  }
}

function collectLocalBlockBindings(body, temporaries) {
  const tempIds = new Set((temporaries ?? []).map((t) => t.id));
  const writeCounts = new Map();
  const blockDefs = new Map();
  const totalReads = new Map();
  const callReads = new Map();
  const capturedByBlock = new Set();

  const visit = (expr) => {
    if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return;
    switch (expr.op) {
      case 'binding':
        if (tempIds.has(expr.id)) {
          totalReads.set(expr.id, (totalReads.get(expr.id) ?? 0) + 1);
        }
        return;
      case 'binding-write':
        if (tempIds.has(expr.id)) {
          writeCounts.set(expr.id, (writeCounts.get(expr.id) ?? 0) + 1);
          if (expr.value?.op === 'block' && !containsNestedBlock(expr.value.program?.body)) {
            blockDefs.set(expr.id, expr.value);
          }
        }
        visit(expr.value);
        return;
      case 'sequence':
        for (const stmt of expr.statements ?? []) visit(stmt);
        return;
      case 'integer-add':
      case 'equals':
        visit(expr.left);
        visit(expr.right);
        return;
      case 'if':
        visit(expr.condition);
        visit(expr.then);
        visit(expr.else);
        return;
      case 'apply':
        if (expr.callee?.op === 'binding' && tempIds.has(expr.callee.id)) {
          callReads.set(expr.callee.id, (callReads.get(expr.callee.id) ?? 0) + 1);
        }
        visit(expr.callee);
        for (const arg of expr.arguments ?? []) visit(arg);
        return;
      case 'send': {
        const arity = smalltalkValueSelectorArity(expr.message);
        if (
          arity !== null
          && expr.receiver?.op === 'binding'
          && tempIds.has(expr.receiver.id)
          && (expr.arguments ?? []).length === arity
        ) {
          callReads.set(expr.receiver.id, (callReads.get(expr.receiver.id) ?? 0) + 1);
        }
        visit(expr.receiver);
        for (const arg of expr.arguments ?? []) visit(arg);
        return;
      }
      case 'block':
      case 'make-block':
        for (const cap of expr.captures ?? []) {
          if (cap.mode === 'cell' && tempIds.has(cap.id)) {
            capturedByBlock.add(cap.id);
          } else if (cap.value) {
            visit(cap.value);
          }
        }
        if (expr.program?.body) visit(expr.program.body);
        return;
      default:
        return;
    }
  };

  visit(body);

  const nonEscaping = new Map();
  for (const [tempId, blockExpr] of blockDefs.entries()) {
    const writes = writeCounts.get(tempId) ?? 0;
    const reads = totalReads.get(tempId) ?? 0;
    const calls = callReads.get(tempId) ?? 0;
    if (writes === 1 && reads > 0 && reads === calls && !capturedByBlock.has(tempId)) {
      nonEscaping.set(tempId, blockExpr);
    }
  }
  return nonEscaping;
}

/**
 * Analyzes nested Blocks in `program` to identify closures that do not escape
 * (immediate inline Block applications or single-assignment local Block
 * bindings applied only in-place) vs closures that require full runtime
 * materialization.
 */
function analyzeClosureEscape(program) {
  if (!program || typeof program !== 'object') {
    throw new TypeError('program must be an object');
  }
  const hasTemporaries = Array.isArray(program.temporaries);
  const nonEscapingLocals = hasTemporaries
    ? collectLocalBlockBindings(program.body, program.temporaries)
    : new Map();

  const nonEscapingBlockIds = [];
  const escapingBlockIds = [];
  const localBindingBlockIds = new Set(
    [...nonEscapingLocals.values()].map((b) => b.blockId),
  );

  const scan = (expr, inImmediateCallPosition = false) => {
    if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return;
    switch (expr.op) {
      case 'block': {
        if (inImmediateCallPosition || localBindingBlockIds.has(expr.blockId)) {
          nonEscapingBlockIds.push(expr.blockId);
        } else {
          escapingBlockIds.push(expr.blockId);
        }
        for (const cap of expr.captures ?? []) {
          if (cap.value) scan(cap.value, false);
        }
        if (expr.program?.body) scan(expr.program.body, false);
        return;
      }
      case 'apply': {
        const directBlock = expr.callee?.op === 'block'
          && (expr.callee.program?.parameters?.length ?? 0) === (expr.arguments ?? []).length
          && !containsNestedBlock(expr.callee.program?.body);
        scan(expr.callee, directBlock);
        for (const arg of expr.arguments ?? []) scan(arg, false);
        return;
      }
      case 'send': {
        const arity = smalltalkValueSelectorArity(expr.message);
        const directBlock = arity !== null
          && expr.receiver?.op === 'block'
          && (expr.receiver.program?.parameters?.length ?? 0) === arity
          && (expr.arguments ?? []).length === arity
          && !containsNestedBlock(expr.receiver.program?.body);
        scan(expr.receiver, directBlock);
        for (const arg of expr.arguments ?? []) scan(arg, false);
        return;
      }
      case 'binding-write':
        scan(expr.value, false);
        return;
      case 'sequence':
        for (const stmt of expr.statements ?? []) scan(stmt, false);
        return;
      case 'integer-add':
      case 'equals':
        scan(expr.left, false);
        scan(expr.right, false);
        return;
      case 'if':
        scan(expr.condition, false);
        scan(expr.then, false);
        scan(expr.else, false);
        return;
      default:
        return;
    }
  };

  scan(program.body, false);
  return Object.freeze({
    nonEscapingBlockIds: Object.freeze(nonEscapingBlockIds),
    escapingBlockIds: Object.freeze(escapingBlockIds),
  });
}

/**
 * Inlines non-escaping nested Blocks in `program` so that full closure
 * materialization (`make_block_site_*`) and host Block invocation (`apply` /
 * `value:`) are unnecessary when a Block is only applied locally.
 */
function optimizeNonEscapingClosures(program) {
  if (!program || typeof program !== 'object') {
    throw new TypeError('program must be an object');
  }
  const hasTemporaries = Array.isArray(program.temporaries);
  const addedTemporaries = [];
  const existingTempIds = new Set((program.temporaries ?? []).map((t) => t.id));
  let inlineCounter = 0;
  const inlinedBlockIds = [];
  let eliminatedApplySites = 0;

  const allocateTemp = (prefix, name) => {
    let candidate = `${prefix}:${inlineCounter}`;
    inlineCounter += 1;
    while (existingTempIds.has(candidate)) {
      candidate = `${prefix}:${inlineCounter}`;
      inlineCounter += 1;
    }
    existingTempIds.add(candidate);
    addedTemporaries.push({id: candidate, name});
    return candidate;
  };

  const nonEscapingLocals = hasTemporaries
    ? collectLocalBlockBindings(program.body, program.temporaries)
    : new Map();

  const inlineBlockApplication = (blockExpr, argExprs) => {
    const childProgram = blockExpr.program;
    if (!childProgram || typeof childProgram !== 'object') return null;
    const paramCount = childProgram.parameters?.length ?? 0;
    if (paramCount !== argExprs.length) return null;
    if (containsNestedBlock(childProgram.body)) return null;

    if (!hasTemporaries) {
      // lagrange-code/v0: only inline when all arguments and captures are pure substitution expressions
      const captures = blockExpr.captures ?? [];
      if (!argExprs.every(isPureSubstitutionExpression)) return null;
      if (!captures.every((c) => isPureSubstitutionExpression(c.value))) return null;
      const argumentMap = new Map(argExprs.map((arg, index) => [index, arg]));
      const bindingMap = new Map(captures.map((cap) => [cap.id, cap.value]));
      inlinedBlockIds.push(blockExpr.blockId);
      eliminatedApplySites += 1;
      return rewriteInlinedBody(childProgram.body, {
        argumentMap,
        bindingMap,
        receiverExpr: {op: 'receiver'},
      });
    }

    // lagrange-code/v1 or v2: lower arguments, snapshot captures, and child temporaries into temporaries + sequence
    const setupStatements = [];
    const argumentMap = new Map();
    argExprs.forEach((argExpr, index) => {
      const paramDesc = childProgram.parameters[index];
      const paramName = paramDesc?.name ?? `arg_${index}`;
      const tempId = allocateTemp(`inline:${blockExpr.blockId}:param:${index}`, paramName);
      setupStatements.push({
        op: 'binding-write',
        id: tempId,
        value: transform(argExpr),
      });
      argumentMap.set(index, {op: 'binding', id: tempId});
    });

    const bindingMap = new Map();
    for (const cap of blockExpr.captures ?? []) {
      if (cap.mode === 'cell') {
        bindingMap.set(cap.id, {op: 'binding', id: cap.id});
      } else {
        const capValue = transform(cap.value);
        if (isPureSubstitutionExpression(capValue)) {
          bindingMap.set(cap.id, capValue);
        } else {
          const capTempId = allocateTemp(`inline:${blockExpr.blockId}:cap:${cap.id}`, cap.name ?? cap.id);
          setupStatements.push({
            op: 'binding-write',
            id: capTempId,
            value: capValue,
          });
          bindingMap.set(cap.id, {op: 'binding', id: capTempId});
        }
      }
    }

    for (const childTemp of childProgram.temporaries ?? []) {
      const mappedTempId = allocateTemp(`inline:${blockExpr.blockId}:temp:${childTemp.id}`, childTemp.name ?? childTemp.id);
      bindingMap.set(childTemp.id, {op: 'binding', id: mappedTempId});
    }

    inlinedBlockIds.push(blockExpr.blockId);
    eliminatedApplySites += 1;
    const rewrittenBody = rewriteInlinedBody(childProgram.body, {
      argumentMap,
      bindingMap,
      receiverExpr: {op: 'receiver'},
    });

    if (setupStatements.length === 0) {
      return rewrittenBody;
    }
    const bodyStatements = rewrittenBody.op === 'sequence'
      ? rewrittenBody.statements
      : [rewrittenBody];
    return {
      op: 'sequence',
      statements: [...setupStatements, ...bodyStatements],
    };
  };

  function transform(expr) {
    if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return expr;
    switch (expr.op) {
      case 'binding-write': {
        if (nonEscapingLocals.has(expr.id)) {
          return {op: 'literal', value: canonicalizeValue(integerValue(0))};
        }
        return {
          op: 'binding-write',
          id: expr.id,
          value: transform(expr.value),
        };
      }
      case 'sequence':
        return {
          op: 'sequence',
          statements: expr.statements.map(transform),
        };
      case 'integer-add':
      case 'equals':
        return {
          op: expr.op,
          left: transform(expr.left),
          right: transform(expr.right),
        };
      case 'if':
        return {
          op: 'if',
          condition: transform(expr.condition),
          then: transform(expr.then),
          else: transform(expr.else),
        };
      case 'apply': {
        const args = expr.arguments ?? [];
        if (expr.callee?.op === 'block') {
          const inlined = inlineBlockApplication(expr.callee, args);
          if (inlined) return inlined;
        }
        if (expr.callee?.op === 'binding' && nonEscapingLocals.has(expr.callee.id)) {
          const targetBlock = nonEscapingLocals.get(expr.callee.id);
          const inlined = inlineBlockApplication(targetBlock, args);
          if (inlined) return inlined;
        }
        return {
          op: 'apply',
          callee: transform(expr.callee),
          arguments: args.map(transform),
        };
      }
      case 'send': {
        const args = expr.arguments ?? [];
        const arity = smalltalkValueSelectorArity(expr.message);
        if (arity !== null && args.length === arity) {
          if (expr.receiver?.op === 'block') {
            const inlined = inlineBlockApplication(expr.receiver, args);
            if (inlined) return inlined;
          }
          if (expr.receiver?.op === 'binding' && nonEscapingLocals.has(expr.receiver.id)) {
            const targetBlock = nonEscapingLocals.get(expr.receiver.id);
            const inlined = inlineBlockApplication(targetBlock, args);
            if (inlined) return inlined;
          }
        }
        return {
          op: 'send',
          languageId: expr.languageId,
          message: cloneExpression(expr.message),
          receiver: transform(expr.receiver),
          arguments: args.map(transform),
        };
      }
      case 'block':
      case 'make-block':
        return {
          ...cloneExpression(expr),
          captures: (expr.captures ?? []).map((cap) =>
            cap.value ? {...cap, value: transform(cap.value)} : cloneExpression(cap)),
          ...(expr.program ? {program: optimizeNonEscapingClosures(expr.program).program} : {}),
        };
      default:
        return cloneExpression(expr);
    }
  }

  const transformedBody = transform(program.body);
  const retainedTemporaries = hasTemporaries
    ? [
      ...program.temporaries.filter((t) => !nonEscapingLocals.has(t.id)),
      ...addedTemporaries,
    ]
    : undefined;

  const uniqueInlinedIds = [...new Set(inlinedBlockIds)];
  return Object.freeze({
    program: Object.freeze({
      ...program,
      ...(hasTemporaries ? {temporaries: retainedTemporaries} : {}),
      body: transformedBody,
    }),
    inlinedBlockIds: Object.freeze(uniqueInlinedIds),
    eliminatedClosureSites: uniqueInlinedIds.length,
    eliminatedApplySites,
  });
}

function isPureDirectCallableBody(expr) {
  if (!expr || typeof expr !== 'object' || Array.isArray(expr)) return false;
  switch (expr.op) {
    case 'literal':
    case 'argument':
    case 'receiver':
    case 'binding':
      return true;
    case 'integer-add':
    case 'equals':
      return isPureDirectCallableBody(expr.left) && isPureDirectCallableBody(expr.right);
    case 'if':
      return isPureDirectCallableBody(expr.condition)
        && isPureDirectCallableBody(expr.then)
        && isPureDirectCallableBody(expr.else);
    case 'sequence':
      return (expr.statements ?? []).every(isPureDirectCallableBody);
    default:
      return false;
  }
}

/**
 * Discovers and normalizes intra-module direct call targets between entries in
 * a shared WASM compilation group. When entry A invokes a pure sibling entry B
 * in the same module (either via a nested Block in the same group or an
 * explicit `intraModuleCallTargets` binding map), the compiler can emit a
 * native WebAssembly `call` instruction (`0x10 <funcIdx>`) directly between
 * the module's internal functions without host suspension or closure creation.
 */
function planIntraModuleDirectCalls(entries, {intraModuleCallTargets = null} = {}) {
  if (!Array.isArray(entries) || entries.length === 0) {
    throw new TypeError('entries must be a non-empty array');
  }
  const byEntry = new Map();
  const byMemberIndex = new Map();
  const bySemanticBlockId = new Map();

  entries.forEach((entry, index) => {
    const program = entry.program;
    const hasCells = Array.isArray(program?.temporaries) && program.temporaries.length > 0
      || Array.isArray(program?.captures) && program.captures.some((c) => c.mode === 'cell');
    const directCallable = Boolean(program && !hasCells && isPureDirectCallableBody(program.body));
    const info = Object.freeze({
      entry: entry.entry,
      memberIndex: entry.memberIndex,
      functionOffset: index,
      parameterCount: Array.isArray(program?.parameters) ? program.parameters.length : 0,
      captures: Object.freeze((program?.captures ?? []).filter((c) => c.mode !== 'cell')),
      directCallable,
      semanticBlockId: entry.semanticBlockId ?? null,
    });
    byEntry.set(entry.entry, info);
    byMemberIndex.set(entry.memberIndex, info);
    if (typeof entry.semanticBlockId === 'string' && entry.semanticBlockId.length > 0) {
      bySemanticBlockId.set(entry.semanticBlockId, info);
    }
  });

  const bindingTargets = new Map();
  if (intraModuleCallTargets && typeof intraModuleCallTargets === 'object') {
    for (const [bindingId, spec] of Object.entries(intraModuleCallTargets)) {
      const targetInfo = spec.targetEntry !== undefined
        ? byEntry.get(spec.targetEntry)
        : byMemberIndex.get(spec.targetMemberIndex);
      if (!targetInfo) {
        throw new TypeError(`intraModuleCallTargets[${bindingId}] references unknown module entry`);
      }
      bindingTargets.set(bindingId, Object.freeze({
        ...targetInfo,
        captureExpressions: Object.freeze(spec.captureExpressions ?? []),
      }));
    }
  }

  return Object.freeze({
    byEntry,
    byMemberIndex,
    bySemanticBlockId,
    bindingTargets,
  });
}

class WasmModuleBudgetExceededError extends RangeError {
  constructor(message, details = {}) {
    super(message);
    this.name = 'WasmModuleBudgetExceededError';
    this.details = Object.freeze({...details});
  }
}

/**
 * Splits a logical compilation group's entries into bounded physical WASM
 * module shards according to `maxMembersPerModule` and/or `maxByteBudget`.
 */
function partitionCompilationGroupByBudget({
  entries,
  maxMembersPerModule = Infinity,
  maxByteBudget = Infinity,
  compileEntries,
  strictSingleMemberBudget = false,
} = {}) {
  if (!Array.isArray(entries) || entries.length === 0) {
    throw new TypeError('entries must be a non-empty array');
  }
  if (typeof compileEntries !== 'function') {
    throw new TypeError('compileEntries function is required');
  }
  if (maxMembersPerModule !== Infinity) {
    requiredPositiveInteger(maxMembersPerModule, 'maxMembersPerModule');
  }
  if (maxByteBudget !== Infinity) {
    requiredPositiveInteger(maxByteBudget, 'maxByteBudget');
  }

  const shards = [];
  let currentEntries = [];
  let currentCompiled = null;

  const flushShard = () => {
    if (currentEntries.length === 0) return;
    const compiled = currentCompiled ?? compileEntries(currentEntries);
    shards.push(Object.freeze({
      shardIndex: shards.length,
      memberIndices: Object.freeze(currentEntries.map((e) => e.memberIndex)),
      entries: Object.freeze([...currentEntries]),
      compiled,
      byteLength: compiled.bytes.byteLength,
    }));
    currentEntries = [];
    currentCompiled = null;
  };

  for (const entry of entries) {
    if (currentEntries.length >= maxMembersPerModule) {
      flushShard();
    }
    const candidateEntries = [...currentEntries, entry];
    const candidateCompiled = compileEntries(candidateEntries);
    if (candidateCompiled.bytes.byteLength > maxByteBudget) {
      if (currentEntries.length === 0) {
        if (strictSingleMemberBudget) {
          throw new WasmModuleBudgetExceededError(
            `Single compilation group member ${entry.entry} (${candidateCompiled.bytes.byteLength} bytes) exceeds maxByteBudget (${maxByteBudget} bytes)`,
            {
              entry: entry.entry,
              memberIndex: entry.memberIndex,
              byteLength: candidateCompiled.bytes.byteLength,
              maxByteBudget,
            },
          );
        }
        currentEntries = candidateEntries;
        currentCompiled = candidateCompiled;
        flushShard();
        continue;
      }
      flushShard();
      const singleCompiled = compileEntries([entry]);
      if (strictSingleMemberBudget && singleCompiled.bytes.byteLength > maxByteBudget) {
        throw new WasmModuleBudgetExceededError(
          `Single compilation group member ${entry.entry} (${singleCompiled.bytes.byteLength} bytes) exceeds maxByteBudget (${maxByteBudget} bytes)`,
          {
            entry: entry.entry,
            memberIndex: entry.memberIndex,
            byteLength: singleCompiled.bytes.byteLength,
            maxByteBudget,
          },
        );
      }
      currentEntries = [entry];
      currentCompiled = singleCompiled;
    } else {
      currentEntries = candidateEntries;
      currentCompiled = candidateCompiled;
    }
  }
  flushShard();

  return Object.freeze({
    shardCount: shards.length,
    maxMembersPerModule: maxMembersPerModule === Infinity ? null : maxMembersPerModule,
    maxByteBudget: maxByteBudget === Infinity ? null : maxByteBudget,
    shards: Object.freeze(shards),
  });
}

export {
  WasmModuleBudgetExceededError,
  analyzeClosureEscape,
  analyzeLivePlanVariables,
  collectFreePlanVariables,
  optimizeNonEscapingClosures,
  partitionCompilationGroupByBudget,
  planIntraModuleDirectCalls,
};

import {TupleMap} from '../support/tuple-map.js';
import {isWasmModuleArtifact} from './module-contract.js';

const WASM_INSTANCE_REUSE_STATELESS_V0 = 'stateless-v0';

// A tuple key, not a joined string: image and object ids are arbitrary non-empty text, so
// no separator is safe to join on. See src/support/tuple-map.js.
// The pool keys and gates on identity and the instanceReuse PROVENANCE only; the contract itself
// was already decoded by the executor through the accessor, so nothing is re-parsed per acquire.
function modulePoolKey(artifact) {
  if (!isWasmModuleArtifact(artifact)) throw new TypeError(`not a WASM module artifact: ${artifact?.representation ?? 'missing'}`);
  return [artifact.imageId, artifact.id];
}

function requireReusableModule(artifact) {
  modulePoolKey(artifact);
  if (artifact.metadata?.instanceReuse !== WASM_INSTANCE_REUSE_STATELESS_V0) {
    throw new TypeError(`WASM module does not declare reusable instance contract: ${WASM_INSTANCE_REUSE_STATELESS_V0}`);
  }
  return artifact;
}

function shouldDropState(state) {
  return state.inUse === 0 && state.creating === 0 && state.idle.length === 0;
}

class WasmInstancePool {
  constructor({maxIdlePerModule = 1} = {}) {
    if (!Number.isInteger(maxIdlePerModule) || maxIdlePerModule < 0) {
      throw new TypeError('WASM instance pool maxIdlePerModule must be a non-negative integer');
    }
    this.maxIdlePerModule = maxIdlePerModule;
    this.modules = new TupleMap(2);
    this.hits = 0;
    this.misses = 0;
    this.created = 0;
    this.retired = 0;
    this.discarded = 0;
  }

  stateFor(moduleArtifact) {
    const key = modulePoolKey(moduleArtifact);
    let state = this.modules.get(key);
    if (!state) {
      state = {idle: [], inUse: 0, creating: 0};
      this.modules.set(key, state);
    }
    return {key, state};
  }

  async acquire(moduleArtifact, create) {
    requireReusableModule(moduleArtifact);
    if (typeof create !== 'function') throw new TypeError('WASM instance pool create must be a function');
    const {key, state} = this.stateFor(moduleArtifact);
    let slot = state.idle.pop();
    if (slot) {
      this.hits += 1;
    } else {
      this.misses += 1;
      state.creating += 1;
      try {
        slot = await create();
        if (!slot || typeof slot !== 'object' || !(slot.instance instanceof WebAssembly.Instance)) {
          throw new TypeError('WASM instance pool factory must return a slot containing a WebAssembly.Instance');
        }
        this.created += 1;
      } catch (error) {
        state.creating -= 1;
        if (shouldDropState(state) && this.modules.get(key) === state) this.modules.delete(key);
        throw error;
      }
      state.creating -= 1;
    }
    state.inUse += 1;
    let released = false;

    const release = ({retire = false} = {}) => {
      if (released) throw new TypeError('WASM instance pool lease already released');
      if (typeof retire !== 'boolean') throw new TypeError('WASM instance pool retire must be a boolean');
      released = true;
      state.inUse -= 1;
      if (retire) {
        this.retired += 1;
      } else if (state.idle.length < this.maxIdlePerModule) {
        state.idle.push(slot);
      } else {
        this.discarded += 1;
      }
      if (shouldDropState(state) && this.modules.get(key) === state) this.modules.delete(key);
    };

    return Object.freeze({slot, release});
  }

  clear() {
    for (const [key, state] of this.modules) {
      state.idle.length = 0;
      if (shouldDropState(state)) this.modules.delete(key);
    }
  }

  resetStats() {
    this.hits = 0;
    this.misses = 0;
    this.created = 0;
    this.retired = 0;
    this.discarded = 0;
  }

  stats() {
    let idle = 0;
    let inUse = 0;
    for (const state of this.modules.values()) {
      idle += state.idle.length;
      inUse += state.inUse;
    }
    return Object.freeze({
      modules: this.modules.size,
      idle,
      inUse,
      hits: this.hits,
      misses: this.misses,
      created: this.created,
      retired: this.retired,
      discarded: this.discarded,
    });
  }
}

export {
  WASM_INSTANCE_REUSE_STATELESS_V0,
  WasmInstancePool,
  modulePoolKey,
};

import {TupleMap} from '../support/tuple-map.js';

// A tuple key, not a joined string: image and object ids are arbitrary non-empty text, so
// no separator is safe to join on. See src/support/tuple-map.js. The key is the module artifact's
// identity and is version-agnostic (v1 or v2) — the caller supplies the raw bytes to compile.
function moduleCacheKey(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact') throw new TypeError('module cache key requires a code-artifact');
  if (typeof artifact.imageId !== 'string' || typeof artifact.id !== 'string') throw new TypeError('module cache key requires imageId and id');
  return [artifact.imageId, artifact.id];
}

class WasmModuleCache {
  constructor({compile = (bytes) => WebAssembly.compile(bytes)} = {}) {
    if (typeof compile !== 'function') throw new TypeError('WASM module cache compile must be a function');
    this.compile = compile;
    this.entries = new TupleMap(2);
    this.hits = 0;
    this.misses = 0;
    this.compilations = 0;
    this.failures = 0;
  }

  // `bytes` are the module's implementation bytes as resolved through the canonical accessor
  // (readModuleContract). The cache never decodes a representation itself: the frozen v1 form
  // and v2 both reach it the same way, so there is exactly one place that knows where bytes live.
  // `bytes` is the module's implementation as resolved through the canonical accessor: either
  // the Uint8Array itself or a thunk returning it, which is invoked ONLY on a cache miss — so a
  // hit resolves and decodes nothing.
  async get(moduleArtifact, bytes) {
    if (!(bytes instanceof Uint8Array) && typeof bytes !== 'function') {
      throw new TypeError('WASM module cache requires the module bytes (or a thunk) resolved through the module-contract accessor');
    }
    const key = moduleCacheKey(moduleArtifact);
    const existing = this.entries.get(key);
    if (existing) {
      this.hits += 1;
      return await existing;
    }

    this.misses += 1;
    this.compilations += 1;
    let pending;
    pending = Promise.resolve()
      .then(async () => {
        const moduleBytes = typeof bytes === 'function' ? await bytes() : bytes;
        if (!(moduleBytes instanceof Uint8Array)) throw new TypeError('WASM module bytes must resolve to a Uint8Array');
        return await this.compile(moduleBytes);
      })
      .then((module) => {
        if (!(module instanceof WebAssembly.Module)) {
          throw new TypeError('WASM module cache compiler must return a WebAssembly.Module');
        }
        return module;
      })
      .catch((error) => {
        this.failures += 1;
        if (this.entries.get(key) === pending) this.entries.delete(key);
        throw error;
      });
    this.entries.set(key, pending);
    return await pending;
  }

  clear() {
    this.entries.clear();
  }

  resetStats() {
    this.hits = 0;
    this.misses = 0;
    this.compilations = 0;
    this.failures = 0;
  }

  stats() {
    return Object.freeze({
      entries: this.entries.size,
      hits: this.hits,
      misses: this.misses,
      compilations: this.compilations,
      failures: this.failures,
    });
  }
}

export {WasmModuleCache, moduleCacheKey};

// The single canonical decoder for a compiled WASM module's executable contract (Bead
// lagrange-images-ygi, ADR pending). The four executors run execution separately, but they must
// NOT each re-interpret the representation schema — they read the contract through here.
//
// wasm-module/v2 (canonical): the executable semantics — abi, literals, function descriptors and
// send/closure/effect sites — live in the artifact's identity-bearing CONTENT as canonical JSON,
// and the raw compiled bytes are a SEPARATELY identity-bearing artifact referenced through one
// `role: implementation` dependency (the same pattern wasm-callable-interface/v1 uses). The
// implementation binding participates in module identity because contentIdentity follows the
// dependency edge into the closure (proven: identical contract + different bytes -> different
// identity), so there is one authority for the binding and no JSON-vs-edge conflict.
//
// wasm-module/v1 (FROZEN, ADR 0035 precedent — a named durable representation is versioned, not
// mutated): the same contract lives in stripped provenance `metadata` with the bytes as content.
// It still executes in-image through this accessor, but it does not survive a portable release —
// which is the defect v2 exists to fix. New compiler output is v2.
//
// `instanceReuse` is deliberately NOT part of the contract here: it is a non-semantic optimization
// (absent -> fresh instance per activation, which is always correct; `stateless-v0` only ever
// denotes the same observable result), so it stays in provenance metadata and may safely disappear
// on install, degrading only to fresh instantiation.
import {bytesValue, canonicalizeValue, isObjectRef, textValue} from '../value/index.js';
import {normalizeMetadata} from '../object/model.js';
import {base64Decode} from '../support/portable-bytes.js';
import {
  WASM_BINARY_V1,
  WASM_IMPLEMENTATION_DEPENDENCY_ROLE,
  assertWasmModuleArtifact as assertWasmModuleV1Artifact,
} from '../code/wasm-artifacts.js';

const WASM_MODULE_V1 = 'wasm-module/v1';
const WASM_MODULE_V2 = 'wasm-module/v2';
const CONTRACT_KEYS = Object.freeze(['abi', 'closureSites', 'effectSites', 'functions', 'literals', 'sendSites']);
// Single-function compilations used to mirror their sole descriptor's entry/parameters/captures/
// cellBindings at the top level of v1 metadata. They are SEMANTIC mirrors of functions[0], so they
// never enter v2 provenance metadata: a v2 module has exactly one authority for them (content).
const SEMANTIC_MIRROR_KEYS = Object.freeze(['entry', 'parameters', 'captures', 'cellBindings']);
const WASM_MODULE_CONTRACT_KEYS = CONTRACT_KEYS;
const WASM_MODULE_SEMANTIC_MIRROR_KEYS = SEMANTIC_MIRROR_KEYS;

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function requiredArray(value, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  return value;
}

function requiredIndex(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

// Deterministic serialization: keys sorted at every level so the descriptor's content bytes — and
// therefore its identity — never drift with object construction order. Not ordinary
// JSON.stringify, whose key order follows insertion.
function canonicalJson(value, path = 'contract') {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'number') {
    // JSON.stringify would silently turn NaN/Infinity into null — a different value under the
    // same identity. Refuse instead: nothing in a contract is allowed to be non-finite.
    if (!Number.isFinite(value)) throw new TypeError(`${path} must be a finite number`);
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) return `[${value.map((entry, index) => canonicalJson(entry, `${path}[${index}]`)).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k], `${path}.${k}`)}`).join(',')}}`;
  }
  throw new TypeError(`${path} contains a non-canonical ${value === undefined ? 'undefined' : typeof value} value`);
}

// Validate + freeze the executable contract (order-independent). The function descriptors keep the
// shape the executors already require (executor.js normalizeModuleFunctions), so this owner defines
// the schema once and the executors consume it.
function normalizeModuleContract(contract, label = 'WASM module contract') {
  if (!contract || typeof contract !== 'object' || Array.isArray(contract)) throw new TypeError(`${label} must be an object`);
  const keys = Object.keys(contract).sort();
  if (keys.length !== CONTRACT_KEYS.length || keys.some((k, i) => k !== CONTRACT_KEYS[i])) {
    throw new TypeError(`${label} must contain exactly ${CONTRACT_KEYS.join(', ')}`);
  }
  const functions = requiredArray(contract.functions, `${label}.functions`);
  if (functions.length === 0) throw new TypeError(`${label}.functions must be non-empty`);
  return Object.freeze({
    abi: requiredText(contract.abi, `${label}.abi`),
    literals: Object.freeze([...requiredArray(contract.literals, `${label}.literals`)]),
    functions: Object.freeze(functions.map((descriptor, index) => normalizeFunctionDescriptor(descriptor, `${label}.functions[${index}]`))),
    sendSites: Object.freeze([...requiredArray(contract.sendSites, `${label}.sendSites`)]),
    closureSites: Object.freeze([...requiredArray(contract.closureSites, `${label}.closureSites`)]),
    effectSites: Object.freeze([...requiredArray(contract.effectSites, `${label}.effectSites`)]),
  });
}

// `cellBindings` is ABI-specific: the lexical-cell ABIs (value-handle-abi/v1, resumable v2) require
// it on every descriptor and the v0 ABIs require its ABSENCE (both executor families check exact
// keys). It is therefore preserved exactly as the compiler emitted it — present or absent — never
// defaulted, so the executors' exact-key contracts hold for either ABI family.
function normalizeFunctionDescriptor(descriptor, label) {
  if (!descriptor || typeof descriptor !== 'object' || Array.isArray(descriptor)) throw new TypeError(`${label} must be an object`);
  return Object.freeze({
    entry: requiredText(descriptor.entry, `${label}.entry`),
    memberIndex: requiredIndex(descriptor.memberIndex, `${label}.memberIndex`),
    parameters: requiredIndex(descriptor.parameters, `${label}.parameters`),
    captures: Object.freeze([...requiredArray(descriptor.captures, `${label}.captures`)]),
    ...(Object.hasOwn(descriptor, 'cellBindings')
      ? {cellBindings: Object.freeze([...requiredArray(descriptor.cellBindings, `${label}.cellBindings`)])}
      : {}),
    sendSiteIndices: Object.freeze([...requiredArray(descriptor.sendSiteIndices, `${label}.sendSiteIndices`)]),
    closureSiteIndices: Object.freeze([...requiredArray(descriptor.closureSiteIndices, `${label}.closureSiteIndices`)]),
  });
}

// The v2 descriptor's canonical content bytes, from a validated contract.
function encodeModuleContractContent(contract) {
  return canonicalJson(normalizeModuleContract(contract));
}

function implementationRef(artifact) {
  const deps = (artifact.dependencies ?? []).filter((d) => d.role === WASM_IMPLEMENTATION_DEPENDENCY_ROLE);
  if (deps.length !== 1) throw new TypeError(`${WASM_MODULE_V2} must have exactly one ${WASM_IMPLEMENTATION_DEPENDENCY_ROLE} dependency`);
  const ref = canonicalizeValue(deps[0].artifact);
  if (!isObjectRef(ref)) throw new TypeError(`${WASM_MODULE_V2} implementation must be an unpinned object ref`);
  return ref;
}

function assertWasmModuleV2Artifact(artifact) {
  if (!artifact || artifact.kind !== 'code-artifact' || artifact.representation !== WASM_MODULE_V2) {
    throw new TypeError(`artifact is not ${WASM_MODULE_V2}`);
  }
  if (artifact.content?.kind !== 'text') throw new TypeError(`${WASM_MODULE_V2} content must be a canonical-JSON text Value`);
  let parsed;
  try {
    parsed = JSON.parse(artifact.content.value);
  } catch (error) {
    throw new TypeError(`${WASM_MODULE_V2} content must be valid JSON`, {cause: error});
  }
  // Canonical form is enforced on READ as well as on write: a descriptor whose bytes are not the
  // canonical serialization of its own contract would carry a different identity for the same
  // meaning, so it is not a v2 module at all.
  if (canonicalJson(normalizeModuleContract(parsed, `${WASM_MODULE_V2} content`)) !== artifact.content.value) {
    throw new TypeError(`${WASM_MODULE_V2} content is not the canonical serialization of its contract`);
  }
  implementationRef(artifact);
  return artifact;
}

function isWasmModuleArtifact(artifact) {
  return artifact?.kind === 'code-artifact'
    && (artifact.representation === WASM_MODULE_V1 || artifact.representation === WASM_MODULE_V2);
}

// Either durable version of a compiled module. v1 is validated by its frozen contract owner
// (src/code/wasm-artifacts.js), v2 by this module.
function assertWasmModuleArtifactAnyVersion(artifact) {
  if (artifact?.representation === WASM_MODULE_V2) return assertWasmModuleV2Artifact(artifact);
  if (artifact?.representation === WASM_MODULE_V1) return assertWasmModuleV1Artifact(artifact);
  throw new TypeError(`not a WASM module artifact: ${artifact?.representation ?? 'missing'}`);
}

// The executable contract WITHOUT the bytes — what a compile-side reader (function assembly, tree
// installation) needs. Synchronous: neither version requires resolving the implementation to know
// its abi, literals, sites or function table.
function readModuleDescriptor(artifact) {
  if (artifact?.representation === WASM_MODULE_V2) {
    assertWasmModuleV2Artifact(artifact);
    return normalizeModuleContract(JSON.parse(artifact.content.value), `${WASM_MODULE_V2} content`);
  }
  if (artifact?.representation === WASM_MODULE_V1) {
    // Frozen v1: contract in provenance metadata. Decoded leniently exactly as before (the v1
    // executors validate the schema themselves), never through the v2 normalizer.
    if (artifact.content?.kind !== 'bytes') throw new TypeError(`${WASM_MODULE_V1} content must be a bytes Value`);
    const md = artifact.metadata ?? {};
    const sendSites = Object.freeze([...(md.sendSites ?? [])]);
    const closureSites = Object.freeze([...(md.closureSites ?? [])]);
    return Object.freeze({
      abi: requiredText(md.abi, `${WASM_MODULE_V1} metadata.abi`),
      literals: Object.freeze([...(md.literals ?? [])]),
      functions: Array.isArray(md.functions)
        ? Object.freeze([...md.functions])
        // The oldest v1 sub-form (before the functions table): one entry described by the
        // top-level entry/parameters/captures[/cellBindings] mirrors, using every site. This is
        // exactly the fallback the executors and function assembly applied before the accessor
        // existed, kept here — in the frozen decoder — so those artifacts stay executable.
        : Object.freeze([Object.freeze({
          entry: requiredText(md.entry, `${WASM_MODULE_V1} metadata.entry`),
          memberIndex: 0,
          parameters: md.parameters,
          captures: Object.freeze([...(md.captures ?? [])]),
          ...(Object.hasOwn(md, 'cellBindings') ? {cellBindings: Object.freeze([...md.cellBindings])} : {}),
          sendSiteIndices: Object.freeze(sendSites.map((_, index) => index)),
          closureSiteIndices: Object.freeze(closureSites.map((_, index) => index)),
        })]),
      sendSites,
      closureSites,
      effectSites: Object.freeze([...(md.effectSites ?? [])]),
    });
  }
  throw new TypeError(`not a WASM module artifact: ${artifact?.representation ?? 'missing'}`);
}

// The module's implementation bytes ONLY, resolved through the one place that knows where they
// live (the implementation dependency for v2, the content for frozen v1). Executors hand this to
// the module cache as a thunk, so a cache hit resolves and decodes nothing.
async function readModuleImplementationBytes(artifact, {resolveImplementation} = {}) {
  if (artifact?.representation === WASM_MODULE_V2) {
    if (typeof resolveImplementation !== 'function') {
      throw new TypeError(`${WASM_MODULE_V2} requires resolveImplementation(ref) to read its bytes`);
    }
    const ref = implementationRef(artifact);
    const impl = await resolveImplementation(ref);
    if (!impl || impl.content?.kind !== 'bytes') {
      throw new TypeError(`${WASM_MODULE_V2} implementation ${ref.imageId}/${ref.objectId} must be a bytes artifact`);
    }
    return base64Decode(impl.content.base64);
  }
  if (artifact?.representation === WASM_MODULE_V1) {
    if (artifact.content?.kind !== 'bytes') throw new TypeError(`${WASM_MODULE_V1} content must be a bytes Value`);
    return base64Decode(artifact.content.base64);
  }
  throw new TypeError(`not a WASM module artifact: ${artifact?.representation ?? 'missing'}`);
}

// THE canonical accessor. Returns {bytes, abi, literals, functions, sendSites, closureSites,
// effectSites} for either version. `resolveImplementation(ref)` fetches the raw bytes artifact for
// v2 (an executor passes context.images.getCodeArtifact); it is never called for v1.
async function readModuleContract(artifact, {resolveImplementation} = {}) {
  const descriptor = readModuleDescriptor(artifact);
  return Object.freeze({bytes: await readModuleImplementationBytes(artifact, {resolveImplementation}), ...descriptor});
}

// Select one function of a module's contract by entry name or member index. The ONE lookup every
// compile-side reader (function assembly, tree installation, class builder) uses.
function moduleFunctionOf(descriptor, {entry, memberIndex} = {}) {
  const functions = descriptor?.functions ?? [];
  const found = entry !== undefined
    ? functions.find((candidate) => candidate?.entry === entry)
    : functions.find((candidate) => candidate?.memberIndex === memberIndex);
  if (!found) {
    throw new TypeError(`WASM module function not found: ${entry !== undefined ? `entry ${entry}` : `member ${memberIndex}`}`);
  }
  return found;
}

// A single-source compilation exports exactly one function; that is the entry a function artifact
// derived from it selects. Replaces the old top-level metadata.entry mirror.
function soleModuleEntry(descriptor) {
  const functions = descriptor?.functions ?? [];
  if (functions.length !== 1) throw new TypeError(`WASM module exports ${functions.length} functions; expected exactly one`);
  return functions[0].entry;
}

// THE durable v2 graph for one compilation, described ONCE here (the representation owner) as a
// generic compilation RESULT GRAPH the CompilationService persists atomically:
//   'implementation'  wasm-binary/v1  — the exact compiled bytes, the neutral raw-byte owner
//   'module'          wasm-module/v2  — canonical-JSON contract + ONE role:implementation dependency
// Compilers hand in compilation FACTS {bytes, contract, metadata}; they never build artifacts.
// `metadata` is provenance only: a contract field or a semantic mirror there is refused, so the
// descriptor content stays the single authority for meaning.
function describeWasmModuleV2Result({languageId, bytes, contract, metadata = {}} = {}) {
  if (!(bytes instanceof Uint8Array) || bytes.length === 0) throw new TypeError('WASM module bytes must be a non-empty Uint8Array');
  const normalized = normalizeModuleContract(contract);
  const provenance = normalizeMetadata(metadata, `${WASM_MODULE_V2} provenance metadata`);
  for (const key of [...CONTRACT_KEYS, ...SEMANTIC_MIRROR_KEYS]) {
    if (Object.hasOwn(provenance, key)) {
      throw new TypeError(`${WASM_MODULE_V2} provenance metadata must not carry the semantic field ${key}`);
    }
  }
  return Object.freeze({
    // Only when the compiler stated one: an absent languageId lets the CompilationService apply
    // its own fallback (the source's, or the group members' common language).
    ...(languageId === undefined ? {} : {languageId}),
    primary: 'module',
    artifacts: Object.freeze([
      Object.freeze({key: 'implementation', representation: WASM_BINARY_V1, content: bytesValue(bytes), dependencies: [], metadata: {}}),
      Object.freeze({
        key: 'module',
        representation: WASM_MODULE_V2,
        content: textValue(canonicalJson(normalized)),
        dependencies: [{role: WASM_IMPLEMENTATION_DEPENDENCY_ROLE, artifact: 'implementation'}],
        metadata: provenance,
      }),
    ]),
  });
}

export {
  WASM_IMPLEMENTATION_DEPENDENCY_ROLE,
  WASM_MODULE_CONTRACT_KEYS,
  WASM_MODULE_SEMANTIC_MIRROR_KEYS,
  WASM_MODULE_V1,
  WASM_MODULE_V2,
  assertWasmModuleArtifactAnyVersion,
  assertWasmModuleV2Artifact,
  canonicalJson,
  describeWasmModuleV2Result,
  encodeModuleContractContent,
  implementationRef,
  isWasmModuleArtifact,
  moduleFunctionOf,
  normalizeModuleContract,
  readModuleContract,
  readModuleDescriptor,
  readModuleImplementationBytes,
  soleModuleEntry,
};

const WASM_RESUMABLE_VALUE_HANDLE_ABI_V1 = 'lagrange-value-handle-resumable/v1';
// The resumable ABI is versioned independently of the simple one, so mutable lexical state
// advances it separately. A cell must stay correct across a non-tail send and its resumption,
// which is a property of the continuation machinery rather than of the cell operations.
const WASM_RESUMABLE_VALUE_HANDLE_ABI_V2 = 'lagrange-value-handle-resumable/v2';

export {WASM_RESUMABLE_VALUE_HANDLE_ABI_V1, WASM_RESUMABLE_VALUE_HANDLE_ABI_V2};

import {
  I32,
  functionExport,
  functionImport,
  functionType,
  s32,
  section,
  u32,
  vector,
} from './encoding.js';
import {
  LAGRANGE_CODE_V1,
  LAGRANGE_CODE_V2,
  parseLagrangeCodeV1Program,
  parseLagrangeCodeV2Program,
} from '../code/lagrange-code-v1.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {WASM_ENTRY_V0, WASM_IMPORT_MODULE} from './abi.js';
import {WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1} from './compiler-v1.js';
import {WASM_RESUMABLE_VALUE_HANDLE_ABI_V2} from './resumable-abi.js';
import {
  analyzeLivePlanVariables,
  optimizeNonEscapingClosures,
  planIntraModuleDirectCalls,
} from './group-optimizations.js';

// lagrange-value-handle-resumable/v2: the resumable lane for lagrange-code/v1.
//
// The rule the whole design turns on is that **cell identity is never continuation state**.
//
//   a Value already read from a cell   may be saved across suspension, because evaluation
//                                      consumed that read before suspending
//   a future cell read or write        always goes through cell_get / cell_set
//
// So a cell becomes an explicit synchronous CPS operation sitting at its evaluation position,
// never a `$capture:` parameter threaded through resume entries. The v1 resumable compiler treats
// every binding as a capture parameter, which is exactly the part that cannot survive mutation.
//
// The savedValues machinery is unchanged in spirit: it saves Value handles that have already been
// computed, not lexical variables.
const BASE_IMPORT_COUNT_V2 = 6;
const CELL_GET_IMPORT = 4;
const CELL_SET_IMPORT = 5;

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeModuleEntry(value, index) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`WASM module entry ${index} must be an object`);
  const entry = requiredText(value.entry, `WASM module entry ${index} name`);
  if (!Number.isInteger(value.memberIndex) || value.memberIndex < 0) {
    throw new TypeError(`WASM module entry ${index} memberIndex must be a non-negative integer`);
  }
  return Object.freeze({
    entry,
    memberIndex: value.memberIndex,
    program: value.program,
    allowApply: value.allowApply === true,
    semanticBlockId: typeof value.semanticBlockId === 'string' && value.semanticBlockId.length > 0
      ? value.semanticBlockId
      : null,
  });
}

function collectLiteral(literals, value) {
  const normalized = canonicalizeValue(value);
  if (isReference(normalized)) throw new TypeError('WASM resumable backend does not embed reference literals; use arguments/captures instead');
  const key = JSON.stringify(normalized);
  const existing = literals.keys.get(key);
  if (existing !== undefined) return existing;
  const index = literals.values.length;
  literals.values.push(normalized);
  literals.keys.set(key, index);
  return index;
}

function normalizeCaptureDescriptor(capture, index) {
  const label = `WASM closure capture ${index}`;
  const mode = requiredText(capture?.mode, `${label} mode`);
  if (mode === 'cell') {
    exactKeys(capture, ['id', 'mode', 'name'], label);
    return Object.freeze({
      id: requiredText(capture.id, `${label} id`),
      name: requiredText(capture.name, `${label} name`),
      mode: 'cell',
    });
  }
  if (mode !== 'snapshot') throw new TypeError(`${label} mode must be snapshot or cell`);
  exactKeys(capture, ['id', 'mode', 'name', 'value'], label);
  return Object.freeze({
    id: requiredText(capture.id, `${label} id`),
    name: requiredText(capture.name, `${label} name`),
    mode: 'snapshot',
  });
}

function newTemp(state) {
  const id = `$t${state.nextTemp}`;
  state.nextTemp += 1;
  return id;
}

function collectSendEffect(state, expression) {
  if (!Array.isArray(expression.arguments)) throw new TypeError('WASM send arguments must be an array');
  const message = canonicalizeValue(expression.message);
  if (isReference(message)) throw new TypeError('WASM resumable backend does not place reference messages in module metadata');
  const siteIndex = state.sendSites.length;
  state.sendSites.push(Object.freeze({
    languageId: requiredText(expression.languageId, 'send languageId'),
    message,
    arity: expression.arguments.length,
  }));
  const effectIndex = state.effects.length;
  state.effects.push({
    kind: 'send',
    siteIndex,
    requestArity: 1 + expression.arguments.length,
    savedCount: 0,
    resumeEntry: null,
  });
  return effectIndex;
}

function collectApplyEffect(state, expression) {
  if (!Array.isArray(expression.arguments)) throw new TypeError('WASM apply arguments must be an array');
  const siteIndex = state.sendSites.length;
  state.sendSites.push(Object.freeze({
    kind: 'apply',
    arity: expression.arguments.length,
  }));
  const effectIndex = state.effects.length;
  state.effects.push({
    kind: 'send',
    siteIndex,
    requestArity: 1 + expression.arguments.length,
    savedCount: 0,
    resumeEntry: null,
  });
  return effectIndex;
}

// requestArity counts snapshot captures only, exactly as in the simple v1 backend. Saved
// continuation handles follow the request handles, and the two counts stay separate.
function collectClosureEffect(state, expression) {
  if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
  const captures = Object.freeze(expression.captures.map(normalizeCaptureDescriptor));
  const siteIndex = state.closureSites.length;
  state.closureSites.push(Object.freeze({
    blockId: requiredText(expression.blockId, 'WASM semantic block id'),
    captures,
  }));
  const effectIndex = state.effects.length;
  state.effects.push({
    kind: 'closure',
    siteIndex,
    requestArity: captures.filter(({mode}) => mode === 'snapshot').length,
    savedCount: 0,
    resumeEntry: null,
  });
  return effectIndex;
}

function lowerSequenceValues(expressions, state, context, index, values, done) {
  if (index >= expressions.length) return done(values);
  return lowerExpression(expressions[index], state, context, (value) =>
    lowerSequenceValues(expressions, state, context, index + 1, [...values, value], done));
}

function lowerExpression(expression, state, context, continuation) {
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) {
    throw new TypeError('WASM compiler expression must be an object');
  }

  switch (expression.op) {
    case 'literal': {
      const id = newTemp(state);
      const value = canonicalizeValue(expression.value);
      if (isReference(value)) throw new TypeError('WASM resumable backend does not embed reference literals; use arguments/captures instead');
      return {kind: 'let', id, op: 'literal', value, next: continuation(id)};
    }
    case 'argument': {
      if (!Number.isInteger(expression.index) || expression.index < 0 || expression.index >= context.parameterCount) {
        throw new TypeError(`WASM argument index out of range: ${expression.index}`);
      }
      return continuation(`$argument:${expression.index}`);
    }
    case 'receiver':
      return continuation('$receiver');
    case 'binding': {
      // A cell read is a `let` at this evaluation position. Its *result* may then be saved across a
      // later suspension, which is correct: the read already happened. What must never happen is
      // the cell itself becoming a continuation parameter.
      const slot = context.cellSlots.get(expression.id);
      if (slot !== undefined) {
        const id = newTemp(state);
        return {kind: 'let', id, op: 'cell-get', slot, next: continuation(id)};
      }
      if (!context.captureIds.has(expression.id)) {
        throw new TypeError(`WASM binding is neither a cell nor a snapshot capture: ${expression.id}`);
      }
      return continuation(`$capture:${expression.id}`);
    }
    case 'binding-write': {
      const slot = context.cellSlots.get(expression.id);
      if (slot === undefined) throw new TypeError(`WASM assignment target is not a cell: ${expression.id}`);
      // The write node sits after the right-hand side in the continuation. If that side suspends,
      // splitPlan moves this node into the resume segment, so the cell is written after resumption
      // with the returned result — never prepared or performed early.
      return lowerExpression(expression.value, state, context, (value) => {
        const id = newTemp(state);
        return {kind: 'let', id, op: 'cell-set', slot, value, next: continuation(id)};
      });
    }
    case 'sequence': {
      if (!Array.isArray(expression.statements) || expression.statements.length === 0) {
        throw new TypeError('sequence statements must be a non-empty array');
      }
      const last = expression.statements.length - 1;
      const lowerFrom = (index) => (index === last
        ? lowerExpression(expression.statements[index], state, context, continuation)
        : lowerExpression(expression.statements[index], state, context, () => lowerFrom(index + 1)));
      return lowerFrom(0);
    }
    case 'integer-add':
    case 'equals':
      return lowerExpression(expression.left, state, context, (left) =>
        lowerExpression(expression.right, state, context, (right) => {
          const id = newTemp(state);
          return {kind: 'let', id, op: expression.op, left, right, next: continuation(id)};
        }));
    case 'if':
      return lowerExpression(expression.condition, state, context, (condition) => ({
        kind: 'if',
        condition,
        then: lowerExpression(expression.then, state, context, continuation),
        else: lowerExpression(expression.else, state, context, continuation),
      }));
    case 'send':
      return lowerExpression(expression.receiver, state, context, (receiver) =>
        lowerSequenceValues(expression.arguments, state, context, 0, [], (args) => {
          const resultId = newTemp(state);
          return {
            kind: 'effect',
            effectIndex: collectSendEffect(state, expression),
            requestValues: [receiver, ...args],
            resultId,
            next: continuation(resultId),
          };
        }));
    case 'apply': {
      if (!context.allowApply) throw new TypeError(`WASM resumable backend v2 does not support semantic op: ${expression.op}`);
      if (!Array.isArray(expression.arguments)) throw new TypeError('WASM apply arguments must be an array');
      if (context.directCalls) {
        let directTarget = null;
        let captureExprs = [];
        if (expression.callee?.op === 'binding' && context.directCalls.bindingTargets.has(expression.callee.id)) {
          const target = context.directCalls.bindingTargets.get(expression.callee.id);
          if (target.directCallable && target.parameterCount === expression.arguments.length) {
            directTarget = target;
            captureExprs = target.captureExpressions ?? [];
          }
        } else if (expression.callee?.op === 'block' && context.directCalls.bySemanticBlockId.has(expression.callee.blockId)) {
          const target = context.directCalls.bySemanticBlockId.get(expression.callee.blockId);
          if (target.directCallable && target.parameterCount === expression.arguments.length) {
            directTarget = target;
            captureExprs = (expression.callee.captures ?? [])
              .filter(({mode}) => mode === 'snapshot')
              .map(({value}) => value);
          }
        }
        if (directTarget) {
          state.intraModuleDirectCalls.push(Object.freeze({
            callerEntry: context.entryName,
            targetEntry: directTarget.entry,
            targetMemberIndex: directTarget.memberIndex,
            arity: expression.arguments.length,
          }));
          return lowerSequenceValues([...expression.arguments, ...captureExprs], state, context, 0, [], (callValues) => {
            const resultId = newTemp(state);
            return {
              kind: 'let',
              id: resultId,
              op: 'direct-call',
              targetEntry: directTarget.entry,
              targetMemberIndex: directTarget.memberIndex,
              callValues,
              next: continuation(resultId),
            };
          });
        }
      }
      return lowerExpression(expression.callee, state, context, (callee) =>
        lowerSequenceValues(expression.arguments, state, context, 0, [], (args) => {
          const resultId = newTemp(state);
          return {
            kind: 'effect',
            effectIndex: collectApplyEffect(state, expression),
            requestValues: [callee, ...args],
            resultId,
            next: continuation(resultId),
          };
        }));
    }
    case 'make-block':
    case 'block': {
      if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
      expression.captures.forEach((capture, index) => normalizeCaptureDescriptor(capture, index));
      // Only snapshot captures contribute request handles. A cell capture is reconstructed by the
      // host from site metadata, so there is no handle position it could arrive through.
      const snapshotValues = expression.captures
        .filter(({mode}) => mode === 'snapshot')
        .map(({value}) => value);
      return lowerSequenceValues(snapshotValues, state, context, 0, [], (captures) => {
        const resultId = newTemp(state);
        return {
          kind: 'effect',
          effectIndex: collectClosureEffect(state, expression),
          requestValues: captures,
          resultId,
          next: continuation(resultId),
        };
      });
    }
    default:
      throw new TypeError(`WASM resumable backend v2 does not support semantic op: ${expression.op}`);
  }
}

function directEffectReturn(plan) {
  return plan.next?.kind === 'return' && plan.next.value === plan.resultId;
}

function splitPlan(plan, available, state, rootEntry, segments) {
  switch (plan.kind) {
    case 'let':
      return {
        ...plan,
        next: splitPlan(plan.next, [...available, plan.id], state, rootEntry, segments),
      };
    case 'if':
      return {
        ...plan,
        then: splitPlan(plan.then, [...available], state, rootEntry, segments),
        else: splitPlan(plan.else, [...available], state, rootEntry, segments),
      };
    case 'return':
      return plan;
    case 'effect': {
      const effect = state.effects[plan.effectIndex];
      if (directEffectReturn(plan)) {
        effect.savedCount = 0;
        effect.resumeEntry = null;
        return {
          kind: 'effect-terminal',
          effectIndex: plan.effectIndex,
          requestValues: plan.requestValues,
          savedValues: [],
        };
      }

      const liveness = state.optimizeLiveHandles
        ? analyzeLivePlanVariables(plan.next, available)
        : {savedValues: [...available], eliminatedValues: []};
      const savedValues = [...liveness.savedValues];
      state.liveHandleSites.push(Object.freeze({
        effectIndex: plan.effectIndex,
        savedCount: savedValues.length,
        eliminatedCount: liveness.eliminatedValues.length,
        savedVariables: Object.freeze([...savedValues]),
        eliminatedVariables: Object.freeze([...liveness.eliminatedValues]),
      }));
      const resumeEntry = `${rootEntry}$resume_${plan.effectIndex}`;
      if (state.exportNames.has(resumeEntry)) throw new TypeError(`duplicate WASM resume export entry: ${resumeEntry}`);
      state.exportNames.add(resumeEntry);
      effect.savedCount = savedValues.length;
      effect.resumeEntry = resumeEntry;

      const continuationSegment = {
        entry: resumeEntry,
        parameterVars: [...savedValues, plan.resultId],
        effectIndex: plan.effectIndex,
        root: false,
        plan: null,
      };
      segments.push(continuationSegment);
      continuationSegment.plan = splitPlan(
        plan.next,
        [...savedValues, plan.resultId],
        state,
        rootEntry,
        segments,
      );

      return {
        kind: 'effect-terminal',
        effectIndex: plan.effectIndex,
        requestValues: plan.requestValues,
        savedValues,
      };
    }
    default:
      throw new TypeError(`unknown resumable plan node: ${plan.kind}`);
  }
}

function compilePlan(plan, context) {
  const localGet = (id) => {
    const index = context.env.get(id);
    if (index === undefined) throw new TypeError(`WASM resumable variable is unavailable: ${id}`);
    return [0x20, ...u32(index)];
  };

  const localFor = (id) => {
    const existing = context.env.get(id);
    if (existing !== undefined) return existing;
    const index = context.parameterCount + context.localCount;
    context.localCount += 1;
    context.env.set(id, index);
    return index;
  };

  switch (plan.kind) {
    case 'let': {
      const localIndex = localFor(plan.id);
      let valueCode;
      if (plan.op === 'literal') {
        const literalIndex = collectLiteral(context.literals, plan.value);
        valueCode = [0x41, ...s32(literalIndex), 0x10, ...u32(0)];
      } else if (plan.op === 'integer-add') {
        valueCode = [...localGet(plan.left), ...localGet(plan.right), 0x10, ...u32(1)];
      } else if (plan.op === 'equals') {
        valueCode = [...localGet(plan.left), ...localGet(plan.right), 0x10, ...u32(2)];
      } else if (plan.op === 'cell-get') {
        valueCode = [0x41, ...s32(plan.slot), 0x10, ...u32(CELL_GET_IMPORT)];
      } else if (plan.op === 'cell-set') {
        valueCode = [0x41, ...s32(plan.slot), ...localGet(plan.value), 0x10, ...u32(CELL_SET_IMPORT)];
      } else if (plan.op === 'direct-call') {
        const targetFuncIdx = context.rootFunctionIndices?.get(plan.targetEntry);
        if (targetFuncIdx === undefined) {
          throw new TypeError(`WASM intra-module direct call target not found: ${plan.targetEntry}`);
        }
        valueCode = [
          0x41, ...s32(0),
          ...plan.callValues.flatMap(localGet),
          0x10, ...u32(targetFuncIdx),
        ];
      } else {
        throw new TypeError(`unknown resumable pure op: ${plan.op}`);
      }
      return [...valueCode, 0x21, ...u32(localIndex), ...compilePlan(plan.next, context)];
    }
    case 'if':
      return [
        ...localGet(plan.condition),
        0x10, ...u32(3),
        0x04, 0x40,
        ...compilePlan(plan.then, context),
        0x05,
        ...compilePlan(plan.else, context),
        0x0b,
        0x00,
      ];
    case 'effect-terminal':
      return [
        ...plan.requestValues.flatMap(localGet),
        ...plan.savedValues.flatMap(localGet),
        0x10, ...u32(BASE_IMPORT_COUNT_V2 + plan.effectIndex),
        0x0f,
      ];
    case 'return':
      return [...localGet(plan.value), 0x0f];
    default:
      throw new TypeError(`unknown resumable plan node: ${plan.kind}`);
  }
}

function compileSegment(segment, literals, rootFunctionIndices = new Map()) {
  const env = new Map(segment.parameterVars.map((name, index) => [name, index]));
  const context = {
    env,
    parameterCount: segment.parameterVars.length,
    localCount: 0,
    literals,
    rootFunctionIndices,
  };
  const instructions = compilePlan(segment.plan, context);
  const localDeclarations = context.localCount === 0
    ? [0x00]
    : [0x01, ...u32(context.localCount), I32];
  const body = [...localDeclarations, ...instructions, 0x00, 0x0b];
  return Object.freeze({
    entry: segment.entry,
    parameterCount: segment.parameterVars.length,
    effectIndex: segment.effectIndex ?? null,
    root: segment.root,
    body: [...u32(body.length), ...body],
  });
}

function prepareEntries(entries) {
  if (!Array.isArray(entries) || entries.length === 0) throw new TypeError('WASM module entries must be a non-empty array');
  const normalizedEntries = entries.map(normalizeModuleEntry);
  const entryNames = new Set();
  const memberIndices = new Set();
  for (const entry of normalizedEntries) {
    if (entryNames.has(entry.entry)) throw new TypeError(`duplicate WASM export entry: ${entry.entry}`);
    if (memberIndices.has(entry.memberIndex)) throw new TypeError(`duplicate WASM member index: ${entry.memberIndex}`);
    entryNames.add(entry.entry);
    memberIndices.add(entry.memberIndex);
  }
  return {normalizedEntries, entryNames};
}

// Same slot table as the simple v1 backend, and function-local for the same reason: a shared module
// holds several semantic Blocks whose static binding ids all begin `root:`.
function cellBindingsOf(program) {
  const bindings = [];
  const slots = new Map();
  const declare = ({id, name}, source) => {
    if (slots.has(id)) return;
    slots.set(id, bindings.length);
    bindings.push(Object.freeze({id, name, source}));
  };
  for (const temporary of program.temporaries) declare(temporary, 'temporary');
  for (const capture of program.captures) {
    if (capture.mode === 'cell') declare(capture, 'capture');
  }
  return {bindings: Object.freeze(bindings), slots};
}

function compileResumableWasmV2ModuleEntries(entries, {
  allowApply = false,
  optimizeLiveHandles = true,
  optimizeClosures = false,
  intraModuleDirectCalls = false,
  intraModuleCallTargets = null,
} = {}) {
  const {normalizedEntries, entryNames} = prepareEntries(entries);
  const effectiveEntries = optimizeClosures
    ? normalizedEntries.map((entry) => ({
      ...entry,
      program: optimizeNonEscapingClosures(entry.program).program,
    }))
    : normalizedEntries;
  const directCalls = (intraModuleDirectCalls || intraModuleCallTargets)
    ? planIntraModuleDirectCalls(effectiveEntries, {intraModuleCallTargets})
    : null;
  const state = {
    sendSites: [],
    closureSites: [],
    effects: [],
    nextTemp: 0,
    exportNames: new Set(entryNames),
    optimizeLiveHandles: Boolean(optimizeLiveHandles),
    liveHandleSites: [],
    intraModuleDirectCalls: [],
  };
  const segments = [];
  const functionDescriptors = [];

  for (const entry of effectiveEntries) {
    const program = entry.program;
    if (!program || !Array.isArray(program.parameters) || !Array.isArray(program.captures) || !Array.isArray(program.temporaries)) {
      throw new TypeError(`WASM module entry ${entry.entry} program must contain parameters, temporaries and captures arrays`);
    }
    // Only snapshot captures become entry parameters. Cell captures are reached through the slot
    // table, so they never appear in a segment signature — root or resume.
    const captureIds = program.captures
      .filter(({mode}) => mode !== 'cell')
      .map(({id}, index) => requiredText(id, `WASM capture ${index} id`));
    if (new Set(captureIds).size !== captureIds.length) throw new TypeError(`WASM module entry ${entry.entry} has duplicate capture ids`);
    const {bindings: cellBindings, slots: cellSlots} = cellBindingsOf(program);
    const context = {
      entryName: entry.entry,
      parameterCount: program.parameters.length,
      captureIds: new Set(captureIds),
      cellSlots,
      allowApply: allowApply || entry.allowApply,
      directCalls,
    };

    const sendStart = state.sendSites.length;
    const closureStart = state.closureSites.length;
    const plan = lowerExpression(program.body, state, context, (value) => ({kind: 'return', value}));
    const parameterVars = [
      '$receiver',
      ...Array.from({length: program.parameters.length}, (_, index) => `$argument:${index}`),
      ...captureIds.map((id) => `$capture:${id}`),
    ];
    const rootSegment = {
      entry: entry.entry,
      parameterVars,
      effectIndex: null,
      root: true,
      plan: null,
    };
    segments.push(rootSegment);
    rootSegment.plan = splitPlan(plan, [...parameterVars], state, entry.entry, segments);

    functionDescriptors.push(Object.freeze({
      entry: entry.entry,
      memberIndex: entry.memberIndex,
      parameters: program.parameters.length,
      captures: Object.freeze(captureIds),
      cellBindings,
      sendSiteIndices: Object.freeze(Array.from(
        {length: state.sendSites.length - sendStart},
        (_, offset) => sendStart + offset,
      )),
      closureSiteIndices: Object.freeze(Array.from(
        {length: state.closureSites.length - closureStart},
        (_, offset) => closureStart + offset,
      )),
    }));
  }

  const literals = {values: [], keys: new Map()};
  const firstFunctionIndex = BASE_IMPORT_COUNT_V2 + state.effects.length;
  const rootFunctionIndices = new Map();
  segments.forEach((segment, index) => {
    if (segment.root) rootFunctionIndices.set(segment.entry, firstFunctionIndex + index);
  });
  const compiledSegments = segments.map((segment) => compileSegment(segment, literals, rootFunctionIndices));
  const effectSites = Object.freeze(state.effects.map((effect) => Object.freeze({
    kind: effect.kind,
    siteIndex: effect.siteIndex,
    requestArity: effect.requestArity,
    savedCount: effect.savedCount,
    resumeEntry: effect.resumeEntry,
  })));
  const continuations = Object.freeze(compiledSegments
    .filter(({root}) => !root)
    .map(({entry, effectIndex, parameterCount}) => Object.freeze({
      entry,
      effectIndex,
      parameters: parameterCount,
    })));

  const effectTypes = effectSites.map(({requestArity, savedCount}) =>
    functionType(Array.from({length: requestArity + savedCount}, () => I32), [I32]));
  const segmentTypes = compiledSegments.map(({parameterCount}) =>
    functionType(Array.from({length: parameterCount}, () => I32), [I32]));
  const types = vector([
    functionType([I32], [I32]),
    functionType([I32, I32], [I32]),
    ...effectTypes,
    ...segmentTypes,
  ]);

  const effectImports = effectSites.map((effect, effectIndex) => {
    const name = effect.kind === 'send'
      ? `send_site_${effect.siteIndex}`
      : `make_block_site_${effect.siteIndex}`;
    return functionImport(WASM_IMPORT_MODULE, name, 2 + effectIndex);
  });
  const imports = vector([
    functionImport(WASM_IMPORT_MODULE, 'literal', 0),
    functionImport(WASM_IMPORT_MODULE, 'integer_add', 1),
    functionImport(WASM_IMPORT_MODULE, 'equals', 1),
    functionImport(WASM_IMPORT_MODULE, 'is_true', 0),
    functionImport(WASM_IMPORT_MODULE, 'cell_get', 0),
    functionImport(WASM_IMPORT_MODULE, 'cell_set', 1),
    ...effectImports,
  ]);

  const firstSegmentTypeIndex = 2 + effectSites.length;
  const functions = vector(compiledSegments.map((_, index) => [...u32(firstSegmentTypeIndex + index)]));
  const exports = vector(compiledSegments.map(({entry}, index) => functionExport(entry, firstFunctionIndex + index)));
  const code = vector(compiledSegments.map(({body}) => body));

  return Object.freeze({
    bytes: new Uint8Array([
      0x00, 0x61, 0x73, 0x6d,
      0x01, 0x00, 0x00, 0x00,
      ...section(1, types),
      ...section(2, imports),
      ...section(3, functions),
      ...section(7, exports),
      ...section(10, code),
    ]),
    literals: Object.freeze(literals.values),
    sendSites: Object.freeze(state.sendSites),
    closureSites: Object.freeze(state.closureSites),
    effectSites,
    continuations,
    functions: Object.freeze(functionDescriptors),
    liveHandleOptimization: Object.freeze({
      enabled: state.optimizeLiveHandles,
      totalSavedHandles: state.liveHandleSites.reduce((sum, s) => sum + s.savedCount, 0),
      eliminatedHandleCount: state.liveHandleSites.reduce((sum, s) => sum + s.eliminatedCount, 0),
      sites: Object.freeze([...state.liveHandleSites]),
    }),
    intraModuleDirectCalls: Object.freeze([...state.intraModuleDirectCalls]),
  });
}

function compileResumableWasmV2Module(program, options = {}) {
  const compiled = compileResumableWasmV2ModuleEntries([{entry: WASM_ENTRY_V0, memberIndex: 0, program}], options);
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
    cellBindings: descriptor.cellBindings,
  });
}

function compileResumableWasmV2ModuleForV2(program, options = {}) {
  const compiled = compileResumableWasmV2ModuleEntries(
    [{entry: WASM_ENTRY_V0, memberIndex: 0, program, allowApply: true}],
    {...options, allowApply: true},
  );
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
    cellBindings: descriptor.cellBindings,
  });
}

const lagrangeCodeV1ToResumableWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V1) throw new TypeError(`source must be ${LAGRANGE_CODE_V1}`);
    const compiled = compileResumableWasmV2Module(parseLagrangeCodeV1Program(source));
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V2,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: compiled.effectSites,
      },
      metadata: {
        continuations: compiled.continuations,
        semanticRepresentation: LAGRANGE_CODE_V1,
      },
    });
  },
});

const lagrangeCodeV2ToResumableWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V2) throw new TypeError(`source must be ${LAGRANGE_CODE_V2}`);
    const compiled = compileResumableWasmV2ModuleForV2(parseLagrangeCodeV2Program(source));
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V2,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: compiled.effectSites,
      },
      metadata: {
        continuations: compiled.continuations,
        semanticRepresentation: LAGRANGE_CODE_V2,
      },
    });
  },
});

const lagrangeCodeV1GroupToResumableWasmModuleCompiler = Object.freeze({
  async compile({group, members}) {
    if (group.policyId !== WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1) {
      throw new TypeError(`unsupported WASM compilation group policy: ${group.policyId}`);
    }
    if (group.options?.physicalLayout !== 'shared-module') {
      throw new TypeError('WASM shared-module compiler requires physicalLayout=shared-module');
    }
    const entries = members.map((source, memberIndex) => {
      if (source.representation !== LAGRANGE_CODE_V1 && source.representation !== LAGRANGE_CODE_V2) {
        throw new TypeError(`WASM group member ${memberIndex} must be ${LAGRANGE_CODE_V1}`);
      }
      const isV2 = source.representation === LAGRANGE_CODE_V2;
      return {
        entry: `run_${memberIndex}`,
        memberIndex: Number.isInteger(group.options?.memberIndices?.[memberIndex])
          ? group.options.memberIndices[memberIndex]
          : memberIndex,
        program: isV2 ? parseLagrangeCodeV2Program(source) : parseLagrangeCodeV1Program(source),
        allowApply: isV2,
        semanticBlockId: source.metadata?.semanticBlockId ?? null,
      };
    });
    const semanticRepresentation = members.some((source) => source.representation === LAGRANGE_CODE_V2)
      ? LAGRANGE_CODE_V2
      : LAGRANGE_CODE_V1;
    const compiled = compileResumableWasmV2ModuleEntries(entries, {
      optimizeLiveHandles: group.options?.optimizeLiveHandles !== false,
      optimizeClosures: group.options?.optimizeClosures === true,
      intraModuleDirectCalls: group.options?.intraModuleDirectCalls === true,
      intraModuleCallTargets: group.options?.intraModuleCallTargets ?? null,
    });
    return Object.freeze({
      bytes: compiled.bytes,
      contract: {
        abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V2,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: compiled.effectSites,
      },
      metadata: {
        continuations: compiled.continuations,
        semanticRepresentation,
        groupPolicyId: group.policyId,
        physicalLayout: 'shared-module',
        ...(compiled.intraModuleDirectCalls.length > 0
          ? {intraModuleDirectCalls: compiled.intraModuleDirectCalls}
          : {}),
      },
    });
  },
});

export {
  BASE_IMPORT_COUNT_V2,
  compileResumableWasmV2Module,
  compileResumableWasmV2ModuleEntries,
  compileResumableWasmV2ModuleForV2,
  lagrangeCodeV1GroupToResumableWasmModuleCompiler,
  lagrangeCodeV1ToResumableWasmModuleCompiler,
  lagrangeCodeV2ToResumableWasmModuleCompiler,
};

import {
  I32,
  functionExport,
  functionImport,
  functionType,
  s32,
  section,
  u32,
  vector,
} from './encoding.js';
import {LAGRANGE_CODE_V0, parseLagrangeCodeProgram} from '../code/lagrange-code-v0.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {
  WASM_ENTRY_V0,
  WASM_IMPORT_MODULE,
} from './abi.js';
import {WASM_RESUMABLE_VALUE_HANDLE_ABI_V1} from './resumable-abi.js';
import {analyzeLivePlanVariables} from './group-optimizations.js';

const BASE_IMPORT_COUNT = 4;
const WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V0 = 'wasm-nested-block-tree/v0';









function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be a non-empty string`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeModuleEntry(value, index) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`WASM module entry ${index} must be an object`);
  const entry = requiredText(value.entry, `WASM module entry ${index} name`);
  if (!Number.isInteger(value.memberIndex) || value.memberIndex < 0) {
    throw new TypeError(`WASM module entry ${index} memberIndex must be a non-negative integer`);
  }
  return Object.freeze({entry, memberIndex: value.memberIndex, program: value.program});
}

function collectLiteral(literals, value) {
  const normalized = canonicalizeValue(value);
  if (isReference(normalized)) throw new TypeError('WASM resumable backend does not embed reference literals; use arguments/captures instead');
  const key = JSON.stringify(normalized);
  const existing = literals.keys.get(key);
  if (existing !== undefined) return existing;
  const index = literals.values.length;
  literals.values.push(normalized);
  literals.keys.set(key, index);
  return index;
}

function normalizeCaptureDescriptor(capture, index) {
  exactKeys(capture, ['id', 'name', 'value'], `WASM closure capture ${index}`);
  return Object.freeze({
    id: requiredText(capture.id, `WASM closure capture ${index} id`),
    name: requiredText(capture.name, `WASM closure capture ${index} name`),
  });
}

function newTemp(state) {
  const id = `$t${state.nextTemp}`;
  state.nextTemp += 1;
  return id;
}

function collectSendEffect(state, expression) {
  if (!Array.isArray(expression.arguments)) throw new TypeError('WASM send arguments must be an array');
  const message = canonicalizeValue(expression.message);
  if (isReference(message)) throw new TypeError('WASM resumable backend does not place reference messages in module metadata');
  const siteIndex = state.sendSites.length;
  state.sendSites.push(Object.freeze({
    languageId: requiredText(expression.languageId, 'send languageId'),
    message,
    arity: expression.arguments.length,
  }));
  const effectIndex = state.effects.length;
  state.effects.push({
    kind: 'send',
    siteIndex,
    requestArity: 1 + expression.arguments.length,
    savedCount: 0,
    resumeEntry: null,
  });
  return effectIndex;
}

function collectClosureEffect(state, expression) {
  if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
  const captures = Object.freeze(expression.captures.map(normalizeCaptureDescriptor));
  const siteIndex = state.closureSites.length;
  state.closureSites.push(Object.freeze({
    blockId: requiredText(expression.blockId, 'WASM semantic block id'),
    captures,
  }));
  const effectIndex = state.effects.length;
  state.effects.push({
    kind: 'closure',
    siteIndex,
    requestArity: captures.length,
    savedCount: 0,
    resumeEntry: null,
  });
  return effectIndex;
}

function lowerSequence(expressions, state, context, index, values, done) {
  if (index >= expressions.length) return done(values);
  return lowerExpression(expressions[index], state, context, (value) =>
    lowerSequence(expressions, state, context, index + 1, [...values, value], done));
}

function lowerExpression(expression, state, context, continuation) {
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) {
    throw new TypeError('WASM compiler expression must be an object');
  }

  switch (expression.op) {
    case 'literal': {
      const id = newTemp(state);
      const value = canonicalizeValue(expression.value);
      if (isReference(value)) throw new TypeError('WASM resumable backend does not embed reference literals; use arguments/captures instead');
      return {kind: 'let', id, op: 'literal', value, next: continuation(id)};
    }
    case 'argument': {
      if (!Number.isInteger(expression.index) || expression.index < 0 || expression.index >= context.parameterCount) {
        throw new TypeError(`WASM argument index out of range: ${expression.index}`);
      }
      return continuation(`$argument:${expression.index}`);
    }
    case 'receiver':
      return continuation('$receiver');
    case 'binding': {
      if (!context.captureIds.has(expression.id)) {
        throw new TypeError(`WASM binding is not declared as a capture: ${expression.id}`);
      }
      return continuation(`$capture:${expression.id}`);
    }
    case 'integer-add':
    case 'equals':
      return lowerExpression(expression.left, state, context, (left) =>
        lowerExpression(expression.right, state, context, (right) => {
          const id = newTemp(state);
          return {kind: 'let', id, op: expression.op, left, right, next: continuation(id)};
        }));
    case 'if':
      return lowerExpression(expression.condition, state, context, (condition) => ({
        kind: 'if',
        condition,
        then: lowerExpression(expression.then, state, context, continuation),
        else: lowerExpression(expression.else, state, context, continuation),
      }));
    case 'send':
      return lowerExpression(expression.receiver, state, context, (receiver) =>
        lowerSequence(expression.arguments, state, context, 0, [], (args) => {
          const resultId = newTemp(state);
          return {
            kind: 'effect',
            effectIndex: collectSendEffect(state, expression),
            requestValues: [receiver, ...args],
            resultId,
            next: continuation(resultId),
          };
        }));
    case 'block':
      if (!Array.isArray(expression.captures)) throw new TypeError('WASM nested Block captures must be an array');
      expression.captures.forEach((capture, index) => normalizeCaptureDescriptor(capture, index));
      return lowerSequence(expression.captures.map(({value}) => value), state, context, 0, [], (captures) => {
        const resultId = newTemp(state);
        return {
          kind: 'effect',
          effectIndex: collectClosureEffect(state, expression),
          requestValues: captures,
          resultId,
          next: continuation(resultId),
        };
      });
    default:
      throw new TypeError(`WASM resumable backend does not support semantic op: ${expression.op}`);
  }
}

function directEffectReturn(plan) {
  return plan.next?.kind === 'return' && plan.next.value === plan.resultId;
}

function splitPlan(plan, available, state, rootEntry, segments) {
  switch (plan.kind) {
    case 'let':
      return {
        ...plan,
        next: splitPlan(plan.next, [...available, plan.id], state, rootEntry, segments),
      };
    case 'if':
      return {
        ...plan,
        then: splitPlan(plan.then, [...available], state, rootEntry, segments),
        else: splitPlan(plan.else, [...available], state, rootEntry, segments),
      };
    case 'return':
      return plan;
    case 'effect': {
      const effect = state.effects[plan.effectIndex];
      if (directEffectReturn(plan)) {
        effect.savedCount = 0;
        effect.resumeEntry = null;
        return {
          kind: 'effect-terminal',
          effectIndex: plan.effectIndex,
          requestValues: plan.requestValues,
          savedValues: [],
        };
      }

      const liveness = state.optimizeLiveHandles
        ? analyzeLivePlanVariables(plan.next, available)
        : {savedValues: [...available], eliminatedValues: []};
      const savedValues = [...liveness.savedValues];
      state.liveHandleSites.push(Object.freeze({
        effectIndex: plan.effectIndex,
        savedCount: savedValues.length,
        eliminatedCount: liveness.eliminatedValues.length,
        savedVariables: Object.freeze([...savedValues]),
        eliminatedVariables: Object.freeze([...liveness.eliminatedValues]),
      }));
      const resumeEntry = `${rootEntry}$resume_${plan.effectIndex}`;
      if (state.exportNames.has(resumeEntry)) throw new TypeError(`duplicate WASM resume export entry: ${resumeEntry}`);
      state.exportNames.add(resumeEntry);
      effect.savedCount = savedValues.length;
      effect.resumeEntry = resumeEntry;

      const continuationSegment = {
        entry: resumeEntry,
        parameterVars: [...savedValues, plan.resultId],
        effectIndex: plan.effectIndex,
        root: false,
        plan: null,
      };
      segments.push(continuationSegment);
      continuationSegment.plan = splitPlan(
        plan.next,
        [...savedValues, plan.resultId],
        state,
        rootEntry,
        segments,
      );

      return {
        kind: 'effect-terminal',
        effectIndex: plan.effectIndex,
        requestValues: plan.requestValues,
        savedValues,
      };
    }
    default:
      throw new TypeError(`unknown resumable plan node: ${plan.kind}`);
  }
}

function compilePlan(plan, context) {
  const localGet = (id) => {
    const index = context.env.get(id);
    if (index === undefined) throw new TypeError(`WASM resumable variable is unavailable: ${id}`);
    return [0x20, ...u32(index)];
  };

  const localFor = (id) => {
    const existing = context.env.get(id);
    if (existing !== undefined) return existing;
    const index = context.parameterCount + context.localCount;
    context.localCount += 1;
    context.env.set(id, index);
    return index;
  };

  switch (plan.kind) {
    case 'let': {
      const localIndex = localFor(plan.id);
      let valueCode;
      if (plan.op === 'literal') {
        const literalIndex = collectLiteral(context.literals, plan.value);
        valueCode = [0x41, ...s32(literalIndex), 0x10, ...u32(0)];
      } else if (plan.op === 'integer-add') {
        valueCode = [...localGet(plan.left), ...localGet(plan.right), 0x10, ...u32(1)];
      } else if (plan.op === 'equals') {
        valueCode = [...localGet(plan.left), ...localGet(plan.right), 0x10, ...u32(2)];
      } else {
        throw new TypeError(`unknown resumable pure op: ${plan.op}`);
      }
      return [...valueCode, 0x21, ...u32(localIndex), ...compilePlan(plan.next, context)];
    }
    case 'if':
      return [
        ...localGet(plan.condition),
        0x10, ...u32(3),
        0x04, 0x40,
        ...compilePlan(plan.then, context),
        0x05,
        ...compilePlan(plan.else, context),
        0x0b,
        0x00,
      ];
    case 'effect-terminal':
      return [
        ...plan.requestValues.flatMap(localGet),
        ...plan.savedValues.flatMap(localGet),
        0x10, ...u32(BASE_IMPORT_COUNT + plan.effectIndex),
        0x0f,
      ];
    case 'return':
      return [...localGet(plan.value), 0x0f];
    default:
      throw new TypeError(`unknown resumable plan node: ${plan.kind}`);
  }
}

function compileSegment(segment, literals) {
  const env = new Map(segment.parameterVars.map((name, index) => [name, index]));
  const context = {
    env,
    parameterCount: segment.parameterVars.length,
    localCount: 0,
    literals,
  };
  const instructions = compilePlan(segment.plan, context);
  const localDeclarations = context.localCount === 0
    ? [0x00]
    : [0x01, ...u32(context.localCount), I32];
  const body = [...localDeclarations, ...instructions, 0x00, 0x0b];
  return Object.freeze({
    entry: segment.entry,
    parameterCount: segment.parameterVars.length,
    effectIndex: segment.effectIndex ?? null,
    root: segment.root,
    body: [...u32(body.length), ...body],
  });
}

function prepareEntries(entries) {
  if (!Array.isArray(entries) || entries.length === 0) throw new TypeError('WASM module entries must be a non-empty array');
  const normalizedEntries = entries.map(normalizeModuleEntry);
  const entryNames = new Set();
  const memberIndices = new Set();
  for (const entry of normalizedEntries) {
    if (entryNames.has(entry.entry)) throw new TypeError(`duplicate WASM export entry: ${entry.entry}`);
    if (memberIndices.has(entry.memberIndex)) throw new TypeError(`duplicate WASM member index: ${entry.memberIndex}`);
    entryNames.add(entry.entry);
    memberIndices.add(entry.memberIndex);
  }
  return {normalizedEntries, entryNames};
}

function compileResumableWasmModuleEntries(entries, {optimizeLiveHandles = true} = {}) {
  const {normalizedEntries, entryNames} = prepareEntries(entries);
  const state = {
    sendSites: [],
    closureSites: [],
    effects: [],
    nextTemp: 0,
    exportNames: new Set(entryNames),
    optimizeLiveHandles: Boolean(optimizeLiveHandles),
    liveHandleSites: [],
  };
  const segments = [];
  const functionDescriptors = [];

  for (const entry of normalizedEntries) {
    const program = entry.program;
    if (!program || !Array.isArray(program.parameters) || !Array.isArray(program.captures)) {
      throw new TypeError(`WASM module entry ${entry.entry} program must contain parameters and captures arrays`);
    }
    const captureIds = program.captures.map(({id}, index) => requiredText(id, `WASM capture ${index} id`));
    if (new Set(captureIds).size !== captureIds.length) throw new TypeError(`WASM module entry ${entry.entry} has duplicate capture ids`);
    const context = {
      parameterCount: program.parameters.length,
      captureIds: new Set(captureIds),
    };

    const sendStart = state.sendSites.length;
    const closureStart = state.closureSites.length;
    const plan = lowerExpression(program.body, state, context, (value) => ({kind: 'return', value}));
    const parameterVars = [
      '$receiver',
      ...Array.from({length: program.parameters.length}, (_, index) => `$argument:${index}`),
      ...captureIds.map((id) => `$capture:${id}`),
    ];
    const rootSegment = {
      entry: entry.entry,
      parameterVars,
      effectIndex: null,
      root: true,
      plan: null,
    };
    segments.push(rootSegment);
    rootSegment.plan = splitPlan(plan, [...parameterVars], state, entry.entry, segments);

    functionDescriptors.push(Object.freeze({
      entry: entry.entry,
      memberIndex: entry.memberIndex,
      parameters: program.parameters.length,
      captures: Object.freeze(captureIds),
      sendSiteIndices: Object.freeze(Array.from(
        {length: state.sendSites.length - sendStart},
        (_, offset) => sendStart + offset,
      )),
      closureSiteIndices: Object.freeze(Array.from(
        {length: state.closureSites.length - closureStart},
        (_, offset) => closureStart + offset,
      )),
    }));
  }

  const literals = {values: [], keys: new Map()};
  const compiledSegments = segments.map((segment) => compileSegment(segment, literals));
  const effectSites = Object.freeze(state.effects.map((effect) => Object.freeze({
    kind: effect.kind,
    siteIndex: effect.siteIndex,
    requestArity: effect.requestArity,
    savedCount: effect.savedCount,
    resumeEntry: effect.resumeEntry,
  })));
  const continuations = Object.freeze(compiledSegments
    .filter(({root}) => !root)
    .map(({entry, effectIndex, parameterCount}) => Object.freeze({
      entry,
      effectIndex,
      parameters: parameterCount,
    })));

  const effectTypes = effectSites.map(({requestArity, savedCount}) =>
    functionType(Array.from({length: requestArity + savedCount}, () => I32), [I32]));
  const segmentTypes = compiledSegments.map(({parameterCount}) =>
    functionType(Array.from({length: parameterCount}, () => I32), [I32]));
  const types = vector([
    functionType([I32], [I32]),
    functionType([I32, I32], [I32]),
    ...effectTypes,
    ...segmentTypes,
  ]);

  const effectImports = effectSites.map((effect, effectIndex) => {
    const name = effect.kind === 'send'
      ? `send_site_${effect.siteIndex}`
      : `make_block_site_${effect.siteIndex}`;
    return functionImport(WASM_IMPORT_MODULE, name, 2 + effectIndex);
  });
  const imports = vector([
    functionImport(WASM_IMPORT_MODULE, 'literal', 0),
    functionImport(WASM_IMPORT_MODULE, 'integer_add', 1),
    functionImport(WASM_IMPORT_MODULE, 'equals', 1),
    functionImport(WASM_IMPORT_MODULE, 'is_true', 0),
    ...effectImports,
  ]);

  const firstSegmentTypeIndex = 2 + effectSites.length;
  const functions = vector(compiledSegments.map((_, index) => [...u32(firstSegmentTypeIndex + index)]));
  const firstFunctionIndex = BASE_IMPORT_COUNT + effectSites.length;
  const exports = vector(compiledSegments.map(({entry}, index) => functionExport(entry, firstFunctionIndex + index)));
  const code = vector(compiledSegments.map(({body}) => body));

  return Object.freeze({
    bytes: new Uint8Array([
      0x00, 0x61, 0x73, 0x6d,
      0x01, 0x00, 0x00, 0x00,
      ...section(1, types),
      ...section(2, imports),
      ...section(3, functions),
      ...section(7, exports),
      ...section(10, code),
    ]),
    literals: Object.freeze(literals.values),
    sendSites: Object.freeze(state.sendSites),
    closureSites: Object.freeze(state.closureSites),
    effectSites,
    continuations,
    functions: Object.freeze(functionDescriptors),
    liveHandleOptimization: Object.freeze({
      enabled: state.optimizeLiveHandles,
      totalSavedHandles: state.liveHandleSites.reduce((sum, s) => sum + s.savedCount, 0),
      eliminatedHandleCount: state.liveHandleSites.reduce((sum, s) => sum + s.eliminatedCount, 0),
      sites: Object.freeze([...state.liveHandleSites]),
    }),
  });
}

function compileResumableWasmModule(program, options = {}) {
  const compiled = compileResumableWasmModuleEntries([{entry: WASM_ENTRY_V0, memberIndex: 0, program}], options);
  const descriptor = compiled.functions[0];
  return Object.freeze({
    ...compiled,
    parameterCount: descriptor.parameters,
    captureIds: descriptor.captures,
  });
}

const lagrangeCodeV0ToResumableWasmModuleCompiler = Object.freeze({
  async compile({source}) {
    if (source.representation !== LAGRANGE_CODE_V0) throw new TypeError(`source must be ${LAGRANGE_CODE_V0}`);
    const program = parseLagrangeCodeProgram(source);
    const compiled = compileResumableWasmModule(program);
    return Object.freeze({
      languageId: source.languageId,
      bytes: compiled.bytes,
      contract: {
        abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V1,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: compiled.effectSites,
      },
      metadata: {
        continuations: compiled.continuations,
        semanticRepresentation: LAGRANGE_CODE_V0,
      },
    });
  },
});

const lagrangeCodeGroupToResumableWasmModuleCompiler = Object.freeze({
  async compile({group, members}) {
    if (group.policyId !== WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V0) {
      throw new TypeError(`unsupported WASM compilation group policy: ${group.policyId}`);
    }
    if (group.options?.physicalLayout !== 'shared-module') {
      throw new TypeError('WASM shared-module compiler requires physicalLayout=shared-module');
    }
    const entries = members.map((source, memberIndex) => {
      if (source.representation !== LAGRANGE_CODE_V0) {
        throw new TypeError(`WASM group member ${memberIndex} must be ${LAGRANGE_CODE_V0}`);
      }
      return {
        entry: `run_${memberIndex}`,
        memberIndex,
        program: parseLagrangeCodeProgram(source),
      };
    });
    const compiled = compileResumableWasmModuleEntries(entries);
    return Object.freeze({
      bytes: compiled.bytes,
      contract: {
        abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V1,
        literals: compiled.literals,
        functions: compiled.functions,
        sendSites: compiled.sendSites,
        closureSites: compiled.closureSites,
        effectSites: compiled.effectSites,
      },
      metadata: {
        continuations: compiled.continuations,
        semanticRepresentation: LAGRANGE_CODE_V0,
        groupPolicyId: group.policyId,
        physicalLayout: 'shared-module',
      },
    });
  },
});

function isWasmTailEffectRestrictionError(error) {
  if (!(error instanceof TypeError)) return false;
  return error.message.includes('message sends only in tail position')
    || error.message.includes('nested Block creation only in tail position');
}

export {
  compileResumableWasmModule,
  compileResumableWasmModuleEntries,
  isWasmTailEffectRestrictionError,
  lagrangeCodeGroupToResumableWasmModuleCompiler,
  lagrangeCodeV0ToResumableWasmModuleCompiler,
};

import {assertWasmFunctionArtifactAnyVersion, functionModuleRef, resolveFunctionContract} from './function-contract.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {
  WASM_IMPORT_MODULE,
  ValueHandleArena,
} from './abi.js';
import {
  WASM_INSTANCE_REUSE_STATELESS_V0,
  WasmInstancePool,
} from './instance-pool.js';
import {readCellThrough, writeCellThrough} from './cell-access.js';
import {WasmModuleCache} from './module-cache.js';
import {readModuleDescriptor, readModuleImplementationBytes} from './module-contract.js';
import {WASM_RESUMABLE_VALUE_HANDLE_ABI_V2} from './resumable-abi.js';

const MAX_WASM_RESUMPTIONS = 256;

// The lagrange-value-handle-resumable/v2 executor: the resumable lane for lagrange-code/v1.
//
// Every normalizer here branches on the v2 ABI; the v1 normalizers never learn the v1-semantic
// shape. The one structural difference from v2's predecessor is that a cell is never continuation
// state — cell_get/cell_set run synchronously at their evaluation position, so a resume entry
// carries only Value handles that were already computed.
function requireNonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeCaptures(value, label = 'WASM function metadata.captures') {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  return Object.freeze(value.map((id, index) => {
    if (typeof id !== 'string' || id.length === 0) throw new TypeError(`${label} ${index} must be a non-empty binding id`);
    return id;
  }));
}

function normalizeIndexList(value, limit, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((entry, index) => {
    const normalized = requireNonNegativeInteger(entry, `${label} ${index}`);
    if (normalized >= limit) throw new TypeError(`${label} ${index} is out of range`);
    if (seen.has(normalized)) throw new TypeError(`${label} contains duplicate index ${normalized}`);
    seen.add(normalized);
    return normalized;
  }));
}

function normalizeLiterals(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract literals must be an array');
  return Object.freeze(value.map((entry) => canonicalizeValue(entry)));
}

function normalizeSendSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract sendSites must be an array');
  return Object.freeze(value.map((site, index) => {
    if (site && typeof site === 'object' && !Array.isArray(site) && site.kind === 'apply') {
      exactKeys(site, ['kind', 'arity'], `WASM apply site ${index}`);
      return Object.freeze({
        kind: 'apply',
        arity: requireNonNegativeInteger(site.arity, `WASM apply site ${index} arity`),
      });
    }
    exactKeys(site, ['languageId', 'message', 'arity'], `WASM send site ${index}`);
    if (typeof site.languageId !== 'string' || site.languageId.length === 0) {
      throw new TypeError(`WASM send site ${index} languageId must be a non-empty string`);
    }
    const message = canonicalizeValue(site.message);
    if (isReference(message)) throw new TypeError(`WASM send site ${index} message must not hide a graph reference`);
    return Object.freeze({
      languageId: site.languageId,
      message,
      arity: requireNonNegativeInteger(site.arity, `WASM send site ${index} arity`),
    });
  }));
}

function normalizeClosureSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract closureSites must be an array');
  return Object.freeze(value.map((site, siteIndex) => {
    exactKeys(site, ['blockId', 'captures'], `WASM closure site ${siteIndex}`);
    if (typeof site.blockId !== 'string' || site.blockId.length === 0) {
      throw new TypeError(`WASM closure site ${siteIndex} blockId must be non-empty text`);
    }
    if (!Array.isArray(site.captures)) throw new TypeError(`WASM closure site ${siteIndex} captures must be an array`);
    // v2 closure sites carry a per-capture mode. A v1-shaped site is a mismatch here, not
    // something to interpret generously.
    const captures = Object.freeze(site.captures.map((capture, captureIndex) => {
      const label = `WASM closure site ${siteIndex} capture ${captureIndex}`;
      exactKeys(capture, ['id', 'mode', 'name'], label);
      const mode = requiredCellText(capture.mode, `${label} mode`);
      if (mode !== 'snapshot' && mode !== 'cell') throw new TypeError(`${label} mode must be snapshot or cell`);
      return Object.freeze({
        id: requiredCellText(capture.id, `${label} id`),
        name: requiredCellText(capture.name, `${label} name`),
        mode,
      });
    }));
    return Object.freeze({blockId: site.blockId, captures});
  }));
}

function normalizeEffectSites(value, sendSites, closureSites) {
  if (!Array.isArray(value)) throw new TypeError('resumable WASM module contract effectSites must be an array');
  const seen = new Set();
  return Object.freeze(value.map((effect, effectIndex) => {
    exactKeys(
      effect,
      ['kind', 'siteIndex', 'requestArity', 'savedCount', 'resumeEntry'],
      `resumable WASM effect site ${effectIndex}`,
    );
    if (!['send', 'closure'].includes(effect.kind)) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} kind must be send or closure`);
    }
    const siteIndex = requireNonNegativeInteger(effect.siteIndex, `resumable WASM effect site ${effectIndex} siteIndex`);
    const key = `${effect.kind}:${siteIndex}`;
    if (seen.has(key)) throw new TypeError(`duplicate resumable WASM effect site: ${key}`);
    seen.add(key);

    const site = effect.kind === 'send' ? sendSites[siteIndex] : closureSites[siteIndex];
    if (!site) throw new TypeError(`resumable WASM effect site ${effectIndex} references a missing ${effect.kind} site`);
    // Snapshot captures only. A cell capture occupies no handle position, so counting every
    // semantic capture here would demand a handle the compiler never emits — and a closure with
    // one cell capture and no snapshots would fail validation with an off-by-one.
    const expectedRequestArity = effect.kind === 'send'
      ? 1 + site.arity
      : site.captures.filter(({mode}) => mode === 'snapshot').length;
    const requestArity = requireNonNegativeInteger(effect.requestArity, `resumable WASM effect site ${effectIndex} requestArity`);
    if (requestArity !== expectedRequestArity) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} request arity does not match its ${effect.kind} site`);
    }
    const savedCount = requireNonNegativeInteger(effect.savedCount, `resumable WASM effect site ${effectIndex} savedCount`);
    const resumeEntry = effect.resumeEntry;
    if (resumeEntry !== null && (typeof resumeEntry !== 'string' || resumeEntry.length === 0)) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} resumeEntry must be non-empty text or null`);
    }
    if (resumeEntry === null && savedCount !== 0) {
      throw new TypeError(`tail resumable WASM effect site ${effectIndex} must not save continuation handles`);
    }
    return Object.freeze({
      kind: effect.kind,
      siteIndex,
      requestArity,
      savedCount,
      resumeEntry,
    });
  }));
}

function normalizeModuleFunctions(value, sendSites, closureSites) {
  if (!Array.isArray(value) || value.length === 0) {
    throw new TypeError('resumable WASM module contract functions must be a non-empty array');
  }
  const entries = new Set();
  const memberIndices = new Set();
  return Object.freeze(value.map((descriptor, index) => {
    exactKeys(
      descriptor,
      ['entry', 'memberIndex', 'parameters', 'captures', 'cellBindings', 'sendSiteIndices', 'closureSiteIndices'],
      `WASM module function ${index}`,
    );
    if (typeof descriptor.entry !== 'string' || descriptor.entry.length === 0) throw new TypeError(`WASM module function ${index} entry must be non-empty text`);
    if (entries.has(descriptor.entry)) throw new TypeError(`duplicate WASM module function entry: ${descriptor.entry}`);
    entries.add(descriptor.entry);
    const memberIndex = requireNonNegativeInteger(descriptor.memberIndex, `WASM module function ${index} memberIndex`);
    if (memberIndices.has(memberIndex)) throw new TypeError(`duplicate WASM module function memberIndex: ${memberIndex}`);
    memberIndices.add(memberIndex);
    return Object.freeze({
      entry: descriptor.entry,
      memberIndex,
      parameters: requireNonNegativeInteger(descriptor.parameters, `WASM module function ${index} parameters`),
      captures: normalizeCaptures(descriptor.captures, `WASM module function ${index} captures`),
      cellBindings: normalizeCellBindings(descriptor.cellBindings, `WASM module function ${index} cellBindings`),
      sendSiteIndices: normalizeIndexList(descriptor.sendSiteIndices, sendSites.length, `WASM module function ${index} sendSiteIndices`),
      closureSiteIndices: normalizeIndexList(descriptor.closureSiteIndices, closureSites.length, `WASM module function ${index} closureSiteIndices`),
    });
  }));
}

function normalizeCellBindings(value, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((binding, index) => {
    exactKeys(binding, ['id', 'name', 'source'], `${label} ${index}`);
    const id = requiredCellText(binding.id, `${label} ${index} id`);
    if (seen.has(id)) throw new TypeError(`${label} declares duplicate cell binding ${id}`);
    seen.add(id);
    const source = requiredCellText(binding.source, `${label} ${index} source`);
    if (source !== 'temporary' && source !== 'capture') {
      throw new TypeError(`${label} ${index} source must be temporary or capture`);
    }
    return Object.freeze({id, name: requiredCellText(binding.name, `${label} ${index} name`), source});
  }));
}

function requiredCellText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

// Full equality, not ids only: two durable artifacts must not be able to disagree about whether a
// cell is a temporary or a capture and still validate.




function recordPending(pending, effect) {
  if (pending.effect !== null) throw new TypeError('WASM activation attempted more than one pending host effect');
  pending.effect = Object.freeze(effect);
  return 0;
}

function effectMaps(effectSites) {
  const sends = new Map();
  const closures = new Map();
  effectSites.forEach((effect, effectIndex) => {
    const target = effect.kind === 'send' ? sends : closures;
    target.set(effect.siteIndex, Object.freeze({...effect, effectIndex}));
  });
  return {sends, closures};
}

function createRebindableHostEnvironment(literals, sendSites, closureSites, effectSites) {
  const holder = {current: null};
  const maps = effectMaps(effectSites);
  const current = () => {
    if (!holder.current) throw new TypeError('WASM instance host environment is not bound to an activation');
    return holder.current;
  };
  const lagrange = {
    literal(index) {
      const state = current();
      if (!Number.isInteger(index) || index < 0 || index >= literals.length) throw new TypeError(`WASM literal index out of range: ${index}`);
      return state.arena.put(literals[index]);
    },
    integer_add(left, right) {
      return current().arena.integerAdd(left, right);
    },
    equals(left, right) {
      return current().arena.equals(left, right);
    },
    is_true(handle) {
      return current().arena.isTrue(handle);
    },
    // Synchronous, resolved through this activation's descriptor, and rebound on every segment
    // entry — including each resumption — so a cell read after resumption sees the live cell.
    cell_get(slot) {
      const state = current();
      return state.arena.put(readCellThrough(state.readCell, state.cellBinding(slot)));
    },
    cell_set(slot, handle) {
      const state = current();
      const binding = state.cellBinding(slot);
      const value = state.arena.get(handle, `WASM cell_set value handle for slot ${slot}`);
      return state.arena.put(writeCellThrough(state.writeCell, binding, value));
    },
  };

  sendSites.forEach((site, siteIndex) => {
    const effect = maps.sends.get(siteIndex);
    if (!effect) throw new TypeError(`resumable WASM send site ${siteIndex} has no effect descriptor`);
    lagrange[`send_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeSendSites.has(siteIndex)) throw new TypeError(`inactive WASM send site invoked: ${siteIndex}`);
      const expected = effect.requestArity + effect.savedCount;
      if (handles.length !== expected) {
        throw new TypeError(`resumable WASM send site ${siteIndex} expected ${expected} handles, received ${handles.length}`);
      }
      const requestHandles = handles.slice(0, effect.requestArity);
      const savedHandles = Object.freeze(handles.slice(effect.requestArity));
      if (site.kind === 'apply') {
        return recordPending(state.pending, {
          kind: 'apply',
          siteIndex,
          request: Object.freeze({
            callee: state.arena.get(requestHandles[0], `WASM apply site ${siteIndex} callee handle`),
            arguments: Object.freeze(requestHandles.slice(1).map((handle, argumentIndex) =>
              state.arena.get(handle, `WASM apply site ${siteIndex} argument ${argumentIndex} handle`))),
          }),
          resume: effect.resumeEntry === null
            ? null
            : Object.freeze({entry: effect.resumeEntry, handles: savedHandles}),
        });
      }
      return recordPending(state.pending, {
        kind: 'send',
        siteIndex,
        request: Object.freeze({
          languageId: site.languageId,
          receiver: state.arena.get(requestHandles[0], `WASM send site ${siteIndex} receiver handle`),
          message: site.message,
          arguments: Object.freeze(requestHandles.slice(1).map((handle, argumentIndex) =>
            state.arena.get(handle, `WASM send site ${siteIndex} argument ${argumentIndex} handle`))),
        }),
        resume: effect.resumeEntry === null
          ? null
          : Object.freeze({entry: effect.resumeEntry, handles: savedHandles}),
      });
    };
  });

  closureSites.forEach((site, siteIndex) => {
    const effect = maps.closures.get(siteIndex);
    if (!effect) throw new TypeError(`resumable WASM closure site ${siteIndex} has no effect descriptor`);
    lagrange[`make_block_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeClosureSites.has(siteIndex)) throw new TypeError(`inactive WASM closure site invoked: ${siteIndex}`);
      const expected = effect.requestArity + effect.savedCount;
      if (handles.length !== expected) {
        throw new TypeError(`resumable WASM closure site ${siteIndex} expected ${expected} handles, received ${handles.length}`);
      }
      const requestHandles = handles.slice(0, effect.requestArity);
      const savedHandles = Object.freeze(handles.slice(effect.requestArity));
      const prototype = state.closurePrototypes.get(siteIndex);
      if (!prototype) throw new TypeError(`WASM closure prototype missing at execution: ${site.blockId}`);
      return recordPending(state.pending, {
        kind: 'closure',
        siteIndex,
        request: Object.freeze({
          prototype,
          // Request handles cover snapshot captures only; saved continuation handles follow them
          // and are counted separately. A cell capture occupies no handle position at all.
          captures: Object.freeze((() => {
            let handleIndex = 0;
            return site.captures.map((capture) => {
              if (capture.mode === 'cell') {
                return Object.freeze({id: capture.id, name: capture.name, mode: 'cell'});
              }
              const handle = requestHandles[handleIndex];
              handleIndex += 1;
              return Object.freeze({
                id: capture.id,
                name: capture.name,
                mode: 'snapshot',
                value: state.arena.get(handle, `WASM closure site ${siteIndex} capture ${capture.id} handle`),
              });
            });
          })()),
        }),
        resume: effect.resumeEntry === null
          ? null
          : Object.freeze({entry: effect.resumeEntry, handles: savedHandles}),
      });
    };
  });

  return Object.freeze({
    imports: {[WASM_IMPORT_MODULE]: lagrange},
    bind({arena, descriptor, closurePrototypes, pending, readCell, writeCell}) {
      if (holder.current) throw new TypeError('WASM instance host environment is already bound');
      const cellBindings = descriptor.cellBindings;
      holder.current = {
        arena,
        closurePrototypes,
        pending,
        readCell,
        writeCell,
        cellBinding(slot) {
          if (!Number.isInteger(slot) || slot < 0 || slot >= cellBindings.length) {
            throw new TypeError(`WASM cell slot out of range for ${descriptor.entry}: ${slot}`);
          }
          return cellBindings[slot];
        },
        activeSendSites: new Set(descriptor.sendSiteIndices),
        activeClosureSites: new Set(descriptor.closureSiteIndices),
      };
    },
    unbind() {
      if (!holder.current) throw new TypeError('WASM instance host environment is not bound');
      holder.current = null;
    },
  });
}

function instanceReuseMode(moduleArtifact) {
  const mode = moduleArtifact.metadata?.instanceReuse;
  if (mode === undefined) return null;
  if (mode !== WASM_INSTANCE_REUSE_STATELESS_V0) throw new TypeError(`unsupported WASM instance reuse contract: ${mode}`);
  return mode;
}

async function createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites) {
  const host = createRebindableHostEnvironment(literals, sendSites, closureSites, effectSites);
  const instance = await WebAssembly.instantiate(compiledModule, host.imports);
  return Object.freeze({instance, host});
}

async function acquireInstance({
  moduleArtifact,
  compiledModule,
  instancePool,
  literals,
  sendSites,
  closureSites,
  effectSites,
}) {
  if (instanceReuseMode(moduleArtifact) === WASM_INSTANCE_REUSE_STATELESS_V0) {
    return await instancePool.acquire(
      moduleArtifact,
      async () => await createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites),
    );
  }
  const slot = await createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites);
  let released = false;
  return Object.freeze({
    slot,
    release() {
      if (released) throw new TypeError('WASM one-shot instance lease already released');
      released = true;
    },
  });
}

async function performHostEffect(effect, context) {
  if (effect.kind === 'send') {
    if (typeof context.sendMessage !== 'function') throw new TypeError('WASM message send requires a message runtime');
    return canonicalizeValue(await context.sendMessage(effect.request));
  }
  if (effect.kind === 'apply') {
    if (typeof context.invokeBlock !== 'function') throw new TypeError('WASM callable application requires a Block invocation runtime');
    return canonicalizeValue(await context.invokeBlock(effect.request.callee, effect.request.arguments));
  }
  if (effect.kind === 'closure') {
    if (typeof context.createClosure !== 'function') throw new TypeError('WASM closure creation requires a closure runtime');
    return canonicalizeValue(await context.createClosure(effect.request));
  }
  throw new TypeError(`unknown WASM host effect kind: ${effect.kind}`);
}

function createResumableWasmFunctionV2Executor({
  moduleCache = new WasmModuleCache(),
  instancePool = new WasmInstancePool(),
} = {}) {
  if (!moduleCache || typeof moduleCache.get !== 'function' || typeof moduleCache.stats !== 'function') {
    throw new TypeError('moduleCache must be a WasmModuleCache-compatible object');
  }
  if (!instancePool || typeof instancePool.acquire !== 'function' || typeof instancePool.stats !== 'function') {
    throw new TypeError('instancePool must be a WasmInstancePool-compatible object');
  }

  return Object.freeze({
    moduleCache,
    instancePool,
    async execute({activation, code}, context, resolved = null) {
      if (!resolved) assertWasmFunctionArtifactAnyVersion(code);
      for (const operation of ['readCell', 'writeCell', 'declareTemporaries']) {
        if (typeof context[operation] !== 'function') {
          throw new TypeError(`the lagrange-value-handle-resumable/v2 ABI requires the ${operation} execution operation`);
        }
      }
      const moduleRef = functionModuleRef(code);
      const moduleArtifact = resolved?.moduleArtifact ?? await context.images.getCodeArtifact(moduleRef.imageId, moduleRef.objectId);
      if (!moduleArtifact) throw new TypeError(`WASM module not found: ${moduleRef.imageId}/${moduleRef.objectId}`);
      const contract = readModuleDescriptor(moduleArtifact);
      const resolveImplementation = (ref) => context.images.getCodeArtifact(ref.imageId, ref.objectId);
      if (contract.abi !== WASM_RESUMABLE_VALUE_HANDLE_ABI_V2) {
        throw new TypeError(`WASM module ABI does not match ${WASM_RESUMABLE_VALUE_HANDLE_ABI_V2}`);
      }
      const literals = normalizeLiterals(contract.literals);
      const sendSites = normalizeSendSites(contract.sendSites);
      const closureSites = normalizeClosureSites(contract.closureSites);
      const effectSites = normalizeEffectSites(contract.effectSites, sendSites, closureSites);
      const fn = resolveFunctionContract(
        code,
        Object.freeze({...contract, functions: normalizeModuleFunctions(contract.functions, sendSites, closureSites), closureSites}),
        resolved?.selection ? {selection: resolved.selection} : {},
      );
      const {descriptor, closurePrototypes} = fn;
      const parameterCount = descriptor.parameters;
      const captureIds = descriptor.captures;
      if (activation.arguments.length !== parameterCount) {
        throw new TypeError(`WASM activation expected ${parameterCount} arguments, received ${activation.arguments.length}`);
      }
      const compiledModule = await moduleCache.get(moduleArtifact, () => readModuleImplementationBytes(moduleArtifact, {resolveImplementation}));

      // Only temporaries: a cell capture already exists in the frame that declared it.
      context.declareTemporaries(descriptor.cellBindings.filter(({source}) => source === 'temporary'));

      const arena = new ValueHandleArena({receiverAbsent: activation.receiver === null});
      const receiverHandle = activation.receiver === null ? 0 : arena.put(activation.receiver);
      const argumentHandles = activation.arguments.map((value) => arena.put(value));
      const captureHandles = [];
      for (const bindingId of captureIds) captureHandles.push(arena.put(await context.lookupBinding(bindingId)));
      const pending = {effect: null};

      const lease = await acquireInstance({
        moduleArtifact,
        compiledModule,
        instancePool,
        literals,
        sendSites,
        closureSites,
        effectSites,
      });
      let bound = false;
      let released = false;
      let result = null;
      let tailEffect = null;
      let currentEntry = fn.entry;
      let currentHandles = [receiverHandle, ...argumentHandles, ...captureHandles];
      let resumptions = 0;

      context.recordWasmState?.({
        wasmState: 'running',
        suspensionCount: 0,
        resumedCount: 0,
        lastSuspension: null,
      });

      try {
        while (true) {
          context.checkCancelled?.();
          pending.effect = null;
          lease.slot.host.bind({
            arena,
            descriptor,
            closurePrototypes,
            pending,
            readCell: context.readCell,
            writeCell: context.writeCell,
          });
          bound = true;
          const entry = lease.slot.instance.exports[currentEntry];
          if (typeof entry !== 'function') throw new TypeError(`WASM function/resume entry not found: ${currentEntry}`);
          const resultHandle = entry(...currentHandles);

          const effect = pending.effect;
          lease.slot.host.unbind();
          bound = false;

          if (effect === null) {
            result = arena.get(resultHandle, 'WASM result handle');
            break;
          }
          if (resultHandle !== 0) throw new TypeError('WASM host effect suspension must return reserved handle 0');

          if (effect.resume === null) {
            tailEffect = effect;
            break;
          }
          resumptions += 1;
          if (resumptions > MAX_WASM_RESUMPTIONS) throw new TypeError('WASM resumable effect limit exceeded');

          const suspensionMeta = Object.freeze({
            abi: contract.abi,
            entry: fn.entry,
            currentEntry,
            effectKind: effect.kind,
            siteIndex: effect.siteIndex ?? null,
            resumeEntry: effect.resume.entry,
            savedHandleCount: effect.resume.handles.length,
            step: resumptions,
          });
          context.recordWasmState?.({
            wasmState: 'suspended',
            suspensionCount: resumptions,
            resumedCount: resumptions - 1,
            lastSuspension: suspensionMeta,
            event: 'suspend',
          });

          const resumedValue = await performHostEffect(effect, context);
          context.checkCancelled?.();
          context.recordWasmState?.({
            wasmState: 'running',
            suspensionCount: resumptions,
            resumedCount: resumptions,
            lastSuspension: suspensionMeta,
            event: 'resume',
          });
          const resultValueHandle = arena.put(resumedValue);
          currentEntry = effect.resume.entry;
          currentHandles = [...effect.resume.handles, resultValueHandle];
        }

        context.recordWasmState?.({wasmState: 'completed'});
        lease.release();
        released = true;
      } catch (error) {
        try {
          context.recordWasmState?.({wasmState: 'retired', event: 'retire'});
        } catch {}
        if (bound) {
          try { lease.slot.host.unbind(); } catch {}
          bound = false;
        }
        if (!released) {
          try { lease.release({retire: true}); } catch {}
          released = true;
        }
        throw error;
      }

      if (tailEffect !== null) return await performHostEffect(tailEffect, context);
      return canonicalizeValue(result);
    },
  });
}

export {
  MAX_WASM_RESUMPTIONS,
  createResumableWasmFunctionV2Executor,
};

import {assertWasmFunctionArtifactAnyVersion, functionModuleRef, resolveFunctionContract} from './function-contract.js';
import {canonicalizeValue, isReference} from '../value/index.js';
import {
  WASM_IMPORT_MODULE,
  ValueHandleArena,
} from './abi.js';
import {
  WASM_INSTANCE_REUSE_STATELESS_V0,
  WasmInstancePool,
} from './instance-pool.js';
import {WasmModuleCache} from './module-cache.js';
import {readModuleDescriptor, readModuleImplementationBytes} from './module-contract.js';
import {WASM_RESUMABLE_VALUE_HANDLE_ABI_V1} from './resumable-abi.js';

const MAX_WASM_RESUMPTIONS = 256;

function requireNonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) throw new TypeError(`${label} must be a non-negative integer`);
  return value;
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    throw new TypeError(`${label} must contain exactly ${wanted.join(', ')}`);
  }
  return value;
}

function normalizeCaptures(value, label = 'WASM function metadata.captures') {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  return Object.freeze(value.map((id, index) => {
    if (typeof id !== 'string' || id.length === 0) throw new TypeError(`${label} ${index} must be a non-empty binding id`);
    return id;
  }));
}

function normalizeIndexList(value, limit, label) {
  if (!Array.isArray(value)) throw new TypeError(`${label} must be an array`);
  const seen = new Set();
  return Object.freeze(value.map((entry, index) => {
    const normalized = requireNonNegativeInteger(entry, `${label} ${index}`);
    if (normalized >= limit) throw new TypeError(`${label} ${index} is out of range`);
    if (seen.has(normalized)) throw new TypeError(`${label} contains duplicate index ${normalized}`);
    seen.add(normalized);
    return normalized;
  }));
}

function normalizeLiterals(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract literals must be an array');
  return Object.freeze(value.map((entry) => canonicalizeValue(entry)));
}

function normalizeSendSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract sendSites must be an array');
  return Object.freeze(value.map((site, index) => {
    exactKeys(site, ['languageId', 'message', 'arity'], `WASM send site ${index}`);
    if (typeof site.languageId !== 'string' || site.languageId.length === 0) {
      throw new TypeError(`WASM send site ${index} languageId must be a non-empty string`);
    }
    const message = canonicalizeValue(site.message);
    if (isReference(message)) throw new TypeError(`WASM send site ${index} message must not hide a graph reference`);
    return Object.freeze({
      languageId: site.languageId,
      message,
      arity: requireNonNegativeInteger(site.arity, `WASM send site ${index} arity`),
    });
  }));
}

function normalizeClosureSites(value) {
  if (!Array.isArray(value)) throw new TypeError('WASM module contract closureSites must be an array');
  return Object.freeze(value.map((site, siteIndex) => {
    exactKeys(site, ['blockId', 'captures'], `WASM closure site ${siteIndex}`);
    if (typeof site.blockId !== 'string' || site.blockId.length === 0) {
      throw new TypeError(`WASM closure site ${siteIndex} blockId must be non-empty text`);
    }
    if (!Array.isArray(site.captures)) throw new TypeError(`WASM closure site ${siteIndex} captures must be an array`);
    const captures = Object.freeze(site.captures.map((capture, captureIndex) => {
      exactKeys(capture, ['id', 'name'], `WASM closure site ${siteIndex} capture ${captureIndex}`);
      if (typeof capture.id !== 'string' || capture.id.length === 0) throw new TypeError(`WASM closure capture ${captureIndex} id must be non-empty text`);
      if (typeof capture.name !== 'string' || capture.name.length === 0) throw new TypeError(`WASM closure capture ${captureIndex} name must be non-empty text`);
      return Object.freeze({id: capture.id, name: capture.name});
    }));
    return Object.freeze({blockId: site.blockId, captures});
  }));
}

function normalizeEffectSites(value, sendSites, closureSites) {
  if (!Array.isArray(value)) throw new TypeError('resumable WASM module contract effectSites must be an array');
  const seen = new Set();
  return Object.freeze(value.map((effect, effectIndex) => {
    exactKeys(
      effect,
      ['kind', 'siteIndex', 'requestArity', 'savedCount', 'resumeEntry'],
      `resumable WASM effect site ${effectIndex}`,
    );
    if (!['send', 'closure'].includes(effect.kind)) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} kind must be send or closure`);
    }
    const siteIndex = requireNonNegativeInteger(effect.siteIndex, `resumable WASM effect site ${effectIndex} siteIndex`);
    const key = `${effect.kind}:${siteIndex}`;
    if (seen.has(key)) throw new TypeError(`duplicate resumable WASM effect site: ${key}`);
    seen.add(key);

    const site = effect.kind === 'send' ? sendSites[siteIndex] : closureSites[siteIndex];
    if (!site) throw new TypeError(`resumable WASM effect site ${effectIndex} references a missing ${effect.kind} site`);
    const expectedRequestArity = effect.kind === 'send' ? 1 + site.arity : site.captures.length;
    const requestArity = requireNonNegativeInteger(effect.requestArity, `resumable WASM effect site ${effectIndex} requestArity`);
    if (requestArity !== expectedRequestArity) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} request arity does not match its ${effect.kind} site`);
    }
    const savedCount = requireNonNegativeInteger(effect.savedCount, `resumable WASM effect site ${effectIndex} savedCount`);
    const resumeEntry = effect.resumeEntry;
    if (resumeEntry !== null && (typeof resumeEntry !== 'string' || resumeEntry.length === 0)) {
      throw new TypeError(`resumable WASM effect site ${effectIndex} resumeEntry must be non-empty text or null`);
    }
    if (resumeEntry === null && savedCount !== 0) {
      throw new TypeError(`tail resumable WASM effect site ${effectIndex} must not save continuation handles`);
    }
    return Object.freeze({
      kind: effect.kind,
      siteIndex,
      requestArity,
      savedCount,
      resumeEntry,
    });
  }));
}

function normalizeModuleFunctions(value, sendSites, closureSites) {
  if (!Array.isArray(value) || value.length === 0) {
    throw new TypeError('resumable WASM module contract functions must be a non-empty array');
  }
  const entries = new Set();
  const memberIndices = new Set();
  return Object.freeze(value.map((descriptor, index) => {
    exactKeys(
      descriptor,
      ['entry', 'memberIndex', 'parameters', 'captures', 'sendSiteIndices', 'closureSiteIndices'],
      `WASM module function ${index}`,
    );
    if (typeof descriptor.entry !== 'string' || descriptor.entry.length === 0) throw new TypeError(`WASM module function ${index} entry must be non-empty text`);
    if (entries.has(descriptor.entry)) throw new TypeError(`duplicate WASM module function entry: ${descriptor.entry}`);
    entries.add(descriptor.entry);
    const memberIndex = requireNonNegativeInteger(descriptor.memberIndex, `WASM module function ${index} memberIndex`);
    if (memberIndices.has(memberIndex)) throw new TypeError(`duplicate WASM module function memberIndex: ${memberIndex}`);
    memberIndices.add(memberIndex);
    return Object.freeze({
      entry: descriptor.entry,
      memberIndex,
      parameters: requireNonNegativeInteger(descriptor.parameters, `WASM module function ${index} parameters`),
      captures: normalizeCaptures(descriptor.captures, `WASM module function ${index} captures`),
      sendSiteIndices: normalizeIndexList(descriptor.sendSiteIndices, sendSites.length, `WASM module function ${index} sendSiteIndices`),
      closureSiteIndices: normalizeIndexList(descriptor.closureSiteIndices, closureSites.length, `WASM module function ${index} closureSiteIndices`),
    });
  }));
}




function recordPending(pending, effect) {
  if (pending.effect !== null) throw new TypeError('WASM activation attempted more than one pending host effect');
  pending.effect = Object.freeze(effect);
  return 0;
}

function effectMaps(effectSites) {
  const sends = new Map();
  const closures = new Map();
  effectSites.forEach((effect, effectIndex) => {
    const target = effect.kind === 'send' ? sends : closures;
    target.set(effect.siteIndex, Object.freeze({...effect, effectIndex}));
  });
  return {sends, closures};
}

function createRebindableHostEnvironment(literals, sendSites, closureSites, effectSites) {
  const holder = {current: null};
  const maps = effectMaps(effectSites);
  const current = () => {
    if (!holder.current) throw new TypeError('WASM instance host environment is not bound to an activation');
    return holder.current;
  };
  const lagrange = {
    literal(index) {
      const state = current();
      if (!Number.isInteger(index) || index < 0 || index >= literals.length) throw new TypeError(`WASM literal index out of range: ${index}`);
      return state.arena.put(literals[index]);
    },
    integer_add(left, right) {
      return current().arena.integerAdd(left, right);
    },
    equals(left, right) {
      return current().arena.equals(left, right);
    },
    is_true(handle) {
      return current().arena.isTrue(handle);
    },
  };

  sendSites.forEach((site, siteIndex) => {
    const effect = maps.sends.get(siteIndex);
    if (!effect) throw new TypeError(`resumable WASM send site ${siteIndex} has no effect descriptor`);
    lagrange[`send_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeSendSites.has(siteIndex)) throw new TypeError(`inactive WASM send site invoked: ${siteIndex}`);
      const expected = effect.requestArity + effect.savedCount;
      if (handles.length !== expected) {
        throw new TypeError(`resumable WASM send site ${siteIndex} expected ${expected} handles, received ${handles.length}`);
      }
      const requestHandles = handles.slice(0, effect.requestArity);
      const savedHandles = Object.freeze(handles.slice(effect.requestArity));
      return recordPending(state.pending, {
        kind: 'send',
        siteIndex,
        request: Object.freeze({
          languageId: site.languageId,
          receiver: state.arena.get(requestHandles[0], `WASM send site ${siteIndex} receiver handle`),
          message: site.message,
          arguments: Object.freeze(requestHandles.slice(1).map((handle, argumentIndex) =>
            state.arena.get(handle, `WASM send site ${siteIndex} argument ${argumentIndex} handle`))),
        }),
        resume: effect.resumeEntry === null
          ? null
          : Object.freeze({entry: effect.resumeEntry, handles: savedHandles}),
      });
    };
  });

  closureSites.forEach((site, siteIndex) => {
    const effect = maps.closures.get(siteIndex);
    if (!effect) throw new TypeError(`resumable WASM closure site ${siteIndex} has no effect descriptor`);
    lagrange[`make_block_site_${siteIndex}`] = (...handles) => {
      const state = current();
      if (!state.activeClosureSites.has(siteIndex)) throw new TypeError(`inactive WASM closure site invoked: ${siteIndex}`);
      const expected = effect.requestArity + effect.savedCount;
      if (handles.length !== expected) {
        throw new TypeError(`resumable WASM closure site ${siteIndex} expected ${expected} handles, received ${handles.length}`);
      }
      const requestHandles = handles.slice(0, effect.requestArity);
      const savedHandles = Object.freeze(handles.slice(effect.requestArity));
      const prototype = state.closurePrototypes.get(siteIndex);
      if (!prototype) throw new TypeError(`WASM closure prototype missing at execution: ${site.blockId}`);
      return recordPending(state.pending, {
        kind: 'closure',
        siteIndex,
        request: Object.freeze({
          prototype,
          captures: Object.freeze(site.captures.map((capture, captureIndex) => Object.freeze({
            id: capture.id,
            name: capture.name,
            value: state.arena.get(requestHandles[captureIndex], `WASM closure site ${siteIndex} capture ${captureIndex} handle`),
          }))),
        }),
        resume: effect.resumeEntry === null
          ? null
          : Object.freeze({entry: effect.resumeEntry, handles: savedHandles}),
      });
    };
  });

  return Object.freeze({
    imports: {[WASM_IMPORT_MODULE]: lagrange},
    bind({arena, descriptor, closurePrototypes, pending}) {
      if (holder.current) throw new TypeError('WASM instance host environment is already bound');
      holder.current = {
        arena,
        closurePrototypes,
        pending,
        activeSendSites: new Set(descriptor.sendSiteIndices),
        activeClosureSites: new Set(descriptor.closureSiteIndices),
      };
    },
    unbind() {
      if (!holder.current) throw new TypeError('WASM instance host environment is not bound');
      holder.current = null;
    },
  });
}

function instanceReuseMode(moduleArtifact) {
  const mode = moduleArtifact.metadata?.instanceReuse;
  if (mode === undefined) return null;
  if (mode !== WASM_INSTANCE_REUSE_STATELESS_V0) throw new TypeError(`unsupported WASM instance reuse contract: ${mode}`);
  return mode;
}

async function createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites) {
  const host = createRebindableHostEnvironment(literals, sendSites, closureSites, effectSites);
  const instance = await WebAssembly.instantiate(compiledModule, host.imports);
  return Object.freeze({instance, host});
}

async function acquireInstance({
  moduleArtifact,
  compiledModule,
  instancePool,
  literals,
  sendSites,
  closureSites,
  effectSites,
}) {
  if (instanceReuseMode(moduleArtifact) === WASM_INSTANCE_REUSE_STATELESS_V0) {
    return await instancePool.acquire(
      moduleArtifact,
      async () => await createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites),
    );
  }
  const slot = await createInstanceSlot(compiledModule, literals, sendSites, closureSites, effectSites);
  let released = false;
  return Object.freeze({
    slot,
    release() {
      if (released) throw new TypeError('WASM one-shot instance lease already released');
      released = true;
    },
  });
}

async function performHostEffect(effect, context) {
  if (effect.kind === 'send') {
    if (typeof context.sendMessage !== 'function') throw new TypeError('WASM message send requires a message runtime');
    return canonicalizeValue(await context.sendMessage(effect.request));
  }
  if (effect.kind === 'closure') {
    if (typeof context.createClosure !== 'function') throw new TypeError('WASM closure creation requires a closure runtime');
    return canonicalizeValue(await context.createClosure(effect.request));
  }
  throw new TypeError(`unknown WASM host effect kind: ${effect.kind}`);
}

function createResumableWasmFunctionV1Executor({
  moduleCache = new WasmModuleCache(),
  instancePool = new WasmInstancePool(),
} = {}) {
  if (!moduleCache || typeof moduleCache.get !== 'function' || typeof moduleCache.stats !== 'function') {
    throw new TypeError('moduleCache must be a WasmModuleCache-compatible object');
  }
  if (!instancePool || typeof instancePool.acquire !== 'function' || typeof instancePool.stats !== 'function') {
    throw new TypeError('instancePool must be a WasmInstancePool-compatible object');
  }

  return Object.freeze({
    moduleCache,
    instancePool,
    async execute({activation, code}, context, resolved = null) {
      if (!resolved) assertWasmFunctionArtifactAnyVersion(code);
      const moduleRef = functionModuleRef(code);
      const moduleArtifact = resolved?.moduleArtifact ?? await context.images.getCodeArtifact(moduleRef.imageId, moduleRef.objectId);
      if (!moduleArtifact) throw new TypeError(`WASM module not found: ${moduleRef.imageId}/${moduleRef.objectId}`);
      const contract = readModuleDescriptor(moduleArtifact);
      const resolveImplementation = (ref) => context.images.getCodeArtifact(ref.imageId, ref.objectId);
      if (contract.abi !== WASM_RESUMABLE_VALUE_HANDLE_ABI_V1) {
        throw new TypeError(`WASM module ABI does not match ${WASM_RESUMABLE_VALUE_HANDLE_ABI_V1}`);
      }
      const literals = normalizeLiterals(contract.literals);
      const sendSites = normalizeSendSites(contract.sendSites);
      const closureSites = normalizeClosureSites(contract.closureSites);
      const effectSites = normalizeEffectSites(contract.effectSites, sendSites, closureSites);
      const fn = resolveFunctionContract(
        code,
        Object.freeze({...contract, functions: normalizeModuleFunctions(contract.functions, sendSites, closureSites), closureSites}),
        resolved?.selection ? {selection: resolved.selection} : {},
      );
      const {descriptor, closurePrototypes} = fn;
      const parameterCount = descriptor.parameters;
      const captureIds = descriptor.captures;
      if (activation.arguments.length !== parameterCount) {
        throw new TypeError(`WASM activation expected ${parameterCount} arguments, received ${activation.arguments.length}`);
      }
      const compiledModule = await moduleCache.get(moduleArtifact, () => readModuleImplementationBytes(moduleArtifact, {resolveImplementation}));

      const arena = new ValueHandleArena({receiverAbsent: activation.receiver === null});
      const receiverHandle = activation.receiver === null ? 0 : arena.put(activation.receiver);
      const argumentHandles = activation.arguments.map((value) => arena.put(value));
      const captureHandles = [];
      for (const bindingId of captureIds) captureHandles.push(arena.put(await context.lookupBinding(bindingId)));
      const pending = {effect: null};

      const lease = await acquireInstance({
        moduleArtifact,
        compiledModule,
        instancePool,
        literals,
        sendSites,
        closureSites,
        effectSites,
      });
      let bound = false;
      let released = false;
      let result = null;
      let tailEffect = null;
      let currentEntry = fn.entry;
      let currentHandles = [receiverHandle, ...argumentHandles, ...captureHandles];
      let resumptions = 0;

      context.recordWasmState?.({
        wasmState: 'running',
        suspensionCount: 0,
        resumedCount: 0,
        lastSuspension: null,
      });

      try {
        while (true) {
          context.checkCancelled?.();
          pending.effect = null;
          lease.slot.host.bind({arena, descriptor, closurePrototypes, pending});
          bound = true;
          const entry = lease.slot.instance.exports[currentEntry];
          if (typeof entry !== 'function') throw new TypeError(`WASM function/resume entry not found: ${currentEntry}`);
          const resultHandle = entry(...currentHandles);

          const effect = pending.effect;
          lease.slot.host.unbind();
          bound = false;

          if (effect === null) {
            result = arena.get(resultHandle, 'WASM result handle');
            break;
          }
          if (resultHandle !== 0) throw new TypeError('WASM host effect suspension must return reserved handle 0');

          if (effect.resume === null) {
            tailEffect = effect;
            break;
          }
          resumptions += 1;
          if (resumptions > MAX_WASM_RESUMPTIONS) throw new TypeError('WASM resumable effect limit exceeded');

          const suspensionMeta = Object.freeze({
            abi: contract.abi,
            entry: fn.entry,
            currentEntry,
            effectKind: effect.kind,
            siteIndex: effect.siteIndex ?? null,
            resumeEntry: effect.resume.entry,
            savedHandleCount: effect.resume.handles.length,
            step: resumptions,
          });
          context.recordWasmState?.({
            wasmState: 'suspended',
            suspensionCount: resumptions,
            resumedCount: resumptions - 1,
            lastSuspension: suspensionMeta,
            event: 'suspend',
          });

          const resumedValue = await performHostEffect(effect, context);
          context.checkCancelled?.();
          context.recordWasmState?.({
            wasmState: 'running',
            suspensionCount: resumptions,
            resumedCount: resumptions,
            lastSuspension: suspensionMeta,
            event: 'resume',
          });
          const resultValueHandle = arena.put(resumedValue);
          currentEntry = effect.resume.entry;
          currentHandles = [...effect.resume.handles, resultValueHandle];
        }

        context.recordWasmState?.({wasmState: 'completed'});
        lease.release();
        released = true;
      } catch (error) {
        try {
          context.recordWasmState?.({wasmState: 'retired', event: 'retire'});
        } catch {}
        if (bound) {
          try { lease.slot.host.unbind(); } catch {}
          bound = false;
        }
        if (!released) {
          try { lease.release({retire: true}); } catch {}
          released = true;
        }
        throw error;
      }

      if (tailEffect !== null) return await performHostEffect(tailEffect, context);
      return canonicalizeValue(result);
    },
  });
}

export {
  MAX_WASM_RESUMPTIONS,
  createResumableWasmFunctionV1Executor,
};

import {ensureBlock, ensureCodeArtifact} from '../graph/ensure-records.js';
import {uuid as randomUUID} from '../support/default-crypto.js';
import {base64urlEncode, utf8Encode} from '../support/portable-bytes.js';
import {
  LAGRANGE_CODE_V1,
  LAGRANGE_CODE_V2,
  normalizeLagrangeCodeV1Program,
  normalizeLagrangeCodeV2Program,
  parseLagrangeCodeV1Program,
  parseLagrangeCodeV2Program,
} from '../code/lagrange-code-v1.js';
import {bindClosurePrototypes, describeWasmFunctionV2} from './function-contract.js';
import {WASM_MODULE_V2, moduleFunctionOf, readModuleDescriptor} from './module-contract.js';
import {createCompilationGroup} from '../compilation/group.js';
import {normalizeMetadata} from '../object/model.js';
import {canonicalizeValue, isObjectRef, objectRef, textValue} from '../value/index.js';
import {WASM_VALUE_HANDLE_ABI_V1} from './abi.js';
import {
  WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1,
  compileWasmV1ModuleEntries,
  isWasmV1TailEffectRestrictionError,
} from './compiler-v1.js';
import {WASM_RESUMABLE_VALUE_HANDLE_ABI_V2} from './resumable-abi.js';
import {compileResumableWasmV2ModuleEntries} from './resumable-compiler-v2.js';
import {
  optimizeNonEscapingClosures,
  partitionCompilationGroupByBudget,
} from './group-optimizations.js';

// The lagrange-code/v1 Block-tree installer. A sibling of the v0 installer rather than a
// generalization of it: that one hardcodes v0 normalization, v0 semantic persistence and v0
// preflight throughout, and making it generic while the v1 path is still unproven would add risk
// without adding meaning. Shared plumbing can be extracted later if it turns out to be worth it.
//
// There is deliberately no "does this program need mutable state?" analysis here. That decision was
// made when the semantic artifact was created; the representation is now the source of truth.
const SUPPORTED_MODULE_ABIS = Object.freeze([WASM_VALUE_HANDLE_ABI_V1, WASM_RESUMABLE_VALUE_HANDLE_ABI_V2]);

function requiredText(value, label) {
  if (typeof value !== 'string' || value.length === 0) throw new TypeError(`${label} must be non-empty text`);
  return value;
}

function normalizeObjectRef(value, label) {
  const ref = canonicalizeValue(value);
  if (!isObjectRef(ref)) throw new TypeError(`${label} must be an unpinned object ref`);
  return ref;
}

function assertServices(images, compilation) {
  if (!images || typeof images !== 'object') throw new TypeError('images service is required');
  for (const method of ['getCodeArtifact', 'putCodeArtifact', 'getBlock', 'putBlock']) {
    if (typeof images[method] !== 'function') throw new TypeError(`images service must implement ${method}`);
  }
  if (!compilation || typeof compilation.compileGroup !== 'function') {
    throw new TypeError('compilation service with compileGroup is required');
  }
}

// v1 bodies reach nested Blocks through statement sequences and assignment right-hand sides as
// well as the v0 positions, so omitting those would silently install no prototype for them.
function directNestedBlocks(expression, result = []) {
  if (!expression || typeof expression !== 'object' || Array.isArray(expression)) return result;
  switch (expression.op) {
    case 'block':
      result.push(expression);
      return result;
    case 'binding-write':
      return directNestedBlocks(expression.value, result);
    case 'sequence':
      for (const statement of expression.statements) directNestedBlocks(statement, result);
      return result;
    case 'send':
      directNestedBlocks(expression.receiver, result);
      for (const argument of expression.arguments ?? []) directNestedBlocks(argument, result);
      return result;
    case 'apply':
      directNestedBlocks(expression.callee, result);
      for (const argument of expression.arguments ?? []) directNestedBlocks(argument, result);
      return result;
    case 'integer-add':
    case 'equals':
      directNestedBlocks(expression.left, result);
      directNestedBlocks(expression.right, result);
      return result;
    case 'if':
      directNestedBlocks(expression.condition, result);
      directNestedBlocks(expression.then, result);
      directNestedBlocks(expression.else, result);
      return result;
    default:
      return result;
  }
}

function blockKey(blockId) {
  return base64urlEncode(utf8Encode(requiredText(blockId, 'semantic block id')));
}

// Preflight both backends before anything is written: the simple one where legal, the resumable one
// where a non-tail effect makes it necessary.
function preflightEntries(entries, options = {}) {
  try {
    return {compiled: compileWasmV1ModuleEntries(entries, options), abi: WASM_VALUE_HANDLE_ABI_V1};
  } catch (error) {
    if (!isWasmV1TailEffectRestrictionError(error)) throw error;
    return {compiled: compileResumableWasmV2ModuleEntries(entries, options), abi: WASM_RESUMABLE_VALUE_HANDLE_ABI_V2};
  }
}

function validateTree(program, seen = new Set(), {representation = LAGRANGE_CODE_V1} = {}) {
  const normalized = representation === LAGRANGE_CODE_V2
    ? normalizeLagrangeCodeV2Program(program)
    : normalizeLagrangeCodeV1Program(program);
  for (const nested of directNestedBlocks(normalized.body)) {
    const blockId = requiredText(nested.blockId, 'nested semantic block id');
    if (seen.has(blockId)) throw new TypeError(`duplicate semantic block id in WASM tree: ${blockId}`);
    seen.add(blockId);
    validateTree(nested.program, seen, {representation});
  }
  return normalized;
}

function nodeIds(rootId, semanticBlockId = null) {
  if (semanticBlockId === null) {
    return Object.freeze({
      moduleId: `${rootId}:wasm:module`,
      functionId: `${rootId}:wasm:function`,
      blockId: rootId,
      semanticId: null,
    });
  }
  const key = blockKey(semanticBlockId);
  return Object.freeze({
    semanticId: `${rootId}:wasm:semantic:${key}`,
    moduleId: `${rootId}:wasm:module`,
    functionId: `${rootId}:wasm:function:${key}`,
    blockId: `${rootId}:wasm:prototype:${key}`,
  });
}

function planTree(program, rootId, semanticBlockId = null, {representation = LAGRANGE_CODE_V1} = {}) {
  const plan = {
    semanticBlockId,
    program: representation === LAGRANGE_CODE_V2
      ? normalizeLagrangeCodeV2Program(program)
      : normalizeLagrangeCodeV1Program(program),
    ids: nodeIds(rootId, semanticBlockId),
    children: [],
  };
  for (const nested of directNestedBlocks(plan.program.body)) {
    plan.children.push(planTree(nested.program, rootId, nested.blockId, {representation}));
  }
  return plan;
}

function flattenPlans(root) {
  const all = [];
  const visit = (plan) => {
    all.push(plan);
    for (const child of plan.children) visit(child);
  };
  visit(root);
  return [
    root,
    ...all.filter((plan) => plan !== root).sort((left, right) =>
      String(left.semanticBlockId).localeCompare(String(right.semanticBlockId))),
  ];
}

async function persistSemanticTree({images, rootRef, rootArtifact, rootPlan, rootId}) {
  rootPlan.semanticRef = rootRef;
  rootPlan.semanticArtifact = rootArtifact;

  const persistChildren = async (parentPlan) => {
    for (const child of parentPlan.children) {
      const childArtifact = await ensureCodeArtifact(images, parentPlan.semanticRef.imageId, {
        id: child.ids.semanticId,
        languageId: parentPlan.semanticArtifact.languageId,
        representation: rootArtifact.representation,
        content: textValue(JSON.stringify(child.program)),
        derivedFrom: [parentPlan.semanticRef],
        metadata: {semanticBlockId: child.semanticBlockId, wasmTreeRootId: rootId},
      });
      child.semanticArtifact = childArtifact;
      child.semanticRef = objectRef(childArtifact.imageId, childArtifact.id);
      await persistChildren(child);
    }
  };

  await persistChildren(rootPlan);
}

function normalizePrototypeMap(blockPrototypes) {
  if (!blockPrototypes || typeof blockPrototypes !== 'object' || Array.isArray(blockPrototypes)) {
    throw new TypeError('blockPrototypes must be an object keyed by semantic block id');
  }
  const result = new Map();
  for (const [blockId, ref] of Object.entries(blockPrototypes)) {
    requiredText(blockId, 'block prototype id');
    result.set(blockId, normalizeObjectRef(ref, `block prototype ${blockId}`));
  }
  return result;
}

// The v1-lane assembly seam. Separate from assembleWasmFunctionArtifact(), which requires
// lagrange-code/v0; the SUPPORTED_MODULE_ABIS gate is what keeps a v0-ABI module out of this lane.
async function assembleWasmV1FunctionArtifact({
  images,
  semanticRef,
  moduleRef,
  functionId,
  entry,
  blockPrototypes = {},
} = {}) {
  const semantic = await images.getCodeArtifact(semanticRef.imageId, semanticRef.objectId);
  if (!semantic || (semantic.representation !== LAGRANGE_CODE_V1 && semantic.representation !== LAGRANGE_CODE_V2)) {
    throw new TypeError(`semanticRef must reference ${LAGRANGE_CODE_V1}`);
  }
  const normalizedModuleRef = normalizeObjectRef(moduleRef, 'moduleRef');
  const moduleArtifact = await images.getCodeArtifact(normalizedModuleRef.imageId, normalizedModuleRef.objectId);
  if (!moduleArtifact) throw new TypeError('moduleRef must reference a WASM module artifact');
  const moduleDescriptor = readModuleDescriptor(moduleArtifact);
  const abi = moduleDescriptor.abi;
  if (!SUPPORTED_MODULE_ABIS.includes(abi)) {
    throw new TypeError(`WASM v1 function assembly requires ${SUPPORTED_MODULE_ABIS.join(' or ')}, got ${abi}`);
  }

  const descriptor = moduleFunctionOf(moduleDescriptor, {entry: requiredText(entry, 'WASM function entry')});
  const {closurePrototypes, prototypeRefs} = bindClosurePrototypes({
    descriptor,
    closureSites: moduleDescriptor.closureSites,
    prototypes: normalizePrototypeMap(blockPrototypes),
  });
  for (const ref of prototypeRefs) {
    if (!await images.getBlock(ref.imageId, ref.objectId)) {
      throw new TypeError(`WASM Block prototype not found: ${ref.imageId}/${ref.objectId}`);
    }
  }

  // The v2 function carries only its selection; abi/parameters/captures/cellBindings are the
  // module's function-table entry, resolved at execution through the module accessor.
  const functionArtifact = await ensureCodeArtifact(images, semanticRef.imageId, describeWasmFunctionV2({
    functionId,
    languageId: semantic.languageId,
    semanticRef,
    moduleRef: normalizedModuleRef,
    entry: descriptor.entry,
    closurePrototypes,
    prototypeRefs,
  }));
  return Object.freeze({moduleArtifact, functionArtifact});
}

async function installExecutableTree({
  images,
  moduleArtifact,
  shardPlacement = null,
  groupPlans,
  rootPlan,
  rootId,
  rootEnvironment,
  rootMetadata,
}) {
  const memberIndex = new Map(groupPlans.map((plan, index) => [plan, index]));
  const nodes = [];

  const install = async (plan) => {
    const blockPrototypes = {};
    for (const childPlan of plan.children) {
      const child = await install(childPlan);
      blockPrototypes[childPlan.semanticBlockId] = objectRef(child.block.imageId, child.block.id);
    }

    const placement = shardPlacement?.get(plan) ?? {
      moduleArtifact,
      shardMemberIndex: memberIndex.get(plan),
    };
    const planModuleArtifact = placement.moduleArtifact;
    const moduleRef = objectRef(planModuleArtifact.imageId, planModuleArtifact.id);
    const moduleDescriptor = readModuleDescriptor(planModuleArtifact);
    const descriptor = moduleFunctionOf(moduleDescriptor, {memberIndex: placement.shardMemberIndex});
    const activeClosureBlockIds = new Set(
      descriptor.closureSiteIndices.map((siteIdx) => moduleDescriptor.closureSites[siteIdx]?.blockId),
    );
    const activeBlockPrototypes = Object.fromEntries(
      Object.entries(blockPrototypes).filter(([blockId]) => activeClosureBlockIds.has(blockId)),
    );

    const {functionArtifact} = await assembleWasmV1FunctionArtifact({
      images,
      semanticRef: plan.semanticRef,
      moduleRef,
      functionId: plan.ids.functionId,
      entry: descriptor.entry,
      blockPrototypes: activeBlockPrototypes,
    });
    const isRoot = plan === rootPlan;
    const block = await ensureBlock(images, plan.semanticRef.imageId, {
      id: plan.ids.blockId,
      code: objectRef(functionArtifact.imageId, functionArtifact.id),
      environment: isRoot ? rootEnvironment : null,
      metadata: isRoot
        ? rootMetadata
        : {prototype: true, semanticBlockId: plan.semanticBlockId, wasmTreeRootId: rootId},
    });
    const node = Object.freeze({
      semanticBlockId: plan.semanticBlockId,
      semanticArtifact: plan.semanticArtifact,
      moduleArtifact: planModuleArtifact,
      functionArtifact,
      block,
      blockPrototypes: Object.freeze({...activeBlockPrototypes}),
    });
    nodes.push(node);
    return node;
  };

  const root = await install(rootPlan);
  return Object.freeze({root, nodes: Object.freeze(nodes)});
}

async function installWasmV1BlockTree({
  images,
  compilation,
  semanticRef,
  id = randomUUID(),
  environment = null,
  metadata = {},
  optimizeClosures = false,
  intraModuleDirectCalls = false,
  moduleBudget = null,
} = {}) {
  assertServices(images, compilation);
  requiredText(id, 'WASM Block tree id');
  const rootEnvironment = environment === null ? null : normalizeObjectRef(environment, 'root WASM Block environment');
  const rootMetadata = normalizeMetadata(metadata, 'WASM Block tree metadata');
  const rootRef = normalizeObjectRef(semanticRef, 'root semantic code artifact');
  const semanticArtifact = await images.getCodeArtifact(rootRef.imageId, rootRef.objectId);
  if (!semanticArtifact || (semanticArtifact.representation !== LAGRANGE_CODE_V1 && semanticArtifact.representation !== LAGRANGE_CODE_V2)) {
    throw new TypeError(`root semantic code artifact must be ${LAGRANGE_CODE_V1}`);
  }

  const representation = semanticArtifact.representation;
  const isV2 = representation === LAGRANGE_CODE_V2;
  const parsed = isV2
    ? parseLagrangeCodeV2Program(semanticArtifact)
    : parseLagrangeCodeV1Program(semanticArtifact);
  const rawProgram = validateTree(parsed, new Set(), {representation});
  const closureOptimization = optimizeClosures
    ? optimizeNonEscapingClosures(rawProgram)
    : {program: rawProgram, inlinedBlockIds: [], eliminatedClosureSites: 0, eliminatedApplySites: 0};
  const program = validateTree(closureOptimization.program, new Set(), {representation});
  const rootPlan = planTree(program, id, null, {representation});
  const groupPlans = flattenPlans(rootPlan);
  // Preflight before any write, so a program neither backend accepts installs nothing.
  preflightEntries(
    groupPlans.map((plan, memberIndex) => ({
      entry: `run_${memberIndex}`,
      memberIndex,
      program: plan.program,
      allowApply: isV2,
      semanticBlockId: plan.semanticBlockId,
    })),
    {intraModuleDirectCalls: Boolean(intraModuleDirectCalls)},
  );

  let effectiveRootRef = rootRef;
  let effectiveRootArtifact = semanticArtifact;
  if (closureOptimization.inlinedBlockIds.length > 0) {
    effectiveRootArtifact = await ensureCodeArtifact(images, rootRef.imageId, {
      id: `${id}:wasm:semantic:root`,
      languageId: semanticArtifact.languageId,
      representation,
      content: textValue(JSON.stringify(program)),
      derivedFrom: [rootRef],
      metadata: {wasmTreeRootId: id, inlinedBlockIds: closureOptimization.inlinedBlockIds},
    });
    effectiveRootRef = objectRef(effectiveRootArtifact.imageId, effectiveRootArtifact.id);
  }
  await persistSemanticTree({
    images,
    rootRef: effectiveRootRef,
    rootArtifact: effectiveRootArtifact,
    rootPlan,
    rootId: id,
  });

  if (moduleBudget && typeof moduleBudget === 'object') {
    const planEntries = groupPlans.map((plan, memberIndex) => ({
      entry: `run_${memberIndex}`,
      memberIndex,
      program: plan.program,
      allowApply: isV2,
      semanticBlockId: plan.semanticBlockId,
      plan,
    }));
    const split = partitionCompilationGroupByBudget({
      entries: planEntries,
      maxMembersPerModule: moduleBudget.maxMembersPerModule ?? Infinity,
      maxByteBudget: moduleBudget.maxByteBudget ?? Infinity,
      strictSingleMemberBudget: moduleBudget.strictSingleMemberBudget === true,
      compileEntries: (shardEntries) => preflightEntries(
        shardEntries.map((e, idx) => ({
          entry: `run_${idx}`,
          memberIndex: idx,
          program: e.program,
          allowApply: e.allowApply,
          semanticBlockId: e.semanticBlockId,
        })),
        {intraModuleDirectCalls: Boolean(intraModuleDirectCalls)},
      ).compiled,
    });
    const shardPlacement = new Map();
    const moduleArtifacts = [];
    const groups = [];
    const shardSummaries = [];

    for (const shard of split.shards) {
      const shardModuleId = shard.shardIndex === 0
        ? nodeIds(id).moduleId
        : `${nodeIds(id).moduleId}:shard:${shard.shardIndex}`;
      const shardGroup = createCompilationGroup({
        policyId: WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1,
        targetRepresentation: WASM_MODULE_V2,
        members: shard.entries.map((e) => e.plan.semanticRef),
        options: {
          physicalLayout: 'shared-module',
          ...(intraModuleDirectCalls ? {intraModuleDirectCalls: true} : {}),
        },
      });
      const shardModuleArtifact = await compilation.compileGroup(shardGroup, {id: shardModuleId});
      moduleArtifacts.push(shardModuleArtifact);
      groups.push(shardGroup);
      shard.entries.forEach((e, shardMemberIndex) => {
        shardPlacement.set(e.plan, {moduleArtifact: shardModuleArtifact, shardMemberIndex});
      });
      shardSummaries.push(Object.freeze({
        shardIndex: shard.shardIndex,
        moduleId: shardModuleArtifact.id,
        memberIndices: shard.memberIndices,
        byteLength: shard.byteLength,
      }));
    }

    const installed = await installExecutableTree({
      images,
      moduleArtifact: moduleArtifacts[0],
      shardPlacement,
      groupPlans,
      rootPlan,
      rootId: id,
      rootEnvironment,
      rootMetadata,
    });

    return Object.freeze({
      ...installed.root,
      nodes: installed.nodes,
      group: groups[0],
      groups: Object.freeze(groups),
      moduleArtifacts: Object.freeze(moduleArtifacts),
      budgetSplit: Object.freeze({
        shardCount: split.shardCount,
        maxMembersPerModule: split.maxMembersPerModule,
        maxByteBudget: split.maxByteBudget,
        shards: Object.freeze(shardSummaries),
      }),
      closureOptimization: Object.freeze({
        inlinedBlockIds: closureOptimization.inlinedBlockIds,
        eliminatedClosureSites: closureOptimization.eliminatedClosureSites,
        eliminatedApplySites: closureOptimization.eliminatedApplySites,
      }),
    });
  }

  const group = createCompilationGroup({
    policyId: WASM_NESTED_BLOCK_TREE_GROUP_POLICY_V1,
    targetRepresentation: WASM_MODULE_V2,
    members: groupPlans.map((plan) => plan.semanticRef),
    options: {
      physicalLayout: 'shared-module',
      ...(intraModuleDirectCalls ? {intraModuleDirectCalls: true} : {}),
    },
  });
  const moduleArtifact = await compilation.compileGroup(group, {id: nodeIds(id).moduleId});
  const installed = await installExecutableTree({
    images,
    moduleArtifact,
    groupPlans,
    rootPlan,
    rootId: id,
    rootEnvironment,
    rootMetadata,
  });

  return Object.freeze({
    ...installed.root,
    nodes: installed.nodes,
    group,
    closureOptimization: Object.freeze({
      inlinedBlockIds: closureOptimization.inlinedBlockIds,
      eliminatedClosureSites: closureOptimization.eliminatedClosureSites,
      eliminatedApplySites: closureOptimization.eliminatedApplySites,
    }),
  });
}

